/* ── Session helpers ── */
function saveSession(user) {
  sessionStorage.setItem(SESSION_KEY, JSON.stringify({
    username:    user.username,
    displayName: user.displayName,
    role:        user.role,
    unitUsaha:   user.unitUsaha || '',
    token:       user.token    || '',
    loginTime:   Date.now(),
  }));
}
function getSession() {
  try { return JSON.parse(sessionStorage.getItem(SESSION_KEY)); } catch { return null; }
}
function clearSession() { sessionStorage.removeItem(SESSION_KEY); }
function redirectTo(path) {
  // Tambahkan cache-buster ke HTML pages agar browser tidak pakai versi lama
  if (path === 'dashboard.html' || path === 'login.html') {
    window.location.href = path + '?v=20260609v';
  } else {
    window.location.href = path;
  }
}

/* ── Formatters ── */
function formatTime(ts) {
  return new Date(ts).toLocaleString('id-ID', {
    day: '2-digit', month: 'short', year: 'numeric',
    hour: '2-digit', minute: '2-digit',
  });
}
function formatDuration(startTs) {
  const diff = Math.floor((Date.now() - startTs) / 1000);
  const h = Math.floor(diff / 3600);
  const m = Math.floor((diff % 3600) / 60);
  const s = diff % 60;
  if (h > 0) return `${h} jam ${m} menit`;
  if (m > 0) return `${m} menit ${s} detik`;
  return `${s} detik`;
}
function getInitials(name) {
  return name.split(' ').map(w => w[0]).slice(0, 2).join('').toUpperCase();
}

/* ── Page detector ── */
const isLoginPage     = document.body.classList.contains('auth-page');
const isDashboardPage = document.body.classList.contains('dashboard-page');

/* ============================================================
   LOGIN PAGE
   ============================================================ */
if (isLoginPage) {
  if (getSession()) redirectTo('dashboard.html');

  const form       = document.getElementById('loginForm');
  const userInput  = document.getElementById('username');
  const passInput  = document.getElementById('password');
  const userErr    = document.getElementById('usernameError');
  const passErr    = document.getElementById('passwordError');
  const alertBox   = document.getElementById('alertBox');
  const submitBtn  = document.getElementById('submitBtn');
  const btnText    = submitBtn.querySelector('.btn-text');
  const btnSpinner = submitBtn.querySelector('.btn-spinner');
  const toggleBtn  = document.getElementById('togglePassword');
  const rememberMe = document.getElementById('rememberMe');

  const saved = localStorage.getItem('akta_remember');
  if (saved) { userInput.value = saved; rememberMe.checked = true; }

  toggleBtn.addEventListener('click', () => {
    const isHidden = passInput.type === 'password';
    passInput.type = isHidden ? 'text' : 'password';
    toggleBtn.querySelector('.eye-open').classList.toggle('hidden', isHidden);
    toggleBtn.querySelector('.eye-closed').classList.toggle('hidden', !isHidden);
  });

  userInput.addEventListener('input', () => clearFieldError(userInput, userErr));
  passInput.addEventListener('input', () => clearFieldError(passInput, passErr));

  function clearFieldError(input, errEl) {
    input.classList.remove('invalid');
    errEl.textContent = '';
  }
  function showAlert(msg, type = 'error') {
    alertBox.textContent = msg;
    alertBox.className = `alert ${type}`;
    alertBox.classList.remove('hidden');
  }
  function setLoading(on) {
    submitBtn.disabled = on;
    btnText.classList.toggle('hidden', on);
    btnSpinner.classList.toggle('hidden', !on);
  }
  function validate() {
    let valid = true;
    if (!userInput.value.trim()) {
      userInput.classList.add('invalid');
      userErr.textContent = 'Username tidak boleh kosong.';
      valid = false;
    }
    if (!passInput.value) {
      passInput.classList.add('invalid');
      passErr.textContent = 'Password tidak boleh kosong.';
      valid = false;
    } else if (passInput.value.length < 4) {
      passInput.classList.add('invalid');
      passErr.textContent = 'Password minimal 4 karakter.';
      valid = false;
    }
    return valid;
  }
  async function attemptLogin(username, password) {
    // Utamakan autentikasi via server jika tersedia
    if (window.API) {
      try {
        await fetch('/api/ping', { signal: AbortSignal.timeout(2000) });
        const res = await window.API.login(username, password);
        // refreshToken sudah disimpan ke localStorage oleh API.login
        return { ...res.user, token: res.token };
      } catch (e) {
        // Server down / error → fallback ke local users
        const isAuthError = e.message && (e.message.includes('salah') || e.message.includes('dinonaktifkan') || e.message.includes('tidak valid'));
        if (isAuthError) throw e; // Jangan fallback jika server menolak credentials
      }
    }

    // Fallback: cek custom users di localStorage (offline mode)
    try {
      const custom = JSON.parse(localStorage.getItem('akta_custom_users')) || [];
      const localUser = custom.find(u => u.username === username && u.password === password && !u._disabled) || null;
      if (localUser) return localUser;
    } catch {}

    // Fallback: cek built-in users (offline mode)
    const builtIn = USERS.find(u => u.username === username && u.password === password);
    if (builtIn) {
      await new Promise(r => setTimeout(r, 400));
      return builtIn;
    }

    // User tidak ditemukan di mana pun
    await new Promise(r => setTimeout(r, 600));
    throw new Error('Username atau password salah.');
  }

  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    alertBox.classList.add('hidden');
    if (!validate()) return;
    const username = userInput.value.trim();
    const password = passInput.value;
    setLoading(true);
    try {
      const user = await attemptLogin(username, password);
      if (rememberMe.checked) localStorage.setItem('akta_remember', username);
      else localStorage.removeItem('akta_remember');
      saveSession(user);
      redirectTo('dashboard.html');
    } catch (err) {
      showAlert(err.message);
      passInput.value = '';
      passInput.focus();
    } finally {
      setLoading(false);
    }
  });
}

