  // ── NOTIFICATION SYSTEM ──────────────────────────────────────────

  // Inject toast container sekali
  if (!document.getElementById('notifToastContainer')) {
    const tc = document.createElement('div');
    tc.id = 'notifToastContainer';
    document.body.appendChild(tc);
  }

  let _notifUnread   = 0;
  let _notifDropOpen = false;
  let _sseSource     = null;

  function _notifRelativeTime(iso) {
    const diff = Date.now() - new Date(iso).getTime();
    if (diff < 60000)     return 'Baru saja';
    if (diff < 3600000)   return Math.floor(diff / 60000) + ' menit lalu';
    if (diff < 86400000)  return Math.floor(diff / 3600000) + ' jam lalu';
    return Math.floor(diff / 86400000) + ' hari lalu';
  }

  function _notifUpdateBadge(count) {
    _notifUnread = count;
    const badge = document.getElementById('notifBadge');
    if (!badge) return;
    if (count > 0) {
      badge.textContent = count > 99 ? '99+' : String(count);
      badge.style.display = 'flex';
    } else {
      badge.style.display = 'none';
    }
  }

  function _notifShowToast(title, message, type) {
    const container = document.getElementById('notifToastContainer');
    if (!container) return;
    const toast = document.createElement('div');
    toast.className = `notif-toast ${type || 'info'}`;
    toast.innerHTML = `
      <div>
        <div class="notif-toast-title">${title}</div>
        ${message ? `<div class="notif-toast-msg">${message}</div>` : ''}
      </div>`;
    container.appendChild(toast);
    setTimeout(() => {
      toast.style.transition = 'opacity .4s, transform .4s';
      toast.style.opacity    = '0';
      toast.style.transform  = 'translateX(30px)';
      setTimeout(() => toast.remove(), 400);
    }, 5000);
  }

  function _notifRenderItem(n) {
    const isUnread = !n.isRead && !n.is_read;
    const type     = n.type || 'info';
    const timeStr  = _notifRelativeTime(n.createdAt || n.created_at || new Date().toISOString());
    return `
      <button class="notif-item${isUnread ? ' unread' : ''}" data-id="${n.id}" onclick="window._notifMarkRead(${n.id}, this)">
        <div class="notif-dot ${isUnread ? type : 'read'}"></div>
        <div style="flex:1;min-width:0">
          <div class="notif-item-title">${n.title || '-'}</div>
          ${n.message ? `<div class="notif-item-msg">${n.message}</div>` : ''}
          <div class="notif-item-time">${timeStr}</div>
        </div>
      </button>`;
  }

  async function _notifLoadDropdown() {
    const list = document.getElementById('notifDropdownList');
    if (!list) return;
    list.innerHTML = '<div class="notif-empty" style="padding:16px;text-align:center;color:#9ca3af;font-size:.8rem">Memuat…</div>';
    try {
      const d = await _apiReq('GET', '/notifications?limit=20');
      _notifUpdateBadge(d.unread || 0);
      if (!d.data || d.data.length === 0) {
        list.innerHTML = '<div class="notif-empty">Tidak ada notifikasi</div>';
        return;
      }
      list.innerHTML = d.data.map(_notifRenderItem).join('');
    } catch {
      list.innerHTML = '<div class="notif-empty">Gagal memuat notifikasi</div>';
    }
  }

  window._toggleNotifDropdown = function (e) {
    e.stopPropagation();
    const drop = document.getElementById('notifDropdown');
    if (!drop) return;
    _notifDropOpen = !_notifDropOpen;
    drop.style.display = _notifDropOpen ? 'block' : 'none';
    if (_notifDropOpen) _notifLoadDropdown();
  };

  window._notifMarkRead = async function (id, btn) {
    try {
      await _apiReq('PUT', `/notifications/${id}/read`);
      if (btn) {
        btn.classList.remove('unread');
        const dot = btn.querySelector('.notif-dot');
        if (dot) { dot.className = 'notif-dot read'; }
      }
      _notifUpdateBadge(Math.max(0, _notifUnread - 1));
    } catch { /* ignore */ }
  };

  window._notifReadAll = async function () {
    try {
      await _apiReq('PUT', '/notifications/read-all');
      _notifUpdateBadge(0);
      const list = document.getElementById('notifDropdownList');
      if (list) {
        list.querySelectorAll('.notif-item.unread').forEach(el => {
          el.classList.remove('unread');
          const dot = el.querySelector('.notif-dot');
          if (dot) dot.className = 'notif-dot read';
        });
      }
    } catch { /* ignore */ }
  };

  // Tutup dropdown saat klik di luar
  document.addEventListener('click', (e) => {
    if (_notifDropOpen && !document.getElementById('notifBtn')?.contains(e.target)) {
      _notifDropOpen = false;
      const drop = document.getElementById('notifDropdown');
      if (drop) drop.style.display = 'none';
    }
  });

  // Mulai koneksi SSE
  function _startSSE() {
    if (_sseSource) { _sseSource.close(); _sseSource = null; }
    try {
      _sseSource = new EventSource('/api/notifications/stream');
      _sseSource.addEventListener('notification', (e) => {
        try {
          const n = JSON.parse(e.data);
          _notifUpdateBadge(_notifUnread + 1);
          _notifShowToast(n.title, n.message, n.type);
          // Jika dropdown sedang terbuka, tambah item di atas
          if (_notifDropOpen) {
            const list = document.getElementById('notifDropdownList');
            if (list) {
              const emptyEl = list.querySelector('.notif-empty');
              if (emptyEl) emptyEl.remove();
              list.insertAdjacentHTML('afterbegin', _notifRenderItem(n));
            }
          }
        } catch { /* ignore */ }
      });
      _sseSource.onerror = () => {
        // Reconnect otomatis setelah 15 detik jika koneksi putus
        if (_sseSource) { _sseSource.close(); _sseSource = null; }
        setTimeout(_startSSE, 15000);
      };
    } catch { /* SSE tidak didukung browser lama */ }
  }

  // Fetch unread count awal + mulai SSE
  _apiReq('GET', '/notifications?limit=1').then(d => _notifUpdateBadge(d.unread || 0)).catch(() => {});
  _startSSE();

  function formatRupiah(n) { return 'Rp ' + n.toLocaleString('id-ID'); }

  /* ============================================================
     MODUL PENGGUNA
     ============================================================ */
  const CUSTOM_USERS_KEY = 'akta_custom_users';

  function loadCustomUsers() {
    try { return JSON.parse(localStorage.getItem(CUSTOM_USERS_KEY)) || []; } catch { return []; }
  }
  function saveCustomUsers(list) {
    localStorage.setItem(CUSTOM_USERS_KEY, JSON.stringify(list));
    window.API?.sync(CUSTOM_USERS_KEY, list);
  }


  function getAllUsers() {
    const custom = loadCustomUsers();
    // Merge: custom overrides built-in by username
    const customMap = {};
    custom.forEach(u => { customMap[u.username] = u; });
    const base = USERS.map(u => customMap[u.username]
      ? { ...u, ...customMap[u.username] }
      : u
    );
    // Add truly new custom users (not in USERS array)
    const baseUsernames = new Set(USERS.map(u => u.username));
    custom.filter(u => !baseUsernames.has(u.username)).forEach(u => base.push(u));
    return base;
  }

  // ── User modal ──────────────────────────────────
  let _editingUsername  = null;
  let _prefillPassword  = null;  // nilai password asli saat modal dibuka (untuk deteksi perubahan)
  let _penggunaList     = [];
  let _penggunaPage    = 1;
  const _penggunaLimit = 50;

  async function renderPengguna() {
    const tbody   = document.getElementById('penggunaTableBody');
    const stat    = document.getElementById('penggunaStat');
    if (!tbody) return;

    const search  = document.getElementById('penggunaSearch')?.value.trim() || '';
    const role    = document.getElementById('penggunaRoleFilter')?.value || '';
    const showDis = document.getElementById('penggunaShowDisabled')?.checked || false;

    tbody.innerHTML = '<tr><td colspan="7" style="text-align:center;color:var(--text-secondary);padding:20px">Memuat…</td></tr>';

    let path = `/admin/users?page=${_penggunaPage}&limit=${_penggunaLimit}`;
    if (role)   path += `&role=${encodeURIComponent(role)}`;
    if (search) path += `&search=${encodeURIComponent(search)}`;

    // Helper: render rows dari daftar user
    function _renderUserRows(list, pageOffset, isAdmin) {
      if (!list.length) {
        return '<tr><td colspan="7" style="text-align:center;color:var(--text-secondary);padding:20px">Tidak ada pengguna ditemukan.</td></tr>';
      }
      return list.map((u, i) => {
        const isMe      = u.username === session.username;
        const isBuiltin = u.source === 'builtin';
        const canDel    = isAdmin && !isMe && u.username !== 'admin';
        const dnSafe    = (u.displayName || u.username).replace(/'/g, "\\'");
        const statusBadge = u.isDisabled
          ? `<span style="font-size:.72rem;padding:2px 8px;border-radius:4px;background:#fee2e2;color:#b91c1c;font-weight:600">Nonaktif</span>`
          : `<span class="badge-active" style="font-size:.72rem">Aktif</span>`;
        return `<tr class="${isMe ? 'user-table-row-me' : ''}" style="${u.isDisabled ? 'opacity:.6' : ''}">
          <td>${pageOffset + i + 1}</td>
          <td><strong>${u.username}</strong>${isMe ? ' <span class="badge-me" style="font-size:.68rem">Anda</span>' : ''}${isBuiltin ? ' <span style="font-size:.64rem;color:#6b7280;background:#f1f5f9;padding:1px 5px;border-radius:3px">sistem</span>' : ''}</td>
          <td>${u.displayName || '—'}</td>
          <td><span class="badge-role ${u.role}">${ROLE_LABELS[u.role] || u.role}</span></td>
          <td style="font-size:.82rem">
            ${u.unitUsaha
              ? (_BRANCH_ROLES.includes(u.role)
                  ? `<span style="color:var(--text-secondary)">${u.unitUsaha}</span>`
                  : `<span style="font-size:.68rem;background:#e0f2fe;color:#0369a1;padding:1px 7px;border-radius:10px;font-weight:600">${u.unitUsaha}</span>`)
              : '<span style="color:var(--text-secondary)">—</span>'}
          </td>
          <td>${statusBadge}</td>
          <td>
            <div style="display:flex;gap:4px;justify-content:flex-end;flex-wrap:wrap">
              ${isAdmin ? `<button class="tbl-btn" onclick="window._openUserModal('${u.username}')" title="Edit">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
              </button>` : ''}
              ${canDel && !u.isDisabled ? `<button class="tbl-btn tbl-btn-del" onclick="window._confirmDeleteUser('${u.username}','${dnSafe}',${isBuiltin})" title="Kelola/Hapus">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18"/><path d="M19 6l-1 14H6L5 6"/><path d="M8 6V4h8v2"/></svg>
              </button>` : ''}
              ${canDel && u.isDisabled ? `<button class="tbl-btn" onclick="window._enableUser('${u.username}')" title="Aktifkan kembali" style="color:#16a34a">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="9" cy="7" r="4"/><polyline points="17 11 20 14 23 11"/></svg>
              </button>` : ''}
            </div>
          </td>
        </tr>`;
      }).join('');
    }

    try {
      const data  = await _apiReq('GET', path);
      _penggunaList       = data.data || [];
      const total         = data.total || 0;
      const totalPages    = data.totalPages || 1;
      const isAdmin       = session.role === 'admin';
      if (stat) stat.textContent = `${total} pengguna`;
      const rows = showDis ? _penggunaList : _penggunaList.filter(u => !u.isDisabled);
      tbody.innerHTML = _renderUserRows(rows, (_penggunaPage - 1) * _penggunaLimit, isAdmin);
      const pagEl = document.getElementById('penggunaPagination');
      if (pagEl) {
        pagEl.innerHTML = totalPages > 1
          ? Array.from({ length: totalPages }, (_, i) => i + 1).map(p =>
              `<button class="btn-${p === _penggunaPage ? 'primary' : 'outline'}" style="padding:4px 12px;font-size:.8rem;min-width:34px" onclick="window._penggunaGoPage(${p})">${p}</button>`
            ).join('')
          : '';
      }
    } catch (e) {
      // Fallback offline: tampilkan dari getAllUsers() lokal
      try {
        const isAdmin = session.role === 'admin';
        let localUsers = getAllUsers().map(u => ({
          username:   u.username,
          displayName: u.displayName,
          role:       u.role,
          unitUsaha:  u.unitUsaha || '',
          isDisabled: !!(u._disabled),
          source:     'builtin',
        }));
        if (role)   localUsers = localUsers.filter(u => u.role === role);
        if (search) localUsers = localUsers.filter(u =>
          u.username.toLowerCase().includes(search.toLowerCase()) ||
          (u.displayName||'').toLowerCase().includes(search.toLowerCase())
        );
        const rows = showDis ? localUsers : localUsers.filter(u => !u.isDisabled);
        _penggunaList = rows;
        if (stat) stat.textContent = `${rows.length} pengguna (offline)`;
        tbody.innerHTML = _renderUserRows(rows, 0, isAdmin);
      } catch {
        tbody.innerHTML = `<tr><td colspan="7" style="text-align:center;color:#ef4444;padding:20px">Gagal memuat data pengguna.</td></tr>`;
      }
    }
  }

  window._penggunaGoPage    = p => { _penggunaPage = p; renderPengguna(); };
  window._renderPenggunaFilter = () => { _penggunaPage = 1; renderPengguna(); };

  window._openUserModal = async function (username) {
    _editingUsername = username || null;
    const modal = document.getElementById('userModal');
    if (!modal) return;
    modal.classList.remove('hidden');
    modal.style.display = 'flex';

    document.getElementById('userModalAlert').classList.add('hidden');
    const titleEl  = document.getElementById('userModalTitle');
    if (titleEl) titleEl.textContent = username ? 'Edit Pengguna' : 'Tambah Pengguna';

    const usernameEl = document.getElementById('userUsername');
    const passwordEl = document.getElementById('userPassword');
    const pwHelpEl   = document.getElementById('userPasswordHelp');
    const pwReqEl    = document.getElementById('userPasswordReq');
    const nameEl     = document.getElementById('userNameInput');
    const roleEl     = document.getElementById('userRole');
    const uuEl       = document.getElementById('userUnitUsaha');
    const disGrp     = document.getElementById('userDisabledGroup');
    const disChk     = document.getElementById('userIsDisabled');

    const encHintEl = document.getElementById('userPasswordEncHint');

    if (username) {
      if (usernameEl) { usernameEl.value = username; usernameEl.readOnly = true; }
      if (passwordEl) { passwordEl.value = ''; passwordEl.type = 'password'; }
      if (pwHelpEl)   pwHelpEl.style.display   = '';
      if (pwReqEl)    pwReqEl.style.display     = 'none';
      if (encHintEl)  encHintEl.style.display   = 'none';
      if (disGrp)     disGrp.style.display      = '';
      function _fillUserModal(u) {
        if (!u) return;
        const wilEl = document.getElementById('userWilayah');
        if (nameEl) nameEl.value   = u.displayName || '';
        if (roleEl) roleEl.value   = u.role || '';
        if (disChk) disChk.checked = !!u.isDisabled;
        // Isi field lokasi sesuai role
        if (_BRANCH_ROLES.includes(u.role)) {
          if (uuEl)  uuEl.value  = u.unitUsaha || '';
          if (wilEl) wilEl.value = '';
        } else {
          if (uuEl)  uuEl.value  = '';
          if (wilEl) wilEl.value = u.unitUsaha || '';
        }
        window._onUserRoleChange();
      }
      try {
        const cached = _penggunaList.find(u => u.username === username);
        const u = cached || await _apiReq('GET', `/admin/users?search=${encodeURIComponent(username)}`).then(d => d.data?.find(x => x.username === username));
        _fillUserModal(u);
      } catch {
        _fillUserModal(getAllUsers().find(x => x.username === username));
      }
      // Ambil password dari server untuk ditampilkan
      _prefillPassword = null;
      try {
        const pwData = await _apiReq('GET', `/admin/users/${encodeURIComponent(username)}/password`);
        if (pwData.encrypted) {
          if (passwordEl) passwordEl.value = '';
          if (pwHelpEl)   pwHelpEl.style.display  = 'none';
          if (encHintEl)  encHintEl.style.display = '';
          _prefillPassword = null;  // terenkripsi — tidak bisa pre-fill
        } else if (pwData.password) {
          if (passwordEl) passwordEl.value = pwData.password;
          if (pwHelpEl)   pwHelpEl.style.display  = '';
          if (encHintEl)  encHintEl.style.display = 'none';
          _prefillPassword = pwData.password;  // simpan nilai asli untuk deteksi perubahan
        }
      } catch { /* tidak kritis, abaikan */ }
    } else {
      if (usernameEl) { usernameEl.value = ''; usernameEl.readOnly = false; }
      if (passwordEl) { passwordEl.value = ''; passwordEl.type = 'password'; }
      if (pwHelpEl)   pwHelpEl.style.display  = 'none';
      if (pwReqEl)    pwReqEl.style.display   = '';
      if (encHintEl)  encHintEl.style.display = 'none';
      if (nameEl)     nameEl.value    = '';
      if (roleEl)     roleEl.value    = '';
      if (uuEl)       uuEl.value      = '';
      if (disGrp)     disGrp.style.display  = 'none';
      if (disChk)     disChk.checked  = false;
    }
    window._onUserRoleChange();
  };

  window._toggleUserPw = function () {
    const el   = document.getElementById('userPassword');
    const icon = document.getElementById('userPwEyeIcon');
    if (!el) return;
    const isHidden = el.type === 'password';
    el.type = isHidden ? 'text' : 'password';
    if (icon) icon.innerHTML = isHidden
      ? '<path d="M17.94 17.94A10.07 10.07 0 0112 20c-7 0-11-8-11-8a18.45 18.45 0 015.06-5.94"/><path d="M9.9 4.24A9.12 9.12 0 0112 4c7 0 11 8 11 8a18.5 18.5 0 01-2.16 3.19"/><line x1="1" y1="1" x2="23" y2="23"/>'
      : '<path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/>';
  };

  window._closeUserModal = function () {
    const modal = document.getElementById('userModal');
    if (modal) { modal.classList.add('hidden'); modal.style.display = ''; }
    _editingUsername = null;
    _prefillPassword = null;
  };

  const _BRANCH_ROLES   = ['so', 'csc', 'whs', 'kasir'];
  const _REGIONAL_ROLES = ['auditor', 'manajer', 'koordinator', 'coo', 'adm', 'afd', 'rss'];

  window._onUserRoleChange = function () {
    const role   = document.getElementById('userRole')?.value;
    const uuGrp  = document.getElementById('userUnitUsahaGroup');
    const wilGrp = document.getElementById('userWilayahGroup');
    if (uuGrp)  uuGrp.style.display  = _BRANCH_ROLES.includes(role)   ? '' : 'none';
    if (wilGrp) wilGrp.style.display = _REGIONAL_ROLES.includes(role) ? '' : 'none';
  };

  window._saveUser = async function () {
    const username    = document.getElementById('userUsername').value.trim();
    const password    = document.getElementById('userPassword').value;
    const displayName = document.getElementById('userNameInput').value.trim();
    const role        = document.getElementById('userRole').value;
    const unitUsaha   = _BRANCH_ROLES.includes(role)
      ? (document.getElementById('userUnitUsaha')?.value.trim() || '')
      : (document.getElementById('userWilayah')?.value || '');
    const isDisabled  = document.getElementById('userIsDisabled')?.checked || false;
    const alertEl     = document.getElementById('userModalAlert');
    const saveBtn     = document.querySelector('#userModal .btn-primary');

    function showModalAlert(msg) {
      alertEl.textContent = msg;
      alertEl.className   = 'alert error';
      alertEl.classList.remove('hidden');
    }

    if (!username)    return showModalAlert('Username tidak boleh kosong.');
    if (!/^[a-zA-Z0-9_]{3,50}$/.test(username)) return showModalAlert('Username: 3–50 karakter, huruf/angka/underscore.');
    if (!displayName) return showModalAlert('Nama lengkap tidak boleh kosong.');
    if (!role)        return showModalAlert('Pilih role terlebih dahulu.');

    // Deteksi apakah password benar-benar diubah: abaikan jika sama dengan nilai prefill
    const passwordChanged = password && password !== _prefillPassword;

    if (!_editingUsername) {
      if (!password)           return showModalAlert('Password wajib diisi untuk pengguna baru.');
      if (password.length < 8) return showModalAlert('Password minimal 8 karakter.');
      if (!/[a-zA-Z]/.test(password) || !/[0-9]/.test(password)) return showModalAlert('Password harus mengandung huruf dan angka.');
    } else if (passwordChanged) {
      if (password.length < 8) return showModalAlert('Password minimal 8 karakter.');
      if (!/[a-zA-Z]/.test(password) || !/[0-9]/.test(password)) return showModalAlert('Password harus mengandung huruf dan angka.');
    }

    alertEl.classList.add('hidden');
    if (saveBtn) saveBtn.disabled = true;

    try {
      if (!_editingUsername) {
        await _apiReq('POST', '/admin/users', { username, password, displayName, role, unitUsaha });
      } else {
        const body = { displayName, role, unitUsaha, is_disabled: isDisabled };
        if (passwordChanged) body.newPassword = password;
        await _apiReq('PUT', '/admin/users/' + encodeURIComponent(_editingUsername), body);
      }
    } catch (serverErr) {
      // Fallback offline: simpan langsung ke akta_custom_users
      try {
        const cu = loadCustomUsers();
        if (!_editingUsername) {
          if (cu.find(u => u.username === username) || USERS.find(u => u.username === username)) {
            return showModalAlert('Username sudah digunakan.');
          }
          cu.push({ username, password, _passwordClear: password, displayName, role, unitUsaha, _disabled: false, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() });
        } else {
          let idx = cu.findIndex(u => u.username === _editingUsername);
          if (idx === -1) {
            const bi = USERS.find(u => u.username === _editingUsername);
            if (!bi) { showModalAlert('User tidak ditemukan.'); return; }
            cu.push({ username: bi.username, password: bi.password, _passwordClear: bi.password, displayName: bi.displayName, role: bi.role, unitUsaha: bi.unitUsaha || '', _disabled: false, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() });
            idx = cu.length - 1;
          }
          cu[idx].displayName = displayName;
          cu[idx].role        = role;
          cu[idx].unitUsaha   = unitUsaha;
          cu[idx]._disabled   = isDisabled;
          if (passwordChanged) { cu[idx].password = password; cu[idx]._passwordClear = password; }
          cu[idx].updatedAt   = new Date().toISOString();
        }
        saveCustomUsers(cu);
      } catch (localErr) {
        if (saveBtn) saveBtn.disabled = false;
        return showModalAlert(serverErr.message || 'Terjadi kesalahan. Coba lagi.');
      }
    }
    showToast(!_editingUsername ? 'Pengguna baru berhasil ditambahkan.' : 'Data pengguna diperbarui.', 'success');
    window._closeUserModal();
    renderPengguna();
    const mmSection = document.getElementById('section-menu-management');
    if (mmSection && !mmSection.classList.contains('hidden')) renderMenuManagement();
    if (saveBtn) saveBtn.disabled = false;
  };

  window._confirmDeleteUser = function (username, displayName, isBuiltin) {
    const dn = displayName || username;
    const builtinNote = isBuiltin
      ? '<br><small style="color:#6b7280;display:block;margin-top:4px">User sistem bawaan — hanya bisa dinonaktifkan, tidak bisa dihapus permanen.</small>'
      : '';
    document.getElementById('userDelMsg').innerHTML =
      `Pilih tindakan untuk pengguna <strong>${dn}</strong> (${username}):${builtinNote}`;

    const disBtn = document.getElementById('confirmUserDisable');
    const delBtn = document.getElementById('confirmUserDel');
    if (disBtn) {
      disBtn.onclick = async () => {
        document.getElementById('userDelModal').classList.add('hidden');
        await window._deleteUser(username);
      };
    }
    if (delBtn) {
      delBtn.style.display = isBuiltin ? 'none' : '';
      delBtn.onclick = async () => {
        document.getElementById('userDelModal').classList.add('hidden');
        await window._hardDeleteUser(username);
      };
    }
    document.getElementById('userDelModal').classList.remove('hidden');
  };

  window._deleteUser = async function (username) {
    try {
      await _apiReq('DELETE', '/admin/users/' + encodeURIComponent(username));
    } catch {
      // Fallback offline
      try {
        const cu = loadCustomUsers();
        let idx = cu.findIndex(u => u.username === username);
        if (idx === -1) {
          const bi = USERS.find(u => u.username === username);
          if (!bi) { showToast('User tidak ditemukan.', 'error'); return; }
          cu.push({ username: bi.username, password: bi.password, _passwordClear: bi.password, displayName: bi.displayName, role: bi.role, unitUsaha: bi.unitUsaha || '', _disabled: true, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() });
        } else {
          cu[idx]._disabled = true;
          cu[idx].updatedAt = new Date().toISOString();
        }
        saveCustomUsers(cu);
      } catch (e2) { showToast('Gagal menonaktifkan: ' + e2.message, 'error'); return; }
    }
    renderPengguna();
    const mmSec = document.getElementById('section-menu-management');
    if (mmSec && !mmSec.classList.contains('hidden')) renderMenuManagement();
    showToast('Pengguna dinonaktifkan.', 'info');
  };

  window._hardDeleteUser = async function (username) {
    try {
      await _apiReq('DELETE', '/admin/users/' + encodeURIComponent(username) + '?permanent=true');
    } catch {
      // Fallback offline: hapus dari custom_users
      try {
        const cu = loadCustomUsers().filter(u => u.username !== username);
        saveCustomUsers(cu);
      } catch (e2) { showToast('Gagal menghapus: ' + e2.message, 'error'); return; }
    }
    renderPengguna();
    const mmSec = document.getElementById('section-menu-management');
    if (mmSec && !mmSec.classList.contains('hidden')) renderMenuManagement();
    showToast('Pengguna dihapus permanen.', 'success');
  };

  window._enableUser = async function (username) {
    try {
      await _apiReq('PUT', '/admin/users/' + encodeURIComponent(username), { is_disabled: false });
    } catch {
      try {
        const cu = loadCustomUsers();
        let idx = cu.findIndex(u => u.username === username);
        if (idx === -1) {
          const bi = USERS.find(u => u.username === username);
          if (!bi) { showToast('User tidak ditemukan.', 'error'); return; }
          cu.push({ username: bi.username, password: bi.password, _passwordClear: bi.password, displayName: bi.displayName, role: bi.role, unitUsaha: bi.unitUsaha || '', _disabled: false, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() });
        } else {
          cu[idx]._disabled = false;
          cu[idx].updatedAt = new Date().toISOString();
        }
        saveCustomUsers(cu);
      } catch (e2) { showToast('Gagal mengaktifkan: ' + e2.message, 'error'); return; }
    }
    renderPengguna();
    showToast('Pengguna diaktifkan kembali.', 'success');
  };

  // Close modals on overlay click
  document.getElementById('userModal')?.addEventListener('click', function(e) {
    if (e.target === this) window._closeUserModal();
  });
  document.getElementById('userDelModal')?.addEventListener('click', function(e) {
    if (e.target === this) this.classList.add('hidden');
  });

  /* ============================================================
     MODUL PENGATURAN
     ============================================================ */
  function loadOrgSettings() {
    try { return JSON.parse(localStorage.getItem(ORG_KEY)) || {}; } catch { return {}; }
  }
  function saveOrgSettings(data) { localStorage.setItem(ORG_KEY, JSON.stringify(data)); }

  // ── MODUL MONITORING ─────────────────────────────────────────────
  let _monitoringTimer    = null;
  let _monitoringChartLogin = null;
  let _monitoringChartSync  = null;

  function _fmtUptime(secs) {
    const d = Math.floor(secs / 86400);
    const h = Math.floor((secs % 86400) / 3600);
    const m = Math.floor((secs % 3600) / 60);
    if (d > 0) return `${d}h ${h}j ${m}m`;
    if (h > 0) return `${h}j ${m}m`;
    return `${m} menit`;
  }

  function _setText(id, val, cls) {
    const el = document.getElementById(id);
    if (!el) return;
    el.textContent = val;
    if (cls) el.className = `monitoring-status-val ${cls}`;
  }

  function _renderCharts(chartData) {
    const labels = chartData.login_per_hari.map(d => {
      const dt = new Date(d.date + 'T00:00:00');
      return dt.toLocaleDateString('id-ID', { day: 'numeric', month: 'short' });
    });
    const loginData = chartData.login_per_hari.map(d => d.count);
    const syncData  = chartData.data_sync_per_hari.map(d => d.count);

    const chartDefaults = { borderRadius: 4, borderWidth: 2, tension: 0.35, pointRadius: 3 };

    // Line chart: Login per hari
    const ctxL = document.getElementById('chartLogin')?.getContext('2d');
    if (ctxL) {
      if (_monitoringChartLogin) _monitoringChartLogin.destroy();
      _monitoringChartLogin = new Chart(ctxL, {
        type: 'line',
        data: {
          labels,
          datasets: [{
            label: 'Login', data: loginData,
            borderColor: '#1e3a5f', backgroundColor: 'rgba(30,58,95,.08)',
            fill: true, ...chartDefaults,
          }],
        },
        options: {
          responsive: true, maintainAspectRatio: true,
          plugins: { legend: { display: false } },
          scales: {
            y: { beginAtZero: true, ticks: { precision: 0, font: { size: 11 } }, grid: { color: '#f1f5f9' } },
            x: { ticks: { font: { size: 10 } }, grid: { display: false } },
          },
        },
      });
    }

    // Bar chart: Data sync per hari
    const ctxS = document.getElementById('chartSync')?.getContext('2d');
    if (ctxS) {
      if (_monitoringChartSync) _monitoringChartSync.destroy();
      _monitoringChartSync = new Chart(ctxS, {
        type: 'bar',
        data: {
          labels,
          datasets: [{
            label: 'Data Sync', data: syncData,
            backgroundColor: 'rgba(99,102,241,.7)',
            borderColor: '#4f46e5',
            ...chartDefaults,
          }],
        },
        options: {
          responsive: true, maintainAspectRatio: true,
          plugins: { legend: { display: false } },
          scales: {
            y: { beginAtZero: true, ticks: { precision: 0, font: { size: 11 } }, grid: { color: '#f1f5f9' } },
            x: { ticks: { font: { size: 10 } }, grid: { display: false } },
          },
        },
      });
    }
  }

  function _renderActivityTable(rows) {
    const tbody = document.getElementById('monitoringActivityTable');
    if (!tbody) return;
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="5" style="text-align:center;color:var(--gray-400);padding:16px">Tidak ada aktivitas</td></tr>';
      return;
    }
    const actionColor = { LOGIN: '#16a34a', LOGIN_FAILED: '#dc2626', EXPORT: '#d97706', DELETE: '#ef4444', CREATE: '#2563eb', UPDATE: '#7c3aed', BACKUP: '#0d9488' };
    tbody.innerHTML = rows.map(r => {
      const ts  = r.timestamp ? new Date(r.timestamp).toLocaleString('id-ID', { day:'2-digit', month:'short', hour:'2-digit', minute:'2-digit' }) : '-';
      const col = actionColor[r.action] || '#6b7280';
      return `<tr>
        <td style="font-size:.78rem;white-space:nowrap">${ts}</td>
        <td style="font-size:.8rem">${r.displayName || r.username || '-'}</td>
        <td><span style="display:inline-block;padding:2px 8px;border-radius:4px;font-size:.72rem;font-weight:700;background:${col}15;color:${col}">${r.action}</span></td>
        <td style="font-size:.78rem;max-width:260px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${r.detail||''}">${r.detail || '-'}</td>
        <td style="font-size:.75rem;color:var(--gray-400)">${r.ip || '-'}</td>
      </tr>`;
    }).join('');
  }

  async function renderMonitoring(forceRefresh) {
    if (session.role !== 'admin') return;
    try {
      const [stats, chartData] = await Promise.all([
        _apiReq('GET', '/admin/stats'),
        _apiReq('GET', '/admin/stats/chart'),
      ]);

      // Kartu
      _setText('mcUserAktifVal', stats.users.aktif_hari_ini);
      _setText('mcTaskOpenVal',   stats.data.tasks_open);
      _setText('mcSkPendingVal',  stats.data.sk_pending);
      _setText('mcUptimeVal',     _fmtUptime(stats.server.uptime_detik));

      // Server status
      _setText('msDbStatus',    'Connected ✓', 'ok');
      _setText('msMemory',      `${stats.server.memory_mb} MB`);
      _setText('msReqPerMin',   stats.activity.request_per_menit);
      _setText('msDbConn',      stats.server.db_connections);
      _setText('msCacheKeys',   stats.server.cache_keys);
      _setText('msOnline',      `${stats.users.online_sekarang} koneksi`);
      _setText('msLoginToday',  stats.activity.login_hari_ini);
      _setText('msLoginFail',   stats.activity.login_gagal_hari_ini, stats.activity.login_gagal_hari_ini > 0 ? 'err' : '');
      _setText('msExportToday', stats.activity.export_hari_ini);

      // Aktivitas
      _renderActivityTable(stats.recent_activity);

      // Charts
      _renderCharts(chartData);

      // Timestamp
      const el = document.getElementById('monitoringLastUpdate');
      if (el) el.textContent = `Diperbarui: ${new Date().toLocaleTimeString('id-ID')}`;

    } catch (e) {
      showToast('Gagal memuat monitoring: ' + e.message, 'error');
    }

    // Auto-refresh setiap 60 detik
    if (_monitoringTimer) clearTimeout(_monitoringTimer);
    _monitoringTimer = setTimeout(() => {
      if (document.getElementById('section-monitoring')?.classList.contains('hidden') === false) {
        renderMonitoring();
      }
    }, 60000);
  }

  window._loadMonitoring = renderMonitoring;

  function renderPengaturan() {
    const org = loadOrgSettings();
    document.getElementById('setNamaOrg').value    = org.namaOrg    || 'AKTA IAT';
    document.getElementById('setTahunBuku').value  = org.tahunBuku  || new Date().getFullYear();
    document.getElementById('setAlamat').value     = org.alamat     || '';
    document.getElementById('setKontak').value     = org.kontak     || '';
    document.getElementById('setUsername').value   = session.username;
    document.getElementById('setNamaLengkap').value = session.displayName;

    // Tampilkan panel Manajemen Status Audit hanya untuk admin/adm
    const card = document.getElementById('statusMgmtCard');
    if (card) {
      const canManage = session.role === 'admin' || session.role === 'adm';
      card.style.display = canManage ? '' : 'none';
      if (canManage) renderStatusMgmt();
    }
    const rekCard = document.getElementById('rekomendasiMgmtCard');
    if (rekCard) {
      const canManage = session.role === 'admin' || session.role === 'adm';
      rekCard.style.display = canManage ? '' : 'none';
      if (canManage) renderRekomendasiMgmt();
    }
  }

  /* ── Manajemen Status Audit ─────────────────────────────────────── */

  // Status yang bisa di-rollback ke: key = current status, value = array target status
  const STATUS_ROLLBACK_MAP = {
    selesai:      [
      { key: 'in_progress',   label: 'Mulai Cabang (Pemeriksaan Berjalan)',   icon: '▶' },
      { key: 'audit_started', label: 'Mulai Audit (Auditor Memulai)',          icon: '▶' },
      { key: 'coo_approved',  label: 'Disetujui COO (Belum Mulai Audit)',      icon: '→' },
    ],
    in_progress:  [
      { key: 'audit_started', label: 'Mulai Audit (Auditor Memulai)',          icon: '▶' },
      { key: 'coo_approved',  label: 'Disetujui COO (Belum Mulai Audit)',      icon: '→' },
    ],
    audit_started: [
      { key: 'coo_approved',  label: 'Disetujui COO (Belum Mulai Audit)',      icon: '→' },
      { key: 'manajer_approved', label: 'Disetujui Manajer (Menunggu COO)',    icon: '→' },
    ],
  };

  let _statusMgmtFilter = { search: '', planStatus: 'semua' };
  let _statusResetTaskId = null;
  let _statusResetTarget = null;

  function renderStatusMgmt() {
    const el = document.getElementById('statusMgmtTable');
    if (!el) return;
    tasks = loadTasks();
    plans = loadPlans();

    const search     = (_statusMgmtFilter.search || '').toLowerCase();
    const planStatus = _statusMgmtFilter.planStatus;

    // Kumpulkan semua task yang bisa di-reset (ada di STATUS_ROLLBACK_MAP)
    const resetableStatuses = Object.keys(STATUS_ROLLBACK_MAP);
    let rows = [];

    plans.forEach(plan => {
      if (planStatus !== 'semua' && plan.status !== planStatus) return;
      if (search && !plan.noSPT.toLowerCase().includes(search) && !plan.cabangPlan.toLowerCase().includes(search)) return;

      const planTasks = tasks.filter(t =>
        String(t.planId) === String(plan.id) && resetableStatuses.includes(t.status)
      );
      if (!planTasks.length) return;

      rows.push(`
        <div style="border:1px solid var(--border);border-radius:8px;margin-bottom:10px;overflow:hidden">
          <div style="padding:8px 14px;background:var(--hover);border-bottom:1px solid var(--border);
                      display:flex;align-items:center;gap:8px;flex-wrap:wrap">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/>
              <line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/>
            </svg>
            <strong style="font-size:.88rem">${plan.noSPT}</strong>
            <span style="font-size:.8rem;color:var(--text-secondary)">${plan.jenisAudit}</span>
            <span style="font-size:.8rem;color:var(--text-secondary)">·</span>
            <span style="font-size:.8rem;font-weight:600">${plan.cabangPlan}${plan.cabangArea ? ' ' + areaBadge(plan.cabangArea) : ''}</span>
            <span style="margin-left:auto">${planStatusBadge(plan.status)}</span>
          </div>
          <div style="padding:10px 14px">
            ${planTasks.map(t => `
              <div style="display:flex;align-items:center;gap:8px;padding:7px 0;
                          border-bottom:1px solid #f1f5f9;flex-wrap:wrap" id="smrow-${t.id}">
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                  <path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2"/><circle cx="12" cy="7" r="4"/>
                </svg>
                <span style="font-size:.85rem;font-weight:600">${getUserDisplay(t.assignedTo)}</span>
                ${t.isKepala ? '<span style="font-size:.72rem;color:var(--primary);font-weight:600">Kepala Tim</span>' : ''}
                ${taskStatusBadge(t.status)}
                ${t.tglMulai ? `<span style="font-size:.75rem;color:var(--text-secondary)">Mulai: ${t.tglMulai}</span>` : ''}
                <button class="btn-outline" style="margin-left:auto;font-size:.78rem;padding:4px 12px;
                        border-color:#f59e0b;color:#92400e;background:#fffbeb"
                        onclick="window._openStatusResetModal('${t.id}')">
                  <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"
                       style="vertical-align:middle;margin-right:4px">
                    <polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 102.13-9.36L1 10"/>
                  </svg>
                  Reset Status
                </button>
              </div>`).join('')}
          </div>
        </div>`);
    });

    el.innerHTML = rows.length
      ? rows.join('')
      : `<div class="empty-state" style="padding:30px">
           <p>Tidak ada task yang bisa di-reset.</p>
           <p style="font-size:.8rem;color:var(--text-secondary)">
             Hanya task dengan status Selesai, Berjalan, atau Mulai Audit yang dapat dikembalikan.
           </p>
         </div>`;
  }

  window._filterStatusMgmt = function () {
    _statusMgmtFilter.search     = document.getElementById('statusMgmtSearch')?.value || '';
    _statusMgmtFilter.planStatus = document.getElementById('statusMgmtPlanFilter')?.value || 'semua';
    renderStatusMgmt();
  };

  // ── Reset Rekomendasi oleh ADM ───────────────────────────────────────
  function renderRekomendasiMgmt() {
    const el = document.getElementById('rekomendasiMgmtTable');
    if (!el) return;
    const rekList = loadRekomendasi();
    if (!rekList.length) {
      el.innerHTML = `<div class="empty-state" style="padding:20px"><p>Belum ada data rekomendasi.</p></div>`;
      return;
    }
    const statusLbl = {
      pending_auditor:'Menunggu Auditor', pending_unit:'Menunggu Unit Usaha',
      pending_rss:'Menunggu RSS', pending_manajer:'Menunggu Manajer',
      pending_afd:'Menunggu Keputusan AFD', selesai:'✓ Selesai',
    };
    el.innerHTML = rekList.map(r => `
      <div style="border:1px solid #c4b5fd;border-radius:7px;padding:10px 14px;margin-bottom:8px;background:#faf5ff;display:flex;align-items:center;gap:12px;flex-wrap:wrap">
        <div style="flex:1;min-width:180px">
          <strong style="font-size:.88rem">${r.noSPT}</strong>
          <span style="font-size:.8rem;color:var(--text-secondary);margin-left:8px">${r.unitUsaha}</span>
          <div style="font-size:.75rem;margin-top:3px">
            Status: <strong style="color:#5b21b6">${statusLbl[r.status] || r.status}</strong>
          </div>
        </div>
        <div style="display:flex;gap:6px;flex-wrap:wrap">
          ${REKOM_STATUS_SEQ.filter(s => s !== 'selesai' && s !== 'pending_auditor').map(s => `
            <button class="btn-outline" style="font-size:.72rem;padding:3px 10px;border-color:#7c3aed;color:#7c3aed"
                    onclick="window._adminResetRekom('${r.planId}','${s}')">
              ↩ Ke ${statusLbl[s]?.replace('Menunggu ','') || s}
            </button>`).join('')}
          <button class="btn-clear-data" style="font-size:.72rem;padding:3px 10px"
                  onclick="window._adminResetRekom('${r.planId}','pending_auditor')">
            ↩ Mulai Ulang (Auditor)
          </button>
        </div>
      </div>`).join('');
  }

  window._adminResetRekom = function (planId, toStatus) {
    const rekList = loadRekomendasi();
    const idx = rekList.findIndex(r => String(r.planId) === String(planId));
    if (idx < 0) return;
    const fromStatus = rekList[idx].status;
    if (!confirm(`Reset rekomendasi "${rekList[idx].noSPT}" dari "${fromStatus}" ke "${toStatus}"?`)) return;

    // Hapus data step yang akan di-ulang
    const fromIdx = REKOM_STATUS_SEQ.indexOf(fromStatus);
    const toIdx   = REKOM_STATUS_SEQ.indexOf(toStatus);
    if (toIdx >= 0 && toIdx <= fromIdx) {
      // Hapus step dari toIdx sampai fromIdx
      for (let i = toIdx; i <= fromIdx; i++) {
        const stepKey = REKOM_STEPS[i]?.key;
        if (stepKey) rekList[idx].steps[stepKey] = null;
      }
    }
    rekList[idx].status = toStatus;
    saveRekomendasi(rekList);
    renderRekomendasiMgmt();
    showToast(`Rekomendasi ${rekList[idx].noSPT} berhasil direset ke ${toStatus}.`, 'success');
  };

  window._openStatusResetModal = function (taskId) {
    tasks = loadTasks();
    plans = loadPlans();
    const t = tasks.find(x => x.id == taskId);
    if (!t) return;
    _statusResetTaskId = taskId;
    _statusResetTarget = null;

    const plan = plans.find(p => String(p.id) === String(t.planId));
    const titleEl = document.getElementById('statusResetModalTitle');
    if (titleEl) titleEl.textContent = 'Reset Status Audit';

    // Info task
    const infoEl = document.getElementById('statusResetTaskInfo');
    if (infoEl) infoEl.innerHTML = `
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px">
        <div><label style="font-size:.72rem;text-transform:uppercase;color:#9ca3af;display:block">No SPT</label>
             <strong>${t.noSPT}</strong></div>
        <div><label style="font-size:.72rem;text-transform:uppercase;color:#9ca3af;display:block">Cabang</label>
             <strong>${t.cabangPlan}</strong></div>
        <div><label style="font-size:.72rem;text-transform:uppercase;color:#9ca3af;display:block">Auditor</label>
             <span>${getUserDisplay(t.assignedTo)}</span></div>
        <div><label style="font-size:.72rem;text-transform:uppercase;color:#9ca3af;display:block">Status Saat Ini</label>
             ${taskStatusBadge(t.status)}</div>
      </div>`;

    // Log ringkas
    const logEl = document.getElementById('statusResetLogSection');
    if (logEl) logEl.innerHTML = renderStatusLog(t.statusLog);

    // Opsi status target
    const targets = STATUS_ROLLBACK_MAP[t.status] || [];
    const optEl = document.getElementById('statusResetOptions');
    if (optEl) {
      if (!targets.length) {
        optEl.innerHTML = `<p style="color:var(--text-secondary);font-size:.82rem">Status ini tidak dapat di-rollback.</p>`;
      } else {
        optEl.innerHTML = targets.map(s => `
          <label style="display:flex;align-items:center;gap:10px;padding:8px 12px;border:1px solid var(--border);
                         border-radius:7px;cursor:pointer;transition:.15s"
                 onmouseenter="this.style.background='#f8fafc'" onmouseleave="this.style.background=''"
                 onclick="window._selectStatusTarget('${s.key}', this)">
            <input type="radio" name="statusTarget" value="${s.key}" style="margin:0;accent-color:#1e3a5f" />
            <span style="font-size:.88rem">
              <strong style="color:#1e3a5f">${s.icon} ${s.label}</strong>
            </span>
          </label>`).join('');
      }
    }

    // Reset fields
    const reasonEl = document.getElementById('statusResetReason');
    if (reasonEl) reasonEl.value = '';
    const alertEl = document.getElementById('statusResetAlert');
    if (alertEl) alertEl.classList.add('hidden');

    document.getElementById('statusResetModal').classList.remove('hidden');
    document.getElementById('statusResetModal').style.display = 'flex';
  };

  window._selectStatusTarget = function (key, labelEl) {
    _statusResetTarget = key;
    document.querySelectorAll('#statusResetOptions label').forEach(l => {
      l.style.borderColor = '';
      l.style.background  = '';
    });
    if (labelEl) {
      labelEl.style.borderColor = '#1e3a5f';
      labelEl.style.background  = '#eef2ff';
    }
  };

  window._closeStatusResetModal = function () {
    document.getElementById('statusResetModal')?.classList.add('hidden');
    document.getElementById('statusResetModal').style.display = '';
    _statusResetTaskId = null;
    _statusResetTarget = null;
  };

  window._confirmStatusReset = function () {
    const alertEl = document.getElementById('statusResetAlert');
    function showAlert(msg) {
      alertEl.textContent = msg;
      alertEl.className = 'alert error';
      alertEl.classList.remove('hidden');
    }

    if (!_statusResetTarget) { showAlert('Pilih status tujuan terlebih dahulu.'); return; }

    const reason = document.getElementById('statusResetReason').value.trim();
    if (!reason) { showAlert('Alasan reset wajib diisi.'); return; }

    tasks = loadTasks();
    const idx = tasks.findIndex(x => x.id == _statusResetTaskId);
    if (idx < 0) { showAlert('Task tidak ditemukan.'); return; }

    const oldStatus = tasks[idx].status;
    const note = `[RESET oleh ${session.displayName} (${session.role})] ${oldStatus} → ${_statusResetTarget}. Alasan: ${reason}`;

    tasks[idx] = {
      ...tasks[idx],
      status:         _statusResetTarget,
      resetAt:        new Date().toISOString(),
      resetBy:        session.username,
      resetReason:    reason,
      statusLog:      addStatusLog(tasks[idx], _statusResetTarget, note),
    };

    // Jika task di-reset dari selesai, kembalikan plan ke aktif
    if (oldStatus === 'selesai') {
      plans = loadPlans();
      const pi = plans.findIndex(p => String(p.id) === String(tasks[idx].planId));
      if (pi >= 0 && plans[pi].status === 'selesai') {
        plans[pi].status = 'aktif';
        delete plans[pi].selesaiAt;
        savePlans(plans);
      }
    }

    saveTasks(tasks);
    window._closeStatusResetModal();
    renderStatusMgmt();
    renderAuditSection();
    updateTaskBadge();
    updateAuditBadge();

    showToast(
      `Status task ${getUserDisplay(tasks[idx].assignedTo)} berhasil direset ke "${_statusResetTarget || tasks[idx].status}".`,
      'success', 4000
    );
  };

  document.getElementById('statusResetModal')?.addEventListener('click', function(e) {
    if (e.target === this) window._closeStatusResetModal();
  });

  document.getElementById('btnSaveOrg').addEventListener('click', () => {
    const data = {
      namaOrg:   document.getElementById('setNamaOrg').value.trim(),
      tahunBuku: document.getElementById('setTahunBuku').value,
      alamat:    document.getElementById('setAlamat').value.trim(),
      kontak:    document.getElementById('setKontak').value.trim(),
    };
    saveOrgSettings(data);
    showToast('Pengaturan organisasi disimpan.', 'success');
  });

  document.getElementById('btnResetOrg').addEventListener('click', () => {
    localStorage.removeItem(ORG_KEY);
    renderPengaturan();
    showToast('Pengaturan direset ke default.', 'info');
  });

  /* ============================================================
     MODUL MANAJEMEN MENU (ADM)
     ============================================================ */

  // ── Pengaturan Menu Pemeriksaan per Jenis Audit ──────────────
  const PEM_MENU_CONFIG_KEY = 'akta_pem_menu_cfg';

  const PEM_MENU_ITEMS = [
    { key:'smh',        label:'Pemeriksaan Unit SMH',    icon:'🏍' },
    { key:'luar',       label:'Perlengkapan Luar Fisik', icon:'📦' },
    { key:'kas',        label:'Pemeriksaan Kas',         icon:'💰' },
    { key:'hgp',        label:"HGP & AHM Oil's",        icon:'🛢' },
    { key:'bank',       label:'Pemeriksaan Bank',        icon:'🏦' },
    { key:'meterai',    label:'Materai Tempel',          icon:'📮' },
    { key:'bpkb',       label:'BPKB Onhand',            icon:'📄' },
    { key:'lapos',      label:'Lapos & Inproses BPKB',  icon:'📑' },
    { key:'kwt',        label:'Kwitansi Gantung',        icon:'🧾' },
    { key:'piutang',    label:'Piutang Reguler',         icon:'💳' },
    { key:'kds',        label:'Tunggakan KDS',           icon:'⏰' },
    { key:'ttp',        label:'TTP Gantung',             icon:'📋' },
    { key:'mt',         label:'Pemeriksaan MT',          icon:'🔧' },
    { key:'lampiran',   label:'Lampiran',                icon:'📎' },
    { key:'grading',    label:'Grading',                 icon:'⭐' },
    { key:'rekomendasi',label:'Rekomendasi',             icon:'💡' },
    { key:'bu_perf',    label:'BU Performance',          icon:'📊' },
  ];

  const JENIS_AUDIT_LIST = [
    'Audit',
    'Audit Online Kas + Unit SMH',
    "Audit Online Kas + HGP & AHM Oil's",
    'Audit Verifikasi HO',
    'Audit Verifikasi Lapangan',
    'Audit Serah Terima Sales Office Head',
    'Audit Serah Terima Warehouse',
    "Audit Kas + HGP & AHM Oil's",
    'Audit Kas + Unit SMH',
    'Audit Kas + BPKB',
    'Audit Serah Terima Partkeeper',
    'Audit Serah Terima Workshop Head',
    'Audit PJS SO HEAD',
    'Audit PJS SO ADH',
    'Audit CHTC',
    'Audit PAV/HC3/HOHO MDN',
    'Audit Faktur',
    'Audit Serah Terima Kasir',
    'Audit Serah Terima Pos Head',
  ];

  // Default: semua menu aktif untuk semua jenis audit
  function _defaultPemMenuConfig() {
    const cfg = {};
    JENIS_AUDIT_LIST.forEach(j => {
      cfg[j] = {};
      PEM_MENU_ITEMS.forEach(m => { cfg[j][m.key] = true; });
    });
    return cfg;
  }

  function loadPemMenuConfig() {
    try {
      const saved = JSON.parse(localStorage.getItem(PEM_MENU_CONFIG_KEY));
      if (!saved) return _defaultPemMenuConfig();
      // Merge — ensure new jenis/items get defaults
      const def = _defaultPemMenuConfig();
      JENIS_AUDIT_LIST.forEach(j => {
        def[j] = {};
        PEM_MENU_ITEMS.forEach(m => {
          def[j][m.key] = (saved[j] && saved[j][m.key] !== undefined) ? saved[j][m.key] : true;
        });
      });
      return def;
    } catch { return _defaultPemMenuConfig(); }
  }

  function savePemMenuConfigData(cfg) {
    localStorage.setItem(PEM_MENU_CONFIG_KEY, JSON.stringify(cfg));
    window.API?.sync(PEM_MENU_CONFIG_KEY, cfg);
  }

  function isPemMenuEnabled(jenisAudit, menuKey) {
    const cfg = loadPemMenuConfig();
    // Jika jenis audit tidak dikenal dalam config → tampilkan semua
    if (!cfg[jenisAudit]) return true;
    return cfg[jenisAudit][menuKey] !== false;
  }

  function renderPemMenuConfig() {
    const el = document.getElementById('pemMenuConfigTable');
    if (!el) return;
    const isAdm = (session?.role === 'adm' || session?.role === 'admin');
    if (!isAdm) {
      el.innerHTML = '<p style="color:var(--text-secondary);font-size:.84rem">⚠️ Hanya ADM yang dapat mengatur konfigurasi ini.</p>';
      return;
    }
    // In-memory draft so tab-switching doesn't lose unsaved changes
    if (!window._pemCfgDraft) window._pemCfgDraft = loadPemMenuConfig();
    const cfg = window._pemCfgDraft;
    // Restore selected tab from localStorage so it survives page refresh
    const _savedJenis = localStorage.getItem('akta_pem_cfg_selected_jenis');
    const selected = el.dataset.selectedJenis
      || (_savedJenis && JENIS_AUDIT_LIST.includes(_savedJenis) ? _savedJenis : null)
      || JENIS_AUDIT_LIST[0];

    // ── Tab pills per jenis audit ──
    const tabsHtml = JENIS_AUDIT_LIST.map(j => {
      const onCount = PEM_MENU_ITEMS.filter(m => cfg[j]?.[m.key] !== false).length;
      const isAct   = (j === selected);
      const safeJ   = j.replace(/'/g, "\\'");
      return `<button onclick="window._selectPemCfgJenis('${safeJ}')"
        style="display:inline-flex;align-items:center;gap:6px;padding:6px 12px;border-radius:8px;
               border:1.5px solid ${isAct ? 'var(--primary)' : 'var(--border)'};
               background:${isAct ? 'var(--primary)' : 'var(--card)'};
               color:${isAct ? '#fff' : 'var(--text)'};
               font-size:.75rem;font-weight:600;cursor:pointer;white-space:nowrap;transition:all .15s">
        <span>${j}</span>
        <span style="background:${isAct ? 'rgba(255,255,255,.25)' : 'var(--hover)'};border-radius:9px;padding:1px 7px;font-size:.68rem">${onCount}/${PEM_MENU_ITEMS.length}</span>
      </button>`;
    }).join('');

    // ── Toggle cards for selected jenis ──
    const cardsHtml = PEM_MENU_ITEMS.map(m => {
      const chk   = cfg[selected]?.[m.key] !== false;
      const safeJ = selected.replace(/"/g, '&quot;');
      return `<label style="display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:9px;
                    border:1.5px solid ${chk ? '#6ee7b7' : 'var(--border)'};
                    background:${chk ? '#f0fdf4' : 'var(--card)'};cursor:pointer;transition:all .15s">
        <input type="checkbox" class="pem-menu-cfg-cb"
               data-jenis="${safeJ}" data-menu="${m.key}"
               ${chk ? 'checked' : ''}
               style="width:15px;height:15px;accent-color:#059669;cursor:pointer;flex-shrink:0"
               onchange="window._onPemCfgChange(this)">
        <span style="flex:1;font-size:.81rem;font-weight:600;color:var(--text)">${m.label}</span>
        <span class="pem-cfg-status" style="font-size:.74rem;font-weight:700;color:${chk ? '#059669' : '#94a3b8'};white-space:nowrap">${chk ? '✓ Aktif' : '○ Off'}</span>
      </label>`;
    }).join('');

    el.innerHTML = `
      <div>
        <div style="margin-bottom:10px">
          <div style="font-size:.72rem;color:var(--text-secondary);font-weight:700;text-transform:uppercase;letter-spacing:.06em;margin-bottom:7px">
            Pilih Jenis Audit
          </div>
          <div style="display:flex;flex-wrap:wrap;gap:5px">${tabsHtml}</div>
        </div>

        <div style="background:var(--hover);border-radius:9px;padding:11px 15px;margin-bottom:11px;
                    display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px">
          <div>
            <div style="font-size:.86rem;font-weight:700">${selected}</div>
            <div style="font-size:.73rem;color:var(--text-secondary);margin-top:2px">
              Centang menu yang <strong>aktif</strong> untuk jenis audit ini
            </div>
          </div>
          <div style="display:flex;gap:6px;flex-wrap:wrap">
            <button onclick="window._pemCfgToggleAll('${selected.replace(/'/g, "\\'")}',true)"
              style="font-size:.74rem;padding:5px 12px;border-radius:6px;border:1px solid #6ee7b7;
                     background:#f0fdf4;color:#065f46;cursor:pointer;font-weight:600">
              ✓ Semua Aktif
            </button>
            <button onclick="window._pemCfgToggleAll('${selected.replace(/'/g, "\\'")}',false)"
              style="font-size:.74rem;padding:5px 12px;border-radius:6px;border:1px solid var(--border);
                     background:var(--card);color:var(--text-secondary);cursor:pointer">
              ○ Semua Non-aktif
            </button>
          </div>
        </div>

        <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(195px,1fr));gap:7px;margin-bottom:14px">
          ${cardsHtml}
        </div>

        <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
          <button onclick="window._savePemMenuConfig()"
            style="background:var(--primary);color:#fff;border:none;border-radius:7px;padding:8px 20px;font-size:.84rem;font-weight:700;cursor:pointer">
            💾 Simpan Konfigurasi
          </button>
          <button onclick="window._resetPemMenuConfig()"
            style="background:var(--hover);color:var(--text-secondary);border:1px solid var(--border);border-radius:7px;padding:8px 14px;font-size:.84rem;cursor:pointer">
            ↺ Reset Semua ke Default
          </button>
          <span id="pemMenuCfgMsg" style="font-size:.78rem;color:#166534"></span>
        </div>
      </div>`;
  }

  window._onPemCfgChange = function(cb) {
    if (!window._pemCfgDraft) window._pemCfgDraft = loadPemMenuConfig();
    const j = cb.dataset.jenis; const k = cb.dataset.menu;
    if (j && k && window._pemCfgDraft[j]) window._pemCfgDraft[j][k] = cb.checked;
    const lbl = cb.closest('label');
    if (lbl) {
      lbl.style.border     = `1.5px solid ${cb.checked ? '#6ee7b7' : 'var(--border)'}`;
      lbl.style.background = cb.checked ? '#f0fdf4' : 'var(--card)';
      const st = lbl.querySelector('.pem-cfg-status');
      if (st) { st.textContent = cb.checked ? '✓ Aktif' : '○ Off'; st.style.color = cb.checked ? '#059669' : '#94a3b8'; }
    }
    // Refresh tab pill counts only (lightweight)
    document.querySelectorAll('#pemMenuConfigTable button').forEach(btn => {
      const label = btn.querySelector('span:first-child')?.textContent;
      const countEl = btn.querySelector('span:last-child');
      if (!label || !countEl || !window._pemCfgDraft[label]) return;
      const onCount = PEM_MENU_ITEMS.filter(m => window._pemCfgDraft[label]?.[m.key] !== false).length;
      countEl.textContent = `${onCount}/${PEM_MENU_ITEMS.length}`;
    });
  };

  window._selectPemCfgJenis = function(jenis) {
    // Capture current DOM checkboxes before re-render
    if (!window._pemCfgDraft) window._pemCfgDraft = loadPemMenuConfig();
    document.querySelectorAll('.pem-menu-cfg-cb').forEach(cb => {
      const j = cb.dataset.jenis; const k = cb.dataset.menu;
      if (j && k && window._pemCfgDraft[j]) window._pemCfgDraft[j][k] = cb.checked;
    });
    const el = document.getElementById('pemMenuConfigTable');
    if (!el) return;
    el.dataset.selectedJenis = jenis;
    // Persist selected tab so it survives page refresh
    localStorage.setItem('akta_pem_cfg_selected_jenis', jenis);
    renderPemMenuConfig();
  };

  window._pemCfgToggleAll = function(jenis, state) {
    if (!window._pemCfgDraft) window._pemCfgDraft = loadPemMenuConfig();
    PEM_MENU_ITEMS.forEach(m => { if (window._pemCfgDraft[jenis]) window._pemCfgDraft[jenis][m.key] = state; });
    document.querySelectorAll('.pem-menu-cfg-cb').forEach(cb => {
      if (cb.dataset.jenis !== jenis) return;
      cb.checked = state;
      const lbl = cb.closest('label');
      if (lbl) {
        lbl.style.border     = `1.5px solid ${state ? '#6ee7b7' : 'var(--border)'}`;
        lbl.style.background = state ? '#f0fdf4' : 'var(--card)';
        const st = lbl.querySelector('.pem-cfg-status');
        if (st) { st.textContent = state ? '✓ Aktif' : '○ Off'; st.style.color = state ? '#059669' : '#94a3b8'; }
      }
    });
    const el = document.getElementById('pemMenuConfigTable');
    if (el) { el.dataset.selectedJenis = jenis; renderPemMenuConfig(); }
  };

  window._savePemMenuConfig = function() {
    if (!window._pemCfgDraft) window._pemCfgDraft = loadPemMenuConfig();
    // Capture current visible checkboxes
    document.querySelectorAll('.pem-menu-cfg-cb').forEach(cb => {
      const j = cb.dataset.jenis; const k = cb.dataset.menu;
      if (j && k && window._pemCfgDraft[j]) window._pemCfgDraft[j][k] = cb.checked;
    });
    savePemMenuConfigData(window._pemCfgDraft);
    const msg = document.getElementById('pemMenuCfgMsg');
    if (msg) { msg.textContent = '✓ Tersimpan — ' + new Date().toLocaleTimeString('id-ID'); setTimeout(() => { if (msg) msg.textContent = ''; }, 3000); }
    showToast('Konfigurasi menu pemeriksaan disimpan.', 'success');
    renderPemMenuConfig();
  };

  window._resetPemMenuConfig = function() {
    if (!confirm('Reset semua konfigurasi menu pemeriksaan ke default (semua aktif)?')) return;
    window._pemCfgDraft = _defaultPemMenuConfig();
    savePemMenuConfigData(window._pemCfgDraft);
    const el = document.getElementById('pemMenuConfigTable');
    if (el) el.dataset.selectedJenis = JENIS_AUDIT_LIST[0];
    renderPemMenuConfig();
    showToast('Konfigurasi direset ke default.', 'info');
  };

  // Build menu section list dynamically from actual nav items in the DOM
  function getDynamicMenuSections() {
    const seen = new Set();
    return [...sectionItems]
      .map(li => li.dataset.section)
      .filter(key => {
        if (!key || NAV_CONFIG_EXCLUDE.has(key) || seen.has(key)) return false;
        seen.add(key);
        return true;
      })
      .map(key => {
        const meta = NAV_META[key];
        if (meta) return { key, label: meta.label, desc: meta.desc };
        // Fallback: derive label from nav link text
        const navA = document.querySelector(`.nav-item[data-section="${key}"] a`);
        const rawText = navA ? navA.textContent.replace(/\s+/g, ' ').trim() : key;
        const label = rawText.replace(/\d+$/, '').trim() || key; // strip trailing badge numbers
        return { key, label, desc: '' };
      });
  }
  // Urutan tampil default untuk role yang sudah dikenal
  const ROLE_DISPLAY_ORDER = [
    'manajer', 'koordinator', 'coo', 'auditor',
    'so', 'csc', 'whs', 'kasir', 'rss', 'afd',
  ];

  // Bangun daftar role secara dinamis dari semua user yang ada
  function getConfigurableRoles() {
    const excluded = new Set(['admin', 'adm']);
    const roleSet  = new Set();

    // Kumpulkan semua role dari seluruh user (built-in + custom)
    getAllUsers().forEach(u => {
      if (u.role && !excluded.has(u.role)) roleSet.add(u.role);
    });

    // Urutkan: role yang dikenal duluan (sesuai ROLE_DISPLAY_ORDER),
    // lalu role baru (tidak dikenal) secara alfabetis di akhir
    const known = ROLE_DISPLAY_ORDER.filter(r => roleSet.has(r));
    const newRoles = [...roleSet]
      .filter(r => !ROLE_DISPLAY_ORDER.includes(r))
      .sort((a, b) => a.localeCompare(b));

    return [...known, ...newRoles].map(key => ({
      key,
      label: ROLE_LABELS[key]
        ? ROLE_LABELS[key]
        : key.charAt(0).toUpperCase() + key.slice(1),
      isNew: !ROLE_DISPLAY_ORDER.includes(key),
    }));
  }

  function renderMenuManagement() {
    const container = document.getElementById('menuConfigTable');
    if (!container) return;
    // Reset draft so re-opening always loads from saved storage
    window._pemCfgDraft = null;
    renderPemMenuConfig();

    const rules          = loadMenuConfig();
    const configRoles    = getConfigurableRoles();

    // Header kolom — role baru diberi lencana hijau "Baru"
    const roleHeaders = configRoles.map(r =>
      `<th style="text-align:center;min-width:80px;font-size:.78rem">
         ${r.label}
         ${r.isNew
           ? '<div style="font-size:.62rem;background:#dcfce7;color:#166534;border-radius:4px;padding:1px 5px;margin-top:2px;display:inline-block">Baru</div>'
           : ''}
       </th>`
    ).join('');

    const rows = getDynamicMenuSections().map(sec => {
      const defaultRoles = DEFAULT_NAV_RULES[sec.key] || [];
      const cells = configRoles.map(role => {
        const checked = (rules[sec.key] || []).includes(role.key);
        return `<td style="text-align:center">
          <input type="checkbox" class="menu-cfg-cb"
            data-section="${sec.key}" data-role="${role.key}"
            ${checked ? 'checked' : ''}
          />
        </td>`;
      }).join('');

      return `<tr>
        <td>
          <strong style="font-size:.88rem">${sec.label}</strong>
          <div style="font-size:.75rem;color:var(--text-secondary);margin-top:2px">${sec.desc}</div>
        </td>
        <td style="text-align:center">
          <span class="badge-role admin" style="font-size:.7rem">Admin</span>
          <span class="badge-role adm" style="font-size:.7rem;margin-left:3px">ADM</span>
        </td>
        ${cells}
      </tr>`;
    }).join('');

    // Hitung total role baru (tidak dikenal sebelumnya)
    const newCount = configRoles.filter(r => r.isNew).length;
    const newRoleBanner = newCount > 0
      ? `<div style="display:flex;align-items:center;gap:8px;background:#f0fdf4;border:1px solid #86efac;
                     border-radius:7px;padding:8px 14px;margin-bottom:10px;font-size:.82rem;color:#166534">
           <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
             <path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/>
             <circle cx="9" cy="7" r="4"/>
             <path d="M23 21v-2a4 4 0 00-3-3.87"/><path d="M16 3.13a4 4 0 010 7.75"/>
           </svg>
           <span><strong>${newCount} role baru</strong> terdeteksi dari daftar pengguna dan otomatis ditambahkan sebagai kolom baru di bawah.
           Atur akses menunya lalu klik <strong>Simpan Konfigurasi</strong>.</span>
         </div>`
      : '';

    container.innerHTML = `
      ${newRoleBanner}
      <div style="overflow-x:auto">
        <table class="menu-cfg-table" style="min-width:600px">
          <thead>
            <tr>
              <th>Menu / Section</th>
              <th style="text-align:center;min-width:110px;font-size:.78rem">Selalu Ada</th>
              ${roleHeaders}
            </tr>
          </thead>
          <tbody>${rows}</tbody>
        </table>
      </div>
      <p style="margin-top:12px;font-size:.8rem;color:var(--text-secondary)">
        &#9432; <strong>Admin</strong> dan <strong>ADM</strong> selalu memiliki akses ke semua menu yang relevan.
        Kolom role muncul otomatis saat ada pengguna dengan role tersebut.
        Perubahan berlaku setelah disimpan.
      </p>`;
  }

  window.saveMenuConfig = function () {
    const newRules = {};
    // Seed from current nav sections (admin always included)
    getDynamicMenuSections().forEach(sec => {
      const defAdm = (DEFAULT_NAV_RULES[sec.key] || ['admin', 'adm']).filter(r => r === 'admin' || r === 'adm');
      newRules[sec.key] = [...defAdm];
    });

    document.querySelectorAll('.menu-cfg-cb').forEach(cb => {
      const sec  = cb.dataset.section;
      const role = cb.dataset.role;
      if (cb.checked && newRules[sec] && !newRules[sec].includes(role)) newRules[sec].push(role);
    });

    // Ensure ADM always in database section
    if (newRules['database-smh'] && !newRules['database-smh'].includes('adm')) newRules['database-smh'].push('adm');

    localStorage.setItem(MENU_CONFIG_KEY, JSON.stringify(newRules));
    window.API?.sync(MENU_CONFIG_KEY, newRules);
    currentNavRules = loadMenuConfig();
    applyNavVisibility(currentNavRules);
    showToast('Konfigurasi menu berhasil disimpan.', 'success');
  };

  window.resetMenuConfig = function () {
    if (!confirm('Reset konfigurasi menu ke default?')) return;
    localStorage.removeItem(MENU_CONFIG_KEY);
    currentNavRules = loadMenuConfig();
    applyNavVisibility(currentNavRules);
    renderMenuManagement();
    showToast('Konfigurasi menu direset ke default.', 'info');
  };

  /* ============================================================
     MODUL PEMERIKSAAN KAS
     ============================================================ */
  const PEM_TODAY   = new Date().toISOString().split('T')[0];
  const DENOMINATIONS = [100000, 50000, 20000, 10000, 5000, 2000, 1000, 500, 200, 100];

  // Set default dates
  try {
    document.getElementById('tglPemeriksaan').value   = PEM_TODAY;
    document.getElementById('kasBesarTanggalAwal').value = PEM_TODAY;
  } catch(e) { console.error('[init] pem-kas dates:', e); }

  function createTransaksiRow(tbody, onRecalc) {
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td><input type="date" class="pem-input-sm" value="${PEM_TODAY}" /></td>
      <td><input type="text"   class="pem-input-sm" placeholder="Keterangan..." /></td>
      <td><input type="number" class="pem-input-sm pem-num" value="0" min="0" /></td>
      <td><button class="btn-del-row" title="Hapus baris">&#10005;</button></td>`;
    tr.querySelector('.btn-del-row').addEventListener('click', () => { tr.remove(); onRecalc(); });
    tr.querySelector('.pem-num').addEventListener('input', onRecalc);
    tbody.appendChild(tr);
    onRecalc();
  }

  function createBlankoRow(container) {
    const div = document.createElement('div');
    div.className = 'blanko-row';
    div.innerHTML = `
      <span class="blanko-jenis-label">Jenis</span>
      <input type="text" class="kas-input blanko-input" placeholder="Nomor range blanko..." />
      <button class="btn-del-row" title="Hapus baris">&#10005;</button>`;
    div.querySelector('.btn-del-row').addEventListener('click', () => div.remove());
    container.appendChild(div);
  }

  function buildPecahanTable() {
    const tbody = document.getElementById('pecahanBody');
    DENOMINATIONS.forEach(d => {
      const tr = document.createElement('tr');
      tr.dataset.denom = d;
      tr.innerHTML = `
        <td class="pecahan-denom">${d.toLocaleString('id-ID')}</td>
        <td><input type="number" class="pem-num-sm pec-kb" value="0" min="0" /></td>
        <td class="pec-kb-total">Rp 0</td>
        <td><input type="number" class="pem-num-sm pec-kk" value="0" min="0" /></td>
        <td class="pec-kk-total">Rp 0</td>`;
      tbody.appendChild(tr);
    });
    document.querySelectorAll('.pec-kb, .pec-kk').forEach(inp =>
      inp.addEventListener('input', pemRecalcAll));
  }

  function pemSumRows(tbody) {
    return Array.from(tbody.querySelectorAll('.pem-num'))
      .reduce((s, inp) => s + (parseInt(inp.value) || 0), 0);
  }

  function pemRecalcPecahan() {
    let kbQty = 0, kbAmt = 0, kkQty = 0, kkAmt = 0;
    document.querySelectorAll('#pecahanBody tr').forEach(tr => {
      const d   = parseInt(tr.dataset.denom);
      const kbQ = parseInt(tr.querySelector('.pec-kb').value) || 0;
      const kkQ = parseInt(tr.querySelector('.pec-kk').value) || 0;
      tr.querySelector('.pec-kb-total').textContent = formatRupiah(d * kbQ);
      tr.querySelector('.pec-kk-total').textContent = formatRupiah(d * kkQ);
      kbQty += kbQ;  kbAmt += d * kbQ;
      kkQty += kkQ;  kkAmt += d * kkQ;
    });
    document.getElementById('pec-kb-qty-total').textContent = kbQty.toLocaleString('id-ID');
    document.getElementById('pec-kb-total').textContent     = formatRupiah(kbAmt);
    document.getElementById('pec-kk-qty-total').textContent = kkQty.toLocaleString('id-ID');
    document.getElementById('pec-kk-total').textContent     = formatRupiah(kkAmt);
    return { kbAmt, kkAmt };
  }

  function pemSetSelisih(elId, selisih) {
    const el = document.getElementById(elId);
    el.textContent = formatRupiah(Math.abs(selisih)) + (selisih === 0 ? ' ✓' : ' ✗');
    el.className   = selisih === 0 ? 'selisih-ok' : 'selisih-err';
  }

  function pemRecalcAll() {
    const { kbAmt: fisikKB, kkAmt: fisikKK } = pemRecalcPecahan();

    // Kas Besar
    const saldoAwal       = parseInt(document.getElementById('kasBesarSaldoAwal').value) || 0;
    const totalPenerimaan = pemSumRows(document.getElementById('penerimaanBody'));
    const totalPengeluaran = pemSumRows(document.getElementById('pengeluaranBody'));
    const saldoBukuKB     = saldoAwal + totalPenerimaan - totalPengeluaran;

    document.getElementById('disp-kb-saldo-awal').textContent  = formatRupiah(saldoAwal);
    document.getElementById('disp-kb-penerimaan').textContent  = formatRupiah(totalPenerimaan);
    document.getElementById('disp-kb-pengeluaran').textContent = formatRupiah(totalPengeluaran);
    document.getElementById('disp-kb-saldo-buku').textContent  = formatRupiah(saldoBukuKB);
    document.getElementById('disp-kb-saldo-fisik').textContent = formatRupiah(fisikKB);
    pemSetSelisih('disp-kb-selisih', saldoBukuKB - fisikKB);

    // Kas Kecil
    const cadangan    = parseInt(document.getElementById('kasKecilCadangan').value) || 0;
    const totalBon    = pemSumRows(document.getElementById('bonGantungBody'));
    const saldoBukuKK = cadangan - totalBon;

    document.getElementById('disp-kk-cadangan').textContent    = formatRupiah(cadangan);
    document.getElementById('disp-kk-bon').textContent         = formatRupiah(totalBon);
    document.getElementById('disp-kk-saldo-buku').textContent  = formatRupiah(saldoBukuKK);
    document.getElementById('disp-kk-saldo-fisik').textContent = formatRupiah(fisikKK);
    pemSetSelisih('disp-kk-selisih', saldoBukuKK - fisikKK);
  }

  // Initialise
  try {
    buildPecahanTable();
    createTransaksiRow(document.getElementById('penerimaanBody'),  pemRecalcAll);
    createTransaksiRow(document.getElementById('pengeluaranBody'), pemRecalcAll);
    createTransaksiRow(document.getElementById('bonGantungBody'),  pemRecalcAll);
    createBlankoRow(document.getElementById('blankoH1Body'));
    createBlankoRow(document.getElementById('blankoH2Body'));

    document.getElementById('addPenerimaan').addEventListener('click', () =>
      createTransaksiRow(document.getElementById('penerimaanBody'), pemRecalcAll));
    document.getElementById('addPengeluaran').addEventListener('click', () =>
      createTransaksiRow(document.getElementById('pengeluaranBody'), pemRecalcAll));
    document.getElementById('addBonGantung').addEventListener('click', () =>
      createTransaksiRow(document.getElementById('bonGantungBody'), pemRecalcAll));
    document.getElementById('addBlankoH1').addEventListener('click', () =>
      createBlankoRow(document.getElementById('blankoH1Body')));
    document.getElementById('addBlankoH2').addEventListener('click', () =>
      createBlankoRow(document.getElementById('blankoH2Body')));

    document.getElementById('kasBesarSaldoAwal').addEventListener('input', pemRecalcAll);
    document.getElementById('kasKecilCadangan').addEventListener('input', pemRecalcAll);

    // Cetak
    document.getElementById('btnCetakPem').addEventListener('click', () => {
      const nama = document.getElementById('namaAuditee').value.trim();
      if (!nama) { showToast('Isi nama auditee terlebih dahulu.', 'error'); return; }
      window.print();
    });

    // Reset form
    document.getElementById('btnResetPem').addEventListener('click', () => {
      if (!confirm('Reset seluruh form Pemeriksaan Kas?')) return;
      document.getElementById('namaAuditee').value      = '';
      document.getElementById('tglPemeriksaan').value   = PEM_TODAY;
      document.getElementById('kasBesarTanggalAwal').value = PEM_TODAY;
      document.getElementById('kasBesarSaldoAwal').value = '0';
      document.getElementById('kasKecilCadangan').value = '0';
      document.getElementById('kasBesarKet').value      = '';
      document.getElementById('kasKecilKet').value      = '';
      ['penerimaanBody','pengeluaranBody','bonGantungBody'].forEach(id => {
        const tbody = document.getElementById(id);
        tbody.innerHTML = '';
        createTransaksiRow(tbody, pemRecalcAll);
      });
      ['blankoH1Body','blankoH2Body'].forEach(id => {
        const container = document.getElementById(id);
        container.innerHTML = '';
        createBlankoRow(container);
      });
      document.querySelectorAll('.pec-kb, .pec-kk').forEach(inp => { inp.value = '0'; });
      pemRecalcAll();
      showToast('Form Pemeriksaan Kas direset.', 'info');
    });

    pemRecalcAll();
  } catch(e) { console.error('[init] pem-kas module:', e); }

  /* ============================================================
     MODUL PEMERIKSAAN SMH
     ============================================================ */
  const SMH_HARGA_KEY     = 'akta_smh_harga';
  const SMH_PLAFON_KEY    = 'akta_smh_plafon';
  const SMH_ONHAND_KEY    = 'akta_smh_onhand';
  const SMH_PERL_KEY      = 'akta_smh_perlengkapan';
  const SMH_HASIL_KEY     = 'akta_smh_hasil';
  const SMH_UNIT_AREA_KEY    = 'akta_smh_unit_area';
  const DASH_CHART_VALS_KEY  = 'akta_dash_chart_vals';
  const DASH_UNIT_VALS_KEY   = 'akta_dash_unit_vals';
  const SMH_LUAR_KEY      = 'akta_smh_luar_fisik';

  // ── Grading ──────────────────────────────────────────────
  const GRADING_DB_KEY       = 'akta_grading_db';
  const GRADING_SESSIONS_KEY = 'akta_grading_sessions';
  function loadGradingDb()        { try { return JSON.parse(localStorage.getItem(GRADING_DB_KEY))       || []; } catch { return []; } }
  function saveGradingDb(d)       { localStorage.setItem(GRADING_DB_KEY, JSON.stringify(d));       window.API?.sync(GRADING_DB_KEY, d); }
  function loadGradingSessions()  { try { return JSON.parse(localStorage.getItem(GRADING_SESSIONS_KEY)) || []; } catch { return []; } }
  function saveGradingSessions(d) { localStorage.setItem(GRADING_SESSIONS_KEY, JSON.stringify(d)); window.API?.sync(GRADING_SESSIONS_KEY, d); }

  function loadSmhData(key)       { try { return JSON.parse(localStorage.getItem(key)) || []; } catch { return []; } }
  function saveSmhData(key, data) {
    localStorage.setItem(key, JSON.stringify(data));
    window.API?.sync(key, data);
  }
  // Buat key unik per plan agar data tiap plan tidak saling menimpa
  function _onhandKey(planId) {
    return planId ? SMH_ONHAND_KEY + '_' + planId : SMH_ONHAND_KEY;
  }

  // Load onhand untuk planId tertentu — setiap plan punya key sendiri
  function _loadOnhandForPlan(planId) {
    if (!planId) return [];
    try {
      const raw = localStorage.getItem(_onhandKey(planId));
      if (!raw) {
        // Coba migrate dari format lama (single key) jika planId cocok
        const legacyRaw = localStorage.getItem(SMH_ONHAND_KEY);
        if (!legacyRaw) return [];
        const legacy = JSON.parse(legacyRaw);
        if (legacy && !Array.isArray(legacy) && String(legacy.planId) === String(planId) && Array.isArray(legacy.data)) {
          // Pindahkan ke key baru, hapus yang lama
          localStorage.setItem(_onhandKey(planId), JSON.stringify(legacy.data));
          localStorage.removeItem(SMH_ONHAND_KEY);
          return legacy.data;
        }
        return [];
      }
      const stored = JSON.parse(raw);
      return Array.isArray(stored) ? stored : [];
    } catch { return []; }
  }

  // Simpan onhand per planId — setiap plan disimpan di key terpisah
  function _saveOnhandForPlan(planId, data) {
    if (!planId) return;
    const key = _onhandKey(planId);
    localStorage.setItem(key, JSON.stringify(data));
    window.API?.sync(key, data);
  }

  // Alias untuk kompatibilitas
  function _smhOnhandPlanKey() { return _auditContext?.planId ? _onhandKey(_auditContext.planId) : SMH_ONHAND_KEY; }

  let smhHarga    = loadSmhData(SMH_HARGA_KEY);
  let smhPlafon   = loadSmhData(SMH_PLAFON_KEY);
  let smhOnhand   = []; // diisi saat plan dibuka via _openAuditPemeriksaan
  let smhPerl     = loadSmhData(SMH_PERL_KEY);
  let smhHasil    = loadSmhData(SMH_HASIL_KEY);
  let smhUnitArea = loadSmhData(SMH_UNIT_AREA_KEY); // [{unitUsaha, area, jenis}]
  let smhLuarFisik = loadSmhData(SMH_LUAR_KEY);     // [{id, tgl, area, keterangan, items}]

  let currentPerlArea = 'SEMUA'; // state for perlengkapan area filter
  let currentScanArea = null;    // area of currently scanned unit

  // ── Render kartu INFORMASI (Auditor/Tanggal/Auditee) di section SMH ──
  function _renderSMHInfoCard(containerId) {
    const el = document.getElementById(containerId);
    if (!el) return;

    const today = new Date().toISOString().slice(0, 10);
    const fmtTgl = (s) => {
      if (!s) return '—';
      const d = new Date(s);
      return d.toLocaleDateString('id-ID', { day: '2-digit', month: 'long', year: 'numeric' });
    };

    // ── Nama Auditor: dari audit context → plan → timAudit ──────────────
    let auditorHTML = '';
    if (_auditContext?.planId) {
      const allP = loadPlans();
      const plan = allP.find(p => String(p.id) === String(_auditContext.planId));
      if (plan) {
        const allU    = getAllUsers();
        const timUsr  = (plan.timAudit || []).map(u => allU.find(x => x.username === u)).filter(Boolean);
        if (timUsr.length === 1) {
          auditorHTML = `<strong>${timUsr[0].displayName}</strong>`;
        } else if (timUsr.length > 1) {
          // Dropdown pilih auditor
          const opts = timUsr.map(u =>
            `<option value="${u.displayName}"${u.username === session.username ? ' selected' : ''}>${u.displayName}</option>`
          ).join('');
          auditorHTML = `<select class="kas-input" id="${containerId}_auditor" style="max-width:260px;padding:4px 8px;font-size:.84rem">
            <option value="">— Pilih Auditor —</option>${opts}</select>`;
        }
      }
    }
    if (!auditorHTML) {
      auditorHTML = `<strong>${session.displayName}</strong>
        <span style="font-size:.72rem;color:var(--text-secondary);margin-left:5px">(${ROLE_LABELS[session.role] || session.role})</span>`;
    }

    // ── Nama Auditee: dari role kasir yang unit usahanya cocok ──────────
    const cabang   = _auditContext?.cabang || session.unitUsaha || '';
    const normUU   = (s) => (s || '').trim().toLowerCase();
    const allU2    = getAllUsers();
    const kasirUsr = allU2.find(u => u.role === 'kasir' && normUU(u.unitUsaha) === normUU(cabang));
    const auditeeNama = kasirUsr ? kasirUsr.displayName : (cabang || session.displayName || '—');

    // ── Tanggal ──────────────────────────────────────────────────────────
    const tglDisplay = fmtTgl(today);
    const unitBadge  = cabang
      ? `<span style="background:#dbeafe;color:#1e40af;padding:2px 10px;border-radius:12px;font-size:.78rem;font-weight:600">${cabang}</span>`
      : '';

    el.innerHTML = `
      <div class="pem-card" style="margin-bottom:14px">
        <div class="pem-card-header">
          <span class="pem-icon-info">i</span>
          INFORMASI
          ${unitBadge ? `<span style="margin-left:8px">${unitBadge}</span>` : ''}
        </div>
        <div class="pem-card-body">
          <div class="pem-row-2col">
            <div class="field-group">
              <label class="pem-label">NAMA AUDITOR</label>
              <div style="padding:8px 12px;background:#f8fafc;border:1px solid var(--border);border-radius:8px;min-height:38px;display:flex;align-items:center">
                ${auditorHTML}
              </div>
            </div>
            <div class="field-group">
              <label class="pem-label">TANGGAL PEMERIKSAAN</label>
              <div style="padding:8px 12px;background:#f8fafc;border:1px solid var(--border);border-radius:8px;font-weight:600">
                ${tglDisplay}
              </div>
            </div>
          </div>
          <div class="field-group" style="margin-top:8px">
            <label class="pem-label">NAMA AUDITEE (KASIR)</label>
            <div style="padding:8px 12px;background:#f8fafc;border:1px solid var(--border);border-radius:8px;display:flex;align-items:center;gap:8px">
              <strong>${auditeeNama}</strong>
              ${kasirUsr ? `<span style="background:#dcfce7;color:#166534;font-size:.72rem;padding:1px 8px;border-radius:10px;font-weight:600">Kasir</span>` : '<span style="color:var(--gray-400);font-size:.78rem">— role kasir tidak ditemukan untuk unit ini</span>'}
            </div>
          </div>
        </div>
      </div>`;
  }

  // ── Luar-fisik context tracker ───────────────────────────────────────
  // Saat modal luarFisikModal aktif, _luarFormContainer menunjuk ke modal
  // sehingga getElementById tidak salah ambil elemen standalone section
  let _luarFormContainer = null;
  function _luarEl(id) {
    return _luarFormContainer
      ? _luarFormContainer.querySelector('#' + id)
      : document.getElementById(id);
  }

  function getUnitArea(kodeUnitUsaha) {
    if (!kodeUnitUsaha) return null;
    const m = smhUnitArea.find(m => m.unitUsaha === toStr(kodeUnitUsaha).trim());
    return m ? m.area : null;
  }
  function areaBadge(area) {
    if (!area) return '—';
    const cls = area.toLowerCase();
    return `<span class="badge-area ${['aceh','riau','kepri'].includes(cls) ? cls : 'other'}">${area}</span>`;
  }

  /* ── Excel/CSV parser via SheetJS ── */
  function parseExcelBuffer(buffer) {
    const workbook  = XLSX.read(new Uint8Array(buffer), { type: 'array', cellDates: true });
    const sheet     = workbook.Sheets[workbook.SheetNames[0]];
    return XLSX.utils.sheet_to_json(sheet, { defval: '' });
  }

  function toNum(val) {
    if (typeof val === 'number') return Math.round(val);
    return parseInt(String(val || '0').replace(/[^0-9]/g, '')) || 0;
  }
  function toStr(val) { return String(val == null ? '' : val).trim(); }

  /* ── SMH tab switching (scoped per section) ── */
  document.querySelectorAll('.smh-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      const section = tab.closest('.content-section');
      section.querySelectorAll('.smh-tab').forEach(t => t.classList.remove('active'));
      section.querySelectorAll('.smh-tab-content').forEach(c => c.classList.add('hidden'));
      tab.classList.add('active');
      const prefix = tab.closest('[data-tab-prefix]')?.dataset.tabPrefix || 'smhTab-';
      document.getElementById(prefix + tab.dataset.tab)?.classList.remove('hidden');
      const t = tab.dataset.tab;
      if (t === 'analisis') {
        renderSmhAnalisis();
        _renderSMHInfoCard('smhPlafonInfoCard');
      }
      if (t === 'perlengkapan') renderSmhPerl();
      if (t === 'unit-usaha')   renderUnitUsaha();
      if (t === 'grading')      renderGradingDbTab();
      if (t === 'mt')           _renderMtDbContent('baru');
      if (t === 'het')          window._hetDbRender?.();
      if (t === 'scan') {
        renderSmhHasil();
        renderLuarFisik();
        populateOnhandDropdown();
        populateLuarAreaOptions();
        _renderSMHInfoCard('smhScanInfoCard');
        _renderSMHInfoCard('smhLuarInfoCard');
        // Default dates to today
        const today = new Date().toISOString().slice(0, 10);
        const tglEl = document.getElementById('smhScanTgl');
        if (tglEl && !tglEl.value) tglEl.value = today;
        const luarTglEl = document.getElementById('luarTgl');
        if (luarTglEl && !luarTglEl.value) luarTglEl.value = today;
        setTimeout(() => document.getElementById('smhScanInput').focus(), 50);
      }
    });
  });

  /* ── Role-based import visibility ── */
  function applyImportPerm(canImport, wrapId, noPermitId) {
    if (canImport) {
      document.getElementById(noPermitId).classList.add('hidden');
    } else {
      document.getElementById(wrapId).style.display = 'none';
      document.getElementById(noPermitId).classList.remove('hidden');
    }
  }
  function setupSmhPermissions() {
    applyImportPerm(can('import-harga-smh'),    'smhHargaImportWrap',  'smhHargaNoPermit');
    applyImportPerm(can('import-plafon'),        'smhPlafonImportWrap', 'smhPlafonNoPermit');
    applyImportPerm(can('import-onhand'),        'smhOnhandImportWrap', 'smhOnhandNoPermit');
    applyImportPerm(can('import-perlengkapan'),  'smhPerlImportWrap',   'smhPerlNoPermit');
    applyImportPerm(can('import-unit-usaha'),    'smhUUImportWrap',     'smhUUNoPermit');
  }

  /* ── Generic file import setup ── */
  function setupFileImport(dropZoneId, fileInputId, browseId, processFn) {
    const dropZone  = document.getElementById(dropZoneId);
    const fileInput = document.getElementById(fileInputId);
    const browse    = document.getElementById(browseId);
    if (!dropZone || !fileInput) return;
    browse.addEventListener('click', (e) => { e.stopPropagation(); fileInput.click(); });
    dropZone.addEventListener('click', () => fileInput.click());
    dropZone.addEventListener('dragover', (e) => { e.preventDefault(); dropZone.classList.add('drag-over'); });
    dropZone.addEventListener('dragleave', () => dropZone.classList.remove('drag-over'));
    dropZone.addEventListener('drop', (e) => {
      e.preventDefault(); dropZone.classList.remove('drag-over');
      if (e.dataTransfer.files[0]) processFn(e.dataTransfer.files[0]);
    });
    fileInput.addEventListener('change', () => {
      if (fileInput.files[0]) { processFn(fileInput.files[0]); fileInput.value = ''; }
    });
  }

  /* ── HARGA SMH ── */
  function processHargaFile(file) {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const rows = parseExcelBuffer(e.target.result);
        smhHarga = rows.map(r => ({
          kodeModel: toStr(r['Kode Model']),
          namaSMH:   toStr(r['Nama SMH']),
          harga:     toNum(r['Harga (Rp)'] ?? r['Harga']),
        })).filter(r => r.kodeModel);
        saveSmhData(SMH_HARGA_KEY, smhHarga);
        renderSmhHarga();
        showToast(`${smhHarga.length} data Harga SMH berhasil diimport.`, 'success');
      } catch (err) {
        showToast('Format file tidak valid. Pastikan file Excel/CSV sesuai.', 'error');
      }
    };
    reader.onerror = () => showToast('Gagal membaca file.', 'error');
    reader.readAsArrayBuffer(file);
  }

  function renderSmhHarga() {
    const tbody = document.getElementById('smhHargaTableBody');
    const stat  = document.getElementById('smhHargaStat');
    if (smhHarga.length === 0) {
      tbody.innerHTML = `<tr><td colspan="4"><div class="empty-state"><svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 000 7h5a3.5 3.5 0 010 7H6"/></svg><p>Belum ada data harga SMH. Import file CSV untuk memulai.</p></div></td></tr>`;
      if (stat) stat.innerHTML = 'Belum ada data';
      return;
    }
    if (stat) stat.innerHTML = `<strong>${smhHarga.length}</strong> model`;
    tbody.innerHTML = smhHarga.map((r, i) => `<tr>
      <td>${i + 1}</td>
      <td><strong>${r.kodeModel}</strong></td>
      <td>${r.namaSMH}</td>
      <td class="saldo-cell">${formatRupiah(r.harga)}</td>
    </tr>`).join('');
  }

  /* ── PLAFON ── */
  function processPlafonFile(file) {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const rows = parseExcelBuffer(e.target.result);
        smhPlafon = rows.map(r => ({
          kodeUnitUsaha: toStr(r['Kode Unit Usaha']),
          daerah:        toStr(r['Daerah']),
          plafon:        toNum(r['Plafon (Rp)'] ?? r['Plafon']),
        })).filter(r => r.kodeUnitUsaha);
        saveSmhData(SMH_PLAFON_KEY, smhPlafon);
        renderSmhPlafon();
        showToast(`${smhPlafon.length} data Plafon berhasil diimport.`, 'success');
      } catch (err) {
        showToast('Format file tidak valid. Pastikan file Excel/CSV sesuai.', 'error');
      }
    };
    reader.onerror = () => showToast('Gagal membaca file.', 'error');
    reader.readAsArrayBuffer(file);
  }

  function renderSmhPlafon() {
    const tbody = document.getElementById('smhPlafonTableBody');
    const stat  = document.getElementById('smhPlafonStat');
    if (smhPlafon.length === 0) {
      tbody.innerHTML = `<tr><td colspan="4"><div class="empty-state"><svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z"/></svg><p>Belum ada data plafon. Import file CSV untuk memulai.</p></div></td></tr>`;
      if (stat) stat.innerHTML = 'Belum ada data';
      return;
    }
    if (stat) stat.innerHTML = `<strong>${smhPlafon.length}</strong> unit usaha`;
    tbody.innerHTML = smhPlafon.map((r, i) => `<tr>
      <td>${i + 1}</td>
      <td><strong>${r.kodeUnitUsaha}</strong></td>
      <td>${r.daerah}</td>
      <td class="saldo-cell">${formatRupiah(r.plafon)}</td>
    </tr>`).join('');
  }

  /* ── ONHAND — smart parser for Laporan Unit On Hand format ── */
  function processOnhandFile(file) {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const workbook = XLSX.read(new Uint8Array(e.target.result), {
          type: 'array', cellDates: true, raw: false,
        });
        const sheet   = workbook.Sheets[workbook.SheetNames[0]];
        // Read all rows as raw string arrays — preserves complex layout
        const allRows = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: '' })
                          .map(row => row.map(c => String(c == null ? '' : c).trim()));

        /* --- Step 1: locate the column-header row (contains "No.Mesin") --- */
        let cols = { mesin: 1, rangka: 2, sel: 4, noSPB: 5, tglSPB: 6,
                     noShip: 7, tglShip: 8, dO: 9, model: 10, warna: 11,
                     gudang: -1 };  // -1 = not found yet

        for (let i = 0; i < Math.min(allRows.length, 25); i++) {
          const flat = allRows[i].join('|').toLowerCase();
          if (flat.includes('mesin')) {
            allRows[i].forEach((h, j) => {
              const raw = h.toLowerCase();
              const lh  = raw.replace(/[\s.\/\-_()']/g, '');
              if (lh.includes('mesin'))                              cols.mesin  = j;
              if (lh.includes('rangka'))                             cols.rangka = j;
              if (lh === 'sel')                                      cols.sel    = j;
              if (lh === 'nospb' || raw.includes('no.spb') || raw.includes('no spb'))
                                                                     cols.noSPB  = j;
              if (lh === 'tglspb' || raw.includes('tgl.spb') || raw.includes('tgl spb'))
                                                                     cols.tglSPB = j;
              if (lh === 'noshiplist' || lh === 'noshiplis')        cols.noShip = j;
              if (lh === 'tglshiplist' || lh === 'tglshiplis')      cols.tglShip = j;
              if (lh === 'nodo' || raw.includes('no.do') || raw.includes('no do'))
                                                                     cols.dO     = j;
              if (lh === 'model')                                    cols.model  = j;
              if (lh === 'warna' || lh === 'wrn' || lh === 'color') cols.warna  = j;
              // Kolom Gudang/Lokasi — banyak variasi nama
              if (
                lh.includes('gudang') ||
                lh === 'lokasi' || lh === 'lokasiunit' || lh === 'lokasiunitmotor' ||
                lh === 'namalokasi' || lh === 'kodegudang' || lh === 'namagudang' ||
                lh === 'warehouse' || lh === 'location' || lh === 'storagelocation' ||
                lh === 'lokasimotor' || lh === 'tempatpenyimpanan'
              ) {
                cols.gudang = j;
              }
            });
            break;
          }
        }

        /* --- Step 2: walk every row, track context, collect data rows --- */
        const units = [];
        let currentModel    = '';
        let currentWarna    = '';
        let currentUnitUsaha = '';  // Dibaca dari metadata "Kode Unit Usaha"

        allRows.forEach(row => {
          const firstCell = row[0] || '';
          const allText   = row.join(' ').toLowerCase();

          // Metadata: "Kode Unit Usaha" (e.g. "CDN-TPP")
          if (allText.includes('kode unit usaha')) {
            const idx = row.findIndex(c => c.toLowerCase().includes('kode unit usaha'));
            if (idx >= 0) {
              currentUnitUsaha = row.slice(idx + 1).find(c => c !== '') || '';
              currentUnitUsaha = currentUnitUsaha.replace(/^[:\s]+/, '').trim();
            }
            return;
          }

          // Metadata: "Kode Model Intern"
          if (allText.includes('kode model intern')) {
            const idx = row.findIndex(c => c.toLowerCase().includes('kode model intern'));
            if (idx >= 0) {
              currentModel = row.slice(idx + 1).find(c => c !== '') || '';
              // Trim trailing colon/space artefacts
              currentModel = currentModel.replace(/^[:\s]+/, '').trim();
            }
            return;
          }

          // Metadata: "Kode Warna Intern"
          if (allText.includes('kode warna intern')) {
            const idx = row.findIndex(c => c.toLowerCase().includes('kode warna intern'));
            if (idx >= 0) {
              currentWarna = row.slice(idx + 1).find(c => c !== '') || '';
              currentWarna = currentWarna.replace(/^[:\s]+/, '').trim();
            }
            return;
          }

          // Skip header / sub-total / title rows
          if (allText.includes('sub total') || allText.includes('laporan') ||
              firstCell.toLowerCase() === 'no.' || firstCell.toLowerCase() === 'no') return;

          // Data row: first cell is a positive integer (sequential no.)
          if (/^\d+$/.test(firstCell) && parseInt(firstCell) > 0) {
            units.push({
              kodeUnitUsaha:   currentUnitUsaha,
              kodeModelIntern: currentModel,
              kodeWarnaIntern: currentWarna,
              noMesin:    row[cols.mesin]  || '',
              noRangka:   row[cols.rangka] || '',
              sel:        row[cols.sel]    || '',
              noSPB:      row[cols.noSPB]  || '',
              tglSPB:     row[cols.tglSPB] || '',
              noShipList: row[cols.noShip] || '',
              tglShipList:row[cols.tglShip]|| '',
              noDO:       row[cols.dO]     || '',
              model:      row[cols.model]  || '',
              warna:      row[cols.warna]  || '',
              // Kolom gudang/lokasi (jika ada di file)
              gudang:     cols.gudang >= 0 ? (row[cols.gudang] || '') : '',
            });
          }
        });

        if (units.length === 0) {
          showToast('Tidak ada data unit yang terbaca. Pastikan format file sesuai Laporan Unit On Hand.', 'error');
          return;
        }
        smhOnhand = units;
        _saveOnhandForPlan(_auditContext?.planId, smhOnhand);
        renderSmhOnhand();
        populateOnhandDropdown();
        showToast(`${smhOnhand.length} unit berhasil diimport.`, 'success');
      } catch (err) {
        console.error('Onhand import error:', err);
        showToast('Gagal membaca file. Periksa format Excel.', 'error');
      }
    };
    reader.onerror = () => showToast('Gagal membaca file.', 'error');
    reader.readAsArrayBuffer(file);
  }

  function renderSmhOnhand() {
    const container = document.getElementById('smhOnhandContainer');
    const stat      = document.getElementById('smhOnhandStat');
    if (smhOnhand.length === 0) {
      container.innerHTML = `<div class="empty-state"><svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="2" y="3" width="6" height="18" rx="1"/><rect x="9" y="8" width="6" height="13" rx="1"/><rect x="16" y="5" width="6" height="16" rx="1"/></svg><p>Belum ada data onhand. Import file CSV untuk memulai.</p></div>`;
      if (stat) stat.innerHTML = 'Belum ada data';
      return;
    }
    if (stat) stat.innerHTML = `<strong>${smhOnhand.length}</strong> unit`;

    // Group by kodeModelIntern → kodeWarnaIntern
    const modelGroups = {};
    smhOnhand.forEach(u => {
      const m = u.kodeModelIntern || '—';
      const w = u.kodeWarnaIntern || '—';
      if (!modelGroups[m]) modelGroups[m] = {};
      if (!modelGroups[m][w]) modelGroups[m][w] = [];
      modelGroups[m][w].push(u);
    });

    let html = '';
    let no   = 0;

    Object.entries(modelGroups).forEach(([model, warnaGroups]) => {
      const modelTotal = Object.values(warnaGroups).reduce((s, arr) => s + arr.length, 0);
      html += `<div class="onhand-model-group">
        <div class="onhand-model-hdr">
          <span>Kode Model Intern: <strong>${model}</strong></span>
          <span>Total: <strong>${modelTotal} Unit</strong></span>
        </div>`;

      Object.entries(warnaGroups).forEach(([warna, units]) => {
        html += `<div class="onhand-warna-group">
          <div class="onhand-warna-hdr">
            <span>Kode Warna Intern: <strong>${warna}</strong></span>
            <span>${units.length} Unit</span>
          </div>
          <div class="table-wrapper">
            <table class="kas-table" style="font-size:.8rem">
              <thead><tr>
                <th>No</th><th>No.Mesin</th><th>No.Rangka</th>
                <th style="background:#dbeafe;color:#1e40af;min-width:90px">Gudang/Lokasi</th>
                <th>Sel</th>
                <th>No.SPB</th><th>Tgl.SPB</th><th>No.ShipList</th><th>Tgl.ShipList</th>
                <th>No.DO</th><th>Model</th><th>Warna</th>
              </tr></thead>
              <tbody>`;
        units.forEach(u => {
          no++;
          html += `<tr>
            <td>${no}</td>
            <td style="white-space:nowrap">${u.noMesin}</td>
            <td style="white-space:nowrap">${u.noRangka}</td>
            <td style="white-space:nowrap;font-weight:600;color:#1e40af;background:#eff6ff">${u.gudang || '—'}</td>
            <td>${u.sel}</td>
            <td style="white-space:nowrap">${u.noSPB}</td>
            <td style="white-space:nowrap">${u.tglSPB}</td>
            <td style="white-space:nowrap">${u.noShipList}</td>
            <td style="white-space:nowrap">${u.tglShipList}</td>
            <td style="white-space:nowrap">${u.noDO}</td>
            <td>${u.model}</td>
            <td>${u.warna}</td>
          </tr>`;
        });
        html += `</tbody></table></div>
          <div class="onhand-sub-total">
            <span>Sub Total Warna: <strong>${warna}</strong></span>
            <span><strong>${units.length} Unit</strong></span>
          </div>
        </div>`;
      });

      html += `<div class="onhand-model-total">
        <span>Sub Total Model: ${model}</span>
        <span>${modelTotal} Unit</span>
      </div></div>`;
    });

    container.innerHTML = html;
  }

  /* ── PLAFON SMH ── */
  function renderSmhAnalisis() {
    // Reload data terkini
    smhHarga  = loadSmhData(SMH_HARGA_KEY);
    smhPlafon = loadSmhData(SMH_PLAFON_KEY);

    // ── Helpers ──────────────────────────────────────────────────────────
    // Normalisasi kode (hapus spasi, slash, dash, underscore)
    const normKode = s => (s || '').replace(/[\s\/\-_]/g, '').toUpperCase();

    // 3 huruf terakhir dari kode unit usaha (untuk matching plafon)
    const last3 = s => (s || '').replace(/[\s\-_]/g, '').toUpperCase().slice(-3);

    // Cari harga SMH: match kolom "model" dari onhand terhadap kodeModel di smhHarga
    // Urutan prioritas: exact → normalized → namaSMH exact → namaSMH normalized
    function findHarga(modelName, kodeIntern) {
      if (!smhHarga.length) return null;
      const nModel  = normKode(modelName);
      const nIntern = normKode(kodeIntern);
      return smhHarga.find(h => h.kodeModel === modelName)
          || smhHarga.find(h => normKode(h.kodeModel) === nModel)
          || smhHarga.find(h => (h.namaSMH || '') === modelName)
          || smhHarga.find(h => normKode(h.namaSMH) === nModel)
          || (kodeIntern && (
               smhHarga.find(h => h.kodeModel === kodeIntern)
            || smhHarga.find(h => normKode(h.kodeModel) === nIntern)
          )) || null;
    }

    // ── A. Hitung nilai onhand per model (kolom "model" dari baris data) ─
    // Kolom "model" = nama komersial (misal "VARIO 125"), digunakan untuk
    // matching harga. kodeModelIntern = kode internal dari metadata file.
    const modelQty      = {};  // modelName → qty
    const modelInternMap = {}; // modelName → kodeModelIntern (untuk referensi)

    smhOnhand.forEach(u => {
      // Prioritaskan kolom "model" (nama komersial), fallback ke kodeModelIntern
      const m = (u.model || u.kodeModelIntern || '').trim() || '—';
      modelQty[m] = (modelQty[m] || 0) + 1;
      if (u.kodeModelIntern && !modelInternMap[m]) modelInternMap[m] = u.kodeModelIntern;
    });

    let totalQty = 0, totalNilaiOH = 0;
    const modelRows = [];

    Object.entries(modelQty).sort((a, b) => a[0].localeCompare(b[0])).forEach(([model, qty], i) => {
      const hData  = findHarga(model, modelInternMap[model]);
      const harga  = hData ? hData.harga  : 0;
      const nama   = hData ? hData.namaSMH : '';
      const nilai  = harga * qty;
      totalQty     += qty;
      totalNilaiOH += nilai;

      const hargaTxt = harga
        ? formatRupiah(harga)
        : `<span style="color:var(--gray-400);font-style:italic;font-size:.8rem">Belum ada</span>`;
      const nilaiTxt = nilai
        ? `<strong>${formatRupiah(nilai)}</strong>`
        : `<span style="color:var(--gray-400)">—</span>`;
      const internTxt = modelInternMap[model]
        ? `<span style="font-size:.72rem;color:var(--text-secondary)">${modelInternMap[model]}</span>`
        : '';

      modelRows.push(`<tr>
        <td>${i + 1}</td>
        <td><strong>${model}</strong><br>${internTxt}</td>
        <td style="color:var(--text-secondary)">${nama || '<span style="color:var(--gray-400);font-style:italic">—</span>'}</td>
        <td style="text-align:center;font-weight:700;color:var(--primary)">${qty}</td>
        <td class="saldo-cell">${hargaTxt}</td>
        <td class="saldo-cell">${nilaiTxt}</td>
      </tr>`);
    });

    const modelBodyEl = document.getElementById('smhAnalisisModelBody');
    if (modelRows.length === 0) {
      modelBodyEl.innerHTML = `<tr><td colspan="6"><div class="empty-state"><p>Belum ada data onhand.</p></div></td></tr>`;
    } else {
      modelRows.push(`<tr style="background:#eef2ff;font-weight:700;border-top:2px solid #818cf8">
        <td colspan="3" style="text-align:right;padding-right:16px;color:var(--gray-700);font-size:.85rem;letter-spacing:.04em">TOTAL KESELURUHAN</td>
        <td style="text-align:center;color:var(--primary);font-size:1rem">${totalQty}</td>
        <td></td>
        <td class="saldo-cell" style="font-size:1rem;color:var(--primary)">${formatRupiah(totalNilaiOH)}</td>
      </tr>`);
      modelBodyEl.innerHTML = modelRows.join('');
    }

    // ── B. Total nilai onhand per unit usaha (last-3 matching) ───────────
    // Gunakan kolom "model" untuk hitung harga per unit, group by last3(kodeUnitUsaha)
    const unitNilaiMap = {};  // last3(kodeUnitUsaha) → total nilai SMH
    const unitKodeMap  = {};  // last3 → kodeUnitUsaha asli onhand
    smhOnhand.forEach(u => {
      const key    = last3(u.kodeUnitUsaha);
      const mName  = (u.model || u.kodeModelIntern || '').trim();
      const hData  = findHarga(mName, u.kodeModelIntern);
      const harga  = hData ? hData.harga : 0;
      if (key) {
        unitNilaiMap[key] = (unitNilaiMap[key] || 0) + harga;
        if (!unitKodeMap[key]) unitKodeMap[key] = u.kodeUnitUsaha;
      }
    });

    // Fallback: jika kodeUnitUsaha kosong di semua onhand, assign ke audit context
    const hasUUData   = Object.keys(unitNilaiMap).length > 0;
    const auditCabang = (_auditContext?.cabang || session.unitUsaha || '').trim();

    // ── Plafon relevan: hanya unit yang benar-benar match onhand (last-3) ──
    // Rumus: totalNilaiOH vs plafon_unit_yang_sesuai (bukan semua plafon)
    let relevantPlafon = 0;
    const matchedPlafonLabels = []; // untuk keterangan di banner

    if (hasUUData) {
      // Match kunci last3 dari onhand ke smhPlafon
      smhPlafon.forEach(p => {
        if (unitNilaiMap[last3(p.kodeUnitUsaha)] !== undefined) {
          relevantPlafon += (p.plafon || 0);
          matchedPlafonLabels.push(p.kodeUnitUsaha);
        }
      });
    }
    if (!relevantPlafon && auditCabang) {
      // Fallback via audit context last-3
      const ctxKey = last3(auditCabang);
      smhPlafon.forEach(p => {
        if (last3(p.kodeUnitUsaha) === ctxKey) {
          relevantPlafon += (p.plafon || 0);
          matchedPlafonLabels.push(p.kodeUnitUsaha);
        }
      });
    }
    if (!relevantPlafon && smhPlafon.length === 1) {
      // Fallback terakhir: satu plafon saja
      relevantPlafon = smhPlafon[0].plafon || 0;
      matchedPlafonLabels.push(smhPlafon[0].kodeUnitUsaha);
    }

    const plafonBodyEl = document.getElementById('smhAnalisisPlafonBody');

    if (smhPlafon.length === 0) {
      plafonBodyEl.innerHTML = `<tr><td colspan="8"><div class="empty-state"><p>Belum ada data plafon. Import data plafon di tab Database.</p></div></td></tr>`;
    } else {
      let grandPlafon = 0, grandNilai = 0;
      let rowNo = 0;
      const diagramData = [];

      // Hanya render baris yang punya nilai onhand (hapus baris tanpa data)
      const plafonRows = smhPlafon.map(p => {
        const key3 = last3(p.kodeUnitUsaha);

        let nilai = unitNilaiMap[key3] || 0;

        // Fallback jika onhand tidak punya kodeUnitUsaha
        if (!hasUUData && !nilai) {
          const isCtxMatch = auditCabang && last3(auditCabang) === key3;
          const isOnlyOne  = smhPlafon.length === 1;
          nilai = (isCtxMatch || isOnlyOne) ? totalNilaiOH : 0;
        }

        // ── Lewati baris yang tidak ada onhand-nya ──
        if (nilai <= 0) return null;

        rowNo++;
        const plafon    = p.plafon || 0;
        const selisih   = plafon - nilai;
        const utilisasi = plafon > 0 ? Math.round((nilai / plafon) * 100) : 0;

        grandPlafon += plafon;
        grandNilai  += nilai;

        diagramData.push({ label: p.kodeUnitUsaha, daerah: p.daerah || '—', nilai, plafon, utilisasi });

        const statusEl = selisih > 0
          ? `<span style="background:#dcfce7;color:#166534;padding:2px 10px;border-radius:12px;font-size:.78rem;font-weight:700">✓ Dalam Plafon</span>`
          : selisih < 0
            ? `<span style="background:#fee2e2;color:#991b1b;padding:2px 10px;border-radius:12px;font-size:.78rem;font-weight:700">⚠ Melewati Plafon</span>`
            : `<span style="background:#dbeafe;color:#1e40af;padding:2px 10px;border-radius:12px;font-size:.78rem;font-weight:700">= Tepat Plafon</span>`;

        const selCls    = selisih > 0 ? 'color:#16a34a' : selisih < 0 ? 'color:#dc2626' : 'color:#2563eb';
        const selisihEl = `<span style="${selCls};font-weight:700">${selisih >= 0 ? '' : '−'}${formatRupiah(Math.abs(selisih))}</span>`;

        const utilisasiBg  = utilisasi > 100 ? '#fee2e2' : utilisasi > 90 ? '#fef9c3' : '#f0fdf4';
        const utilisasiClr = utilisasi > 100 ? '#991b1b' : utilisasi > 90 ? '#854d0e' : '#166534';
        const utilisasiEl  = `<span style="background:${utilisasiBg};color:${utilisasiClr};padding:2px 8px;border-radius:10px;font-size:.8rem;font-weight:700">${utilisasi}%</span>`;

        const matchBadge = ` <span style="background:#ede9fe;color:#5b21b6;font-size:.66rem;padding:1px 6px;border-radius:8px;font-weight:600">${key3}</span>`;

        return `<tr>
          <td>${rowNo}</td>
          <td><strong>${p.kodeUnitUsaha}</strong>${matchBadge}</td>
          <td style="color:var(--text-secondary)">${p.daerah || '—'}</td>
          <td class="saldo-cell" style="font-weight:700">${formatRupiah(nilai)}</td>
          <td class="saldo-cell">${formatRupiah(plafon)}</td>
          <td>${selisihEl}</td>
          <td style="text-align:center">${utilisasiEl}</td>
          <td>${statusEl}</td>
        </tr>`;
      }).filter(Boolean); // hapus null (baris tanpa onhand)

      if (plafonRows.length === 0) {
        plafonBodyEl.innerHTML = `<tr><td colspan="8"><div class="empty-state"><p>Belum ada data onhand yang cocok dengan unit usaha di database plafon.<br><small>Pastikan 3 huruf terakhir kode unit usaha onhand dan plafon sama (contoh: CDN-<strong>TPP</strong> ↔ SO <strong>TPP</strong>).</small></p></div></td></tr>`;
      } else {
        const grandSelisih   = grandPlafon - grandNilai;
        const grandUtil      = grandPlafon > 0 ? Math.round((grandNilai / grandPlafon) * 100) : 0;
        const grandSelPrefix = grandSelisih >= 0 ? '' : '−';
        const grandSelClr    = grandSelisih > 0 ? '#16a34a' : grandSelisih < 0 ? '#dc2626' : '#2563eb';

        plafonRows.push(`<tr style="background:#eef2ff;font-weight:700;border-top:2px solid #818cf8">
          <td colspan="2" style="text-align:right;padding-right:12px;color:var(--gray-700);font-size:.85rem;letter-spacing:.04em">TOTAL (${rowNo} unit)</td>
          <td></td>
          <td class="saldo-cell" style="font-size:1rem;color:var(--primary)">${formatRupiah(grandNilai)}</td>
          <td class="saldo-cell" style="font-size:1rem">${formatRupiah(grandPlafon)}</td>
          <td class="saldo-cell" style="${grandSelClr};font-size:1rem">${grandSelPrefix}${formatRupiah(Math.abs(grandSelisih))}</td>
          <td style="text-align:center"><span style="font-weight:700;font-size:.9rem;color:${grandSelClr}">${grandUtil}%</span></td>
          <td></td>
        </tr>`);
        plafonBodyEl.innerHTML = plafonRows.join('');
      }

      // ── E. Diagram Utilisasi Plafon SMH ────────────────────────────────
      const diagEl = document.getElementById('smhPlafonDiagram');
      if (diagEl) {
        if (diagramData.length === 0) {
          diagEl.innerHTML = '';
        } else {
          // Urutkan descending by utilisasi
          diagramData.sort((a, b) => b.utilisasi - a.utilisasi);

          const maxUtil = Math.max(...diagramData.map(d => d.utilisasi), 100);
          const barItems = diagramData.map(d => {
            const pct     = Math.min(d.utilisasi, 100);  // bar capped 100% visually
            const overPct = d.utilisasi > 100 ? Math.min(d.utilisasi - 100, 50) : 0;
            const barClr  = d.utilisasi > 100 ? '#ef4444'
                          : d.utilisasi > 90  ? '#f59e0b'
                          : d.utilisasi > 70  ? '#3b82f6'
                          : '#22c55e';
            const overBar = overPct > 0
              ? `<div style="position:absolute;left:${pct}%;top:0;bottom:0;width:${overPct * 0.5}%;background:#dc2626;opacity:.7;border-radius:0 4px 4px 0"></div>`
              : '';
            const statDot = d.utilisasi > 100 ? '🔴' : d.utilisasi > 90 ? '🟡' : '🟢';
            return `
              <div style="display:flex;align-items:center;gap:10px;padding:6px 0;border-bottom:1px solid #f1f5f9">
                <div style="width:90px;flex-shrink:0;font-size:.8rem;font-weight:700;color:var(--text-primary);overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${d.label}">${d.label}</div>
                <div style="flex:1;position:relative;height:20px;background:#f1f5f9;border-radius:4px;overflow:hidden">
                  <div style="position:absolute;left:0;top:0;bottom:0;width:${pct}%;background:${barClr};border-radius:4px;transition:width .4s"></div>
                  ${overBar}
                  <div style="position:absolute;left:0;top:0;right:0;bottom:0;display:flex;align-items:center;padding:0 6px">
                    <span style="font-size:.72rem;font-weight:700;color:${pct > 40 ? '#fff' : '#374151'}">${d.utilisasi}%</span>
                  </div>
                </div>
                <div style="width:130px;flex-shrink:0;font-size:.75rem;color:var(--text-secondary);text-align:right">
                  ${formatRupiah(d.nilai)}<br>
                  <span style="font-size:.68rem;color:var(--gray-400)">/ ${formatRupiah(d.plafon)}</span>
                </div>
                <div style="width:20px;text-align:center;font-size:.85rem">${statDot}</div>
              </div>`;
          }).join('');

          // Legenda
          const legenda = `
            <div style="display:flex;gap:14px;flex-wrap:wrap;margin-top:12px;font-size:.75rem;color:var(--text-secondary)">
              <span><span style="display:inline-block;width:12px;height:12px;background:#22c55e;border-radius:2px;vertical-align:middle;margin-right:4px"></span>≤ 70%</span>
              <span><span style="display:inline-block;width:12px;height:12px;background:#3b82f6;border-radius:2px;vertical-align:middle;margin-right:4px"></span>71–90%</span>
              <span><span style="display:inline-block;width:12px;height:12px;background:#f59e0b;border-radius:2px;vertical-align:middle;margin-right:4px"></span>91–100%</span>
              <span><span style="display:inline-block;width:12px;height:12px;background:#ef4444;border-radius:2px;vertical-align:middle;margin-right:4px"></span>&gt; 100% (Melewati Plafon)</span>
            </div>`;

          diagEl.innerHTML = `
            <div class="pem-card" style="margin-top:16px;margin-bottom:4px">
              <div class="pem-card-header">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="18" y1="20" x2="18" y2="10"/><line x1="12" y1="20" x2="12" y2="4"/><line x1="6" y1="20" x2="6" y2="14"/></svg>
                DIAGRAM UTILISASI PLAFON SMH
                <span style="margin-left:auto;font-size:.75rem;font-weight:400;color:#a5b4fc">${diagramData.length} unit dengan onhand</span>
              </div>
              <div class="pem-card-body">
                ${barItems}
                ${legenda}
              </div>
            </div>`;
        }
      }
    }

    // ── C. Summary stat cards ─────────────────────────────────────────────
    // Gunakan relevantPlafon (hanya plafon unit yang match, bukan total semua)
    const sisaPlafon      = relevantPlafon - totalNilaiOH;
    const utilisasiGlobal = relevantPlafon > 0 ? Math.round((totalNilaiOH / relevantPlafon) * 100) : 0;
    const statusPlafon    = relevantPlafon === 0 ? 'Plafon Belum Tersinkron'
                          : sisaPlafon >= 0 ? 'Dalam Plafon' : 'Melewati Plafon';
    const statusColor     = relevantPlafon === 0 ? 'orange' : sisaPlafon >= 0 ? 'green' : 'red';

    document.getElementById('smhAnalisisSummary').innerHTML = `
      <div class="stat-card">
        <div class="stat-icon blue">
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2"/><rect x="9" y="3" width="6" height="4" rx="1"/><path d="M9 12l2 2 4-4"/></svg>
        </div>
        <div class="stat-info">
          <span class="stat-value">${smhOnhand.length.toLocaleString('id-ID')}</span>
          <span class="stat-label">Total Unit Onhand</span>
        </div>
      </div>
      <div class="stat-card">
        <div class="stat-icon green">
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="18" y1="20" x2="18" y2="10"/><line x1="12" y1="20" x2="12" y2="4"/><line x1="6" y1="20" x2="6" y2="14"/></svg>
        </div>
        <div class="stat-info">
          <span class="stat-value">${Object.keys(modelQty).length}</span>
          <span class="stat-label">Jenis Model</span>
        </div>
      </div>
      <div class="stat-card">
        <div class="stat-icon teal">
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 000 7h5a3.5 3.5 0 010 7H6"/></svg>
        </div>
        <div class="stat-info">
          <span class="stat-value">${formatRupiah(totalNilaiOH)}</span>
          <span class="stat-label">Total Nilai Onhand</span>
        </div>
      </div>
      <div class="stat-card">
        <div class="stat-icon ${statusColor}">
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>
        </div>
        <div class="stat-info">
          <span class="stat-value">${utilisasiGlobal}%</span>
          <span class="stat-label">Utilisasi Plafon · ${statusPlafon}</span>
        </div>
        <span class="stat-change ${sisaPlafon >= 0 ? 'up' : 'down'}">${sisaPlafon >= 0 ? '+' : ''}${formatRupiah(sisaPlafon)}</span>
      </div>`;

    // ── D. Plafon Banner (prominent) ──────────────────────────────────────
    const bannerEl = document.getElementById('smhPlafonBanner');
    if (!bannerEl) return;

    if (smhOnhand.length === 0 || smhPlafon.length === 0) {
      bannerEl.innerHTML = '';
      return;
    }

    // Warna banner berdasarkan status
    const bannerBg  = relevantPlafon === 0 ? '#fff7ed'
                    : sisaPlafon >= 0       ? '#f0fdf4' : '#fff1f2';
    const bannerBrd = relevantPlafon === 0 ? '#fed7aa'
                    : sisaPlafon >= 0       ? '#86efac' : '#fca5a5';
    const bannerClr = relevantPlafon === 0 ? '#9a3412'
                    : sisaPlafon >= 0       ? '#166534' : '#991b1b';
    const bannerIcon = relevantPlafon === 0
      ? `<svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="${bannerClr}" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>`
      : sisaPlafon >= 0
        ? `<svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="${bannerClr}" stroke-width="2"><path d="M22 11.08V12a10 10 0 11-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>`
        : `<svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="${bannerClr}" stroke-width="2"><path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>`;

    // Keterangan unit yang match (dari onhand → plafon via last-3)
    const matchInfo = matchedPlafonLabels.length > 0
      ? `<div style="font-size:.72rem;color:${bannerClr};opacity:.8;margin-top:3px">Plafon: ${matchedPlafonLabels.join(', ')}</div>`
      : `<div style="font-size:.72rem;color:${bannerClr};opacity:.8;margin-top:3px">Belum ada plafon yang tersinkron (3 huruf terakhir tidak cocok)</div>`;

    // Label plafon — tampilkan "(hanya unit yg match)" agar jelas
    const plafonLabel = matchedPlafonLabels.length > 0
      ? `Unit: ${matchedPlafonLabels.join(', ')}`
      : 'Plafon belum tersinkron';

    bannerEl.innerHTML = `
      <div style="background:${bannerBg};border:1.5px solid ${bannerBrd};border-radius:12px;padding:16px 20px;display:flex;align-items:center;gap:20px;flex-wrap:wrap;margin-bottom:4px">
        <div style="flex-shrink:0">${bannerIcon}</div>
        <div style="flex:1;min-width:160px">
          <div style="font-size:.78rem;font-weight:700;color:${bannerClr};letter-spacing:.05em;text-transform:uppercase;margin-bottom:2px">Status Plafon SMH</div>
          <div style="font-size:1.15rem;font-weight:800;color:${bannerClr}">${statusPlafon}</div>
          ${matchInfo}
        </div>
        <div style="display:flex;gap:24px;flex-wrap:wrap">
          <div style="text-align:center">
            <div style="font-size:.72rem;color:var(--text-secondary);font-weight:600;letter-spacing:.04em">NILAI ONHAND SMH</div>
            <div style="font-size:1rem;font-weight:800;color:var(--text-primary)">${formatRupiah(totalNilaiOH)}</div>
          </div>
          <div style="text-align:center">
            <div style="font-size:.72rem;color:var(--text-secondary);font-weight:600;letter-spacing:.04em">PLAFON${matchedPlafonLabels.length > 0 ? ' (' + matchedPlafonLabels.join('+') + ')' : ''}</div>
            <div style="font-size:1rem;font-weight:800;color:var(--text-primary)">${relevantPlafon > 0 ? formatRupiah(relevantPlafon) : '<span style="color:var(--gray-400);font-size:.85rem">Belum ada</span>'}</div>
          </div>
          <div style="text-align:center">
            <div style="font-size:.72rem;color:var(--text-secondary);font-weight:600;letter-spacing:.04em">SISA PLAFON</div>
            <div style="font-size:1rem;font-weight:800;color:${bannerClr}">${relevantPlafon > 0 ? (sisaPlafon >= 0 ? '' : '−') + formatRupiah(Math.abs(sisaPlafon)) : '—'}</div>
          </div>
          <div style="text-align:center">
            <div style="font-size:.72rem;color:var(--text-secondary);font-weight:600;letter-spacing:.04em">% UTILISASI</div>
            <div style="font-size:1.1rem;font-weight:800;color:${bannerClr}">${relevantPlafon > 0 ? utilisasiGlobal + '%' : '—'}</div>
          </div>
        </div>
      </div>`;
  }

  /* ============================================================
     MODUL PERLENGKAPAN SMH
     ============================================================ */
  function processPerlFile(file) {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const wb  = XLSX.read(new Uint8Array(e.target.result), { type: 'array' });
        const ws  = wb.Sheets[wb.SheetNames[0]];
        const raw = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });

        // Find header row (contains NOSIN)
        let hdrIdx = -1;
        for (let i = 0; i < Math.min(raw.length, 10); i++) {
          const up = raw[i].map(c => toStr(c).toUpperCase().trim());
          if (up.includes('NOSIN')) { hdrIdx = i; break; }
        }
        if (hdrIdx < 0) { showToast('Header NOSIN tidak ditemukan dalam file.', 'error'); return; }

        const hdrs = raw[hdrIdx].map(c => toStr(c).replace(/\n/g, ' ').toUpperCase().trim());

        // Key column indices
        const tipeIdx  = hdrs.indexOf('TIPE');
        const nosinIdx = hdrs.indexOf('NOSIN');
        const typeIdx  = hdrs.indexOf('TYPE');
        // NO column = separator between perlengkapan table and Unit Usaha reference table
        const noIdx    = hdrs.findIndex((h, i) => h === 'NO' && i > nosinIdx + 2);

        // Unit Usaha mapping columns (right of NO): Unit Usaha | AREA | JENIS
        const uuIdx    = noIdx >= 0 ? hdrs.findIndex((h, i) => i > noIdx && (h.includes('USAHA') || h === 'UNIT')) : -1;
        const areaRefI = noIdx >= 0 ? hdrs.findIndex((h, i) => i > noIdx && h === 'AREA') : -1;
        const jenisI   = noIdx >= 0 ? hdrs.findIndex((h, i) => i > noIdx && h === 'JENIS') : -1;
        // Fallback to positional offsets if headers not found
        const finalUuIdx    = uuIdx >= 0    ? uuIdx    : (noIdx >= 0 ? noIdx + 1 : -1);
        const finalAreaIdx  = areaRefI >= 0 ? areaRefI : (noIdx >= 0 ? noIdx + 2 : -1);
        const finalJenisIdx = jenisI >= 0   ? jenisI   : (noIdx >= 0 ? noIdx + 3 : -1);

        // Perlengkapan area columns: between NOSIN+1 and TYPE/NO (e.g. ACEH, RIAU, KEPRI)
        const perlEnd  = typeIdx > nosinIdx ? typeIdx : (noIdx > 0 ? noIdx : hdrs.length);
        const areaCols = [];
        for (let i = nosinIdx + 1; i < perlEnd; i++) {
          const h = hdrs[i];
          if (!h || h === 'TYPE' || h === 'TIPE') continue;
          areaCols.push({ area: h, idx: i });
        }

        const items      = [];
        const unitAreaMap = [];
        const seenUU     = new Set();

        for (let r = hdrIdx + 1; r < raw.length; r++) {
          const row = raw[r];

          // ── Perlengkapan rows (has NOSIN value) ──
          const nosin = toStr(row[nosinIdx]);
          if (nosin) {
            const tipe = tipeIdx >= 0 ? toStr(row[tipeIdx]) : '';
            const type = typeIdx >= 0 ? toStr(row[typeIdx]) : '';
            for (const { area, idx } of areaCols) {
              const cellVal = toStr(row[idx]);
              if (!cellVal) continue;
              // Each cell may be comma-separated (e.g. "Kaca Spion Revo, Toolset CUB")
              cellVal.split(',').map(s => s.trim()).filter(s => s).forEach(perlName => {
                items.push({ tipeMotor: tipe, kodeModel: nosin, area, namaPerlengkapan: perlName, tipeTipe: type, qty: 1 });
              });
            }
          }

          // ── Unit Usaha mapping rows (right side of NO column) ──
          if (noIdx >= 0 && toStr(row[noIdx])) {
            const uu = finalUuIdx >= 0 ? toStr(row[finalUuIdx]).trim() : '';
            const ar = finalAreaIdx >= 0 ? toStr(row[finalAreaIdx]).trim() : '';
            const jn = finalJenisIdx >= 0 ? toStr(row[finalJenisIdx]).trim() : '';
            if (uu && ar && !seenUU.has(uu)) {
              seenUU.add(uu);
              unitAreaMap.push({ unitUsaha: uu, area: ar, jenis: jn });
            }
          }
        }

        if (!items.length) {
          showToast('Tidak ada data perlengkapan yang terbaca. Periksa format file.', 'error');
          return;
        }
        smhPerl     = items;
        smhUnitArea = unitAreaMap;
        saveSmhData(SMH_PERL_KEY, smhPerl);
        saveSmhData(SMH_UNIT_AREA_KEY, smhUnitArea);
        renderSmhPerl();
        populateLuarAreaOptions();
        const msg = unitAreaMap.length > 0
          ? `${items.length} item perlengkapan & ${unitAreaMap.length} unit usaha berhasil diimport.`
          : `${items.length} item perlengkapan berhasil diimport.`;
        showToast(msg, 'success');
      } catch (err) {
        showToast('Format file tidak valid.', 'error');
      }
    };
    reader.onerror = () => showToast('Gagal membaca file.', 'error');
    reader.readAsArrayBuffer(file);
  }

  function renderSmhPerl(areaFilter) {
    if (areaFilter !== undefined) currentPerlArea = areaFilter;

    const tbody = document.getElementById('smhPerlTableBody');
    const stat  = document.getElementById('smhPerlStat');

    // Build area filter bar dynamically
    const filterBar = document.getElementById('perlAreaFilterBar');
    if (filterBar) {
      const areas = ['SEMUA', ...new Set(smhPerl.map(p => p.area).filter(a => a).sort())];
      filterBar.innerHTML = areas.map(a =>
        `<button class="perl-area-btn${currentPerlArea === a ? ' active' : ''}"
                 onclick="window._smhRenderPerl('${a}')">${a === 'SEMUA' ? 'Semua Area' : a}</button>`
      ).join('');
    }

    if (smhPerl.length === 0) {
      tbody.innerHTML = `<tr><td colspan="9"><div class="empty-state"><p>Belum ada data perlengkapan. Import file Excel untuk memulai.</p></div></td></tr>`;
      if (stat) stat.innerHTML = 'Belum ada data';
      return;
    }
    if (stat) stat.innerHTML = `<strong>${smhPerl.length}</strong> item`;

    const filtered = currentPerlArea === 'SEMUA'
      ? smhPerl
      : smhPerl.filter(p => p.area === currentPerlArea);

    if (filtered.length === 0) {
      tbody.innerHTML = `<tr><td colspan="9"><div class="empty-state"><p>Tidak ada data untuk area <strong>${currentPerlArea}</strong>.</p></div></td></tr>`;
      return;
    }

    // Build Unit Usaha → Area lookup
    const uuToArea = {};
    smhUnitArea.forEach(m => { uuToArea[m.unitUsaha] = m.area; });

    // Count onhand per (kodeModel, area)
    const ohByModelArea = {};
    smhOnhand.forEach(u => {
      const model = u.kodeModelIntern || '';
      if (!model) return;
      const ar  = uuToArea[u.kodeUnitUsaha] || '';
      const key = `${model}||${ar}`;
      ohByModelArea[key] = (ohByModelArea[key] || 0) + 1;
    });

    // Count how many times each perlengkapan item was marked "ada" in inspections
    const checkedMap = {};
    smhHasil.forEach(h => {
      (h.perlengkapan || []).forEach(p => {
        if (p.ada) {
          const key = `${h.kodeModel}||${h.area || ''}||${p.nama}`;
          checkedMap[key] = (checkedMap[key] || 0) + 1;
        }
      });
    });

    tbody.innerHTML = filtered.map((p, i) => {
      const onhandQty = ohByModelArea[`${p.kodeModel}||${p.area}`] || 0;
      const total     = p.qty * onhandQty;
      const checked   = checkedMap[`${p.kodeModel}||${p.area}||${p.namaPerlengkapan}`] || 0;
      const remaining = Math.max(0, total - checked);
      const remCls    = remaining === 0 && total > 0 ? 'perl-total-zero'
                      : remaining < total ? 'perl-total-highlight' : '';
      return `<tr>
        <td>${i + 1}</td>
        <td>${p.tipeMotor || '—'}</td>
        <td><strong>${p.kodeModel}</strong></td>
        <td>${p.namaPerlengkapan}</td>
        <td style="text-align:center">${p.tipeTipe || '—'}</td>
        <td>${areaBadge(p.area)}</td>
        <td style="text-align:center">${onhandQty}</td>
        <td style="text-align:center">${checked > 0 ? `<strong>${checked}</strong>` : '0'}</td>
        <td style="text-align:center" class="${remCls}">${remaining}</td>
      </tr>`;
    }).join('');
  }
  // Expose for inline onclick in area filter buttons
  window._smhRenderPerl = renderSmhPerl;

  /* ============================================================
     MODUL SCAN & PEMERIKSAAN
     ============================================================ */
  let currentScanUnit = null;

  /* ── Helpers ── */
  function getAllAreas() {
    const set = new Set();
    smhPerl.forEach(p => { if (p.area) set.add(p.area.toUpperCase()); });
    smhUnitArea.forEach(m => { if (m.area) set.add(m.area.toUpperCase()); });
    return [...set].sort();
  }

  function populateLuarAreaOptions() {
    const sel = document.getElementById('luarArea');
    if (!sel) return;
    const prev = sel.value;
    const areas = getAllAreas();
    sel.innerHTML = '<option value="">— Pilih Area —</option>' +
      areas.map(a => `<option value="${a}">${a}</option>`).join('');
    if (prev) sel.value = prev;
  }

  function _normUU(s) { return (s || '').toUpperCase().replace(/[\s\-_]/g, ''); }

  // ── Cek apakah unit sudah pernah diperiksa (dikunci per plan + unit usaha) ──
  function _isAlreadyScanned(noMesin, noRangka) {
    const norm   = s => (s || '').replace(/\s/g, '').toUpperCase();
    const nM     = norm(noMesin);
    const nR     = norm(noRangka);
    const planId = _auditContext?.planId || null;
    const cabang = _auditContext?.cabang || session.unitUsaha || null;

    return smhHasil.some(h => {
      const sameUnit = (nM && norm(h.noMesin) === nM) || (nR && norm(h.noRangka) === nR);
      if (!sameUnit) return false;
      // Kunci per plan: blok jika plan sama
      if (planId && h.auditPlanId) return String(h.auditPlanId) === String(planId);
      // Kunci per unit usaha (tanpa plan): blok jika cabang sama
      if (cabang && h.auditCabang)  return h.auditCabang === cabang;
      // Fallback standalone: blok duplikat yang tidak punya planId
      return !h.auditPlanId;
    });
  }

  // ── Bangun Set noMesin (sudah terscan) untuk context saat ini ──
  function _getScannedMesinSet() {
    const norm   = s => (s || '').replace(/\s/g, '').toUpperCase();
    const planId = _auditContext?.planId || null;
    const cabang = _auditContext?.cabang || session.unitUsaha || null;
    return new Set(
      smhHasil
        .filter(h => {
          if (planId && h.auditPlanId) return String(h.auditPlanId) === String(planId);
          if (cabang && h.auditCabang)  return h.auditCabang === cabang;
          return !h.auditPlanId;
        })
        .map(h => norm(h.noMesin))
        .filter(Boolean)
    );
  }

  function populateOnhandDropdown() {
    const sel = document.getElementById('smhScanSelect');
    if (!sel) return;
    const prev = sel.value;

    // Filter onhand for branch staff to only their cabang
    let displayUnits = smhOnhand;
    const r = session.role;
    const ctx = _auditContext;
    if (ctx) {
      // Audit context active: filter to this specific audit's cabang
      const ctxUU = _normUU(ctx.cabang);
      displayUnits = smhOnhand.filter(u => {
        const uuu = _normUU(u.kodeUnitUsaha);
        return !ctxUU || uuu === ctxUU || uuu.includes(ctxUU) || ctxUU.includes(uuu);
      });
    } else if ((r === 'so' || r === 'csc' || r === 'whs') && session.unitUsaha) {
      // Branch staff without explicit context: filter to their unit usaha
      const myUU = _normUU(session.unitUsaha);
      displayUnits = smhOnhand.filter(u => {
        const uuu = _normUU(u.kodeUnitUsaha);
        return !myUU || uuu === myUU || uuu.includes(myUU) || myUU.includes(uuu);
      });
    }

    // Hilangkan unit yang sudah terscan dalam konteks plan/unit usaha yang sama
    smhHasil = loadSmhData(SMH_HASIL_KEY);
    const scannedSet = _getScannedMesinSet();
    const norm = s => (s || '').replace(/\s/g, '').toUpperCase();
    const unscannedUnits = displayUnits.filter(u => !scannedSet.has(norm(u.noMesin)));
    const scannedCount   = displayUnits.length - unscannedUnits.length;

    sel.innerHTML = '<option value="">— Pilih No.Mesin / No.Rangka dari Daftar Onhand —</option>' +
      unscannedUnits.map(u => {
        const gudangInfo = u.gudang ? ` | ${u.gudang}` : '';
        return `<option value="${u.noMesin}">${u.noMesin} / ${u.noRangka} — ${u.kodeModelIntern}${gudangInfo}</option>`;
      }).join('') +
      (scannedCount > 0
        ? `<option disabled>── ${scannedCount} unit sudah diperiksa (tersembunyi) ──</option>`
        : '');
    if (prev && !scannedSet.has(norm(prev))) sel.value = prev;
  }

  function formatTglHasil(w) {
    if (!w) return '—';
    if (/^\d{4}-\d{2}-\d{2}$/.test(w)) {
      const [y, m, d] = w.split('-');
      return `${d}/${m}/${y}`;
    }
    return new Date(w).toLocaleDateString('id-ID');
  }

  /* ── PML (multi-select dropdown) global callbacks ── */
  window._openPml = function () {
    const panel = document.getElementById('pmlPanel');
    if (panel && panel.classList.contains('hidden')) {
      panel.classList.remove('hidden');
      document.getElementById('pmlTrigger')?.classList.add('open');
      window._filterPml(document.getElementById('pmlSearch')?.value || '');
    }
  };

  window._closePml = function () {
    const panel = document.getElementById('pmlPanel');
    if (panel) { panel.classList.add('hidden'); }
    document.getElementById('pmlTrigger')?.classList.remove('open');
    const srch = document.getElementById('pmlSearch');
    if (srch) srch.value = '';
    window._filterPml('');
  };

  window._togglePml = function () {
    const panel = document.getElementById('pmlPanel');
    if (!panel) return;
    if (panel.classList.contains('hidden')) window._openPml();
    else window._closePml();
  };

  window._filterPml = function (q) {
    const query = (q || '').toLowerCase();
    let visible = 0;
    document.querySelectorAll('#pmlList .pml-item-row').forEach(row => {
      const lbl = row.querySelector('.pml-item-label');
      const show = !query || (lbl && lbl.textContent.toLowerCase().includes(query));
      row.style.display = show ? '' : 'none';
      if (show) visible++;
    });
    // Auto-open panel when typing
    if (q && visible > 0) window._openPml();
    window._updateSelectAll();
  };

  window._selectAllPml = function (checked) {
    document.querySelectorAll('#pmlList .pml-item-row').forEach(row => {
      if (row.style.display !== 'none') {
        const cb = row.querySelector('.pml-item-cb');
        if (cb) cb.checked = checked;
      }
    });
    window._updatePmlDisplay();
  };

  window._updatePmlDisplay = function () {
    const all     = document.querySelectorAll('#pmlList .pml-item-cb');
    const checked = document.querySelectorAll('#pmlList .pml-item-cb:checked');

    // Update badge
    const badge = document.getElementById('pmlSelectedBadge');
    if (badge) {
      if (all.length === 0) {
        badge.classList.add('hidden');
      } else if (checked.length === 0) {
        badge.classList.add('hidden');
      } else {
        badge.textContent = checked.length === all.length
          ? `✓ Semua ${all.length} item terpilih`
          : `✓ ${checked.length} dari ${all.length} item terpilih`;
        badge.classList.remove('hidden');
      }
    }

    // Keep triggerLabel in sync (backward compat)
    const label = document.getElementById('pmlTriggerLabel');
    if (label) {
      if (all.length === 0)                   label.textContent = '';
      else if (checked.length === 0)          label.textContent = '';
      else if (checked.length === all.length) label.textContent = `Semua (${all.length}) terpilih`;
      else                                    label.textContent = `${checked.length}/${all.length} terpilih`;
    }

    // Update progress bar
    const pct  = all.length > 0 ? Math.round(checked.length / all.length * 100) : 0;
    const bar  = document.getElementById('pmlProgressBar');
    const plbl = document.getElementById('pmlProgressLabel');
    if (bar)  bar.style.width  = pct + '%';
    if (plbl) plbl.textContent = `${checked.length} ada / ${all.length - checked.length} tidak ada`;

    window._updateSelectAll();
  };

  window._updateSelectAll = function () {
    const sa = document.getElementById('pmlSelectAll');
    if (!sa) return;
    const visible = Array.from(
      document.querySelectorAll('#pmlList .pml-item-row')
    ).filter(r => r.style.display !== 'none');
    const checkedVis = visible.filter(r => r.querySelector('.pml-item-cb')?.checked);
    sa.indeterminate = checkedVis.length > 0 && checkedVis.length < visible.length;
    sa.checked = visible.length > 0 && checkedVis.length === visible.length;
  };

  /* ── buildPerlChecklist → writes into #pmlList ── */
  function buildPerlChecklist(kodeModel, area, noMesin) {
    const listEl  = document.getElementById('pmlList');
    const emptyEl = document.getElementById('smhPerlEmpty');
    const wrapEl  = document.getElementById('pmlWrap');
    const tagEl   = document.getElementById('perlUnitTag');

    const norm = s => toStr(s).toUpperCase().replace(/[\s\-_]+/g, '');
    const normModel = norm(kodeModel);

    // 5-char prefix dari noMesin (requirement 2)
    // Contoh: "KD11E 1650833" → "KD11E"
    const mesinPfx = noMesin
      ? noMesin.replace(/\s/g, '').slice(0, 5).toUpperCase()
      : '';

    // ── Matching priority ──────────────────────────────────
    // 1. Exact kodeModelIntern match
    let items = smhPerl.filter(p => norm(p.kodeModel) === normModel);

    // 2. Exact noMesin 5-char prefix match against smhPerl.kodeModel
    if (items.length === 0 && mesinPfx) {
      items = smhPerl.filter(p => norm(p.kodeModel) === mesinPfx);
    }

    // 3. noMesin prefix starts-with kodeModel or vice versa
    if (items.length === 0 && mesinPfx) {
      items = smhPerl.filter(p => {
        const pk = norm(p.kodeModel);
        return pk.startsWith(mesinPfx) || mesinPfx.startsWith(pk);
      });
    }

    // 4. kodeModelIntern partial match
    if (items.length === 0 && normModel) {
      items = smhPerl.filter(p => {
        const pk = norm(p.kodeModel);
        return pk.includes(normModel) || normModel.includes(pk);
      });
    }

    // 5. Filter by area
    const normArea = area ? area.toUpperCase() : '';
    if (normArea && items.some(p => toStr(p.area).toUpperCase() === normArea)) {
      items = items.filter(p => toStr(p.area).toUpperCase() === normArea);
    }

    // NO fallback "show all" — ketat sesuai database

    // ── Deduplikasi per wilayah/area (requirement 2) ──────
    // Kelompokkan per namaPerlengkapan, ambil qty tertinggi per nama
    // Ini mencegah item double jika database memiliki entri duplikat
    const deduped = new Map();
    items.forEach(item => {
      const key = item.namaPerlengkapan.trim().toLowerCase();
      if (!deduped.has(key) || item.qty > deduped.get(key).qty) {
        deduped.set(key, item);
      }
    });
    items = [...deduped.values()];

    // Update header tag
    const modelLabel = kodeModel || mesinPfx || '?';
    if (tagEl) {
      tagEl.textContent = modelLabel + (normArea ? ' · ' + normArea : '');
      tagEl.style.display = items.length > 0 ? '' : 'none';
    }

    if (items.length === 0) {
      listEl.innerHTML = '';
      if (emptyEl) emptyEl.classList.remove('hidden');
      if (wrapEl)  wrapEl.classList.add('hidden');
      return;
    }
    if (emptyEl) emptyEl.classList.add('hidden');
    if (wrapEl)  wrapEl.classList.remove('hidden');

    // ── Hitung stok tersisa per item ──────────────────────
    const onhandForModel = smhOnhand.filter(u => {
      const um = norm(u.kodeModelIntern);
      const up = u.noMesin ? u.noMesin.replace(/\s/g,'').slice(0,5).toUpperCase() : '';
      return um === normModel || um === mesinPfx || up === mesinPfx;
    });
    const onhandCount = onhandForModel.length;

    const usedMap = {};
    smhHasil.forEach(h => {
      const hm = norm(h.kodeModel);
      if (hm !== normModel && hm !== mesinPfx) return;
      (h.perlengkapan || []).forEach(p => {
        if (p.ada) usedMap[p.nama] = (usedMap[p.nama] || 0) + 1;
      });
    });

    // ── Urutkan: tipeMotor → namaPerlengkapan ────────────
    items.sort((a, b) => {
      const tA = (a.tipeMotor || 'Umum').localeCompare(b.tipeMotor || 'Umum');
      if (tA !== 0) return tA;
      return a.namaPerlengkapan.localeCompare(b.namaPerlengkapan);
    });

    // ── Group by tipeMotor ────────────────────────────────
    const grouped = {};
    items.forEach(item => {
      const grp = item.tipeMotor || 'Umum';
      if (!grouped[grp]) grouped[grp] = [];
      grouped[grp].push(item);
    });

    const multiGroup = Object.keys(grouped).length > 1;
    let idx = 0;
    let html = '';
    Object.entries(grouped).forEach(([grp, grpItems]) => {
      if (multiGroup) html += `<div class="pml-group-header">${grp}</div>`;
      html += grpItems.map(item => {
        const escapedNama = item.namaPerlengkapan.replace(/"/g, '&quot;');
        const totalStok   = onhandCount * item.qty;
        const usedStok    = usedMap[item.namaPerlengkapan] || 0;
        const sisaStok    = Math.max(0, totalStok - usedStok);
        const stockCls    = sisaStok === 0 ? 'pml-stock-zero'
                          : sisaStok < totalStok * 0.25 ? 'pml-stock-low'
                          : 'pml-stock-ok';
        const stockBadge  = totalStok > 0
          ? `<span class="pml-stock ${stockCls}" title="Stok: ${sisaStok} dari ${totalStok}">Sisa: ${sisaStok}/${totalStok}</span>`
          : '';
        return `<label class="pml-item-row">
          <input type="checkbox" class="pml-item-cb" data-idx="${idx++}"
                 data-nama="${escapedNama}" data-qty="${item.qty}" data-sisa="${sisaStok}" checked
                 onchange="window._updatePmlDisplay()" />
          <span class="pml-item-label">${item.namaPerlengkapan}</span>
          <span class="pml-item-meta">
            <span class="pml-item-qty">×${item.qty}</span>
            ${stockBadge}
          </span>
        </label>`;
      }).join('');
    });

    listEl.innerHTML = html;
    window._updatePmlDisplay();

    // Buka panel langsung setelah checklist terisi
    const panel = document.getElementById('pmlPanel');
    if (panel) panel.classList.remove('hidden');
    document.getElementById('pmlTrigger')?.classList.add('open');
  }

  /* ── selectUnit: shared by doScan + dropdown ── */
  function selectUnit(found) {
    // Access control: branch staff can only inspect their own cabang units
    const r = session.role;
    if ((r === 'so' || r === 'csc' || r === 'whs') && session.unitUsaha) {
      const myUU   = _normUU(session.unitUsaha);
      const unitUU = _normUU(found.kodeUnitUsaha);
      if (unitUU && myUU && !unitUU.includes(myUU) && !myUU.includes(unitUU)) {
        showToast(`Unit ${found.noMesin} bukan milik cabang ${session.unitUsaha}. Akses ditolak.`, 'error');
        return;
      }
    }

    // ── Cek duplikat: unit sudah pernah diperiksa dalam plan/cabang yang sama ──
    smhHasil = loadSmhData(SMH_HASIL_KEY);
    if (_isAlreadyScanned(found.noMesin, found.noRangka)) {
      const ctx = _auditContext ? ` (Plan: ${_auditContext.noSPT || _auditContext.planId})` : '';
      showToast(`Unit ${found.noMesin} sudah diperiksa${ctx}. Tidak dapat discan ulang.`, 'error');
      document.getElementById('smhResultFound')?.classList.add('hidden');
      document.getElementById('smhResultNotFound')?.classList.add('hidden');
      document.getElementById('smhScanInput').value = '';
      document.getElementById('smhScanSelect').value = '';
      return;
    }
    currentScanUnit = found;
    currentScanArea = getUnitArea(found.kodeUnitUsaha);

    // Backward-compat hidden spans
    document.getElementById('resNoMesin').textContent    = found.noMesin;
    document.getElementById('resNoRangka').textContent   = found.noRangka;
    document.getElementById('resKodeModel').textContent  = found.kodeModelIntern;
    document.getElementById('resKodeWarna').textContent  = found.kodeWarnaIntern;
    document.getElementById('resUnitUsaha').textContent  = found.kodeUnitUsaha || '—';
    document.getElementById('resArea').innerHTML         = areaBadge(currentScanArea) || '—';
    document.getElementById('resNoSPB').textContent      = found.noSPB || '—';
    document.getElementById('resNoDO').textContent       = found.noDO || '—';

    // ── Isi form card baru ─────────────────────────────
    const scanDisp = document.getElementById('fisikScanDisplay');
    if (scanDisp) scanDisp.textContent = found.noMesin;

    const ketFisikEl = document.getElementById('fisikKetFisik');
    if (ketFisikEl) ketFisikEl.value = 'Fisik Ada';

    const jMotorEl = document.getElementById('fisikJenisMotor');
    if (jMotorEl) jMotorEl.value =
      [found.kodeModelIntern, found.kodeWarnaIntern].filter(Boolean).join(' / ') || '—';

    const lokasiEl = document.getElementById('fisikLokasi');
    if (lokasiEl) {
      // Prioritas: kolom gudang dari onhand → kodeUnitUsaha → area
      const lokasiVal = found.gudang || found.kodeUnitUsaha || currentScanArea || '';
      lokasiEl.value = lokasiVal;
    }

    const rangkaEl = document.getElementById('fisikNoRangka');
    if (rangkaEl) rangkaEl.value = found.noRangka || '—';

    const spbEl = document.getElementById('fisikNoSPB');
    if (spbEl) spbEl.value = [found.noSPB, found.noDO].filter(Boolean).join(' / ') || '—';

    const ketEl = document.getElementById('fisikKeterangan');
    if (ketEl) {
      // Default: Ready for Sale berdasarkan kondisi onhand
      ketEl.value = 'Ready for Sale';
    }

    buildPerlChecklist(found.kodeModelIntern, currentScanArea, found.noMesin);
    document.getElementById('smhResultFound').classList.remove('hidden');
    document.getElementById('smhResultNotFound').classList.add('hidden');

    // Scroll to result
    setTimeout(() => {
      document.getElementById('smhResultFound')?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }, 100);
  }

  function doScan() {
    const raw   = document.getElementById('smhScanInput').value.trim();
    const query = raw.toLowerCase();
    if (!query) return;

    let found = smhOnhand.find(u =>
      u.noMesin.toLowerCase() === query || u.noRangka.toLowerCase() === query
    );
    if (!found) {
      found = smhOnhand.find(u =>
        u.noMesin.toLowerCase().includes(query) || u.noRangka.toLowerCase().includes(query)
      );
    }

    if (found) {
      // Cek duplikat lebih dulu sebelum selectUnit
      smhHasil = loadSmhData(SMH_HASIL_KEY);
      if (_isAlreadyScanned(found.noMesin, found.noRangka)) {
        const ctx = _auditContext ? ` dalam Plan ${_auditContext.noSPT || _auditContext.planId}` : '';
        currentScanUnit = null;
        currentScanArea = null;
        document.getElementById('smhScanInput').value = '';
        document.getElementById('smhScanSelect').value = '';
        document.getElementById('smhResultFound').classList.add('hidden');
        document.getElementById('smhResultNotFound').classList.remove('hidden');
        document.getElementById('smhNotFoundMsg').innerHTML =
          `<strong>${found.noMesin}</strong> sudah pernah diperiksa${ctx}. Gunakan unit lain.`;
        return;
      }
      selectUnit(found);
      document.getElementById('smhScanSelect').value = found.noMesin;
    } else {
      currentScanUnit = null;
      currentScanArea = null;
      document.getElementById('smhNotFoundMsg').textContent =
        `"${raw}" tidak ditemukan dalam data onhand SMH. Pastikan data onhand sudah diimport.`;
      document.getElementById('smhResultFound').classList.add('hidden');
      document.getElementById('smhResultNotFound').classList.remove('hidden');
    }
  }

  function saveHasilPemeriksaan() {
    if (!currentScanUnit) return;
    const tgl = (document.getElementById('smhScanTgl')?.value) ||
                new Date().toISOString().slice(0, 10);
    const perlItems = [];
    document.querySelectorAll('#pmlList .pml-item-cb').forEach(cb => {
      perlItems.push({
        nama: cb.dataset.nama,
        qty:  parseInt(cb.dataset.qty) || 1,
        ada:  cb.checked ? 1 : 0,
      });
    });

    const keteranganFisik = document.getElementById('fisikKetFisik')?.value?.trim() || 'Fisik Ada';
    const statusFisik     = document.getElementById('fisikKeterangan')?.value?.trim() || 'Ready for Sale';
    const lokasiManual    = document.getElementById('fisikLokasi')?.value?.trim() || currentScanUnit.gudang || '';

    smhHasil.unshift({
      id:             Date.now(),
      waktu:          tgl,
      noMesin:        currentScanUnit.noMesin,
      noRangka:       currentScanUnit.noRangka,
      kodeModel:      currentScanUnit.kodeModelIntern,
      kodeWarna:      currentScanUnit.kodeWarnaIntern,
      kodeUnitUsaha:  currentScanUnit.kodeUnitUsaha,
      gudang:         lokasiManual,
      area:           currentScanArea || '',
      keteranganFisik,
      statusFisik,
      perlengkapan:   perlItems,
      savedBy:        session.username,
      // Audit context (if present)
      auditPlanId:    _auditContext ? _auditContext.planId  : null,
      auditNoSPT:     _auditContext ? _auditContext.noSPT   : null,
      auditCabang:    _auditContext ? _auditContext.cabang  : null,
    });
    saveSmhData(SMH_HASIL_KEY, smhHasil);
    renderSmhHasil();
    renderSmhPerl();
    // Refresh dropdown agar unit yang baru disimpan hilang dari pilihan
    populateOnhandDropdown();

    // ── Sinkronisasi ke luar fisik (requirement 3) ────────
    const adaItems = perlItems.filter(p => p.ada);
    if (adaItems.length > 0) {
      const syncData = {
        noMesin:   currentScanUnit.noMesin,
        kodeModel: currentScanUnit.kodeModelIntern,
        area:      currentScanArea || '',
        tgl:       tgl,
        items:     adaItems.map(p => ({ nama: p.nama, qty: p.qty })),
      };
      localStorage.setItem('akta_luar_sync_pending', JSON.stringify(syncData));
      _checkLuarSyncBanner();
    }

    // Reset (keep date, clear unit selection)
    currentScanUnit = null;
    currentScanArea = null;
    document.getElementById('smhScanInput').value  = '';
    document.getElementById('smhScanSelect').value = '';
    document.getElementById('smhResultFound').classList.add('hidden');
    document.getElementById('smhResultNotFound').classList.add('hidden');
    document.getElementById('pmlPanel')?.classList.add('hidden');
    document.getElementById('pmlTrigger')?.classList.remove('open');
    const tagEl = document.getElementById('perlUnitTag');
    if (tagEl) tagEl.style.display = 'none';
    showToast('Hasil pemeriksaan berhasil disimpan.', 'success');
    document.getElementById('smhScanInput').focus();
  }

  function renderSmhHasil() {
    const tbody   = document.getElementById('smhHasilBody');
    const bannerEl = document.getElementById('smhHasilPlanBanner');
    if (!tbody) return;

    // ── Filter by audit plan context (requirement 1) ─────
    let display = smhHasil;
    const smhSimpanBar = document.getElementById('smhSimpanPemBar');

    if (_auditContext && _auditContext.planId) {
      display = smhHasil.filter(h => String(h.auditPlanId) === String(_auditContext.planId));
      if (bannerEl) {
        bannerEl.innerHTML = `
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"
               style="vertical-align:middle;margin-right:4px"><rect x="3" y="4" width="18" height="18" rx="2"/>
               <line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/>
               <line x1="3" y1="10" x2="21" y2="10"/></svg>
          Menampilkan hasil pemeriksaan untuk <strong>No. SPT: ${_auditContext.noSPT || _auditContext.planId}</strong>
          — Cabang: <strong>${_auditContext.cabang || '—'}</strong>
          <span style="margin-left:8px;color:#888;font-size:.78rem">${display.length} unit diperiksa</span>`;
        bannerEl.style.display = '';
      }

      // ── Simpan ke Report Audit bar ──────────────────────────────────
      if (smhSimpanBar) {
        if (display.length > 0) {
          const _smhSavedPem  = loadSavedPem();
          const _smhIsSaved   = _smhSavedPem.some(s => String(s.planId) === String(_auditContext.planId) && s.type === 'smh');
          const _smhSavedAt   = _smhIsSaved ? _smhSavedPem.find(s => String(s.planId) === String(_auditContext.planId) && s.type === 'smh').savedAt : null;
          const _smhSavedDate = _smhSavedAt ? new Date(_smhSavedAt).toLocaleString('id-ID', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '';
          smhSimpanBar.innerHTML = `
            <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:12px 16px;
                 background:${_smhIsSaved ? '#dcfce7' : '#f0f9ff'};border-bottom:1.5px solid ${_smhIsSaved ? '#86efac' : '#bae6fd'}">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="${_smhIsSaved?'#166534':'#0369a1'}" stroke-width="2">
                <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/>
                <polyline points="17 21 17 13 7 13 7 21"/><polyline points="7 3 7 8 15 8"/>
              </svg>
              <div style="flex:1">
                <div style="font-size:.83rem;font-weight:700;color:${_smhIsSaved?'#166534':'#0369a1'}">
                  ${_smhIsSaved ? '✓ Pemeriksaan Unit SMH sudah disimpan ke Report Audit' : 'Simpan hasil ini ke Report Audit'}
                </div>
                <div style="font-size:.75rem;color:${_smhIsSaved?'#4ade80':'#64748b'};margin-top:2px">
                  ${_smhIsSaved
                    ? 'Tersimpan: ' + _smhSavedDate + ' &nbsp;·&nbsp; ' + display.length + ' unit diperiksa'
                    : display.length + ' unit diperiksa &nbsp;·&nbsp; Klik untuk tampil di Report Audit'}
                </div>
              </div>
              <button onclick="window._simpanSmhKeReport('${_auditContext.planId}')"
                      style="background:${_smhIsSaved?'#16a34a':'#0369a1'};color:#fff;border:none;border-radius:7px;
                             padding:8px 18px;font-size:.83rem;font-weight:700;cursor:pointer;
                             display:flex;align-items:center;gap:6px;white-space:nowrap">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                  <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/>
                  <polyline points="17 21 17 13 7 13 7 21"/><polyline points="7 3 7 8 15 8"/>
                </svg>
                ${_smhIsSaved ? 'Perbarui ke Report Audit' : 'Simpan ke Report Audit'}
              </button>
            </div>`;
        } else {
          smhSimpanBar.innerHTML = `
            <div style="padding:10px 16px;background:#fff7ed;border-bottom:1px solid #fed7aa;font-size:.82rem;color:#92400e">
              ⚠️ Lakukan pemeriksaan unit SMH terlebih dahulu sebelum dapat menyimpan ke Report Audit.
            </div>`;
        }
      }
    } else {
      if (bannerEl) bannerEl.style.display = 'none';
      if (smhSimpanBar) smhSimpanBar.innerHTML = '';
    }

    if (display.length === 0) {
      tbody.innerHTML = `<tr><td colspan="9"><div class="empty-state"><p>${
        _auditContext ? 'Belum ada hasil pemeriksaan untuk plan ini.' : 'Belum ada hasil pemeriksaan yang disimpan.'
      }</p></div></td></tr>`;
      return;
    }

    let html = '';
    display.forEach((h, i) => {
      const total = h.perlengkapan.length;
      const ada   = h.perlengkapan.filter(p => p.ada).length;
      let perlHtml;
      if (total === 0)         perlHtml = `<span class="perl-badge-none">—</span>`;
      else if (ada === total)  perlHtml = `<span class="perl-badge-ok">✓ ${ada}/${total} Lengkap</span>`;
      else                     perlHtml = `<span class="perl-badge-warn">⚠ ${ada}/${total} Kurang</span>`;

      const detailId  = `detail-${h.id}`;
      const planTag   = h.auditNoSPT
        ? `<span style="font-size:.68rem;color:#6366f1;margin-left:4px">#${h.auditNoSPT}</span>` : '';
      const statusBadge = h.statusFisik
        ? `<span class="fisik-status-badge" style="font-size:.68rem">${h.statusFisik}</span>` : '';
      html += `<tr style="cursor:pointer" onclick="document.getElementById('${detailId}').classList.toggle('hidden')">
        <td>${i + 1}</td>
        <td style="white-space:nowrap;font-size:.8rem">${formatTglHasil(h.waktu)}</td>
        <td style="white-space:nowrap"><strong>${h.noMesin}</strong>${planTag}</td>
        <td style="white-space:nowrap">${h.noRangka}</td>
        <td><strong>${h.kodeModel}</strong></td>
        <td>${h.kodeWarna}</td>
        <td>${areaBadge(h.area)}</td>
        <td>${perlHtml}</td>
        <td>
          <span class="badge-fisik-ada" style="font-size:.72rem">${h.keteranganFisik || 'Fisik Ada'}</span>
          ${statusBadge}
          <button class="riwayat-expand-btn" title="Lihat detail">▾</button>
        </td>
      </tr>`;

      if (total > 0) {
        const tags = h.perlengkapan.map(p =>
          `<span class="riwayat-perl-tag ${p.ada ? '' : 'tidak'}">${p.ada ? '✓' : '✕'} ${p.nama}</span>`
        ).join('');
        html += `<tr id="${detailId}" class="riwayat-detail-row hidden">
          <td colspan="9">
            <div style="padding:4px 0 8px 8px"><strong style="font-size:.78rem;color:var(--text-secondary)">No.Mesin: ${h.noMesin}</strong></div>
            <div class="riwayat-perl-tags">${tags}</div>
          </td>
        </tr>`;
      }
    });
    tbody.innerHTML = html;
  }

  /* ── PERLENGKAPAN LUAR FISIK — Form Baru ── */

  // ── Modal Perlengkapan Luar Fisik (dari Audit) ────────────────────────
  window._openLuarFisikModal = function (taskId) {
    // Set container ke modal agar _luarEl() tidak salah ambil elemen standalone
    _luarFormContainer = document.getElementById('luarFisikModal');
    tasks = loadTasks();
    plans = loadPlans();
    const t = tasks.find(x => x.id == taskId);
    if (!t) return;

    // ── Resolusi area wilayah dari berbagai sumber ─────────
    // 1. Dari task.cabangArea (jika tersimpan saat plan dibuat)
    // 2. Dari plan.cabangArea (via planId)
    // 3. Dari smhUnitArea (lookup via cabangPlan = unit usaha)
    const plan = plans.find(p => String(p.id) === String(t.planId));
    let area = (t.cabangArea || plan?.cabangArea || '').trim();
    if (!area && t.cabangPlan) {
      // Lookup dari database unit usaha
      smhUnitArea = loadSmhData(SMH_UNIT_AREA_KEY);
      const uuRec = smhUnitArea.find(u =>
        u.unitUsaha?.trim().toUpperCase() === t.cabangPlan?.trim().toUpperCase()
      );
      area = uuRec?.area || '';
    }

    // Set audit context dengan area yang sudah diresolvasi
    _auditContext = {
      taskId:  t.id,
      planId:  t.planId,
      noSPT:   t.noSPT || plan?.noSPT,
      cabang:  t.cabangPlan || plan?.cabangPlan,
      area,
    };

    // Tampilkan info audit
    const infoEl = document.getElementById('luarFisikAuditInfo');
    const noSPT  = _auditContext.noSPT || '—';
    const cabang = _auditContext.cabang || '—';
    if (infoEl) {
      infoEl.innerHTML = `<strong>Audit:</strong> ${noSPT} &nbsp;|&nbsp;
        <strong>Cabang:</strong> ${cabang}
        ${area ? `&nbsp;<span class="badge-area ${area.toLowerCase().replace(/\s/g,'-')}">${area}</span>` : ''}`;
    }

    // Reset form
    const today = new Date().toISOString().slice(0,10);
    const luarTgl = _luarEl('luarTgl');
    if (luarTgl) luarTgl.value = today;

    const jSel = _luarEl('luarJenisPerlengkapan');
    if (jSel) jSel.value = '';
    const saldoEl = _luarEl('luarSaldo');
    if (saldoEl) saldoEl.value = 0;
    const fisikEl = _luarEl('luarFisik');
    if (fisikEl) fisikEl.value = 0;
    const selEl = _luarEl('luarSelisih');
    if (selEl) { selEl.value = 0; selEl.style.color = ''; }
    const penEl = _luarEl('luarPenjelasan');
    if (penEl) penEl.value = '';

    // Reload data terkini agar saldo sinkron dengan scan terbaru
    smhPerl     = loadSmhData(SMH_PERL_KEY);
    smhHasil    = loadSmhData(SMH_HASIL_KEY);
    smhOnhand   = _loadOnhandForPlan(_auditContext?.planId);
    _populateLuarJenisDropdown(area, t.cabangPlan || plan?.cabangPlan || '');

    // Buka modal
    const modal = document.getElementById('luarFisikModal');
    if (modal) { modal.classList.remove('hidden'); modal.style.display = 'flex'; }

    // Render info card di section luar fisik standalone
    _renderSMHInfoCard('smhLuarInfoCard');
  };

  window._closeLuarFisikModal = function () {
    const modal = document.getElementById('luarFisikModal');
    if (modal) { modal.classList.add('hidden'); modal.style.display = ''; }
    _luarFormContainer = null;
  };

  // Isi dropdown jenis perlengkapan berdasarkan wilayah dan model dari onhand
  function _populateLuarJenisDropdown(area, cabangPlan) {
    const sel = _luarEl('luarJenisPerlengkapan');
    if (!sel) return;

    // ── Ambil data perlengkapan dari module variable (selalu terkini) ──
    // Jika module variable kosong, reload dari localStorage
    let perlData = smhPerl.length > 0
      ? smhPerl
      : (function() {
          try { return JSON.parse(localStorage.getItem('akta_smh_perlengkapan')) || []; }
          catch { return []; }
        })();

    if (!perlData.length) {
      sel.innerHTML = '<option value="">— Import data perlengkapan di menu Database SMH →  Perlengkapan —</option>';
      return;
    }

    // ── Step 1: filter berdasarkan wilayah/area dari plan ─────────────
    const normArea = (area || '').toUpperCase().trim();
    let filtered = normArea
      ? perlData.filter(p => (p.area || '').toUpperCase().trim() === normArea)
      : [...perlData];

    // Jika tidak ada yang cocok dengan area, tampilkan semua
    if (!filtered.length) filtered = [...perlData];

    // ── Step 2: refine lebih lanjut berdasarkan 5 karakter noMesin ────
    // dari data onhand yang ada (kodeModel pada smhPerl vs prefix noMesin)
    const onhandData = smhOnhand.length > 0
      ? smhOnhand
      : (function() {
          try { return JSON.parse(localStorage.getItem('akta_smh_onhand')) || []; }
          catch { return []; }
        })();

    if (onhandData.length > 0) {
      // Kumpulkan semua prefix 5-char dari noMesin di onhand
      const modelPfx = new Set(
        onhandData
          .map(u => (u.noMesin || '').replace(/\s/g, '').slice(0, 5).toUpperCase())
          .filter(Boolean)
      );

      if (modelPfx.size > 0) {
        const byModel = filtered.filter(p => {
          const pk = (p.kodeModel || '').replace(/\s/g, '').toUpperCase();
          return [...modelPfx].some(pfx =>
            pk === pfx ||
            pk.startsWith(pfx) ||
            pfx.startsWith(pk)
          );
        });
        // Gunakan filter model hanya jika ada hasil; jika tidak, tetap pakai area filter
        if (byModel.length > 0) filtered = byModel;
      }
    }

    // ── Step 3: deduplikasi nama perlengkapan (case-insensitive) ──────
    const seen  = new Set();
    const names = [];
    filtered.forEach(p => {
      const n = (p.namaPerlengkapan || '').trim();
      if (n && !seen.has(n.toLowerCase())) {
        seen.add(n.toLowerCase());
        names.push(n);
      }
    });
    names.sort();

    if (!names.length) {
      sel.innerHTML = '<option value="">— Tidak ada perlengkapan untuk wilayah ini —</option>';
      return;
    }

    const areaLabel = normArea || 'Semua Wilayah';
    sel.innerHTML = `<option value="">— Pilih Jenis Perlengkapan · ${names.length} item · ${areaLabel} —</option>` +
      names.map(n => `<option value="${n}">${n}</option>`).join('');
  }

  // Auto-fill saldo: qty_onhand − qty_smh_fisik_ada − qty_luar_fisik_tersimpan
  window._onLuarJenisChange = function () {
    const jenis = _luarEl('luarJenisPerlengkapan')?.value;
    if (!jenis) {
      const saldoEl = _luarEl('luarSaldo');
      if (saldoEl) saldoEl.value = 0;
      window._recalcLuarSelisih();
      return;
    }

    // ── Reload data terkini ─────────────────────────────────────────────
    const perlData   = smhPerl.length > 0   ? smhPerl   : loadSmhData(SMH_PERL_KEY);
    const onhandData = smhOnhand.length > 0 ? smhOnhand : loadSmhData(_smhOnhandPlanKey(_auditContext?.planId));
    const hasilData  = loadSmhData(SMH_HASIL_KEY);
    const luarData   = loadSmhData(SMH_LUAR_KEY);

    const normJenis = jenis.trim().toLowerCase();
    const normArea  = (_auditContext?.area || '').toUpperCase().trim();
    const planId    = _auditContext?.planId;

    // ── A. qty_onhand ───────────────────────────────────────────────────
    // Cari kodeModel (NOSIN) di database perlengkapan yang punya jenis ini
    let matchingPerl = perlData.filter(p =>
      (p.namaPerlengkapan || '').trim().toLowerCase() === normJenis &&
      (!normArea || (p.area || '').toUpperCase().trim() === normArea)
    );
    // Fallback: jika tidak ada yang cocok area, pakai semua
    if (!matchingPerl.length) {
      matchingPerl = perlData.filter(p =>
        (p.namaPerlengkapan || '').trim().toLowerCase() === normJenis
      );
    }
    const modelCodes = new Set(
      matchingPerl.map(p => (p.kodeModel || '').replace(/\s/g, '').toUpperCase()).filter(Boolean)
    );

    // Hitung unit onhand yang noMesin-nya cocok dengan kodeModel (NOSIN 5 char)
    let qtyOnhand = 0;
    if (modelCodes.size > 0) {
      onhandData.forEach(u => {
        const pfx5 = (u.noMesin || '').replace(/\s/g, '').slice(0, 5).toUpperCase();
        if (!pfx5) return;
        for (const mc of modelCodes) {
          if (mc === pfx5 || mc.startsWith(pfx5) || pfx5.startsWith(mc)) {
            qtyOnhand++;
            break;
          }
        }
      });
    }

    // ── B. qty_smh_fisik_ada ────────────────────────────────────────────
    // Dari smhHasil: hitung unit unik yang perlengkapan ini ditandai ada=1
    const onhandMesinSet = new Set(
      onhandData.map(u => (u.noMesin || '').replace(/\s/g, '').toUpperCase()).filter(Boolean)
    );
    const countedMesin = new Set();
    let qtySmhFisik = 0;

    hasilData.forEach(h => {
      if (planId && h.auditPlanId && String(h.auditPlanId) !== String(planId)) return;
      const noMesin = (h.noMesin || '').replace(/\s/g, '').toUpperCase();
      if (onhandMesinSet.size > 0 && !onhandMesinSet.has(noMesin)) return;
      const perlAda = (h.perlengkapan || []).some(p =>
        (p.ada === 1 || p.ada === true) &&
        (p.nama || '').trim().toLowerCase() === normJenis
      );
      if (perlAda && !countedMesin.has(noMesin)) {
        countedMesin.add(noMesin);
        qtySmhFisik++;
      }
    });

    // ── C. qty_luar_fisik_tersimpan ─────────────────────────────────────
    // Dari smhLuarFisik: total fisik yang sudah disimpan untuk jenis ini
    let qtyLuarTersimpan = 0;
    luarData.forEach(r => {
      if (planId && r.auditPlanId && String(r.auditPlanId) !== String(planId)) return;
      if ((r.jenisPerlengkapan || '').trim().toLowerCase() !== normJenis) return;
      qtyLuarTersimpan += (parseFloat(r.fisik) || 0);
    });

    // ── Saldo = A − B − C (minimal 0) ──────────────────────────────────
    const totalSaldo = Math.max(0, qtyOnhand - qtySmhFisik - qtyLuarTersimpan);

    const saldoEl = _luarEl('luarSaldo');
    if (saldoEl) saldoEl.value = totalSaldo;
    window._recalcLuarSelisih();
  };

  // Auto hitung selisih
  window._recalcLuarSelisih = function () {
    const saldo  = parseFloat(_luarEl('luarSaldo')?.value)  || 0;
    const fisik  = parseFloat(_luarEl('luarFisik')?.value)   || 0;
    const selEl  = _luarEl('luarSelisih');
    if (selEl) {
      selEl.value = fisik - saldo;
      selEl.style.color = (fisik - saldo) === 0 ? 'var(--success)' : 'var(--danger)';
    }
  };

  // Tombol counter fisik (-/+)
  window._luarFisikChange = function (delta) {
    const el = _luarEl('luarFisik');
    if (!el) return;
    const newVal = Math.max(0, (parseFloat(el.value) || 0) + delta);
    el.value = newVal;
    window._recalcLuarSelisih();
  };

  function addLuarPerlRow() {} // kept for compat, no-op in new form

  function saveLuarFisik() {
    const tgl      = _luarEl('luarTgl')?.value
                     || new Date().toISOString().slice(0,10);
    const jenis    = _luarEl('luarJenisPerlengkapan')?.value;
    const saldo    = parseFloat(_luarEl('luarSaldo')?.value)  || 0;
    const fisik    = parseFloat(_luarEl('luarFisik')?.value)   || 0;
    const selisih  = parseFloat(_luarEl('luarSelisih')?.value) || 0;
    const penjelasan = _luarEl('luarPenjelasan')?.value?.trim() || '';

    if (!jenis) { showToast('Pilih jenis perlengkapan.', 'error'); return; }

    smhLuarFisik.unshift({
      id: Date.now(),
      tgl,
      namaUnitUsaha: _auditContext?.cabang || session.unitUsaha || '—',
      namaPemeriksa: session.displayName,
      jenisPerlengkapan: jenis,
      saldo,
      fisik,
      selisih,
      penjelasan,
      // Audit context link
      auditPlanId:  _auditContext?.planId  || null,
      auditNoSPT:   _auditContext?.noSPT   || null,
      // Backward-compat
      area:         _auditContext?.area || '',
      keterangan:   penjelasan,
      items:        [{ nama: jenis, qty: fisik }],
    });
    saveSmhData(SMH_LUAR_KEY, smhLuarFisik);
    renderAuditSection();
    renderSmhPerl();

    // Reset form fields
    ['luarJenisPerlengkapan','luarSaldo','luarFisik','luarSelisih'].forEach(id => {
      const el = _luarEl(id);
      if (el) el.value = (el.tagName === 'SELECT' ? '' : 0);
    });
    const penEl2 = _luarEl('luarPenjelasan');
    if (penEl2) penEl2.value = '';

    window._closeLuarFisikModal();
    showToast('Data perlengkapan luar fisik berhasil disimpan.', 'success');
  }

  window.deleteLuarFisik = function (id) {
    if (!confirm('Hapus data ini?')) return;
    smhLuarFisik = smhLuarFisik.filter(r => r.id !== id);
    saveSmhData(SMH_LUAR_KEY, smhLuarFisik);
    renderLuarFisik();
    renderSmhPerl();
  };

  function renderLuarFisik() {
    const tbody = document.getElementById('smhLuarBody');
    if (!tbody) return;
    if (!smhLuarFisik.length) {
      tbody.innerHTML = `<tr><td colspan="10"><div class="empty-state"><p>Belum ada data perlengkapan luar fisik.</p></div></td></tr>`;
      return;
    }
    tbody.innerHTML = smhLuarFisik.map((r, i) => {
      const selisih    = r.selisih ?? (r.fisik !== undefined ? r.fisik - r.saldo : '—');
      const selisisCls = selisih === 0 ? 'color:var(--success);font-weight:700'
                       : typeof selisih === 'number' ? 'color:var(--danger);font-weight:700' : '';
      const jenisLabel = r.jenisPerlengkapan || (r.items?.[0]?.nama) || '—';
      return `<tr>
        <td>${i + 1}</td>
        <td style="white-space:nowrap">${r.tgl || '—'}</td>
        <td><strong>${r.namaUnitUsaha || r.area || '—'}</strong></td>
        <td>${r.namaPemeriksa || '—'}</td>
        <td><strong>${jenisLabel}</strong></td>
        <td style="text-align:center">${r.saldo ?? '—'}</td>
        <td style="text-align:center;font-weight:600">${r.fisik ?? '—'}</td>
        <td style="text-align:center;${selisisCls}">${selisih}</td>
        <td style="font-size:.82rem;max-width:160px">${r.penjelasan || r.keterangan || '—'}</td>
        <td><button class="btn-clear-data" style="font-size:.75rem;padding:3px 8px"
            onclick="window.deleteLuarFisik(${r.id})">Hapus</button></td>
      </tr>`;
    }).join('');
  }

  // ── Sync dari pemeriksaan fisik SMH ─────────────────────────────────
  function _checkLuarSyncBanner() {
    const banner = document.getElementById('luarSyncBanner');
    if (!banner) return;
    try {
      const pending = JSON.parse(localStorage.getItem('akta_luar_sync_pending'));
      if (pending && pending.items && pending.items.length) {
        document.getElementById('luarSyncMsg').textContent =
          `Data pemeriksaan fisik tersedia dari No.Mesin: ${pending.noMesin} ` +
          `(${pending.kodeModel} · ${pending.area || '—'}) — ${pending.tgl}. ` +
          `Klik "Terapkan ke Form" untuk mengisi saldo otomatis.`;
        banner.classList.remove('hidden');
        banner.style.display = 'flex';
      } else {
        banner.style.display = 'none';
      }
    } catch { banner.style.display = 'none'; }
  }

  window._dismissLuarSync = function () {
    localStorage.removeItem('akta_luar_sync_pending');
    const banner = document.getElementById('luarSyncBanner');
    if (banner) banner.style.display = 'none';
  };

  window._applySyncToLuar = function () {
    try {
      const pending = JSON.parse(localStorage.getItem('akta_luar_sync_pending'));
      if (!pending || !pending.items) return;
      // Ambil item pertama dari sync sebagai default jenis perlengkapan
      const firstItem = pending.items[0];
      if (firstItem) {
        const jSel = _luarEl('luarJenisPerlengkapan');
        if (jSel) {
          jSel.value = firstItem.nama;
          if (!jSel.value) {
            // Jika tidak ada di dropdown, tambahkan opsi sementara
            const opt = new Option(firstItem.nama, firstItem.nama, true, true);
            jSel.add(opt);
          }
          window._onLuarJenisChange();
        }
      }
      const tglEl = _luarEl('luarTgl');
      if (tglEl && pending.tgl) tglEl.value = pending.tgl;
      window._dismissLuarSync();
      showToast('Data dari pemeriksaan fisik diterapkan ke form.', 'success');
    } catch {}
  };

  window._syncLuarFromScan = function () {
    try {
      const pending = JSON.parse(localStorage.getItem('akta_luar_sync_pending'));
      if (!pending || !pending.items || !pending.items.length) {
        showToast('Belum ada data dari pemeriksaan fisik SMH.', 'info');
        return;
      }
      window._applySyncToLuar();
    } catch {
      showToast('Tidak ada data sinkronisasi tersedia.', 'error');
    }
  };

