  try { renderSmhOnhand(); }   catch(e) { console.error('[init] renderSmhOnhand:', e); }
  try { renderSmhPerl(); }     catch(e) { console.error('[init] renderSmhPerl:', e); }
  try { renderUnitUsaha(); }   catch(e) { console.error('[init] renderUnitUsaha:', e); }
  try { populateOnhandDropdown(); }  catch(e) { console.error('[init] populateOnhandDropdown:', e); }
  try { populateLuarAreaOptions(); } catch(e) { console.error('[init] populateLuarAreaOptions:', e); }
  // Default scan dates to today
  const _today = new Date().toISOString().slice(0, 10);
  const _tglScan = document.getElementById('smhScanTgl');
  const _tglLuar = document.getElementById('luarTgl');
  if (_tglScan && !_tglScan.value) _tglScan.value = _today;
  if (_tglLuar && !_tglLuar.value) _tglLuar.value = _today;

