  // ── Render tab Database Grading ──────────────────────────────
  function renderGradingDbTab() {
    const db    = loadGradingDb();
    const tbody = document.getElementById('gradingDbTableBody');
    const stat  = document.getElementById('gradingDbStat');
    const count = document.getElementById('gradingDbCount');
    const isAdm = (session.role === 'adm' || session.role === 'admin');

    // Permission
    const noPermit  = document.getElementById('gradingDbNoPermit');
    const importWrap = document.getElementById('gradingDbImportWrap');
    if (noPermit && importWrap) {
      if (isAdm) { noPermit.classList.add('hidden'); importWrap.style.display = ''; }
      else        { noPermit.classList.remove('hidden'); importWrap.style.display = 'none'; }
    }

    if (stat)  stat.textContent  = db.length > 0 ? db.length + ' kriteria' : 'Belum ada data';
    if (count) count.textContent = db.length > 0 ? db.length + ' item' : '';
    if (!tbody) return;

    if (!db.length) {
      tbody.innerHTML = '<tr><td colspan="15" style="text-align:center;color:var(--text-secondary);padding:20px">Belum ada data grading. Import file Excel.</td></tr>';
      return;
    }
    const fPct = v => v !== undefined && v !== null && v !== '' ? (isNaN(v) ? v : (parseFloat(v)*100).toFixed(2)+'%') : '—';
    tbody.innerHTML = db.map((r, i) => `
      <tr>
        <td>${i+1}</td>
        <td style="font-family:monospace;font-size:.78rem;color:#4f46e5">${r.dgrading||'—'}</td>
        <td><span style="background:#dbeafe;color:#1e40af;border-radius:4px;padding:1px 6px;font-size:.72rem;font-weight:600">${r.jenis||'—'}</span></td>
        <td>${r.area||'—'}</td>
        <td style="font-weight:600;max-width:180px">${r.namaPemeriksaan||'—'}</td>
        <td style="font-size:.78rem;max-width:220px">${r.hasilPemeriksaan||'—'}</td>
        <td style="text-align:center;font-weight:700;color:${r.nilai<=2?'#166534':r.nilai>=4?'#dc2626':'#b45309'}">${r.nilai||'—'}</td>
        <td style="text-align:right;font-size:.78rem">${fPct(r.bknf)}</td>
        <td style="text-align:right;font-size:.78rem">${fPct(r.pknf)}</td>
        <td style="text-align:right;font-size:.78rem">${fPct(r.bkf)}</td>
        <td style="text-align:right;font-size:.78rem">${fPct(r.pkf)}</td>
        <td style="text-align:right;font-size:.78rem;font-weight:700;color:#4f46e5">${fPct(r.bnknf)}</td>
        <td style="text-align:right;font-size:.78rem">${fPct(r.pnknf)}</td>
        <td style="text-align:right;font-size:.78rem">${fPct(r.bnkf)}</td>
        <td style="text-align:right;font-size:.78rem">${fPct(r.pnkf)}</td>
      </tr>`).join('');
  }

  // ── Import Excel Grading DB ───────────────────────────────────
  function _importGradingDbFile(file) {
    if (!file) return;
    const isAdm = (session.role === 'adm' || session.role === 'admin');
    if (!isAdm) { showToast('Hanya ADM yang dapat mengimport data Grading.', 'error'); return; }

    const reader = new FileReader();
    reader.onload = function(e) {
      try {
        const wb   = XLSX.read(e.target.result, { type: 'binary' });
        const ws   = wb.Sheets[wb.SheetNames[0]];
        const rows = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });
        const data = [];
        const parseNum = v => {
          if (v === '' || v === null || v === undefined) return 0;
          // XLSX kadang mengembalikan number langsung (sudah desimal dari cell %)
          if (typeof v === 'number') return v;
          const s = String(v).trim();
          const hasPercent = s.includes('%');
          const num = parseFloat(s.replace(',', '.').replace('%', '').trim());
          if (isNaN(num)) return 0;
          // Jika ada tanda %, bagi 100 agar jadi desimal (mis: "2,0%" → 0.02)
          return hasPercent ? num / 100 : num;
        };
        for (let i = 1; i < rows.length; i++) {
          const r = rows[i];
          if (!r[3] && !r[4]) continue; // skip empty rows
          data.push({
            dgrading:        String(r[0] || '').trim(),
            jenis:           String(r[1] || '').trim(),
            area:            String(r[2] || '').trim(),
            namaPemeriksaan: String(r[3] || '').trim(),
            hasilPemeriksaan:String(r[4] || '').trim(),
            nilai:           parseInt(r[5]) || 0,
            bknf:            parseNum(r[6]),
            pknf:            parseNum(r[7]),
            bkf:             parseNum(r[8]),
            pkf:             parseNum(r[9]),
            bnknf:           parseNum(r[10]),
            pnknf:           parseNum(r[11]),
            bnkf:            parseNum(r[12]),
            pnkf:            parseNum(r[13]),
          });
        }
        if (!data.length) { showToast('Tidak ada data valid di file.', 'error'); return; }
        saveGradingDb(data);
        renderGradingDbTab();
        showToast(data.length + ' kriteria grading berhasil diimport.', 'success');
      } catch (err) {
        showToast('Gagal membaca file: ' + err.message, 'error');
      }
    };
    reader.readAsBinaryString(file);
  }

  // ── Init Grading DB tab ───────────────────────────────────────
  (function _initGradingDb() {
    const browseEl   = document.getElementById('gradingDbBrowse');
    const fileInput  = document.getElementById('gradingDbFile');
    const dropZone   = document.getElementById('gradingDbDropZone');
    const importBtn  = document.getElementById('btnImportGradingDb');
    const clearBtn   = document.getElementById('btnClearGradingDb');

    if (browseEl && fileInput)  browseEl.addEventListener('click',  () => fileInput.click());
    if (dropZone && fileInput) {
      dropZone.addEventListener('click',    () => fileInput.click());
      dropZone.addEventListener('dragover',  e => { e.preventDefault(); dropZone.style.borderColor='var(--primary)'; });
      dropZone.addEventListener('dragleave', () => dropZone.style.borderColor='');
      dropZone.addEventListener('drop', e => {
        e.preventDefault(); dropZone.style.borderColor='';
        _importGradingDbFile(e.dataTransfer.files[0]);
      });
    }
    if (fileInput) fileInput.addEventListener('change', e => { _importGradingDbFile(e.target.files[0]); fileInput.value=''; });
    if (importBtn) importBtn.addEventListener('click', () => fileInput?.click());
    if (clearBtn)  clearBtn.addEventListener('click', () => {
      if (!confirm('Hapus semua data Database Grading?')) return;
      saveGradingDb([]);
      renderGradingDbTab();
      showToast('Data Grading dihapus.', 'info');
    });

    renderGradingDbTab();
  })();

  // ═══════════════════════════════════════════════════════════════
  //  MODUL DATABASE HET (Harga Eceran Tertinggi)
  // ═══════════════════════════════════════════════════════════════
  const HET_DB_KEY = 'akta_het_db';
  function loadHetDb()  { try { return JSON.parse(localStorage.getItem(HET_DB_KEY)) || []; } catch { return []; } }
  function saveHetDb(d) { localStorage.setItem(HET_DB_KEY, JSON.stringify(d)); window.API?.sync(HET_DB_KEY, d); }

  // Render tabel HET (dengan filter opsional)
  window._hetDbRender = function() {
    const data    = loadHetDb();
    const isAdm   = (session?.role === 'adm' || session?.role === 'admin');
    const statEl  = document.getElementById('hetDbStat');
    const countEl = document.getElementById('hetDbCount');
    const noPermEl   = document.getElementById('hetDbNoPermit');
    const importWrap = document.getElementById('hetDbImportWrap');

    if (noPermEl)   noPermEl.classList.toggle('hidden', isAdm);
    if (importWrap) {
      importWrap.querySelector('#hetDbDropZone')   && (importWrap.querySelector('#hetDbDropZone').style.display   = isAdm ? '' : 'none');
      importWrap.querySelector('.import-actions')  && (importWrap.querySelector('.import-actions').style.display  = isAdm ? '' : 'none');
    }
    if (statEl) statEl.textContent = data.length ? data.length + ' data' : 'Belum ada data';

    window._hetDbFilter();
  };

  window._hetDbFilter = function() {
    const data    = loadHetDb();
    const q       = (document.getElementById('hetDbSearch')?.value || '').toLowerCase().trim();
    const filtered = q
      ? data.filter(r => (r.kodePart||'').toLowerCase().includes(q) || (r.namaPart||'').toLowerCase().includes(q))
      : data;

    const countEl = document.getElementById('hetDbCount');
    if (countEl) countEl.textContent = q ? filtered.length + ' / ' + data.length + ' data' : data.length + ' data';

    const tbody = document.getElementById('hetDbTableBody');
    if (!tbody) return;
    if (!filtered.length) {
      tbody.innerHTML = '<tr><td colspan="6" style="text-align:center;color:var(--text-secondary);padding:20px">Belum ada data HET. Import file Excel.</td></tr>';
      return;
    }
    tbody.innerHTML = filtered.map((r, i) => `
      <tr>
        <td>${i+1}</td>
        <td style="font-family:monospace;font-size:.78rem;color:#4f46e5">${r.kodePart||'—'}</td>
        <td>${r.namaPart||'—'}</td>
        <td style="text-align:center">${r.grupPart||'—'}</td>
        <td style="text-align:right;font-variant-numeric:tabular-nums">${Number(r.het||0).toLocaleString('id-ID')}</td>
        <td style="white-space:nowrap">${r.tglHetBaru||'—'}</td>
      </tr>`).join('');
  };

  function _importHetDbFile(file) {
    if (!file) return;
    const isAdm = (session?.role === 'adm' || session?.role === 'admin');
    if (!isAdm) { showToast('Hanya ADM yang dapat mengimport data HET.', 'error'); return; }
    const reader = new FileReader();
    reader.onload = function(ev) {
      try {
        const wb   = XLSX.read(new Uint8Array(ev.target.result), { type: 'array' });
        const ws   = wb.Sheets[wb.SheetNames[0]];
        const rows = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });
        // Skip header rows: find first row where col A looks like a part code (non-empty, not "Kode")
        const startIdx = rows.findIndex(r => {
          const v = String(r[0]||'').trim();
          return v && !/kode/i.test(v);
        });
        if (startIdx < 0) { showToast('Tidak ada data ditemukan dalam file.', 'error'); return; }
        const data = rows.slice(startIdx).filter(r => String(r[0]||'').trim()).map(r => ({
          kodePart:   String(r[0]||'').trim(),
          namaPart:   String(r[1]||'').trim(),
          grupPart:   String(r[2]||'').trim(),
          het:        parseFloat(String(r[3]||'0').replace(/[^0-9.]/g,'')) || 0,
          tglHetBaru: String(r[4]||'').trim(),
        }));
        if (!data.length) { showToast('Tidak ada data valid dalam file.', 'error'); return; }
        saveHetDb(data);
        window._hetDbRender();
        showToast(data.length + ' data HET berhasil diimport.', 'success');
      } catch(e) {
        showToast('Gagal membaca file: ' + e.message, 'error');
      }
    };
    reader.readAsArrayBuffer(file);
  }

  // Init HET DB tab
  (function _initHetDb() {
    const browseEl  = document.getElementById('hetDbBrowse');
    const fileInput = document.getElementById('hetDbFile');
    const dropZone  = document.getElementById('hetDbDropZone');
    const importBtn = document.getElementById('btnImportHetDb');
    const clearBtn  = document.getElementById('btnClearHetDb');

    if (browseEl && fileInput) browseEl.addEventListener('click', () => fileInput.click());
    if (dropZone) {
      dropZone.addEventListener('dragover',  e => { e.preventDefault(); dropZone.classList.add('dragover'); });
      dropZone.addEventListener('dragleave', ()  => dropZone.classList.remove('dragover'));
      dropZone.addEventListener('drop',      e  => { e.preventDefault(); dropZone.classList.remove('dragover'); _importHetDbFile(e.dataTransfer.files[0]); });
    }
    if (fileInput) fileInput.addEventListener('change', e => { _importHetDbFile(e.target.files[0]); fileInput.value = ''; });
    if (importBtn) importBtn.addEventListener('click',  () => fileInput?.click());
    if (clearBtn)  clearBtn.addEventListener('click',   () => {
      if (!confirm('Hapus semua data Database HET?')) return;
      saveHetDb([]);
      window._hetDbRender();
      showToast('Data HET dihapus.', 'info');
    });
    window._hetDbRender();
  })();

  // ── Helper: cari HET untuk kode part tertentu ────────────────
  window.getHetByKode = function(kodePart) {
    const r = loadHetDb().find(x => x.kodePart === String(kodePart).trim());
    return r || null;
  };

  // ── Helper: tentukan kolom kontribusi berdasarkan BBNKB & Fraud ──
  // !BBNKB + !Fraud → PKNF
  // !BBNKB + Fraud  → PKF
  //  BBNKB + !Fraud → PNKNF
  //  BBNKB + Fraud  → PNKF
  function _gradingGetKontribusi(item, bbnkb, fraud) {
    if (!bbnkb && !fraud) return item.pknf  || 0;
    if (!bbnkb &&  fraud) return item.pkf   || 0;
    if ( bbnkb && !fraud) return item.pnknf || 0;
    return item.pnkf || 0;
  }

  // ── Helper: nama kolom yang aktif ────────────────────────────────
  function _gradingKolomLabel(bbnkb, fraud) {
    if (!bbnkb && !fraud) return 'PKNF';
    if (!bbnkb &&  fraud) return 'PKF';
    if ( bbnkb && !fraud) return 'PNKNF';
    return 'PNKF';
  }

  // ── State modal grading ───────────────────────────────────────
  let _gradingTaskId  = null;
  let _gradingPlanId  = null;
  let _gradingItems   = [];   // item list yang sedang diisi

  // ── Helper: hitung nilai grading (RATA-RATA, tidak diakumulasi) ──
  // Setiap item memiliki nilai terkunci berdasarkan area (tidak dijumlahkan).
  // Nilai akhir = rata-rata dari semua kontribusi item yang dipilih.
  function _gradingCalcNilai(items) {
    if (!items.length) return 0;
    const sum = items.reduce((s, it) => s + (it.kontribusi || 0), 0);
    return sum / items.length; // rata-rata, bukan penjumlahan
  }

  // ── Helper: format display nilai (desimal mentah dari database) ──
  // Menampilkan nilai asli dari database, bukan dikonversi ke persen
  function _fmtGradingVal(v) {
    if (v === undefined || v === null || isNaN(v)) return '0';
    // Tampilkan dengan desimal yang sesuai (hilangkan trailing zeros berlebih)
    const n = Number(v);
    // Gunakan hingga 4 desimal, hapus trailing zero
    return parseFloat(n.toFixed(4)).toString();
  }

  // ── Render summary nilai ──────────────────────────────────────
  function _renderGradingNilaiSummary(bbnkb, fraud) {
    const el   = document.getElementById('gradingNilaiSummary');
    if (!el)   return;
    const n    = _gradingItems.length;
    const rata = _gradingCalcNilai(_gradingItems);
    const kolom = _gradingKolomLabel(bbnkb, fraud);
    const vals  = _gradingItems.map(it => it.kontribusi || 0);
    const minV  = n ? Math.min(...vals) : 0;
    const maxV  = n ? Math.max(...vals) : 0;
    el.innerHTML = `
      <div style="background:#f0f9ff;border:1.5px solid #bae6fd;border-radius:8px;padding:12px 16px">
        <div style="display:flex;align-items:center;gap:12px">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#0369a1" stroke-width="2"><polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/></svg>
          <div style="flex:1">
            <div style="font-size:.72rem;text-transform:uppercase;color:#0369a1;font-weight:700;letter-spacing:.05em">
              Rata-rata Nilai Grading (${kolom})
              <span style="font-size:.65rem;font-weight:400;color:#64748b;margin-left:6px">— tidak diakumulasi, dikunci per area</span>
            </div>
            <div style="font-size:1.6rem;font-weight:800;color:#0369a1">${_fmtGradingVal(rata)}</div>
            <div style="font-size:.72rem;color:#64748b;margin-top:2px">
              ${n} item &nbsp;·&nbsp;
              ${n > 1 ? `Rentang: ${_fmtGradingVal(minV)} – ${_fmtGradingVal(maxV)}` : 'nilai terkunci dari database'}
            </div>
          </div>
          ${bbnkb ? '<span style="background:#fef3c7;color:#b45309;padding:3px 10px;border-radius:8px;font-size:.78rem;font-weight:700">BBNKB</span>' : ''}
          ${fraud  ? '<span style="background:#fee2e2;color:#dc2626;padding:3px 10px;border-radius:8px;font-size:.78rem;font-weight:700">FRAUD</span>' : ''}
        </div>
        ${n > 1 ? `
        <div style="margin-top:8px;padding-top:8px;border-top:1px dashed #bae6fd;font-size:.75rem;color:#0369a1">
          Detail:
          ${_gradingItems.map(it => `<span style="margin-right:8px">${it.namaPemeriksaan.split(' ').slice(0,3).join(' ')}: <strong>${_fmtGradingVal(it.kontribusi)}</strong></span>`).join('')}
        </div>` : ''}
      </div>`;
  }

  // ── Render items list ─────────────────────────────────────────
  function _renderGradingItemsList(bbnkb, fraud) {
    const el = document.getElementById('gradingItemsList');
    if (!el) return;
    if (!_gradingItems.length) {
      el.innerHTML = '<div style="text-align:center;color:var(--text-secondary);font-size:.82rem;padding:14px 0">Belum ada item pemeriksaan ditambahkan.</div>';
      return;
    }
    const kolom = _gradingKolomLabel(bbnkb, fraud);
    el.innerHTML = `
      <table class="kas-table">
        <thead><tr>
          <th>No</th><th>Nama Pemeriksaan</th><th>Hasil / Temuan</th>
          <th style="text-align:center">Nilai (1-5)</th>
          <th style="text-align:right">Nilai ${kolom} (dari DB)</th>
          <th></th>
        </tr></thead>
        <tbody>
          ${_gradingItems.map((it, i) => `
            <tr>
              <td>${i+1}</td>
              <td style="font-weight:600;font-size:.82rem">${it.namaPemeriksaan}</td>
              <td style="font-size:.78rem;color:var(--text-secondary)">${it.hasilPemeriksaan}</td>
              <td style="text-align:center;font-weight:700;color:${it.nilai<=2?'#166534':it.nilai>=4?'#dc2626':'#b45309'}">${it.nilai}</td>
              <td style="text-align:right;font-weight:800;color:#0369a1;font-size:.92rem">${_fmtGradingVal(it.kontribusi)}</td>
              <td><button onclick="window._removeGradingItem(${i})" style="background:#fee2e2;border:none;border-radius:4px;padding:2px 8px;cursor:pointer;color:#dc2626;font-size:.72rem">✕</button></td>
            </tr>`).join('')}
        </tbody>
      </table>`;
    _renderGradingNilaiSummary(bbnkb, fraud);
  }

  // ════════════════════════════════════════════════════
  // PICA (Problem Identification & Corrective Action)
  // ════════════════════════════════════════════════════

  // _picaData: map idx → { currentCondition } untuk sesi grading aktif
  let _picaData = {};

  // ── Render PICA forms untuk setiap item nilai 1-2 ──────────────
  function _renderGradingPicaForms() {
    const section = document.getElementById('gradingPicaSection');
    const formsEl = document.getElementById('gradingPicaForms');
    if (!section || !formsEl) return;

    const picaItems = _gradingItems
      .map((it, i) => ({ ...it, _idx: i }))
      .filter(it => it.nilai <= 2);

    if (!picaItems.length) {
      section.style.display = 'none';
      return;
    }

    section.style.display = '';
    formsEl.innerHTML = picaItems.map(it => `
      <div style="background:#fff;border:1px solid #fca5a5;border-radius:7px;padding:12px 14px">
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px">
          <div>
            <div style="font-size:.68rem;text-transform:uppercase;color:#dc2626;font-weight:700;margin-bottom:3px">Pemeriksaan PICA</div>
            <div style="font-size:.85rem;font-weight:700;color:#1a1a1a">${it.namaPemeriksaan}</div>
          </div>
          <div>
            <div style="font-size:.68rem;text-transform:uppercase;color:#dc2626;font-weight:700;margin-bottom:3px">Hasil Temuan (Nilai ${it.nilai})</div>
            <div style="font-size:.78rem;color:#374151">${it.hasilPemeriksaan}</div>
          </div>
        </div>
        <div class="field-group" style="margin:0">
          <label class="pem-label" style="color:#dc2626">CURRENT CONDITION <span class="req">*</span>
            <span style="font-size:.65rem;font-weight:400;color:#64748b">— Kondisi saat ini / temuan auditor</span>
          </label>
          <textarea class="kas-input pica-condition-input" data-item-idx="${it._idx}"
                    rows="2" placeholder="Deskripsikan kondisi aktual yang ditemukan..."
                    style="resize:vertical;min-height:60px"
                    onchange="window._onPicaConditionChange(${it._idx}, this.value)"
                    >${_picaData[it._idx]?.currentCondition || ''}</textarea>
        </div>
      </div>`).join('');
  }

  window._onPicaConditionChange = function(idx, val) {
    if (!_picaData[idx]) _picaData[idx] = {};
    _picaData[idx].currentCondition = val;
  };

  // ── State PICA Response Modal ──────────────────────────────────
  let _picaResponseTarget = null; // { sessionId, itemIdx, planId }

  window._openPicaResponseModal = function(sessionId, itemIdx) {
    const sessions = loadGradingSessions();
    const sess = sessions.find(s => s.id === sessionId);
    if (!sess) return;
    const item = (sess.items || [])[itemIdx];
    if (!item || !item.pica) return;
    _picaResponseTarget = { sessionId, itemIdx, planId: sess.planId };

    const infoEl = document.getElementById('picaResponseInfo');
    if (infoEl) {
      infoEl.innerHTML = `
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">
          <div><span style="font-size:.68rem;text-transform:uppercase;color:#dc2626;font-weight:700">Pemeriksaan PICA</span>
               <div style="font-weight:700;margin-top:2px">${item.namaPemeriksaan}</div></div>
          <div><span style="font-size:.68rem;text-transform:uppercase;color:#dc2626;font-weight:700">Nilai / Hasil</span>
               <div style="margin-top:2px"><strong>${item.nilai}</strong> — ${item.hasilPemeriksaan}</div></div>
          <div style="grid-column:1/-1"><span style="font-size:.68rem;text-transform:uppercase;color:#6b7280;font-weight:700">Current Condition (Auditor)</span>
               <div style="margin-top:2px;font-style:italic;color:#374151">${item.pica.currentCondition || '—'}</div></div>
        </div>`;
    }
    // Pre-fill existing response
    const p = item.pica;
    document.getElementById('picaProblemIdentification').value = p.problemIdentification || '';
    document.getElementById('picaCorrectiveAction').value      = p.correctiveAction || '';
    document.getElementById('picaDeadlineCorrective').value    = p.deadlineCorrective || '';
    document.getElementById('picaPicCorrective').value         = p.picCorrective || '';
    document.getElementById('picaRelationShipDept').value      = p.relationShipDept || '';
    document.getElementById('picaRelationShip').value          = p.relationShip || '';

    document.getElementById('picaResponseModal').classList.remove('hidden');
    document.getElementById('picaResponseModal').style.display = 'flex';
  };

  window._closePicaResponseModal = function() {
    const m = document.getElementById('picaResponseModal');
    if (m) { m.classList.add('hidden'); m.style.display = ''; }
    _picaResponseTarget = null;
  };

  window._savePicaResponse = function() {
    if (!_picaResponseTarget) return;
    const probId = document.getElementById('picaProblemIdentification')?.value.trim();
    const corAct = document.getElementById('picaCorrectiveAction')?.value.trim();
    const deadln = document.getElementById('picaDeadlineCorrective')?.value;
    const pic    = document.getElementById('picaPicCorrective')?.value.trim();
    if (!probId) { showToast('Isi Problem Identification.', 'error'); return; }
    if (!corAct) { showToast('Isi Corrective Action.', 'error'); return; }
    if (!deadln) { showToast('Isi Deadline Corrective.', 'error'); return; }
    if (!pic)    { showToast('Isi PIC Corrective.', 'error'); return; }

    const sessions = loadGradingSessions();
    const sIdx = sessions.findIndex(s => s.id === _picaResponseTarget.sessionId);
    if (sIdx < 0) return;
    const iIdx = _picaResponseTarget.itemIdx;
    if (!sessions[sIdx].items[iIdx].pica) sessions[sIdx].items[iIdx].pica = {};
    Object.assign(sessions[sIdx].items[iIdx].pica, {
      problemIdentification: probId,
      correctiveAction:      corAct,
      deadlineCorrective:    deadln,
      picCorrective:         pic,
      relationShipDept:      document.getElementById('picaRelationShipDept')?.value.trim() || '',
      relationShip:          document.getElementById('picaRelationShip')?.value.trim() || '',
      status:                'completed',
      respondedBy:           session.username,
      respondedAt:           new Date().toISOString(),
    });
    saveGradingSessions(sessions);
    window._closePicaResponseModal();
    showToast('Response PICA berhasil disimpan.', 'success');
    renderAuditSection();
    // Refresh Task section jika sedang aktif
    const activeSec = document.querySelector('.content-section:not(.hidden)');
    if (activeSec?.id === 'section-task') renderTaskSection();
  };

  // Tutup PICA modal saat klik overlay
  document.getElementById('picaResponseModal')?.addEventListener('click', function(e) {
    if (e.target === this) window._closePicaResponseModal();
  });

  // ── Detail Grading Modal ──────────────────────────────────────
  window._openGradingDetailModal = function(planId) {
    const el = document.getElementById('gradingDetailContent');
    if (!el) return;

    const gradSessions = loadGradingSessions().filter(s => String(s.planId) === String(planId));
    if (!gradSessions.length) {
      el.innerHTML = '<div style="text-align:center;color:var(--text-secondary);padding:40px">Belum ada penilaian grading untuk plan ini.</div>';
    } else {
      el.innerHTML = gradSessions.map((gs, si) => {
        const kolom = _gradingKolomLabel(gs.bbnkb||false, gs.fraud||false);
        const picaItems = (gs.items||[]).filter(it => it.pica);
        const avgVal = _fmtGradingVal(gs.nilaiTotal||0);

        const rowsHtml = (gs.items||[]).map((it, i) => {
          const valClr = it.nilai <= 2 ? '#166534' : it.nilai >= 4 ? '#dc2626' : '#b45309';
          const valBg  = it.nilai <= 2 ? '#dcfce7'  : it.nilai >= 4 ? '#fee2e2'  : '#fef3c7';
          const hasPica = !!it.pica;
          return `<tr>
            <td style="text-align:center;padding:6px 8px">${i+1}</td>
            <td style="padding:6px 8px;font-weight:600">${it.namaPemeriksaan}</td>
            <td style="padding:6px 8px;font-size:.78rem;color:#374151;max-width:320px">${it.hasilPemeriksaan}</td>
            <td style="padding:6px 8px;text-align:center">
              <span style="background:${valBg};color:${valClr};padding:2px 8px;border-radius:9px;font-weight:800;font-size:.85rem">${it.nilai}</span>
            </td>
            <td style="padding:6px 8px;text-align:right;font-weight:700;color:#0369a1">${_fmtGradingVal(it.kontribusi||0)}</td>
            <td style="padding:6px 8px;text-align:center">
              ${hasPica
                ? `<span style="font-size:.72rem;font-weight:700;padding:2px 8px;border-radius:8px;background:${it.pica.status==='completed'?'#dcfce7':'#fee2e2'};color:${it.pica.status==='completed'?'#166534':'#dc2626'}">
                    ${it.pica.status==='completed'?'✓ Selesai':'⏳ Pending'}
                   </span>`
                : '<span style="font-size:.72rem;color:#94a3b8">—</span>'}
            </td>
          </tr>`;
        }).join('');

        // PICA detail
        const picaDetailHtml = picaItems.length ? `
          <div style="margin-top:16px">
            <div style="font-size:.78rem;font-weight:700;color:#dc2626;text-transform:uppercase;letter-spacing:.04em;margin-bottom:8px;display:flex;align-items:center;gap:5px">
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/></svg>
              Detail PICA (${picaItems.length} item)
            </div>
            ${picaItems.map((it, pi) => {
              const realIdx = (gs.items||[]).indexOf(it);
              const st = it.pica.status;
              return `<div style="border:1px solid ${st==='completed'?'#86efac':'#fca5a5'};border-radius:8px;padding:12px 14px;background:${st==='completed'?'#f0fdf4':'#fff1f2'};margin-bottom:8px">
                <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;font-size:.8rem;margin-bottom:8px">
                  <div><span style="font-size:.68rem;text-transform:uppercase;color:#6b7280;font-weight:700">Pemeriksaan</span>
                       <div style="font-weight:700;margin-top:2px">${it.namaPemeriksaan}</div></div>
                  <div><span style="font-size:.68rem;text-transform:uppercase;color:#6b7280;font-weight:700">Status</span>
                       <div style="margin-top:2px"><span style="font-weight:700;color:${st==='completed'?'#166534':'#dc2626'}">${st==='completed'?'✓ Selesai':'⏳ Menunggu Response'}</span></div></div>
                  <div style="grid-column:1/-1"><span style="font-size:.68rem;text-transform:uppercase;color:#dc2626;font-weight:700">Current Condition (Auditor)</span>
                       <div style="margin-top:2px">${it.pica.currentCondition||'—'}</div></div>
                </div>
                ${st==='completed' ? `
                <div style="border-top:1px dashed #86efac;padding-top:10px;margin-top:4px;display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:8px;font-size:.8rem">
                  <div><span style="font-size:.68rem;text-transform:uppercase;color:#0369a1;font-weight:700">Problem Identification</span>
                       <div style="margin-top:2px">${it.pica.problemIdentification||'—'}</div></div>
                  <div><span style="font-size:.68rem;text-transform:uppercase;color:#0369a1;font-weight:700">Corrective Action</span>
                       <div style="margin-top:2px">${it.pica.correctiveAction||'—'}</div></div>
                  <div><span style="font-size:.68rem;text-transform:uppercase;color:#0369a1;font-weight:700">Deadline Corrective</span>
                       <div style="margin-top:2px;font-weight:700;color:#166534">${it.pica.deadlineCorrective||'—'}</div></div>
                  <div><span style="font-size:.68rem;text-transform:uppercase;color:#0369a1;font-weight:700">PIC Corrective</span>
                       <div style="margin-top:2px">${it.pica.picCorrective||'—'}</div></div>
                  ${it.pica.relationShipDept ? `<div><span style="font-size:.68rem;text-transform:uppercase;color:#0369a1;font-weight:700">Relation Ship Dept</span>
                       <div style="margin-top:2px">${it.pica.relationShipDept}</div></div>` : ''}
                  ${it.pica.relationShip ? `<div><span style="font-size:.68rem;text-transform:uppercase;color:#0369a1;font-weight:700">Relation Ship</span>
                       <div style="margin-top:2px">${it.pica.relationShip}</div></div>` : ''}
                </div>` : `
                <div style="margin-top:6px;font-size:.78rem;color:#6b7280">Response belum diisi oleh unit usaha.</div>`}
              </div>`;
            }).join('')}
          </div>` : '';

        return `
          <div style="margin-bottom:${si < gradSessions.length-1 ? '20px' : '0'}">
            <!-- Header session -->
            <div style="background:#1e3a5f;color:#fff;border-radius:8px 8px 0 0;padding:12px 16px;display:flex;flex-wrap:wrap;align-items:center;gap:10px">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/></svg>
              <span style="font-weight:700;font-size:.95rem">Penilaian Grading ${gradSessions.length > 1 ? '#'+(si+1) : ''}</span>
              <span style="font-size:.8rem;opacity:.8">${gs.tanggal||'—'}</span>
              <div style="margin-left:auto;display:flex;gap:6px;flex-wrap:wrap">
                <span style="background:rgba(255,255,255,.2);border-radius:6px;padding:2px 10px;font-size:.78rem">${gs.jenis}</span>
                <span style="background:rgba(255,255,255,.2);border-radius:6px;padding:2px 10px;font-size:.78rem">Area: ${gs.area||'—'}</span>
                ${gs.bbnkb ? '<span style="background:#fef3c7;color:#b45309;border-radius:6px;padding:2px 10px;font-size:.78rem;font-weight:700">BBNKB</span>' : ''}
                ${gs.fraud  ? '<span style="background:#fee2e2;color:#dc2626;border-radius:6px;padding:2px 10px;font-size:.78rem;font-weight:700">FRAUD</span>' : ''}
              </div>
            </div>

            <!-- Info row -->
            <div style="background:#f0f9ff;border:1px solid #bae6fd;border-top:none;padding:10px 16px;display:flex;flex-wrap:wrap;gap:16px;font-size:.82rem">
              <div><span style="color:#6b7280">Kolom Nilai:</span> <strong style="color:#0369a1">${kolom}</strong></div>
              <div><span style="color:#6b7280">Rata-rata:</span> <strong style="color:#0369a1;font-size:.95rem">${avgVal}</strong></div>
              <div><span style="color:#6b7280">Pembuat:</span> ${gs.pembuat||gs.savedBy||'—'}</div>
              <div><span style="color:#6b7280">Cabang:</span> ${gs.cabangGrading||'—'}</div>
              ${gs.fraud && gs.jenisFraud?.length ? `<div><span style="color:#dc2626;font-weight:700">Jenis Fraud:</span> ${gs.jenisFraud.join(', ')}</div>` : ''}
            </div>

            <!-- Tabel item -->
            <div style="border:1px solid #e5e7eb;border-top:none;border-radius:0 0 8px 8px;overflow:hidden">
              <table style="width:100%;border-collapse:collapse;font-size:.82rem">
                <thead>
                  <tr style="background:#f8fafc;border-bottom:2px solid #e5e7eb">
                    <th style="padding:8px;text-align:center;width:40px">No</th>
                    <th style="padding:8px;text-align:left">Nama Pemeriksaan</th>
                    <th style="padding:8px;text-align:left">Hasil / Temuan</th>
                    <th style="padding:8px;text-align:center;width:70px">Nilai</th>
                    <th style="padding:8px;text-align:right;width:90px">${kolom}</th>
                    <th style="padding:8px;text-align:center;width:90px">PICA</th>
                  </tr>
                </thead>
                <tbody>${rowsHtml}</tbody>
                <tfoot>
                  <tr style="background:#f0f9ff;border-top:2px solid #bae6fd;font-weight:700">
                    <td colspan="4" style="padding:8px 16px;text-align:right;color:#0369a1">Rata-rata ${kolom}:</td>
                    <td style="padding:8px;text-align:right;color:#0369a1;font-size:.95rem">${avgVal}</td>
                    <td></td>
                  </tr>
                </tfoot>
              </table>
            </div>

            ${picaDetailHtml}
          </div>`;
      }).join('<hr style="border:none;border-top:2px dashed var(--border);margin:20px 0">');
    }

    document.getElementById('gradingDetailModal').classList.remove('hidden');
    document.getElementById('gradingDetailModal').style.display = 'flex';
  };

  window._closeGradingDetailModal = function() {
    const m = document.getElementById('gradingDetailModal');
    if (m) { m.classList.add('hidden'); m.style.display = ''; }
  };

  document.getElementById('gradingDetailModal')?.addEventListener('click', function(e) {
    if (e.target === this) window._closeGradingDetailModal();
  });

  // ── END PICA ──

  // ── Event: Pilih Pemeriksaan → isi dropdown Hasil (5 pilihan per Nama + Area) ──
  window._onGradingPemeriksaanChange = function() {
    const selP  = document.getElementById('gradingSelectPemeriksaan');
    const selH  = document.getElementById('gradingSelectHasil');
    const jenis = document.querySelector('.grading-jenis-btn.active')?.dataset.jenis || '';
    const area  = document.getElementById('gradingArea')?.value || '';
    const bbnkb = document.getElementById('gradingBbnkb')?.checked || false;
    if (!selP || !selH) return;
    const nama = selP.value;
    if (!nama) { selH.innerHTML = '<option value="">— Pilih Hasil (5 pilihan) —</option>'; return; }

    // Peringatan jika area belum dipilih
    if (!area) {
      selH.innerHTML = '<option value="">— Pilih Area terlebih dahulu —</option>';
      showToast('Pilih Area terlebih dahulu agar hasil temuan muncul.', 'error');
      return;
    }

    const db = loadGradingDb().filter(r => {
      const namaMatch = r.namaPemeriksaan === nama;
      const jenisOk   = _gradingJenisMatch(r.jenis, jenis);
      const areaOk    = _gradingAreaMatch(r.area, area);
      return namaMatch && jenisOk && areaOk;
    }).sort((a, b) => b.nilai - a.nilai); // urut nilai 5→1

    // Maksimal 5 pilihan (satu per nilai 1-5)
    const seen = new Set();
    const limited = db.filter(r => { if (seen.has(r.nilai)) return false; seen.add(r.nilai); return true; });

    if (!limited.length) {
      selH.innerHTML = '<option value="">— Tidak ada data untuk area ini —</option>';
      return;
    }

    selH.innerHTML = '<option value="">— Pilih Hasil (5 pilihan) —</option>' +
      limited.map(r =>
        `<option value="${r.dgrading}">[${r.nilai}] ${r.hasilPemeriksaan}</option>`
      ).join('');
  };

  // ── Event: Tambah Item ────────────────────────────────────────
  window._addGradingItem = function() {
    const selP   = document.getElementById('gradingSelectPemeriksaan');
    const selH   = document.getElementById('gradingSelectHasil');
    const bbnkb  = document.getElementById('gradingBbnkb')?.checked || false;
    const fraud  = document.getElementById('gradingFraud')?.checked  || false;
    if (!selP?.value) { showToast('Pilih Nama Pemeriksaan terlebih dahulu.', 'error'); return; }
    if (!selH?.value) { showToast('Pilih Hasil Pemeriksaan.', 'error'); return; }

    const db   = loadGradingDb();
    const item = db.find(r => r.dgrading === selH.value);
    if (!item) { showToast('Item tidak ditemukan di database.', 'error'); return; }

    // Tidak boleh duplikat namaPemeriksaan dalam sesi ini
    if (_gradingItems.some(it => it.namaPemeriksaan === item.namaPemeriksaan)) {
      showToast(`"${item.namaPemeriksaan}" sudah ditambahkan dalam sesi ini.`, 'error');
      return;
    }

    _gradingItems.push({
      dgrading:         item.dgrading,
      namaPemeriksaan:  item.namaPemeriksaan,
      hasilPemeriksaan: item.hasilPemeriksaan,
      nilai:            item.nilai,
      kontribusi:       _gradingGetKontribusi(item, bbnkb, fraud),
    });
    _renderGradingItemsList(bbnkb, fraud);
    _renderGradingPicaForms();

    // Refresh dropdown Pemeriksaan — hilangkan yg sudah terpakai
    const jenis = document.querySelector('.grading-jenis-btn.active')?.dataset.jenis || 'SO';
    _populateGradingPemeriksaanDropdown(jenis);
  };

  // ── Event: Hapus Item ─────────────────────────────────────────
  window._removeGradingItem = function(idx) {
    // Hapus PICA data untuk idx ini dan reindex
    const newPicaData = {};
    _gradingItems.splice(idx, 1);
    _gradingItems.forEach((_, i) => {
      const oldIdx = i >= idx ? i + 1 : i;
      if (_picaData[oldIdx]) newPicaData[i] = _picaData[oldIdx];
    });
    _picaData = newPicaData;

    const bbnkb = document.getElementById('gradingBbnkb')?.checked || false;
    const fraud  = document.getElementById('gradingFraud')?.checked  || false;
    _renderGradingItemsList(bbnkb, fraud);
    _renderGradingPicaForms();
    // Refresh dropdown agar item yang dihapus muncul kembali
    const jenis = document.querySelector('.grading-jenis-btn.active')?.dataset.jenis || 'SO';
    _populateGradingPemeriksaanDropdown(jenis);
  };

  // ── Render history grading per plan ──────────────────────────
  function _renderGradingHistory(planId) {
    const el       = document.getElementById('gradingHistory');
    if (!el) return;
    const sessions = loadGradingSessions().filter(s => String(s.planId) === String(planId));
    if (!sessions.length) { el.innerHTML = ''; return; }
    el.innerHTML = `<div style="margin-bottom:10px">
      <div class="status-log-title" style="margin-bottom:8px">Riwayat Penilaian Grading (${sessions.length})</div>
      ${sessions.map(s => {
        const kolom = _gradingKolomLabel(s.bbnkb, s.fraud);
        return `<div style="background:#f9fafb;border:1px solid var(--border);border-radius:8px;padding:10px 14px;margin-bottom:8px;font-size:.82rem">
          <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;margin-bottom:6px">
            <div>
              <strong>${s.jenis}</strong>
              <span style="background:#dbeafe;color:#1e40af;font-size:.72rem;padding:1px 7px;border-radius:10px;margin-left:6px">${s.area||'—'}</span>
              ${s.bbnkb ? '<span style="background:#fef3c7;color:#b45309;font-size:.72rem;padding:1px 7px;border-radius:10px;margin-left:4px">BBNKB</span>' : ''}
              ${s.fraud  ? '<span style="background:#fee2e2;color:#dc2626;font-size:.72rem;padding:1px 7px;border-radius:10px;margin-left:4px">FRAUD</span>' : ''}
              <span style="color:var(--text-secondary);margin-left:8px">${s.tanggal||''}</span>
              <span style="color:var(--text-secondary);font-size:.75rem;margin-left:6px">oleh ${s.savedBy||'—'}</span>
            </div>
            <div style="display:flex;align-items:center;gap:8px">
              <span style="font-size:.9rem;font-weight:800;color:#0369a1">Rata-rata: ${_fmtGradingVal(s.nilaiTotal||0)} <span style="font-size:.72rem;font-weight:400">(${kolom})</span></span>
              <button onclick="window._deleteGradingSession('${s.id}')" style="background:#fee2e2;border:none;border-radius:4px;padding:3px 10px;cursor:pointer;font-size:.75rem;color:#dc2626">Hapus</button>
            </div>
          </div>
          <div style="font-size:.78rem;color:var(--text-secondary)">${(s.items||[]).length} item &nbsp;·&nbsp; Cabang: ${s.cabangGrading||'—'} &nbsp;·&nbsp; Area: ${s.area||'—'}</div>
          ${s.fraud && s.jenisFraud?.length ? `<div style="margin-top:4px;font-size:.75rem;color:#dc2626">Fraud: ${s.jenisFraud.join(', ')}${s.keteranganFraud ? ' — '+s.keteranganFraud : ''}</div>` : ''}
          ${(() => {
            const picaItems = (s.items||[]).filter(it => it.pica);
            if (!picaItems.length) return '';
            const isBranch = ['so','csc','whs'].includes(session.role);
            return picaItems.map((it, ii) => {
              const realIdx = (s.items||[]).indexOf(it);
              const st = it.pica.status;
              const stColor = st === 'completed' ? '#166534' : '#b45309';
              const stBg    = st === 'completed' ? '#dcfce7'  : '#fef3c7';
              const stLbl   = st === 'completed' ? '✓ Selesai' : '⏳ Menunggu Response';
              return `<div style="margin-top:6px;padding:8px 10px;background:#fff1f2;border:1px solid #fca5a5;border-radius:6px;font-size:.78rem">
                <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:6px">
                  <div>
                    <span style="font-weight:700;color:#dc2626">PICA:</span>
                    <strong>${it.namaPemeriksaan}</strong>
                    <span style="margin-left:6px;font-size:.72rem;background:${stBg};color:${stColor};padding:1px 7px;border-radius:8px;font-weight:700">${stLbl}</span>
                  </div>
                  ${(isBranch || session.role === 'auditor' || session.role === 'admin')
                    ? `<button onclick="window._openPicaResponseModal('${s.id}',${realIdx})"
                               style="background:${st==='completed'?'#dcfce7':'#dc2626'};color:${st==='completed'?'#166534':'#fff'};border:none;border-radius:5px;padding:3px 10px;cursor:pointer;font-size:.73rem;font-weight:700">
                         ${st==='completed'?'Lihat/Edit Response':'Isi Response PICA'}
                       </button>` : ''}
                </div>
                ${it.pica.currentCondition ? `<div style="margin-top:4px;color:#374151"><em>Kondisi:</em> ${it.pica.currentCondition}</div>` : ''}
                ${st==='completed' ? `<div style="margin-top:2px;color:#166534;font-size:.73rem">
                  Problem: ${it.pica.problemIdentification||'—'} &nbsp;·&nbsp;
                  PIC: ${it.pica.picCorrective||'—'} &nbsp;·&nbsp;
                  Deadline: ${it.pica.deadlineCorrective||'—'}
                </div>` : ''}
              </div>`;
            }).join('');
          })()}
        </div>`;
      }).join('')}
    </div>`;
  }

  // ── Hapus satu session grading ────────────────────────────────
  window._deleteGradingSession = function(id) {
    if (!confirm('Hapus data grading ini?')) return;
    const data = loadGradingSessions().filter(s => s.id !== id);
    saveGradingSessions(data);
    _renderGradingHistory(_gradingPlanId);
    showToast('Data grading dihapus.', 'info');
  };

  // ── Mapping UI jenis → nilai DB (Excel bisa punya nama berbeda) ─
  const _JENIS_DB_ALIASES = {
    'SO':       ['SO', 'Cabang', 'cabang', 'so', 'showroom', 'sales office', 'so cabang', 'sales', 'toko'],
    'CSC':      ['CSC', 'Bengkel', 'bengkel', 'csc', 'customer service', 'workshop', 'service'],
    'WHS PART': ['WHS PART', 'WHS Part', 'whs part', 'whs-part', 'warehouse part', 'gudang part', 'whs'],
    'WHS UNIT': ['WHS UNIT', 'WHS Unit', 'whs unit', 'whs-unit', 'warehouse unit', 'gudang unit'],
    'Lain-Lain':['Lain-Lain', 'Lain Lain', 'lain-lain', 'lainlain', 'other', 'lain', 'lainnya'],
  };

  function _gradingJenisMatch(dbJenis, uiJenis) {
    if (!uiJenis || uiJenis === 'Lain-Lain') return true;
    const aliases = _JENIS_DB_ALIASES[uiJenis] || [uiJenis];
    const norm = (dbJenis || '').toLowerCase().trim();
    // Exact match first, then partial (db contains alias or alias contains db)
    return aliases.some(a => {
      const al = a.toLowerCase();
      return norm === al || norm.includes(al) || al.includes(norm);
    });
  }

  // ── Global handler untuk tombol Jenis di modal Grading ────────────
  window._onGradingJenisClick = function(btn) {
    document.querySelectorAll('.grading-jenis-btn').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    const bbnkb = document.getElementById('gradingBbnkb')?.checked || false;
    const fraud  = document.getElementById('gradingFraud')?.checked  || false;
    _populateGradingPemeriksaanDropdown(btn.dataset.jenis);
    _renderGradingItemsList(bbnkb, fraud);
  };

  // ── Helper: cocokkan area dropdown → area di database ────────────
  function _gradingAreaMatch(dbArea, selArea) {
    if (!selArea) return true;
    const d = (dbArea || '').toUpperCase();
    if (selArea === 'Aceh')  return d.includes('ACEH') || d.includes('ACH');
    if (selArea === 'Riau')  return d.includes('RRI')  || d.includes('RIAU');
    if (selArea === 'Kepri') return d.includes('KEPRI')|| d.includes('KPR');
    return true;
  }

  // ── Ambil daftar Nama Pemeriksaan yang sudah terpakai untuk plan ini ──
  function _gradingUsedNames(planId) {
    if (!planId) return new Set();
    const fromSession = loadGradingSessions()
      .filter(s => String(s.planId) === String(planId))
      .flatMap(s => (s.items || []).map(it => it.namaPemeriksaan));
    const fromCurrent = _gradingItems.map(it => it.namaPemeriksaan);
    return new Set([...fromSession, ...fromCurrent]);
  }

  // ── Populate dropdown Pemeriksaan (filter Jenis saja, exclude used) ──
  // Area TIDAK difilter di sini — area hanya mempengaruhi dropdown Hasil
  function _populateGradingPemeriksaanDropdown(jenis) {
    const selP  = document.getElementById('gradingSelectPemeriksaan');
    const selH  = document.getElementById('gradingSelectHasil');
    if (!selP) return;

    const db   = loadGradingDb();
    const used = _gradingUsedNames(_gradingPlanId);

    // Jika DB kosong — beri info
    if (!db.length) {
      selP.innerHTML = '<option value="">— DB Grading kosong, import dulu di menu Database —</option>';
      if (selH) selH.innerHTML = '<option value="">— Pilih Hasil (5 pilihan) —</option>';
      return;
    }

    const names = [...new Set(
      db.filter(r => _gradingJenisMatch(r.jenis, jenis))
        .map(r => r.namaPemeriksaan)
    )].filter(n => !used.has(n)).sort();

    if (!names.length) {
      // Tidak ada data untuk jenis ini — tampilkan semua jenis sebagai fallback
      const allNames = [...new Set(db.map(r => r.namaPemeriksaan))].filter(n => !used.has(n)).sort();
      selP.innerHTML = '<option value="">— Pilih Nama Pemeriksaan (semua jenis) —</option>' +
        allNames.map(n => `<option value="${n}">${n}</option>`).join('');
    } else {
      selP.innerHTML = '<option value="">— Pilih Nama Pemeriksaan —</option>' +
        names.map(n => `<option value="${n}">${n}</option>`).join('');
    }
    if (selH) selH.innerHTML = '<option value="">— Pilih Hasil (5 pilihan) —</option>';
  }

  // ── Buka Modal Grading ────────────────────────────────────────
  window._openGradingModal = function(taskId) {
    tasks = loadTasks();
    const t = tasks.find(x => String(x.id) === String(taskId));
    if (!t) return;
    _gradingTaskId = taskId;
    _gradingPlanId = t.planId;
    _gradingItems  = [];

    // Cek apakah plan selesai
    const planSelesai = t.status === 'selesai';

    // Plan info
    const infoEl = document.getElementById('gradingPlanInfo');
    if (infoEl) {
      infoEl.innerHTML = `
        <div class="unit-info-grid">
          <div class="unit-info-item"><label>No SPT</label><span style="font-weight:700">${t.noSPT}</span></div>
          <div class="unit-info-item"><label>Jenis Audit</label><span>${t.jenisAudit}</span></div>
          <div class="unit-info-item"><label>Cabang</label><span>${t.cabangPlan}${t.cabangArea ? ' ' + areaBadge(t.cabangArea) : ''}</span></div>
          <div class="unit-info-item"><label>Status</label><span>${taskStatusBadge(t.status)}</span></div>
        </div>
        ${planSelesai ? '<div style="background:#fee2e2;border:1px solid #fca5a5;border-radius:6px;padding:8px 12px;font-size:.82rem;color:#dc2626;margin-top:8px">🔒 Plan sudah <strong>Selesai</strong> — penilaian grading tidak dapat ditambahkan lagi.</div>' : ''}`;
    }

    // History
    _renderGradingHistory(t.planId);

    // Auto-fill cabang grading
    const cabangEl = document.getElementById('gradingCabang');
    if (cabangEl) cabangEl.value = t.cabangPlan || '';

    // Tanggal default hari ini
    const tglEl = document.getElementById('gradingTanggal');
    if (tglEl && !tglEl.value) tglEl.value = new Date().toISOString().slice(0, 10);

    // Reset jenis buttons → default SO
    document.querySelectorAll('.grading-jenis-btn').forEach(btn =>
      btn.classList.toggle('active', btn.dataset.jenis === 'SO')
    );

    // Reset Area dropdown
    const areaEl  = document.getElementById('gradingArea');
    if (areaEl)  areaEl.value = '';

    // Reset BBNKB & Fraud
    const bbnkbEl = document.getElementById('gradingBbnkb');
    const fraudEl = document.getElementById('gradingFraud');
    const lblBbnkb = document.getElementById('gradingBbnkbLabel');
    const lblFraud = document.getElementById('gradingFraudLabel');
    const fraudFields = document.getElementById('gradingFraudFields');
    if (bbnkbEl)    { bbnkbEl.checked = false; }
    if (lblBbnkb)   { lblBbnkb.textContent = 'Tidak'; }
    if (fraudEl)    { fraudEl.checked = false; }
    if (lblFraud)   { lblFraud.textContent = 'Tidak'; lblFraud.style.color = ''; }
    if (fraudFields){ fraudFields.style.display = 'none'; }
    const jfList = document.getElementById('gradingJenisFraudList');
    const jfInput = document.getElementById('gradingJenisFraud');
    const ketFraud = document.getElementById('gradingKetFraud');
    if (jfList)  jfList.innerHTML = '';
    if (jfInput) jfInput.value = '';
    if (ketFraud) ketFraud.value = '';

    _populateGradingPemeriksaanDropdown('SO');
    _renderGradingItemsList(false, false);
    _renderGradingNilaiSummary(false, false);

    // Lock form jika plan selesai
    ['btnSimpanGrading','gradingFraudFields'].forEach(id => {
      const el = document.getElementById(id);
      if (el && id === 'btnSimpanGrading') el.style.display = planSelesai ? 'none' : '';
    });
    const addBox = document.getElementById('gradingSelectPemeriksaan')?.closest('[style*="dashed"]');
    if (addBox) addBox.style.display = planSelesai ? 'none' : '';

    // Jenis btn onclick sudah dipasang via HTML onclick="window._onGradingJenisClick(this)"

    document.getElementById('gradingModal').classList.remove('hidden');
    document.getElementById('gradingModal').style.display = 'flex';
  };

  // ── Event: Area berubah ───────────────────────────────────────
  window._onGradingAreaChange = function() {
    const jenis  = document.querySelector('.grading-jenis-btn.active')?.dataset.jenis || 'SO';
    const bbnkb  = document.getElementById('gradingBbnkb')?.checked || false;
    const fraud  = document.getElementById('gradingFraud')?.checked  || false;
    _populateGradingPemeriksaanDropdown(jenis);
    _renderGradingItemsList(bbnkb, fraud);
  };

  // ── Event: BBNKB berubah ─────────────────────────────────────
  window._onGradingBbnkbChange = function() {
    const bbnkbEl = document.getElementById('gradingBbnkb');
    const fraudEl = document.getElementById('gradingFraud');
    const lbl     = document.getElementById('gradingBbnkbLabel');
    const bbnkb   = bbnkbEl?.checked || false;
    const fraud   = fraudEl?.checked  || false;
    if (lbl) lbl.textContent = bbnkb ? 'Ya' : 'Tidak';
    // Recalc kontribusi semua item
    const db = loadGradingDb();
    _gradingItems = _gradingItems.map(it => {
      const dbRow = db.find(r => r.dgrading === it.dgrading);
      return dbRow ? { ...it, kontribusi: _gradingGetKontribusi(dbRow, bbnkb, fraud) } : it;
    });
    // Refresh dropdown Pemeriksaan (jenis saja, tidak perlu area/bbnkb)
    const jenis2 = document.querySelector('.grading-jenis-btn.active')?.dataset.jenis || 'SO';
    _populateGradingPemeriksaanDropdown(jenis2);
    // Reset dropdown Hasil agar user pilih ulang berdasarkan pengaturan baru
    const selH2 = document.getElementById('gradingSelectHasil');
    if (selH2) selH2.innerHTML = '<option value="">— Pilih Hasil (5 pilihan) —</option>';
    _renderGradingItemsList(bbnkb, fraud);
  };

  // ── Event: Fraud berubah ─────────────────────────────────────
  window._onGradingFraudChange = function() {
    const bbnkbEl   = document.getElementById('gradingBbnkb');
    const fraudEl   = document.getElementById('gradingFraud');
    const lblFraud  = document.getElementById('gradingFraudLabel');
    const fraudFlds = document.getElementById('gradingFraudFields');
    const bbnkb     = bbnkbEl?.checked || false;
    const fraud     = fraudEl?.checked  || false;
    if (lblFraud)  { lblFraud.textContent = fraud ? 'Ya (FRAUD)' : 'Tidak'; lblFraud.style.color = fraud ? '#dc2626' : ''; }
    if (fraudFlds) fraudFlds.style.display = fraud ? '' : 'none';
    // Reset fraud fields jika uncheck
    if (!fraud) {
      const jfList = document.getElementById('gradingJenisFraudList');
      const jfInput = document.getElementById('gradingJenisFraud');
      const ketFraud = document.getElementById('gradingKetFraud');
      if (jfList)   jfList.innerHTML = '';
      if (jfInput)  jfInput.value = '';
      if (ketFraud) ketFraud.value = '';
    }
    // Recalc kontribusi
    const db = loadGradingDb();
    _gradingItems = _gradingItems.map(it => {
      const dbRow = db.find(r => r.dgrading === it.dgrading);
      return dbRow ? { ...it, kontribusi: _gradingGetKontribusi(dbRow, bbnkb, fraud) } : it;
    });
    _renderGradingItemsList(bbnkb, fraud);
  };

  // ── Tambah Jenis Fraud (tag chip) ────────────────────────────
  let _jenisFraudList = [];
  window._addJenisFraud = function() {
    const inp  = document.getElementById('gradingJenisFraud');
    const list = document.getElementById('gradingJenisFraudList');
    const val  = (inp?.value || '').trim();
    if (!val) return;
    if (!_jenisFraudList.includes(val)) _jenisFraudList.push(val);
    if (inp) inp.value = '';
    if (list) {
      list.innerHTML = _jenisFraudList.map((v, i) =>
        `<span style="display:inline-flex;align-items:center;gap:4px;background:#fee2e2;color:#dc2626;
                       border-radius:6px;padding:3px 10px;font-size:.78rem;font-weight:600">
          ${v}
          <button onclick="window._removeJenisFraud(${i})"
                  style="background:none;border:none;cursor:pointer;color:#dc2626;font-size:.85rem;padding:0;margin-left:2px">✕</button>
        </span>`
      ).join('');
    }
  };
  window._removeJenisFraud = function(idx) {
    _jenisFraudList.splice(idx, 1);
    window._addJenisFraud(); // re-render dengan input kosong
  };

  // ── Tutup Modal Grading ───────────────────────────────────────
  window._closeGradingModal = function() {
    const m = document.getElementById('gradingModal');
    if (m) { m.classList.add('hidden'); m.style.display = ''; }
    _gradingTaskId = null; _gradingPlanId = null;
    _gradingItems = []; _jenisFraudList = []; _picaData = {};
  };

  // ── Simpan Grading ────────────────────────────────────────────
  window._saveGrading = function() {
    if (!_gradingPlanId) return;

    const tgl     = document.getElementById('gradingTanggal')?.value;
    const cabang  = document.getElementById('gradingCabang')?.value  || '';
    const jenis   = document.querySelector('.grading-jenis-btn.active')?.dataset.jenis || 'SO';
    const area    = document.getElementById('gradingArea')?.value    || '';
    const bbnkb   = document.getElementById('gradingBbnkb')?.checked || false;
    const fraud   = document.getElementById('gradingFraud')?.checked  || false;
    const ketFraud = document.getElementById('gradingKetFraud')?.value  || '';

    if (!tgl)    { showToast('Isi Tanggal Penilaian.', 'error'); return; }
    if (!area)   { showToast('Pilih Area terlebih dahulu.', 'error'); return; }
    if (!_gradingItems.length) { showToast('Tambahkan minimal 1 item pemeriksaan.', 'error'); return; }
    if (fraud && !_jenisFraudList.length) { showToast('Isi Jenis Fraud terlebih dahulu.', 'error'); return; }

    const nilaiTotal = _gradingCalcNilai(_gradingItems);

    // Gabungkan PICA data ke setiap item
    const itemsWithPica = _gradingItems.map((it, i) => {
      if (it.nilai <= 2) {
        return {
          ...it,
          pica: {
            currentCondition:      (_picaData[i]?.currentCondition || '').trim(),
            problemIdentification: '',
            correctiveAction:      '',
            deadlineCorrective:    '',
            picCorrective:         '',
            relationShipDept:      '',
            relationShip:          '',
            status:                'pending_branch',
          }
        };
      }
      return it;
    });

    const sessions = loadGradingSessions();
    const newEntry = {
      id:           'grd-' + Date.now(),
      planId:       String(_gradingPlanId),
      noSPT:        tasks.find(x => String(x.id) === String(_gradingTaskId))?.noSPT || '',
      tanggal:      tgl,
      pembuat:      session.displayName || session.username,
      jenis, area, bbnkb, fraud,
      jenisFraud:    fraud ? [..._jenisFraudList] : [],
      keteranganFraud: fraud ? ketFraud : '',
      cabangGrading: cabang,
      items:         itemsWithPica,
      nilaiTotal,
      savedAt:      new Date().toISOString(),
      savedBy:      session.username,
    };
    sessions.push(newEntry);
    saveGradingSessions(sessions);
    try { _updatePicaBadge?.(); } catch {}

    showToast('Penilaian grading berhasil disimpan. Rata-rata nilai: ' + _fmtGradingVal(nilaiTotal), 'success');
    _gradingItems   = [];
    _jenisFraudList = [];
    _picaData       = {};
    _renderGradingHistory(_gradingPlanId);
    _renderGradingPicaForms();
    // Reset form
    const jfList = document.getElementById('gradingJenisFraudList');
    const jfInput = document.getElementById('gradingJenisFraud');
    const ketEl   = document.getElementById('gradingKetFraud');
    const fraudFlds = document.getElementById('gradingFraudFields');
    if (jfList)   jfList.innerHTML = '';
    if (jfInput)  jfInput.value = '';
    if (ketEl)    ketEl.value = '';
    if (fraudFlds) fraudFlds.style.display = 'none';
    const fraudEl2 = document.getElementById('gradingFraud');
    const lblFraud2 = document.getElementById('gradingFraudLabel');
    if (fraudEl2)  fraudEl2.checked = false;
    if (lblFraud2) { lblFraud2.textContent = 'Tidak'; lblFraud2.style.color = ''; }
    // Refresh dropdown Pemeriksaan
    _populateGradingPemeriksaanDropdown(jenis);
    _renderGradingItemsList(bbnkb, fraud);
    _renderGradingNilaiSummary(bbnkb, fraud);
    renderAuditSection();
  };

  // ── Close grading modal on overlay click ──────────────────────
  document.getElementById('gradingModal')?.addEventListener('click', function(e) {
    if (e.target === this) window._closeGradingModal();
  });

  /* ── END MODUL GRADING ── */

  /* ============================================================
     MODUL PICA MENU
     ============================================================ */

  // ── Kumpulkan semua PICA item dari seluruh grading sessions ───
  function _collectAllPica() {
    const sessions  = loadGradingSessions();
    const allPlans  = loadPlans();
    const result    = [];

    sessions.forEach(gs => {
      const plan = allPlans.find(p => String(p.id) === String(gs.planId));
      (gs.items || []).forEach((item, idx) => {
        if (!item.pica) return;
        result.push({
          sessionId:        gs.id,
          itemIdx:          idx,
          planId:           gs.planId,
          noSPT:            gs.noSPT || plan?.noSPT || '—',
          jenisAudit:       plan?.jenisAudit || '—',
          tanggalGrading:   gs.tanggal || gs.savedAt?.slice(0, 10) || '—',
          pembuat:          gs.pembuat || gs.savedBy || '—',
          jenisUnit:        gs.jenis   || '—',
          area:             gs.area    || '—',
          unitUsaha:        gs.cabangGrading || '—',
          namaPemeriksaan:  item.namaPemeriksaan || '—',
          hasilPemeriksaan: item.hasilPemeriksaan || '—',
          nilai:            item.nilai,
          pica:             item.pica,
        });
      });
    });
    return result;
  }

  // ── Update badge PICA di nav ──────────────────────────────────
  function _updatePicaBadge() {
    let allPicaBadge = _collectAllPica();
    if (session?.role === 'rss' && session.unitUsaha) {
      const wil = session.unitUsaha.toLowerCase().trim();
      allPicaBadge = allPicaBadge.filter(p => (p.area || '').toLowerCase().trim() === wil);
    }
    const pendingCount = allPicaBadge.filter(p => p.pica.status !== 'completed').length;
    const badge = document.getElementById('navPicaBadge');
    if (!badge) return;
    if (pendingCount > 0) {
      badge.textContent = pendingCount;
      badge.classList.remove('hidden');
    } else {
      badge.classList.add('hidden');
    }
  }

  // ── Render seksi PICA ─────────────────────────────────────────
  window._renderPicaSection = function() {
    const contentEl = document.getElementById('picaSectionContent');
    if (!contentEl) return;

    const search      = (document.getElementById('picaSearchInput')?.value || '').toLowerCase().trim();
    const filterStatus = document.getElementById('picaFilterStatus')?.value || '';
    const filterUnit   = document.getElementById('picaFilterUnit')?.value   || '';

    let allPica = _collectAllPica();

    // Role-based filter
    const r         = session.role;
    const isBranch  = ['so', 'csc', 'whs', 'kasir'].includes(r);
    const isAuditor = ['auditor', 'admin', 'manajer', 'koordinator', 'coo', 'afd'].includes(r);
    const isRSS     = r === 'rss';
    if (isBranch) {
      allPica = allPica.filter(p => p.unitUsaha === session.unitUsaha);
    } else if (isRSS && session.unitUsaha) {
      // RSS per-wilayah: filter berdasarkan area yang sesuai wilayah user
      const wil = session.unitUsaha.toLowerCase().trim();
      allPica = allPica.filter(p => (p.area || '').toLowerCase().trim() === wil);
    }

    // Populate unit filter dropdown (once)
    const unitSel = document.getElementById('picaFilterUnit');
    if (unitSel) {
      const units = [...new Set(allPica.map(p => p.unitUsaha))].sort();
      const curVal = unitSel.value;
      unitSel.innerHTML = '<option value="">— Semua Unit —</option>' +
        units.map(u => `<option value="${u}" ${u === curVal ? 'selected' : ''}>${u}</option>`).join('');
    }

    // Apply filters
    if (filterUnit) allPica = allPica.filter(p => p.unitUsaha === filterUnit);
    if (filterStatus === 'pending')   allPica = allPica.filter(p => p.pica.status !== 'completed');
    if (filterStatus === 'completed') allPica = allPica.filter(p => p.pica.status === 'completed');
    if (search) allPica = allPica.filter(p =>
      p.unitUsaha.toLowerCase().includes(search) ||
      p.namaPemeriksaan.toLowerCase().includes(search) ||
      p.noSPT.toLowerCase().includes(search) ||
      (p.pica.picCorrective || '').toLowerCase().includes(search) ||
      (p.pica.problemIdentification || '').toLowerCase().includes(search)
    );

    // Stat badges
    const totalAll = _collectAllPica().filter(p => {
      if (isBranch) return p.unitUsaha === session.unitUsaha;
      if (isRSS && session.unitUsaha) return (p.area || '').toLowerCase().trim() === session.unitUsaha.toLowerCase().trim();
      return true;
    });
    const totalPend  = totalAll.filter(p => p.pica.status !== 'completed').length;
    const totalDone  = totalAll.filter(p => p.pica.status === 'completed').length;
    const statEl = document.getElementById('picaStatBadges');
    if (statEl) statEl.innerHTML = `
      <span style="background:#fee2e2;color:#dc2626;font-size:.78rem;font-weight:700;padding:4px 12px;border-radius:12px">
        ⏳ Pending: ${totalPend}
      </span>
      <span style="background:#dcfce7;color:#166534;font-size:.78rem;font-weight:700;padding:4px 12px;border-radius:12px">
        ✓ Selesai: ${totalDone}
      </span>`;

    if (!allPica.length) {
      contentEl.innerHTML = `<div style="text-align:center;padding:48px 0;color:var(--text-secondary)">
        <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" style="opacity:.35;margin-bottom:12px">
          <path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/>
          <line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/>
        </svg>
        <div style="font-size:.9rem">Belum ada data PICA</div>
        <div style="font-size:.8rem;margin-top:4px;opacity:.7">PICA dibuat otomatis saat item grading bernilai 1 atau 2</div>
      </div>`;
      return;
    }

    // Group by unit usaha
    const groups = {};
    allPica.forEach(p => {
      const key = p.unitUsaha;
      if (!groups[key]) groups[key] = [];
      groups[key].push(p);
    });

    const html = Object.entries(groups).sort(([a], [b]) => a.localeCompare(b)).map(([unit, items]) => {
      const pendingN  = items.filter(i => i.pica.status !== 'completed').length;
      const doneN     = items.filter(i => i.pica.status === 'completed').length;

      const rows = items.map(p => {
        const st        = p.pica.status;
        const isComp    = st === 'completed';
        const stBg      = isComp ? '#dcfce7' : '#fee2e2';
        const stColor   = isComp ? '#166534' : '#dc2626';
        const stLabel   = isComp ? '✓ Selesai' : '⏳ Pending';
        const nilaiColor = p.nilai <= 1 ? '#dc2626' : p.nilai <= 2 ? '#b45309' : '#374151';
        const canRespond = ['so','csc','whs','kasir','auditor','admin','rss'].includes(r);

        return `<tr style="vertical-align:top">
          <td style="padding:10px 12px;font-size:.8rem;color:var(--text-secondary);white-space:nowrap">
            ${p.tanggalGrading}<br>
            <span style="font-size:.72rem;opacity:.8">${p.jenisUnit} · ${p.area}</span>
          </td>
          <td style="padding:10px 12px;font-size:.82rem">
            <div style="font-weight:600">${p.noSPT}</div>
            <div style="font-size:.72rem;color:var(--text-secondary)">${p.jenisAudit}</div>
          </td>
          <td style="padding:10px 12px;font-size:.82rem;font-weight:600">${p.namaPemeriksaan}</td>
          <td style="padding:10px 12px;font-size:.8rem;color:var(--text-secondary)">${p.hasilPemeriksaan}</td>
          <td style="padding:10px 12px;text-align:center">
            <span style="font-weight:800;font-size:.9rem;color:${nilaiColor}">${p.nilai}</span>
          </td>
          <td style="padding:10px 12px;font-size:.8rem">
            ${p.pica.currentCondition
              ? `<div style="font-style:italic;color:#374151;max-width:160px">${p.pica.currentCondition}</div>`
              : '<span style="color:var(--text-secondary)">—</span>'}
          </td>
          <td style="padding:10px 12px;font-size:.8rem">
            ${isComp ? `
              <div><span style="font-size:.7rem;font-weight:700;text-transform:uppercase;color:#0369a1">Problem</span>
                   <div>${p.pica.problemIdentification||'—'}</div></div>
              <div style="margin-top:4px"><span style="font-size:.7rem;font-weight:700;text-transform:uppercase;color:#0369a1">Corrective Action</span>
                   <div>${p.pica.correctiveAction||'—'}</div></div>
            ` : '<span style="color:var(--text-secondary);font-size:.78rem">Menunggu response…</span>'}
          </td>
          <td style="padding:10px 12px;font-size:.8rem;white-space:nowrap">
            ${isComp ? `<div style="font-weight:700;color:#166534">${p.pica.deadlineCorrective||'—'}</div>` : '—'}
          </td>
          <td style="padding:10px 12px;font-size:.8rem">
            ${isComp ? (p.pica.picCorrective||'—') : '—'}
          </td>
          <td style="padding:10px 12px;text-align:center">
            <span style="font-size:.72rem;font-weight:700;padding:3px 10px;border-radius:10px;background:${stBg};color:${stColor}">${stLabel}</span>
          </td>
          <td style="padding:10px 12px;text-align:center">
            ${canRespond ? `<button class="btn-primary" style="font-size:.75rem;padding:5px 12px"
              onclick="window._openPicaResponseModal('${p.sessionId}',${p.itemIdx})">
              ${isComp ? 'Lihat/Edit' : 'Isi Response'}
            </button>` : ''}
          </td>
        </tr>`;
      }).join('');

      return `<div style="background:#fff;border:1px solid var(--border);border-radius:12px;margin-bottom:20px;overflow:hidden">
        <div style="background:linear-gradient(135deg,#4f46e5,#7c3aed);color:#fff;padding:14px 20px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px">
          <div>
            <div style="font-weight:700;font-size:1rem">${unit}</div>
            <div style="font-size:.78rem;opacity:.85">${items.length} item PICA</div>
          </div>
          <div style="display:flex;gap:8px;flex-wrap:wrap">
            ${pendingN ? `<span style="background:rgba(255,255,255,.2);padding:3px 12px;border-radius:10px;font-size:.75rem;font-weight:700">⏳ ${pendingN} Pending</span>` : ''}
            ${doneN    ? `<span style="background:rgba(255,255,255,.15);padding:3px 12px;border-radius:10px;font-size:.75rem;font-weight:700">✓ ${doneN} Selesai</span>` : ''}
          </div>
        </div>
        <div style="overflow-x:auto">
          <table style="width:100%;border-collapse:collapse;font-size:.83rem">
            <thead>
              <tr style="background:#f8fafc;border-bottom:2px solid var(--border)">
                <th style="padding:10px 12px;text-align:left;font-size:.72rem;text-transform:uppercase;color:var(--text-secondary);white-space:nowrap">Tanggal</th>
                <th style="padding:10px 12px;text-align:left;font-size:.72rem;text-transform:uppercase;color:var(--text-secondary)">No SPT</th>
                <th style="padding:10px 12px;text-align:left;font-size:.72rem;text-transform:uppercase;color:var(--text-secondary)">Nama Pemeriksaan</th>
                <th style="padding:10px 12px;text-align:left;font-size:.72rem;text-transform:uppercase;color:var(--text-secondary)">Hasil</th>
                <th style="padding:10px 12px;text-align:center;font-size:.72rem;text-transform:uppercase;color:var(--text-secondary)">Nilai</th>
                <th style="padding:10px 12px;text-align:left;font-size:.72rem;text-transform:uppercase;color:var(--text-secondary)">Kondisi Saat Ini</th>
                <th style="padding:10px 12px;text-align:left;font-size:.72rem;text-transform:uppercase;color:var(--text-secondary)">Problem &amp; Action</th>
                <th style="padding:10px 12px;text-align:left;font-size:.72rem;text-transform:uppercase;color:var(--text-secondary);white-space:nowrap">Deadline</th>
                <th style="padding:10px 12px;text-align:left;font-size:.72rem;text-transform:uppercase;color:var(--text-secondary)">PIC</th>
                <th style="padding:10px 12px;text-align:center;font-size:.72rem;text-transform:uppercase;color:var(--text-secondary)">Status</th>
                <th style="padding:10px 12px;text-align:center;font-size:.72rem;text-transform:uppercase;color:var(--text-secondary)">Aksi</th>
              </tr>
            </thead>
            <tbody>
              ${rows}
            </tbody>
          </table>
        </div>
      </div>`;
    }).join('');

    contentEl.innerHTML = html;
    _updatePicaBadge();
  };

  // Refresh PICA badge setelah simpan response
  const _origSavePicaResponse = window._savePicaResponse;
  window._savePicaResponse = function() {
    _origSavePicaResponse?.();
    _updatePicaBadge();
    if (document.getElementById('section-pica')?.classList.contains('hidden') === false) {
      window._renderPicaSection();
    }
  };

  // Init badge
  (function() { try { _updatePicaBadge(); } catch {} })();

  /* ── END MODUL PICA MENU ── */

  /* ============================================================
     MODUL PEMERIKSAAN BANK
     ============================================================ */

  const BANK_PEM_KEY = 'akta_pemeriksaan_bank';
  function loadBankPem()  { try { return JSON.parse(localStorage.getItem(BANK_PEM_KEY)) || []; } catch { return []; } }
  function saveBankPem(d) { localStorage.setItem(BANK_PEM_KEY, JSON.stringify(d)); window.API?.sync(BANK_PEM_KEY, d); }

  // ── State modal ───────────────────────────────────────────────
  let _bankPemTaskId  = null;
  let _bankPemPlanId  = null;
  let _bankPemState   = [];  // array of bank objects
  let _bankCekState   = [];  // array of cek objects

  // ── Buat bank kosong ──────────────────────────────────────────
  function _bankNewEntry() {
    return {
      id:                Date.now() + Math.random(),
      namaBank:          '',
      tglSaldoAwal:      '',
      saldoAwal:         0,
      penerimaan:        [],
      pengeluaran:       [],
      saldoRekKoranTgl:  '',
      saldoRekKoran:     0,
      keteranganSelisih: '',
    };
  }

  // ── Format Rupiah ─────────────────────────────────────────────
  function _bankFmtRp(n) {
    return 'Rp ' + Number(n || 0).toLocaleString('id-ID');
  }

  // ── Kalkulasi per bank ────────────────────────────────────────
  function _bankCalc(b) {
    const sa  = Number(b.saldoAwal || 0);
    const tp  = (b.penerimaan  || []).reduce((s, r) => s + Number(r.jumlah || 0), 0);
    const tpl = (b.pengeluaran || []).reduce((s, r) => s + Number(r.jumlah || 0), 0);
    const sb  = sa + tp - tpl;
    const srk = Number(b.saldoRekKoran || 0);
    const sel = sb - srk;
    return { sa, tp, tpl, sb, srk, sel };
  }

  // ── Render satu bank section ──────────────────────────────────
  function _renderBankSection(b, idx) {
    const c = _bankCalc(b);
    const fRp = v => Number(v || 0).toLocaleString('id-ID');
    const selClr = c.sel === 0 ? '#166534' : '#dc2626';
    const selTxt = c.sel === 0 ? '✓' : '✗';

    const penRows = (b.penerimaan || []).map((r, ri) => `
      <tr>
        <td><input type="date" value="${r.tgl||''}" class="pem-input-sm"
                   onchange="window._bankRowChange(${idx},'penerimaan',${ri},'tgl',this.value)" /></td>
        <td><input type="text" value="${r.ket||''}" class="pem-input-sm" placeholder="Keterangan..."
                   onchange="window._bankRowChange(${idx},'penerimaan',${ri},'ket',this.value)" /></td>
        <td><input type="number" value="${r.jumlah||0}" class="pem-input-sm" min="0"
                   oninput="window._bankRowChange(${idx},'penerimaan',${ri},'jumlah',this.value)" /></td>
        <td><button class="btn-del-row" onclick="window._bankRemoveRow(${idx},'penerimaan',${ri})">✕</button></td>
      </tr>`).join('');

    const pelRows = (b.pengeluaran || []).map((r, ri) => `
      <tr>
        <td><input type="date" value="${r.tgl||''}" class="pem-input-sm"
                   onchange="window._bankRowChange(${idx},'pengeluaran',${ri},'tgl',this.value)" /></td>
        <td><input type="text" value="${r.ket||''}" class="pem-input-sm" placeholder="Keterangan..."
                   onchange="window._bankRowChange(${idx},'pengeluaran',${ri},'ket',this.value)" /></td>
        <td><input type="number" value="${r.jumlah||0}" class="pem-input-sm" min="0"
                   oninput="window._bankRowChange(${idx},'pengeluaran',${ri},'jumlah',this.value)" /></td>
        <td><button class="btn-del-row" onclick="window._bankRemoveRow(${idx},'pengeluaran',${ri})">✕</button></td>
      </tr>`).join('');

    return `
      <div style="margin-bottom:12px;border:2px solid #0d9488;border-radius:8px;overflow:hidden" id="bankSec-${idx}">
        <!-- Header -->
        <div style="background:linear-gradient(135deg,#0f766e,#0d9488);color:#fff;padding:9px 14px;
                    display:flex;align-items:center;gap:8px">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="5" width="20" height="14" rx="2"/><line x1="2" y1="10" x2="22" y2="10"/></svg>
          <span style="font-weight:700;font-size:.9rem">BANK ${idx + 1}</span>
          <span id="bank-name-${idx}" style="font-size:.78rem;opacity:.8;flex:1">${b.namaBank || ''}</span>
          ${_bankPemState.length > 1 ? `
          <button onclick="window._bankRemove(${idx})"
                  style="background:rgba(255,255,255,.2);border:none;color:#fff;border-radius:4px;
                         padding:2px 8px;cursor:pointer;font-size:.8rem">✕ Hapus</button>` : ''}
        </div>
        <!-- Body -->
        <div style="padding:12px 14px;background:#f0fdfa">
          <!-- Nama Bank -->
          <div class="field-group" style="margin-bottom:10px">
            <label class="pem-label">NAMA BANK</label>
            <input type="text" value="${b.namaBank||''}" class="kas-input" placeholder="Nama Bank..."
                   oninput="window._bankFieldChange(${idx},'namaBank',this.value)" />
          </div>
          <!-- Saldo awal -->
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px">
            <div class="field-group">
              <label class="pem-label" style="font-size:.68rem">SALDO AWAL (TANGGAL H-1 PEMERIKSAAN)</label>
              <input type="date" value="${b.tglSaldoAwal||''}" class="kas-input"
                     onchange="window._bankFieldChange(${idx},'tglSaldoAwal',this.value)" />
            </div>
            <div class="field-group">
              <label class="pem-label" style="font-size:.68rem">SALDO AWAL (RP)</label>
              <input type="number" value="${b.saldoAwal||0}" class="kas-input" min="0"
                     oninput="window._bankFieldChange(${idx},'saldoAwal',this.value)" />
            </div>
          </div>
          <!-- Penerimaan -->
          <div class="pem-sub-section">
            <div class="pem-sub-header penerimaan-hdr">▲ PENERIMAAN</div>
            <table class="pem-table">
              <thead><tr><th>TANGGAL</th><th>KETERANGAN</th><th>JUMLAH (RP)</th><th style="width:36px"></th></tr></thead>
              <tbody>${penRows || '<tr><td colspan="4" style="text-align:center;color:#9ca3af;padding:6px;font-style:italic">Belum ada data</td></tr>'}</tbody>
            </table>
            <button class="btn-add-row" onclick="window._bankAddRow(${idx},'penerimaan')">+ Tambah Penerimaan</button>
          </div>
          <!-- Pengeluaran -->
          <div class="pem-sub-section">
            <div class="pem-sub-header pengeluaran-hdr">▼ PENGELUARAN</div>
            <table class="pem-table">
              <thead><tr><th>TANGGAL</th><th>KETERANGAN</th><th>JUMLAH (RP)</th><th style="width:36px"></th></tr></thead>
              <tbody>${pelRows || '<tr><td colspan="4" style="text-align:center;color:#9ca3af;padding:6px;font-style:italic">Belum ada data</td></tr>'}</tbody>
            </table>
            <button class="btn-add-row" onclick="window._bankAddRow(${idx},'pengeluaran')">+ Tambah Pengeluaran</button>
          </div>
          <!-- Summary — diupdate parsial tanpa re-render form -->
          <div class="pem-summary" id="bank-summary-${idx}" style="margin-top:8px">
            <div class="pem-sum-row"><span>Saldo Awal</span><span id="bank-sa-${idx}">${_bankFmtRp(c.sa)}</span></div>
            <div class="pem-sum-row"><span>+ Total Penerimaan</span><span id="bank-tp-${idx}">${_bankFmtRp(c.tp)}</span></div>
            <div class="pem-sum-row"><span>− Total Pengeluaran</span><span id="bank-tpl-${idx}">${_bankFmtRp(c.tpl)}</span></div>
            <div class="pem-sum-row pem-sum-bold">
              <span><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:middle;margin-right:4px"><rect x="2" y="5" width="20" height="14" rx="2"/><line x1="2" y1="10" x2="22" y2="10"/></svg>Saldo Buku (Sistem)</span>
              <span id="bank-sb-${idx}">${_bankFmtRp(c.sb)}</span>
            </div>
            <div class="pem-sum-row"><span>Saldo Rekening Koran</span><span id="bank-srk-${idx}">${_bankFmtRp(c.srk)}</span></div>
            <div class="pem-sum-row pem-sum-selisih">
              <span><strong>Selisih</strong></span>
              <span id="bank-sel-${idx}" style="color:${selClr};font-weight:700">${_bankFmtRp(c.sel)} ${selTxt}</span>
            </div>
          </div>
          <!-- Keterangan Selisih -->
          <div class="field-group" style="margin-top:6px">
            <label class="pem-label">KETERANGAN SELISIH</label>
            <textarea class="kas-input pem-textarea" rows="2" placeholder="contoh: Selisih lebih pembulatan"
                      oninput="window._bankFieldChange(${idx},'keteranganSelisih',this.value)">${b.keteranganSelisih||''}</textarea>
          </div>
          <!-- Saldo Rekening Koran -->
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:8px">
            <div class="field-group">
              <label class="pem-label" style="font-size:.68rem">SALDO REKENING KORAN (TANGGAL)</label>
              <input type="date" value="${b.saldoRekKoranTgl||''}" class="kas-input"
                     onchange="window._bankFieldChange(${idx},'saldoRekKoranTgl',this.value)" />
            </div>
            <div class="field-group">
              <label class="pem-label" style="font-size:.68rem">SALDO REKENING KORAN (RP)</label>
              <input type="number" value="${b.saldoRekKoran||0}" class="kas-input" min="0"
                     oninput="window._bankFieldChange(${idx},'saldoRekKoran',this.value)" />
            </div>
          </div>
        </div>
      </div>`;
  }

  // ── Render semua bank sections ────────────────────────────────
  function _renderBankForm() {
    const container = document.getElementById('bankPemContainer');
    if (!container) return;
    container.innerHTML = _bankPemState.map((b, i) => _renderBankSection(b, i)).join('');

    const cekContainer = document.getElementById('bankPemCekContainer');
    if (cekContainer) {
      cekContainer.innerHTML = _bankCekState.map((c, ci) => `
        <div style="display:flex;gap:6px;align-items:center;margin-bottom:6px">
          <input type="text" value="${c.noCek||''}" class="kas-input" style="flex:1"
                 placeholder="Nomor cek / range cek..."
                 oninput="window._bankCekChange(${ci},this.value)" />
          <button onclick="window._bankRemoveCek(${ci})"
                  style="background:#fee2e2;border:none;border-radius:4px;padding:4px 10px;cursor:pointer;color:#dc2626;font-size:.8rem">✕</button>
        </div>`).join('') || '<div style="color:#9ca3af;font-size:.8rem;text-align:center;padding:6px 0">Belum ada register cek</div>';
    }
  }

  // ── Update summary parsial (tanpa re-render seluruh form) ────
  function _bankRefreshSummary(idx) {
    const b = _bankPemState[idx];
    if (!b) return;
    const c = _bankCalc(b);
    const fRp = _bankFmtRp;
    const selClr = c.sel === 0 ? '#166534' : '#dc2626';
    const selTxt = c.sel === 0 ? '✓' : '✗';
    const set = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
    const setHtml = (id, val, style) => { const el = document.getElementById(id); if (el) { el.innerHTML = val; if (style) el.style.cssText = style; } };
    set(`bank-sa-${idx}`,  fRp(c.sa));
    set(`bank-tp-${idx}`,  fRp(c.tp));
    set(`bank-tpl-${idx}`, fRp(c.tpl));
    set(`bank-sb-${idx}`,  fRp(c.sb));
    set(`bank-srk-${idx}`, fRp(c.srk));
    const selEl = document.getElementById(`bank-sel-${idx}`);
    if (selEl) { selEl.textContent = `${fRp(c.sel)} ${selTxt}`; selEl.style.color = selClr; }
  }

  // ── Event handlers — NO full re-render untuk perubahan teks ──
  window._bankFieldChange = function(idx, field, val) {
    if (!_bankPemState[idx]) return;
    const isNumeric = field === 'saldoAwal' || field === 'saldoRekKoran';
    _bankPemState[idx][field] = isNumeric ? Number(val) || 0 : val;
    if (isNumeric) {
      // Hanya update summary, jangan re-render seluruh form
      _bankRefreshSummary(idx);
    } else if (field === 'namaBank') {
      // Update hanya teks nama di header
      const nameEl = document.getElementById(`bank-name-${idx}`);
      if (nameEl) nameEl.textContent = val;
    }
    // Untuk teks lainnya (tglSaldoAwal, saldoRekKoranTgl, keteranganSelisih): hanya update state
  };

  window._bankRowChange = function(idx, type, ri, field, val) {
    if (!_bankPemState[idx]) return;
    _bankPemState[idx][type][ri][field] = field === 'jumlah' ? Number(val) || 0 : val;
    if (field === 'jumlah') {
      // Hanya update summary
      _bankRefreshSummary(idx);
    }
    // Untuk teks (ket) dan tanggal (tgl): hanya update state, tidak perlu re-render
  };

  window._bankAddRow = function(idx, type) {
    if (!_bankPemState[idx]) return;
    const today = new Date().toISOString().slice(0, 10);
    _bankPemState[idx][type].push({ tgl: today, ket: '', jumlah: 0 });
    _renderBankForm();
  };

  window._bankRemoveRow = function(idx, type, ri) {
    if (!_bankPemState[idx]) return;
    _bankPemState[idx][type].splice(ri, 1);
    _renderBankForm();
  };

  window._bankRemove = function(idx) {
    if (!confirm('Hapus data Bank ' + (idx + 1) + '?')) return;
    _bankPemState.splice(idx, 1);
    _renderBankForm();
  };

  window._bankCekChange = function(ci, val) {
    if (_bankCekState[ci] !== undefined) _bankCekState[ci].noCek = val;
    // Hanya update state, jangan re-render (fokus tetap terjaga)
  };

  window._bankRemoveCek = function(ci) {
    _bankCekState.splice(ci, 1);
    _renderBankForm();
  };

  // ── Render riwayat tersimpan ──────────────────────────────────
  function _renderBankPemHistory(planId) {
    const el = document.getElementById('bankPemHistory');
    if (!el) return;
    const recs = loadBankPem().filter(r => String(r.planId) === String(planId));
    if (!recs.length) { el.innerHTML = ''; return; }
    el.innerHTML = `<div style="margin-bottom:10px">
      <div class="status-log-title" style="margin-bottom:8px">Riwayat Pemeriksaan Bank (${recs.length})</div>
      ${recs.map(r => {
        const totalBanks = (r.banks || []).length;
        const totalCek   = (r.cekBelumDigunakan || []).length;
        return `<div style="background:#f0fdfa;border:1px solid #99f6e4;border-radius:8px;padding:10px 14px;margin-bottom:8px;font-size:.82rem">
          <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px">
            <div>
              <strong>${r.planNoSPT||'—'}</strong>
              <span style="color:var(--text-secondary);margin-left:8px">${r.savedAt ? new Date(r.savedAt).toLocaleDateString('id-ID') : '—'}</span>
              <span style="background:#ccfbf1;color:#0f766e;font-size:.72rem;padding:1px 7px;border-radius:10px;margin-left:6px">${totalBanks} Bank</span>
              ${totalCek > 0 ? `<span style="background:#fef3c7;color:#b45309;font-size:.72rem;padding:1px 7px;border-radius:10px;margin-left:4px">${totalCek} Cek</span>` : ''}
            </div>
            <button onclick="window._loadBankPemRecord('${r.id}')"
                    style="background:#0d9488;color:#fff;border:none;border-radius:5px;padding:3px 12px;cursor:pointer;font-size:.75rem">
              Edit
            </button>
          </div>
          <div style="margin-top:6px;display:flex;flex-wrap:wrap;gap:8px">
            ${(r.banks||[]).map(b => {
              const c = _bankCalc(b);
              return `<span style="font-size:.75rem;background:#fff;border:1px solid #99f6e4;border-radius:5px;padding:2px 8px">
                ${b.namaBank||'Bank'}: Buku ${_bankFmtRp(c.sb)} | RK ${_bankFmtRp(c.srk)}
                <span style="color:${c.sel===0?'#166534':'#dc2626'};font-weight:700"> Selisih: ${_bankFmtRp(c.sel)}</span>
              </span>`;
            }).join('')}
          </div>
        </div>`;
      }).join('')}
    </div>`;
  }

  // ── Load record untuk diedit ──────────────────────────────────
  window._loadBankPemRecord = function(id) {
    const recs = loadBankPem();
    const rec  = recs.find(r => r.id === id);
    if (!rec) return;
    _bankPemState = JSON.parse(JSON.stringify(rec.banks || [_bankNewEntry()]));
    _bankCekState = JSON.parse(JSON.stringify(rec.cekBelumDigunakan || []));
    _renderBankForm();
    showToast('Data bank dimuat untuk diedit.', 'info');
  };

  // ── Buka Modal ────────────────────────────────────────────────
  window._openBankPemModal = function(taskId) {
    tasks = loadTasks();
    const t = tasks.find(x => String(x.id) === String(taskId));
    if (!t) return;
    _bankPemTaskId = taskId;
    _bankPemPlanId = t.planId;

    // Plan info
    const infoEl = document.getElementById('bankPemPlanInfo');
    if (infoEl) {
      infoEl.innerHTML = `
        <div class="unit-info-grid">
          <div class="unit-info-item"><label>No SPT</label><span style="font-weight:700">${t.noSPT}</span></div>
          <div class="unit-info-item"><label>Jenis Audit</label><span>${t.jenisAudit}</span></div>
          <div class="unit-info-item"><label>Cabang</label><span>${t.cabangPlan}${t.cabangArea ? ' ' + areaBadge(t.cabangArea) : ''}</span></div>
          <div class="unit-info-item"><label>Status</label><span>${taskStatusBadge(t.status)}</span></div>
        </div>`;
    }

    // Cek lock: sudah ada data untuk planId ini?
    const existing = loadBankPem().filter(r => String(r.planId) === String(t.planId));
    if (existing.length) {
      // Load data terbaru untuk diedit
      const latest = existing[existing.length - 1];
      _bankPemState = JSON.parse(JSON.stringify(latest.banks || [_bankNewEntry()]));
      _bankCekState = JSON.parse(JSON.stringify(latest.cekBelumDigunakan || []));
    } else {
      // Baru: mulai dengan 1 bank kosong
      _bankPemState = [_bankNewEntry()];
      _bankCekState = [];
    }

    _renderBankPemHistory(t.planId);
    _renderBankForm();

    // Lock form jika task selesai
    const formSection = document.getElementById('bankPemFormSection');
    const planSelesai = t.status === 'selesai';
    if (formSection) formSection.style.display = planSelesai ? 'none' : '';
    if (planSelesai && infoEl) {
      infoEl.insertAdjacentHTML('beforeend', '<div style="background:#fee2e2;border:1px solid #fca5a5;border-radius:6px;padding:8px 12px;font-size:.82rem;color:#dc2626;margin-top:8px">🔒 Plan sudah Selesai — tidak dapat menambah data.</div>');
    }

    document.getElementById('bankPemModal').classList.remove('hidden');
    document.getElementById('bankPemModal').style.display = 'flex';
  };

  // ── Tutup Modal ───────────────────────────────────────────────
  window._closeBankPemModal = function() {
    const m = document.getElementById('bankPemModal');
    if (m) { m.classList.add('hidden'); m.style.display = ''; }
    _bankPemTaskId = null; _bankPemPlanId = null;
    _bankPemState = []; _bankCekState = [];
  };

  // ── Simpan ────────────────────────────────────────────────────
  window._saveBankPemeriksaan = function() {
    if (!_bankPemPlanId) return;
    const t = loadTasks().find(x => String(x.id) === String(_bankPemTaskId));

    // Validasi: minimal 1 bank harus punya nama
    const hasNama = _bankPemState.some(b => b.namaBank.trim());
    if (!hasNama) { showToast('Isi Nama Bank terlebih dahulu.', 'error'); return; }

    const recs   = loadBankPem();
    const idxOld = recs.findIndex(r => String(r.planId) === String(_bankPemPlanId));

    const newRec = {
      id:                idxOld >= 0 ? recs[idxOld].id : 'bpem-' + Date.now(),
      planId:            String(_bankPemPlanId),
      planNoSPT:         t?.noSPT || '',
      cabangPlan:        t?.cabangPlan || '',
      savedAt:           new Date().toISOString(),
      savedBy:           session.username,
      banks:             JSON.parse(JSON.stringify(_bankPemState)),
      cekBelumDigunakan: JSON.parse(JSON.stringify(_bankCekState)),
    };

    if (idxOld >= 0) recs[idxOld] = newRec;
    else             recs.push(newRec);

    saveBankPem(recs);
    // Otomatis tandai tersimpan di Report Audit
    _markSavedPem(_bankPemPlanId, 'bank');
    showToast('Pemeriksaan Bank berhasil disimpan ke Report Audit.', 'success');
    _renderBankPemHistory(_bankPemPlanId);
    renderAuditSection();
    if (typeof renderReportAuditSection === 'function') renderReportAuditSection();
  };

  // ── Init listeners ────────────────────────────────────────────
  document.getElementById('btnTambahBank')?.addEventListener('click', function() {
    _bankPemState.push(_bankNewEntry());
    _renderBankForm();
  });

  document.getElementById('btnTambahCek')?.addEventListener('click', function() {
    _bankCekState.push({ noCek: '' });
    _renderBankForm();
  });

  document.getElementById('bankPemModal')?.addEventListener('click', function(e) {
    if (e.target === this) window._closeBankPemModal();
  });

  /* ── END MODUL PEMERIKSAAN BANK ── */

  /* ============================================================
     MODUL MATERAI TEMPEL
     ============================================================ */
  const METERAI_KEY = 'akta_meterai_tempel';
  function loadMeterai()  { try { return JSON.parse(localStorage.getItem(METERAI_KEY)) || []; } catch { return []; } }
  function saveMeterai(d) { localStorage.setItem(METERAI_KEY, JSON.stringify(d)); window.API?.sync(METERAI_KEY, d); }

  let _materaiTaskId = null;
  let _materaiPlanId = null;
  let _materaiData   = null; // data import terakhir (denominations array + keterangan)

  // ── Parse HTML dari MTP SPP ────────────────────────────────────
  // Format MTP SPP: kolom TANGGAL | NOMOR | KETERANGAN | DEBET | KREDIT | SALDO
  // Denomination header = baris bold "Materai Rp. 3000" / "Materai Rp 10000"
  // Transaksi: sel pertama = tanggal (DD-MM-YYYY atau DD/MM/YYYY)
  // KREDIT bisa negatif (penggunaan materai)
  function _parseMateraiHtml(htmlStr) {
    const parser = new DOMParser();
    const doc = parser.parseFromString(htmlStr, 'text/html');
    const denominations = [];
    let currentDenom = null;

    function parseNum(str) {
      if (!str) return 0;
      const s = String(str).replace(/\s/g,'');
      // Hilangkan semua titik (ribuan) kecuali tanda minus
      const clean = s.replace(/[^\d-]/g,'');
      return parseInt(clean) || 0;
    }

    const allRows = Array.from(doc.querySelectorAll('tr'));
    allRows.forEach(row => {
      const cells   = Array.from(row.querySelectorAll('td, th'));
      const texts   = cells.map(c => c.textContent.replace(/\s+/g,' ').trim());
      const rowText = texts.join(' ').trim();
      if (!rowText) return;

      // ── Baris header denominasi ──
      // "Materai Rp. 3000", "Materai Rp 10000", "Materai Rp. 10.000"
      const denomMatch = rowText.match(/materai\s+rp[.\s]*([\d.,]+)/i);
      if (denomMatch) {
        const rawNum = denomMatch[1].replace(/\./g,'').replace(',','');
        const nominal = parseInt(rawNum) || 0;
        const label   = `Materai Rp ${nominal.toLocaleString('id-ID')}`;
        currentDenom  = {
          label, nominal,
          saldoAwal:   0,
          transactions:[],
          saldoAkhir:  0,
          totalDebet:  0,
          totalKredit: 0,
          fisik:       0,
          uangRp10000: 0,
          pemeriksaan: 0,
          keterangan:  '',
        };
        denominations.push(currentDenom);
        return;
      }

      if (!currentDenom) return;

      // ── SALDO AWAL ──
      if (rowText.match(/saldo\s*awal/i)) {
        currentDenom.saldoAwal = parseNum(texts[texts.length - 1]);
        return;
      }

      // ── SALDO AKHIR ──
      if (rowText.match(/saldo\s*akhir/i)) {
        const len = texts.length;
        currentDenom.totalDebet  = parseNum(texts[len - 3]);
        currentDenom.totalKredit = parseNum(texts[len - 2]);
        currentDenom.saldoAkhir  = parseNum(texts[len - 1]);
        return;
      }

      // ── Baris header tabel (TANGGAL / NOMOR / dll) ──
      if (rowText.match(/tanggal.*nomor/i) || rowText.match(/^(no\b|#\b)/i)) return;

      // ── Baris transaksi: sel pertama adalah tanggal ──
      // Format: DD-MM-YYYY, DD/MM/YYYY, YYYY-MM-DD
      const firstCell = texts[0] || '';
      const isDate = /^\d{2}[.\-\/]\d{2}[.\-\/]\d{2,4}$/.test(firstCell) ||
                     /^\d{4}[.\-\/]\d{2}[.\-\/]\d{2}$/.test(firstCell);
      if (isDate && texts.length >= 5) {
        const len = texts.length;
        // keterangan bisa span 1 atau lebih kolom tengah
        const ket = texts.slice(2, len - 3).join(' ').trim() || texts[2] || '';
        currentDenom.transactions.push({
          tanggal:    firstCell,
          nomor:      texts[1] || '',
          keterangan: ket,
          debet:      parseNum(texts[len - 3]),
          kredit:     parseNum(texts[len - 2]),
          saldo:      parseNum(texts[len - 1]),
        });
      }
    });

    // Fallback: jika SALDO AKHIR tidak terdeteksi, ambil dari baris terakhir transaksi
    denominations.forEach(d => {
      if (d.saldoAkhir === 0 && d.transactions.length) {
        d.saldoAkhir = d.transactions[d.transactions.length - 1].saldo;
      }
      if (d.totalDebet === 0)
        d.totalDebet  = d.transactions.reduce((s, t) => s + Math.max(0, t.debet),  0);
      if (d.totalKredit === 0)
        d.totalKredit = d.transactions.reduce((s, t) => s + t.kredit, 0);
      // Rumus: Pemeriksaan = Fisik + Uang Rp 10.000 - Saldo Akhir
      d.pemeriksaan = d.fisik + d.uangRp10000 - d.saldoAkhir;
    });

    return denominations;
  }

  // ── Render tabel per denominasi ───────────────────────────────
  function _renderMateraiDenomContainer() {
    const el = document.getElementById('materaiDenomContainer');
    if (!el) return;
    if (!_materaiData || !_materaiData.length) {
      el.innerHTML = '';
      return;
    }

    el.innerHTML = _materaiData.map((d, di) => {
      // Rumus: Pemeriksaan = Fisik + Uang Rp.10.000 - Saldo Akhir
      const pem    = d.fisik + d.uangRp10000 - d.saldoAkhir;
      const pemOk  = pem === 0;
      const pemClr = pemOk ? '#166534' : '#dc2626';
      const pemBg  = pemOk ? '#dcfce7'  : '#fee2e2';
      const pemIco = pemOk ? '✓ Sesuai' : (pem > 0 ? `✗ Lebih ${pem}` : `✗ Kurang ${Math.abs(pem)}`);

      const trRows = d.transactions.map((tr, ti) => {
        const isDebet  = tr.debet > 0;
        const isKredit = tr.kredit !== 0;
        const kreditDisp = tr.kredit === 0 ? '–'
                         : tr.kredit > 0   ? `+${tr.kredit}`
                         : String(tr.kredit);
        return `<tr>
          <td style="font-size:.79rem;color:#64748b;text-align:center">${ti + 1}</td>
          <td style="font-size:.8rem;white-space:nowrap">${tr.tanggal}</td>
          <td style="font-size:.77rem;color:#4f46e5">${tr.nomor}</td>
          <td style="font-size:.8rem">${tr.keterangan}</td>
          <td style="text-align:center;color:#16a34a;font-weight:600">${isDebet ? tr.debet : '–'}</td>
          <td style="text-align:center;font-weight:600;color:${isKredit?(tr.kredit<0?'#dc2626':'#16a34a'):'#94a3b8'}">${kreditDisp}</td>
          <td style="text-align:center;font-weight:700">${tr.saldo}</td>
        </tr>`;
      }).join('');

      const hasTransaksi = d.transactions.length > 0;

      return `
        <div style="margin-bottom:22px;border:1.5px solid #d97706;border-radius:10px;overflow:hidden">
          <!-- Header denominasi -->
          <div style="background:linear-gradient(135deg,#78350f,#b45309);color:#fff;padding:10px 16px;font-size:.9rem;font-weight:700;display:flex;align-items:center;gap:6px">
            ⭐ ${d.label}
            <span style="margin-left:auto;font-size:.74rem;font-weight:400;background:rgba(255,255,255,.18);padding:2px 10px;border-radius:8px">
              ${hasTransaksi ? d.transactions.length + ' TRANSAKSI' : 'TIDAK ADA TRANSAKSI'}
            </span>
          </div>

          <!-- Tabel transaksi -->
          <div style="overflow-x:auto">
            <table class="kas-table" style="min-width:520px">
              <thead>
                <tr>
                  <th style="width:36px;text-align:center">NO</th>
                  <th>TANGGAL</th>
                  <th>NOMOR</th>
                  <th>KETERANGAN</th>
                  <th style="text-align:center">DEBET</th>
                  <th style="text-align:center">KREDIT</th>
                  <th style="text-align:center">SALDO</th>
                </tr>
              </thead>
              <tbody>
                <tr style="background:#f0fdf4;font-size:.8rem">
                  <td colspan="4" style="text-align:right;padding-right:14px;font-weight:700;color:#166534">SALDO AWAL</td>
                  <td style="text-align:center;color:#94a3b8">–</td>
                  <td style="text-align:center;color:#94a3b8">–</td>
                  <td style="text-align:center;font-weight:700;color:#166534">${d.saldoAwal}</td>
                </tr>
                ${hasTransaksi ? trRows : `<tr><td colspan="7" style="text-align:center;color:#94a3b8;padding:12px;font-size:.8rem;font-style:italic">Tidak ada transaksi pada periode ini</td></tr>`}
                <tr style="background:#fef3c7;font-size:.83rem">
                  <td colspan="4" style="text-align:right;padding-right:14px;font-weight:700;color:#92400e">SALDO AKHIR</td>
                  <td style="text-align:center;font-weight:700;color:#16a34a">${d.totalDebet !== 0 ? d.totalDebet : '–'}</td>
                  <td style="text-align:center;font-weight:700;color:${d.totalKredit < 0 ? '#dc2626' : '#16a34a'}">${d.totalKredit !== 0 ? d.totalKredit : '–'}</td>
                  <td style="text-align:center;font-weight:700;color:#92400e">${d.saldoAkhir}</td>
                </tr>
              </tbody>
            </table>
          </div>

          <!-- Form pemeriksaan auditor -->
          <div style="padding:14px 16px;background:#fffbeb;border-top:1px solid #fed7aa">
            <div style="font-size:.72rem;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:#92400e;margin-bottom:10px">
              📋 PEMERIKSAAN FISIK — ${d.label}
            </div>
            <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px;align-items:end">

              <!-- Input Fisik -->
              <div>
                <label style="font-size:.74rem;font-weight:700;color:#78350f;display:block;margin-bottom:4px">
                  QTY FISIK (lembar materai)
                </label>
                <input type="number" min="0" value="${d.fisik}"
                       style="width:100%;padding:7px 10px;border:2px solid #d97706;border-radius:7px;text-align:center;font-weight:700;font-size:.92rem;background:#fff"
                       oninput="window._materaiInputChange(${di},'fisik',this.value)" />
              </div>

              <!-- Input Uang Rp 10.000 -->
              <div>
                <label style="font-size:.74rem;font-weight:700;color:#78350f;display:block;margin-bottom:4px">
                  QTY UANG Rp 10.000 (lembar)
                </label>
                <input type="number" min="0" value="${d.uangRp10000}"
                       style="width:100%;padding:7px 10px;border:2px solid #f59e0b;border-radius:7px;text-align:center;font-weight:700;font-size:.92rem;background:#fff"
                       oninput="window._materaiInputChange(${di},'uangRp10000',this.value)" />
              </div>

              <!-- Saldo Akhir (readonly info) -->
              <div>
                <label style="font-size:.74rem;font-weight:700;color:#78350f;display:block;margin-bottom:4px">
                  SALDO AKHIR (buku)
                </label>
                <div style="padding:7px 10px;border:2px solid #e5e7eb;border-radius:7px;text-align:center;font-weight:700;font-size:.92rem;background:#f8fafc;color:#374151">
                  ${d.saldoAkhir}
                </div>
              </div>

              <!-- Hasil Pemeriksaan -->
              <div>
                <label style="font-size:.74rem;font-weight:700;color:${pemClr};display:block;margin-bottom:4px">
                  PEMERIKSAAN (Fisik + Uang − Saldo)
                </label>
                <div style="padding:7px 10px;border:2px solid ${pemClr};border-radius:7px;text-align:center;font-weight:800;font-size:.95rem;background:${pemBg};color:${pemClr}">
                  ${pem} &nbsp;—&nbsp; ${pemIco}
                </div>
              </div>
            </div>

            <!-- Rumus yang dipakai (info) -->
            <div style="margin-top:8px;padding:6px 10px;background:#fef9c3;border:1px solid #fde047;border-radius:6px;font-size:.73rem;color:#713f12">
              📐 <strong>Rumus:</strong> Fisik (${d.fisik}) + Uang Rp 10.000 (${d.uangRp10000}) − Saldo Akhir (${d.saldoAkhir}) = <strong>${pem}</strong>
            </div>
          </div>
        </div>`;
    }).join('');
  }

  // ── Callback perubahan input fisik / uang ─────────────────────
  window._materaiInputChange = function(idx, field, val) {
    if (!_materaiData || !_materaiData[idx]) return;
    _materaiData[idx][field]   = parseInt(val) || 0;
    // Hitung ulang pemeriksaan: Fisik + Uang Rp 10.000 - Saldo Akhir
    _materaiData[idx].pemeriksaan =
      _materaiData[idx].fisik + _materaiData[idx].uangRp10000 - _materaiData[idx].saldoAkhir;
    _renderMateraiDenomContainer();
  };

  // ── Buka modal ────────────────────────────────────────────────
  window._openMateraiModal = function(taskId) {
    tasks = loadTasks();
    const t = tasks.find(x => String(x.id) === String(taskId));
    if (!t) return;
    _materaiTaskId = taskId;
    _materaiPlanId = t.planId;

    // Plan info
    const infoEl = document.getElementById('materaiPlanInfo');
    if (infoEl) {
      infoEl.innerHTML = `
        <div class="unit-info-grid">
          <div class="unit-info-item"><label>No SPT</label><span style="font-weight:700">${t.noSPT}</span></div>
          <div class="unit-info-item"><label>Jenis Audit</label><span>${t.jenisAudit}</span></div>
          <div class="unit-info-item"><label>Cabang</label><span>${t.cabangPlan}${t.cabangArea ? ' ' + areaBadge(t.cabangArea) : ''}</span></div>
          <div class="unit-info-item"><label>Status</label><span>${taskStatusBadge(t.status)}</span></div>
        </div>`;
    }

    // Load data tersimpan untuk plan ini (jika ada)
    const saved = loadMeterai().find(m => String(m.planId) === String(t.planId));
    if (saved) {
      _materaiData = JSON.parse(JSON.stringify(saved.denominations || []));
      const ketEl = document.getElementById('materaiKeterangan');
      if (ketEl) ketEl.value = saved.keterangan || '';
      const statEl = document.getElementById('materaiImportStatus');
      if (statEl) statEl.innerHTML = `<span style="color:#16a34a">✓ Data tersimpan dari file: <strong>${saved.fileName || '—'}</strong></span>`;
    } else {
      _materaiData = null;
      const ketEl = document.getElementById('materaiKeterangan');
      if (ketEl) ketEl.value = '';
      const statEl = document.getElementById('materaiImportStatus');
      if (statEl) statEl.textContent = '';
    }

    _renderMateraiDenomContainer();

    const modal = document.getElementById('materaiModal');
    if (modal) { modal.classList.remove('hidden'); modal.style.display = 'flex'; }
  };

  // ── Tutup modal ───────────────────────────────────────────────
  window._closeMateraiModal = function() {
    const m = document.getElementById('materaiModal');
    if (m) { m.classList.add('hidden'); m.style.display = ''; }
    _materaiTaskId = null; _materaiPlanId = null; _materaiData = null;
  };

  // ── Simpan data materai ───────────────────────────────────────
  window._saveMaterai = function() {
    if (!_materaiPlanId || !_materaiData || !_materaiData.length) {
      showToast('Import file HTML terlebih dahulu.', 'error'); return;
    }
    const keterangan = document.getElementById('materaiKeterangan')?.value || '';
    const recs = loadMeterai();
    const idx  = recs.findIndex(m => String(m.planId) === String(_materaiPlanId));
    const newRec = {
      id:           Date.now(),
      planId:       _materaiPlanId,
      taskId:       _materaiTaskId,
      savedAt:      new Date().toISOString(),
      fileName:     _materaiLastFileName || recs[idx]?.fileName || '',
      denominations: JSON.parse(JSON.stringify(_materaiData)),
      keterangan,
    };
    if (idx >= 0) recs[idx] = newRec; else recs.push(newRec);
    saveMeterai(recs);
    // Otomatis tandai tersimpan di Report Audit
    _markSavedPem(_materaiPlanId, 'meterai');
    showToast('Pemeriksaan Materai Tempel berhasil disimpan ke Report Audit.', 'success');
    renderAuditSection();
    if (typeof renderReportAuditSection === 'function') renderReportAuditSection();
    const msgEl = document.getElementById('materaiSaveMsg');
    if (msgEl) msgEl.innerHTML = '<span style="color:#16a34a">✓ Tersimpan di Report Audit</span>';
  };

  // ── Init listener file input & drag-drop ─────────────────────
  let _materaiLastFileName = '';

  function _processMateraiFile(file) {
    if (!file) return;
    if (!file.name.match(/\.(htm|html)$/i)) {
      showToast('Hanya file .htm / .html yang diterima.', 'error'); return;
    }
    _materaiLastFileName = file.name;
    const reader = new FileReader();
    reader.onload = function(e) {
      const html = e.target.result;
      const parsed = _parseMateraiHtml(html);
      if (!parsed.length) {
        showToast('Tidak ada data denominasi yang terdeteksi dalam file HTML ini.', 'error');
        return;
      }
      _materaiData = parsed;
      _renderMateraiDenomContainer();
      const statEl = document.getElementById('materaiImportStatus');
      if (statEl) statEl.innerHTML = `<span style="color:#16a34a">✓ Import berhasil: <strong>${file.name}</strong> — ${parsed.length} denominasi, ${parsed.reduce((s,d)=>s+d.transactions.length,0)} transaksi</span>`;
    };
    reader.readAsText(file, 'utf-8');
  }

  document.getElementById('materaiFileInput')?.addEventListener('change', function() {
    _processMateraiFile(this.files[0]);
    this.value = '';
  });

  document.getElementById('materaiBrowseBtn')?.addEventListener('click', function() {
    document.getElementById('materaiFileInput')?.click();
  });

  const _mDz = document.getElementById('materaiDropZone');
  if (_mDz) {
    _mDz.addEventListener('dragover', e => { e.preventDefault(); _mDz.style.background = '#fef3c7'; });
    _mDz.addEventListener('dragleave', () => { _mDz.style.background = '#fffbeb'; });
    _mDz.addEventListener('drop', e => {
      e.preventDefault(); _mDz.style.background = '#fffbeb';
      _processMateraiFile(e.dataTransfer.files[0]);
    });
  }

  document.getElementById('materaiModal')?.addEventListener('click', function(e) {
    if (e.target === this) window._closeMateraiModal();
  });

  /* ── END MODUL MATERAI TEMPEL ── */

  /* ============================================================
     MODUL BPKB ONHAND
     ============================================================ */
  const BPKB_DB_KEY   = 'akta_bpkb_db';
  const BPKB_SCAN_KEY = 'akta_bpkb_scan';
  const BPKB_INFO_KEY = 'akta_bpkb_info';

  function loadBpkbDb()    { try { return JSON.parse(localStorage.getItem(BPKB_DB_KEY))   || []; } catch { return []; } }
  function saveBpkbDb(d)   { localStorage.setItem(BPKB_DB_KEY,   JSON.stringify(d)); window.API?.sync(BPKB_DB_KEY,   d); }
  function loadBpkbScan()  { try { return JSON.parse(localStorage.getItem(BPKB_SCAN_KEY)) || []; } catch { return []; } }
  function saveBpkbScan(d) { localStorage.setItem(BPKB_SCAN_KEY, JSON.stringify(d)); window.API?.sync(BPKB_SCAN_KEY, d); }
  function loadBpkbInfoAll()  { try { return JSON.parse(localStorage.getItem(BPKB_INFO_KEY)) || []; } catch { return []; } }
  function saveBpkbInfoAll(d) { localStorage.setItem(BPKB_INFO_KEY, JSON.stringify(d)); window.API?.sync(BPKB_INFO_KEY, d); }
  function getBpkbInfo(planId) {
    return loadBpkbInfoAll().find(r => String(r.planId) === String(planId)) || { planId: String(planId), auditee:'', batasanTgl:'', ttBelum:'' };
  }
  function saveBpkbInfo(data) {
    const all = loadBpkbInfoAll();
    const idx = all.findIndex(r => String(r.planId) === String(data.planId));
    if (idx >= 0) all[idx] = data; else all.push(data);
    saveBpkbInfoAll(all);
  }
  window._bpkbInfoAutoSave = function() {
    if (!_bpkbPlanId) return;
    const g = id => document.getElementById(id);
    saveBpkbInfo({
      planId:     String(_bpkbPlanId),
      auditee:    (g('bpkbInfo_auditee')?.value   || '').trim(),
      batasanTgl: (g('bpkbInfo_batasanTgl')?.value || '').trim(),
      ttBelum:    (g('bpkbInfo_ttBelum')?.value   || '').trim(),
    });
  };

  let _bpkbTaskId = null;
  let _bpkbPlanId = null;
  let _bpkbTab    = 'scan'; // 'scan' | 'belum' | 'luar'

  // ── Parse Excel BPKB ─────────────────────────────────────────
  function _parseBpkbExcel(data) {
    const wb  = XLSX.read(data, { type: 'array', cellDates: true });
    const ws  = wb.Sheets[wb.SheetNames[0]];
    const rows = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });
    if (!rows.length) return [];

    // Cari baris header: harus mengandung minimal 3 keyword kolom yang dikenal
    // (menghindari salah deteksi pada baris judul seperti "LAPORAN BPKB ON HAND")
    const HEADER_KEYWORDS = ['BPKB','POLISI','TERIMA','PEMILIK','MESIN','RANGKA','JENIS','UMUR'];
    let headerIdx = 0;
    for (let i = 0; i < Math.min(15, rows.length); i++) {
      const r = rows[i].map(c => String(c).toUpperCase().trim());
      const matchCount = HEADER_KEYWORDS.filter(kw => r.some(c => c.includes(kw))).length;
      if (matchCount >= 3) { headerIdx = i; break; }
    }

    const headers = rows[headerIdx].map(c => String(c).trim().toUpperCase());
    const colIdx  = k => headers.findIndex(h => h.includes(k));

    const iNoBpkb    = colIdx('BPKB');
    const iNoPolisi  = headers.findIndex(h => h.includes('POLISI'));
    const iTglTerima = headers.findIndex(h => h.includes('TERIMA') || h.includes('TGL'));
    const iNama      = headers.findIndex(h => h.includes('PEMILIK') || h.includes('NAMA'));
    const iNoMesin   = headers.findIndex(h => h.includes('MESIN'));
    const iNoRangka  = headers.findIndex(h => h.includes('RANGKA'));
    const iJenis     = headers.findIndex(h => h === 'JENIS' || h.includes('JENIS'));
    const iUmur      = headers.findIndex(h => h === 'UMUR'  || h.includes('UMUR'));

    const today = new Date();
    const result = [];
    for (let i = headerIdx + 1; i < rows.length; i++) {
      const r = rows[i];
      if (!r || !r.length) continue;
      const noBpkb = String(r[iNoBpkb] ?? '').trim();
      if (!noBpkb) continue;

      // Hitung umur dari TGL TERIMA
      let umurHari = iUmur >= 0 ? (parseInt(r[iUmur]) || 0) : 0;
      if (!umurHari && iTglTerima >= 0 && r[iTglTerima]) {
        try {
          const tglStr = String(r[iTglTerima]).trim();
          let tglDate;
          if (tglStr.match(/^\d{4}-\d{2}-\d{2}/)) {
            tglDate = new Date(tglStr);
          } else if (tglStr.match(/^\d{2}-\d{2}-\d{4}/)) {
            const [d,m,y] = tglStr.split('-');
            tglDate = new Date(`${y}-${m}-${d}`);
          } else if (r[iTglTerima] instanceof Date) {
            tglDate = r[iTglTerima];
          }
          if (tglDate && !isNaN(tglDate)) {
            umurHari = Math.floor((today - tglDate) / 86400000);
          }
        } catch {}
      }

      const jenis = String(r[iJenis] ?? '').trim().toUpperCase() || 'REG';
      result.push({
        noBpkb:    noBpkb,
        noPolisi:  String(r[iNoPolisi]  ?? '').trim(),
        tglTerima: String(r[iTglTerima] ?? '').trim(),
        namaPemilik: String(r[iNama]    ?? '').trim(),
        noMesin:   String(r[iNoMesin]   ?? '').trim(),
        noRangka:  String(r[iNoRangka]  ?? '').trim(),
        jenis,
        umur:      umurHari,
      });
    }
    return result;
  }

  // ── Hitung statistik ─────────────────────────────────────────
  function _bpkbCalcStats(db, scanList) {
    const total   = db.length;
    const reg     = db.filter(b => b.jenis === 'REG').length;
    const kds     = db.filter(b => b.jenis !== 'REG').length;
    const scanned = scanList.filter(s => String(s.planId) === String(_bpkbPlanId) && s.foundInDb).length;
    const belum   = total - scanned;
    const reg120  = db.filter(b => b.jenis === 'REG' && b.umur > 120).length;
    const reg120Pct = reg > 0 ? ((reg120 / reg) * 100).toFixed(2) : '0';
    return { total, reg, kds, scanned, belum, reg120, reg120Pct };
  }

  // ── Render statistik ─────────────────────────────────────────
  function _bpkbRenderStats() {
    const db       = loadBpkbDb();
    const scanList = loadBpkbScan();
    const s        = _bpkbCalcStats(db, scanList);

    const statEl = document.getElementById('bpkbStats');
    const cardsEl = document.getElementById('bpkbStatCards');
    if (!statEl || !cardsEl) return;

    statEl.style.display = db.length ? '' : 'none';
    if (!db.length) return;

    const card = (val, label, clr = '#374151', bg = '#f8fafc', border = '#e5e7eb') =>
      `<div style="background:${bg};border:2px solid ${border};border-radius:8px;padding:10px 16px;text-align:center;min-width:90px">
        <div style="font-size:1.3rem;font-weight:800;color:${clr}">${val}</div>
        <div style="font-size:.68rem;font-weight:700;text-transform:uppercase;color:#6b7280;margin-top:2px;letter-spacing:.04em">${label}</div>
      </div>`;

    cardsEl.innerHTML =
      card(s.total,   'Total BPKB') +
      card(s.reg,     'REG') +
      card(s.kds,     'KDS') +
      card(s.scanned, 'Sudah Scan', '#2563eb', '#eff6ff', '#bfdbfe') +
      card(s.belum,   'Belum Scan', '#dc2626', '#fef2f2', '#fca5a5') +
      card(`${s.reg120}<br><span style="font-size:.72rem">(${s.reg120Pct}%)</span>`, 'REG >120 Hari', '#d97706', '#fffbeb', '#fcd34d');

    const dbStatusEl = document.getElementById('bpkbDbStatus');
    if (dbStatusEl) dbStatusEl.textContent = '● DATABASE AKTIF';
  }

  // ── Render hasil pemeriksaan ──────────────────────────────────
  function _bpkbRenderHasil() {
    const db       = loadBpkbDb();
    const scanList = loadBpkbScan().filter(s => String(s.planId) === String(_bpkbPlanId));
    const s        = _bpkbCalcStats(db, scanList);

    const summEl  = document.getElementById('bpkbHasilSummary');
    const tabBarEl= document.getElementById('bpkbTabBar');
    const tabConEl= document.getElementById('bpkbTabContent');
    const cntEl   = document.getElementById('bpkbHasilCount');
    if (!summEl) return;

    const scanDone = scanList.filter(s => s.foundInDb);
    const luarDb   = scanList.filter(s => !s.foundInDb);
    const belumDb  = db.filter(b => !scanList.some(s => s.foundInDb && s.noBpkb === b.noBpkb));

    if (cntEl) cntEl.textContent = scanDone.length + ' TERSCAN';

    summEl.innerHTML = `
      <div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center">
        <span>Total DB: <strong>${db.length}</strong></span>
        <span style="color:#2563eb">Sudah Scan: <strong>${scanDone.length}</strong></span>
        <span style="color:#dc2626">Belum: <strong>${belumDb.length}</strong></span>
        ${luarDb.length ? `<span style="color:#d97706">Fisik Diluar: <strong>${luarDb.length}</strong></span>` : ''}
      </div>`;

    const tabs = [
      { key: 'scan',  label: '✅ Sudah Scan',      count: scanDone.length, clr: '#2563eb' },
      { key: 'belum', label: '✗ Belum Scan',        count: belumDb.length,  clr: '#dc2626' },
      { key: 'luar',  label: '🔴 Fisik Diluar On Hand', count: luarDb.length, clr: '#d97706' },
    ];

    if (tabBarEl) {
      tabBarEl.innerHTML = tabs.map(t => `
        <button onclick="window._bpkbSetTab('${t.key}')"
                style="background:${_bpkbTab===t.key?'#1e3a5f':'#f1f5f9'};color:${_bpkbTab===t.key?'#fff':t.clr};
                       border:1.5px solid ${_bpkbTab===t.key?'#1e3a5f':'#e2e8f0'};border-radius:6px;
                       padding:5px 12px;font-size:.8rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:6px">
          ${t.label}
          <span style="background:${_bpkbTab===t.key?'rgba(255,255,255,.2)':'#e2e8f0'};border-radius:10px;padding:1px 7px;font-size:.72rem">${t.count}</span>
        </button>`).join('');
    }

    if (!tabConEl) return;

    const tableHead = `<table class="kas-table" style="font-size:.79rem">
      <thead><tr>
        <th style="width:32px;text-align:center">NO.</th>
        <th>NO BPKB</th><th>NO POLISI</th><th>TGL TERIMA</th>
        <th>NAMA PEMILIK</th><th>NO MESIN</th><th>NO RANGKA</th>
        <th style="text-align:center">JENIS</th><th style="text-align:center">UMUR</th>
        <th>KETERANGAN</th><th style="width:36px"></th>
      </tr></thead><tbody>`;

    if (_bpkbTab === 'scan') {
      if (!scanDone.length) {
        tabConEl.innerHTML = '<div style="text-align:center;color:#9ca3af;padding:16px;font-style:italic;font-size:.82rem">Belum ada BPKB yang discan.</div>';
      } else {
        tabConEl.innerHTML = tableHead + scanDone.map((s, i) => {
          const b = db.find(b => b.noBpkb === s.noBpkb) || {};
          return `<tr>
            <td style="text-align:center">${i+1}</td>
            <td style="font-weight:700;font-family:monospace;font-size:.77rem;color:#1e40af">${s.noBpkb}</td>
            <td>${b.noPolisi||s.noPolisi||'—'}</td>
            <td style="white-space:nowrap">${b.tglTerima||'—'}</td>
            <td style="font-size:.77rem">${b.namaPemilik||'—'}</td>
            <td style="font-family:monospace;font-size:.76rem">${b.noMesin||'—'}</td>
            <td style="font-family:monospace;font-size:.76rem">${b.noRangka||'—'}</td>
            <td style="text-align:center"><span style="background:#dbeafe;color:#1e40af;border-radius:10px;padding:1px 7px;font-size:.72rem;font-weight:700">${b.jenis||'REG'}</span></td>
            <td style="text-align:center;font-weight:600;color:${(b.umur||0)>120?'#d97706':'#374151'}">${b.umur||'—'}</td>
            <td style="font-size:.77rem;color:#6b7280">${s.keterangan||''}</td>
            <td><button onclick="window._bpkbHapusScan('${s.id}')" style="background:#fee2e2;border:none;border-radius:4px;padding:2px 8px;cursor:pointer;color:#dc2626;font-size:.8rem">✕</button></td>
          </tr>`;
        }).join('') + '</tbody></table>';
      }
    } else if (_bpkbTab === 'belum') {
      if (!belumDb.length) {
        tabConEl.innerHTML = '<div style="text-align:center;color:#22c55e;padding:16px;font-size:.82rem;font-weight:700">✓ Semua BPKB sudah discan!</div>';
      } else {
        tabConEl.innerHTML = tableHead + belumDb.map((b, i) => `
          <tr style="background:${b.umur>120?'#fff8f0':''}">
            <td style="text-align:center">${i+1}</td>
            <td style="font-weight:700;font-family:monospace;font-size:.77rem;color:#dc2626">${b.noBpkb}</td>
            <td>${b.noPolisi}</td>
            <td style="white-space:nowrap">${b.tglTerima}</td>
            <td style="font-size:.77rem">${b.namaPemilik}</td>
            <td style="font-family:monospace;font-size:.76rem">${b.noMesin}</td>
            <td style="font-family:monospace;font-size:.76rem">${b.noRangka}</td>
            <td style="text-align:center"><span style="background:#dbeafe;color:#1e40af;border-radius:10px;padding:1px 7px;font-size:.72rem;font-weight:700">${b.jenis}</span></td>
            <td style="text-align:center;font-weight:600;color:${b.umur>120?'#d97706':'#374151'}">${b.umur}</td>
            <td>—</td><td></td>
          </tr>`).join('') + '</tbody></table>';
      }
    } else {
      if (!luarDb.length) {
        tabConEl.innerHTML = '<div style="text-align:center;color:#9ca3af;padding:16px;font-style:italic;font-size:.82rem">Tidak ada BPKB fisik diluar database.</div>';
      } else {
        tabConEl.innerHTML = tableHead + luarDb.map((s, i) => `
          <tr style="background:#fff8f0">
            <td style="text-align:center">${i+1}</td>
            <td style="font-weight:700;font-family:monospace;font-size:.77rem;color:#d97706">${s.noBpkb}</td>
            <td>—</td><td>—</td><td>—</td><td>—</td><td>—</td>
            <td style="text-align:center"><span style="background:#fed7aa;color:#92400e;border-radius:10px;padding:1px 7px;font-size:.72rem;font-weight:700">LUAR</span></td>
            <td>—</td>
            <td style="font-size:.77rem;color:#6b7280">${s.keterangan||''}</td>
            <td><button onclick="window._bpkbHapusScan('${s.id}')" style="background:#fee2e2;border:none;border-radius:4px;padding:2px 8px;cursor:pointer;color:#dc2626;font-size:.8rem">✕</button></td>
          </tr>`).join('') + '</tbody></table>';
      }
    }

    // Simpan ke Report Audit bar
    const simpanEl = document.getElementById('bpkbSimpanBar');
    if (simpanEl && scanList.length > 0) {
      const _bpkbSaved = loadSavedPem().some(s => String(s.planId) === String(_bpkbPlanId) && s.type === 'bpkb');
      const _bpkbSavedAt = _bpkbSaved
        ? loadSavedPem().find(s => String(s.planId) === String(_bpkbPlanId) && s.type === 'bpkb').savedAt
        : null;
      simpanEl.innerHTML = `
        <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:12px 14px;
             background:${_bpkbSaved?'#dcfce7':'#f0f9ff'};border:1.5px solid ${_bpkbSaved?'#86efac':'#bae6fd'};border-radius:8px">
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="${_bpkbSaved?'#166534':'#0369a1'}" stroke-width="2">
            <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/>
            <polyline points="17 21 17 13 7 13 7 21"/>
          </svg>
          <div style="flex:1">
            <div style="font-size:.83rem;font-weight:700;color:${_bpkbSaved?'#166534':'#0369a1'}">
              ${_bpkbSaved?'✓ BPKB Onhand sudah disimpan ke Report Audit':'Simpan hasil ke Report Audit'}
            </div>
            <div style="font-size:.74rem;color:#64748b;margin-top:2px">
              ${_bpkbSaved
                ? 'Tersimpan: ' + new Date(_bpkbSavedAt).toLocaleString('id-ID',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}) + ' · ' + scanDone.length + ' terscan, ' + belumDb.length + ' belum'
                : scanDone.length + ' BPKB terscan · ' + belumDb.length + ' belum scan'}
            </div>
          </div>
          <button onclick="window._bpkbSimpanKeReport()"
                  style="background:${_bpkbSaved?'#16a34a':'#0369a1'};color:#fff;border:none;border-radius:7px;
                         padding:8px 16px;font-size:.82rem;font-weight:700;cursor:pointer;white-space:nowrap">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:middle;margin-right:5px">
              <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/>
              <polyline points="17 21 17 13 7 13 7 21"/>
            </svg>
            ${_bpkbSaved?'Perbarui ke Report Audit':'Simpan ke Report Audit'}
          </button>
        </div>`;
    } else if (simpanEl) {
      simpanEl.innerHTML = '';
    }

    // Selalu sinkronkan dropdown agar item yang sudah discan tidak muncul lagi
    _bpkbPopulateDropdown();
  }

  // ── Tab switch ────────────────────────────────────────────────
  window._bpkbSetTab = function(tab) { _bpkbTab = tab; _bpkbRenderHasil(); };

  // ── Data combobox (BPKB belum discan untuk plan aktif) ────────
  let _bpkbComboData = [];

  // ── Populate data combobox ────────────────────────────────────
  function _bpkbPopulateDropdown() {
    const db      = loadBpkbDb();
    const scanned = new Set(
      loadBpkbScan()
        .filter(s => String(s.planId) === String(_bpkbPlanId) && s.foundInDb)
        .map(s => s.noBpkb.toUpperCase())
    );
    _bpkbComboData = db.filter(b => !scanned.has(b.noBpkb.toUpperCase()));

    // Update placeholder search
    const searchEl = document.getElementById('bpkbComboSearch');
    if (searchEl && !searchEl.value) {
      searchEl.placeholder = `Ketik No. BPKB, nama, atau no. polisi… (${_bpkbComboData.length} belum discan)`;
    }
    // Re-render list sesuai teks pencarian yang sudah ada
    _bpkbRenderComboList(searchEl?.value || '');
  }

  // ── Render item list combobox berdasar filter teks ────────────
  function _bpkbRenderComboList(filter) {
    const listEl = document.getElementById('bpkbComboList');
    if (!listEl) return;

    const q        = filter.trim().toUpperCase();
    const filtered = q
      ? _bpkbComboData.filter(b =>
          b.noBpkb.toUpperCase().includes(q) ||
          (b.namaPemilik || '').toUpperCase().includes(q) ||
          (b.noPolisi    || '').toUpperCase().includes(q)
        )
      : _bpkbComboData;

    if (!filtered.length) {
      listEl.innerHTML = `<div style="padding:12px 16px;font-size:.82rem;color:#9ca3af;text-align:center;font-style:italic">
        ${q ? 'Tidak ada hasil untuk "' + filter + '"' : 'Semua BPKB sudah discan.'}
      </div>`;
      return;
    }

    listEl.innerHTML = filtered.map(b => {
      const safe = b.noBpkb.replace(/\\/g,'\\\\').replace(/'/g,"\\'");
      const hi   = (str) => {
        if (!q || !str) return str || '—';
        const idx = str.toUpperCase().indexOf(q);
        if (idx < 0) return str;
        return str.slice(0,idx) +
               `<mark style="background:#fef08a;border-radius:2px">${str.slice(idx,idx+q.length)}</mark>` +
               str.slice(idx+q.length);
      };
      return `<div onclick="window._bpkbComboSelect('${safe}')"
                   style="padding:8px 14px;cursor:pointer;border-bottom:1px solid #f1f5f9;
                          display:flex;gap:12px;align-items:baseline"
                   onmouseover="this.style.background='#eff6ff'" onmouseout="this.style.background=''">
        <span style="font-family:monospace;font-weight:700;color:#1e40af;flex-shrink:0;font-size:.81rem">${hi(b.noBpkb)}</span>
        <span style="color:#374151;flex:1;font-size:.81rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${hi(b.namaPemilik || '—')}</span>
        <span style="color:#6b7280;font-size:.76rem;flex-shrink:0">${hi(b.noPolisi || '—')}</span>
        <span style="font-size:.72rem;background:${b.jenis==='KDS'?'#fef9c3':'#dbeafe'};color:${b.jenis==='KDS'?'#854d0e':'#1e40af'};
               border-radius:8px;padding:1px 6px;flex-shrink:0;font-weight:700">${b.jenis||'REG'}</span>
      </div>`;
    }).join('');
  }

  // ── Filter saat user mengetik ─────────────────────────────────
  window._bpkbComboFilter = function(val) {
    _bpkbRenderComboList(val);
    const panel = document.getElementById('bpkbComboPanel');
    if (panel) panel.style.display = '';
  };

  // ── Buka panel combobox ───────────────────────────────────────
  window._bpkbComboOpen = function() {
    _bpkbRenderComboList(document.getElementById('bpkbComboSearch')?.value || '');
    const panel  = document.getElementById('bpkbComboPanel');
    const border = document.getElementById('bpkbComboBorder');
    if (panel)  panel.style.display  = '';
    if (border) border.style.borderColor = '#1e3a5f';
  };

  // ── Tutup panel combobox ──────────────────────────────────────
  window._bpkbComboClose = function() {
    const panel  = document.getElementById('bpkbComboPanel');
    const border = document.getElementById('bpkbComboBorder');
    if (panel)  panel.style.display  = 'none';
    if (border) border.style.borderColor = '#d1d5db';
  };

  // ── Toggle buka/tutup ─────────────────────────────────────────
  window._bpkbComboToggle = function() {
    const panel = document.getElementById('bpkbComboPanel');
    if (!panel) return;
    if (panel.style.display === 'none' || !panel.style.display) {
      window._bpkbComboOpen();
    } else {
      window._bpkbComboClose();
    }
  };

  // ── Pilih item dari combobox ──────────────────────────────────
  window._bpkbComboSelect = function(noBpkb) {
    window._bpkbComboClose();
    const searchEl = document.getElementById('bpkbComboSearch');
    if (searchEl) searchEl.value = '';

    // Isi scan input dan tambahkan
    const scanInput = document.getElementById('bpkbScanInput');
    if (scanInput) scanInput.value = noBpkb;
    window._bpkbTambah();
  };

  // ── Tutup combobox saat klik di luar ─────────────────────────
  document.addEventListener('click', function(e) {
    const wrap = document.getElementById('bpkbComboWrap');
    if (wrap && !wrap.contains(e.target)) window._bpkbComboClose();
  });

  // ── Tambah scan ───────────────────────────────────────────────
  window._bpkbTambah = function() {
    const input = document.getElementById('bpkbScanInput');
    const ketEl = document.getElementById('bpkbScanKet');
    const resEl = document.getElementById('bpkbScanResult');
    if (!input || !resEl) return;

    const rawInput = input.value.trim().toUpperCase();
    const ket      = ketEl?.value?.trim() || '';
    if (!rawInput) { resEl.innerHTML = '<span style="color:#dc2626">Masukkan No. BPKB terlebih dahulu.</span>'; return; }

    const db = loadBpkbDb();

    // 1. Exact match
    let found = db.find(b => b.noBpkb.toUpperCase() === rawInput);

    // 2. Fuzzy match: barcode mengeluarkan teks lebih panjang yang MENGANDUNG No. BPKB
    //    (minimal 5 karakter agar tidak false-positive)
    if (!found) {
      found = db.find(b => b.noBpkb.length >= 5 && rawInput.includes(b.noBpkb.toUpperCase()));
    }

    // Canonical No. BPKB: gunakan dari DB supaya konsisten; jika tidak ditemukan pakai input mentah
    const noBpkb = found ? found.noBpkb.toUpperCase() : rawInput;

    const scanList = loadBpkbScan();
    // Cek duplikat pada plan ini (gunakan canonical noBpkb)
    if (scanList.some(s => String(s.planId) === String(_bpkbPlanId) && s.noBpkb === noBpkb)) {
      resEl.innerHTML = `<span style="color:#d97706">⚠ No. BPKB <strong>${noBpkb}</strong> sudah pernah di-input.</span>`;
      return;
    }

    // Keterangan: pakai input manual jika ada; jika tidak dan ditemukan → "Fisik Ada"
    const finalKet = ket || (found ? 'Fisik Ada' : '');

    const newScan = {
      id:         Date.now(),
      planId:     String(_bpkbPlanId),
      taskId:     String(_bpkbTaskId),
      noBpkb,
      noPolisi:   found?.noPolisi || '',
      foundInDb:  !!found,
      keterangan: finalKet,
      scannedAt:  new Date().toISOString(),
      scannedBy:  session.username,
    };
    scanList.push(newScan);
    saveBpkbScan(scanList);

    if (found) {
      resEl.innerHTML = `<span style="color:#166534;font-weight:600">✓ Ditemukan: ${found.namaPemilik} — ${found.noPolisi}</span>`;
      _bpkbTab = 'scan';
    } else {
      resEl.innerHTML = `<span style="color:#d97706;font-weight:600">⚠ Tidak ada dalam database — dicatat sebagai Fisik Diluar On Hand.</span>`;
      _bpkbTab = 'luar';
    }

    input.value = '';
    if (ketEl) ketEl.value = '';
    input.focus();
    _bpkbRenderStats();
    _bpkbRenderHasil();
  };

  // ── Hapus scan ────────────────────────────────────────────────
  window._bpkbHapusScan = function(id) {
    const data = loadBpkbScan().filter(s => String(s.id) !== String(id));
    saveBpkbScan(data);
    _bpkbRenderStats();
    _bpkbRenderHasil();
  };

  // ── Simpan ke Report Audit ────────────────────────────────────
  window._bpkbSimpanKeReport = function() {
    _markSavedPem(_bpkbPlanId, 'bpkb');
    showToast('BPKB Onhand berhasil disimpan ke Report Audit.', 'success');
    renderAuditSection();
    _bpkbRenderHasil();
  };

  // ── Buka modal ────────────────────────────────────────────────
  window._openBpkbModal = function(taskId) {
    tasks = loadTasks();
    const t = tasks.find(x => String(x.id) === String(taskId));
    if (!t) return;
    _bpkbTaskId = taskId;
    _bpkbPlanId = t.planId;
    // Default ke tab "Belum Scan" bila belum ada scan untuk plan ini, supaya data langsung terlihat
    const _existingScans = loadBpkbScan().filter(s => String(s.planId) === String(t.planId));
    _bpkbTab = _existingScans.length > 0 ? 'scan' : 'belum';

    // Plan info card
    const infoEl = document.getElementById('bpkbPlanInfo');
    if (infoEl) {
      infoEl.innerHTML = `
        <div class="unit-info-grid">
          <div class="unit-info-item"><label>No SPT</label><span style="font-weight:700">${t.noSPT}</span></div>
          <div class="unit-info-item"><label>Jenis Audit</label><span>${t.jenisAudit}</span></div>
          <div class="unit-info-item"><label>Cabang</label><span>${t.cabangPlan}${t.cabangArea?' '+areaBadge(t.cabangArea):''}</span></div>
          <div class="unit-info-item"><label>Status</label><span>${taskStatusBadge(t.status)}</span></div>
        </div>`;
    }

    // Plan audit banner
    const banner    = document.getElementById('bpkbPlanBanner');
    const bannerCnt = document.getElementById('bpkbPlanBannerContent');
    if (banner && bannerCnt) {
      bannerCnt.innerHTML =
        '<span><strong>' + (t.noSPT || '—') + '</strong></span>' +
        '<span style="opacity:.6">|</span>' +
        '<span>🏢 ' + (t.cabangPlan || '—') + (t.cabangArea ? ' <span style="font-size:.73rem;background:rgba(255,255,255,.2);border-radius:3px;padding:1px 5px">' + t.cabangArea + '</span>' : '') + '</span>' +
        '<span style="opacity:.6">|</span>' +
        '<span>📋 ' + (t.jenisAudit || '—') + '</span>';
      banner.style.display = '';
    }

    // DB status
    const db = loadBpkbDb();
    const msgEl = document.getElementById('bpkbImportMsg');
    if (msgEl && db.length) {
      msgEl.innerHTML = `<span style="color:#16a34a">✅ ${db.length} data berhasil dimuat dari database aktif</span>`;
    } else if (msgEl) {
      msgEl.textContent = '';
    }

    // Isi form INFORMASI dari data tersimpan
    const bpkbInfo = getBpkbInfo(t.planId);
    const _setBpkbField = (id, val) => { const el = document.getElementById(id); if (el) el.value = val || ''; };
    _setBpkbField('bpkbInfo_auditee',    bpkbInfo.auditee);
    _setBpkbField('bpkbInfo_batasanTgl', bpkbInfo.batasanTgl || new Date().toISOString().slice(0,10));
    _setBpkbField('bpkbInfo_ttBelum',    bpkbInfo.ttBelum);

    // Reset scan form
    const scanInput = document.getElementById('bpkbScanInput');
    if (scanInput) scanInput.value = '';
    const ketInput = document.getElementById('bpkbScanKet');
    if (ketInput) ketInput.value = '';
    const resEl = document.getElementById('bpkbScanResult');
    if (resEl) resEl.innerHTML = '';

    _bpkbRenderStats();
    _bpkbRenderHasil();

    // Navigasi ke section (bukan buka modal)
    document.querySelectorAll('.content-section').forEach(s => s.classList.add('hidden'));
    document.querySelectorAll('.nav-item').forEach(li => li.classList.remove('active'));
    const bpkbSection = document.getElementById('section-pemeriksaan-bpkb');
    const auditNav    = document.querySelector('.nav-item[data-section="audit"]');
    if (bpkbSection) bpkbSection.classList.remove('hidden');
    if (auditNav)    auditNav.classList.add('active');

    setTimeout(() => document.getElementById('bpkbScanInput')?.focus(), 150);
  };

  // ── Kembali ke Audit dari BPKB section ────────────────────────
  window._closeBpkbModal = function() {
    _bpkbTaskId = null; _bpkbPlanId = null;
    const banner = document.getElementById('bpkbPlanBanner');
    if (banner) banner.style.display = 'none';
    document.querySelectorAll('.content-section').forEach(s => s.classList.add('hidden'));
    document.querySelectorAll('.nav-item').forEach(li => li.classList.remove('active'));
    const auditSection = document.getElementById('section-audit');
    const auditNav     = document.querySelector('.nav-item[data-section="audit"]');
    if (auditSection) auditSection.classList.remove('hidden');
    if (auditNav)     auditNav.classList.add('active');
    renderAuditSection();
  };

  // ── Init file import listeners ────────────────────────────────
  function _processBpkbFile(file) {
    if (!file) return;
    if (!file.name.match(/\.(xls|xlsx|csv)$/i)) {
      showToast('Hanya file .xls / .xlsx / .csv yang diterima.', 'error'); return;
    }
    const reader = new FileReader();
    reader.onload = function(e) {
      try {
        const parsed = _parseBpkbExcel(new Uint8Array(e.target.result));
        if (!parsed.length) { showToast('Tidak ada data yang terdeteksi di file ini.', 'error'); return; }
        saveBpkbDb(parsed);
        const msgEl = document.getElementById('bpkbImportMsg');
        if (msgEl) msgEl.innerHTML = `<span style="color:#16a34a">✅ ${parsed.length} data berhasil dimuat dari "${file.name}"</span>`;
        const colInfo = document.getElementById('bpkbColInfo');
        if (colInfo) colInfo.textContent = 'Kolom terdeteksi: NO. | NO. BPKB | NO POLISI | TGL. TERIMA | NAMA PEMILIK | NO. MESIN | NO. RANGKA | JENIS | UMUR';
        _bpkbTab = 'belum'; // langsung tampilkan semua data yang baru diimport
        _bpkbRenderStats();
        _bpkbRenderHasil();
        showToast(`${parsed.length} data BPKB berhasil diimport.`, 'success');
      } catch(err) {
        showToast('Gagal membaca file: ' + err.message, 'error');
      }
    };
    reader.readAsArrayBuffer(file);
  }

  document.getElementById('bpkbFileInput')?.addEventListener('change', function() {
    _processBpkbFile(this.files[0]); this.value = '';
  });
  document.getElementById('bpkbBrowseBtn')?.addEventListener('click', function() {
    document.getElementById('bpkbFileInput')?.click();
  });
  const _bpkbDz = document.getElementById('bpkbDropZone');
  if (_bpkbDz) {
    _bpkbDz.addEventListener('dragover', e => { e.preventDefault(); _bpkbDz.style.background = '#dbeafe'; });
    _bpkbDz.addEventListener('dragleave', () => { _bpkbDz.style.background = '#f0f7ff'; });
    _bpkbDz.addEventListener('drop', e => {
      e.preventDefault(); _bpkbDz.style.background = '#f0f7ff';
      _processBpkbFile(e.dataTransfer.files[0]);
    });
  }
  // bpkbModal overlay sudah dikosongkan — konten dipindah ke section-pemeriksaan-bpkb

  /* ── END MODUL BPKB ONHAND ── */

  /* ============================================================
     MODUL PIUTANG REGULER
     ============================================================ */
  const PIUTANG_REG_KEY = 'akta_piutang_reg';

  function loadPiutangRegAll()  { try { return JSON.parse(localStorage.getItem(PIUTANG_REG_KEY)) || []; } catch { return []; } }
  function savePiutangRegAll(d) { localStorage.setItem(PIUTANG_REG_KEY, JSON.stringify(d)); window.API?.sync(PIUTANG_REG_KEY, d); }
  function getPiutangReg(planId) {
    return loadPiutangRegAll().find(r => String(r.planId) === String(planId)) ||
           { planId: String(planId), rows: [], fileName: '', importedAt: null, auditee: '', batasanTgl: '' };
  }
  function savePiutangReg(data) {
    const all = loadPiutangRegAll();
    const idx = all.findIndex(r => String(r.planId) === String(data.planId));
    if (idx >= 0) all[idx] = data; else all.push(data);
    savePiutangRegAll(all);
  }

  let _piutangRegPlanId = null;
  let _piutangRegTaskId = null;

  // ── Parse Excel Piutang Reguler ──────────────────────────────
  // Mendukung format dengan 2 baris header (main header + sub-header)
  // Contoh: baris 11 = "Customer | No.Fakt/Tgl | Debet | Kredit | Tunggakan"
  //         baris 12 = "          | No.Fakt | Tgl. | Pokok | P.P.N | Lain2 | No.Kwit | Tg | Pembayaran | Saldo Akhir | 1-5 | 6-30 | 31-60 | >60"
  function _parsePiutangRegExcel(data) {
    const wb   = XLSX.read(data, { type: 'array', cellDates: true });
    const ws   = wb.Sheets[wb.SheetNames[0]];
    const rows = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });
    if (!rows.length) return [];

    const toU = v => String(v === null || v === undefined ? '' : v).trim().toUpperCase();

    // ── Cari area header (bisa 1 atau 2 baris header) ────────────
    const KW_ALL = ['CUSTOMER','NAMA','DEBITUR','SALDO','TYPE','FAKTUR','FAK','POKOK','PPN','P.P.N','KWIT','PEMBAYARAN','TUNGGAKAN','TGL'];
    let mainHdrIdx = 0, subHdrIdx = -1;
    for (let i = 0; i < Math.min(25, rows.length); i++) {
      const r = rows[i].map(toU);
      if (KW_ALL.filter(k => r.some(c => c.includes(k))).length >= 2) {
        mainHdrIdx = i;
        // Periksa apakah baris berikutnya juga merupakan sub-header
        if (i + 1 < rows.length) {
          const rn = rows[i+1].map(toU);
          if (KW_ALL.filter(k => rn.some(c => c.includes(k))).length >= 2) {
            subHdrIdx = i + 1;
          }
        }
        break;
      }
    }

    const dataStart = subHdrIdx >= 0 ? subHdrIdx + 1 : mainHdrIdx + 1;
    const mainHdr   = rows[mainHdrIdx].map(toU);
    const subHdr    = subHdrIdx >= 0 ? rows[subHdrIdx].map(toU) : [];

    // Gabungkan: jika sub-header ada isinya, pakai sub-header; jika tidak, pakai main header
    const hdr = mainHdr.map((h, i) => (subHdr[i] && subHdr[i] !== '') ? subHdr[i] : h);

    const findCol = (kws, src) => {
      const k = Array.isArray(kws) ? kws : [kws];
      return (src || hdr).findIndex(h => k.some(kw => h.includes(kw)));
    };

    // ── Customer: prioritaskan main header (sering merged cell) ──
    const iCust = (() => {
      const idx = findCol(['CUSTOMER','NAMA CUSTOMER','NAMA DEBITUR','NAMA','DEBITUR','DEBITOR'], mainHdr);
      return idx >= 0 ? idx : 1; // Default kolom B
    })();

    // ── No.Faktur: cari di sub-header dahulu, lalu gabungan ──────
    let iFaktur = (() => {
      const kws = ['NO.FAKT','NOFAKT','NO FAK','FAKT','FAKTUR','NO.FAK','FAK','INVOICE'];
      const s = findCol(kws, subHdr.length ? subHdr : null);
      return s >= 0 ? s : findCol(kws);
    })();

    // ── Tanggal faktur: kolom TGL. di sub-header setelah No.Fakt ─
    let iTgl = (() => {
      if (subHdr.length) {
        // Cari "TGL." atau "TGL" yang bukan kredit, dan posisinya dekat iFaktur
        const cands = subHdr.map((h,i)=>({h,i})).filter(({h,i}) =>
          (h === 'TGL.' || h === 'TGL' || h === 'TANGGAL') &&
          i !== iFaktur && !h.includes('KR') && !h.includes('KREDIT')
        );
        if (cands.length && iFaktur >= 0) {
          // Pilih yang paling dekat dengan iFaktur
          return cands.reduce((b,c) => Math.abs(c.i-iFaktur) < Math.abs(b.i-iFaktur) ? c : b).i;
        }
        if (cands.length) return cands[0].i;
      }
      // Fallback: jika main header "No.Fakt/Tgl" merged → next column
      if (iFaktur >= 0) {
        const mh = mainHdr[iFaktur];
        if (mh.includes('TGL') || mh.includes('TANGGAL')) return iFaktur + 1;
        // Kolom setelah faktur sering berisi tanggal walau header kosong
        if (iFaktur + 1 < hdr.length && (hdr[iFaktur+1] === '' || hdr[iFaktur+1] === 'TGL' || hdr[iFaktur+1] === 'TGL.')) {
          return iFaktur + 1;
        }
      }
      return -1;
    })();

    const iType      = findCol(['TYPE','TYP','JENIS','PRODUK','TIPE']);
    const iSaldoAwal = findCol(['SALDO AWAL','S.AWAL','OPENING','BLN LALU','OUTSTANDING']);
    const iPokok     = findCol(['POKOK','PRINCIPAL']);
    const iPPN       = findCol(['P.P.N','PPN','TAX','PAJAK']);
    const iLain      = findCol(['LAIN2','LAIN-LAIN','LAINNYA','OTHER','ADM','DENDA','BIAYA']);

    // ── No.Kwit di seksi Kredit ───────────────────────────────────
    const iKwit = findCol(['NO.KWIT','NO KWIT','NKWIT','KWIT','KWITANSI']);

    // ── Tg Kredit: kolom "TG" di bawah seksi Kredit ──────────────
    const iTglKr = (() => {
      const cands = hdr.map((h,i)=>({h,i})).filter(({h,i}) =>
        (h === 'TG' || h === 'TGL' || h === 'TANGGAL') &&
        i !== iTgl && iKwit >= 0 && i > iKwit
      );
      return cands.length ? cands[0].i : -1;
    })();

    let iBayar = findCol(['PEMBAYARAN','BAYAR','PAYMENT']);

    // ── Saldo Akhir ───────────────────────────────────────────────
    let iSaldoAkhir = (() => {
      const idx = findCol(['SALDO AKHIR','SALDOAKHIR','AKHIR','ENDING','CLOSING']);
      if (idx >= 0) return idx;
      const all = hdr.map((h,i)=>({h,i})).filter(({h,i}) => h.includes('SALDO') && i !== iSaldoAwal);
      return all.length ? all[0].i : -1;
    })();

    // ── Kolom aging bucket (langsung dari Excel) ──────────────────
    let iBelumJT = findCol(['BELUM JT','BELUM JAT','BLM JT','LANCAR']);
    let iBkt15   = hdr.findIndex(h => h === '1-5' || h === '1 - 5' || /^1\s*[-–]\s*5$/.test(h));
    let iBkt630  = hdr.findIndex(h => h === '6-30' || h === '6 - 30' || /^6\s*[-–]\s*30$/.test(h));
    let iBkt3160 = hdr.findIndex(h => h === '31-60' || h === '31 - 60' || /^31\s*[-–]\s*60$/.test(h));
    let iBkt60p  = hdr.findIndex(h => h === '>60' || h === '> 60' || /LEBIH\s*60/.test(h) || /60\s*KEATAS/.test(h));
    let iGiro    = (() => { const idx = findCol(['GIRO GANTUNG','GIRO','SPK','GANTUNG']); return idx >= 0 ? idx : -1; })();

    // ── Post-validation: koreksi kolom berdasarkan pola data aktual ──────────
    {
      const scan = rows.slice(dataStart, Math.min(dataStart + 6, rows.length))
                       .filter(r => r && r.some(v => v != null && v !== ''));
      const pNv = v => { if (typeof v === 'number') return v; const n = parseFloat(String(v||'').replace(/[^\d.-]/g,'')); return isNaN(n) ? 0 : n; };

      if (scan.length > 0) {
        // Koreksi 1: jika iFaktur menunjuk kolom Date (tanggal) → swap
        if (iFaktur >= 0 && scan.some(r => r[iFaktur] instanceof Date)) {
          const oldFakt  = iFaktur;
          const fakPat   = /^[A-Z]{1,2}\d{4,}/i;
          let   newFakt  = -1;
          for (const r of scan) {
            for (let c = 0; c < r.length; c++) {
              if (c !== oldFakt && fakPat.test(String(r[c]||'').trim())) { newFakt = c; break; }
            }
            if (newFakt >= 0) break;
          }
          if (newFakt >= 0) { iFaktur = newFakt; iTgl = oldFakt; }
        }

        // Koreksi 2: gunakan iBayar sebagai anchor—posisi setelahnya berurutan
        // Urutan: PEMBAYARAN | SALDO AKHIR | BELUM JT | 1-5 | 6-30 | 31-60 | >60 | GIRO
        if (iBayar >= 0) {
          iSaldoAkhir = iBayar + 1;
          iBelumJT    = iBayar + 2;
          iBkt15      = iBayar + 3;
          iBkt630     = iBayar + 4;
          iBkt3160    = iBayar + 5;
          iBkt60p     = iBayar + 6;
          if (iGiro < iBayar + 7) iGiro = iBayar + 7;
        }

        // Koreksi 3: validasi iSaldoAkhir punya nilai besar seperti saldoAwal
        if (iSaldoAkhir >= 0) {
          const akhirV = scan.map(r => pNv(r[iSaldoAkhir]));
          const awalV  = scan.map(r => pNv(r[iSaldoAwal]));
          if (akhirV.every(v => v === 0) && awalV.some(v => v > 0)) {
            // iSaldoAkhir salah — geser maju sampai menemukan kolom dengan nilai besar
            const ncols = scan[0]?.length || 25;
            let bestC = iSaldoAkhir, bestScore = 0;
            for (let c = iSaldoAkhir; c < Math.min(ncols, iSaldoAkhir + 8); c++) {
              const score = scan.filter((r, i) => { const v = pNv(r[c]); return v > 0 && awalV[i] > 0 && Math.abs(v - awalV[i]) / awalV[i] < 0.6; }).length;
              if (score > bestScore) { bestScore = score; bestC = c; }
            }
            if (bestC !== iSaldoAkhir) {
              const diff = bestC - iSaldoAkhir;
              iSaldoAkhir += diff; iBelumJT += diff;
              iBkt15 += diff; iBkt630 += diff; iBkt3160 += diff; iBkt60p += diff;
              if (iGiro >= 0) iGiro += diff;
            }
          }
        }
      }
    }

    // ── Parser helpers ────────────────────────────────────────────
    const parseNum = v => {
      if (v === '' || v === null || v === undefined) return 0;
      if (typeof v === 'number') return v;
      const n = parseFloat(String(v).replace(/[^\d.-]/g,''));
      return isNaN(n) ? 0 : n;
    };
    const parseTgl = v => {
      if (!v) return '';
      if (v instanceof Date) { try { return v.toISOString().slice(0,10); } catch { return ''; } }
      const s = String(v).trim();
      if (!s || s === '0') return '';
      if (s.match(/^\d{4}-\d{2}-\d{2}/)) return s.slice(0,10);
      if (s.match(/^\d{2}[/-]\d{2}[/-]\d{4}/)) {
        const [d,m,y] = s.split(/[/-]/);
        return `${y}-${m.padStart(2,'0')}-${d.padStart(2,'0')}`;
      }
      // Format DD-MM-YY (contoh: 25-11-25)
      if (s.match(/^\d{2}[/-]\d{2}[/-]\d{2}$/)) {
        const [d,m,y] = s.split(/[/-]/);
        const year = parseInt(y) >= 50 ? '19'+y : '20'+y;
        return `${year}-${m.padStart(2,'0')}-${d.padStart(2,'0')}`;
      }
      return s;
    };
    const getStr = (r, i) => i >= 0 ? String(r[i] ?? '').trim() : '';

    // ── Parse data rows ────────────────────────────────────────────
    const result = [];
    for (let i = dataStart; i < rows.length; i++) {
      const r = rows[i];
      if (!r || !r.length) continue;

      // Customer: gunakan iCust, atau scan kolom di sekitarnya
      let cust = getStr(r, iCust);
      if (!cust) {
        for (let c = 1; c <= Math.min(4, r.length - 1); c++) {
          const v = String(r[c] ?? '').trim();
          if (v && isNaN(Number(v.replace(/[,\.]/g,'')))) { cust = v; break; }
        }
      }
      if (!cust || cust === '0' || /^\d+$/.test(cust)) continue;

      // Tanggal: coba iTgl, fallback ke iFaktur+1
      const tglRaw = iTgl >= 0 ? r[iTgl] : (iFaktur >= 0 ? r[iFaktur + 1] : '');

      // ── Mapping kolom Kredit & Tunggakan (setiap kolom geser 1 ke kanan) ──
      // Urutan nyata: NO.KWIT=iTglKr | TG=iBayar | PEMBAYARAN=iSaldoAkhir |
      //               SALDO AKHIR=iBelumJT | BELUM JT=iBkt15 |
      //               1-5=iBkt630 | 6-30=iBkt3160 | 31-60=iBkt60p | >60=iGiro | GIRO=iGiro+1
      const isValidKwit = v => /^[A-Z]{1,4}\d{4,}/i.test((v||'').trim());

      // NO.KWIT: kolom tepat sebelum PEMBAYARAN (= kolom TG = iBayar-1)
      // Fallback ke iTglKr jika iBayar tidak ditemukan
      const kwitCol  = iBayar >= 0 ? iBayar - 1 : iTglKr;
      const kwitRaw  = kwitCol >= 0 ? getStr(r, kwitCol) : '';
      const kwit     = isValidKwit(kwitRaw) ? kwitRaw.trim() : '';

      // TG kredit: nilai dari kolom PEMBAYARAN (iBayar) = sebelumnya berisi tanggal kredit
      const tglKrRaw = iBayar >= 0 ? r[iBayar] : '';

      // Pembayaran: nilai dari kolom SALDO AKHIR (iSaldoAkhir = iBayar+1)
      const pembayaranVal = iSaldoAkhir >= 0 ? parseNum(r[iSaldoAkhir]) : 0;

      // Saldo Akhir: nilai dari kolom BELUM JT (iBelumJT = iBayar+2)
      const saldoAkhirVal = iBelumJT >= 0 ? parseNum(r[iBelumJT]) : 0;

      // Belum JT: nilai dari kolom 1-5 (iBkt15 = iBayar+3)
      const belumJTVal = iBkt15 >= 0 ? parseNum(r[iBkt15]) : null;

      // Tunggakan 1-5: nilai dari kolom 6-30 (iBkt630 = iBayar+4)
      const bkt15Val = iBkt630 >= 0 ? parseNum(r[iBkt630]) : null;

      // Tunggakan 6-30: nilai dari kolom 31-60 (iBkt3160 = iBayar+5)
      const bkt630Val = iBkt3160 >= 0 ? parseNum(r[iBkt3160]) : null;

      // Tunggakan 31-60: nilai dari kolom >60 (iBkt60p = iBayar+6)
      const bkt3160Val = iBkt60p >= 0 ? parseNum(r[iBkt60p]) : null;

      // Tunggakan >60: nilai dari kolom GIRO (iGiro = iBayar+7)
      const bkt60pVal = iGiro >= 0 ? parseNum(r[iGiro]) : null;

      // Giro Gantung/SPK: kolom setelah iGiro (iBayar+8)
      const giroRawCol = iGiro >= 0 ? iGiro + 1 : -1;
      let giroGantung  = giroRawCol >= 0 ? getStr(r, giroRawCol) : '';

      // Keterangan dari Excel: kolom KETERANGAN atau setelah giro
      const iKet = findCol(['KETERANGAN','KET ','CATATAN']);
      const keterangan = iKet >= 0 ? getStr(r, iKet)
                       : (giroRawCol >= 0 ? getStr(r, giroRawCol + 1) : '');

      result.push({
        customer:        cust,
        noFaktur:        getStr(r, iFaktur),
        tanggal:         parseTgl(tglRaw),
        type:            getStr(r, iType),
        // Tukar: saldoAwal diambil dari kolom Pokok, pokok dari kolom Saldo Awal
        saldoAwal:       iPokok     >= 0 ? parseNum(r[iPokok])     : 0,
        pokok:           iSaldoAwal >= 0 ? parseNum(r[iSaldoAwal]) : 0,
        ppn:             iPPN       >= 0 ? parseNum(r[iPPN])       : 0,
        lain2:           iLain      >= 0 ? parseNum(r[iLain])      : 0,
        noKwit:          kwit,
        tglKredit:       parseTgl(tglKrRaw),
        pembayaran:      pembayaranVal,
        saldoAkhir:      saldoAkhirVal,
        giroGantung,
        keterangan,
        keteranganManual: '',
        _belumJT:        belumJTVal,
        _bkt15:          bkt15Val,
        _bkt630:         bkt630Val,
        _bkt3160:        bkt3160Val,
        _bkt60p:         bkt60pVal,
      });
    }
    return result;
  }

  // ── Migrasi otomatis data lama yang tersimpan dengan mapping kolom salah ──────
  // Deteksi: noKwit kosong TAPI tglKredit berisi nilai pola kwitansi (huruf+angka)
  function _migratePiutangRegRow(r) {
    if (!r) return r;
    const isOldData = !r.noKwit && /^[A-Z]{1,4}\d{4,}/i.test(r.tglKredit || '');
    if (!isOldData) return r;
    const pN = v => { if (typeof v === 'number') return v; const n = parseFloat(String(v||'').replace(/[^\d.-]/g,'')); return isNaN(n) ? 0 : n; };
    return {
      ...r,
      noKwit:    /^[A-Z]{1,4}\d{4,}/i.test(r.tglKredit||'') ? r.tglKredit : '',
      tglKredit: '',
      pembayaran: pN(r.saldoAkhir),
      saldoAkhir: r._belumJT != null ? r._belumJT : pN(r.saldoAkhir),
      _belumJT:   r._bkt15,
      _bkt15:     r._bkt630,
      _bkt630:    r._bkt3160,
      _bkt3160:   r._bkt60p,
      _bkt60p:    r.giroGantung ? (pN(r.giroGantung) || null) : null,
      giroGantung: '',
    };
  }

  // ── Hitung aging bucket (jika tidak ada kolom eksplisit di Excel) ──────────
  function _piutangAgingBucket(row, batasanTgl) {
    // Jika kolom aging sudah ada di Excel, gunakan itu
    if (row._bkt15 !== null) return { belumJT: row._belumJT||0, bkt15: row._bkt15, bkt630: row._bkt630||0, bkt3160: row._bkt3160||0, bkt60p: row._bkt60p||0 };
    const saldo = row.saldoAkhir;
    if (!saldo || saldo <= 0) return { belumJT:0, bkt15:0, bkt630:0, bkt3160:0, bkt60p:0 };
    let days = 999;
    if (row.tanggal && batasanTgl) {
      try { days = Math.floor((new Date(batasanTgl) - new Date(row.tanggal)) / 86400000); } catch {}
    }
    if (days <= 0)        return { belumJT: saldo, bkt15:0, bkt630:0, bkt3160:0, bkt60p:0 };
    if (days <= 5)        return { belumJT:0, bkt15: saldo, bkt630:0, bkt3160:0, bkt60p:0 };
    if (days <= 30)       return { belumJT:0, bkt15:0, bkt630: saldo, bkt3160:0, bkt60p:0 };
    if (days <= 60)       return { belumJT:0, bkt15:0, bkt630:0, bkt3160: saldo, bkt60p:0 };
    return                       { belumJT:0, bkt15:0, bkt630:0, bkt3160:0, bkt60p: saldo };
  }

  // ── Render stats ────────────────────────────────────────────
  function _piutangRegRenderStats(rec) {
    const statEl  = document.getElementById('piutangRegStats');
    const cardsEl = document.getElementById('piutangRegStatCards');
    const dbSt    = document.getElementById('piutangRegDbStatus');
    if (!statEl || !cardsEl) return;
    const rows = rec.rows || [];
    if (!rows.length) { statEl.style.display = 'none'; if (dbSt) dbSt.textContent = ''; return; }

    const batasanTgl = (document.getElementById('piutangReg_batasanTgl')?.value || rec.batasanTgl || '');
    let totBelumJT=0, totBkt15=0, totBkt630=0, totBkt3160=0, totBkt60p=0, totSaldoAkhir=0;
    rows.forEach(r0 => {
      const r = _migratePiutangRegRow(r0);
      const b = _piutangAgingBucket(r, batasanTgl);
      totBelumJT += b.belumJT; totBkt15 += b.bkt15; totBkt630 += b.bkt630;
      totBkt3160 += b.bkt3160; totBkt60p += b.bkt60p; totSaldoAkhir += r.saldoAkhir;
    });

    const fmtJt = n => { if (!n) return 'Rp 0'; const v=Math.abs(n); if(v>=1e9) return `Rp ${(n/1e9).toFixed(1)} M`; if(v>=1e6) return `Rp ${(n/1e6).toFixed(1)} Jt`; return 'Rp '+n.toLocaleString('id-ID'); };
    const card  = (val,lbl,clr='#374151',bg='#f8fafc',bdr='#e5e7eb') =>
      `<div style="background:${bg};border:2px solid ${bdr};border-radius:8px;padding:10px 14px;text-align:center;min-width:100px">
        <div style="font-size:1rem;font-weight:800;color:${clr}">${val}</div>
        <div style="font-size:.66rem;font-weight:700;text-transform:uppercase;color:#6b7280;margin-top:2px;letter-spacing:.04em">${lbl}</div>
      </div>`;

    cardsEl.innerHTML =
      card(rows.length, 'Total Customer') +
      card(fmtJt(totBelumJT), 'Belum Jatuh Tempo', '#15803d','#dcfce7','#86efac') +
      card(fmtJt(totBkt15),   'Tunggakan 1-5',     '#b45309','#fffbeb','#fcd34d') +
      card(fmtJt(totBkt630),  'Tunggakan 6-30',    '#b45309','#fff7ed','#fdba74') +
      card(fmtJt(totBkt3160), 'Tunggakan 31-60',   '#dc2626','#fef2f2','#fca5a5') +
      card(fmtJt(totBkt60p),  'Tunggakan >60',     '#7f1d1d','#fef2f2','#f87171') +
      card(fmtJt(totSaldoAkhir),'Total Saldo Akhir','#1e40af','#eff6ff','#bfdbfe');

    statEl.style.display = '';
    if (dbSt) dbSt.textContent = '● DATABASE AKTIF';
  }

  // ── Render tabel & simpan bar ───────────────────────────────
  function _piutangRegRenderTable(rec) {
    const hasilEl = document.getElementById('piutangRegHasilSection');
    if (!hasilEl) return;
    const rows = rec ? (rec.rows || []) : [];
    if (!rows.length) { hasilEl.innerHTML = ''; return; }

    const planId     = rec.planId;
    const batasanTgl = document.getElementById('piutangReg_batasanTgl')?.value || rec.batasanTgl || '';
    const isSaved    = loadSavedPem().some(s => String(s.planId) === String(planId) && s.type === 'piutang_reg');
    const fmtRp      = n => n ? Number(n).toLocaleString('id-ID') : '-';
    const fmtTgl     = s => {
      if (!s || s === '-') return '-';
      try {
        const d = new Date(s);
        if (isNaN(d.getTime())) return s;
        return `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()}`;
      } catch { return s; }
    };
    const fmtKwit = v => {
      const c = (v||'').trim();
      return /^[A-Z]{1,4}\d{4,}/i.test(c) ? c : '-';
    };

    const hasGiro = rows.some(r => r.giroGantung && r.giroGantung !== '-');
    const hasKet  = rows.some(r => r.keterangan && r.keterangan !== '-');

    const th1 = 'padding:7px 5px;text-align:center;white-space:nowrap;font-size:.75rem;border:1px solid rgba(255,255,255,.2)';
    const th2 = 'padding:5px 5px;text-align:center;white-space:nowrap;font-size:.7rem;border:1px solid rgba(255,255,255,.15)';

    const trs = rows.map((r0,i) => {
      const r       = _migratePiutangRegRow(r0);
      const b       = _piutangAgingBucket(r, batasanTgl);
      const overdue = b.bkt15 || b.bkt630 || b.bkt3160 || b.bkt60p;
      const rowBg   = overdue ? (b.bkt3160||b.bkt60p ? '#fff5f5' : '#fffbeb') : (i%2===0?'#fff':'#f9fafb');
      const fmtN    = n => n ? Number(n).toLocaleString('id-ID') : '0';
      const td      = (v,extra='') => `<td style="padding:4px 5px;border:1px solid #e5e7eb;font-size:.77rem;${extra}">${v}</td>`;
      return `<tr style="background:${rowBg}">
        ${td(i+1,'text-align:center;color:#9ca3af;font-size:.7rem')}
        ${td(`<span style="font-weight:600;color:#1e40af">${r.customer}</span>`,'text-align:left')}
        ${td(r.noFaktur||'-','font-family:monospace;font-size:.73rem')}
        ${td(fmtTgl(r.tanggal),'font-size:.73rem')}
        ${td(r.type||'-','text-align:center;font-weight:600')}
        ${td(fmtRp(r.saldoAwal),'text-align:right')}
        ${td(fmtN(r.pokok),'text-align:right;color:#dc2626')}
        ${td(fmtN(r.ppn),'text-align:right;color:#dc2626')}
        ${td(fmtN(r.lain2),'text-align:right;color:#dc2626')}
        ${td(fmtKwit(r.noKwit),'text-align:left;font-size:.73rem')}
        ${td(fmtTgl(r.tglKredit),'font-size:.73rem')}
        ${td(fmtN(r.pembayaran),'text-align:right;color:#16a34a')}
        ${td(fmtRp(r.saldoAkhir),'text-align:right;font-weight:700;color:'+(r.saldoAkhir>0?'#dc2626':r.saldoAkhir<0?'#dc2626':'#374151'))}
        ${td(fmtN(b.belumJT),'text-align:right;color:#15803d')}
        ${td(fmtN(b.bkt15),'text-align:right;color:'+(b.bkt15>0?'#b45309':'#374151'))}
        ${td(fmtN(b.bkt630),'text-align:right;color:'+(b.bkt630>0?'#b45309':'#374151'))}
        ${td(fmtN(b.bkt3160),'text-align:right;color:'+(b.bkt3160>0?'#dc2626':'#374151'))}
        ${td(fmtN(b.bkt60p),'text-align:right;color:'+(b.bkt60p>0?'#7f1d1d':'#374151'))}
        ${hasGiro ? td(r.giroGantung||'-','font-size:.73rem;max-width:120px;word-break:break-all') : ''}
        ${hasKet  ? td(r.keterangan||'-','font-size:.73rem;max-width:120px') : ''}
        <td style="padding:3px 4px;border:1px solid #e5e7eb;min-width:120px">
          <input type="text"
            value="${(r.keteranganManual||'').replace(/"/g,'&quot;').replace(/</g,'&lt;')}"
            onchange="window._piutangRegSaveKet('${planId}',${i},this.value)"
            style="width:100%;border:1px solid #d1d5db;border-radius:4px;padding:3px 6px;font-size:.72rem;outline:none"
            placeholder="—" />
        </td>
      </tr>`;
    }).join('');

    hasilEl.innerHTML = `
      <div class="pem-card">
        <div class="pem-card-header" style="background:#1e3a5f;color:#fff;border-radius:8px 8px 0 0;padding:10px 16px;display:flex;align-items:center;justify-content:space-between">
          <div style="display:flex;align-items:center;gap:8px;font-size:.85rem;font-weight:700;text-transform:uppercase;letter-spacing:.04em">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2"/><rect x="9" y="3" width="6" height="4" rx="1"/></svg>
            DAFTAR PIUTANG &amp; TUNGGAKAN REGULAR
          </div>
          <span style="font-size:.75rem;font-weight:600;background:rgba(255,255,255,.15);padding:2px 10px;border-radius:10px">${rows.length} CUSTOMER</span>
        </div>
        <div class="pem-card-body" style="border:1px solid #1e3a5f;border-top:none;border-radius:0 0 8px 8px;overflow-x:auto;padding:0">
          <table style="width:100%;border-collapse:collapse;font-size:.8rem;min-width:900px">
            <thead>
              <tr style="background:#1e3a5f;color:#fff">
                <th rowspan="2" style="${th1}">NO</th>
                <th rowspan="2" style="${th1};min-width:140px;text-align:left">CUSTOMER</th>
                <th rowspan="2" style="${th1}">NO. FAKTUR</th>
                <th rowspan="2" style="${th1}">TGL</th>
                <th rowspan="2" style="${th1}">TYPE</th>
                <th rowspan="2" style="${th1}">SALDO AWAL</th>
                <th colspan="3" style="${th1}">D E B E T</th>
                <th colspan="3" style="${th1}">K R E D I T</th>
                <th colspan="2" style="${th1}">BELUM JATUH TEMPO</th>
                <th colspan="4" style="${th1}">T U N G G A K A N</th>
                ${hasGiro ? `<th rowspan="2" style="${th1}">GIRO GANTUNG/ SPK</th>` : ''}
                ${hasKet  ? `<th rowspan="2" style="${th1}">KETERANGAN</th>` : ''}
                <th rowspan="2" style="${th1};min-width:120px;background:#1e4d3a">KETERANGAN<br><span style="font-size:.62rem;font-weight:400;opacity:.8">(Auditor)</span></th>
              </tr>
              <tr style="background:#2d4f80;color:#e0e7ff">
                <th style="${th2}">POKOK</th>
                <th style="${th2}">P.P.N</th>
                <th style="${th2}">LAIN2</th>
                <th style="${th2}">NO.KWIT</th>
                <th style="${th2}">TG</th>
                <th style="${th2}">PEMBAYARAN</th>
                <th style="${th2}">SALDO AKHIR</th>
                <th style="${th2}">BLM JT</th>
                <th style="${th2}">1 - 5</th>
                <th style="${th2}">6 - 30</th>
                <th style="${th2}">31 - 60</th>
                <th style="${th2}">&gt; 60</th>
              </tr>
            </thead>
            <tbody>
              ${trs}
            </tbody>
            <tfoot>
              ${(() => {
                const fmtN2 = n => n ? Number(n).toLocaleString('id-ID') : '0';
                let gSaldoAwal=0, gPokok=0, gPPN=0, gLain=0, gPembayaran=0;
                let gSaldoAkhir=0, gBelumJT=0, gBkt15=0, gBkt630=0, gBkt3160=0, gBkt60p=0;
                rows.forEach(r0 => {
                  const r = _migratePiutangRegRow(r0);
                  const b = _piutangAgingBucket(r, batasanTgl);
                  gSaldoAwal  += r.saldoAwal  || 0;
                  gPokok      += r.pokok      || 0;
                  gPPN        += r.ppn        || 0;
                  gLain       += r.lain2      || 0;
                  gPembayaran += r.pembayaran || 0;
                  gSaldoAkhir += r.saldoAkhir || 0;
                  gBelumJT    += b.belumJT;
                  gBkt15      += b.bkt15;
                  gBkt630     += b.bkt630;
                  gBkt3160    += b.bkt3160;
                  gBkt60p     += b.bkt60p;
                });
                const ftd = (v, extra='') => `<td style="padding:5px 5px;border:1px solid #cbd5e1;font-size:.77rem;font-weight:700;background:#f0f9ff;${extra}">${v}</td>`;
                return `<tr style="background:#f0f9ff">
                  ${ftd('Grand Total','text-align:center;color:#1e3a5f;font-size:.75rem;font-weight:700')}
                  ${ftd('Grand Total','text-align:center;color:#1e3a5f;font-size:.75rem')}
                  ${ftd('-','text-align:center')}
                  ${ftd('-','text-align:center')}
                  ${ftd('-','text-align:center')}
                  ${ftd(fmtN2(gSaldoAwal),'text-align:right;color:#1e3a5f')}
                  ${ftd(fmtN2(gPokok),'text-align:right;color:#dc2626')}
                  ${ftd(fmtN2(gPPN),'text-align:right;color:#dc2626')}
                  ${ftd(fmtN2(gLain),'text-align:right;color:#dc2626')}
                  ${ftd('-','text-align:center')}
                  ${ftd('-','text-align:center')}
                  ${ftd(fmtN2(gPembayaran),'text-align:right;color:#16a34a')}
                  ${ftd(fmtN2(gSaldoAkhir),'text-align:right;color:#1e3a5f')}
                  ${ftd(fmtN2(gBelumJT),'text-align:right;color:#15803d')}
                  ${ftd(fmtN2(gBkt15),'text-align:right;color:#b45309')}
                  ${ftd(fmtN2(gBkt630),'text-align:right;color:#b45309')}
                  ${ftd(fmtN2(gBkt3160),'text-align:right;color:#dc2626')}
                  ${ftd(fmtN2(gBkt60p),'text-align:right;color:#7f1d1d')}
                  ${hasGiro ? ftd('-','text-align:center') : ''}
                  ${hasKet  ? ftd('-','text-align:center') : ''}
                  ${ftd('-','text-align:center')}
                </tr>`;
              })()}
            </tfoot>
          </table>
          <!-- Simpan ke Report Audit -->
          <div style="margin-top:14px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px">
            <span style="font-size:.8rem;color:${isSaved?'#16a34a':'#6b7280'}">
              ${isSaved ? '✅ Sudah disimpan ke Report Audit' : '○ Belum disimpan ke Report Audit'}
            </span>
            <div style="display:flex;gap:8px">
              <button onclick="window._piutangRegPrintPDF('${planId}')"
                      style="background:#1e3a5f;color:#fff;border:none;border-radius:7px;padding:7px 16px;font-size:.82rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:6px">
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                  <polyline points="6 9 6 2 18 2 18 9"/>
                  <path d="M6 18H4a2 2 0 01-2-2v-5a2 2 0 012-2h16a2 2 0 012 2v5a2 2 0 01-2 2h-2"/>
                  <rect x="6" y="14" width="12" height="8"/>
                </svg>
                Cetak PDF
              </button>
              <button onclick="window._simpanPemeriksaan('${planId}','piutang_reg')"
                      style="background:#16a34a;color:#fff;border:none;border-radius:7px;padding:7px 16px;font-size:.82rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:6px">
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                  <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/>
                  <polyline points="17 21 17 13 7 13 7 21"/><polyline points="7 3 7 8 15 8"/>
                </svg>
                Simpan ke Report Audit
              </button>
            </div>
          </div>
        </div>
      </div>`;
  }

  // ── Render all (stats + table) ───────────────────────────────
  window._piutangRegRenderAll = function() {
    if (!_piutangRegPlanId) return;
    const rec = getPiutangReg(_piutangRegPlanId);
    _piutangRegRenderStats(rec);
    _piutangRegRenderTable(rec);
  };

  // ── Simpan keterangan manual per baris ──────────────────────
  window._piutangRegSaveKet = function(planId, rowIdx, val) {
    const rec = getPiutangReg(planId);
    if (rec && rec.rows && rec.rows[rowIdx] !== undefined) {
      rec.rows[rowIdx].keteranganManual = val;
      savePiutangReg(rec);
    }
  };

  // ── Auto-save info fields ────────────────────────────────────
  window._piutangRegAutoSave = function() {
    if (!_piutangRegPlanId) return;
    const rec = getPiutangReg(_piutangRegPlanId);
    rec.auditee    = (document.getElementById('piutangReg_auditee')?.value    || '').trim();
    rec.batasanTgl = (document.getElementById('piutangReg_batasanTgl')?.value || '').trim();
    savePiutangReg(rec);
  };

  // ── Buka section Piutang Reguler ─────────────────────────────
  window._openPiutangReg = function(taskId) {
    tasks = loadTasks();
    const t = tasks.find(x => String(x.id) === String(taskId));
    if (!t) return;
    _piutangRegTaskId = taskId;
    _piutangRegPlanId = t.planId;

    // Plan info card
    const infoEl = document.getElementById('piutangRegPlanInfo');
    if (infoEl) {
      infoEl.innerHTML = `<div class="unit-info-grid">
        <div class="unit-info-item"><label>No SPT</label><span style="font-weight:700">${t.noSPT}</span></div>
        <div class="unit-info-item"><label>Jenis Audit</label><span>${t.jenisAudit}</span></div>
        <div class="unit-info-item"><label>Cabang</label><span>${t.cabangPlan}${t.cabangArea?' '+areaBadge(t.cabangArea):''}</span></div>
        <div class="unit-info-item"><label>Status</label><span>${taskStatusBadge(t.status)}</span></div>
      </div>`;
    }

    // Banner
    const banner    = document.getElementById('piutangRegPlanBanner');
    const bannerCnt = document.getElementById('piutangRegPlanBannerContent');
    if (banner && bannerCnt) {
      bannerCnt.innerHTML =
        '<span><strong>' + (t.noSPT||'—') + '</strong></span>' +
        '<span style="opacity:.6">|</span>' +
        '<span>🏢 ' + (t.cabangPlan||'—') + '</span>' +
        '<span style="opacity:.6">|</span>' +
        '<span>📋 ' + (t.jenisAudit||'—') + '</span>';
      banner.style.display = '';
    }

    // Isi form dari data tersimpan
    const rec = getPiutangReg(t.planId);
    const _s  = (id, val) => { const el = document.getElementById(id); if (el) el.value = val || ''; };
    _s('piutangReg_auditee',    rec.auditee);
    _s('piutangReg_batasanTgl', rec.batasanTgl || new Date().toISOString().slice(0,10));

    // Status import
    const msgEl = document.getElementById('piutangRegImportMsg');
    if (msgEl && rec.rows && rec.rows.length) {
      msgEl.innerHTML = `<span style="color:#16a34a">✅ ${rec.rows.length} customer berhasil dimuat dari "${rec.fileName||'file Excel'}"</span>`;
    } else if (msgEl) {
      msgEl.textContent = '';
    }

    _piutangRegRenderAll();

    // Navigasi ke section
    document.querySelectorAll('.content-section').forEach(s => s.classList.add('hidden'));
    document.querySelectorAll('.nav-item').forEach(li => li.classList.remove('active'));
    const sec    = document.getElementById('section-pemeriksaan-piutang-reg');
    const auditNav = document.querySelector('.nav-item[data-section="audit"]');
    if (sec)      sec.classList.remove('hidden');
    if (auditNav) auditNav.classList.add('active');

  };

  // ── Proses file Excel Piutang Reguler (dipanggil dari event listener) ──────
  function _processPiutangRegFile(file) {
    if (!file) return;
    if (!_piutangRegPlanId) { showToast('Buka dulu menu Piutang Reguler dari task audit.', 'error'); return; }
    const reader = new FileReader();
    reader.onload = e => {
      try {
        const rows = _parsePiutangRegExcel(new Uint8Array(e.target.result));
        if (!rows.length) { showToast('Tidak ada data ditemukan di file Excel. Pastikan format kolom sesuai.', 'error'); return; }
        const rec      = getPiutangReg(_piutangRegPlanId);
        // Pertahankan keteranganManual yang sudah diisi auditor saat re-import
        const prevKets = {};
        (rec.rows || []).forEach(r => { if (r.noFaktur) prevKets[r.noFaktur] = r.keteranganManual || ''; });
        rows.forEach(r => { r.keteranganManual = prevKets[r.noFaktur] || ''; });
        rec.rows       = rows;
        rec.fileName   = file.name;
        rec.importedAt = new Date().toISOString();
        rec.auditee    = (document.getElementById('piutangReg_auditee')?.value    || '').trim();
        rec.batasanTgl = (document.getElementById('piutangReg_batasanTgl')?.value || '').trim();
        savePiutangReg(rec);
        const msgEl = document.getElementById('piutangRegImportMsg');
        if (msgEl) msgEl.innerHTML = `<span style="color:#16a34a">✅ ${rows.length} customer berhasil dimuat dari "${file.name}"</span>`;
        _piutangRegRenderAll();
        showToast(`${rows.length} customer berhasil diimport.`, 'success');
      } catch(err) {
        showToast('Gagal membaca file Excel: ' + err.message, 'error');
        console.error('[PiutangReg] parse error:', err);
      }
    };
    reader.readAsArrayBuffer(file);
  }

  // ── Wiring event listeners (dipanggil sekali saat modul dimuat) ──────────
  document.getElementById('piutangRegFileInput')?.addEventListener('change', function() {
    _processPiutangRegFile(this.files[0]); this.value = '';
  });
  document.getElementById('piutangRegBrowseBtn')?.addEventListener('click', function() {
    document.getElementById('piutangRegFileInput')?.click();
  });
  const _piutangRegDz = document.getElementById('piutangRegDropZone');
  if (_piutangRegDz) {
    _piutangRegDz.addEventListener('dragover',  e => { e.preventDefault(); _piutangRegDz.style.background = '#dcfce7'; });
    _piutangRegDz.addEventListener('dragleave', () => { _piutangRegDz.style.background = '#f0fdf4'; });
    _piutangRegDz.addEventListener('drop', e => {
      e.preventDefault(); _piutangRegDz.style.background = '#f0fdf4';
      _processPiutangRegFile(e.dataTransfer.files[0]);
    });
  }

  // ── PDF Print ─────────────────────────────────────────────────
  window._piutangRegPrintPDF = function(planId) {
    const pid = planId || _piutangRegPlanId;
    if (!pid) return;
    const rec = getPiutangReg(pid);
    const rows = rec.rows || [];
    if (!rows.length) { showToast('Tidak ada data untuk dicetak.', 'error'); return; }

    const task = loadTasks().find(t => String(t.planId) === String(pid));
    const plan = _syncAllPlanStatuses ? _syncAllPlanStatuses().find(p => String(p.id) === String(pid)) : null;
    const batasanTgl = rec.batasanTgl || '';
    const fmtTgl = s => { if(!s) return '-'; try { return new Date(s).toLocaleDateString('id-ID',{day:'2-digit',month:'long',year:'numeric'}); } catch { return s; } };
    const fmtRp  = n => n ? Number(n).toLocaleString('id-ID') : '-';

    let totBelumJT=0,totBkt15=0,totBkt630=0,totBkt3160=0,totBkt60p=0,totSaldo=0;
    let gtSaldoAwal=0,gtPokok=0,gtPPN=0,gtLain=0,gtPembayaran=0;
    rows.forEach(r0=>{
      const r=_migratePiutangRegRow(r0);
      const b=_piutangAgingBucket(r,batasanTgl);
      totBelumJT+=b.belumJT; totBkt15+=b.bkt15; totBkt630+=b.bkt630; totBkt3160+=b.bkt3160; totBkt60p+=b.bkt60p; totSaldo+=r.saldoAkhir;
      gtSaldoAwal+=r.saldoAwal||0; gtPokok+=r.pokok||0; gtPPN+=r.ppn||0; gtLain+=r.lain2||0; gtPembayaran+=r.pembayaran||0;
    });
    const fmtJt = n => { if(!n) return 'Rp 0'; const v=Math.abs(n); if(v>=1e9) return `Rp ${(n/1e9).toFixed(2)} M`; if(v>=1e6) return `Rp ${(n/1e6).toFixed(2)} Jt`; return 'Rp '+n.toLocaleString('id-ID'); };

    const hasGiroPdf = rows.some(r => r.giroGantung && r.giroGantung !== '-');
    const hasKetPdf  = rows.some(r => r.keterangan && r.keterangan !== '-');
    const hasKetManual = rows.some(r => r.keteranganManual && r.keteranganManual.trim());
    const fmtN    = n => n ? Number(n).toLocaleString('id-ID') : '0';
    const fmtTglS = s => {
      if (!s || s === '-') return '-';
      try { const d=new Date(s); if(isNaN(d.getTime())) return s;
        return `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()}`; } catch { return s; }
    };
    const isValidKwitPdf = v => /^[A-Z]{1,4}\d{4,}/i.test((v||'').trim());

    const trs = rows.map((r0,i)=>{
      const r = _migratePiutangRegRow(r0);
      const b = _piutangAgingBucket(r, batasanTgl);
      return `<tr>
        <td style="text-align:center">${i+1}</td>
        <td style="font-weight:600">${r.customer}</td>
        <td style="font-family:monospace">${r.noFaktur||'-'}</td>
        <td>${fmtTglS(r.tanggal)}</td>
        <td style="text-align:center">${r.type||'-'}</td>
        <td style="text-align:right">${fmtRp(r.saldoAwal)}</td>
        <td style="text-align:right">${fmtN(r.pokok)}</td>
        <td style="text-align:right">${fmtN(r.ppn)}</td>
        <td style="text-align:right">${fmtN(r.lain2)}</td>
        <td>${isValidKwitPdf(r.noKwit) ? r.noKwit : '-'}</td>
        <td>${fmtTglS(r.tglKredit)}</td>
        <td style="text-align:right">${fmtN(r.pembayaran)}</td>
        <td style="text-align:right;font-weight:700;color:${r.saldoAkhir>0?'#dc2626':'#000'}">${fmtRp(r.saldoAkhir)}</td>
        <td style="text-align:right;color:#15803d">${fmtN(b.belumJT)}</td>
        <td style="text-align:right;color:${b.bkt15>0?'#b45309':'#000'}">${fmtN(b.bkt15)}</td>
        <td style="text-align:right;color:${b.bkt630>0?'#b45309':'#000'}">${fmtN(b.bkt630)}</td>
        <td style="text-align:right;color:${b.bkt3160>0?'#dc2626':'#000'}">${fmtN(b.bkt3160)}</td>
        <td style="text-align:right;color:${b.bkt60p>0?'#7f1d1d':'#000'}">${fmtN(b.bkt60p)}</td>
        ${hasGiroPdf    ? `<td>${r.giroGantung||'-'}</td>` : ''}
        ${hasKetPdf     ? `<td>${r.keterangan||'-'}</td>`  : ''}
        <td>${r.keteranganManual||'-'}</td>
      </tr>`;
    }).join('');

    const html = `<!DOCTYPE html><html><head><meta charset="UTF-8">
      <title>Piutang Reguler — ${task?.noSPT||pid}</title>
      <style>
        *{margin:0;padding:0;box-sizing:border-box}
        @page{size:A3 landscape;margin:10mm}
        body{font-family:'Segoe UI',Arial,sans-serif;font-size:8px;color:#111;padding:8px}
        .header{text-align:center;margin-bottom:8px}
        .header h2{font-size:12px;text-transform:uppercase;letter-spacing:.05em;color:#1e3a5f}
        .header p{font-size:9px;color:#555}
        .info-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:4px;margin-bottom:8px;border:1px solid #ddd;border-radius:4px;padding:6px}
        .info-item label{font-size:7px;text-transform:uppercase;color:#888;display:block}
        .info-item span{font-weight:700;font-size:9px}
        .stats{display:flex;gap:4px;margin-bottom:8px;flex-wrap:wrap}
        .stat-card{border:1px solid #ddd;border-radius:3px;padding:4px 8px;text-align:center;min-width:80px}
        .stat-card .val{font-size:9px;font-weight:800}
        .stat-card .lbl{font-size:6px;text-transform:uppercase;color:#888;margin-top:1px}
        table{width:100%;border-collapse:collapse}
        th{background:#1e3a5f;color:#fff;padding:4px 3px;text-align:center;font-size:7px;white-space:nowrap;border:1px solid rgba(255,255,255,.2)}
        td{padding:3px;border:1px solid #e5e7eb;font-size:7.5px}
        tr:nth-child(even) td{background:#fafafa}
        .total-row td{font-weight:700;background:#f0f9ff;border-top:2px solid #1e3a5f}
        .sig{display:flex;justify-content:space-around;margin-top:20px}
        .sig-box{text-align:center;min-width:160px}
        .sig-box .role{font-size:8px;color:#555;margin-bottom:36px}
        .sig-box .name{border-top:1px solid #333;padding-top:4px;font-size:8px;font-weight:700}
        @media print{body{padding:0}}
      </style></head><body>
      <div class="header">
        <h2>Laporan Piutang &amp; Tunggakan Reguler</h2>
        <p>${task?.cabangPlan||'—'}${task?.cabangArea?' ('+task.cabangArea+')':''} &nbsp;|&nbsp; ${task?.jenisAudit||'Audit'} &nbsp;|&nbsp; Periode: ${fmtTgl(batasanTgl)}</p>
      </div>
      <div class="info-grid">
        <div class="info-item"><label>No SPT</label><span>${task?.noSPT||'—'}</span></div>
        <div class="info-item"><label>Cabang</label><span>${task?.cabangPlan||'—'}</span></div>
        <div class="info-item"><label>Batasan Tanggal</label><span>${fmtTgl(batasanTgl)}</span></div>
        <div class="info-item"><label>Auditee</label><span>${rec.auditee||'—'}</span></div>
      </div>
      <div class="stats">
        <div class="stat-card"><div class="val">${rows.length}</div><div class="lbl">Total Customer</div></div>
        <div class="stat-card"><div class="val" style="color:#15803d">${fmtJt(totBelumJT)}</div><div class="lbl">Belum Jatuh Tempo</div></div>
        <div class="stat-card"><div class="val" style="color:#b45309">${fmtJt(totBkt15)}</div><div class="lbl">Tunggakan 1-5</div></div>
        <div class="stat-card"><div class="val" style="color:#b45309">${fmtJt(totBkt630)}</div><div class="lbl">Tunggakan 6-30</div></div>
        <div class="stat-card"><div class="val" style="color:#dc2626">${fmtJt(totBkt3160)}</div><div class="lbl">Tunggakan 31-60</div></div>
        <div class="stat-card"><div class="val" style="color:#7f1d1d">${fmtJt(totBkt60p)}</div><div class="lbl">Tunggakan &gt;60</div></div>
        <div class="stat-card"><div class="val" style="color:#1e40af">${fmtJt(totSaldo)}</div><div class="lbl">Total Saldo Akhir</div></div>
      </div>
      <table>
        <thead>
          <tr>
            <th rowspan="2">NO</th>
            <th rowspan="2">CUSTOMER</th>
            <th rowspan="2">NO.FAKTUR</th>
            <th rowspan="2">TGL</th>
            <th rowspan="2">TYPE</th>
            <th rowspan="2" style="text-align:right">SALDO AWAL</th>
            <th colspan="3">D E B E T</th>
            <th colspan="3">K R E D I T</th>
            <th colspan="2">BELUM JATUH TEMPO</th>
            <th colspan="4">T U N G G A K A N</th>
            ${hasGiroPdf    ? '<th rowspan="2">GIRO GANTUNG/SPK</th>' : ''}
            ${hasKetPdf     ? '<th rowspan="2">KETERANGAN</th>'        : ''}
            <th rowspan="2">KETERANGAN (AUDITOR)</th>
          </tr>
          <tr>
            <th style="text-align:right">POKOK</th>
            <th style="text-align:right">P.P.N</th>
            <th style="text-align:right">LAIN2</th>
            <th>NO.KWIT</th>
            <th>TG</th>
            <th style="text-align:right">PEMBAYARAN</th>
            <th style="text-align:right">SALDO AKHIR</th>
            <th style="text-align:right">BLM JT</th>
            <th style="text-align:right">1-5</th>
            <th style="text-align:right">6-30</th>
            <th style="text-align:right">31-60</th>
            <th style="text-align:right">&gt;60</th>
          </tr>
        </thead>
        <tbody>${trs}</tbody>
        <tfoot>
          <tr class="total-row">
            <td colspan="5" style="text-align:center;font-weight:700;color:#1e3a5f">Grand Total</td>
            <td style="text-align:right">${fmtN(gtSaldoAwal)}</td>
            <td style="text-align:right;color:#dc2626">${fmtN(gtPokok)}</td>
            <td style="text-align:right;color:#dc2626">${fmtN(gtPPN)}</td>
            <td style="text-align:right;color:#dc2626">${fmtN(gtLain)}</td>
            <td style="text-align:center">-</td>
            <td style="text-align:center">-</td>
            <td style="text-align:right;color:#16a34a">${fmtN(gtPembayaran)}</td>
            <td style="text-align:right;font-weight:700">${fmtRp(totSaldo)}</td>
            <td style="text-align:right;color:#15803d;font-weight:700">${fmtN(totBelumJT)}</td>
            <td style="text-align:right;color:#b45309;font-weight:700">${fmtN(totBkt15)}</td>
            <td style="text-align:right;color:#b45309;font-weight:700">${fmtN(totBkt630)}</td>
            <td style="text-align:right;color:#dc2626;font-weight:700">${fmtN(totBkt3160)}</td>
            <td style="text-align:right;color:#7f1d1d;font-weight:700">${fmtN(totBkt60p)}</td>
            ${hasGiroPdf ? '<td style="text-align:center">-</td>' : ''}
            ${hasKetPdf  ? '<td style="text-align:center">-</td>'  : ''}
            <td style="text-align:center">-</td>
          </tr>
        </tfoot>
      </table>
      <div class="sig">
        <div class="sig-box">
          <div class="role">Auditor</div>
          <div class="name">${session.displayName||'................................'}</div>
        </div>
        <div class="sig-box">
          <div class="role">Auditee / Penanggung Jawab</div>
          <div class="name">${rec.auditee||'................................'}</div>
        </div>
      </div>
      <script>window.onload=function(){window.print();}</script>
      </body></html>`;

    const w = window.open('about:blank');
    if (w) w.document.write(html);
  };

  /* ── END MODUL PIUTANG REGULER ── */

  /* ============================================================
     MODUL TUNGGAKAN KDS
     Struktur kolom Excel:
       No | Kontrak (Nomor + Tanggal) | Nama Customer | Saldo Piutang
       | Belum Jatuh Tempo | Tunggakan (1-5, 6-30, 31-60, >60)
       | Analisa ketidak-aktifan (0bln, 1bln, 2bln, 3bln, 4bln, >5bln) <<ribuan>>
       | Keterangan
     ============================================================ */
  const TUNGGAKAN_KDS_KEY = 'akta_tunggakan_kds';
  let _kdsTaskId = null;
  let _kdsPlanId = null;

  // Label tetap untuk 6 kolom analisa
  const KDS_ANALISA_HDRS = ['0 bln', '1 bln', '2 bln', '3 bln', '4 bln', '> 5 bln'];

  function loadKdsAll()  { try { return JSON.parse(localStorage.getItem(TUNGGAKAN_KDS_KEY)) || []; } catch { return []; } }
  function saveKdsAll(d) { localStorage.setItem(TUNGGAKAN_KDS_KEY, JSON.stringify(d)); window.API?.sync(TUNGGAKAN_KDS_KEY, d); }

  function getKds(planId) {
    return loadKdsAll().find(r => String(r.planId) === String(planId)) ||
           { planId: String(planId), rows: [], fileName: '', importedAt: null, auditee: '', tglPemeriksaan: '' };
  }
  function saveKds(data) {
    const all = loadKdsAll();
    const idx = all.findIndex(r => String(r.planId) === String(data.planId));
    if (idx >= 0) all[idx] = data; else all.push(data);
    saveKdsAll(all);
  }

  // ── Auto-save field perubahan ─────────────────────────────────
  window._kdsAutoSave = function() {
    if (!_kdsPlanId) return;
    const rec = getKds(_kdsPlanId);
    rec.auditee        = (document.getElementById('kds_auditee')?.value || '').trim();
    rec.tglPemeriksaan = (document.getElementById('kds_tglPemeriksaan')?.value || '').trim();
    saveKds(rec);
  };

  // ── Parse Excel Tunggakan KDS ─────────────────────────────────
  // Format Excel (2-baris header):
  //   Baris 1 (main): No | Kontrak(merged) | | Nama Customer | Saldo Piutang | Belum Jatuh Tempo | Tunggakan(merged) | | | | Analisa(merged) | | | | | | Keterangan
  //   Baris 2 (sub) :    | Nomor | Tangg   |                |               |                   | 1-5 | 6-30 | 31-60 | >60 | 0bln | 1bln | 2 | 3 | 4 | >5 |
  function _parseKdsExcel(data) {
    const wb   = XLSX.read(data, { type: 'array', cellDates: true });
    const ws   = wb.Sheets[wb.SheetNames[0]];
    const rows = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });
    if (!rows.length) return { rows: [] };

    const toU = v => String(v === null || v === undefined ? '' : v).trim().toUpperCase();
    const toN = v => { if (typeof v === 'number') return v; const n = parseFloat(String(v||'').replace(/[^\d.,-]/g,'').replace(',','.')); return isNaN(n) ? 0 : n; };
    const toD = v => {
      if (!v) return '';
      if (v instanceof Date) return `${String(v.getDate()).padStart(2,'0')}-${String(v.getMonth()+1).padStart(2,'0')}-${String(v.getFullYear()).slice(2)}`;
      return String(v).trim();
    };

    // Normalisasi: hapus spasi, seragamkan tanda hubung — untuk perbandingan header yang fleksibel
    const normH = v => String(v === null || v === undefined ? '' : v).trim().toUpperCase().replace(/\s+/g,'').replace(/[–—]/g,'-');

    const KW_MAIN = ['KONTRAK','CUSTOMER','DEBITUR','NAMA','SALDO','TUNGGAKAN','JATUH'];
    // Normalisasi KW_SUB sehingga "1 - 5" → "1-5", "> 60" → ">60", "0 BLN" → "0BLN"
    const KW_SUB_NORM = ['NOMOR','TANGG','TGL','1-5','6-30','31-60','>60','BLN'];
    let mainIdx = -1, subIdx = -1;

    for (let i = 0; i < Math.min(25, rows.length); i++) {
      const r = rows[i].map(toU);
      const hasKontrak = r.some(c => c.includes('KONTRAK'));
      const matchMain  = KW_MAIN.filter(k => r.some(c => c.includes(k))).length;
      if (hasKontrak && matchMain >= 3 && mainIdx < 0) {
        mainIdx = i;
        // Cari sub-header dalam 3 baris setelah main header (fleksibel terhadap baris kosong)
        for (let j = i + 1; j <= Math.min(i + 3, rows.length - 1); j++) {
          const nxtNorm = rows[j].map(normH);
          const matchSub = KW_SUB_NORM.filter(k => nxtNorm.some(c => c.includes(k))).length;
          if (matchSub >= 2) { subIdx = j; break; }
        }
        break;
      }
    }

    // Fallback: tidak ada main header → cari baris sub-header langsung (normalisasi)
    if (mainIdx < 0) {
      for (let i = 0; i < Math.min(25, rows.length); i++) {
        const rNorm = rows[i].map(normH);
        const hasNomor = rNorm.some(h => h === 'NOMOR' || h === 'NOKONTRAK' || h === 'NOMORKONTRAK' || h === 'NO.KTR');
        const has1_5   = rNorm.some(h => h === '1-5' || h.includes('1-5'));
        if (hasNomor && has1_5) { subIdx = i; mainIdx = i; break; }
      }
    }

    if (mainIdx < 0 && subIdx < 0) return { rows: [] };

    const useIdx    = subIdx  >= 0 ? subIdx  : mainIdx;
    const mainHdr   = rows[mainIdx >= 0 ? mainIdx : useIdx].map(toU);
    const subHdr    = rows[useIdx].map(toU);
    const dataStart = useIdx + 1;

    // Gabungkan: sub-header diutamakan, fallback ke main header
    const hdr = subHdr.map((h, i) => h || (mainHdr[i] || ''));

    // hdrNorm: normalisasi penuh (hapus spasi, seragamkan tanda hubung) untuk pencarian kolom
    const hdrNorm = hdr.map(normH);

    // fi: cari index kolom di hdrNorm menggunakan keyword ternormalisasi
    const fi = kws => {
      const list = (Array.isArray(kws) ? kws : [kws]).map(k => normH(k));
      return hdrNorm.findIndex(h => list.some(k => h.includes(k)));
    };

    // Kontrak → sub-kolom "Nomor" / "Nomor Faktur" / "Nomor Kontrak"
    // ── Deteksi nomor urut: cek apakah kolom berisi sequential integer (1,2,3…) ──
    const _isNoUrut = colIdx => {
      if (colIdx < 0 || colIdx >= (rows[dataStart]||[]).length) return false;
      const v1 = rows[dataStart]?.[colIdx];
      const v2 = rows[dataStart + 1]?.[colIdx];
      // Sequential integer kecil → kolom No. urut, bukan Nomor Kontrak
      return (typeof v1 === 'number' && v1 >= 1 && v1 <= 9999 &&
              typeof v2 === 'number' && v2 === v1 + 1);
    };
    const iNomor = (() => {
      // Kumpulkan semua kandidat (exact match dahulu, lalu partial)
      const cands = [];
      hdrNorm.forEach((h, i) => {
        if (h === 'NO' || h === 'NO.' || h === 'NOMOR.') return; // skip kolom No. urut
        if (h === 'NOMOR' || h === 'NOMORFAKTUR' || h === 'NO.FAKTUR' || h === 'NOFAKTUR' ||
            h === 'NOKONTRAK' || h === 'NOMORKONTRAK' || h === 'NO.KTR' || h === 'NOFAKTURPENJUALAN')
          cands.push({ i, exact: true });
        else if (h.includes('NOMOR') || h.includes('FAKTUR'))
          cands.push({ i, exact: false });
      });
      // Urutkan: exact dulu, lalu berdasarkan posisi
      cands.sort((a, b) => (b.exact - a.exact) || (a.i - b.i));
      // Pilih kandidat pertama yang BUKAN kolom No. urut sequential
      for (const { i } of cands) {
        if (!_isNoUrut(i)) return i;
      }
      // Fallback: kembalikan kandidat pertama meski sequential (daripada -1)
      return cands[0]?.i ?? -1;
    })();

    const iTgl = (() => {
      const cands = hdrNorm.map((h,i) => ({h,i})).filter(({h,i}) =>
        (h.includes('TANGG') || h === 'TGL' || h === 'DATE') && i !== iNomor
      );
      if (!cands.length) return -1;
      // Pilih yang paling dekat dengan iNomor (kolom tanggal biasanya di sebelah kanan nomor)
      return iNomor >= 0
        ? cands.reduce((b,c) => Math.abs(c.i - iNomor) < Math.abs(b.i - iNomor) ? c : b).i
        : cands[0].i;
    })();

    const iNama    = fi(['NAMACUSTOMER','NAMADEBITUR','NAMADEB','NAMAPELANGGAN','NAMA','CUSTOMER','DEBITUR','PELANGGAN']);
    const iSaldo   = fi(['SALDOPIUTANG','SALDOPINJAMAN','SALDO','OUTSTANDING','BAKIDEBET']);
    const iBelumJT = fi(['BELUMJATUHTEMPO','BELUMJATUH','BELUMJT','BLMJT','LANCAR']);
    const iTgg1_5  = hdrNorm.findIndex(h => /^1-5$/.test(h) || /^1\s*[-–]\s*5$/.test(h));
    const iTgg6_30 = hdrNorm.findIndex(h => /^6-30$/.test(h) || /^6\s*[-–]\s*30$/.test(h));
    const iTgg31_60= hdrNorm.findIndex(h => /^31-60$/.test(h) || /^31\s*[-–]\s*60$/.test(h));
    const iTggGt60 = hdrNorm.findIndex(h => h === '>60' || h === '&GT;60' || /LEBIH60/.test(h) || (h.includes('>') && h.includes('60')));

    // 6 kolom analisa tetap — dimulai tepat setelah >60
    const afterGt60 = iTggGt60 >= 0 ? iTggGt60 + 1
                    : iTgg31_60 >= 0 ? iTgg31_60 + 2
                    : iTgg6_30  >= 0 ? iTgg6_30  + 3
                    : hdr.length - 7;
    const analisaIdxs = [];
    for (let i = afterGt60; analisaIdxs.length < 6 && i < hdr.length; i++) analisaIdxs.push(i);

    // Keterangan: kolom setelah analisa terakhir, atau yang mengandung "KET"/"REMARK"
    const iKet = (() => {
      const k = hdrNorm.map((h,i) => ({h,i})).reverse().find(({h}) => h.includes('KET') || h.includes('REMARK'));
      if (k) return k.i;
      const lastAna = analisaIdxs.length ? analisaIdxs[analisaIdxs.length-1] : -1;
      if (lastAna >= 0 && lastAna+1 < hdr.length) return lastAna+1;
      return hdr.length - 1;
    })();

    // ── DEBUG LOG (buka F12 → Console setelah import) ────────────
    console.group('[KDS DEBUG]');
    console.log('mainIdx:', mainIdx, '| subIdx:', subIdx, '| dataStart:', dataStart);
    console.log('hdrNorm:', JSON.stringify(hdrNorm));
    console.log('iNomor:', iNomor, '| iTgl:', iTgl, '| iNama:', iNama, '| iSaldo:', iSaldo, '| iBelumJT:', iBelumJT);
    console.log('iTgg1_5:', iTgg1_5, '| iTgg6_30:', iTgg6_30, '| iTgg31_60:', iTgg31_60, '| iTggGt60:', iTggGt60);
    console.log('analisaIdxs:', JSON.stringify(analisaIdxs), '| iKet:', iKet);
    if (rows[dataStart]) console.log('row[dataStart]:', JSON.stringify(rows[dataStart]));
    console.groupEnd();
    // ── END DEBUG ─────────────────────────────────────────────────

    const result = [];
    for (let i = dataStart; i < rows.length; i++) {
      const r = rows[i];
      if (!r || r.every(v => v === '' || v === null || v === undefined)) continue;
      const nomor = iNomor >= 0 ? String(r[iNomor]||'').trim() : '';
      const nama  = iNama  >= 0 ? String(r[iNama] ||'').trim() : '';
      if (!nomor && !nama) continue;

      // Skip baris total/grand total (termasuk "GrandTotal" tanpa spasi)
      const allStr     = rows[i].map(toU).join(' ');
      const allStrNorm = allStr.replace(/\s+/g,'');
      if (allStrNorm.includes('GRANDTOTAL') || allStr.includes('GRAND TOTAL') || allStr.includes('TOTAL KESELURUHAN')) continue;
      const firstStr = toU(r[0]||'');
      if ((firstStr.includes('GRAND') || firstStr.includes('TOTAL') || firstStr.includes('JUMLAH')) && !nomor) continue;

      // Skip baris header yang lolos (nilai di kolom nomor adalah label header)
      const nomorNorm = nomor.toUpperCase().replace(/\s+/g,'');
      if (nomorNorm === 'NOMOR' || nomorNorm === 'NOMORFAKTUR' || nomorNorm === 'NOFAKTUR' ||
          nomorNorm === 'NOKONTRAK' || nomorNorm === 'NOMORKONTRAK' || nomorNorm === 'NO.') continue;

      // Skip baris sub-header yang lolos (nilai di kolom nama adalah label kolom)
      const namaUp = nama.toUpperCase().replace(/\s+/g,'');
      if (namaUp === 'TANGGAL' || namaUp === 'TGL' || namaUp === 'TANGG' || namaUp === 'DATE' ||
          namaUp === 'NAMACUSTOMER' || namaUp === 'NAMADEBITUR' || namaUp === 'NAMAPELANGGAN' ||
          namaUp === 'CUSTOMER' || namaUp === 'DEBITUR' || namaUp === 'PELANGGAN') continue;

      result.push({
        noKontrak:    nomor,
        tanggal:      iTgl      >= 0 ? toD(r[iTgl])                   : '',
        namaCustomer: nama,
        saldo:        iSaldo    >= 0 ? toN(r[iSaldo])                 : 0,
        belumJT:      iBelumJT  >= 0 ? toN(r[iBelumJT])              : 0,
        tgg1_5:       iTgg1_5   >= 0 ? toN(r[iTgg1_5])               : 0,
        tgg6_30:      iTgg6_30  >= 0 ? toN(r[iTgg6_30])              : 0,
        tgg31_60:     iTgg31_60 >= 0 ? toN(r[iTgg31_60])             : 0,
        tggGt60:      iTggGt60  >= 0 ? toN(r[iTggGt60])              : 0,
        // 6 kolom analisa tetap (dalam ribuan sesuai format Excel)
        a0bln:  analisaIdxs[0] !== undefined ? toN(r[analisaIdxs[0]]) : 0,
        a1bln:  analisaIdxs[1] !== undefined ? toN(r[analisaIdxs[1]]) : 0,
        a2:     analisaIdxs[2] !== undefined ? toN(r[analisaIdxs[2]]) : 0,
        a3:     analisaIdxs[3] !== undefined ? toN(r[analisaIdxs[3]]) : 0,
        a4:     analisaIdxs[4] !== undefined ? toN(r[analisaIdxs[4]]) : 0,
        aGt5:   analisaIdxs[5] !== undefined ? toN(r[analisaIdxs[5]]) : 0,
        keterangan: iKet >= 0 ? String(r[iKet]||'').trim() : '',
      });
    }
    return { rows: result };
  }

  // ── Render tabel hasil KDS ────────────────────────────────────
  function _kdsRenderTable(rec) {
    const hasilEl = document.getElementById('kdsHasilSection');
    if (!hasilEl) return;
    const rows    = rec.rows || [];
    const isSaved = loadSavedPem().some(s => String(s.planId) === String(_kdsPlanId) && s.type === 'tunggakan_kds');
    if (!rows.length) { hasilEl.innerHTML = ''; return; }

    const fN  = n => n ? Number(n).toLocaleString('id-ID') : '-';
    const fN0 = n => Number(n||0).toLocaleString('id-ID');
    const TH1 = 'padding:6px 4px;background:#92400e;color:#fff;font-size:.72rem;white-space:nowrap;border:1px solid rgba(255,255,255,.2);text-align:center';
    const TH2 = 'padding:5px 4px;background:#b45309;color:#fff;font-size:.7rem;white-space:nowrap;border:1px solid rgba(255,255,255,.15);text-align:center';
    const TH3 = 'padding:5px 4px;background:#1e3a5f;color:#e0e7ff;font-size:.7rem;white-space:nowrap;border:1px solid rgba(255,255,255,.15);text-align:center';
    const td  = (v, e='') => `<td style="padding:4px 5px;border:1px solid #e5e7eb;font-size:.76rem;${e}">${v}</td>`;
    const ftd = (v, e='') => `<td style="padding:5px;border:1px solid #cbd5e1;font-size:.76rem;font-weight:700;background:#fff7ed;${e}">${v}</td>`;

    let gSaldo=0, gBelumJT=0, gT1_5=0, gT6_30=0, gT31_60=0, gTGt60=0;
    let gA0=0, gA1=0, gA2=0, gA3=0, gA4=0, gA5=0;
    rows.forEach(r => {
      gSaldo+=r.saldo||0; gBelumJT+=r.belumJT||0;
      gT1_5+=r.tgg1_5||0; gT6_30+=r.tgg6_30||0; gT31_60+=r.tgg31_60||0; gTGt60+=r.tggGt60||0;
      gA0+=r.a0bln||0; gA1+=r.a1bln||0; gA2+=r.a2||0; gA3+=r.a3||0; gA4+=r.a4||0; gA5+=r.aGt5||0;
    });

    const trs = rows.map((r, i) => `<tr style="background:${i%2===0?'#fff':'#fafafa'}">
      ${td(i+1,'text-align:center;color:#9ca3af;font-size:.7rem')}
      ${td(r.noKontrak||'-','font-family:monospace;font-size:.73rem;white-space:nowrap')}
      ${td(r.tanggal||'-','font-size:.72rem;white-space:nowrap;text-align:center')}
      ${td(`<span style="font-weight:600;color:#92400e">${r.namaCustomer||'-'}</span>`)}
      ${td(fN(r.saldo),'text-align:right')}
      ${td(fN(r.belumJT),'text-align:right;color:#15803d')}
      ${td(r.tgg1_5>0?fN(r.tgg1_5):'-','text-align:right;color:'+(r.tgg1_5>0?'#b45309':'#9ca3af'))}
      ${td(r.tgg6_30>0?fN(r.tgg6_30):'-','text-align:right;color:'+(r.tgg6_30>0?'#b45309':'#9ca3af'))}
      ${td(r.tgg31_60>0?fN(r.tgg31_60):'-','text-align:right;color:'+(r.tgg31_60>0?'#dc2626':'#9ca3af'))}
      ${td(r.tggGt60>0?fN(r.tggGt60):'-','text-align:right;color:'+(r.tggGt60>0?'#7f1d1d':'#9ca3af'))}
      ${td(r.a0bln?fN(r.a0bln):'-','text-align:right')}
      ${td(r.a1bln?fN(r.a1bln):'-','text-align:right')}
      ${td(r.a2?fN(r.a2):'-','text-align:right')}
      ${td(r.a3?fN(r.a3):'-','text-align:right')}
      ${td(r.a4?fN(r.a4):'-','text-align:right')}
      ${td(r.aGt5?fN(r.aGt5):'-','text-align:right')}
      <td style="padding:3px 4px;border:1px solid #e5e7eb;min-width:130px;max-width:220px">
        <input type="text" value="${(r.keterangan||'').replace(/"/g,'&quot;')}"
          placeholder="Tulis keterangan…"
          oninput="window._kdsKetSave(${i},this.value)"
          style="width:100%;border:none;background:transparent;font-size:.74rem;color:#374151;
                 outline:none;padding:2px 4px;border-radius:4px;transition:background .15s"
          onfocus="this.style.background='#fef9c3';this.style.outline='none'"
          onblur="this.style.background='transparent'">
      </td>
    </tr>`).join('');

    hasilEl.innerHTML = `
      <div class="pem-card">
        <div class="pem-card-header" style="background:#92400e;color:#fff;border-radius:8px 8px 0 0;padding:10px 16px;display:flex;align-items:center;justify-content:space-between">
          <div style="display:flex;align-items:center;gap:8px;font-size:.85rem;font-weight:700;text-transform:uppercase;letter-spacing:.04em">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2"/><rect x="9" y="3" width="6" height="4" rx="1"/></svg>
            DAFTAR TUNGGAKAN KDS
          </div>
          <span style="font-size:.75rem;font-weight:600;background:rgba(255,255,255,.15);padding:2px 10px;border-radius:10px">${rows.length} DATA</span>
        </div>
        <div class="pem-card-body" style="border:1px solid #92400e;border-top:none;border-radius:0 0 8px 8px;overflow-x:auto;padding:0">
          <table style="width:100%;border-collapse:collapse;min-width:900px">
            <thead>
              <tr>
                <th rowspan="2" style="${TH1}">NO.</th>
                <th colspan="2" style="${TH1}">KONTRAK</th>
                <th rowspan="2" style="${TH1}">NAMA CUSTOMER</th>
                <th rowspan="2" style="${TH1}">SALDO PIUTANG</th>
                <th rowspan="2" style="${TH1}">BELUM JATUH TEMPO</th>
                <th colspan="4" style="${TH2}">T U N G G A K A N</th>
                <th colspan="6" style="${TH3}">ANALISA KETIDAK-AKTIFAN DEB. 00-61 HR KEATAS<br><span style="font-size:.62rem;font-weight:400;opacity:.8">&lt;&lt; nilai dalam ribuan &gt;&gt;</span></th>
                <th rowspan="2" style="${TH1}">KETERANGAN</th>
              </tr>
              <tr>
                <th style="${TH1}">Nomor</th>
                <th style="${TH1}">Tanggal</th>
                <th style="${TH2}">1 - 5</th>
                <th style="${TH2}">6 - 30</th>
                <th style="${TH2}">31 - 60</th>
                <th style="${TH2}">&gt; 60</th>
                ${KDS_ANALISA_HDRS.map(h => `<th style="${TH3}">${h}</th>`).join('')}
              </tr>
            </thead>
            <tbody>${trs}</tbody>
            <tfoot>
              <tr>
                ${ftd('Grand Total','text-align:center;color:#92400e;font-size:.74rem')}
                ${ftd('Grand Total','text-align:center;color:#92400e;font-size:.74rem')}
                ${ftd('-','text-align:center')}
                ${ftd('-','text-align:center')}
                ${ftd(fN0(gSaldo),'text-align:right;color:#92400e')}
                ${ftd(fN0(gBelumJT),'text-align:right;color:#15803d')}
                ${ftd(fN0(gT1_5),'text-align:right;color:#b45309')}
                ${ftd(fN0(gT6_30),'text-align:right;color:#b45309')}
                ${ftd(fN0(gT31_60),'text-align:right;color:#dc2626')}
                ${ftd(fN0(gTGt60),'text-align:right;color:#7f1d1d')}
                ${ftd(fN0(gA0),'text-align:right')}
                ${ftd(fN0(gA1),'text-align:right')}
                ${ftd(fN0(gA2),'text-align:right')}
                ${ftd(fN0(gA3),'text-align:right')}
                ${ftd(fN0(gA4),'text-align:right')}
                ${ftd(fN0(gA5),'text-align:right')}
                ${ftd('-','text-align:center')}
              </tr>
            </tfoot>
          </table>
        </div>
      </div>
      <!-- Simpan ke Report Audit -->
      <div style="margin-top:14px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px">
        <span style="font-size:.8rem;color:${isSaved?'#16a34a':'#6b7280'}">
          ${isSaved ? '✅ Sudah disimpan ke Report Audit' : '○ Belum disimpan ke Report Audit'}
        </span>
        <div style="display:flex;gap:8px">
          <button onclick="window._kdsPrintPDF('${_kdsPlanId}')"
                  style="background:#92400e;color:#fff;border:none;border-radius:7px;padding:7px 16px;font-size:.82rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:6px">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <polyline points="6 9 6 2 18 2 18 9"/>
              <path d="M6 18H4a2 2 0 01-2-2v-5a2 2 0 012-2h16a2 2 0 012 2v5a2 2 0 01-2 2h-2"/>
              <rect x="6" y="14" width="12" height="8"/>
            </svg>
            Cetak PDF
          </button>
          <button onclick="window._simpanPemeriksaan('${_kdsPlanId}','tunggakan_kds')"
                  style="background:#16a34a;color:#fff;border:none;border-radius:7px;padding:7px 16px;font-size:.82rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:6px">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/>
              <polyline points="17 21 17 13 7 13 7 21"/><polyline points="7 3 7 8 15 8"/>
            </svg>
            Simpan ke Report Audit
          </button>
        </div>
      </div>`;
  }

  // ── Render stats cards ────────────────────────────────────────
  function _kdsRenderStats(rec) {
    const rows    = rec.rows || [];
    const statsEl = document.getElementById('kdsStats');
    const cardsEl = document.getElementById('kdsStatCards');
    const dbSt    = document.getElementById('kdsDbStatus');
    if (!statsEl || !cardsEl) return;
    if (!rows.length) { statsEl.style.display = 'none'; if (dbSt) dbSt.textContent = ''; return; }

    const fJt = n => { if (!n) return 'Rp 0'; const v=Math.abs(n); if(v>=1e9) return `Rp ${(n/1e9).toFixed(2)} M`; if(v>=1e6) return `Rp ${(n/1e6).toFixed(1)} Jt`; return 'Rp '+n.toLocaleString('id-ID'); };
    let gSaldo=0, gBelumJT=0, gT1_5=0, gT6_30=0, gT31_60=0, gTGt60=0;
    rows.forEach(r => { gSaldo+=r.saldo||0; gBelumJT+=r.belumJT||0; gT1_5+=r.tgg1_5||0; gT6_30+=r.tgg6_30||0; gT31_60+=r.tgg31_60||0; gTGt60+=r.tggGt60||0; });
    const card = (val, lbl, clr='#374151', bg='#fff', bdr='#e5e7eb') =>
      `<div style="background:${bg};border:2px solid ${bdr};border-radius:8px;padding:10px 14px;text-align:center;min-width:90px">
        <div style="font-size:1rem;font-weight:800;color:${clr}">${val}</div>
        <div style="font-size:.65rem;font-weight:700;text-transform:uppercase;color:#6b7280;margin-top:2px">${lbl}</div>
      </div>`;
    cardsEl.innerHTML =
      card(rows.length, 'Total Customer') +
      card(fJt(gSaldo),   'Total Saldo',         '#92400e','#fff7ed','#fcd34d') +
      card(fJt(gBelumJT), 'Belum Jatuh Tempo',   '#15803d','#f0fdf4','#86efac') +
      card(fJt(gT1_5),    'Tunggakan 1–5',        '#b45309','#fffbeb','#fcd34d') +
      card(fJt(gT6_30),   'Tunggakan 6–30',       '#b45309','#fff7ed','#fdba74') +
      card(fJt(gT31_60),  'Tunggakan 31–60',      '#dc2626','#fef2f2','#fca5a5') +
      card(fJt(gTGt60),   'Tunggakan &gt;60',     '#7f1d1d','#fef2f2','#f87171');
    statsEl.style.display = '';
    if (dbSt) dbSt.textContent = '● DATABASE AKTIF';
  }

  window._kdsRenderAll = function() {
    if (!_kdsPlanId) return;
    const rec = getKds(_kdsPlanId);
    _kdsRenderStats(rec);
    _kdsRenderTable(rec);
  };

  // ── Simpan keterangan manual per baris ───────────────────────
  window._kdsKetSave = function(rowIdx, value) {
    if (!_kdsPlanId) return;
    const rec = getKds(_kdsPlanId);
    if (!rec.rows || rowIdx < 0 || rowIdx >= rec.rows.length) return;
    rec.rows[rowIdx].keterangan = value.trim();
    saveKds(rec);
  };

  // ── Buka section Tunggakan KDS ────────────────────────────────
  window._openTunggakanKds = function(taskId) {
    tasks = loadTasks();
    const t = tasks.find(x => String(x.id) === String(taskId));
    if (!t) return;
    _kdsTaskId = taskId;
    _kdsPlanId = t.planId;

    const infoEl = document.getElementById('kdsPlanInfo');
    if (infoEl) {
      infoEl.innerHTML = `<div class="unit-info-grid">
        <div class="unit-info-item"><label>No SPT</label><span style="font-weight:700">${t.noSPT}</span></div>
        <div class="unit-info-item"><label>Jenis Audit</label><span>${t.jenisAudit}</span></div>
        <div class="unit-info-item"><label>Cabang</label><span>${t.cabangPlan}${t.cabangArea?' '+areaBadge(t.cabangArea):''}</span></div>
        <div class="unit-info-item"><label>Status</label><span>${taskStatusBadge(t.status)}</span></div>
      </div>`;
    }
    const banner    = document.getElementById('kdsPlanBanner');
    const bannerCnt = document.getElementById('kdsPlanBannerContent');
    if (banner && bannerCnt) {
      bannerCnt.innerHTML =
        '<span><strong>'+(t.noSPT||'—')+'</strong></span>'+
        '<span style="opacity:.6">|</span>'+
        '<span>🏢 '+(t.cabangPlan||'—')+'</span>'+
        '<span style="opacity:.6">|</span>'+
        '<span>📋 '+(t.jenisAudit||'—')+'</span>';
      banner.style.display = '';
    }

    const rec = getKds(t.planId);
    const _s  = (id, val) => { const el = document.getElementById(id); if (el) el.value = val || ''; };
    _s('kds_auditee',        rec.auditee);
    _s('kds_tglPemeriksaan', rec.tglPemeriksaan || new Date().toISOString().slice(0,10));

    const msgEl = document.getElementById('kdsImportMsg');
    if (msgEl && rec.rows && rec.rows.length) {
      msgEl.innerHTML = `<span style="color:#16a34a">✅ ${rec.rows.length} data berhasil dimuat dari "${rec.fileName||'file Excel'}"</span>`;
    } else if (msgEl) {
      msgEl.textContent = '';
    }

    window._kdsRenderAll();

    document.querySelectorAll('.content-section').forEach(s => s.classList.add('hidden'));
    document.querySelectorAll('.nav-item').forEach(li => li.classList.remove('active'));
    const sec      = document.getElementById('section-pemeriksaan-tunggakan-kds');
    const auditNav = document.querySelector('.nav-item[data-section="audit"]');
    if (sec)      sec.classList.remove('hidden');
    if (auditNav) auditNav.classList.add('active');
  };

  // ── Proses file Excel KDS ─────────────────────────────────────
  function _processKdsFile(file) {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = e => {
      try {
        const { rows } = _parseKdsExcel(new Uint8Array(e.target.result));
        if (!rows.length) { showToast('Tidak ada data ditemukan di file Excel.', 'error'); return; }
        const rec      = getKds(_kdsPlanId);
        rec.rows       = rows;
        rec.fileName   = file.name;
        rec.importedAt = new Date().toISOString();
        saveKds(rec);
        const msgEl = document.getElementById('kdsImportMsg');
        if (msgEl) msgEl.innerHTML = `<span style="color:#16a34a">✅ ${rows.length} data berhasil dimuat dari "${file.name}"</span>`;
        const dbSt = document.getElementById('kdsDbStatus');
        if (dbSt) dbSt.textContent = '● DATABASE AKTIF';
        window._kdsRenderAll();
        showToast(`${rows.length} data Tunggakan KDS berhasil diimport.`, 'success');
      } catch(err) {
        showToast('Gagal membaca file Excel: ' + err.message, 'error');
      }
    };
    reader.readAsArrayBuffer(file);
  }

  // ── Print PDF individual Tunggakan KDS ───────────────────────
  window._kdsPrintPDF = function(planId) {
    const pid = planId || _kdsPlanId;
    if (!pid) return;
    const rec  = getKds(pid);
    const rows = rec.rows || [];
    if (!rows.length) { showToast('Tidak ada data untuk dicetak.', 'error'); return; }

    const task = loadTasks().find(t => String(t.planId) === String(pid));
    const fN   = n => n ? Number(n).toLocaleString('id-ID') : '-';
    const fN0  = n => Number(n||0).toLocaleString('id-ID');
    const fmtTglKds = s => s || '-';

    let gSaldo=0, gBJT=0, gT1_5=0, gT6_30=0, gT31_60=0, gTGt60=0;
    let gA0=0, gA1=0, gA2=0, gA3=0, gA4=0, gA5=0;
    rows.forEach(r => {
      gSaldo+=r.saldo||0; gBJT+=r.belumJT||0;
      gT1_5+=r.tgg1_5||0; gT6_30+=r.tgg6_30||0; gT31_60+=r.tgg31_60||0; gTGt60+=r.tggGt60||0;
      gA0+=r.a0bln||0; gA1+=r.a1bln||0; gA2+=r.a2||0; gA3+=r.a3||0; gA4+=r.a4||0; gA5+=r.aGt5||0;
    });

    const trs = rows.map((r,i) => `<tr>
      <td style="text-align:center">${i+1}</td>
      <td style="font-family:monospace;white-space:nowrap">${r.noKontrak||'-'}</td>
      <td style="white-space:nowrap;text-align:center">${fmtTglKds(r.tanggal)}</td>
      <td style="font-weight:600">${r.namaCustomer||'-'}</td>
      <td style="text-align:right">${fN(r.saldo)}</td>
      <td style="text-align:right;color:#166534">${fN(r.belumJT)}</td>
      <td style="text-align:right;color:${r.tgg1_5>0?'#b45309':'#374151'}">${r.tgg1_5?fN(r.tgg1_5):'-'}</td>
      <td style="text-align:right;color:${r.tgg6_30>0?'#b45309':'#374151'}">${r.tgg6_30?fN(r.tgg6_30):'-'}</td>
      <td style="text-align:right;color:${r.tgg31_60>0?'#dc2626':'#374151'}">${r.tgg31_60?fN(r.tgg31_60):'-'}</td>
      <td style="text-align:right;color:${r.tggGt60>0?'#7f1d1d':'#374151'}">${r.tggGt60?fN(r.tggGt60):'-'}</td>
      <td style="text-align:right">${r.a0bln?fN(r.a0bln):'-'}</td>
      <td style="text-align:right">${r.a1bln?fN(r.a1bln):'-'}</td>
      <td style="text-align:right">${r.a2?fN(r.a2):'-'}</td>
      <td style="text-align:right">${r.a3?fN(r.a3):'-'}</td>
      <td style="text-align:right">${r.a4?fN(r.a4):'-'}</td>
      <td style="text-align:right">${r.aGt5?fN(r.aGt5):'-'}</td>
      <td style="font-size:7px;max-width:120px;word-break:break-word">${r.keterangan||'-'}</td>
    </tr>`).join('');

    const html = `<!DOCTYPE html><html><head><meta charset="UTF-8">
      <title>Laporan Tunggakan KDS — ${task?.noSPT||pid}</title>
      <style>
        *{margin:0;padding:0;box-sizing:border-box}
        @page{size:A3 landscape;margin:8mm}
        body{font-family:'Times New Roman',serif;font-size:8px;color:#000;padding:6px}
        .hdr{text-align:center;margin-bottom:6px}
        .hdr h2{font-size:13px;font-weight:700;text-transform:uppercase}
        .hdr p{font-size:9px}
        table{width:100%;border-collapse:collapse}
        th{background:#000;color:#fff;padding:3px 3px;text-align:center;font-size:7px;white-space:nowrap;border:1px solid #000}
        th.tng{background:#555}
        th.ana{background:#222}
        td{padding:2px 3px;border:1px solid #999;font-size:7.5px}
        tr:nth-child(even) td{background:#f5f5f5}
        .gr td{font-weight:700;border-top:2px solid #000}
      </style></head><body>
      <div class="hdr">
        <h2>LAPORAN TUNGGAKAN KDS</h2>
        <p>Per Tanggal : ${rec.tglPemeriksaan||'—'}</p>
        <p style="margin-top:4px">${task?.cabangPlan||'—'}${task?.cabangArea?' ('+task.cabangArea+')':''} &nbsp;|&nbsp; Auditee: ${rec.auditee||'—'}</p>
      </div>
      <table>
        <thead>
          <tr>
            <th rowspan="2">No</th>
            <th colspan="2">Kontrak</th>
            <th rowspan="2">Nama Customer</th>
            <th rowspan="2">Saldo Piutang</th>
            <th rowspan="2">Belum Jatuh Tempo</th>
            <th colspan="4" class="tng">T u n g g a k a n</th>
            <th colspan="6" class="ana">Analisa ketidak-aktifan Deb. yang 00-61 hr keatas<br><span style="font-weight:400;font-size:6px">&lt;&lt; nilai dalam ribuan &gt;&gt;</span></th>
            <th rowspan="2">Keterangan</th>
          </tr>
          <tr>
            <th>Nomor</th><th>Tangg</th>
            <th class="tng">1 - 5</th><th class="tng">6 - 30</th><th class="tng">31 - 60</th><th class="tng">&gt; 60</th>
            <th class="ana">0 bln</th><th class="ana">1 bln</th><th class="ana">2 bln</th><th class="ana">3 bln</th><th class="ana">4 bln</th><th class="ana">&gt; 5 bln</th>
          </tr>
        </thead>
        <tbody>${trs}</tbody>
        <tfoot>
          <tr class="gr">
            <td colspan="4" style="text-align:center">Grand Total</td>
            <td style="text-align:right">${fN0(gSaldo)}</td>
            <td style="text-align:right">${fN0(gBJT)}</td>
            <td style="text-align:right">${fN0(gT1_5)}</td>
            <td style="text-align:right">${fN0(gT6_30)}</td>
            <td style="text-align:right">${fN0(gT31_60)}</td>
            <td style="text-align:right">${fN0(gTGt60)}</td>
            <td style="text-align:right">${fN0(gA0)}</td>
            <td style="text-align:right">${fN0(gA1)}</td>
            <td style="text-align:right">${fN0(gA2)}</td>
            <td style="text-align:right">${fN0(gA3)}</td>
            <td style="text-align:right">${fN0(gA4)}</td>
            <td style="text-align:right">${fN0(gA5)}</td>
            <td>-</td>
          </tr>
        </tfoot>
      </table>
      <script>window.onload=function(){window.print();}<\/script>
      </body></html>`;

    const w = window.open('about:blank');
    if (w) w.document.write(html);
  };

  // ── Event listeners KDS ───────────────────────────────────────
  document.addEventListener('DOMContentLoaded', () => {
    const browseBtn = document.getElementById('kdsBrowseBtn');
    const fileInput = document.getElementById('kdsFileInput');
    const dropZone  = document.getElementById('kdsDropZone');
    if (browseBtn && fileInput) {
      browseBtn.addEventListener('click', () => fileInput.click());
      fileInput.addEventListener('change', e => { if (e.target.files[0]) _processKdsFile(e.target.files[0]); e.target.value = ''; });
    }
    if (dropZone) {
      dropZone.addEventListener('dragover',  e => { e.preventDefault(); dropZone.style.background = '#fef3c7'; });
      dropZone.addEventListener('dragleave', () => { dropZone.style.background = '#fffbeb'; });
      dropZone.addEventListener('drop', e => {
        e.preventDefault(); dropZone.style.background = '#fffbeb';
        _processKdsFile(e.dataTransfer.files[0]);
      });
    }
  });

  /* ── END MODUL TUNGGAKAN KDS ── */

  /* ============================================================
     MODUL TTP GANTUNG
     Import laporan HTML dari sistem leasing.
     Kolom: No TTP | Tgl | No Faktur | Nama | Nilai | Sudah Cair
            | Tgl Cair | Nilai Cair | Tagihan Belum Cair | Ket | Diff | Fisik
     Dikelompokkan per Area (ADIRA, CMD, FIF, dll.)
     ============================================================ */
  const TTP_KEY = 'akta_ttp_gantung';
  let _ttpTaskId = null;
  let _ttpPlanId = null;

  function loadTtpAll()  { try { return JSON.parse(localStorage.getItem(TTP_KEY)) || []; } catch { return []; } }
  function saveTtpAll(d) { localStorage.setItem(TTP_KEY, JSON.stringify(d)); window.API?.sync(TTP_KEY, d); }

  function getTtp(planId) {
    return loadTtpAll().find(r => String(r.planId) === String(planId)) ||
           { planId: String(planId), rows: [], fileName: '', importedAt: null, auditee: '', tglPemeriksaan: '' };
  }
  function saveTtp(data) {
    const all = loadTtpAll();
    const idx = all.findIndex(r => String(r.planId) === String(data.planId));
    if (idx >= 0) all[idx] = data; else all.push(data);
    saveTtpAll(all);
  }

  window._ttpAutoSave = function() {
    if (!_ttpPlanId) return;
    const rec = getTtp(_ttpPlanId);
    rec.auditee        = (document.getElementById('ttp_auditee')?.value || '').trim();
    rec.tglPemeriksaan = (document.getElementById('ttp_tglPemeriksaan')?.value || '').trim();
    saveTtp(rec);
  };

  // ── Simpan keterangan manual per baris ───────────────────────
  window._ttpKetSave = function(rowIdx, value) {
    if (!_ttpPlanId) return;
    const rec = getTtp(_ttpPlanId);
    if (!rec.rows || rowIdx < 0 || rowIdx >= rec.rows.length) return;
    rec.rows[rowIdx].keteranganManual = value.trim();
    saveTtp(rec);
  };

  // ── Toggle FISIK checkbox ─────────────────────────────────────
  window._ttpFisikToggle = function(rowIdx, val) {
    if (!_ttpPlanId) return;
    const rec = getTtp(_ttpPlanId);
    if (!rec.rows || rowIdx < 0 || rowIdx >= rec.rows.length) return;
    rec.rows[rowIdx].fisik = val;
    saveTtp(rec);
  };

  // ── Simpan status manual per baris ───────────────────────────
  window._ttpStatusSave = function(rowIdx, value) {
    if (!_ttpPlanId) return;
    const rec = getTtp(_ttpPlanId);
    if (!rec.rows || rowIdx < 0 || rowIdx >= rec.rows.length) return;
    rec.rows[rowIdx].statusManual = value.trim();
    saveTtp(rec);
  };

  // ── Parse laporan HTML TTP Gantung (robust multi-format) ─────
  function _parseTtpHtml(html) {
    const parser = new DOMParser();
    const rows   = [];
    const doc    = parser.parseFromString(html, 'text/html');

    const toN   = s => { const n = parseFloat(String(s||'').replace(/\./g,'').replace(',','.').replace(/[^\d.-]/g,'')); return isNaN(n) ? 0 : n; };
    const toU   = s => String(s||'').trim().toUpperCase();
    const clean = s => String(s||'').replace(/\s+/g,' ').trim();

    // Keywords untuk setiap field
    const FIELD_KW = {
      noTtp:            ['no ttp','no. ttp','nomor ttp','no.ttp','nottp'],
      tglTtp:           ['tgl ttp','tgl. ttp','tanggal ttp','tgl.ttp','tglttp'],
      noFaktur:         ['no faktur','no. faktur','nomor faktur','no.faktur','nofaktur','faktur','invoice'],
      nama:             ['nama customer','nama debitur','nama nasabah','nama','customer','debitur','nasabah'],
      nilai:            ['nilai tagihan','nilai (rp)','nilai rp','nilai','amount'],
      sudahCair:        ['sudah cair','terbayar','dibayar','paid'],
      tglCair:          ['tgl cair','tanggal cair','tgl pencairan','tanggal pencairan','tgl. cair'],
      nilaiCair:        ['nilai cair','nilai pencairan','pencairan (rp)'],
      tagihanBelumCair: ['tagihan belum cair','belum cair','sisa tagihan','outstanding'],
      keterangan:       ['keterangan','ket.','notes','remark'],
      diff:             ['diff (hari)','diff hari','aging'],
      status:           ['status'],
    };

    // ── Bangun grid 2D yang memperhitungkan colspan DAN rowspan ──
    // Setiap cell di grid[baris][kolom] berisi teks header sebenarnya
    function buildGrid(trs, maxR) {
      const grid = [];
      const occ  = {}; // occupied by rowspan: key = "r,c"
      for (let ri = 0; ri < Math.min(trs.length, maxR); ri++) {
        if (!grid[ri]) grid[ri] = [];
        let col = 0;
        Array.from(trs[ri].querySelectorAll('th,td')).forEach(cell => {
          while (occ[`${ri},${col}`]) col++;
          const cs  = Math.max(1, parseInt(cell.getAttribute('colspan')||'1'));
          const rs  = Math.max(1, parseInt(cell.getAttribute('rowspan')||'1'));
          const txt = clean(cell.textContent);
          for (let dr = 0; dr < rs; dr++) {
            if (!grid[ri+dr]) grid[ri+dr] = [];
            for (let dc = 0; dc < cs; dc++) {
              grid[ri+dr][col+dc] = txt;
              if (dr > 0 || dc > 0) occ[`${ri+dr},${col+dc}`] = true;
            }
          }
          col += cs;
        });
      }
      return grid;
    }

    // ── Skor satu baris grid terhadap FIELD_KW ───────────────────
    function scoreGridRow(rowArr) {
      const low = (rowArr||[]).map(t => (t||'').toLowerCase());
      let score = 0; const map = {};
      Object.entries(FIELD_KW).forEach(([field, kws]) => {
        const idx = low.findIndex(c => kws.some(k => c === k || c.includes(k)));
        if (idx >= 0) { map[field] = idx; score++; }
      });
      return { score, map };
    }

    const allTrs = Array.from(doc.querySelectorAll('tr'));
    if (!allTrs.length) return [];

    // ── Bangun grid untuk 40 baris pertama ───────────────────────
    const GRID_MAX = Math.min(allTrs.length, 40);
    const grid = buildGrid(allTrs, GRID_MAX);

    // ── Identifikasi baris data pertama: row dimana sel pertama
    //    berisi angka / non-keyword dan baris sebelumnya punya keyword ─
    // Strategi: scan grid, kumpulkan semua baris dengan score ≥ 1,
    //           merge colMap mereka, lalu data mulai setelah baris terakhir header

    let colMap      = {};
    let headerEndRow = 0;

    for (let ri = 0; ri < GRID_MAX; ri++) {
      const { score, map } = scoreGridRow(grid[ri]);
      if (score >= 1) {
        Object.assign(colMap, map); // merge — baris terakhir overrides
        headerEndRow = ri + 1;
      } else if (headerEndRow > 0) {
        break; // setelah header section, data dimulai
      }
    }

    // ── Isi gap colMap secara posisional (TTP report standar) ────
    // Urutan kolom standar: [rowNo, noTtp, tglTtp, noFaktur, nama, nilai,
    //                        sudahCair, tglCair, nilaiCair, belumCair, ket, status]
    (function fillGaps() {
      const m = colMap;
      // Penentu anchor: sudahCair adalah keyword paling mudah terdeteksi
      if (m.sudahCair !== undefined) {
        const sc = m.sudahCair;
        if (m.nilai        === undefined) m.nilai        = sc - 1;
        if (m.noFaktur     === undefined) m.noFaktur     = sc - 3;
        if (m.nama         === undefined) m.nama         = sc - 2;
        if (m.tglTtp       === undefined) m.tglTtp       = sc - 4;
        if (m.noTtp        === undefined) m.noTtp        = sc - 5;
        if (m.tglCair      === undefined) m.tglCair      = sc + 1;
        if (m.nilaiCair    === undefined) m.nilaiCair    = sc + 2;
        if (m.tagihanBelumCair === undefined) m.tagihanBelumCair = sc + 3;
        if (m.keterangan   === undefined) m.keterangan   = sc + 4;
        if (m.status       === undefined) m.status       = sc + 5;
      } else if (m.nama !== undefined) {
        const na = m.nama;
        if (m.noFaktur  === undefined) m.noFaktur  = na - 1;
        if (m.tglTtp    === undefined) m.tglTtp    = na - 2;
        if (m.noTtp     === undefined) m.noTtp     = na - 3;
        if (m.nilai     === undefined) m.nilai     = na + 1;
        if (m.sudahCair === undefined) m.sudahCair = na + 2;
        if (m.tglCair   === undefined) m.tglCair   = na + 3;
        if (m.nilaiCair === undefined) m.nilaiCair = na + 4;
        if (m.tagihanBelumCair === undefined) m.tagihanBelumCair = na + 5;
        if (m.keterangan === undefined) m.keterangan = na + 6;
        if (m.status     === undefined) m.status     = na + 7;
      }
    })();

    const calcDiff = tglStr => {
      if (!tglStr) return 0;
      const s = tglStr.replace(/\s/g,'');
      const parts = s.split(/[-\/\.]/);
      if (parts.length !== 3) return 0;
      const [p0,p1,p2] = parts.map(Number);
      const d = p2 > 1000 ? new Date(p2, p1-1, p0) : new Date(p0, p1-1, p2);
      if (isNaN(d)) return 0;
      return Math.max(0, Math.floor((Date.now() - d.getTime()) / 86400000));
    };

    // ── Iterasi data rows ─────────────────────────────────────────
    let currentArea = '';
    for (let ri = headerEndRow; ri < allTrs.length; ri++) {
      const tr       = allTrs[ri];
      const rawCells = Array.from(tr.querySelectorAll('th,td'));
      const texts    = rawCells.map(c => clean(c.textContent));
      if (!texts.length || texts.every(t => !t)) continue;

      const rowLow = texts.join(' ').toLowerCase();

      // Skip header ulang
      if (scoreGridRow(texts).score >= 3) continue;

      // Skip total
      if (/total|grand total|sub total|subtotal/i.test(rowLow)) continue;

      // Deteksi baris area label
      const ne  = texts.filter(t => t.length > 0);
      const hasCs = rawCells.some(c => parseInt(c.getAttribute('colspan')||'1') > 3);
      if (hasCs || (ne.length === 1 && texts.length > 3)) {
        const cand = toU(ne[0]).replace(/:/g,'').trim();
        if (cand.length > 0 && cand.length < 40 && !/^\d/.test(cand) && !/total/i.test(cand)) {
          currentArea = cand; continue;
        }
      }

      // Proses baris data
      const get  = (f, def='') => { const i = colMap[f]; return (i !== undefined && i >= 0) ? (texts[i]||def) : def; };
      const getN = f           => { const i = colMap[f]; return (i !== undefined && i >= 0) ? toN(texts[i]) : 0; };

      const noTtp    = clean(get('noTtp'));
      const nama     = clean(get('nama'));
      const tglStr   = clean(get('tglTtp'));
      const noFaktur = clean(get('noFaktur'));

      if (!noTtp && !nama && !noFaktur) continue;
      if (/^no\.?\s*ttp$/i.test(noTtp)) continue;

      let diff = getN('diff');
      if (!diff && tglStr) diff = calcDiff(tglStr);

      const nilaiVal  = getN('nilai');
      const sudahCair = getN('sudahCair');
      const nilaiCair = getN('nilaiCair') || sudahCair;
      const belumCair = getN('tagihanBelumCair') || Math.max(0, nilaiVal - nilaiCair);

      rows.push({
        area:             currentArea || 'LAINNYA',
        noTtp,  tglTtp: tglStr,  noFaktur,  nama,
        nilai:  nilaiVal,  sudahCair,
        tglCair:          clean(get('tglCair')) || '-',
        nilaiCair,
        tagihanBelumCair: belumCair,
        keterangan:       clean(get('keterangan')),
        keteranganManual: '',
        status:           clean(get('status')) || '-',
        statusManual:     '',  diff,  fisik: false,
      });
    }

    // ── Fallback posisional: jika keyword approach gagal ─────────
    // Deteksi baris berisi kode TTP (pola: 2-3 huruf kapital + angka)
    if (!rows.length) {
      const TTP_RE = /^[A-Z]{2,3}\d{3,8}$/;
      let area2 = '';
      for (const tr of allTrs) {
        const rawCells = Array.from(tr.querySelectorAll('th,td'));
        const t = rawCells.map(c => clean(c.textContent));
        if (!t.length || t.every(x => !x)) continue;
        if (/total|grand total|subtotal/i.test(t.join(' ').toLowerCase())) continue;

        const ne2 = t.filter(x => x.length > 0);
        const hasCs2 = rawCells.some(c => parseInt(c.getAttribute('colspan')||'1') > 3);
        if (hasCs2 || (ne2.length === 1 && t.length > 3)) {
          const cand = toU(ne2[0]).replace(/:/g,'').trim();
          if (cand.length > 0 && cand.length < 40 && !/^\d/.test(cand) && !/total/i.test(cand)) {
            area2 = cand; continue;
          }
        }

        let ttpCol = -1;
        for (let ci = 0; ci <= Math.min(3, t.length - 1); ci++) {
          if (TTP_RE.test(t[ci].toUpperCase().replace(/\s/g,''))) { ttpCol = ci; break; }
        }
        if (ttpCol < 0) continue;

        const g  = (off, def='') => clean(t[ttpCol + off] || def);
        const gN = off           => toN(t[ttpCol + off]);
        const nv = gN(4), sc = gN(5), nc = gN(7) || sc;

        rows.push({
          area: area2 || 'LAINNYA',
          noTtp: g(0), tglTtp: g(1), noFaktur: g(2), nama: g(3),
          nilai: nv, sudahCair: sc, tglCair: g(6) || '-', nilaiCair: nc,
          tagihanBelumCair: gN(8) || Math.max(0, nv - nc),
          keterangan: g(9), keteranganManual: '',
          status: g(10) || '-', statusManual: '',
          diff: calcDiff(g(1)), fisik: false,
        });
      }
    }
    return rows;
  }

  // ── Render tabel TTP ─────────────────────────────────────────
  function _ttpRenderTable(rec) {
    const hasilEl = document.getElementById('ttpHasilSection');
    if (!hasilEl) return;
    const rows    = rec.rows || [];
    const isSaved = loadSavedPem().some(s => String(s.planId) === String(_ttpPlanId) && s.type === 'ttp_gantung');
    if (!rows.length) { hasilEl.innerHTML = ''; return; }

    const fN  = n => Number(n||0).toLocaleString('id-ID');
    const fN0 = n => Number(n||0).toLocaleString('id-ID');
    const TH1 = 'padding:5px 4px;background:#0f4c81;color:#fff;font-size:.7rem;white-space:nowrap;border:1px solid rgba(255,255,255,.2);text-align:center';
    const TH2 = 'padding:5px 4px;background:#1e6a9e;color:#fff;font-size:.7rem;white-space:nowrap;border:1px solid rgba(255,255,255,.15);text-align:center';
    const TH3 = 'padding:5px 4px;background:#065f46;color:#d1fae5;font-size:.7rem;white-space:nowrap;border:1px solid rgba(255,255,255,.15);text-align:center';
    const td  = (v, e='') => `<td style="padding:4px 5px;border:1px solid #e5e7eb;font-size:.76rem;${e}">${v}</td>`;
    const ftd = (v, e='') => `<td style="padding:5px;border:1px solid #cbd5e1;font-size:.76rem;font-weight:700;background:#eff6ff;${e}">${v}</td>`;

    const BULAN_ID = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
    const fmtIndo = s => {
      if (!s) return '—';
      const p = String(s).split('-');
      if (p.length !== 3) return s;
      const [y, m, d] = p.map(Number);
      return `${d} ${BULAN_ID[m-1]||m} ${y}`;
    };
    const periode = fmtIndo(rec.tglPemeriksaan);

    // ── Hitung selisih hari: tglTtp → tglPemeriksaan (inklusif) ──
    // Jika tglPemeriksaan belum diisi, gunakan tanggal hari ini sebagai acuan
    const calcHariTtp = tglTtpStr => {
      if (!tglTtpStr || tglTtpStr === '-') return null;
      const parse = s => {
        const p = String(s).replace(/\s/g,'').split(/[-\/\.]/);
        if (p.length !== 3) return NaN;
        const [a, b, c] = p.map(Number);
        return a > 1000 ? new Date(a, b-1, c) : new Date(c, b-1, a);
      };
      const d1 = parse(tglTtpStr);
      if (isNaN(+d1)) return null;
      // Gunakan tglPemeriksaan jika ada, fallback ke hari ini
      const refStr = rec.tglPemeriksaan || (() => {
        const n = new Date();
        return `${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,'0')}-${String(n.getDate()).padStart(2,'0')}`;
      })();
      const d2 = parse(refStr);
      if (isNaN(+d2)) return null;
      const h = Math.round((+d2 - +d1) / 86400000) + 1;
      return h > 0 ? h : null; // abaikan jika tanggal TTP setelah tanggal pemeriksaan
    };
    const hariTd = (tglTtpStr) => {
      const h = calcHariTtp(tglTtpStr);
      if (h === null) return `<td style="padding:4px 5px;border:1px solid #e5e7eb;font-size:.76rem;text-align:center;color:#9ca3af">-</td>`;
      const c = h > 90 ? '#dc2626' : h > 30 ? '#d97706' : '#374151';
      return `<td style="padding:4px 5px;border:1px solid #e5e7eb;font-size:.76rem;text-align:center;font-weight:700;color:${c}">${h}</td>`;
    };

    // Kelompokkan per area
    const areas = [...new Set(rows.map(r => r.area))];
    let gBelum=0;
    rows.forEach(r => { gBelum+=r.tagihanBelumCair||0; });

    let trs = '';
    areas.forEach(area => {
      const aRows = rows.filter(r => r.area === area);
      let aTotal = 0; aRows.forEach(r => aTotal += r.tagihanBelumCair||0);
      // Baris header area
      trs += `<tr style="background:#dbeafe">
        <td colspan="14" style="padding:5px 8px;font-size:.78rem;font-weight:800;color:#1e3a5f;border:1px solid #bfdbfe;letter-spacing:.04em">
          ${area}
        </td>
      </tr>`;
      aRows.forEach((r, i) => {
        const rowIdx = rows.indexOf(r);
        trs += `<tr style="background:${i%2===0?'#fff':'#f8fafc'}">
          ${td(i+1,'text-align:center;color:#9ca3af;font-size:.7rem')}
          ${td(`<span style="font-family:monospace;font-size:.73rem;font-weight:600;color:#1e3a5f">${r.noTtp||'-'}</span>`)}
          ${td(r.tglTtp||'-','font-size:.72rem;white-space:nowrap;text-align:center')}
          ${td(`<span style="font-family:monospace;font-size:.72rem">${r.noFaktur||'-'}</span>`)}
          ${td(`<span style="font-weight:600;color:#0f4c81">${r.nama||'-'}</span>`)}
          ${td(fN(r.nilai),'text-align:right')}
          ${td(fN0(r.sudahCair||0),'text-align:right')}
          ${td(r.tglCair&&r.tglCair!=='-'?r.tglCair:'-','font-size:.72rem;text-align:center;white-space:nowrap')}
          ${td(fN0(r.nilaiCair||0),'text-align:right')}
          ${td(r.tagihanBelumCair>0?`<strong style="color:#dc2626">${fN(r.tagihanBelumCair)}</strong>`:fN0(0),'text-align:right')}
          ${hariTd(r.tglTtp)}
          ${td(r.keterangan ? `<span style="color:#374151;font-size:.7rem;line-height:1.4;white-space:pre-line">${r.keterangan}</span>` : '<span style="color:#c0c4cc">—</span>','vertical-align:top')}
          <td style="padding:2px 3px;border:1px solid #e5e7eb;font-size:.7rem;min-width:90px;max-width:180px;vertical-align:middle">
            <input type="text" value="${(r.keteranganManual||'').replace(/"/g,'&quot;')}"
              placeholder="Isi keterangan…"
              oninput="window._ttpKetSave(${rowIdx},this.value)"
              style="width:100%;border:1px solid #e5e7eb;background:#fff;font-size:.72rem;color:#374151;outline:none;padding:3px 5px;border-radius:4px"
              onfocus="this.style.borderColor='#6366f1';this.style.background='#f5f3ff'" onblur="this.style.borderColor='#e5e7eb';this.style.background='#fff'">
          </td>
          <td style="padding:2px 3px;border:1px solid #e5e7eb;font-size:.7rem;min-width:44px;vertical-align:middle;text-align:center">
            <input type="text" value="${(r.statusManual||r.status||'-').replace(/"/g,'&quot;')}"
              oninput="window._ttpStatusSave(${rowIdx},this.value)"
              style="width:100%;border:none;background:transparent;font-size:.72rem;color:#374151;outline:none;padding:1px 2px;text-align:center;border-radius:3px"
              onfocus="this.style.background='#fef9c3'" onblur="this.style.background='transparent'">
          </td>
        </tr>`;
      });
      // Subtotal area
      trs += `<tr style="background:#eff6ff">
        <td colspan="9" style="padding:4px 8px;font-size:.74rem;font-weight:700;color:#1e3a5f;border:1px solid #bfdbfe;text-align:right">
          TOTAL ${area}
        </td>
        ${ftd(`<strong style="color:#dc2626">${fN0(aTotal)}</strong>`,'text-align:right;background:#eff6ff')}
        <td colspan="4" style="border:1px solid #bfdbfe;background:#eff6ff"></td>
      </tr>`;
    });

    hasilEl.innerHTML = `
      <div class="pem-card">
        <div style="text-align:center;padding:12px 16px 6px">
          <div style="font-size:.95rem;font-weight:800;text-transform:uppercase;letter-spacing:.04em;color:#0f4c81">LAPORAN PENGONTROLAN TAGIHAN TTP</div>
          <div style="font-size:.8rem;color:#374151;margin-top:3px">Periode : ${periode} s/d ${periode}</div>
        </div>
        ${rec.auditee ? `<div style="padding:2px 16px 8px;font-size:.82rem;font-weight:700;color:#374151">Sales Office ${rec.auditee}</div>` : ''}
        <div class="pem-card-header" style="background:#0f4c81;color:#fff;padding:10px 16px;display:flex;align-items:center;justify-content:space-between">
          <div style="display:flex;align-items:center;gap:8px;font-size:.85rem;font-weight:700;text-transform:uppercase;letter-spacing:.04em">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2"/><rect x="9" y="3" width="6" height="4" rx="1"/></svg>
            DAFTAR TAGIHAN TTP GANTUNG
          </div>
          <span style="font-size:.75rem;font-weight:600;background:rgba(255,255,255,.15);padding:2px 10px;border-radius:10px">${rows.length} DATA</span>
        </div>
        <div class="pem-card-body" style="border:1px solid #0f4c81;border-top:none;border-radius:0 0 8px 8px;overflow-x:auto;padding:0">
          <table style="width:100%;border-collapse:collapse;min-width:1180px">
            <thead>
              <tr>
                <th rowspan="2" style="${TH1}">NO.</th>
                <th colspan="2" style="${TH1}">TTP</th>
                <th colspan="4" style="${TH2}">FAKTUR</th>
                <th colspan="2" style="${TH3}">PENCAIRAN</th>
                <th rowspan="2" style="${TH1}">TAGIHAN YANG<br>BELUM CAIR</th>
                <th rowspan="2" style="${TH1}">HARI</th>
                <th rowspan="2" style="${TH1}">KETERANGAN</th>
                <th rowspan="2" style="${TH1}">CATATAN<br>AUDITOR</th>
                <th rowspan="2" style="${TH1}">STATUS</th>
              </tr>
              <tr>
                <th style="${TH1}">NO.</th>
                <th style="${TH1}">TGL.</th>
                <th style="${TH2}">NO.</th>
                <th style="${TH2}">NAMA</th>
                <th style="${TH2}">NILAI</th>
                <th style="${TH2}">SUDAH CAIR</th>
                <th style="${TH3}">TANGGAL</th>
                <th style="${TH3}">NILAI</th>
              </tr>
            </thead>
            <tbody>${trs}</tbody>
            <tfoot>
              <tr>
                <td colspan="9" style="padding:5px 8px;border:1px solid #cbd5e1;font-size:.76rem;font-weight:700;background:#eff6ff;text-align:right;color:#0f4c81">Grand Total</td>
                <td style="padding:5px;border:1px solid #cbd5e1;font-size:.76rem;font-weight:700;background:#eff6ff;text-align:right"><strong style="color:#dc2626">${fN0(gBelum)}</strong></td>
                <td colspan="4" style="border:1px solid #cbd5e1;background:#eff6ff"></td>
              </tr>
            </tfoot>
          </table>
        </div>
      </div>
      <!-- Simpan ke Report Audit -->
      <div style="margin-top:14px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px">
        <span style="font-size:.8rem;color:${isSaved?'#16a34a':'#6b7280'}">
          ${isSaved ? '✅ Sudah disimpan ke Report Audit' : '○ Belum disimpan ke Report Audit'}
        </span>
        <div style="display:flex;gap:8px">
          <button onclick="window._ttpPrintPDF('${_ttpPlanId}')"
                  style="background:#0f4c81;color:#fff;border:none;border-radius:7px;padding:7px 16px;font-size:.82rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:6px">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 01-2-2v-5a2 2 0 012-2h16a2 2 0 012 2v5a2 2 0 01-2 2h-2"/>
              <rect x="6" y="14" width="12" height="8"/>
            </svg>
            Cetak PDF
          </button>
          <button onclick="window._simpanPemeriksaan('${_ttpPlanId}','ttp_gantung')"
                  style="background:#16a34a;color:#fff;border:none;border-radius:7px;padding:7px 16px;font-size:.82rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:6px">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/>
              <polyline points="17 21 17 13 7 13 7 21"/><polyline points="7 3 7 8 15 8"/>
            </svg>
            Simpan ke Report Audit
          </button>
        </div>
      </div>`;
  }

  // ── Render stats cards ────────────────────────────────────────
  function _ttpRenderStats(rec) {
    const rows    = rec.rows || [];
    const statsEl = document.getElementById('ttpStats');
    const cardsEl = document.getElementById('ttpStatCards');
    const dbSt    = document.getElementById('ttpDbStatus');
    if (!statsEl || !cardsEl) return;
    if (!rows.length) { statsEl.style.display='none'; if(dbSt) dbSt.textContent=''; return; }

    let gBelum=0, maxDiff=0, gFisik=0;
    rows.forEach(r => { gBelum+=r.tagihanBelumCair||0; if((r.diff||0)>maxDiff) maxDiff=r.diff; if(r.fisik) gFisik++; });

    const fJt = n => { if(!n) return 'Rp 0'; const v=Math.abs(n); if(v>=1e9) return `Rp ${(n/1e9).toFixed(2)} M`; if(v>=1e6) return `Rp ${(n/1e6).toFixed(1)} Jt`; return 'Rp '+n.toLocaleString('id-ID'); };
    const card = (val,lbl,clr='#374151',bg='#fff',bdr='#e5e7eb') =>
      `<div style="background:${bg};border:2px solid ${bdr};border-radius:8px;padding:10px 14px;text-align:center;min-width:90px">
        <div style="font-size:1rem;font-weight:800;color:${clr}">${val}</div>
        <div style="font-size:.65rem;font-weight:700;text-transform:uppercase;color:#6b7280;margin-top:2px">${lbl}</div>
      </div>`;

    cardsEl.innerHTML =
      card(rows.length,      'Total Data',             '#0f4c81','#eff6ff','#93c5fd') +
      card(fJt(gBelum),      'Total Tagihan Belum Cair','#dc2626','#fef2f2','#fca5a5') +
      card(maxDiff+' hari',  'Diff Terlama',            '#d97706','#fffbeb','#fcd34d') +
      card(gFisik+'/'+rows.length,'Fisik Terverifikasi','#15803d','#f0fdf4','#86efac');
    statsEl.style.display = '';
    if (dbSt) dbSt.textContent = '● DATABASE AKTIF';
  }

  window._ttpRenderAll = function() {
    if (!_ttpPlanId) return;
    const rec = getTtp(_ttpPlanId);
    _ttpRenderStats(rec);
    _ttpRenderTable(rec);
  };

  // ── Print PDF ─────────────────────────────────────────────────
  window._ttpPrintPDF = function(pid) {
    const rec  = getTtp(pid);
    const rows = rec.rows || [];
    if (!rows.length) { showToast('Belum ada data untuk dicetak.', 'error'); return; }

    const tasks = loadTasks();
    const task  = tasks.find(t => String(t.planId) === String(pid));
    const fN    = n => Number(n||0).toLocaleString('id-ID');
    const fN0   = n => Number(n||0).toLocaleString('id-ID');

    const BULAN_ID = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
    const fmtIndo = s => {
      if (!s) return '—';
      const p = String(s).split('-');
      if (p.length !== 3) return s;
      const [y, m, d] = p.map(Number);
      return `${d} ${BULAN_ID[m-1]||m} ${y}`;
    };
    const periode = fmtIndo(rec.tglPemeriksaan);

    let gBelum=0;
    rows.forEach(r => gBelum+=r.tagihanBelumCair||0);

    const areas = [...new Set(rows.map(r => r.area))];
    let trs = '';
    const calcHariPdf = tglTtpStr => {
      if (!tglTtpStr || tglTtpStr === '-') return null;
      const parse = s => {
        const p = String(s).replace(/\s/g,'').split(/[-\/\.]/);
        if (p.length !== 3) return NaN;
        const [a, b, c] = p.map(Number);
        return a > 1000 ? new Date(a, b-1, c) : new Date(c, b-1, a);
      };
      const d1 = parse(tglTtpStr);
      if (isNaN(+d1)) return null;
      const refStr = rec.tglPemeriksaan || (() => {
        const n = new Date();
        return `${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,'0')}-${String(n.getDate()).padStart(2,'0')}`;
      })();
      const d2 = parse(refStr);
      if (isNaN(+d2)) return null;
      const h = Math.round((+d2 - +d1) / 86400000) + 1;
      return h > 0 ? h : null;
    };

    areas.forEach(area => {
      const aRows = rows.filter(r => r.area === area);
      let aTotal = 0; aRows.forEach(r => aTotal += r.tagihanBelumCair||0);
      trs += `<tr style="background:#dbeafe"><td colspan="14" style="padding:4px 6px;font-weight:800;font-size:8px;color:#1e3a5f;border:1px solid #bfdbfe">${area}</td></tr>`;
      aRows.forEach((r,i) => {
        const hari   = calcHariPdf(r.tglTtp);
        const status = r.statusManual || r.status || '-';
        trs += `<tr>
          <td style="text-align:center">${i+1}</td>
          <td style="font-family:monospace;white-space:nowrap">${r.noTtp||'-'}</td>
          <td style="white-space:nowrap;text-align:center">${r.tglTtp||'-'}</td>
          <td style="font-family:monospace;font-size:7px">${r.noFaktur||'-'}</td>
          <td style="font-weight:600">${r.nama||'-'}</td>
          <td style="text-align:right">${fN(r.nilai)}</td>
          <td style="text-align:right">${fN0(r.sudahCair||0)}</td>
          <td style="white-space:nowrap;text-align:center">${r.tglCair&&r.tglCair!=='-'?r.tglCair:'-'}</td>
          <td style="text-align:right">${fN0(r.nilaiCair||0)}</td>
          <td style="text-align:right;color:#dc2626;font-weight:700">${r.tagihanBelumCair>0?fN(r.tagihanBelumCair):fN0(0)}</td>
          <td style="text-align:center;font-weight:700;color:${hari!==null&&hari>90?'#dc2626':hari!==null&&hari>30?'#b45309':'#374151'}">${hari!==null?hari:'-'}</td>
          <td style="font-size:6.5px;max-width:120px;word-break:break-word">${r.keterangan||'-'}</td>
          <td style="font-size:6.5px;max-width:120px;word-break:break-word">${r.keteranganManual||''}</td>
          <td style="text-align:center">${status}</td>
        </tr>`;
      });
      trs += `<tr style="background:#eff6ff"><td colspan="9" style="font-weight:700;font-size:7.5px;text-align:right;border-top:1px solid #93c5fd">TOTAL ${area}</td><td style="text-align:right;font-weight:800;color:#dc2626">${fN0(aTotal)}</td><td colspan="4"></td></tr>`;
    });

    const html = `<!DOCTYPE html><html><head><meta charset="UTF-8">
      <title>TTP Gantung — ${task?.noSPT||pid}</title>
      <style>
        *{margin:0;padding:0;box-sizing:border-box}
        @page{size:A3 landscape;margin:8mm}
        body{font-family:'Times New Roman',serif;font-size:8px;color:#000;padding:6px}
        .hdr{text-align:center;margin-bottom:6px}
        .hdr h2{font-size:13px;font-weight:700;text-transform:uppercase}
        .hdr p{font-size:9px}
        .hdr .so{text-align:left;font-size:9px;font-weight:700;margin-top:3px}
        table{width:100%;border-collapse:collapse}
        th{background:#0f4c81;color:#fff;padding:3px;text-align:center;font-size:7px;white-space:nowrap;border:1px solid #000}
        td{padding:2px 3px;border:1px solid #aaa;font-size:7.5px}
        tr:nth-child(even) td{background:#f0f4ff}
        .gr td{font-weight:700;border-top:2px solid #000;background:#dbeafe}
      </style></head><body>
      <div class="hdr">
        <h2>LAPORAN PENGONTROLAN TAGIHAN TTP</h2>
        <p>Periode : ${periode} s/d ${periode}</p>
        ${rec.auditee ? `<p class="so">Sales Office ${rec.auditee}</p>` : ''}
      </div>
      <table>
        <thead>
          <tr>
            <th rowspan="2">No</th>
            <th colspan="2">TTP</th>
            <th colspan="4">Faktur</th>
            <th colspan="2">Pencairan</th>
            <th rowspan="2">Tagihan Yang Belum Cair</th>
            <th rowspan="2">Hari</th>
            <th rowspan="2">Keterangan</th>
            <th rowspan="2">Catatan Auditor</th>
            <th rowspan="2">Status</th>
          </tr>
          <tr>
            <th>No.</th><th>Tgl.</th>
            <th>No.</th><th>Nama</th><th>Nilai</th><th>Sudah Cair</th>
            <th>Tanggal</th><th>Nilai</th>
          </tr>
        </thead>
        <tbody>${trs}</tbody>
        <tfoot>
          <tr class="gr">
            <td colspan="9" style="text-align:right">Grand Total</td>
            <td style="text-align:right;color:#dc2626">${fN0(gBelum)}</td>
            <td colspan="4"></td>
          </tr>
        </tfoot>
      </table>
      </body></html>`;

    const win = window.open('','_blank','width=1200,height=800');
    if (win) { win.document.write(html); win.document.close(); setTimeout(() => win.print(), 600); }
    else showToast('Popup diblokir browser. Izinkan popup untuk cetak PDF.', 'error');
  };

  // ── Buka section TTP Gantung ──────────────────────────────────
  window._openTtpGantung = function(taskId) {
    tasks = loadTasks();
    const t = tasks.find(x => String(x.id) === String(taskId));
    if (!t) return;
    _ttpTaskId = taskId;
    _ttpPlanId = t.planId;

    const infoEl = document.getElementById('ttpPlanInfo');
    if (infoEl) {
      infoEl.innerHTML = `<div class="unit-info-grid">
        <div class="unit-info-item"><label>No SPT</label><span style="font-weight:700">${t.noSPT}</span></div>
        <div class="unit-info-item"><label>Jenis Audit</label><span>${t.jenisAudit}</span></div>
        <div class="unit-info-item"><label>Cabang</label><span>${t.cabangPlan}${t.cabangArea?' '+areaBadge(t.cabangArea):''}</span></div>
        <div class="unit-info-item"><label>Status</label><span>${taskStatusBadge(t.status)}</span></div>
      </div>`;
    }
    const banner    = document.getElementById('ttpPlanBanner');
    const bannerCnt = document.getElementById('ttpPlanBannerContent');
    if (banner && bannerCnt) {
      bannerCnt.innerHTML =
        '<span><strong>'+(t.noSPT||'—')+'</strong></span>'+
        '<span style="opacity:.6">|</span><span>🏢 '+(t.cabangPlan||'—')+'</span>'+
        '<span style="opacity:.6">|</span><span>📋 '+(t.jenisAudit||'—')+'</span>';
      banner.style.display = '';
    }

    const rec = getTtp(t.planId);
    const _s = (id, val) => { const el = document.getElementById(id); if (el) el.value = val||''; };
    _s('ttp_auditee',        rec.auditee);
    _s('ttp_tglPemeriksaan', rec.tglPemeriksaan || new Date().toISOString().slice(0,10));

    const msgEl = document.getElementById('ttpImportMsg');
    if (msgEl && rec.rows && rec.rows.length) {
      msgEl.innerHTML = `<span style="color:#16a34a">✅ ${rec.rows.length} data berhasil dimuat dari "${rec.fileName||'file HTML'}"</span>`;
    } else if (msgEl) { msgEl.textContent = ''; }

    window._ttpRenderAll();

    document.querySelectorAll('.content-section').forEach(s => s.classList.add('hidden'));
    document.querySelectorAll('.nav-item').forEach(li => li.classList.remove('active'));
    const sec    = document.getElementById('section-pemeriksaan-ttp-gantung');
    const navAudit = document.querySelector('.nav-item[data-section="audit"]');
    if (sec)      sec.classList.remove('hidden');
    if (navAudit) navAudit.classList.add('active');
  };

  // ── Kembali ke Audit ─────────────────────────────────────────
  window._closeTtpGantung = function() {
    _ttpTaskId = null; _ttpPlanId = null;
    const banner = document.getElementById('ttpPlanBanner');
    if (banner) banner.style.display = 'none';
    document.querySelectorAll('.content-section').forEach(s => s.classList.add('hidden'));
    document.querySelectorAll('.nav-item').forEach(li => li.classList.remove('active'));
    const auditSec = document.getElementById('section-audit');
    const auditNav = document.querySelector('.nav-item[data-section="audit"]');
    if (auditSec) auditSec.classList.remove('hidden');
    if (auditNav) auditNav.classList.add('active');
    renderAuditSection();
  };

  // ── Proses file HTML ──────────────────────────────────────────
  function _processTtpFile(file) {
    if (!file) return;
    if (!file.name.match(/\.(htm|html)$/i)) {
      showToast('Hanya file .htm / .html yang diterima.', 'error'); return;
    }
    if (!_ttpPlanId) {
      showToast('Buka pemeriksaan TTP melalui tombol "TTP Gantung" di menu Audit terlebih dahulu.', 'error');
      return;
    }
    const reader = new FileReader();
    reader.onload = function(e) {
      const parsed = _parseTtpHtml(e.target.result);
      const msgEl  = document.getElementById('ttpImportMsg');
      if (!parsed.length) {
        if (msgEl) msgEl.innerHTML = '<span style="color:#dc2626">⚠ Tidak ada data TTP yang terdeteksi. Pastikan file adalah laporan TTP Gantung dari sistem.</span>';
        showToast('Format file tidak dikenali. Pastikan file laporan TTP Gantung yang valid.', 'error');
        return;
      }
      const rec = getTtp(_ttpPlanId);
      // Pertahankan fisik & keterangan manual baris lama jika noTtp sama
      const prev = {};
      (rec.rows||[]).forEach(r => { if(r.noTtp) prev[r.noTtp] = { fisik: r.fisik, keteranganManual: r.keteranganManual }; });
      parsed.forEach(r => {
        if (r.noTtp && prev[r.noTtp]) {
          r.fisik = prev[r.noTtp].fisik;
          r.keteranganManual = prev[r.noTtp].keteranganManual;
        }
      });
      rec.rows = parsed;
      rec.fileName = file.name;
      rec.importedAt = new Date().toISOString();
      saveTtp(rec);
      if (msgEl) msgEl.innerHTML = `<span style="color:#16a34a">✅ ${parsed.length} data berhasil dimuat dari "${file.name}"</span>`;
      window._ttpRenderAll();
      showToast(`${parsed.length} data TTP Gantung berhasil diimport.`, 'success');
    };
    reader.onerror = function() {
      showToast('Gagal membaca file. Coba lagi.', 'error');
    };
    reader.readAsText(file, 'utf-8');
  }

  // ── Daftarkan listener file input & drag-drop langsung ───────
  document.getElementById('ttpBrowseBtn')?.addEventListener('click', function() {
    document.getElementById('ttpFileInput')?.click();
  });
  document.getElementById('ttpFileInput')?.addEventListener('change', function() {
    if (this.files[0]) _processTtpFile(this.files[0]);
    this.value = '';
  });
  (function() {
    const dz = document.getElementById('ttpDropZone');
    if (!dz) return;
    dz.addEventListener('dragover',  e => { e.preventDefault(); dz.style.background = '#d1fae5'; });
    dz.addEventListener('dragleave', () => { dz.style.background = '#f0fdf4'; });
    dz.addEventListener('drop', e => {
      e.preventDefault(); dz.style.background = '#f0fdf4';
      if (e.dataTransfer.files[0]) _processTtpFile(e.dataTransfer.files[0]);
    });
  })();

  /* ── END MODUL TTP GANTUNG ── */

  /* ============================================================
     MODUL LAPOS & INPROSES BPKB
     ============================================================ */
  const LAPOS_BPKB_KEY = 'akta_lapos_bpkb';
  let _laposPlanId = null;
  let _laposTaskId = null;

  function loadLaposAll()  { try { return JSON.parse(localStorage.getItem(LAPOS_BPKB_KEY)) || []; } catch { return []; } }
  function saveLaposAll(d) { localStorage.setItem(LAPOS_BPKB_KEY, JSON.stringify(d)); window.API?.sync(LAPOS_BPKB_KEY, d); }

  function _laposDefault(planId) {
    return {
      planId: String(planId),
      auditee:'', batasanTgl:'', ttBelum:'',
      posSaldoAwalTgl:'', posSaldoAwalFisik:0,
      posPenerimaan:[{ket:'',qty:0},{ket:'',qty:0}],
      posPengeluaran:[{ket:'',qty:0},{ket:'',qty:0}],
      posFisikHitung:0,
      inpNama:'', inpSaldoAwal:0,
      inpPendaftaran:[{ket:'',qty:0},{ket:'',qty:0}],
      inpPenyelesaian:[{ket:'',qty:0},{ket:'',qty:0}],
      inpFisikHitung:0,
      ketSelisih:[{ket:'',qty:0}],
      rincianBulan:[{bulan:'',qty:0}],
      onHand:0, ketOnHand:'', keterangan:'',
    };
  }

  function getLaposData(planId) {
    return loadLaposAll().find(d => String(d.planId) === String(planId)) || _laposDefault(planId);
  }

  function saveLaposData(data) {
    const all = loadLaposAll();
    const idx = all.findIndex(d => String(d.planId) === String(data.planId));
    if (idx >= 0) all[idx] = data; else all.push(data);
    saveLaposAll(all);
  }

  // ── Baca baris dinamis dari DOM ────────────────────────────────
  function _laposReadRows(prefix) {
    const rows = []; let i = 0;
    while (document.getElementById(`${prefix}_ket_${i}`) !== null) {
      rows.push({
        ket: (document.getElementById(`${prefix}_ket_${i}`)?.value || '').trim(),
        qty: parseInt(document.getElementById(`${prefix}_qty_${i}`)?.value || 0) || 0,
      });
      i++;
    }
    return rows;
  }

  function _laposReadBulan(prefix) {
    const rows = []; let i = 0;
    while (document.getElementById(`${prefix}_bln_${i}`) !== null) {
      rows.push({
        bulan: (document.getElementById(`${prefix}_bln_${i}`)?.value || '').trim(),
        qty:   parseInt(document.getElementById(`${prefix}_qty_${i}`)?.value || 0) || 0,
      });
      i++;
    }
    return rows;
  }

  // ── Auto-save: baca DOM → simpan → update rekap ───────────────
  window._laposAutoSave = function() {
    if (!_laposPlanId) return;
    const g  = id => document.getElementById(id);
    const qn = id => parseFloat(g(id)?.value || 0) || 0;
    const qs = id => (g(id)?.value || '').trim();

    const data = {
      planId: String(_laposPlanId),
      auditee: qs('lapos_auditee'), batasanTgl: qs('lapos_batasanTgl'), ttBelum: qs('lapos_ttBelum'),
      posSaldoAwalTgl: qs('lapos_posTgl'), posSaldoAwalFisik: qn('lapos_posSaldo'),
      posPenerimaan:  _laposReadRows('lrv'),
      posPengeluaran: _laposReadRows('lou'),
      posFisikHitung: qn('lapos_posFisik'),
      inpNama: qs('lapos_inpNama'), inpSaldoAwal: qn('lapos_inpSaldo'),
      inpPendaftaran: _laposReadRows('ldn'),
      inpPenyelesaian:_laposReadRows('lsl'),
      inpFisikHitung: qn('lapos_inpFisik'),
      ketSelisih:   _laposReadRows('lks'),
      rincianBulan: _laposReadBulan('lrb'),
      onHand: qn('lapos_onHand'), ketOnHand: qs('lapos_ketOnHand'), keterangan: qs('lapos_ket'),
    };
    saveLaposData(data);
    _laposUpdateCalc(data);
  };

  // ── Update hanya bagian rekap tanpa re-render ─────────────────
  function _laposUpdateCalc(data) {
    const fmtN = n => n === 0 ? '0' : n.toLocaleString('id-ID');
    const nihil = n => n === 0
      ? '<span style="color:#16a34a;font-weight:700">Nihil</span>'
      : `<span style="color:${n>0?'#2563eb':'#dc2626'};font-weight:700">${n > 0 ? '+' : ''}${fmtN(n)}</span>`;

    const sumQty = arr => (arr||[]).reduce((s,r) => s + (parseInt(r.qty)||0), 0);

    // Posisi
    const posRcv  = sumQty(data.posPenerimaan);
    const posOut  = sumQty(data.posPengeluaran);
    const posBuku = (data.posSaldoAwalFisik||0) + posRcv - posOut;
    const posSel  = posBuku - (data.posFisikHitung||0);

    // Inproses
    const inpDft  = sumQty(data.inpPendaftaran);
    const inpSel2 = sumQty(data.inpPenyelesaian);
    const inpBuku = (data.inpSaldoAwal||0) + inpDft - inpSel2;
    const inpSel  = inpBuku - (data.inpFisikHitung||0);

    // On Hand
    const selOH   = (data.onHand||0) - (data.posFisikHitung||0);
    const ketSelTot = sumQty(data.ketSelisih);
    const bulanTot  = sumQty(data.rincianBulan);

    const set = (id, html) => { const el = document.getElementById(id); if (el) el.innerHTML = html; };
    set('lr_posAwal',    fmtN(data.posSaldoAwalFisik||0));
    set('lr_posRcv',     `<span style="color:#16a34a">${fmtN(posRcv)}</span>`);
    set('lr_posOut',     `<span style="color:#dc2626">${fmtN(posOut)}</span>`);
    set('lr_posBuku',    `<strong>${fmtN(posBuku)}</strong>`);
    set('lr_posFisik',   fmtN(data.posFisikHitung||0));
    set('lr_posSel',     nihil(posSel));
    set('lr_inpAwal',    fmtN(data.inpSaldoAwal||0));
    set('lr_inpDft',     `<span style="color:#2563eb">${fmtN(inpDft)}</span>`);
    set('lr_inpSel2',    `<span style="color:#d97706">${fmtN(inpSel2)}</span>`);
    set('lr_inpBuku',    `<strong>${fmtN(inpBuku)}</strong>`);
    set('lr_inpFisik',   fmtN(data.inpFisikHitung||0));
    set('lr_inpSel',     nihil(inpSel));
    set('lr_ketSelTot',  fmtN(ketSelTot));
    set('lr_bulanTot',   fmtN(bulanTot));
    set('lr_ohFisik',    fmtN(data.posFisikHitung||0));
    set('lr_ohOnHand',   fmtN(data.onHand||0));
    set('lr_ohSel',      nihil(selOH));
  }

  // ── Helper: render satu grup baris dinamis ────────────────────
  function _laposRowsHtml(prefix, rows, colLabel) {
    const safeVal = v => String(v||'').replace(/"/g,'&quot;');
    return `
      <table style="width:100%;border-collapse:collapse;margin-bottom:6px">
        <thead><tr>
          <th style="text-align:left;font-size:.71rem;font-weight:700;color:#6b7280;text-transform:uppercase;
                     padding:5px 8px;border-bottom:1px solid #e5e7eb">${colLabel||'KETERANGAN'}</th>
          <th style="width:80px;text-align:center;font-size:.71rem;font-weight:700;color:#6b7280;
                     text-transform:uppercase;padding:5px 8px;border-bottom:1px solid #e5e7eb">QTY</th>
          <th style="width:32px"></th>
        </tr></thead>
        <tbody>
          ${rows.map((r,i) => `
            <tr>
              <td style="padding:3px 6px">
                <input type="text" id="${prefix}_ket_${i}" value="${safeVal(r.ket)}"
                       class="kas-input" style="margin:0;font-size:.82rem" placeholder="Keterangan"
                       oninput="window._laposAutoSave()" />
              </td>
              <td style="padding:3px 6px">
                <input type="number" id="${prefix}_qty_${i}" value="${r.qty||0}" min="0"
                       class="kas-input" style="margin:0;text-align:right;font-size:.82rem"
                       oninput="window._laposAutoSave()" />
              </td>
              <td style="padding:3px 4px;text-align:center">
                <button onclick="window._laposDelRow('${prefix}',${i})"
                        style="background:#fee2e2;border:none;border-radius:4px;padding:3px 7px;
                               cursor:pointer;color:#dc2626;font-size:.78rem">✕</button>
              </td>
            </tr>`).join('')}
        </tbody>
      </table>
      <button onclick="window._laposAddRow('${prefix}')"
              style="background:none;border:1.5px dashed #3b82f6;border-radius:6px;padding:4px 14px;
                     color:#2563eb;font-size:.76rem;cursor:pointer;font-weight:600">+ Tambah Baris</button>`;
  }

  function _laposBulanHtml(prefix, rows) {
    const safeVal = v => String(v||'').replace(/"/g,'&quot;');
    return `
      <table style="width:100%;border-collapse:collapse;margin-bottom:6px">
        <thead><tr>
          <th style="text-align:left;font-size:.71rem;font-weight:700;color:#6b7280;text-transform:uppercase;
                     padding:5px 8px;border-bottom:1px solid #e5e7eb">BULAN</th>
          <th style="width:80px;text-align:center;font-size:.71rem;font-weight:700;color:#6b7280;
                     text-transform:uppercase;padding:5px 8px;border-bottom:1px solid #e5e7eb">QTY (BUKU)</th>
          <th style="width:32px"></th>
        </tr></thead>
        <tbody>
          ${rows.map((r,i) => `
            <tr>
              <td style="padding:3px 6px">
                <input type="text" id="${prefix}_bln_${i}" value="${safeVal(r.bulan)}"
                       class="kas-input" style="margin:0;font-size:.82rem" placeholder="Contoh: Maret 2025"
                       oninput="window._laposAutoSave()" />
              </td>
              <td style="padding:3px 6px">
                <input type="number" id="${prefix}_qty_${i}" value="${r.qty||0}" min="0"
                       class="kas-input" style="margin:0;text-align:right;font-size:.82rem"
                       oninput="window._laposAutoSave()" />
              </td>
              <td style="padding:3px 4px;text-align:center">
                <button onclick="window._laposDelBulan(${i})"
                        style="background:#fee2e2;border:none;border-radius:4px;padding:3px 7px;
                               cursor:pointer;color:#dc2626;font-size:.78rem">✕</button>
              </td>
            </tr>`).join('')}
        </tbody>
      </table>
      <button onclick="window._laposAddBulan()"
              style="background:none;border:1.5px dashed #3b82f6;border-radius:6px;padding:4px 14px;
                     color:#2563eb;font-size:.76rem;cursor:pointer;font-weight:600">+ Tambah Bulan</button>`;
  }

  // ── Row add/delete ─────────────────────────────────────────────
  window._laposAddRow = function(prefix) {
    window._laposAutoSave();
    const d = getLaposData(_laposPlanId);
    const map = {
      lrv: 'posPenerimaan', lou: 'posPengeluaran',
      ldn: 'inpPendaftaran', lsl: 'inpPenyelesaian',
      lks: 'ketSelisih',
    };
    if (map[prefix]) { d[map[prefix]].push({ket:'',qty:0}); saveLaposData(d); renderLaposBpkbSection(); }
  };

  window._laposDelRow = function(prefix, idx) {
    window._laposAutoSave();
    const d = getLaposData(_laposPlanId);
    const map = {
      lrv: 'posPenerimaan', lou: 'posPengeluaran',
      ldn: 'inpPendaftaran', lsl: 'inpPenyelesaian',
      lks: 'ketSelisih',
    };
    if (map[prefix] && d[map[prefix]].length > 1) {
      d[map[prefix]].splice(idx, 1); saveLaposData(d); renderLaposBpkbSection();
    }
  };

  window._laposAddBulan = function() {
    window._laposAutoSave();
    const d = getLaposData(_laposPlanId);
    d.rincianBulan.push({bulan:'',qty:0}); saveLaposData(d); renderLaposBpkbSection();
  };

  window._laposDelBulan = function(idx) {
    window._laposAutoSave();
    const d = getLaposData(_laposPlanId);
    if (d.rincianBulan.length > 1) {
      d.rincianBulan.splice(idx, 1); saveLaposData(d); renderLaposBpkbSection();
    }
  };

  // ── Render form lengkap ke laposBpkbContent ───────────────────
  function renderLaposBpkbSection() {
    const content = document.getElementById('laposBpkbContent');
    if (!content || !_laposPlanId) return;
    const d = getLaposData(_laposPlanId);

    const sumQ = arr => (arr||[]).reduce((s,r)=>s+(parseInt(r.qty)||0),0);
    const posRcv  = sumQ(d.posPenerimaan);
    const posOut  = sumQ(d.posPengeluaran);
    const posBuku = (d.posSaldoAwalFisik||0) + posRcv - posOut;
    const posSel  = posBuku - (d.posFisikHitung||0);
    const inpDft  = sumQ(d.inpPendaftaran);
    const inpSel2 = sumQ(d.inpPenyelesaian);
    const inpBuku = (d.inpSaldoAwal||0) + inpDft - inpSel2;
    const inpSel  = inpBuku - (d.inpFisikHitung||0);
    const selOH   = (d.onHand||0) - (d.posFisikHitung||0);
    const ketSelTot = sumQ(d.ketSelisih);
    const bulanTot  = sumQ(d.rincianBulan);

    const fmtN = n => n===0?'0':Number(n).toLocaleString('id-ID');
    const nihil = n => n===0
      ? '<span style="color:#16a34a;font-weight:700">Nihil</span>'
      : `<span style="color:${n>0?'#2563eb':'#dc2626'};font-weight:700">${n>0?'+':''}${fmtN(n)}</span>`;

    const hdr = (bg,fg,icon,label,extra='') =>
      `<div style="background:${bg};color:${fg};border-radius:8px 8px 0 0;padding:10px 16px;
              display:flex;align-items:center;gap:8px;font-size:.85rem;font-weight:700;
              text-transform:uppercase;letter-spacing:.04em">${icon}${label}${extra}</div>`;

    const card = (hdrHtml, bodyHtml, borderClr='#1e3a5f') =>
      `<div>${hdrHtml}<div style="border:1px solid ${borderClr};border-top:none;
              border-radius:0 0 8px 8px;padding:14px">${bodyHtml}</div></div>`;

    const rekapRow = (label, id, clrClass='', bold=false) =>
      `<div style="display:flex;justify-content:space-between;padding:5px 0;
              border-bottom:1px solid #f1f5f9;font-size:.84rem">
        <span style="${bold?'font-weight:700':''}${clrClass?';color:'+clrClass:''}">${label}</span>
        <span id="${id}" style="${bold?'font-weight:700':''}">0</span>
      </div>`;

    const inpRow = (label, id, defVal=0) =>
      `<div style="margin-top:12px">
        <label style="font-size:.72rem;font-weight:700;text-transform:uppercase;color:#374151;display:block;margin-bottom:4px">${label}</label>
        <input type="number" id="${id}" value="${defVal}" min="0"
               class="kas-input" oninput="window._laposAutoSave()" />
      </div>`;

    // Simpan bar
    const _lapSaved = loadSavedPem().some(s => String(s.planId)===String(_laposPlanId) && s.type==='lapos_bpkb');
    const simpanBar = `
      <div style="margin-top:14px;display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:12px 14px;
           background:${_lapSaved?'#dcfce7':'#f0f9ff'};border:1.5px solid ${_lapSaved?'#86efac':'#bae6fd'};border-radius:8px">
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="${_lapSaved?'#166534':'#0369a1'}" stroke-width="2">
          <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/>
          <polyline points="17 21 17 13 7 13 7 21"/>
        </svg>
        <div style="flex:1;font-size:.82rem;font-weight:700;color:${_lapSaved?'#166534':'#0369a1'}">
          ${_lapSaved ? '✓ Lapos & Inproses BPKB sudah disimpan ke Report Audit' : 'Simpan hasil ke Report Audit'}
        </div>
        <button onclick="window._simpanPemeriksaan('${_laposPlanId}','lapos_bpkb')"
                style="background:${_lapSaved?'#16a34a':'#0369a1'};color:#fff;border:none;border-radius:7px;
                       padding:8px 16px;font-size:.82rem;font-weight:700;cursor:pointer;white-space:nowrap">
          ${_lapSaved ? 'Perbarui ke Report Audit' : 'Simpan ke Report Audit'}
        </button>
      </div>`;

    content.innerHTML = `
      <!-- INFORMASI -->
      ${card(
        hdr('#1e3a5f','#fff','<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="flex-shrink:0"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>','INFORMASI'),
        `<div class="pem-row-2col">
           <div class="field-group">
             <label class="pem-label">AUDITEE</label>
             <input type="text" id="lapos_auditee" value="${(d.auditee||'').replace(/"/g,'&quot;')}"
                    class="kas-input" placeholder="Nama Auditee..." oninput="window._laposAutoSave()" />
           </div>
           <div class="field-group">
             <label class="pem-label">BATASAN TANGGAL <span style="font-size:.7rem;font-weight:400">(Pendaftaran, Penerimaan/Penyelesaian &amp; Pengeluaran)</span></label>
             <input type="date" id="lapos_batasanTgl" value="${d.batasanTgl||''}"
                    class="kas-input" oninput="window._laposAutoSave()" />
           </div>
         </div>
         <div class="field-group" style="margin-top:10px">
           <label class="pem-label">TT BPKB YANG BELUM DIGUNAKAN</label>
           <input type="text" id="lapos_ttBelum" value="${(d.ttBelum||'').replace(/"/g,'&quot;')}"
                  class="kas-input" placeholder="Contoh: BZ 4126 - 4150" oninput="window._laposAutoSave()" />
         </div>`,
      )}

      <!-- TWO-COLUMN GRID: POSISI | INPROSES -->
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:16px">

        <!-- KOLOM KIRI: LAPORAN POSISI BPKB -->
        <div style="display:flex;flex-direction:column;gap:12px">
          ${card(
            hdr('#1e3a5f','#fff','<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>','LAPORAN POSISI BPKB'),
            `<div class="pem-row-2col">
               <div class="field-group">
                 <label class="pem-label">SALDO AWAL — FISIK BPKB (tanggal)</label>
                 <input type="date" id="lapos_posTgl" value="${d.posSaldoAwalTgl||''}"
                        class="kas-input" oninput="window._laposAutoSave()" />
               </div>
               <div class="field-group">
                 <label class="pem-label">SALDO FISIK BPKB (UNIT)</label>
                 <input type="number" id="lapos_posSaldo" value="${d.posSaldoAwalFisik||0}" min="0"
                        class="kas-input" oninput="window._laposAutoSave()" />
               </div>
             </div>`,
          )}

          <!-- PENERIMAAN FISIK -->
          ${card(
            hdr('#16a34a','#fff','<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg>',
              'PENERIMAAN/PENYELESAIAN S/D — <span id="lapos_posBatasDisp" style="font-size:.75rem;opacity:.8;font-weight:400;margin-left:4px">'+(d.batasanTgl||'—')+'</span>'),
            `<div style="font-size:.75rem;font-weight:700;text-transform:uppercase;color:#166534;margin-bottom:8px">PENERIMAAN FISIK BPKB</div>
             ${_laposRowsHtml('lrv', d.posPenerimaan)}`,
            '#16a34a'
          )}

          <!-- PENGELUARAN -->
          ${card(
            hdr('#dc2626','#fff','<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="4 18 15 7 20 12"/></svg>',
              'PENGELUARAN S/D — <span id="lapos_posOutDisp" style="font-size:.75rem;opacity:.8;font-weight:400;margin-left:4px">'+(d.batasanTgl||'—')+'</span>'),
            `<div style="font-size:.75rem;font-weight:700;text-transform:uppercase;color:#991b1b;margin-bottom:8px">PENGELUARAN BPKB (BAST, TT BPKB, DLL)</div>
             ${_laposRowsHtml('lou', d.posPengeluaran)}`,
            '#dc2626'
          )}
        </div>

        <!-- KOLOM KANAN: LAPORAN INPROSES -->
        <div style="display:flex;flex-direction:column;gap:12px">
          ${card(
            hdr('#1e3a5f','#fff','<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>','LAPORAN INPROSES',
              `&nbsp;— <input type="text" id="lapos_inpNama" value="${(d.inpNama||'').replace(/"/g,'&quot;')}"
                 style="background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);border-radius:4px;
                        padding:2px 8px;font-size:.78rem;color:#fff;outline:none;width:120px;font-weight:400;letter-spacing:0"
                 placeholder="Contoh: PKU, MKN..."
                 oninput="window._laposAutoSave()" />`),
            `<div class="pem-row-2col">
               <div class="field-group">
                 <label class="pem-label">SALDO AWAL — INPROSES (tanggal)</label>
                 <div class="kas-input" style="background:#f1f5f9;color:#6b7280;padding:9px 12px;font-size:.83rem">
                   ${d.posSaldoAwalTgl || '—'} (sama dengan saldo awal posisi)
                 </div>
               </div>
               <div class="field-group">
                 <label class="pem-label">SALDO INPROSES — (UNIT)</label>
                 <input type="number" id="lapos_inpSaldo" value="${d.inpSaldoAwal||0}" min="0"
                        class="kas-input" oninput="window._laposAutoSave()" />
               </div>
             </div>`,
          )}

          <!-- PENDAFTARAN -->
          ${card(
            hdr('#2563eb','#fff','<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>',
              'PENDAFTARAN S/D — <span style="font-size:.75rem;opacity:.8;font-weight:400;margin-left:4px">'+(d.batasanTgl||'—')+'</span>'),
            `<div style="font-size:.75rem;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:8px">PENDAFTARAN BPKB</div>
             ${_laposRowsHtml('ldn', d.inpPendaftaran)}`,
            '#2563eb'
          )}

          <!-- PENYELESAIAN INPROSES -->
          ${card(
            hdr('#16a34a','#fff','<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg>',
              'PENERIMAAN/PENYELESAIAN S/D — <span style="font-size:.75rem;opacity:.8;font-weight:400;margin-left:4px">'+(d.batasanTgl||'—')+'</span>'),
            `<div style="font-size:.75rem;font-weight:700;text-transform:uppercase;color:#166534;margin-bottom:8px">PENYELESAIAN INPROSES BPKB</div>
             ${_laposRowsHtml('lsl', d.inpPenyelesaian)}`,
            '#16a34a'
          )}
        </div>
      </div>

      <!-- REKAP & SELISIH -->
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:16px">
        <div>
          ${card(
            hdr('#1e3a5f','#fff','<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/></svg>','REKAP &amp; SELISIH — FISIK BPKB'),
            rekapRow('Saldo Awal Fisik','lr_posAwal') +
            rekapRow('+ Penerimaan Fisik','lr_posRcv') +
            rekapRow('− Pengeluaran Fisik','lr_posOut') +
            rekapRow('Saldo Buku Fisik','lr_posBuku','',true) +
            rekapRow('Fisik BPKB (Hitung)','lr_posFisik') +
            `<div style="display:flex;justify-content:space-between;padding:6px 0;font-size:.84rem;font-weight:700">
               <span>Selisih Fisik</span><span id="lr_posSel">${nihil(posSel)}</span></div>` +
            inpRow('FISIK BPKB (HITUNG)','lapos_posFisik', d.posFisikHitung||0),
          )}
        </div>
        <div>
          ${card(
            hdr('#1e3a5f','#fff','<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/></svg>','REKAP &amp; SELISIH — INPROSES'),
            rekapRow('Saldo Awal Inproses','lr_inpAwal') +
            rekapRow('+ Pendaftaran','lr_inpDft') +
            rekapRow('− Penyelesaian Inproses','lr_inpSel2') +
            rekapRow('Saldo Buku Inproses','lr_inpBuku','',true) +
            rekapRow('Fisik Inproses (Hitung)','lr_inpFisik') +
            `<div style="display:flex;justify-content:space-between;padding:6px 0;font-size:.84rem;font-weight:700">
               <span>Selisih Inproses</span><span id="lr_inpSel">${nihil(inpSel)}</span></div>` +
            inpRow('FISIK INPROSES (HITUNG)','lapos_inpFisik', d.inpFisikHitung||0),
          )}
        </div>
      </div>

      <!-- KETERANGAN GLOBAL -->
      <div class="pem-card" style="margin-top:16px">
        <div class="pem-card-body">
          <label class="pem-label">KETERANGAN <span style="font-weight:400;font-size:.72rem">(opsional)</span></label>
          <textarea id="lapos_ket" class="kas-input pem-textarea" rows="2"
                    placeholder="Keterangan tambahan terkait rekap selisih..."
                    oninput="window._laposAutoSave()">${d.keterangan||''}</textarea>
        </div>
      </div>

      <!-- KET SELISIH INPROSES | RINCIAN PER BULAN -->
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:16px">
        <div>
          ${card(
            hdr('#1e3a5f','#fff','<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>','KETERANGAN SELISIH INPROSES'),
            `${_laposRowsHtml('lks', d.ketSelisih, 'KETERANGAN')}
             <div style="text-align:right;font-size:.82rem;font-weight:700;color:#374151;margin-top:8px;padding-top:6px;border-top:1px solid #e5e7eb">
               Total: <span id="lr_ketSelTot">${fmtN(ketSelTot)}</span> buku
             </div>`,
          )}
        </div>
        <div>
          ${card(
            hdr('#1e3a5f','#fff','<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>','RINCIAN INPROSES PER BULAN'),
            `${_laposBulanHtml('lrb', d.rincianBulan)}
             <div style="text-align:right;font-size:.82rem;font-weight:700;color:#374151;margin-top:8px;padding-top:6px;border-top:1px solid #e5e7eb">
               Total: <span id="lr_bulanTot">${fmtN(bulanTot)}</span> buku
             </div>`,
          )}
        </div>
      </div>

      <!-- ON HAND BPKB VS FISIK BPKB -->
      ${card(
        hdr('#1e3a5f','#fff','<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="3" width="6" height="18" rx="1"/><rect x="9" y="8" width="6" height="13" rx="1"/><rect x="16" y="5" width="6" height="16" rx="1"/></svg>','ON HAND BPKB VS FISIK BPKB'),
        `<div style="max-width:320px">
           <label class="pem-label">ON HAND BPKB (DARI STOCK DI BO)</label>
           <input type="number" id="lapos_onHand" value="${d.onHand||0}" min="0"
                  class="kas-input" oninput="window._laposAutoSave()" />
         </div>
         <div style="margin-top:14px">
           <div style="display:flex;justify-content:space-between;padding:6px 0;font-size:.84rem;border-bottom:1px solid #f1f5f9">
             <span>Fisik BPKB</span><span id="lr_ohFisik">${fmtN(d.posFisikHitung||0)}</span>
           </div>
           <div style="display:flex;justify-content:space-between;padding:6px 0;font-size:.84rem;border-bottom:1px solid #f1f5f9">
             <span>On Hand BPKB</span><span id="lr_ohOnHand">${fmtN(d.onHand||0)}</span>
           </div>
           <div style="display:flex;justify-content:space-between;padding:7px 0;font-size:.84rem;font-weight:700">
             <span>Selisih On Hand vs Fisik</span><span id="lr_ohSel">${nihil(selOH)}</span>
           </div>
         </div>
         <div style="margin-top:12px">
           <label class="pem-label">KETERANGAN SELISIH ON HAND</label>
           <textarea id="lapos_ketOnHand" class="kas-input pem-textarea" rows="2"
                     placeholder="Contoh: Selisih sebanyak 73 merupakan BPKB yang belum di input ke sistem via SP..."
                     oninput="window._laposAutoSave()">${d.ketOnHand||''}</textarea>
         </div>`,
        '#1e3a5f'
      )}

      ${simpanBar}
    `;

    // Inisialisasi nilai rekap dengan data aktual
    _laposUpdateCalc(d);
  }

  // ── Buka section lapos bpkb dari audit bar ─────────────────────
  window._openLaposBpkb = function(taskId) {
    tasks = loadTasks();
    const t = tasks.find(x => String(x.id) === String(taskId));
    if (!t) return;
    _laposTaskId = taskId;
    _laposPlanId = t.planId;

    // Plan banner
    const banner    = document.getElementById('laposBpkbPlanBanner');
    const bannerCnt = document.getElementById('laposBpkbPlanBannerContent');
    if (banner && bannerCnt) {
      bannerCnt.innerHTML =
        '<span><strong>' + (t.noSPT||'—') + '</strong></span>' +
        '<span style="opacity:.6">|</span>' +
        '<span>🏢 ' + (t.cabangPlan||'—') + (t.cabangArea ? ' <span style="font-size:.73rem;background:rgba(255,255,255,.2);border-radius:3px;padding:1px 5px">' + t.cabangArea + '</span>' : '') + '</span>' +
        '<span style="opacity:.6">|</span>' +
        '<span>📋 ' + (t.jenisAudit||'—') + '</span>';
      banner.style.display = '';
    }

    // Navigate ke section
    document.querySelectorAll('.content-section').forEach(s => s.classList.add('hidden'));
    document.querySelectorAll('.nav-item').forEach(li => li.classList.remove('active'));
    const section  = document.getElementById('section-pemeriksaan-lapos-bpkb');
    const auditNav = document.querySelector('.nav-item[data-section="audit"]');
    if (section)   section.classList.remove('hidden');
    if (auditNav)  auditNav.classList.add('active');

    renderLaposBpkbSection();
  };

  // ── Generate & print PDF Laporan Lapos & Inproses BPKB ────────
  window._laposPrintPDF = function(planId) {
    const pid = planId || _laposPlanId;
    if (!pid) return;
    const d = getLaposData(pid);

    // Cari info plan/task
    const allTasks = loadTasks();
    const task = allTasks.find(t => String(t.planId) === String(pid));
    const allPlans = loadPlans ? loadPlans() : [];
    const plan = allPlans.find(p => String(p.id) === String(pid));
    const noSPT   = task?.noSPT   || plan?.noSPT   || '—';
    const cabang  = task?.cabangPlan || plan?.cabangPlan || '—';
    const area    = task?.cabangArea || plan?.cabangArea || '';
    const jenisAudit = task?.jenisAudit || plan?.jenisAudit || '—';

    // Org info
    const org = (() => { try { return JSON.parse(localStorage.getItem('akta_org')) || {}; } catch { return {}; } })();
    const orgName = org.namaOrg || 'AKTA IAT';

    const fmtTgl = s => {
      if (!s) return '—';
      try { return new Date(s).toLocaleDateString('id-ID', { day:'2-digit', month:'long', year:'numeric' }); } catch { return s; }
    };
    const fmtN = n => n === 0 ? '0' : Number(n || 0).toLocaleString('id-ID');
    const now  = new Date().toLocaleDateString('id-ID', { day:'2-digit', month:'long', year:'numeric', hour:'2-digit', minute:'2-digit' });

    const sumQ  = arr => (arr||[]).reduce((s,r) => s+(parseInt(r.qty)||0), 0);
    const posRcv  = sumQ(d.posPenerimaan);
    const posOut  = sumQ(d.posPengeluaran);
    const posBuku = (d.posSaldoAwalFisik||0) + posRcv - posOut;
    const posSel  = posBuku - (d.posFisikHitung||0);
    const inpDft  = sumQ(d.inpPendaftaran);
    const inpSel2 = sumQ(d.inpPenyelesaian);
    const inpBuku = (d.inpSaldoAwal||0) + inpDft - inpSel2;
    const inpSel  = inpBuku - (d.inpFisikHitung||0);
    const selOH   = (d.onHand||0) - (d.posFisikHitung||0);
    const ketSelTot = sumQ(d.ketSelisih);
    const bulanTot  = sumQ(d.rincianBulan);

    const selColor = n => n === 0 ? '#16a34a' : (n > 0 ? '#2563eb' : '#dc2626');
    const selText  = n => n === 0 ? '<strong style="color:#16a34a">NIHIL</strong>'
      : `<strong style="color:${selColor(n)}">${n > 0 ? '+' : ''}${fmtN(n)}</strong>`;

    const rowsHtml = (rows, emptyMsg) => {
      if (!rows || !rows.length) return `<tr><td colspan="2" style="text-align:center;color:#9ca3af;font-style:italic">${emptyMsg||'—'}</td></tr>`;
      return rows.map((r,i) => `
        <tr style="background:${i%2===0?'#fff':'#f8fafc'}">
          <td>${r.ket || '—'}</td>
          <td class="num" style="font-weight:700">${fmtN(r.qty||0)}</td>
        </tr>`).join('');
    };

    const bulanRowsHtml = (rows) => {
      if (!rows || !rows.length) return `<tr><td colspan="2" style="text-align:center;color:#9ca3af;font-style:italic">—</td></tr>`;
      return rows.map((r,i) => `
        <tr style="background:${i%2===0?'#fff':'#f8fafc'}">
          <td>${r.bulan || '—'}</td>
          <td class="num" style="font-weight:700">${fmtN(r.qty||0)}</td>
        </tr>`).join('');
    };

    const html = `<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"/>
<title>Lapos & Inproses BPKB — ${noSPT}</title>
<style>
  *{box-sizing:border-box;margin:0;padding:0}
  body{font-family:'Segoe UI',Arial,sans-serif;font-size:11px;color:#1a1a1a;background:#fff;padding:20px 24px}
  @page{size:A4 portrait;margin:12mm 10mm}
  @media print{body{padding:0}.no-print{display:none!important}button{display:none!important}}

  /* ── Header ── */
  .doc-header{border-bottom:3px solid #1e3a5f;padding-bottom:10px;margin-bottom:16px;display:flex;justify-content:space-between;align-items:flex-end}
  .doc-header .org{font-size:15px;font-weight:800;color:#1e3a5f}
  .doc-header .subtitle{font-size:9px;color:#6b7280;margin-top:3px}
  .doc-header .title-block{text-align:right}
  .doc-header .doc-title{font-size:14px;font-weight:800;color:#1e3a5f}
  .doc-header .doc-meta{font-size:9px;color:#6b7280;margin-top:2px}

  /* ── Plan info grid ── */
  .plan-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;background:#f0f4ff;
             border:1px solid #c7d7ff;border-radius:6px;padding:10px 12px;margin-bottom:14px}
  .plan-item label{font-size:8.5px;text-transform:uppercase;letter-spacing:.05em;color:#6b7280;display:block;margin-bottom:2px}
  .plan-item span{font-weight:700;font-size:11px;color:#1e3a5f}

  /* ── Info strip ── */
  .info-strip{background:#f8fafc;border:1px solid #e5e7eb;border-radius:6px;padding:9px 12px;
              display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:14px}
  .info-strip .lbl{font-size:8.5px;text-transform:uppercase;letter-spacing:.05em;color:#9ca3af;margin-bottom:2px}
  .info-strip .val{font-weight:600;font-size:10.5px}

  /* ── Two-column layout ── */
  .two-col{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px}

  /* ── Section header ── */
  .sec-hdr{color:#fff;padding:6px 10px;font-size:10px;font-weight:700;text-transform:uppercase;
           letter-spacing:.04em;border-radius:4px 4px 0 0;margin-bottom:0;display:flex;align-items:center;gap:6px}
  .sec-body{border:1px solid;border-top:none;border-radius:0 0 4px 4px;padding:10px;margin-bottom:10px}
  .sec-hdr.navy{background:#1e3a5f}.sec-body.navy{border-color:#1e3a5f}
  .sec-hdr.green{background:#16a34a}.sec-body.green{border-color:#16a34a}
  .sec-hdr.red  {background:#dc2626}.sec-body.red  {border-color:#dc2626}
  .sec-hdr.blue {background:#2563eb}.sec-body.blue {border-color:#2563eb}

  /* ── Sub label ── */
  .sub-lbl{font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;margin-bottom:6px}

  /* ── Saldo row ── */
  .saldo-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px}
  .saldo-item .lbl{font-size:8.5px;text-transform:uppercase;color:#6b7280;margin-bottom:3px}
  .saldo-item .val{font-weight:700;font-size:13px;color:#1e3a5f;
                   border:1px solid #c7d7ff;background:#f0f4ff;border-radius:4px;padding:4px 8px;text-align:center}

  /* ── Tables ── */
  table{width:100%;border-collapse:collapse;font-size:10px;margin-bottom:4px}
  thead tr{background:#374151;color:#fff}
  th{padding:5px 8px;text-align:left;font-size:9.5px;font-weight:700}
  td{padding:4px 8px;border-bottom:1px solid #f1f5f9;font-size:10px}
  td.num{text-align:right;font-variant-numeric:tabular-nums}
  .tbl-total{display:flex;justify-content:flex-end;font-size:10px;font-weight:700;
             border-top:2px solid #374151;padding-top:4px;margin-top:2px}

  /* ── Rekap table ── */
  .rekap-tbl{width:100%;border-collapse:collapse;margin-bottom:4px}
  .rekap-tbl td{padding:4px 6px;border-bottom:1px solid #f1f5f9;font-size:10px;vertical-align:middle}
  .rekap-tbl td:last-child{text-align:right;font-weight:600;width:80px}
  .rekap-tbl tr.bold td{font-weight:700;border-top:2px solid #1e3a5f;background:#f0f4ff}
  .rekap-tbl tr.selisih td{background:#f0fdf4;font-weight:700;font-size:11px}
  .rekap-tbl tr.selisih.err td{background:#fff1f2}

  /* ── On hand section ── */
  .oh-grid{display:grid;grid-template-columns:1fr 2fr;gap:12px;align-items:start}
  .oh-summary{border:1px solid #e5e7eb;border-radius:6px;overflow:hidden}
  .oh-summary .row{display:flex;justify-content:space-between;padding:6px 10px;
                   border-bottom:1px solid #f1f5f9;font-size:10.5px}
  .oh-summary .row:last-child{border-bottom:none;font-weight:700;font-size:11px;background:#f8fafc}

  /* ── Signature ── */
  .ttd-section{display:grid;grid-template-columns:1fr 1fr 1fr;gap:30px;margin-top:28px;padding-top:14px;border-top:1px solid #e5e7eb}
  .ttd-box{text-align:center;font-size:10px}
  .ttd-box .role{color:#6b7280;font-size:9px;margin-bottom:36px}
  .ttd-box .name{font-weight:700;border-top:1px solid #374151;padding-top:4px;margin-top:4px}

  /* ── Footer ── */
  .doc-footer{margin-top:16px;border-top:1px solid #e5e7eb;padding-top:6px;
              font-size:8.5px;color:#9ca3af;display:flex;justify-content:space-between}

  /* ── Print button ── */
  .print-btn{display:flex;gap:8px;margin-bottom:14px}
  .print-btn button{padding:7px 18px;border:none;border-radius:6px;cursor:pointer;font-weight:700;font-size:12px}
</style>
</head><body>

<!-- Print Button (hidden on print) -->
<div class="print-btn no-print">
  <button onclick="window.print()" style="background:#1e3a5f;color:#fff">🖨️ Print / Simpan PDF</button>
  <button onclick="window.close()" style="background:#f1f5f9;color:#374151">✕ Tutup</button>
</div>

<!-- Document Header -->
<div class="doc-header">
  <div>
    <div class="org">${orgName}</div>
    <div class="subtitle">Sistem Audit Internal — AKTA IAT</div>
  </div>
  <div class="title-block">
    <div class="doc-title">BERITA ACARA PEMERIKSAAN</div>
    <div class="doc-meta" style="font-weight:700;font-size:11px;color:#1e3a5f">LAPORAN POSISI &amp; INPROSES BPKB</div>
    <div class="doc-meta">Dicetak: ${now}</div>
  </div>
</div>

<!-- Plan Info -->
<div class="plan-grid">
  <div class="plan-item"><label>No. SPT</label><span>${noSPT}</span></div>
  <div class="plan-item"><label>Jenis Audit</label><span>${jenisAudit}</span></div>
  <div class="plan-item"><label>Cabang</label><span>${cabang}${area ? ' · ' + area : ''}</span></div>
  <div class="plan-item"><label>Auditee</label><span>${d.auditee || '—'}</span></div>
</div>

<!-- Informasi -->
<div class="info-strip">
  <div>
    <div class="lbl">Batasan Tanggal</div>
    <div class="val">${fmtTgl(d.batasanTgl)}</div>
  </div>
  <div>
    <div class="lbl">TT BPKB Belum Digunakan</div>
    <div class="val">${d.ttBelum || '—'}</div>
  </div>
  <div>
    <div class="lbl">Nama Inproses</div>
    <div class="val">${d.inpNama || '—'}</div>
  </div>
</div>

<!-- Dua Kolom: Posisi BPKB | Inproses BPKB -->
<div class="two-col">

  <!-- KOLOM KIRI: POSISI BPKB -->
  <div>
    <div class="sec-hdr navy">
      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
        <path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/>
      </svg>
      LAPORAN POSISI BPKB
    </div>
    <div class="sec-body navy">
      <div class="saldo-grid" style="margin-bottom:10px">
        <div class="saldo-item">
          <div class="lbl">Saldo Awal Fisik — Tanggal</div>
          <div class="val" style="font-size:11px">${fmtTgl(d.posSaldoAwalTgl)}</div>
        </div>
        <div class="saldo-item">
          <div class="lbl">Saldo Fisik BPKB (Unit)</div>
          <div class="val">${fmtN(d.posSaldoAwalFisik||0)}</div>
        </div>
      </div>

      <div class="sub-lbl" style="color:#16a34a">▲ PENERIMAAN FISIK BPKB (S/D ${fmtTgl(d.batasanTgl)})</div>
      <table>
        <thead><tr><th>Keterangan</th><th style="text-align:right">Qty</th></tr></thead>
        <tbody>${rowsHtml(d.posPenerimaan,'Tidak ada penerimaan')}</tbody>
        <tfoot><tr style="background:#f0fdf4">
          <td style="font-weight:700;font-size:10px;color:#16a34a">Total Penerimaan</td>
          <td class="num" style="font-weight:800;color:#16a34a">${fmtN(posRcv)}</td>
        </tr></tfoot>
      </table>

      <div class="sub-lbl" style="color:#dc2626;margin-top:8px">▼ PENGELUARAN BPKB (S/D ${fmtTgl(d.batasanTgl)})</div>
      <table>
        <thead><tr><th>Keterangan</th><th style="text-align:right">Qty</th></tr></thead>
        <tbody>${rowsHtml(d.posPengeluaran,'Tidak ada pengeluaran')}</tbody>
        <tfoot><tr style="background:#fff1f2">
          <td style="font-weight:700;font-size:10px;color:#dc2626">Total Pengeluaran</td>
          <td class="num" style="font-weight:800;color:#dc2626">${fmtN(posOut)}</td>
        </tr></tfoot>
      </table>
    </div>
  </div>

  <!-- KOLOM KANAN: INPROSES BPKB -->
  <div>
    <div class="sec-hdr navy">
      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
        <path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/>
      </svg>
      LAPORAN INPROSES${d.inpNama ? ' — ' + d.inpNama : ''}
    </div>
    <div class="sec-body navy">
      <div class="saldo-grid" style="margin-bottom:10px">
        <div class="saldo-item">
          <div class="lbl">Saldo Awal Inproses — Tanggal</div>
          <div class="val" style="font-size:11px">${fmtTgl(d.posSaldoAwalTgl)}</div>
        </div>
        <div class="saldo-item">
          <div class="lbl">Saldo Inproses (Unit)</div>
          <div class="val">${fmtN(d.inpSaldoAwal||0)}</div>
        </div>
      </div>

      <div class="sub-lbl" style="color:#2563eb">📝 PENDAFTARAN BPKB (S/D ${fmtTgl(d.batasanTgl)})</div>
      <table>
        <thead><tr><th>Keterangan</th><th style="text-align:right">Qty</th></tr></thead>
        <tbody>${rowsHtml(d.inpPendaftaran,'Tidak ada pendaftaran')}</tbody>
        <tfoot><tr style="background:#eff6ff">
          <td style="font-weight:700;font-size:10px;color:#2563eb">Total Pendaftaran</td>
          <td class="num" style="font-weight:800;color:#2563eb">${fmtN(inpDft)}</td>
        </tr></tfoot>
      </table>

      <div class="sub-lbl" style="color:#16a34a;margin-top:8px">✓ PENYELESAIAN INPROSES BPKB (S/D ${fmtTgl(d.batasanTgl)})</div>
      <table>
        <thead><tr><th>Keterangan</th><th style="text-align:right">Qty</th></tr></thead>
        <tbody>${rowsHtml(d.inpPenyelesaian,'Tidak ada penyelesaian')}</tbody>
        <tfoot><tr style="background:#f0fdf4">
          <td style="font-weight:700;font-size:10px;color:#16a34a">Total Penyelesaian</td>
          <td class="num" style="font-weight:800;color:#16a34a">${fmtN(inpSel2)}</td>
        </tr></tfoot>
      </table>
    </div>
  </div>
</div>

<!-- REKAP & SELISIH -->
<div class="two-col">
  <!-- Rekap Posisi -->
  <div>
    <div class="sec-hdr navy">
      <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
        <polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/>
      </svg>
      REKAP &amp; SELISIH — FISIK BPKB
    </div>
    <div class="sec-body navy" style="padding:0">
      <table class="rekap-tbl">
        <tbody>
          <tr><td>Saldo Awal Fisik</td><td>${fmtN(d.posSaldoAwalFisik||0)}</td></tr>
          <tr><td style="color:#16a34a">+ Penerimaan Fisik</td><td style="color:#16a34a">${fmtN(posRcv)}</td></tr>
          <tr><td style="color:#dc2626">− Pengeluaran Fisik</td><td style="color:#dc2626">${fmtN(posOut)}</td></tr>
          <tr class="bold"><td>Saldo Buku Fisik</td><td>${fmtN(posBuku)}</td></tr>
          <tr><td>Fisik BPKB (Hitung)</td><td>${fmtN(d.posFisikHitung||0)}</td></tr>
          <tr class="selisih ${posSel!==0?'err':''}">
            <td>Selisih Fisik</td>
            <td>${selText(posSel)}</td>
          </tr>
        </tbody>
      </table>
    </div>
  </div>
  <!-- Rekap Inproses -->
  <div>
    <div class="sec-hdr navy">
      <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
        <polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/>
      </svg>
      REKAP &amp; SELISIH — INPROSES${d.inpNama ? ' ' + d.inpNama : ''}
    </div>
    <div class="sec-body navy" style="padding:0">
      <table class="rekap-tbl">
        <tbody>
          <tr><td>Saldo Awal Inproses</td><td>${fmtN(d.inpSaldoAwal||0)}</td></tr>
          <tr><td style="color:#2563eb">+ Pendaftaran</td><td style="color:#2563eb">${fmtN(inpDft)}</td></tr>
          <tr><td style="color:#d97706">− Penyelesaian Inproses</td><td style="color:#d97706">${fmtN(inpSel2)}</td></tr>
          <tr class="bold"><td>Saldo Buku Inproses</td><td>${fmtN(inpBuku)}</td></tr>
          <tr><td>Fisik Inproses (Hitung)</td><td>${fmtN(d.inpFisikHitung||0)}</td></tr>
          <tr class="selisih ${inpSel!==0?'err':''}">
            <td>Selisih Inproses</td>
            <td>${selText(inpSel)}</td>
          </tr>
        </tbody>
      </table>
    </div>
  </div>
</div>

${d.keterangan ? `<div style="background:#fffbeb;border:1px solid #fcd34d;border-radius:6px;padding:8px 12px;margin-bottom:14px;font-size:10px">
  <strong style="color:#92400e">Keterangan:</strong> ${d.keterangan}</div>` : ''}

<!-- Ket Selisih Inproses | Rincian Per Bulan -->
<div class="two-col">
  <div>
    <div class="sec-hdr navy">📋 KETERANGAN SELISIH INPROSES</div>
    <div class="sec-body navy">
      <table>
        <thead><tr><th>Keterangan</th><th style="text-align:right">QTY (Buku)</th></tr></thead>
        <tbody>${rowsHtml(d.ketSelisih,'Tidak ada keterangan selisih')}</tbody>
      </table>
      <div class="tbl-total">Total: <strong style="margin-left:6px">${fmtN(ketSelTot)}</strong> buku</div>
    </div>
  </div>
  <div>
    <div class="sec-hdr navy">📅 RINCIAN INPROSES PER BULAN</div>
    <div class="sec-body navy">
      <table>
        <thead><tr><th>Bulan</th><th style="text-align:right">QTY (Buku)</th></tr></thead>
        <tbody>${bulanRowsHtml(d.rincianBulan)}</tbody>
      </table>
      <div class="tbl-total">Total: <strong style="margin-left:6px">${fmtN(bulanTot)}</strong> buku</div>
    </div>
  </div>
</div>

<!-- On Hand BPKB vs Fisik BPKB -->
<div class="sec-hdr navy" style="margin-bottom:0">
  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
    <rect x="2" y="3" width="6" height="18" rx="1"/><rect x="9" y="8" width="6" height="13" rx="1"/>
    <rect x="16" y="5" width="6" height="16" rx="1"/>
  </svg>
  ON HAND BPKB VS FISIK BPKB
</div>
<div class="sec-body navy" style="margin-bottom:14px">
  <div class="oh-grid">
    <div>
      <div style="font-size:9px;text-transform:uppercase;color:#6b7280;margin-bottom:4px">ON HAND BPKB (dari stock di BO)</div>
      <div style="font-size:22px;font-weight:800;color:#1e3a5f;border:2px solid #c7d7ff;
                  background:#f0f4ff;border-radius:6px;padding:8px 14px;text-align:center">${fmtN(d.onHand||0)}</div>
    </div>
    <div>
      <div class="oh-summary">
        <div class="row"><span>Fisik BPKB</span><strong>${fmtN(d.posFisikHitung||0)}</strong></div>
        <div class="row"><span>On Hand BPKB</span><strong>${fmtN(d.onHand||0)}</strong></div>
        <div class="row" style="${selOH!==0?'background:#fff1f2':'background:#f0fdf4'}">
          <span><strong>Selisih On Hand vs Fisik</strong></span>
          <span>${selText(selOH)}</span>
        </div>
      </div>
      ${d.ketOnHand ? `<div style="margin-top:8px;font-size:9.5px;background:#fafafa;border:1px solid #e5e7eb;
              border-radius:4px;padding:7px 10px;color:#374151">
        <strong>Keterangan:</strong> ${d.ketOnHand}</div>` : ''}
    </div>
  </div>
</div>

<!-- Tanda Tangan -->
<div class="ttd-section">
  <div class="ttd-box">
    <div class="role">Auditor</div>
    <div class="name">${task?.assignedTo ? getUserDisplay(task.assignedTo) : '................................'}</div>
  </div>
  <div class="ttd-box">
    <div class="role">Kepala Tim Audit</div>
    <div class="name">................................</div>
  </div>
  <div class="ttd-box">
    <div class="role">Auditee / Penanggung Jawab</div>
    <div class="name">${d.auditee || '................................'}</div>
  </div>
</div>

<!-- Footer -->
<div class="doc-footer">
  <span>${orgName} — AKTA IAT Audit System</span>
  <span>No. SPT: ${noSPT} · ${cabang}${area ? ' · ' + area : ''} · Dicetak: ${now}</span>
</div>

<script>window.onload=function(){window.print();};<\/script>
</body></html>`;

    const win = window.open('', '_blank', 'width=900,height=700,scrollbars=yes');
    if (win) { win.document.write(html); win.document.close(); }
    else showToast('Popup diblokir browser. Izinkan popup untuk melihat PDF.', 'error');
  };

  // ── Reset form ────────────────────────────────────────────────
  window._laposReset = function() {
    if (!_laposPlanId) return;
    if (!confirm('Reset semua data Lapos & Inproses BPKB untuk plan ini?')) return;
    const all = loadLaposAll().filter(d => String(d.planId) !== String(_laposPlanId));
    saveLaposAll(all);
    renderLaposBpkbSection();
  };

  /* ── END MODUL LAPOS & INPROSES BPKB ── */

  /* ============================================================
     MODUL KWITANSI GANTUNG
     ============================================================ */
  const KWT_DB_KEY   = 'akta_kwt_db';
  const KWT_SCAN_KEY = 'akta_kwt_scan';
  let _kwtPlanId  = null;
  let _kwtTaskId  = null;

  function loadKwtDb()    { try { return JSON.parse(localStorage.getItem(KWT_DB_KEY))   || []; } catch { return []; } }
  function saveKwtDb(d)   { localStorage.setItem(KWT_DB_KEY,   JSON.stringify(d)); window.API?.sync(KWT_DB_KEY,   d); }
  function loadKwtScan()  { try { return JSON.parse(localStorage.getItem(KWT_SCAN_KEY)) || []; } catch { return []; } }
  function saveKwtScan(d) { localStorage.setItem(KWT_SCAN_KEY, JSON.stringify(d)); window.API?.sync(KWT_SCAN_KEY, d); }

  // ── Helper get/set audit data per row ─────────────────────────
  function _kwtGetRow(planId, noKwt) {
    return loadKwtScan().find(r => String(r.planId) === String(planId) && r.noKwt === noKwt)
      || { planId: String(planId), noKwt, fisik: false, keterangan: '' };
  }
  function _kwtSetRow(planId, noKwt, patch) {
    const all = loadKwtScan();
    const idx = all.findIndex(r => String(r.planId) === String(planId) && r.noKwt === noKwt);
    const cur = idx >= 0 ? all[idx] : { planId: String(planId), noKwt, fisik: false, keterangan: '' };
    const updated = { ...cur, ...patch };
    if (idx >= 0) all[idx] = updated; else all.push(updated);
    saveKwtScan(all);
  }

  // ── Parse Excel Kwitansi Gantung (robust) ───────────────────────
  function _parseKwtExcel(data) {
    const wb   = XLSX.read(data, { type:'array', cellDates:true });
    const ws   = wb.Sheets[wb.SheetNames[0]];
    const rows = XLSX.utils.sheet_to_json(ws, { header:1, defval:'' });
    if (!rows.length) return [];

    // Leasing names yang dikenal (untuk deteksi sub-header grup)
    const LEASING_LIST = ['ADIRA','FIF','WOM','BAF','ACC','OTO','MCF','BCA FINANCE',
      'MANDIRI TUNAS','CLIPAN','BFI','INDOMOBIL','SPEKTRA','SUMMIT','KREDIT PLUS','KREDITPLUS','MITRA PINASTHIKA'];

    // ── STEP 1: Temukan baris header kolom ────────────────────────
    // Header harus mengandung kolom KWITANSI DAN minimal 2 kolom lain
    let headerIdx = -1;
    for (let i = 0; i < Math.min(25, rows.length); i++) {
      const cells = rows[i].map(c => String(c||'').trim().toUpperCase());
      if (cells.filter(c => c).length < 3) continue; // skip baris dengan < 3 kolom isi

      const hasKwt      = cells.some(c => c.includes('KWITANSI') && c.length <= 25);
      const hasDate     = cells.some(c => (c.includes('TGL') || c.includes('TANGGAL')) && c.length <= 25);
      const hasCustomer = cells.some(c => c.includes('CUSTOMER') || c.includes('NASABAH'));
      const hasNilai    = cells.some(c => c.includes('NILAI') || c.includes('AMOUNT'));
      const hasFaktur   = cells.some(c => c.includes('FAKTUR'));

      // Header valid: harus ada kolom KWITANSI + minimal 2 dari yang lain
      const extra = [hasDate, hasCustomer, hasNilai, hasFaktur].filter(Boolean).length;
      if (hasKwt && extra >= 2) { headerIdx = i; break; }
    }

    if (headerIdx < 0) return []; // tidak bisa deteksi header

    // ── STEP 2: Peta kolom dari baris header ─────────────────────
    const headers = rows[headerIdx].map(c => String(c||'').trim().toUpperCase());
    // Log header untuk debug (toast singkat)
    // console.log('KWT headers:', headers);

    // NO. KWITANSI — cari dengan exact match prioritas, KWITANSI mengandung "KWIT" jadi awas
    const iNoKwt = (() => {
      for (const pat of ['NO. KWITANSI','NO KWITANSI','NO.KWITANSI','NOMOR KWITANSI','NO KWT']) {
        const idx = headers.findIndex(h => h === pat || h.startsWith(pat));
        if (idx >= 0) return idx;
      }
      // Fallback: KWITANSI tapi bukan NILAI KWITANSI
      const idx = headers.findIndex(h => h.includes('KWITANSI') && !h.startsWith('NILAI') && !h.startsWith('TAGIHAN'));
      return idx;
    })();

    const iTgl = (() => {
      for (const pat of ['TGL. KWITANSI','TGL KWITANSI','TANGGAL KWITANSI','TGL.KWITANSI','TGL. KWT','TANGGAL']) {
        const idx = headers.findIndex(h => h === pat || h.startsWith(pat));
        if (idx >= 0) return idx;
      }
      return headers.findIndex(h => (h.startsWith('TGL') || h.startsWith('TANGGAL')) && h.length <= 25);
    })();

    // NAMA CUSTOMER — coba berbagai variasi nama kolom
    const iCustomer = (() => {
      for (const pat of ['NAMA CUSTOMER','CUSTOMER','NAMA NASABAH','NASABAH','NAMA DEBITUR','DEBITUR']) {
        const idx = headers.findIndex(h => h === pat || h.startsWith(pat));
        if (idx >= 0) return idx;
      }
      // Fallback: kolom NAMA yang pendek dan bukan LEASING/BANK
      return headers.findIndex(h =>
        h.startsWith('NAMA') && h.length <= 30 && !h.includes('BANK') && !h.includes('LEASING')
      );
    })();

    // NO. AR
    const iNoAR = (() => {
      for (const pat of ['NO. AR','NO AR','NO.AR','NOAR','NO. A/R','NO A/R']) {
        const idx = headers.findIndex(h => h === pat || h.startsWith(pat));
        if (idx >= 0) return idx;
      }
      return headers.findIndex(h => (h.endsWith('AR') || h.endsWith(' AR')) && h.length <= 10);
    })();

    // NO. FAKTUR — prioritas exact match
    const iNoFaktur = (() => {
      for (const pat of ['NO. FAKTUR','NO FAKTUR','NO.FAKTUR','NOMOR FAKTUR','NO. INVOICE','NO INVOICE']) {
        const idx = headers.findIndex(h => h === pat || h.startsWith(pat));
        if (idx >= 0) return idx;
      }
      return headers.findIndex(h => h.includes('FAKTUR') || h.includes('INVOICE'));
    })();

    // NILAI — CATATAN: "NILAI KWITANSI (RP)" mengandung "KWIT" jadi jangan difilter!
    // Cukup cari kolom yang mengandung NILAI atau AMOUNT, prioritaskan yang ada angka/RP
    const iNilai = (() => {
      for (const pat of ['NILAI KWITANSI (RP)','NILAI KWITANSI','NILAI (RP)','NILAI','AMOUNT','TAGIHAN','JUMLAH']) {
        const idx = headers.findIndex(h => h === pat || h.startsWith(pat));
        if (idx >= 0) return idx;
      }
      return headers.findIndex(h => h.includes('NILAI') || h.includes('AMOUNT') || h.includes('TAGIHAN'));
    })();

    // DIFF / HARI GANTUNG — jumlah hari sejak kwitansi
    const iDiff = (() => {
      for (const pat of ['DIFF','HARI GANTUNG','HARI','SELISIH HARI','AGING','UMUR','LAMA','BEREDAR']) {
        const idx = headers.findIndex(h => h === pat || h.startsWith(pat + ' '));
        if (idx >= 0) return idx;
      }
      return -1;
    })();

    // JUMLAH — kolom alternatif untuk nilai (kadang diisi, kadang sama dengan NILAI KWITANSI)
    const iJumlah = (() => {
      // Jangan ambil kolom yang sudah dipakai iNilai
      const idx = headers.findIndex((h, i) => i !== iNilai && (h === 'JUMLAH' || h.startsWith('JUMLAH') || h === 'TOTAL' || h.startsWith('TOTAL ')));
      return idx;
    })();

    const iLeasing = headers.findIndex(h =>
      h.includes('LEASING') || h.includes('FINANCE') || h.includes('PEMBIAYAAN') || h.includes('LEMBAGA'));

    if (iNoKwt < 0) return []; // kolom NO. KWITANSI wajib ada

    // ── Fungsi parse tanggal ──────────────────────────────────────
    const parseDate = (raw) => {
      if (!raw) return null;
      try {
        if (raw instanceof Date) return isNaN(raw) ? null : raw;
        const s = String(raw).trim();
        if (!s) return null;
        // DD/MM/YYYY atau DD-MM-YYYY
        const m1 = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
        if (m1) return new Date(parseInt(m1[3]), parseInt(m1[2])-1, parseInt(m1[1]));
        // YYYY-MM-DD
        const m2 = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
        if (m2) return new Date(parseInt(m2[1]), parseInt(m2[2])-1, parseInt(m2[3]));
        return null;
      } catch { return null; }
    };

    const fmtDate = (d) => {
      if (!d || isNaN(d)) return '';
      const dd  = String(d.getDate()).padStart(2,'0');
      const mm  = String(d.getMonth()+1).padStart(2,'0');
      const yy  = d.getFullYear();
      return `${dd}/${mm}/${yy}`;
    };

    // Fungsi parse nilai uang — handle format Indonesia (1.234.000) & Amerika (1,234,000)
    const parseNilai = (raw) => {
      if (raw === null || raw === undefined || raw === '') return 0;
      if (typeof raw === 'number') return Math.round(raw); // angka langsung dari XLSX
      const s = String(raw).trim().replace(/\s/g,'').replace(/^Rp\.?\s*/i,'');
      if (!s) return 0;
      const hasDot   = s.includes('.');
      const hasComma = s.includes(',');
      let cleaned = s;
      if (hasDot && hasComma) {
        // Ada keduanya: yang terakhir adalah desimal
        const lDot = s.lastIndexOf('.'), lComma = s.lastIndexOf(',');
        if (lDot > lComma) cleaned = s.replace(/,/g,'');          // 1,234.56
        else               cleaned = s.replace(/\./g,'').replace(',','.');  // 1.234,56
      } else if (hasComma) {
        // Hanya koma: jika ada ≥2 koma ATAU koma diikuti tepat 3 digit di akhir → thousands
        const parts = s.split(',');
        if (parts.length > 2 || (parts.length === 2 && parts[1].length === 3)) {
          cleaned = s.replace(/,/g,'');   // 1,234,000 → 1234000
        } else {
          cleaned = s.replace(',','.');   // 1234,5 → 1234.5
        }
      } else if (hasDot) {
        // Hanya titik: jika ada ≥2 titik ATAU titik diikuti tepat 3 digit di akhir → thousands
        const parts = s.split('.');
        if (parts.length > 2 || (parts.length === 2 && parts[1].length === 3)) {
          cleaned = s.replace(/\./g,'');  // 1.234.000 → 1234000
        }
        // else biarkan: 1234.5 → desimal biasa
      }
      cleaned = cleaned.replace(/[^0-9.]/g,'');
      return parseFloat(cleaned) || 0;
    };

    // ── STEP 3: Iterasi baris data dengan deteksi sub-header grup ─
    const today  = new Date();
    const result = [];
    let curLeasing = '';

    for (let i = headerIdx + 1; i < rows.length; i++) {
      const r = rows[i];
      if (!r) continue;

      const cells      = r.map(c => String(c||'').trim());
      const nonEmpty   = cells.filter(c => c !== '');
      if (nonEmpty.length === 0) continue; // baris kosong total

      const cellsUp    = cells.map(c => c.toUpperCase());
      const allUp      = cellsUp.join('|');

      // ── Deteksi baris sub-header LEASING (grup) ───────────────
      // Baris ini: ≤3 sel berisi nilai, dan salah satunya adalah nama leasing
      if (nonEmpty.length <= 3) {
        const joined = nonEmpty.map(c => c.toUpperCase()).join(' ');
        const found  = LEASING_LIST.find(l => joined.includes(l));
        if (found) { curLeasing = found; continue; }
        // Coba juga deteksi dari baris yang hanya berisi satu teks yang merupakan nama leasing
        if (nonEmpty.length === 1) {
          const only = nonEmpty[0].toUpperCase();
          const exactFound = LEASING_LIST.find(l => only === l || only.startsWith(l + ' ') || only.startsWith(l + '('));
          if (exactFound) { curLeasing = exactFound; continue; }
        }
      }

      // ── Skip baris total/sub-total/judul ─────────────────────
      if (allUp.includes('SUB TOTAL') || allUp.includes('GRAND TOTAL') ||
          allUp.includes('SUBTOTAL') || allUp.includes('JUMLAH TOTAL') ||
          cellsUp[0].includes('TOTAL') || cellsUp[0].includes('PER TANGGAL') ||
          cellsUp[0].includes('TANGGAL :') || nonEmpty[0]?.toUpperCase().includes('PER TGL')) {
        continue;
      }

      // ── Ambil NO. KWITANSI ────────────────────────────────────
      const noKwtRaw = cells[iNoKwt] || '';
      const noKwt    = noKwtRaw.trim();
      if (!noKwt) continue;

      // Skip jika isinya seperti label/header (bukan nomor kwitansi)
      const nkUp = noKwt.toUpperCase();
      if (nkUp.includes('KWITANSI') || nkUp.includes('NO.') || nkUp.includes('NOMOR') ||
          nkUp.includes('PER TANGGAL') || nkUp.includes('TANGGAL') ||
          (nkUp.length > 25 && !noKwt.match(/\d/))) continue;

      // ── Parse TGL ─────────────────────────────────────────────
      const tglDate  = iTgl >= 0 ? parseDate(r[iTgl]) : null;
      const tglFmt   = tglDate ? fmtDate(tglDate) : (iTgl >= 0 ? String(r[iTgl]||'').trim() : '');

      // ── Parse NILAI & JUMLAH ──────────────────────────────────
      const nilaiRaw  = iNilai  >= 0 ? parseNilai(r[iNilai])  : 0;
      const jumlahRaw = iJumlah >= 0 ? parseNilai(r[iJumlah]) : 0;
      // Gunakan nilai terbaik: prioritaskan NILAI KWITANSI; jika 0 fallback ke JUMLAH
      const nilai = nilaiRaw > 0 ? nilaiRaw : jumlahRaw;

      // ── Parse DIFF ────────────────────────────────────────────
      // Sanity: DIFF adalah jumlah hari (biasanya 0–9999), bukan nilai uang jutaan
      let diff = 0;
      if (iDiff >= 0 && r[iDiff] !== '' && r[iDiff] !== null && r[iDiff] !== undefined) {
        const rawDiff = Math.round(parseFloat(String(r[iDiff]).replace(',','.')) || 0);
        // Jika rawDiff terlalu besar (bukan hari melainkan nilai), hitung dari TGL
        if (rawDiff >= 0 && rawDiff <= 9999) {
          diff = rawDiff;
        } else {
          diff = tglDate && !isNaN(tglDate)
            ? Math.max(0, Math.floor((today - tglDate) / 86400000))
            : 0;
        }
      } else if (tglDate && !isNaN(tglDate)) {
        diff = Math.max(0, Math.floor((today - tglDate) / 86400000));
      }

      // ── Tentukan LEASING ──────────────────────────────────────
      let leasing = curLeasing;
      if (!leasing && iLeasing >= 0) {
        const lRaw = String(r[iLeasing]||'').trim().toUpperCase();
        leasing = LEASING_LIST.find(l => lRaw.includes(l)) || lRaw || 'LAINNYA';
      }
      if (!leasing) leasing = 'LAINNYA';

      // ── Helper: baca sel; jika kosong coba 1 kolom ke kiri ──────
      // (beberapa Excel menaruh header di kolom kanan dari data sebenarnya)
      const readLeft = (arr, idx) => {
        if (idx < 0) return '';
        const v = arr[idx]?.trim ? arr[idx].trim() : String(arr[idx]||'').trim();
        if (v) return v;
        // Kolom saat ini kosong → coba kolom kiri
        const vL = idx > 0 ? (arr[idx-1]?.trim ? arr[idx-1].trim() : String(arr[idx-1]||'').trim()) : '';
        return vL;
      };

      // Customer & Faktur pakai readLeft karena header terkadang 1 kolom di kanan data
      const customerVal = readLeft(cells, iCustomer);
      const noFakturVal = readLeft(cells, iNoFaktur);

      result.push({
        noKwt,
        tgl:      tglFmt,
        customer: customerVal,
        noAR:     iNoAR >= 0 ? cells[iNoAR] : '',
        noFaktur: noFakturVal,
        nilai,
        jumlah:   jumlahRaw > 0 && jumlahRaw !== nilaiRaw ? jumlahRaw : nilai,
        diff,
        leasing,
      });
    }
    return result;
  }

  // ── Proses import file ──────────────────────────────────────────
  function _processKwtFile(file) {
    if (!file) return;
    if (!file.name.match(/\.(xls|xlsx|csv)$/i)) {
      showToast('Hanya file .xls / .xlsx / .csv yang diterima.', 'error'); return;
    }
    const reader = new FileReader();
    reader.onload = function(e) {
      try {
        const parsed = _parseKwtExcel(new Uint8Array(e.target.result));
        if (!parsed.length) {
          showToast('Tidak ada data kwitansi yang terdeteksi. Pastikan format kolom: NO. KWITANSI | TGL. KWITANSI | NAMA CUSTOMER | NO. AR | NO. FAKTUR | NILAI KWITANSI (RP) | DIFF.', 'error');
          return;
        }
        saveKwtDb(parsed);
        // Tampilkan info leasing yang terdeteksi
        const lMap = {};
        parsed.forEach(r => { const l=r.leasing||'LAINNYA'; lMap[l]=(lMap[l]||0)+1; });
        const lInfo = Object.entries(lMap).map(([l,n]) => `${l}(${n})`).join(', ');
        const sample = parsed[0] || {};
        const colInfo = [
          sample.noKwt     ? `No.Kwt ✓`    : `No.Kwt ✗`,
          sample.tgl       ? `Tgl ✓`       : `Tgl ✗`,
          sample.customer  ? `Customer ✓`  : `Customer ✗ (tidak ditemukan)`,
          sample.noAR      ? `No.AR ✓`     : `No.AR ✗`,
          sample.noFaktur  ? `Faktur ✓`    : `Faktur ✗ (tidak ditemukan)`,
          sample.nilai > 0 ? `Nilai ✓`     : `Nilai ✗`,
          sample.diff > 0  ? `Diff ✓`      : `Diff (hitung dari tgl)`,
        ].join(' · ');
        const msgEl = document.getElementById('kwtImportMsg');
        if (msgEl) msgEl.innerHTML = `<span style="color:#16a34a">✅ ${parsed.length} kwitansi berhasil dimuat dari "${file.name}"</span>
          <br><span style="font-size:.73rem;color:#6b7280">Leasing: ${lInfo}</span>
          <br><span style="font-size:.72rem;color:#9ca3af">Kolom: ${colInfo}</span>`;
        showToast(`${parsed.length} data kwitansi berhasil diimport. Leasing: ${lInfo}`, 'success');
        renderKwtSection();
      } catch(err) {
        showToast('Gagal membaca file: ' + err.message, 'error');
      }
    };
    reader.readAsArrayBuffer(file);
  }

  // ── Render section utama ────────────────────────────────────────
  function renderKwtSection() {
    const content = document.getElementById('kwtContent');
    if (!content) return;
    const db      = loadKwtDb();
    const scans   = loadKwtScan().filter(r => String(r.planId) === String(_kwtPlanId));
    const fmtRp   = n => 'Rp ' + Number(n||0).toLocaleString('id-ID');
    const fmtN    = n => Number(n||0).toLocaleString('id-ID');

    // ── Kelompokkan per leasing ───────────────────────────────
    const leasingMap = {};
    db.forEach(row => {
      const l = row.leasing || 'LAINNYA';
      if (!leasingMap[l]) leasingMap[l] = [];
      leasingMap[l].push(row);
    });
    const leasings = Object.keys(leasingMap).sort();

    // ── Stats ─────────────────────────────────────────────────
    const totalNilai   = db.reduce((s,r) => s + (r.nilai||0), 0);
    const totalDiff    = db.reduce((s,r) => s + (r.diff||0), 0);
    const avgDiff      = db.length ? (totalDiff / db.length).toFixed(1) : '0';
    const uniqueCust   = new Set(db.map(r => r.customer)).size;
    const savedState   = loadSavedPem().some(s => String(s.planId) === String(_kwtPlanId) && s.type === 'kwt_gantung');

    // Format nilai besar
    const fmtJt = n => n >= 1e9 ? (n/1e9).toFixed(1) + ' M'
      : n >= 1e6 ? (n/1e6).toFixed(1) + ' Jt'
      : fmtN(n);

    // ── Render tabel per leasing ──────────────────────────────
    const tableRows = leasings.map(leasing => {
      const rows    = leasingMap[leasing];
      const sumNilai = rows.reduce((s,r) => s+(r.nilai||0), 0);
      const avgDiffL = rows.length ? (rows.reduce((s,r)=>s+(r.diff||0),0) / rows.length).toFixed(1) : '0';
      const fisikCount = rows.filter(r => _kwtGetRow(_kwtPlanId, r.noKwt).fisik).length;

      const dataRows = rows.map((row, idx) => {
        const sc  = _kwtGetRow(_kwtPlanId, row.noKwt);
        const ket = sc.keterangan || '';
        const safeKet = ket.replace(/"/g,'&quot;');
        return `<tr>
          <td style="text-align:center;font-size:.78rem">${idx+1}</td>
          <td style="font-family:monospace;font-size:.77rem;font-weight:700;color:#0f766e">${row.noKwt}</td>
          <td style="font-size:.78rem;white-space:nowrap">${row.tgl}</td>
          <td style="font-size:.78rem;font-weight:600">${row.customer}</td>
          <td style="font-family:monospace;font-size:.76rem">${row.noAR}</td>
          <td style="font-family:monospace;font-size:.75rem;color:#6b7280">${row.noFaktur}</td>
          <td style="text-align:right;font-weight:700;font-size:.78rem">
            ${fmtRp(row.nilai)}
            ${row.jumlah && row.jumlah !== row.nilai && row.jumlah > 0
              ? `<br><span style="font-size:.68rem;color:#0f766e;font-weight:400">Jml: ${fmtRp(row.jumlah)}</span>`
              : ''}
          </td>
          <td style="text-align:center;font-weight:700;color:${row.diff>30?'#dc2626':row.diff>14?'#d97706':'#374151'}">${row.diff}</td>
          <td>
            <input type="text" value="${safeKet}"
                   style="width:100%;padding:4px 8px;border:1px solid #e5e7eb;border-radius:5px;font-size:.75rem"
                   placeholder="Keterangan... (opsional)"
                   onchange="window._kwtSaveKet('${row.noKwt}', this.value)"
                   oninput="window._kwtSaveKet('${row.noKwt}', this.value)" />
          </td>
          <td style="text-align:center">
            <input type="checkbox" ${sc.fisik ? 'checked' : ''}
                   style="width:16px;height:16px;cursor:pointer;accent-color:#0f766e"
                   onchange="window._kwtToggleFisik('${row.noKwt}', this.checked)" />
          </td>
        </tr>`;
      }).join('');

      return `
        <tr style="background:#0f766e;color:#fff">
          <td colspan="10" style="padding:6px 10px;font-size:.8rem;font-weight:700;letter-spacing:.04em">
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:middle;margin-right:5px"><rect x="2" y="5" width="20" height="14" rx="2"/><line x1="2" y1="10" x2="22" y2="10"/></svg>
            ${leasing} (${rows.length} KWITANSI) — Fisik Terperiksa: ${fisikCount}/${rows.length}
          </td>
        </tr>
        ${dataRows}
        <tr style="background:#f0fdf4;font-weight:700">
          <td colspan="6" style="text-align:right;padding:6px 10px;font-size:.79rem;color:#065f46">Sub Total ${leasing}</td>
          <td style="text-align:right;padding:6px 10px;font-size:.79rem;color:#065f46">${fmtRp(sumNilai)}</td>
          <td style="text-align:center;padding:6px 10px;font-size:.79rem;color:#065f46">${avgDiffL}</td>
          <td colspan="2"></td>
        </tr>`;
    }).join('');

    // Grand Total
    const fisikTotal = db.filter(r => _kwtGetRow(_kwtPlanId, r.noKwt).fisik).length;

    content.innerHTML = `
      <!-- Import section -->
      <div class="pem-card" style="margin-bottom:14px">
        <div class="pem-card-header" style="background:#0f766e;color:#fff;border-radius:8px 8px 0 0;padding:10px 16px;
             display:flex;align-items:center;justify-content:space-between">
          <div style="display:flex;align-items:center;gap:8px;font-size:.85rem;font-weight:700;text-transform:uppercase;letter-spacing:.04em">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="5" width="20" height="14" rx="2"/><line x1="2" y1="10" x2="22" y2="10"/></svg>
            IMPORT DATABASE KWITANSI GANTUNG (EXCEL)
          </div>
          ${db.length ? `<span style="font-size:.73rem;font-weight:600;background:rgba(255,255,255,.2);padding:2px 10px;border-radius:10px">● DATABASE AKTIF</span>` : ''}
        </div>
        <div class="pem-card-body" style="border:1px solid #0f766e;border-top:none;border-radius:0 0 8px 8px">
          <div class="import-zone" id="kwtDropZone"
               style="border:2px dashed #0f766e;border-radius:8px;padding:20px;text-align:center;cursor:pointer;background:#f0fdf4;transition:background .2s">
            <svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="#0f766e" stroke-width="1.5" style="margin-bottom:8px">
              <path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/>
            </svg>
            <p style="margin:0 0 8px;font-size:.85rem;color:#065f46">Drag &amp; drop file <strong>.xls / .xlsx</strong> laporan kwitansi gantung<br>atau klik tombol di bawah</p>
            <button type="button" id="kwtBrowseBtn"
                    style="background:#0f766e;color:#fff;border:none;border-radius:7px;padding:7px 18px;font-size:.82rem;cursor:pointer;font-weight:600">
              📂 Pilih File Excel
            </button>
            <input type="file" id="kwtFileInput" accept=".xls,.xlsx,.csv" hidden />
          </div>
          <div id="kwtImportMsg" style="margin-top:8px;font-size:.8rem;text-align:center;color:var(--text-secondary)">
            ${db.length ? `<span style="color:#16a34a">✅ ${db.length} kwitansi berhasil dimuat</span>` : ''}
          </div>
        </div>
      </div>

      ${!db.length ? `<div class="empty-state" style="padding:40px">
          <svg width="42" height="42" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="2" y="5" width="20" height="14" rx="2"/><line x1="2" y1="10" x2="22" y2="10"/></svg>
          <p>Import data kwitansi gantung dari Excel terlebih dahulu.</p>
        </div>` : `

      <!-- Stats -->
      <div style="display:flex;flex-wrap:wrap;gap:10px;margin-bottom:14px">
        ${[
          ['Total Transaksi', db.length, '#374151', '#f8fafc', '#e5e7eb'],
          ['Customer', uniqueCust, '#374151', '#f8fafc', '#e5e7eb'],
          ['Leasing', leasings.length, '#374151', '#f8fafc', '#e5e7eb'],
          ['Fisik Terperiksa', `${fisikTotal}/${db.length}`, '#16a34a', '#f0fdf4', '#86efac'],
          ['Total Nilai', fmtJt(totalNilai), '#0f766e', '#f0fdf4', '#6ee7b7'],
        ].map(([lbl, val, clr, bg, border]) =>
          `<div style="background:${bg};border:2px solid ${border};border-radius:10px;padding:10px 18px;text-align:center;min-width:100px;flex:1">
            <div style="font-size:1.3rem;font-weight:800;color:${clr}">${val}</div>
            <div style="font-size:.68rem;font-weight:700;text-transform:uppercase;color:#6b7280;margin-top:2px;letter-spacing:.04em">${lbl}</div>
          </div>`).join('')}
      </div>

      <!-- Rata-rata hari -->
      <div style="background:linear-gradient(135deg,#0f766e,#0d9488);border-radius:10px;padding:14px 20px;margin-bottom:14px;color:#fff">
        <div style="display:flex;align-items:center;gap:20px;flex-wrap:wrap">
          <div>
            <div style="font-size:2.2rem;font-weight:900;letter-spacing:-1px">${avgDiff}</div>
            <div style="font-size:.75rem;opacity:.85;font-weight:600">RATA-RATA HARI KWITANSI GANTUNG</div>
            <div style="font-size:.72rem;opacity:.7;margin-top:2px">Total difft: ${totalDiff} hari = ${db.length} kwitansi</div>
          </div>
          <div style="display:flex;flex-wrap:wrap;gap:8px;flex:1;justify-content:flex-end">
            ${leasings.map(l => {
              const rows  = leasingMap[l];
              const avg   = rows.length ? (rows.reduce((s,r)=>s+(r.diff||0),0)/rows.length).toFixed(1) : '0';
              return `<div style="background:rgba(255,255,255,.15);border-radius:8px;padding:8px 14px;text-align:center">
                <div style="font-size:1.3rem;font-weight:800">${avg}</div>
                <div style="font-size:.72rem;opacity:.85">${l} (${rows.length})</div>
              </div>`;
            }).join('')}
          </div>
        </div>
      </div>

      <!-- Daftar Kwitansi -->
      <div class="pem-card">
        <div class="pem-card-header" style="background:#0f766e;color:#fff;border-radius:8px 8px 0 0">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2"/><rect x="9" y="3" width="6" height="4" rx="1"/></svg>
          DAFTAR KWITANSI GANTUNG
          <span style="margin-left:auto;font-size:.75rem;font-weight:600;background:rgba(255,255,255,.2);padding:2px 10px;border-radius:10px">${db.length} KWITANSI</span>
        </div>
        <div style="border:1px solid #0f766e;border-top:none;border-radius:0 0 8px 8px;overflow:auto">
          <table class="kas-table" style="font-size:.79rem;min-width:900px">
            <thead>
              <tr style="background:#134e4a;color:#fff">
                <th style="width:32px;text-align:center">NO.</th>
                <th>NO. KWITANSI</th>
                <th>TGL. KWITANSI</th>
                <th>NAMA CUSTOMER</th>
                <th>NO. AR</th>
                <th>NO. FAKTUR</th>
                <th style="text-align:right">NILAI KWITANSI (RP)</th>
                <th style="text-align:center;width:48px">DIFF</th>
                <th style="min-width:160px">KETERANGAN</th>
                <th style="text-align:center;width:44px">FISIK</th>
              </tr>
            </thead>
            <tbody>
              ${tableRows}
              <!-- Grand Total -->
              <tr style="background:#134e4a;color:#fff;font-weight:700">
                <td colspan="6" style="text-align:right;padding:7px 10px">GRAND TOTAL</td>
                <td style="text-align:right;padding:7px 10px">${fmtRp(totalNilai)}</td>
                <td style="text-align:center;padding:7px 10px">${avgDiff}</td>
                <td colspan="2"></td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>

      <!-- Simpan ke Report Audit -->
      <div style="margin-top:14px;display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:12px 14px;
           background:${savedState?'#dcfce7':'#f0fdf4'};border:1.5px solid ${savedState?'#86efac':'#6ee7b7'};border-radius:8px">
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="${savedState?'#166534':'#065f46'}" stroke-width="2">
          <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/>
          <polyline points="17 21 17 13 7 13 7 21"/>
        </svg>
        <div style="flex:1;font-size:.82rem;font-weight:700;color:${savedState?'#166534':'#065f46'}">
          ${savedState ? '✓ Kwitansi Gantung sudah disimpan ke Report Audit' : 'Simpan hasil ke Report Audit'}
        </div>
        <button onclick="window._simpanPemeriksaan('${_kwtPlanId}','kwt_gantung')"
                style="background:${savedState?'#16a34a':'#0f766e'};color:#fff;border:none;border-radius:7px;
                       padding:8px 16px;font-size:.82rem;font-weight:700;cursor:pointer;white-space:nowrap">
          ${savedState ? 'Perbarui ke Report Audit' : 'Simpan ke Report Audit'}
        </button>
      </div>
      `}`;

    // Attach event listeners setelah render
    _kwtAttachListeners();
  }

  function _kwtAttachListeners() {
    document.getElementById('kwtBrowseBtn')?.addEventListener('click', () =>
      document.getElementById('kwtFileInput')?.click());
    document.getElementById('kwtFileInput')?.addEventListener('change', function() {
      _processKwtFile(this.files[0]); this.value = '';
    });
    const dz = document.getElementById('kwtDropZone');
    if (dz) {
      dz.addEventListener('dragover', e => { e.preventDefault(); dz.style.background='#d1fae5'; });
      dz.addEventListener('dragleave', () => { dz.style.background='#f0fdf4'; });
      dz.addEventListener('drop', e => {
        e.preventDefault(); dz.style.background='#f0fdf4';
        _processKwtFile(e.dataTransfer.files[0]);
      });
    }
  }

  // ── Toggle fisik ────────────────────────────────────────────────
  window._kwtToggleFisik = function(noKwt, checked) {
    _kwtSetRow(_kwtPlanId, noKwt, { fisik: checked });
    // Update badge count saja tanpa full re-render (hindari kehilangan focus input)
    const db = loadKwtDb();
    const fisikTotal = db.filter(r => _kwtGetRow(_kwtPlanId, r.noKwt).fisik).length;
    const el = document.querySelector('[id^="kwtContent"] .pem-card-header span');
    // Update stat card (simple approach)
  };

  // ── Save keterangan ─────────────────────────────────────────────
  window._kwtSaveKet = function(noKwt, val) {
    _kwtSetRow(_kwtPlanId, noKwt, { keterangan: val.trim() });
  };

  // ── Buka section ────────────────────────────────────────────────
  window._openKwtGantung = function(taskId) {
    tasks = loadTasks();
    const t = tasks.find(x => String(x.id) === String(taskId));
    if (!t) return;
    _kwtTaskId = taskId;
    _kwtPlanId = t.planId;

    const banner    = document.getElementById('kwtPlanBanner');
    const bannerCnt = document.getElementById('kwtPlanBannerContent');
    if (banner && bannerCnt) {
      bannerCnt.innerHTML =
        '<span><strong>' + (t.noSPT||'—') + '</strong></span>' +
        '<span style="opacity:.6">|</span>' +
        '<span>🏢 ' + (t.cabangPlan||'—') + (t.cabangArea?'  <span style="font-size:.73rem;background:rgba(255,255,255,.2);border-radius:3px;padding:1px 5px">'+t.cabangArea+'</span>':'') + '</span>' +
        '<span style="opacity:.6">|</span>' +
        '<span>📋 ' + (t.jenisAudit||'—') + '</span>';
      banner.style.display = '';
    }

    document.querySelectorAll('.content-section').forEach(s => s.classList.add('hidden'));
    document.querySelectorAll('.nav-item').forEach(li => li.classList.remove('active'));
    const section  = document.getElementById('section-pemeriksaan-kwtgantung');
    const auditNav = document.querySelector('.nav-item[data-section="audit"]');
    if (section)   section.classList.remove('hidden');
    if (auditNav)  auditNav.classList.add('active');
    renderKwtSection();
  };

  // ── Reset ────────────────────────────────────────────────────────
  window._kwtReset = function() {
    if (!confirm('Reset semua data audit kwitansi gantung untuk plan ini?\n(Database tidak akan dihapus, hanya data fisik & keterangan.)')) return;
    const all = loadKwtScan().filter(r => String(r.planId) !== String(_kwtPlanId));
    saveKwtScan(all);
    renderKwtSection();
  };

  // ── Generate PDF ─────────────────────────────────────────────────
  window._kwtPrintPDF = function(planId) {
    const pid = planId || _kwtPlanId;
    if (!pid) return;
    const db    = loadKwtDb();
    if (!db.length) { showToast('Belum ada data kwitansi gantung.', 'error'); return; }
    const scans = loadKwtScan().filter(r => String(r.planId) === String(pid));
    const _gRow = noKwt => scans.find(r => r.noKwt === noKwt) || { fisik:false, keterangan:'' };

    const allTasks = loadTasks();
    const task  = allTasks.find(t => String(t.planId) === String(pid));
    const noSPT = task?.noSPT || '—';
    const cabang= task?.cabangPlan || '—';
    const area  = task?.cabangArea || '';
    const org   = (() => { try { return JSON.parse(localStorage.getItem('akta_org')) || {}; } catch { return {}; } })();
    const orgName = org.namaOrg || 'AKTA IAT';
    const now   = new Date().toLocaleDateString('id-ID',{day:'2-digit',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit'});
    const fmtRp = n => 'Rp ' + Number(n||0).toLocaleString('id-ID');

    const lMap = {};
    db.forEach(r => { const l = r.leasing||'LAINNYA'; if(!lMap[l]) lMap[l]=[]; lMap[l].push(r); });
    const leasings = Object.keys(lMap).sort();
    const totalNilai = db.reduce((s,r)=>s+(r.nilai||0),0);
    const totalDiff  = db.reduce((s,r)=>s+(r.diff||0),0);
    const avgDiff    = db.length ? (totalDiff/db.length).toFixed(1) : '0';
    const fisikOk    = db.filter(r => _gRow(r.noKwt).fisik).length;

    const tableBody = leasings.map(leasing => {
      const rows    = lMap[leasing];
      const sumNilai = rows.reduce((s,r)=>s+(r.nilai||0),0);
      const avgDL   = rows.length ? (rows.reduce((s,r)=>s+(r.diff||0),0)/rows.length).toFixed(1) : '0';
      const dataRows = rows.map((r,i) => {
        const sc = _gRow(r.noKwt);
        return `<tr style="background:${i%2?'#f8fafc':'#fff'}">
          <td style="text-align:center">${i+1}</td>
          <td style="font-family:monospace;font-size:9px;font-weight:700;color:#0f766e">${r.noKwt}</td>
          <td style="white-space:nowrap">${r.tgl}</td>
          <td style="font-weight:600;font-size:9.5px">${r.customer}</td>
          <td style="font-family:monospace;font-size:9px">${r.noAR}</td>
          <td style="font-family:monospace;font-size:8.5px">${r.noFaktur}</td>
          <td style="text-align:right;font-weight:700">${fmtRp(r.nilai)}</td>
          <td style="text-align:center;font-weight:700;color:${r.diff>30?'#dc2626':r.diff>14?'#d97706':'#374151'}">${r.diff}</td>
          <td style="font-size:9px">${sc.keterangan||''}</td>
          <td style="text-align:center;font-size:11px">${sc.fisik?'<span style="color:#16a34a;font-weight:700">✓</span>':'<span style="color:#dc2626">✗</span>'}</td>
        </tr>`;
      }).join('');
      return `<tr style="background:#0f766e;color:#fff">
        <td colspan="10" style="padding:5px 10px;font-size:10px;font-weight:700">
          ${leasing} (${rows.length} kwitansi)
        </td></tr>
        ${dataRows}
        <tr style="background:#f0fdf4;font-weight:700">
          <td colspan="6" style="text-align:right;padding:5px 8px;font-size:9.5px;color:#065f46">Sub Total ${leasing}</td>
          <td style="text-align:right;padding:5px 8px;color:#065f46">${fmtRp(sumNilai)}</td>
          <td style="text-align:center;padding:5px 8px;color:#065f46">${avgDL}</td>
          <td colspan="2"></td>
        </tr>`;
    }).join('');

    const html = `<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"/>
<title>Kwitansi Gantung — ${noSPT}</title>
<style>
  *{box-sizing:border-box;margin:0;padding:0}
  body{font-family:'Segoe UI',Arial,sans-serif;font-size:10px;color:#1a1a1a;background:#fff;padding:16px 20px}
  @page{size:A4 landscape;margin:10mm 8mm}
  @media print{body{padding:0}.no-print{display:none!important}button{display:none!important}}
  .header{border-bottom:3px solid #0f766e;padding-bottom:10px;margin-bottom:14px;display:flex;justify-content:space-between;align-items:flex-end}
  .header .org{font-size:15px;font-weight:800;color:#0f766e}
  .header .sub{font-size:9px;color:#6b7280;margin-top:2px}
  .header .right{text-align:right;font-size:9.5px;color:#6b7280}
  .plan-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:6px;margin-bottom:12px;background:#f0fdf4;border:1px solid #6ee7b7;border-radius:6px;padding:8px 10px}
  .plan-item label{font-size:8px;text-transform:uppercase;letter-spacing:.05em;color:#6b7280;display:block;margin-bottom:2px}
  .plan-item span{font-weight:700;font-size:10px;color:#0f766e}
  .stat-row{display:flex;gap:8px;margin-bottom:10px}
  .stat-box{flex:1;background:#f0fdf4;border:1.5px solid #6ee7b7;border-radius:7px;padding:8px 12px;text-align:center}
  .stat-box .val{font-size:1.3rem;font-weight:800;color:#0f766e}
  .stat-box .lbl{font-size:8px;font-weight:700;text-transform:uppercase;color:#6b7280;margin-top:2px}
  .rata-box{background:linear-gradient(135deg,#0f766e,#0d9488);color:#fff;border-radius:8px;padding:12px 16px;margin-bottom:12px;display:flex;align-items:center;gap:20px}
  .rata-main .big{font-size:1.8rem;font-weight:900}
  .rata-main .lbl{font-size:9px;opacity:.85;margin-top:2px}
  .rata-sub{display:flex;flex-wrap:wrap;gap:8px}
  .rata-sub-item{background:rgba(255,255,255,.15);border-radius:6px;padding:6px 12px;text-align:center}
  .rata-sub-item .v{font-size:1.1rem;font-weight:800}
  .rata-sub-item .l{font-size:8px;opacity:.85}
  table{width:100%;border-collapse:collapse;font-size:9.5px}
  thead tr{background:#134e4a;color:#fff}
  th{padding:5px 7px;text-align:left;font-size:9px;font-weight:700}
  td{padding:4px 7px;border-bottom:1px solid #f1f5f9;vertical-align:middle}
  .footer{margin-top:14px;border-top:1px solid #e5e7eb;padding-top:6px;font-size:8px;color:#9ca3af;display:flex;justify-content:space-between}
  .print-btn{display:flex;gap:8px;margin-bottom:12px}
</style>
</head><body>
<div class="print-btn no-print">
  <button onclick="window.print()" style="background:#0f766e;color:#fff;padding:7px 18px;border:none;border-radius:6px;font-weight:700;cursor:pointer">🖨️ Print / Simpan PDF</button>
  <button onclick="window.close()" style="background:#f1f5f9;color:#374151;padding:7px 14px;border:none;border-radius:6px;font-weight:700;cursor:pointer">✕ Tutup</button>
</div>
<div class="header">
  <div><div class="org">${orgName}</div><div class="sub">Sistem Audit Internal — AKTA IAT</div></div>
  <div class="right">
    <div style="font-size:13px;font-weight:800;color:#0f766e">BERITA ACARA PEMERIKSAAN</div>
    <div style="font-weight:700;color:#0f766e">KWITANSI GANTUNG</div>
    <div>Dicetak: ${now}</div>
  </div>
</div>
<div class="plan-grid">
  <div class="plan-item"><label>No. SPT</label><span>${noSPT}</span></div>
  <div class="plan-item"><label>Cabang</label><span>${cabang}${area?' · '+area:''}</span></div>
  <div class="plan-item"><label>Total Kwitansi</label><span>${db.length}</span></div>
  <div class="plan-item"><label>Fisik Terperiksa</label><span style="color:${fisikOk===db.length?'#16a34a':'#dc2626'}">${fisikOk} / ${db.length}</span></div>
  <div class="plan-item"><label>Total Nilai</label><span>Rp ${Number(totalNilai).toLocaleString('id-ID')}</span></div>
</div>
<div class="rata-box">
  <div class="rata-main"><div class="big">${avgDiff}</div><div class="lbl">RATA-RATA HARI KWITANSI GANTUNG</div><div style="font-size:8px;opacity:.7;margin-top:3px">Total difft: ${totalDiff} hari = ${db.length} kwitansi</div></div>
  <div class="rata-sub">
    ${leasings.map(l => {
      const rows = lMap[l];
      const avg  = rows.length ? (rows.reduce((s,r)=>s+(r.diff||0),0)/rows.length).toFixed(1) : '0';
      return `<div class="rata-sub-item"><div class="v">${avg}</div><div class="l">${l} (${rows.length})</div></div>`;
    }).join('')}
  </div>
</div>
<table>
  <thead>
    <tr>
      <th style="width:24px;text-align:center">NO.</th>
      <th>NO. KWITANSI</th><th>TGL. KWITANSI</th><th>NAMA CUSTOMER</th>
      <th>NO. AR</th><th>NO. FAKTUR</th>
      <th style="text-align:right">NILAI KWITANSI (RP)</th>
      <th style="text-align:center;width:40px">DIFF</th>
      <th>KETERANGAN</th>
      <th style="text-align:center;width:40px">FISIK</th>
    </tr>
  </thead>
  <tbody>
    ${tableBody}
    <tr style="background:#134e4a;color:#fff;font-weight:700">
      <td colspan="6" style="text-align:right;padding:5px 8px">GRAND TOTAL</td>
      <td style="text-align:right;padding:5px 8px">${fmtRp(totalNilai)}</td>
      <td style="text-align:center;padding:5px 8px">${avgDiff}</td>
      <td colspan="2"></td>
    </tr>
  </tbody>
</table>
<div class="footer">
  <span>${orgName} — AKTA IAT Audit System · No. SPT: ${noSPT} · ${cabang}${area?' · '+area:''}</span>
  <span>Dicetak: ${now}</span>
</div>
<script>window.onload=function(){window.print();};<\/script>
</body></html>`;

    const win = window.open('', '_blank', 'width=1100,height=700,scrollbars=yes');
    if (win) { win.document.write(html); win.document.close(); }
    else showToast('Popup diblokir. Izinkan popup untuk melihat PDF.', 'error');
  };

  /* ── END MODUL KWITANSI GANTUNG ── */

  /* ============================================================
     MODUL HGP & AHM OIL'S
     ============================================================ */
  const HGP_STOK_KEY  = 'akta_hgp_stok';
  const HGP_HASIL_KEY = 'akta_hgp_hasil';
  const HGP_META_KEY  = 'akta_hgp_meta';
  const HGP_WO_KEY    = 'akta_hgp_wo';

  function loadHgp(key)       { try { return JSON.parse(localStorage.getItem(key)) || []; } catch { return []; } }
  function loadHgpMeta()      { try { return JSON.parse(localStorage.getItem(HGP_META_KEY)) || {}; } catch { return {}; } }
  function saveHgp(key, data) { localStorage.setItem(key, JSON.stringify(data)); window.API?.sync(key, data); }
  function saveHgpMeta(m)     { localStorage.setItem(HGP_META_KEY, JSON.stringify(m)); window.API?.sync(HGP_META_KEY, m); }

  // ── Helper format tanggal khusus HGP
  function _hgpFmtTgl(s) {
    if (!s) return '—';
    try { return new Date(s).toLocaleDateString('id-ID', { day:'2-digit', month:'long', year:'numeric' }); } catch { return s; }
  }

  // ── Render section HGP ────────────────────────────────────────
  function renderHgpSection() {
    const stok   = loadHgp(HGP_STOK_KEY);
    const hasil  = loadHgp(HGP_HASIL_KEY);
    const wo     = loadHgp(HGP_WO_KEY);
    const meta   = loadHgpMeta();
    const ctx    = _hgpPlanContext; // konteks plan dari Audit section

    // ── Render banner konteks plan ──────────────────────────
    const banner    = document.getElementById('hgpPlanBanner');
    const bannerCnt = document.getElementById('hgpPlanBannerContent');
    if (banner && bannerCnt) {
      if (ctx) {
        bannerCnt.innerHTML =
          '<span><strong>' + ctx.noSPT + '</strong></span>' +
          '<span style="opacity:.6">|</span>' +
          '<span>&#127970; ' + ctx.cabangPlan + (ctx.cabangArea ? ' <span style="font-size:.73rem;background:rgba(255,255,255,.2);border-radius:3px;padding:1px 5px">' + ctx.cabangArea + '</span>' : '') + '</span>' +
          '<span style="opacity:.6">|</span>' +
          '<span>&#128203; ' + ctx.jenisAudit + '</span>' +
          '<span style="opacity:.6">|</span>' +
          '<span>&#128197; ' + ctx.tanggalPlan + '</span>';
        banner.style.display = '';
      } else {
        banner.style.display = 'none';
      }
    }

    _renderHgpStokTable(stok, meta, ctx);
    _renderHgpPeriksaTab(stok, hasil, meta, ctx);
    _renderHgpWOTab(stok, wo, hasil, meta, ctx);
    _renderHgpHasilTab(stok, hasil, wo, meta, ctx);
    _updateHgpBadge(hasil.length);
    _updateHgpWoBadge(wo.length);
  }

  // ── Helper: total WO qty per noPart ────────────────────────
  function _hgpWoTotal(wo) {
    const map = {};
    wo.forEach(w => { map[w.noPart] = (map[w.noPart] || 0) + (w.qty || 0); });
    return map;
  }

  function _updateHgpBadge(count) {
    const b = document.getElementById('hgpHasilBadge');
    if (!b) return;
    b.textContent = count;
    b.classList.toggle('hidden', count === 0);
  }

  function _updateHgpWoBadge(count) {
    const b = document.getElementById('hgpWoBadge');
    if (!b) return;
    b.textContent = count;
    b.classList.toggle('hidden', count === 0);
  }

  // ── Meta info banner dari file (fallback) ───────────────────
  function _hgpMetaBanner(meta) {
    if (!meta || !meta.unitUsaha) return '';
    return '<strong>' + meta.unitUsaha + '</strong> &nbsp;&middot;&nbsp; Periode: <strong>' +
           (meta.periodeAwal || '—') + '</strong> s/d <strong>' + (meta.periodeAkhir || '—') + '</strong>' +
           (meta.tanggalFile ? ' &nbsp;&middot;&nbsp; File: ' + meta.tanggalFile : '');
  }

  // ── Info banner utama: plan (prioritas) atau file ────────────
  function _hgpInfoBanner(meta, ctx) {
    if (ctx) {
      let txt = '<strong>' + ctx.noSPT + '</strong>';
      txt += ' &nbsp;&middot;&nbsp; &#127970; <strong>' + ctx.cabangPlan + '</strong>';
      if (ctx.cabangArea) txt += ' <span style="font-size:.72rem;background:#d1fae5;color:#065f46;border-radius:3px;padding:1px 5px">' + ctx.cabangArea + '</span>';
      txt += ' &nbsp;&middot;&nbsp; ' + ctx.jenisAudit;
      txt += ' &nbsp;&middot;&nbsp; &#128197; Tgl Plan: <strong>' + ctx.tanggalPlan + '</strong>';
      if (meta && meta.periodeAwal) {
        txt += ' <span style="font-size:.74rem;opacity:.7">&nbsp;(Periode stok: ' + meta.periodeAwal + ' s/d ' + (meta.periodeAkhir || '—') + ')</span>';
      }
      return txt;
    }
    return _hgpMetaBanner(meta);
  }

  // ── Render tabel stok (Tab Import) ──────────────────────────
  function _renderHgpStokTable(stok, meta, ctx) {
    const body    = document.getElementById('hgpStokBody');
    const stat    = document.getElementById('hgpImportStat');
    const count   = document.getElementById('hgpStokCount');
    const metaDiv = document.getElementById('hgpMetaInfo');
    if (!body) return;

    const importedCount = stok.filter(s => !s.isManual).length;
    const manualCount   = stok.filter(s => s.isManual).length;

    if (stat) stat.textContent = stok.length > 0 ? stok.length + ' item' : 'Belum ada data';
    if (count) {
      count.textContent = stok.length === 0 ? ''
        : stok.length + ' item tersedia' + (manualCount > 0 ? ' (' + importedCount + ' import + ' + manualCount + ' manual)' : '');
    }

    if (metaDiv) {
      if (importedCount > 0 && (meta.unitUsaha || ctx)) {
        metaDiv.innerHTML = '&#9989; ' + _hgpInfoBanner(meta, ctx);
        metaDiv.style.display = '';
      } else if (importedCount === 0 && manualCount > 0) {
        metaDiv.innerHTML = '&#9989; ' + manualCount + ' item manual ditambahkan';
        metaDiv.style.display = '';
      } else {
        metaDiv.style.display = 'none';
      }
    }

    if (!stok.length) { body.innerHTML = '<tr><td colspan="10" style="text-align:center;color:var(--text-secondary);padding:20px">Belum ada data stok. Import file Excel atau tambah item manual.</td></tr>'; return; }

    body.innerHTML = stok.map((item, i) => {
      const manualBadge = item.isManual
        ? '<span style="font-size:.63rem;background:#ede9fe;color:#5b21b6;border-radius:4px;padding:1px 5px;margin-left:4px;vertical-align:middle">MANUAL</span>'
        : '';
      const hapusBtn = item.isManual
        ? '<button class="tbl-btn" title="Hapus item manual" onclick="window._hapusHgpItemManual(\'' + item.noPart.replace(/'/g,"\\'") + '\')">' +
            '<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">' +
              '<polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14H6L5 6"/>' +
            '</svg>' +
          '</button>'
        : '';
      const zeroStyle = item.isManual ? ';color:#94a3b8' : '';
      return '<tr style="' + (item.isManual ? 'background:#faf5ff' : '') + '">' +
        '<td>' + (i + 1) + '</td>' +
        '<td style="font-family:monospace;font-size:.82rem">' + item.noPart + manualBadge + '</td>' +
        '<td>' + item.namaPart + '</td>' +
        '<td style="text-align:right' + zeroStyle + '">' + (item.awal ?? 0) + '</td>' +
        '<td style="text-align:right' + zeroStyle + '">' + (item.masuk ?? 0) + '</td>' +
        '<td style="text-align:right' + zeroStyle + '">' + (item.keluar ?? 0) + '</td>' +
        '<td style="text-align:right' + zeroStyle + '">' + (item.adjust ?? 0) + '</td>' +
        '<td style="text-align:right;font-weight:700;color:' + (item.isManual ? '#94a3b8' : '#0369a1') + '">' + (item.akhir ?? 0) + '</td>' +
        '<td style="font-size:.8rem;color:var(--text-secondary)">' + (item.keterangan || '') + '</td>' +
        '<td>' + hapusBtn + '</td>' +
        '</tr>';
    }).join('');
  }

  // ── Render Tab Pemeriksaan ───────────────────────────────────
  function _renderHgpPeriksaTab(stok, hasil, meta, ctx) {
    const noData = document.getElementById('hgpPeriksaNoData');
    const form   = document.getElementById('hgpPeriksaForm');
    const sel    = document.getElementById('hgpSelectPart');
    const metaDiv= document.getElementById('hgpPeriksaMetaInfo');
    if (!noData || !form) return;

    if (!stok.length) {
      noData.classList.remove('hidden');
      form.style.display = 'none';
      return;
    }
    noData.classList.add('hidden');
    form.style.display = '';

    if (metaDiv) {
      if (meta.unitUsaha || ctx) { metaDiv.innerHTML = '&#9989; ' + _hgpInfoBanner(meta, ctx); metaDiv.style.display = ''; }
      else metaDiv.style.display = 'none';
    }

    // Populate dropdown — tampilkan No Part + Nama Part lengkap
    if (sel) {
      const doneSet = new Set(hasil.map(h => h.noPart));
      sel.innerHTML = '<option value="">— Pilih No Part / Nama Part —</option>' +
        stok.map((item, i) => {
          const done     = doneSet.has(item.noPart);
          const codeTag  = item.noPart && !item.noPart.startsWith('ITEM-')
                         ? `[${item.noPart}]` : `(#${i+1})`;
          const label    = `${codeTag}  ${item.namaPart}${done ? '  ✓' : ''}`;
          const valKey   = item.noPart || String(i);
          return `<option value="${valKey}" ${done ? 'style="color:#166534;font-weight:600"' : ''}>${label}</option>`;
        }).join('');
    }

    // Progress
    const prog = document.getElementById('hgpPeriksaProgress');
    if (prog) prog.textContent = `${hasil.length} dari ${stok.length} item diperiksa`;

    // Set default tanggal
    const tgl = document.getElementById('hgpTglPeriksa');
    if (tgl && !tgl.value) tgl.value = new Date().toISOString().slice(0, 10);

    // Set pemeriksa
    const pem = document.getElementById('hgpPemeriksa');
    if (pem && !pem.value) pem.value = session.displayName || '';

    _renderHgpRiwayat(hasil);
  }

  // ── Render riwayat pemeriksaan (per scan log entry) ─────────
  function _renderHgpRiwayat(hasil) {
    const body = document.getElementById('hgpRiwayatBody');
    if (!body) return;
    if (!hasil.length) {
      body.innerHTML = '<tr><td colspan="12" style="text-align:center;color:var(--text-secondary);padding:16px">Belum ada hasil pemeriksaan</td></tr>';
      return;
    }

    let rows = '';
    let no   = 0;
    for (const h of hasil) {
      const selClr   = (h.selisih ?? 0) < 0 ? '#dc2626' : (h.selisih ?? 0) > 0 ? '#d97706' : '#166534';
      const scanLogs = h.scanLogs || [{ qty: h.fisikTotal || h.fisik || 0, fisikCum: h.fisikTotal || h.fisik || 0, saldoTersisa: (h.akhir||0) - (h.fisikTotal||h.fisik||0), tgl: h.tgl, pemeriksa: h.pemeriksa, keterangan: h.keterangan, savedAt: h.updatedAt || h.savedAt }];
      const totalScan = scanLogs.length;

      for (let si = 0; si < totalScan; si++) {
        const lg        = scanLogs[si];
        const sisaClr   = (lg.saldoTersisa ?? 0) < 0 ? '#dc2626' : (lg.saldoTersisa ?? 0) === 0 ? '#166534' : '#d97706';
        const isFirst   = si === 0;
        const isLast    = si === totalScan - 1;
        no++;

        const trBorder   = isFirst ? 'border-top:2px solid #e2e8f0' : 'border-top:1px dashed #f1f5f9';
        const noPartCell = isFirst
          ? '<td style="font-family:monospace;font-size:.77rem;font-weight:700">' + h.noPart + '</td>'
          : '<td></td>';
        const namaCell   = isFirst
          ? '<td style="font-size:.82rem;font-weight:600">' + h.namaPart + '</td>'
          : '<td><span style="color:#94a3b8;font-size:.72rem">&#x21B3; scan ke-' + (si+1) + '</span></td>';
        const akhirCell  = isFirst
          ? '<td style="text-align:right;font-weight:600">' + h.akhir + '</td>'
          : '<td></td>';
        const sisa       = lg.saldoTersisa !== undefined ? lg.saldoTersisa : (h.akhir - lg.fisikCum);
        const selSign    = (h.selisih >= 0) ? '+' : '';
        const selisihCell= isLast
          ? '<td style="text-align:right;font-weight:700;color:' + selClr + '">' + selSign + h.selisih + '</td>'
          : '<td></td>';
        const hapusBtn   = isLast
          ? '<button class="tbl-btn" title="Hapus semua log item ini" onclick="window._hapusHgpHasil(\'' + h.noPart + '\')"><svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14H6L5 6"/></svg></button>'
          : '';

        rows += '<tr style="' + trBorder + '">' +
          '<td style="color:#94a3b8;font-size:.75rem">' + no + '</td>' +
          '<td style="font-size:.74rem;white-space:nowrap;color:var(--text-secondary)">' + _hgpFmtWaktu(lg.savedAt) + '</td>' +
          noPartCell + namaCell + akhirCell +
          '<td style="text-align:right;color:#0284c7;font-weight:700">+' + lg.qty + '</td>' +
          '<td style="text-align:right;color:#2563eb;font-weight:700">' + lg.fisikCum + '</td>' +
          '<td style="text-align:right;font-weight:600;color:' + sisaClr + '">' + sisa + '</td>' +
          selisihCell +
          '<td style="font-size:.76rem">' + (lg.keterangan || '') + '</td>' +
          '<td style="font-size:.74rem;color:var(--text-secondary)">' + (lg.pemeriksa || '—') + '</td>' +
          '<td style="text-align:center">' + hapusBtn + '</td>' +
          '</tr>';
      }
    }
    body.innerHTML = rows;
  }

  // ── Render Tab Hasil ─────────────────────────────────────────
  function _renderHgpHasilTab(stok, hasil, wo, meta, ctx) {
    const metaDiv  = document.getElementById('hgpHasilMetaInfo');
    const body     = document.getElementById('hgpHasilBody');
    const summary  = document.getElementById('hgpHasilSummary');
    if (!body) return;

    if (metaDiv) {
      if (meta.unitUsaha || ctx) { metaDiv.innerHTML = '&#9989; ' + _hgpInfoBanner(meta, ctx); metaDiv.style.display = ''; }
      else metaDiv.style.display = 'none';
    }

    // ── Tombol Simpan ke Report Audit (hanya muncul jika ada konteks plan dari Audit) ──
    const simpanBar = document.getElementById('hgpSimpanPemBar');
    if (simpanBar) {
      if (ctx && ctx.planId && (hasil.length > 0 || (wo && wo.length > 0))) {
        const savedPem  = loadSavedPem();
        const isSaved   = savedPem.some(s => String(s.planId) === String(ctx.planId) && s.type === 'hgp');
        const savedAt   = isSaved ? savedPem.find(s => String(s.planId) === String(ctx.planId) && s.type === 'hgp').savedAt : null;
        const savedDate = savedAt ? new Date(savedAt).toLocaleString('id-ID', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '';
        simpanBar.innerHTML = `
          <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:14px;padding:12px 16px;
               background:${isSaved ? '#dcfce7' : '#f0f9ff'};border:1.5px solid ${isSaved ? '#86efac' : '#bae6fd'};
               border-radius:8px">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="${isSaved?'#166534':'#0369a1'}" stroke-width="2">
              <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/>
              <polyline points="17 21 17 13 7 13 7 21"/><polyline points="7 3 7 8 15 8"/>
            </svg>
            <div style="flex:1">
              <div style="font-size:.83rem;font-weight:700;color:${isSaved?'#166534':'#0369a1'}">
                ${isSaved ? '✓ Pemeriksaan HGP & AHM Oil\'s sudah disimpan ke Report Audit' : 'Simpan hasil ini ke Report Audit'}
              </div>
              <div style="font-size:.75rem;color:${isSaved?'#4ade80':'#64748b'};margin-top:2px">
                ${isSaved ? 'Tersimpan: ' + savedDate + ' &nbsp;·&nbsp; Plan: ' + ctx.noSPT : 'Plan: ' + ctx.noSPT + ' &nbsp;·&nbsp; ' + ctx.cabangPlan + ' &nbsp;·&nbsp; ' + (hasil.length) + ' item diperiksa'}
              </div>
            </div>
            <button onclick="window._simpanPemeriksaan('${ctx.planId}','hgp')"
                    style="background:${isSaved?'#16a34a':'#0369a1'};color:#fff;border:none;border-radius:7px;
                           padding:8px 18px;font-size:.83rem;font-weight:700;cursor:pointer;
                           display:flex;align-items:center;gap:6px;white-space:nowrap">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/>
                <polyline points="17 21 17 13 7 13 7 21"/><polyline points="7 3 7 8 15 8"/>
              </svg>
              ${isSaved ? 'Perbarui ke Report Audit' : 'Simpan ke Report Audit'}
            </button>
          </div>`;
      } else if (ctx && ctx.planId) {
        simpanBar.innerHTML = `
          <div style="margin-bottom:14px;padding:10px 16px;background:#fff7ed;border:1px solid #fed7aa;
               border-radius:8px;font-size:.82rem;color:#92400e">
            ⚠️ Lakukan pemeriksaan HGP & AHM Oil's terlebih dahulu sebelum dapat menyimpan ke Report Audit.
          </div>`;
      } else {
        simpanBar.innerHTML = '';
      }
    }

    // WO total per noPart
    const woMap  = _hgpWoTotal(wo || []);

    // Hitung summary (dengan WO)
    const hasilMap = {};
    hasil.forEach(h => { hasilMap[h.noPart] = h; });

    const totalItems   = stok.length;
    const diperiksa    = hasil.length;
    const belumPeriksa = totalItems - diperiksa;

    // Selisih = Fisik Scan + WO Gantung - Saldo Akhir
    // Dihitung jika ada fisik scan ATAU ada WO Gantung
    let selisihNeg = 0, selisihPos = 0, ok = 0;
    stok.forEach(item => {
      const h       = hasilMap[item.noPart];
      const woQty   = woMap[item.noPart] || 0;
      const fisikSc = h ? (h.fisikTotal || h.fisik || 0) : 0;
      const hasData = h !== undefined || woQty > 0;
      if (!hasData) return;
      const selisih = (fisikSc + woQty) - (item.akhir ?? 0);
      if (selisih < 0)      selisihNeg++;
      else if (selisih > 0) selisihPos++;
      else                  ok++;
    });
    const totalWOEntri = (wo || []).length;

    if (summary) {
      summary.innerHTML = [
        { label: 'Total Item',    val: totalItems,   bg: '#f0f9ff', clr: '#0369a1' },
        { label: 'Diperiksa',     val: diperiksa,    bg: '#f0fdf4', clr: '#166534' },
        { label: 'Belum',         val: belumPeriksa, bg: '#fff7ed', clr: '#92400e' },
        { label: 'WO Gantung',    val: totalWOEntri, bg: '#fffbeb', clr: '#b45309' },
        { label: 'Selisih &#8722;', val: selisihNeg, bg: '#fef2f2', clr: '#dc2626' },
        { label: 'Selisih +',     val: selisihPos,   bg: '#fefce8', clr: '#d97706' },
        { label: 'Sesuai',        val: ok,           bg: '#f0fdf4', clr: '#166534' },
      ].map(s => '<div style="background:' + s.bg + ';border-radius:8px;padding:10px 14px;text-align:center">' +
          '<div style="font-size:1.4rem;font-weight:800;color:' + s.clr + '">' + s.val + '</div>' +
          '<div style="font-size:.72rem;color:' + s.clr + ';margin-top:2px">' + s.label + '</div>' +
        '</div>').join('');
    }

    if (!stok.length) {
      body.innerHTML = '<tr><td colspan="16" style="text-align:center;color:var(--text-secondary);padding:20px">Belum ada data stok.</td></tr>';
      return;
    }

    let grandTotalJumlah = 0;

    const rows = stok.map((item, i) => {
      const h          = hasilMap[item.noPart];
      const fisikScan  = h ? (h.fisikTotal || h.fisik || 0) : null;
      const woQty      = woMap[item.noPart] || 0;
      const akhirSys   = item.akhir ?? 0;

      const hasData    = fisikScan !== null || woQty > 0;
      const fisikCalc  = fisikScan !== null ? fisikScan : 0;
      const totalFisik = hasData ? (fisikCalc + woQty) : null;
      const selisih    = hasData ? (totalFisik - akhirSys) : null;

      // HET lookup dari database HET berdasarkan kode part
      const hetRec  = loadHetDb().find(r => r.kodePart === item.noPart);
      const hetVal  = hetRec ? (hetRec.het || 0) : null;

      // Jumlah = |selisih| * HET (hanya jika selisih != 0 dan HET ada)
      const jumlah  = (selisih !== null && selisih !== 0 && hetVal !== null)
        ? Math.abs(selisih) * hetVal
        : null;

      if (jumlah !== null) grandTotalJumlah += jumlah;

      const selClr = selisih === null ? '#94a3b8' : selisih < 0 ? '#dc2626' : selisih > 0 ? '#d97706' : '#166534';
      const rowBg  = selisih === null ? '' : selisih !== 0 ? 'background:#fff8f8' : 'background:#f0fdf4';

      const fmtRp = v => v.toLocaleString('id-ID');

      return '<tr style="' + rowBg + '">' +
        '<td>' + (i + 1) + '</td>' +
        '<td style="font-family:monospace;font-size:.8rem">' + item.noPart + '</td>' +
        '<td>' + item.namaPart + '</td>' +
        '<td style="text-align:right">' + (item.awal ?? 0) + '</td>' +
        '<td style="text-align:right">' + (item.masuk ?? 0) + '</td>' +
        '<td style="text-align:right">' + (item.keluar ?? 0) + '</td>' +
        '<td style="text-align:right">' + (item.adjust ?? 0) + '</td>' +
        '<td style="text-align:right;font-weight:600;color:#0369a1">' + (item.akhir ?? 0) + '</td>' +
        '<td style="text-align:right;font-weight:700;color:' + (fisikScan !== null ? '#2563eb' : '#94a3b8') + '">' + (fisikScan !== null ? fisikScan : '—') + '</td>' +
        '<td style="text-align:right;font-weight:700;color:' + (woQty > 0 ? '#d97706' : '#94a3b8') + '">' + (woQty > 0 ? '+' + woQty : '—') + '</td>' +
        '<td style="text-align:right;font-weight:800;color:' + (totalFisik !== null ? '#0369a1' : '#94a3b8') + '">' + (totalFisik !== null ? totalFisik : '—') + '</td>' +
        '<td style="text-align:right;font-weight:700;color:' + selClr + '">' + (selisih !== null ? (selisih >= 0 ? '+' : '') + selisih : '—') + '</td>' +
        '<td style="text-align:right;font-size:.8rem;color:' + (hetVal !== null ? '#0891b2' : '#94a3b8') + '">' + (hetVal !== null ? fmtRp(hetVal) : '—') + '</td>' +
        '<td style="text-align:right;font-weight:700;color:' + (jumlah !== null ? (selisih < 0 ? '#dc2626' : '#d97706') : '#94a3b8') + '">' + (jumlah !== null ? fmtRp(jumlah) : '—') + '</td>' +
        '<td style="font-size:.78rem;color:var(--text-secondary)">' + (item.keterangan || '') + '</td>' +
        '<td style="font-size:.78rem">' + (h ? (h.keterangan || '') : '') + '</td>' +
        '</tr>';
    }).join('');

    // Baris total
    const totalRow = grandTotalJumlah > 0
      ? '<tr style="background:#fef2f2;font-weight:800;border-top:2px solid #dc2626">' +
          '<td colspan="13" style="text-align:right;font-size:.83rem;color:#dc2626;padding:8px 10px">TOTAL JUMLAH SELISIH</td>' +
          '<td style="text-align:right;font-size:.9rem;font-weight:800;color:#dc2626">' + grandTotalJumlah.toLocaleString('id-ID') + '</td>' +
          '<td colspan="2"></td>' +
        '</tr>'
      : '';

    body.innerHTML = rows + totalRow;
  }

  // ── Import XLS ──────────────────────────────────────────────
  function _importHgpXLS(file) {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = function(e) {
      try {
        const wb  = XLSX.read(new Uint8Array(e.target.result), { type: 'array' });
        const ws  = wb.Sheets[wb.SheetNames[0]];
        const raw = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });

        // ── Helpers ───────────────────────────────────────────────
        const norm = s => String(s ?? '').toUpperCase().trim().replace(/\s+/g, ' ');

        // Pola kode part: campuran huruf+angka, 4–25 karakter, tanpa spasi
        // Contoh: 06401K15900, 06401K45N41, AHM-OIL-10W-40, dst.
        function isPartCode(v) {
          const s = String(v ?? '').trim();
          return s.length >= 4 && s.length <= 30 &&
                 !s.includes(' ') &&
                 /[A-Z0-9]/.test(s.toUpperCase()) &&
                 /\d/.test(s) &&           // harus ada angka
                 /[A-Za-z]/.test(s);       // harus ada huruf
        }
        function isPlainNumber(v) { return /^\d{1,4}$/.test(String(v ?? '').trim()); }
        function isTextName(v) {
          const s = String(v ?? '').trim();
          return s.length >= 2 && /[A-Za-z]/.test(s) && !isPartCode(s);
        }

        // ── Deteksi header row ────────────────────────────────────
        const KEY_CODE = ['NO PART','NOPART','NO.PART','KODE PART','KODE','PART NO','PART NUMBER','NO. PART'];
        const KEY_NAME = ['NAMA PART','NAMAPART','NAMA BARANG','NAMA','DESKRIPSI','DESCRIPTION','ITEM NAME'];
        const KEY_END  = ['AKHIR','SALDO AKHIR','CLOSING'];
        const KEY_NUM  = ['AWAL','MASUK','KELUAR','ADJUST','AKHIR'];

        let headerRow = -1, bestScore = 0;
        for (let r = 0; r < Math.min(raw.length, 25); r++) {
          const cols = raw[r].map(c => norm(c));
          const s = (cols.some(c => KEY_CODE.includes(c)) ? 3 : 0) +
                    (cols.some(c => KEY_NAME.includes(c)) ? 3 : 0) +
                    (cols.some(c => KEY_END.includes(c))  ? 1 : 0) +
                    (KEY_NUM.filter(k => cols.includes(k)).length);
          if (s > bestScore) { bestScore = s; headerRow = r; }
          if (s >= 6) break;
        }
        if (headerRow < 0 || bestScore < 2) {
          showToast('Header kolom tidak ditemukan. Pastikan file format STOCK PART dengan kolom NO PART dan NAMA PART.', 'error');
          return;
        }

        // ── Mapping kolom ─────────────────────────────────────────
        const headers = raw[headerRow].map(c => norm(c));

        function findCol(keys) {
          for (const k of keys) { const i = headers.indexOf(k); if (i >= 0) return i; }
          for (const k of keys) { const i = headers.findIndex(h => h.includes(k)); if (i >= 0) return i; }
          return -1;
        }

        const colIdx = {
          noPart:     findCol(KEY_CODE),
          namaPart:   findCol(KEY_NAME),
          awal:       findCol(['AWAL','SALDO AWAL','OPENING']),
          masuk:      findCol(['MASUK','TERIMA','IN']),
          keluar:     findCol(['KELUAR','JUAL','KELUAR','OUT']),
          adjust:     findCol(['ADJUST','ADJUSMENT','PENYESUAIAN']),
          akhir:      findCol(KEY_END),
          keterangan: findCol(['KETERANGAN','KET','LOCATION','LOC','NOTE','NOTES']),
        };

        // ── Validasi via data sampel (4 baris pertama) ───────────
        // Kumpulkan baris data nyata
        const FOOTER_KEYS = ['VERSION','DILAPORKAN','DIKETAHUI','MENGETAHUI','TOTAL','HAL :'];
        const sampleRows  = [];
        for (let r = headerRow + 1; r < raw.length && sampleRows.length < 5; r++) {
          const row = raw[r];
          if (!row || !row.some(c => c && String(c).trim())) continue;
          const ru = row.map(c => norm(c)).join(' ');
          if (FOOTER_KEYS.some(k => ru.includes(k))) continue;
          if (isPlainNumber(row[0]) || !row[0]) sampleRows.push(row);
          else if (row.some(c => isPartCode(c))) sampleRows.push(row);
        }

        if (sampleRows.length > 0) {
          // Cek apakah noPart kolom terdeteksi benar
          const noPartVals  = sampleRows.map(r => String(r[colIdx.noPart]  ?? '').trim()).filter(Boolean);
          const namaPartVals= sampleRows.map(r => String(r[colIdx.namaPart] ?? '').trim()).filter(Boolean);

          const noPartHasCodes = noPartVals.some(v => isPartCode(v));
          const noPartAllText  = noPartVals.length > 0 && noPartVals.every(v => isTextName(v) && !isPartCode(v));

          // Jika noPart kolom tidak ada kode part → cari kolom yang tepat
          if (!noPartHasCodes || noPartAllText) {
            // Scan semua kolom header untuk cari yang berisi kode part
            let bestCodeCol = -1;
            for (let col = 0; col < headers.length; col++) {
              if (col === colIdx.namaPart || isPlainNumber(headers[col])) continue;
              const vals = sampleRows.map(r => String(r[col] ?? '').trim()).filter(Boolean);
              const codeCount = vals.filter(v => isPartCode(v)).length;
              if (codeCount >= Math.ceil(vals.length * 0.5) && codeCount > 0) {
                bestCodeCol = col;
                break;
              }
            }

            if (bestCodeCol >= 0 && bestCodeCol !== colIdx.noPart) {
              // Jika kolom noPart lama ternyata berisi nama → pindahkan ke namaPart
              if (noPartAllText && colIdx.namaPart < 0) {
                colIdx.namaPart = colIdx.noPart;
              }
              colIdx.noPart = bestCodeCol;
            }
          }

          // Jika namaPart masih kosong → cari kolom text setelah noPart
          const namaPartVals2 = sampleRows.map(r => String(r[colIdx.namaPart] ?? '').trim()).filter(Boolean);
          if (!namaPartVals2.some(v => isTextName(v))) {
            for (let col = 0; col < headers.length; col++) {
              if (col === colIdx.noPart || col === colIdx.awal || isPlainNumber(headers[col])) continue;
              const vals = sampleRows.map(r => String(r[col] ?? '').trim()).filter(Boolean);
              if (vals.some(v => isTextName(v)) && !vals.some(v => isPartCode(v))) {
                colIdx.namaPart = col;
                break;
              }
            }
          }
        }

        // ── Meta info (unit usaha & periode) ──────────────────────
        let unitUsaha = '', periodeAwal = '', periodeAkhir = '', tanggalFile = '';
        for (let r = 0; r < headerRow; r++) {
          const cells = raw[r].map(c => String(c ?? '').trim()).filter(Boolean);
          if (!unitUsaha && cells[0] && cells[0].length >= 3) {
            const v = cells[0].toUpperCase();
            if (!/^(NO|STOCK|PART|VERSION|VERSI|HAL|TOTAL)/.test(v)) unitUsaha = cells[0];
          }
          const rowUp = cells.map(c => c.toUpperCase());
          if (rowUp.some(c => c.includes('PERIODE'))) {
            const dates = cells.filter(c => /\d{1,2}[-\/]\d{2}[-\/]\d{4}/.test(c));
            if (dates[0]) periodeAwal  = dates[0];
            if (dates[1]) periodeAkhir = dates[1];
            if (!periodeAwal) {
              const pi = rowUp.findIndex(c => c.includes('PERIODE'));
              const si = rowUp.findIndex(c => c === 'S/D' || c === 'SD');
              if (pi >= 0 && cells[pi + 1]) periodeAwal  = cells[pi + 1];
              if (si >= 0 && cells[si + 1]) periodeAkhir = cells[si + 1];
            }
          }
        }
        for (let r = headerRow + 1; r < raw.length; r++) {
          const ru = raw[r].map(c => norm(c)).join(' ');
          if (ru.includes('VERSION') || ru.includes('VERSI')) {
            const d = raw[r].filter(c => /\d{2}-\d{2}-\d{4}/.test(String(c)));
            if (d.length) tanggalFile = String(d[0]);
            break;
          }
        }

        // ── Parse baris data ──────────────────────────────────────
        const stok = [];
        let rowNo = 0;
        for (let r = headerRow + 1; r < raw.length; r++) {
          const row = raw[r];
          if (!row || row.length === 0) continue;
          const ru = row.map(c => norm(c)).join(' ');
          if (FOOTER_KEYS.some(k => ru.includes(k))) continue;

          const noPart   = colIdx.noPart   >= 0 ? String(row[colIdx.noPart]   ?? '').trim() : '';
          const namaPart = colIdx.namaPart  >= 0 ? String(row[colIdx.namaPart] ?? '').trim() : '';

          if (!noPart && !namaPart) continue;
          if (isPlainNumber(noPart) && !namaPart) continue; // baris nomor urut saja

          const toNum = idx => {
            if (idx < 0) return 0;
            const v = String(row[idx] ?? '').replace(/[^\d-]/g, '');
            return parseInt(v) || 0;
          };

          rowNo++;
          stok.push({
            rowNo,
            noPart:     noPart     || ('ITEM-' + rowNo),
            namaPart:   namaPart   || noPart || '—',
            awal:       toNum(colIdx.awal),
            masuk:      toNum(colIdx.masuk),
            keluar:     toNum(colIdx.keluar),
            adjust:     toNum(colIdx.adjust),
            akhir:      toNum(colIdx.akhir),
            keterangan: colIdx.keterangan >= 0 ? String(row[colIdx.keterangan] ?? '').trim() : '',
          });
        }

        if (!stok.length) { showToast('Tidak ada data yang dapat diparse. Cek format file.', 'error'); return; }

        saveHgp(HGP_STOK_KEY, stok);
        saveHgpMeta({ unitUsaha, periodeAwal, periodeAkhir, tanggalFile, importedAt: new Date().toISOString() });

        renderHgpSection();
        const withCode = stok.filter(x => isPartCode(x.noPart)).length;
        showToast(`${stok.length} item berhasil diimport — ${withCode} item dengan kode No Part.`, 'success');
      } catch(err) {
        console.error('[HGP Import]', err);
        showToast('Gagal membaca file: ' + err.message, 'error');
      }
    };
    reader.readAsArrayBuffer(file);
  }

  // ── Helper: format waktu singkat ──────────────────────────
  function _hgpFmtWaktu(iso) {
    if (!iso) return '—';
    try {
      const d = new Date(iso);
      return d.toLocaleDateString('id-ID',{day:'2-digit',month:'2-digit',year:'numeric'}) +
             ' ' + d.toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit',second:'2-digit'});
    } catch { return iso; }
  }

  // ── Helper: update akumulasi banner & log di form ──────────
  function _hgpUpdateAccumDisplay(item, existing) {
    const akum       = existing ? (existing.fisikTotal || 0) : 0;
    const scanNo     = existing ? ((existing.scanLogs || []).length + 1) : 1;
    const akhir      = item.akhir ?? 0;
    const qtyNow     = parseInt(document.getElementById('hgpQtyFisik')?.value) || 0;
    // WO Gantung untuk item ini
    const wo         = loadHgp(HGP_WO_KEY);
    const woQty      = _hgpWoTotal(wo)[item.noPart] || 0;
    const totalFisik = akum + qtyNow + woQty; // fisik scan + WO
    const sisa       = akhir - totalFisik;
    const selisih    = totalFisik - akhir;

    // Banner akumulasi
    const banner = document.getElementById('hgpAkumBanner');
    if (banner) {
      if (akum > 0) {
        document.getElementById('hgpAkumFisik').textContent = akum;
        const sisaEl = document.getElementById('hgpAkumSisa');
        const sisaAkum = akhir - akum;
        sisaEl.textContent  = sisaAkum;
        sisaEl.style.color  = sisaAkum < 0 ? '#dc2626' : sisaAkum === 0 ? '#166534' : '#d97706';
        document.getElementById('hgpAkumScanNo').textContent = scanNo;
        banner.style.display = '';
      } else {
        banner.style.display = 'none';
      }
    }

    // Total fisik proyeksi
    const totEl = document.getElementById('hgpTotalFisik');
    if (totEl) { totEl.value = totalFisik; totEl.style.color = '#2563eb'; }

    // Saldo tersisa
    const sisaEl2 = document.getElementById('hgpSaldoTersisa');
    if (sisaEl2) {
      sisaEl2.value = sisa;
      sisaEl2.style.color = sisa < 0 ? '#dc2626' : sisa === 0 ? '#166534' : '#d97706';
    }

    // Selisih
    const selEl = document.getElementById('hgpSelisihVal');
    if (selEl) {
      selEl.value = selisih;
      selEl.style.color = selisih < 0 ? '#dc2626' : selisih > 0 ? '#d97706' : '#166534';
    }

    // Info simpan
    const infoEl = document.getElementById('hgpSimpanInfo');
    if (infoEl) {
      if (qtyNow > 0) {
        infoEl.textContent = `Akan menyimpan +${qtyNow} scan ke-${scanNo} → Total: ${totalFisik} | Sisa: ${sisa}`;
        infoEl.style.color = sisa < 0 ? '#dc2626' : '#166534';
      } else {
        infoEl.textContent = '';
      }
    }

    // Log scan textarea
    const logEl = document.getElementById('hgpLogScan');
    if (logEl) {
      const logs = existing?.scanLogs || [];
      const lines = logs.map((lg, i) =>
        `Scan #${i+1}  +${lg.qty} unit  |  ${_hgpFmtWaktu(lg.savedAt)}  |  ${lg.pemeriksa || '—'}  |  Kum: ${lg.fisikCum}  |  Sisa: ${akhir - lg.fisikCum}`
      );
      lines.push('─'.repeat(55));
      lines.push(`Total Terscan: ${akum}  |  Saldo Sistem: ${akhir}  |  Sisa: ${akhir - akum}`);
      logEl.value = lines.join('\n');
      logEl.scrollTop = logEl.scrollHeight;
    }
  }

  // ── Helper: isi form pemeriksaan dari item stok ─────────────
  function _hgpFillFormWithItem(item) {
    if (!item) return;
    const info   = document.getElementById('hgpSelectedInfo');
    const grid   = document.getElementById('hgpSelectedGrid');
    const fisikF = document.getElementById('hgpFisikForm');

    // Sync dropdown
    const sel = document.getElementById('hgpSelectPart');
    if (sel) sel.value = item.noPart;

    // Cek existing hasil dan WO untuk item ini
    const hasil    = loadHgp(HGP_HASIL_KEY);
    const woData   = loadHgp(HGP_WO_KEY);
    const existing = hasil.find(h => h.noPart === item.noPart);
    const akum     = existing ? (existing.fisikTotal || 0) : 0;
    const woQtyFill = _hgpWoTotal(woData)[item.noPart] || 0;

    // Set hidden akumulasi
    const akumEl = document.getElementById('hgpFisikAkum');
    if (akumEl) akumEl.value = akum;

    // Akhir
    const akhirInput = document.getElementById('hgpAkhirVal');
    if (akhirInput) akhirInput.value = item.akhir ?? 0;

    // Info grid
    if (grid) {
      const noPartDisplay = item.noPart && !item.noPart.startsWith('ITEM-')
        ? `<span style="font-family:monospace;font-size:.88rem;font-weight:700;color:#0369a1">${item.noPart}</span>`
        : '—';
      const scanCount  = existing?.scanLogs?.length || 0;
      const totalSoFar = akum + woQtyFill;
      grid.innerHTML = [
        { l: 'No Part',       v: noPartDisplay },
        { l: 'Nama Part',     v: '<strong>' + item.namaPart + '</strong>' },
        { l: 'Awal',          v: item.awal  ?? 0 },
        { l: 'Masuk',         v: item.masuk ?? 0 },
        { l: 'Keluar',        v: item.keluar ?? 0 },
        { l: 'Adjust',        v: item.adjust ?? 0 },
        { l: 'Akhir Sistem',  v: '<strong style="color:#0369a1;font-size:1rem">' + (item.akhir ?? 0) + '</strong>' },
        { l: 'Fisik Scan',    v: '<strong style="color:' + (akum>0?'#2563eb':'#94a3b8') + '">' + akum + '</strong> (' + scanCount + '&times;)' },
        { l: 'WO Gantung',    v: '<strong style="color:' + (woQtyFill>0?'#d97706':'#94a3b8') + '">' + (woQtyFill>0?'+':'') + woQtyFill + '</strong>' },
        { l: 'Total Fisik',   v: '<strong style="color:' + (totalSoFar>0?'#166534':'#94a3b8') + '">' + totalSoFar + '</strong>' },
        { l: 'Ket Sistem',    v: item.keterangan || '—' },
      ].map(r => '<div><span style="font-size:.68rem;text-transform:uppercase;opacity:.75;display:block;margin-bottom:2px">' + r.l + '</span>' + r.v + '</div>').join('');
    }
    if (info)   info.style.display  = '';
    if (fisikF) fisikF.style.display = '';

    // Reset qty, update display
    const qtyEl = document.getElementById('hgpQtyFisik');
    if (qtyEl) qtyEl.value = 0;
    const ketEl = document.getElementById('hgpKeterangan');
    if (ketEl) ketEl.value = '';

    _hgpUpdateAccumDisplay(item, existing);
    setTimeout(() => document.getElementById('hgpQtyFisik')?.focus(), 100);
  }

  // ── Event: pilih part dari dropdown ────────────────────────
  window._onHgpPartSelect = function () {
    const sel    = document.getElementById('hgpSelectPart');
    const valKey = sel?.value;
    if (!valKey) {
      document.getElementById('hgpSelectedInfo')?.style && (document.getElementById('hgpSelectedInfo').style.display = 'none');
      document.getElementById('hgpFisikForm')?.style    && (document.getElementById('hgpFisikForm').style.display    = 'none');
      return;
    }
    const stok = loadHgp(HGP_STOK_KEY);
    const item = stok.find(s => s.noPart === valKey) || stok[parseInt(valKey)] || null;
    _hgpFillFormWithItem(item);
  };

  // ── Scan / cari No Part ──────────────────────────────────
  window._hgpScanSearch = function () {
    const scanEl = document.getElementById('hgpScanInput');
    const msgEl  = document.getElementById('hgpScanMsg');
    const query  = (scanEl?.value || '').trim().toUpperCase();
    if (!query) return;

    const stok = loadHgp(HGP_STOK_KEY);
    if (!stok.length) {
      if (msgEl) { msgEl.textContent = '⚠ Belum ada data stok.'; msgEl.style.color = '#d97706'; msgEl.style.display = ''; }
      return;
    }

    let item = stok.find(s => s.noPart.toUpperCase() === query);
    if (!item) item = stok.find(s => s.noPart.toUpperCase().includes(query));
    if (!item) item = stok.find(s => s.namaPart.toUpperCase().includes(query));

    if (!item) {
      if (msgEl) {
        msgEl.innerHTML = `<span style="color:#dc2626">&#10007; Tidak ditemukan: <strong>"${query}"</strong></span>`;
        msgEl.style.display = '';
      }
      scanEl.select();
      return;
    }

    _hgpFillFormWithItem(item);
    if (msgEl) {
      const codeTag = item.noPart && !item.noPart.startsWith('ITEM-') ? `[${item.noPart}]` : '';
      msgEl.innerHTML = `<span style="color:#166534">&#10003; <strong>${codeTag} ${item.namaPart}</strong> — Akhir: <strong>${item.akhir}</strong></span>`;
      msgEl.style.display = '';
    }
    if (scanEl) { scanEl.value = ''; scanEl.focus(); }
  };

  window._hgpFisikChange = function(delta) {
    const el = document.getElementById('hgpQtyFisik');
    if (!el) return;
    el.value = Math.max(0, (parseInt(el.value) || 0) + delta);
    window._recalcHgpSelisih();
  };

  window._recalcHgpSelisih = function() {
    const noPart = document.getElementById('hgpSelectPart')?.value;
    if (!noPart) return;
    const stok = loadHgp(HGP_STOK_KEY);
    const item = stok.find(s => s.noPart === noPart);
    if (!item) return;
    const hasil    = loadHgp(HGP_HASIL_KEY);
    const existing = hasil.find(h => h.noPart === noPart);
    _hgpUpdateAccumDisplay(item, existing);
  };

  window._hgpClearForm = function() {
    const sel = document.getElementById('hgpSelectPart');
    if (sel) sel.value = '';
    document.getElementById('hgpSelectedInfo')?.style && (document.getElementById('hgpSelectedInfo').style.display = 'none');
    document.getElementById('hgpFisikForm')?.style    && (document.getElementById('hgpFisikForm').style.display    = 'none');
    document.getElementById('hgpAkumBanner')?.style   && (document.getElementById('hgpAkumBanner').style.display   = 'none');
    const akumEl = document.getElementById('hgpFisikAkum');
    if (akumEl) akumEl.value = 0;
  };

  // ── Simpan scan (AKUMULASI) ───────────────────────────────
  window._simpanHgpHasil = function() {
    const noPart  = document.getElementById('hgpSelectPart')?.value;
    const qtyNow  = parseInt(document.getElementById('hgpQtyFisik')?.value) || 0;
    const akhir   = parseInt(document.getElementById('hgpAkhirVal')?.value) || 0;
    const ket     = document.getElementById('hgpKeterangan')?.value?.trim() || '';
    const tgl     = document.getElementById('hgpTglPeriksa')?.value || new Date().toISOString().slice(0,10);
    const pem     = document.getElementById('hgpPemeriksa')?.value?.trim() || session.displayName;

    if (!noPart) { showToast('Pilih sparepart terlebih dahulu.', 'error'); return; }
    if (qtyNow <= 0) { showToast('Masukkan Qty Scan Ini > 0.', 'error'); return; }

    const stok = loadHgp(HGP_STOK_KEY);
    const item = stok.find(s => s.noPart === noPart);
    if (!item) { showToast('Item tidak ditemukan.', 'error'); return; }

    const hasil    = loadHgp(HGP_HASIL_KEY);
    const idx      = hasil.findIndex(h => h.noPart === noPart);
    const existing = idx >= 0 ? hasil[idx] : null;

    const prevTotal   = existing ? (existing.fisikTotal || 0) : 0;
    const newTotal    = prevTotal + qtyNow;
    const saldoSesudah = akhir - newTotal;
    const now         = new Date().toISOString();

    const newLog = {
      scanNo:      (existing?.scanLogs?.length || 0) + 1,
      qty:         qtyNow,
      fisikCum:    newTotal,
      saldoTersisa: saldoSesudah,
      tgl,
      pemeriksa:   pem,
      keterangan:  ket,
      savedAt:     now,
    };

    const rec = {
      noPart,
      namaPart:    item.namaPart,
      akhir,
      fisikTotal:  newTotal,
      selisih:     newTotal - akhir,
      keterangan:  ket,
      tgl,
      pemeriksa:   pem,
      updatedAt:   now,
      scanLogs:    [...(existing?.scanLogs || []), newLog],
    };

    if (idx >= 0) hasil[idx] = rec;
    else          hasil.push(rec);

    saveHgp(HGP_HASIL_KEY, hasil);

    // Update form: reset qty, update akumulasi display (tetap di item yg sama)
    const qtyEl = document.getElementById('hgpQtyFisik');
    if (qtyEl) qtyEl.value = 0;
    const akumEl = document.getElementById('hgpFisikAkum');
    if (akumEl) akumEl.value = newTotal;

    // Re-fill form dengan data terbaru
    _hgpFillFormWithItem(item);

    // Refresh riwayat
    _renderHgpRiwayat(loadHgp(HGP_HASIL_KEY));
    const prog = document.getElementById('hgpPeriksaProgress');
    if (prog) {
      const stokLen  = loadHgp(HGP_STOK_KEY).length;
      const hasilLen = loadHgp(HGP_HASIL_KEY).length;
      prog.textContent = `${hasilLen} dari ${stokLen} item diperiksa`;
    }
    _updateHgpBadge(loadHgp(HGP_HASIL_KEY).length);

    const scanNo = rec.scanLogs.length;
    const msg = `Scan #${scanNo} tersimpan — [${noPart}] ${item.namaPart}: +${qtyNow} → Total: ${newTotal} | Sisa: ${saldoSesudah}`;
    showToast(msg, saldoSesudah < 0 ? 'error' : saldoSesudah === 0 ? 'success' : 'info', 4000);
  };

  // ── Hapus satu hasil (semua log) ────────────────────────────
  window._hapusHgpHasil = function(noPart) {
    if (!confirm(`Hapus semua log scan untuk item ini?\n[${noPart}]`)) return;
    const hasil = loadHgp(HGP_HASIL_KEY).filter(h => h.noPart !== noPart);
    saveHgp(HGP_HASIL_KEY, hasil);
    renderHgpSection();
    showToast('Semua log scan item dihapus.', 'info');
  };

  // ── Hapus semua hasil ───────────────────────────────────────
  window._hapusSemuaHgpHasil = function() {
    if (!confirm('Hapus semua hasil pemeriksaan HGP & AHM Oil\'s?')) return;
    saveHgp(HGP_HASIL_KEY, []);
    renderHgpSection();
    showToast('Semua hasil pemeriksaan dihapus.', 'info');
  };

  /* ─────────────────────────────────────────────────────────────
     MODUL WO GANTUNG
     ───────────────────────────────────────────────────────────── */

  // ── Render Tab WO Gantung ────────────────────────────────────
  function _renderHgpWOTab(stok, wo, hasil, meta, ctx) {
    const metaDiv = document.getElementById('hgpWoMetaInfo');
    const body    = document.getElementById('hgpWoBody');
    const prog    = document.getElementById('hgpWoProgress');
    if (!body) return;

    if (metaDiv) {
      if (meta.unitUsaha || ctx) { metaDiv.innerHTML = '&#9888; WO Gantung &nbsp;&middot;&nbsp; ' + _hgpInfoBanner(meta, ctx); metaDiv.style.display = ''; }
      else metaDiv.style.display = 'none';
    }

    // Set default tgl & pemeriksa
    const tglEl = document.getElementById('hgpWoTgl');
    if (tglEl && !tglEl.value) tglEl.value = new Date().toISOString().slice(0, 10);
    const pemEl = document.getElementById('hgpWoPemeriksa');
    if (pemEl && !pemEl.value) pemEl.value = session.displayName || '';

    // Summary WO per noPart
    const woMap   = _hgpWoTotal(wo);
    const hasilMap = {};
    hasil.forEach(h => { hasilMap[h.noPart] = h.fisikTotal || 0; });

    if (prog) {
      const totalQtyWO  = wo.reduce((s, w) => s + (w.qty || 0), 0);
      const uniqueParts = Object.keys(woMap).length;
      prog.textContent  = `${wo.length} entri | ${uniqueParts} no part | Total Qty WO: ${totalQtyWO}`;
    }

    if (!wo.length) {
      body.innerHTML = '<tr><td colspan="12" style="text-align:center;color:var(--text-secondary);padding:16px">Belum ada data WO Gantung.</td></tr>';
      return;
    }

    // Kelompokkan per noPart, tampilkan per entri WO
    const stokMap = {};
    stok.forEach(s => { stokMap[s.noPart] = s; });

    let rows = '';
    let no   = 0;
    const groups = {};
    wo.forEach(w => {
      if (!groups[w.noPart]) groups[w.noPart] = [];
      groups[w.noPart].push(w);
    });

    for (const noPart of Object.keys(groups)) {
      const entries  = groups[noPart];
      const stokItem = stokMap[noPart];
      const akhir    = stokItem ? (stokItem.akhir ?? 0) : '—';
      const fisikScan = hasilMap[noPart] || 0;
      const woQty    = woMap[noPart] || 0;
      const totalFisik = fisikScan + woQty;

      for (let i = 0; i < entries.length; i++) {
        const w      = entries[i];
        const isFirst = i === 0;
        no++;

        rows += '<tr style="' + (isFirst ? 'border-top:2px solid #e2e8f0' : 'border-top:1px dashed #f1f5f9') + '">' +
          '<td style="color:#94a3b8;font-size:.75rem">' + no + '</td>' +
          '<td style="font-size:.74rem;white-space:nowrap;color:var(--text-secondary)">' + _hgpFmtWaktu(w.savedAt) + '</td>' +
          '<td style="font-family:monospace;font-size:.77rem' + (isFirst ? ';font-weight:700' : '') + '">' + (isFirst ? noPart : '') + '</td>' +
          '<td style="font-size:.82rem' + (isFirst ? ';font-weight:600' : '') + '">' + (isFirst ? (w.namaPart || '—') : '<span style="color:#94a3b8;font-size:.72rem">&#x21B3; WO #' + (i+1) + '</span>') + '</td>' +
          '<td style="font-size:.82rem;font-weight:600;color:#c2410c">' + (w.noWO || '—') + '</td>' +
          '<td style="text-align:right;font-weight:700;color:#d97706">+' + (w.qty || 0) + '</td>' +
          '<td style="text-align:right' + (isFirst ? ';font-weight:600' : '') + '">' + (isFirst ? akhir : '') + '</td>' +
          '<td style="text-align:right;color:#2563eb' + (isFirst ? ';font-weight:600' : '') + '">' + (isFirst ? fisikScan : '') + '</td>' +
          '<td style="text-align:right;color:#d97706;font-weight:700' + (isFirst ? '' : ';opacity:0') + '">' + (isFirst ? totalFisik : totalFisik) + '</td>' +
          '<td style="font-size:.76rem">' + (w.keterangan || '') + '</td>' +
          '<td style="font-size:.74rem;color:var(--text-secondary)">' + (w.pemeriksa || '—') + '</td>' +
          '<td><button class="tbl-btn" onclick="window._hapusHgpWO(\'' + w.id + '\')" title="Hapus entri ini">' +
            '<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">' +
              '<polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14H6L5 6"/>' +
            '</svg>' +
          '</button></td>' +
          '</tr>';
      }
    }
    body.innerHTML = rows;
  }

  // ── Scan cari item untuk WO form ────────────────────────────
  window._hgpWoScanSearch = function() {
    const scanEl = document.getElementById('hgpWoScanInput');
    const msgEl  = document.getElementById('hgpWoScanMsg');
    const query  = (scanEl?.value || '').trim().toUpperCase();
    if (!query) return;

    const stok = loadHgp(HGP_STOK_KEY);
    let item = stok.find(s => s.noPart.toUpperCase() === query);
    if (!item) item = stok.find(s => s.noPart.toUpperCase().includes(query));
    if (!item) item = stok.find(s => s.namaPart.toUpperCase().includes(query));

    if (!item) {
      if (msgEl) { msgEl.innerHTML = '<span style="color:#dc2626">&#10007; Tidak ditemukan: <strong>"' + query + '"</strong></span>'; msgEl.style.display = ''; }
      scanEl?.select();
      return;
    }

    _hgpWoFillForm(item);
    if (msgEl) {
      const hasil = loadHgp(HGP_HASIL_KEY);
      const h = hasil.find(x => x.noPart === item.noPart);
      const wo = loadHgp(HGP_WO_KEY);
      const woQty = _hgpWoTotal(wo)[item.noPart] || 0;
      msgEl.innerHTML = '<span style="color:#166534">&#10003; <strong>[' + item.noPart + '] ' + item.namaPart + '</strong> — Akhir: ' + item.akhir + ' | Fisik Scan: ' + (h ? h.fisikTotal : 0) + ' | WO: ' + woQty + '</span>';
      msgEl.style.display = '';
    }
    if (scanEl) { scanEl.value = ''; scanEl.focus(); }
  };

  function _hgpWoFillForm(item) {
    if (!item) return;
    const grid   = document.getElementById('hgpWoSelectedGrid');
    const form   = document.getElementById('hgpWoForm');
    const wo     = loadHgp(HGP_WO_KEY);
    const hasil  = loadHgp(HGP_HASIL_KEY);
    const woQty  = _hgpWoTotal(wo)[item.noPart] || 0;
    const fisikScan = (hasil.find(h => h.noPart === item.noPart)?.fisikTotal) || 0;
    const totalFisik = fisikScan + woQty;

    if (grid) {
      grid.innerHTML = [
        { l: 'No Part',      v: '<span style="font-family:monospace;font-weight:700;color:#c2410c">' + item.noPart + '</span>' },
        { l: 'Nama Part',    v: '<strong>' + item.namaPart + '</strong>' },
        { l: 'Akhir Sistem', v: '<strong style="color:#0369a1">' + (item.akhir ?? 0) + '</strong>' },
        { l: 'Fisik Scan',   v: '<span style="color:#2563eb;font-weight:600">' + fisikScan + '</span>' },
        { l: 'WO Gantung',   v: '<span style="color:#d97706;font-weight:600">' + woQty + ' (+ baru)</span>' },
        { l: 'Total Fisik',  v: '<strong style="color:#166534">' + totalFisik + '</strong>' },
      ].map(r => '<div><span style="font-size:.68rem;text-transform:uppercase;opacity:.75;display:block;margin-bottom:2px">' + r.l + '</span>' + r.v + '</div>').join('');
    }

    // Store current noPart in a hidden field
    const hidden = document.getElementById('hgpWoCurrentNoPart');
    if (!hidden) {
      const inp = document.createElement('input');
      inp.type = 'hidden';
      inp.id = 'hgpWoCurrentNoPart';
      document.getElementById('hgpWoForm')?.prepend(inp);
    }
    const noPartEl = document.getElementById('hgpWoCurrentNoPart');
    if (noPartEl) noPartEl.value = item.noPart;

    const namaEl = document.getElementById('hgpWoCurrentNamaPart');
    if (!namaEl) {
      const inp2 = document.createElement('input');
      inp2.type = 'hidden';
      inp2.id = 'hgpWoCurrentNamaPart';
      document.getElementById('hgpWoForm')?.prepend(inp2);
    }
    const namaPartEl = document.getElementById('hgpWoCurrentNamaPart');
    if (namaPartEl) namaPartEl.value = item.namaPart;

    if (form) form.style.display = '';

    // Info simpan
    const infoEl = document.getElementById('hgpWoSimpanInfo');
    if (infoEl) infoEl.textContent = 'Qty WO akan ditambahkan ke Total Fisik item ini.';
  }

  window._hgpWoQtyChange = function(delta) {
    const el = document.getElementById('hgpWoQty');
    if (!el) return;
    el.value = Math.max(1, (parseInt(el.value) || 1) + delta);
  };

  window._hgpWoClearForm = function() {
    const form = document.getElementById('hgpWoForm');
    if (form) form.style.display = 'none';
    const msgEl = document.getElementById('hgpWoScanMsg');
    if (msgEl) msgEl.style.display = 'none';
    const noWOEl = document.getElementById('hgpWoNoWO');
    if (noWOEl) noWOEl.value = '';
    const qtyEl = document.getElementById('hgpWoQty');
    if (qtyEl) qtyEl.value = 1;
    const ketEl = document.getElementById('hgpWoKet');
    if (ketEl) ketEl.value = '';
    const scanEl = document.getElementById('hgpWoScanInput');
    if (scanEl) { scanEl.value = ''; scanEl.focus(); }
  };

  // ── Simpan WO Gantung ────────────────────────────────────────
  window._simpanHgpWO = function() {
    const noPart  = document.getElementById('hgpWoCurrentNoPart')?.value || '';
    const namaPart = document.getElementById('hgpWoCurrentNamaPart')?.value || '';
    const noWO    = document.getElementById('hgpWoNoWO')?.value?.trim() || '';
    const qty     = parseInt(document.getElementById('hgpWoQty')?.value) || 0;
    const ket     = document.getElementById('hgpWoKet')?.value?.trim() || '';
    const tgl     = document.getElementById('hgpWoTgl')?.value || new Date().toISOString().slice(0, 10);
    const pem     = document.getElementById('hgpWoPemeriksa')?.value?.trim() || session.displayName;

    if (!noPart)  { showToast('Scan atau pilih No Part terlebih dahulu.', 'error'); return; }
    if (!noWO)    { showToast('No WO / No Faktur wajib diisi.', 'error'); return; }
    if (qty <= 0) { showToast('Qty WO harus > 0.', 'error'); return; }

    const wo = loadHgp(HGP_WO_KEY);
    const rec = {
      id:        Date.now() + '-' + Math.random().toString(36).slice(2, 6),
      noPart,
      namaPart,
      noWO,
      qty,
      keterangan: ket,
      tgl,
      pemeriksa:  pem,
      savedAt:    new Date().toISOString(),
    };
    wo.push(rec);
    saveHgp(HGP_WO_KEY, wo);

    // Reset form, lanjut input WO berikutnya
    const noWOEl = document.getElementById('hgpWoNoWO');
    if (noWOEl) noWOEl.value = '';
    const qtyEl  = document.getElementById('hgpWoQty');
    if (qtyEl)  qtyEl.value = 1;
    const ketEl  = document.getElementById('hgpWoKet');
    if (ketEl)  ketEl.value = '';

    const stok  = loadHgp(HGP_STOK_KEY);
    const hasil = loadHgp(HGP_HASIL_KEY);
    const meta  = loadHgpMeta();
    _renderHgpWOTab(stok, wo, hasil, meta);
    _updateHgpWoBadge(wo.length);

    // Update form info
    const stokItem = stok.find(s => s.noPart === noPart);
    if (stokItem) _hgpWoFillForm(stokItem);

    showToast('WO Gantung tersimpan — [' + noPart + '] +' + qty + ' (No WO: ' + noWO + ')', 'success', 4000);
  };

  // ── Hapus satu entri WO ──────────────────────────────────────
  window._hapusHgpWO = function(id) {
    if (!confirm('Hapus entri WO Gantung ini?')) return;
    const wo = loadHgp(HGP_WO_KEY).filter(w => w.id !== id);
    saveHgp(HGP_WO_KEY, wo);
    renderHgpSection();
    showToast('Entri WO Gantung dihapus.', 'info');
  };

  // ── Hapus semua WO ───────────────────────────────────────────
  window._hapusSemuaHgpWO = function() {
    if (!confirm('Hapus semua data WO Gantung?')) return;
    saveHgp(HGP_WO_KEY, []);
    renderHgpSection();
    showToast('Semua WO Gantung dihapus.', 'info');
  };

  // ── Export / Cetak PDF ──────────────────────────────────────
  window._cetakHgpPDF = function() {
    const stok  = loadHgp(HGP_STOK_KEY);
    const hasil = loadHgp(HGP_HASIL_KEY);
    const wo    = loadHgp(HGP_WO_KEY);
    const meta  = loadHgpMeta();
    const ctx   = _hgpPlanContext;
    if (!stok.length) { showToast('Belum ada data stok untuk dicetak.', 'error'); return; }

    const org      = (() => { try { return JSON.parse(localStorage.getItem('akta_org')) || {}; } catch { return {}; } })();
    const hasilMap = {};
    hasil.forEach(h => { hasilMap[h.noPart] = h; });
    const woMap    = _hgpWoTotal(wo);
    const hasWO    = Object.keys(woMap).length > 0;

    // Identitas laporan: prioritas plan, fallback file/org
    const unitLabel = ctx ? ctx.cabangPlan + (ctx.cabangArea ? ' [' + ctx.cabangArea + ']' : '') : (meta.unitUsaha || org.namaOrg || '');
    const planLabel = ctx ? (ctx.noSPT + ' — ' + ctx.jenisAudit + ' — ' + ctx.tanggalPlan) : '';
    const periodeLabel = meta.periodeAwal ? ('Periode Stok: ' + meta.periodeAwal + ' s/d ' + (meta.periodeAkhir || '—')) : '';

    let pdfGrandTotal = 0;
    const hetDb = loadHetDb();

    const rows = stok.map((item, i) => {
      const h          = hasilMap[item.noPart];
      const fisikScan  = h ? (h.fisikTotal || h.fisik || 0) : null;
      const woQty      = woMap[item.noPart] || 0;
      const akhirSys   = item.akhir ?? 0;

      const hasData    = fisikScan !== null || woQty > 0;
      const fisikCalc  = fisikScan !== null ? fisikScan : 0;
      const totalFisik = hasData ? (fisikCalc + woQty) : null;
      const selisih    = hasData ? (totalFisik - akhirSys) : null;

      // HET lookup
      const hetRec  = hetDb.find(r => r.kodePart === item.noPart);
      const hetVal  = hetRec ? (hetRec.het || 0) : null;
      const jumlah  = (selisih !== null && selisih !== 0 && hetVal !== null)
        ? Math.abs(selisih) * hetVal : null;
      if (jumlah !== null) pdfGrandTotal += jumlah;

      const fmtRp  = v => Number(v).toLocaleString('id-ID');
      const selClr = selisih === null ? '' : selisih < 0 ? 'color:#dc2626' : selisih > 0 ? 'color:#d97706' : 'color:#166534';
      const rowBg  = selisih !== null && selisih !== 0 ? 'background:#fff8f8' : '';

      return '<tr style="' + rowBg + '">' +
        '<td style="text-align:center">' + (i+1) + '</td>' +
        '<td style="font-family:monospace;font-size:9px">' + item.noPart + '</td>' +
        '<td>' + item.namaPart + '</td>' +
        '<td style="text-align:right">' + (item.awal??0) + '</td>' +
        '<td style="text-align:right">' + (item.masuk??0) + '</td>' +
        '<td style="text-align:right">' + (item.keluar??0) + '</td>' +
        '<td style="text-align:right">' + (item.adjust??0) + '</td>' +
        '<td style="text-align:right;font-weight:700">' + (item.akhir??0) + '</td>' +
        '<td style="text-align:right;font-weight:700;color:#2563eb">' + (fisikScan !== null ? fisikScan : '—') + '</td>' +
        (hasWO ? '<td style="text-align:right;font-weight:700;color:#d97706">' + (woQty > 0 ? '+'+woQty : '—') + '</td>' : '') +
        (hasWO ? '<td style="text-align:right;font-weight:800;color:#0369a1">' + (totalFisik !== null ? totalFisik : '—') + '</td>' : '') +
        '<td style="text-align:right;font-weight:700;' + selClr + '">' + (selisih !== null ? (selisih>=0?'+':'')+selisih : '—') + '</td>' +
        '<td style="text-align:right;font-size:8px;color:#0891b2">' + (hetVal !== null ? fmtRp(hetVal) : '—') + '</td>' +
        '<td style="text-align:right;font-weight:700;' + (jumlah !== null ? (selisih < 0 ? 'color:#dc2626' : 'color:#d97706') : '') + '">' + (jumlah !== null ? fmtRp(jumlah) : '—') + '</td>' +
        '<td style="font-size:9px">' + (item.keterangan||'') + '</td>' +
        '<td style="font-size:9px">' + (h ? (h.keterangan||'') : '') + '</td>' +
        '</tr>';
    }).join('');

    // Baris total jumlah
    const woColCount = hasWO ? 2 : 0;
    const baseColsBeforeTotal = 12 + woColCount; // NO+NOPART+NAMA+AWAL+MASUK+KELUAR+ADJUST+AKHIR+FISIK+WO+TOTAL+SELISIH
    const totalRow = pdfGrandTotal > 0
      ? '<tr style="background:#fef2f2;font-weight:800">' +
          '<td colspan="' + baseColsBeforeTotal + '" style="text-align:right;font-size:9px;color:#dc2626;padding:5px 6px">TOTAL JUMLAH SELISIH</td>' +
          '<td style="text-align:right;font-weight:800;color:#dc2626;font-size:10px">' + Number(pdfGrandTotal).toLocaleString('id-ID') + '</td>' +
          '<td colspan="2"></td>' +
        '</tr>'
      : '';

    const woColHeader = hasWO
      ? '<th style="background:#b45309">WO GANTUNG</th><th style="background:#0369a1">TOTAL FISIK</th>'
      : '';
    const selNote = hasWO ? ' (Fisik Scan + WO Gantung)' : '';

    const win = window.open('', '_blank');
    win.document.write('<!DOCTYPE html><html><head><meta charset="UTF-8"/>' +
      '<title>Laporan Stok Part &amp; Oli</title>' +
      '<style>' +
        'body{font-family:Arial,sans-serif;font-size:11px;margin:0;padding:10px}' +
        'table{width:100%;border-collapse:collapse}' +
        'th,td{border:1px solid #ccc;padding:4px 5px;font-size:9px}' +
        'th{background:#1e3a5f;color:#fff;text-align:center}' +
        '.hdr{text-align:center;margin-bottom:10px}' +
        '.meta{display:flex;justify-content:space-between;margin:4px 0;font-size:10px}' +
        '.foot{display:flex;justify-content:space-between;margin-top:28px}' +
        '.sign{width:45%;text-align:center}' +
        '@media print{@page{size:A4 landscape;margin:1cm}}' +
      '</style></head><body>' +
      '<div class="hdr">' +
        '<div style="font-size:11px;font-weight:700">' + unitLabel + '</div>' +
        '<h2 style="margin:4px 0;font-size:14px">STOCK PART &amp; OLI AHM</h2>' +
        (planLabel ? '<div style="font-size:9px;color:#1e40af">' + planLabel + '</div>' : '') +
        (periodeLabel ? '<div style="font-size:9px;color:#6b7280">' + periodeLabel + '</div>' : '') +
        (hasWO ? '<div style="font-size:9px;color:#b45309">&#9888; Termasuk WO Gantung</div>' : '') +
      '</div>' +
      '<div class="meta">' +
        '<span>' + (ctx ? 'No SPT: ' + ctx.noSPT : 'PERIODE : ' + (meta.periodeAwal || '—') + ' S/D ' + (meta.periodeAkhir || '—')) + '</span>' +
        '<span>Dicetak: ' + new Date().toLocaleDateString('id-ID',{day:'2-digit',month:'long',year:'numeric'}) + '</span>' +
      '</div>' +
      '<table><thead><tr>' +
        '<th>NO</th><th>NO PART</th><th>NAMA PART</th>' +
        '<th>AWAL</th><th>MASUK</th><th>KELUAR</th><th>ADJUST</th><th>AKHIR</th>' +
        '<th style="background:#1e40af">FISIK SCAN</th>' +
        woColHeader +
        '<th>SELISIH' + selNote + '</th>' +
        '<th style="background:#0891b2">HET (Rp)</th>' +
        '<th style="background:#b91c1c">JUMLAH (Rp)</th>' +
        '<th>KET SIS</th><th>KET PERIKSA</th>' +
      '</tr></thead><tbody>' + rows + totalRow + '</tbody></table>' +
      '<div class="foot">' +
        '<div class="sign"><p>DILAPORKAN OLEH,</p><br/><br/><br/><p>________________________</p></div>' +
        '<div class="sign"><p>DIKETAHUI OLEH,</p><br/><br/><br/><p>________________________</p></div>' +
      '</div>' +
      '<script>window.onload=function(){window.print();}<\/script>' +
      '</body></html>');
    win.document.close();
  };

  // ── Toggle form tambah manual ────────────────────────────────
  window._toggleHgpManualForm = function() {
    const form     = document.getElementById('hgpManualForm');
    const chevron  = document.getElementById('hgpManualChevron');
    if (!form) return;
    const isOpen = form.style.display !== 'none';
    form.style.display = isOpen ? 'none' : '';
    if (chevron) chevron.style.transform = isOpen ? '' : 'rotate(180deg)';
    if (!isOpen) document.getElementById('hgpManualNoPart')?.focus();
  };

  // ── Tambah item manual ke stok ──────────────────────────────
  window._tambahHgpItemManual = function() {
    const noPartEl  = document.getElementById('hgpManualNoPart');
    const namaEl    = document.getElementById('hgpManualNamaPart');
    const ketEl     = document.getElementById('hgpManualKet');
    const msgEl     = document.getElementById('hgpManualMsg');

    const noPart    = (noPartEl?.value  || '').trim();
    const namaPart  = (namaEl?.value    || '').trim();
    const keterangan= (ketEl?.value     || '').trim();

    function showMsg(txt, clr) {
      if (msgEl) { msgEl.textContent = txt; msgEl.style.color = clr || '#dc2626'; }
    }

    if (!noPart)   { showMsg('No Part wajib diisi.'); noPartEl?.focus();  return; }
    if (!namaPart) { showMsg('Nama Part wajib diisi.'); namaEl?.focus(); return; }

    const stok = loadHgp(HGP_STOK_KEY);

    // Cek duplikasi
    if (stok.some(s => s.noPart.toUpperCase() === noPart.toUpperCase())) {
      showMsg('No Part "' + noPart + '" sudah ada di daftar stok.');
      noPartEl?.select();
      return;
    }

    // Item manual: semua nilai = 0
    const newItem = {
      rowNo:      stok.length + 1,
      noPart,
      namaPart,
      awal:       0,
      masuk:      0,
      keluar:     0,
      adjust:     0,
      akhir:      0,
      keterangan,
      isManual:   true,
      addedAt:    new Date().toISOString(),
    };

    stok.push(newItem);
    saveHgp(HGP_STOK_KEY, stok);

    // Reset form
    if (noPartEl)  noPartEl.value  = '';
    if (namaEl)    namaEl.value    = '';
    if (ketEl)     ketEl.value     = '';
    showMsg('&#10003; [' + noPart + '] ' + namaPart + ' berhasil ditambahkan.', '#166534');

    renderHgpSection();
    noPartEl?.focus();
  };

  // ── Hapus item manual dari stok ──────────────────────────────
  window._hapusHgpItemManual = function(noPart) {
    const stok = loadHgp(HGP_STOK_KEY);
    const item = stok.find(s => s.noPart === noPart && s.isManual);
    if (!item) { showToast('Item tidak ditemukan.', 'error'); return; }
    if (!confirm('Hapus item manual "' + item.namaPart + '" [' + noPart + '] dari daftar stok?\nHasil pemeriksaan item ini juga akan dihapus.')) return;

    // Hapus dari stok
    saveHgp(HGP_STOK_KEY, stok.filter(s => !(s.noPart === noPart && s.isManual)));
    // Hapus juga dari hasil & WO jika ada
    saveHgp(HGP_HASIL_KEY, loadHgp(HGP_HASIL_KEY).filter(h => h.noPart !== noPart));
    saveHgp(HGP_WO_KEY,    loadHgp(HGP_WO_KEY).filter(w => w.noPart !== noPart));

    renderHgpSection();
    showToast('Item manual dihapus.', 'info');
  };

  // ── Setup event listeners HGP ────────────────────────────────
  (function _initHgp() {
    const browseBtn  = document.getElementById('hgpBrowse');
    const fileInput  = document.getElementById('hgpFile');
    const dropZone   = document.getElementById('hgpDropZone');
    const importBtn  = document.getElementById('btnImportHgp');
    const clearBtn   = document.getElementById('btnClearHgpStok');
    const resetBtn   = document.getElementById('btnResetHgp');
    const cetakBtn   = document.getElementById('btnCetakHgp');

    if (browseBtn && fileInput) browseBtn.addEventListener('click', () => fileInput.click());
    if (dropZone  && fileInput) {
      dropZone.addEventListener('click', () => fileInput.click());
      dropZone.addEventListener('dragover',  e => { e.preventDefault(); dropZone.style.borderColor = 'var(--primary)'; });
      dropZone.addEventListener('dragleave', () => dropZone.style.borderColor = '');
      dropZone.addEventListener('drop', e => {
        e.preventDefault();
        dropZone.style.borderColor = '';
        const f = e.dataTransfer.files[0];
        if (f) _importHgpXLS(f);
      });
    }
    if (importBtn && fileInput) importBtn.addEventListener('click', () => fileInput.click());
    if (fileInput) fileInput.addEventListener('change', e => { if (e.target.files[0]) _importHgpXLS(e.target.files[0]); });
    if (clearBtn) clearBtn.addEventListener('click', () => {
      if (!confirm('Hapus semua data stok yang diimport?')) return;
      saveHgp(HGP_STOK_KEY, []);
      saveHgpMeta({});
      renderHgpSection();
      showToast('Data stok dihapus.', 'info');
    });
    if (resetBtn) resetBtn.addEventListener('click', () => {
      if (!confirm('Reset semua data HGP (stok & hasil pemeriksaan)?')) return;
      saveHgp(HGP_STOK_KEY, []);
      saveHgp(HGP_HASIL_KEY, []);
      saveHgpMeta({});
      renderHgpSection();
      showToast('Semua data HGP & AHM Oil\'s direset.', 'info');
    });
    if (cetakBtn) cetakBtn.addEventListener('click', window._cetakHgpPDF);

    // Tab switching untuk hgpTab-*
    document.querySelectorAll('[data-tab-prefix="hgpTab-"] .smh-tab').forEach(btn => {
      btn.addEventListener('click', () => {
        const prefix = 'hgpTab-';
        const tabId  = btn.dataset.tab;
        document.querySelectorAll('[data-tab-prefix="hgpTab-"] .smh-tab').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        document.querySelectorAll('[id^="hgpTab-"]').forEach(el => el.classList.add('hidden'));
        const target = document.getElementById(prefix + tabId);
        if (target) target.classList.remove('hidden');
        if (tabId === 'periksa' || tabId === 'hasil') renderHgpSection();
      });
    });
  })();

  /* ============================================================
     MODUL PLAN AUDIT & TASK
     ============================================================ */
  const PLAN_KEY     = 'akta_plans';
  const TASK_KEY     = 'akta_tasks';
  const KAS_AUDIT_KEY  = 'akta_audit_kas';
  const REKOM_KEY      = 'akta_rekomendasi';

  function loadRekomendasi() { try { return JSON.parse(localStorage.getItem(REKOM_KEY)) || []; } catch { return []; } }
  function saveRekomendasi(d){ localStorage.setItem(REKOM_KEY, JSON.stringify(d)); window.API?.sync(REKOM_KEY, d); }

  function loadPlans()    { try { return JSON.parse(localStorage.getItem(PLAN_KEY))     || []; } catch { return []; } }
  function savePlans(d)   { localStorage.setItem(PLAN_KEY, JSON.stringify(d));   window.API?.sync(PLAN_KEY, d); }
  function loadTasks()    { try { return JSON.parse(localStorage.getItem(TASK_KEY))     || []; } catch { return []; } }
  function saveTasks(d)   { localStorage.setItem(TASK_KEY, JSON.stringify(d));   window.API?.sync(TASK_KEY, d); }
  function loadKasAudit() { try { return JSON.parse(localStorage.getItem(KAS_AUDIT_KEY)) || []; } catch { return []; } }
  function saveKasAudit(d){ localStorage.setItem(KAS_AUDIT_KEY, JSON.stringify(d)); window.API?.sync(KAS_AUDIT_KEY, d); }

  const SAVED_PEM_KEY = 'akta_saved_pemeriksaan';
  function loadSavedPem() { try { return JSON.parse(localStorage.getItem(SAVED_PEM_KEY)) || []; } catch { return []; } }
  function saveSavedPem(d){ localStorage.setItem(SAVED_PEM_KEY, JSON.stringify(d)); window.API?.sync(SAVED_PEM_KEY, d); }

  // ═══════════════════════════════════════════════════════════════
  // MT (Mekanik Tools) — Database & Pemeriksaan
  // ═══════════════════════════════════════════════════════════════

  const MT_DB_KEY  = 'akta_mt_database';
  const MT_PEM_KEY = 'akta_mt_pemeriksaan';

  function loadMtDb()     { try { return JSON.parse(localStorage.getItem(MT_DB_KEY))  || {baru:[],lama:[],fi:[]}; } catch { return {baru:[],lama:[],fi:[]}; } }
  function saveMtDb(d)    { localStorage.setItem(MT_DB_KEY, JSON.stringify(d)); window.API?.sync(MT_DB_KEY, d); }
  function loadMtPemAll() { try { return JSON.parse(localStorage.getItem(MT_PEM_KEY)) || []; } catch { return []; } }
  function saveMtPemAll(d){ localStorage.setItem(MT_PEM_KEY, JSON.stringify(d)); window.API?.sync(MT_PEM_KEY, d); }

  // ── Migrasi data lama (single rec → sessions array) ──────────
  function _migrateMtPemIfNeeded() {
    const all = loadMtPemAll();
    let changed = false;
    all.forEach(rec => {
      if (!rec.sessions) {
        rec.sessions = (rec.items?.length || rec.mekanik)
          ? [{ id: 'mt_mig_' + rec.planId, mekanik: rec.mekanik||'', jenis: rec.jenis||'baru',
               tgl: rec.tgl||'', items: rec.items||[], savedAt: rec.savedAt||null }]
          : [];
        delete rec.mekanik; delete rec.jenis; delete rec.items; delete rec.tgl; delete rec.savedAt;
        changed = true;
      }
    });
    if (changed) saveMtPemAll(all);
  }

  // ── Session helpers ──────────────────────────────────────────
  function loadMtSessions(planId) {
    _migrateMtPemIfNeeded();
    const rec = loadMtPemAll().find(r => String(r.planId) === String(planId));
    return rec?.sessions || [];
  }
  function saveMtSession(planId, sess) {
    _migrateMtPemIfNeeded();
    const all = loadMtPemAll();
    let rec = all.find(r => String(r.planId) === String(planId));
    if (!rec) { rec = { planId: String(planId), sessions: [] }; all.push(rec); }
    if (!rec.sessions) rec.sessions = [];
    const idx = rec.sessions.findIndex(s => s.id === sess.id);
    if (idx >= 0) rec.sessions[idx] = sess; else rec.sessions.push(sess);
    saveMtPemAll(all);
  }
  function deleteMtSessionById(planId, sessId) {
    const all = loadMtPemAll();
    const rec = all.find(r => String(r.planId) === String(planId));
    if (rec?.sessions) { rec.sessions = rec.sessions.filter(s => s.id !== sessId); saveMtPemAll(all); }
  }
  function getMtSessionById(planId, sessId) {
    return loadMtSessions(planId).find(s => s.id === sessId);
  }
  function newMtSession(jenis) {
    return { id: 'mt_' + Date.now() + '_' + Math.floor(Math.random()*9999),
             mekanik:'', jenis: jenis||'baru', tgl: new Date().toISOString().slice(0,10),
             items:[], savedAt:null };
  }

  // Compat shim agar kode lama tidak error
  function getMtPem(planId) {
    const sessions = loadMtSessions(planId);
    return sessions[0] || { planId:String(planId), mekanik:'', jenis:'baru', items:[], tgl:'', savedAt:null };
  }
  function saveMtPem(data) {
    if (data.id) saveMtSession(data.planId, data);
  }

