  window._mtLoadDefault = function(kat) {
    if (kat !== 'lama') { showToast('Data default hanya tersedia untuk MT Lama.','error'); return; }
    if (!confirm(`Muat ${MT_LAMA_DEFAULT.length} item data default MT Lama? Data yang ada akan diganti.`)) return;
    // Pertahankan gambar yang sudah ada berdasarkan kode
    const db  = loadMtDb();
    db.baru   = db.baru || [];
    db.fi     = db.fi   || [];
    const old = {};
    (db.lama || []).forEach(it => { if (it.kode) old[it.kode] = it; });
    db.lama = MT_LAMA_DEFAULT.map(it => ({
      ...it, gambar: old[it.kode]?.gambar || null
    }));
    saveMtDb(db);
    _renderMtDbContent('lama');
    showToast(`${MT_LAMA_DEFAULT.length} item MT Lama berhasil dimuat.`, 'success');
  };

  // ── Upload gambar per item ────────────────────────────────────
  window._mtDbUploadGambar = function(kat, idx) {
    const input = document.createElement('input');
    input.type = 'file'; input.accept = 'image/*';
    input.onchange = e => {
      const file = e.target.files[0]; if (!file) return;
      const reader = new FileReader();
      reader.onload = ev => {
        const img = new Image();
        img.onload = () => {
          const MAX = 240;
          let w = img.width, h = img.height;
          if (w > h) { if (w > MAX) { h = Math.round(h * MAX / w); w = MAX; } }
          else       { if (h > MAX) { w = Math.round(w * MAX / h); h = MAX; } }
          const cv = document.createElement('canvas');
          cv.width = w; cv.height = h;
          cv.getContext('2d').drawImage(img, 0, 0, w, h);
          const b64 = cv.toDataURL('image/jpeg', 0.72);
          const db = loadMtDb();
          if (db[kat]?.[idx]) { db[kat][idx].gambar = b64; saveMtDb(db); _renderMtDbContent(kat); showToast('Gambar berhasil diupload.','success'); }
        };
        img.src = ev.target.result;
      };
      reader.readAsDataURL(file);
    };
    input.click();
  };

  window._mtDbHapusGambar = function(kat, idx) {
    const db = loadMtDb();
    if (db[kat]?.[idx]) { delete db[kat][idx].gambar; saveMtDb(db); _renderMtDbContent(kat); }
  };

  function _renderMtDbContent(kat) {
    const el = document.getElementById(`mtDbContent-${kat}`);
    if (!el) return;
    const db   = loadMtDb();
    const items = db[kat] || [];
    const isAdm = session.role === 'adm' || session.role === 'admin';
    const fmtKat = { baru:'MT Baru', lama:'MT Lama', fi:'MT FI' };

    const tableRows = items.length
      ? items.map((it, i) => `
        <tr id="mtDbRow-${kat}-${i}">
          <td style="padding:4px 6px;border:1px solid #e5e7eb;text-align:center;font-size:.74rem;color:#9ca3af">${i+1}</td>
          <td style="padding:4px 8px;border:1px solid #e5e7eb;font-size:.78rem;font-weight:600;white-space:nowrap">${it.namaSingkat||''}</td>
          <td style="padding:4px 8px;border:1px solid #e5e7eb;font-size:.78rem">${it.nama||''}</td>
          <td style="padding:4px 8px;border:1px solid #e5e7eb;font-size:.74rem;font-family:monospace">${it.kode||'-'}</td>
          <td style="padding:4px 6px;border:1px solid #e5e7eb;text-align:center;width:90px">
            ${it.gambar
              ? `<div style="position:relative;display:inline-block">
                   <img src="${it.gambar}" style="width:64px;height:48px;object-fit:contain;border-radius:4px;border:1px solid #e5e7eb;cursor:pointer"
                        onclick="window._mtDbUploadGambar('${kat}',${i})" title="Klik untuk ganti gambar"/>
                   <button onclick="window._mtDbHapusGambar('${kat}',${i})"
                     style="position:absolute;top:-5px;right:-5px;background:#dc2626;color:#fff;border:none;border-radius:50%;width:16px;height:16px;font-size:9px;cursor:pointer;line-height:16px;padding:0" title="Hapus gambar">✕</button>
                 </div>`
              : (isAdm
                  ? `<button onclick="window._mtDbUploadGambar('${kat}',${i})"
                       style="background:#f0fdf4;color:#15803d;border:1px solid #86efac;border-radius:5px;padding:3px 8px;font-size:.7rem;cursor:pointer">
                       <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:middle;margin-right:2px"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>Upload
                     </button>`
                  : '-')
            }
          </td>
        </tr>`).join('')
      : `<tr><td colspan="5" style="text-align:center;color:var(--text-secondary);padding:18px">
           Belum ada data.${kat==='lama'&&isAdm?' Klik <strong>Muat Data Default</strong> atau import Excel.':' Import Excel terlebih dahulu.'}</td></tr>`;

    el.innerHTML = `
      ${!isAdm ? `<div class="no-permission-notice" style="margin-bottom:12px">⚠️ Hanya pengguna dengan role <strong>ADM</strong> yang dapat mengimport/mengubah data peralatan MT.</div>` : ''}
      ${isAdm ? `
      <div class="import-zone" id="mtDbDrop-${kat}" style="margin-bottom:12px;cursor:pointer">
        <svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" style="margin-bottom:8px"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>
        <p>Drag &amp; drop file Excel <strong>${fmtKat[kat]}</strong>, atau <strong id="mtDbBrowseLbl-${kat}" style="cursor:pointer;color:var(--primary)">klik untuk pilih file</strong></p>
        <div class="import-hint">Format: <code>Nama Singkat &nbsp;|&nbsp; Nama Peralatan (IND) &nbsp;|&nbsp; Kode Peralatan</code> &nbsp;atau&nbsp; <code>Nama Peralatan &nbsp;|&nbsp; Kode Peralatan</code> — <code>.xlsx</code> / <code>.xls</code></div>
        <input type="file" id="mtDbFile-${kat}" accept=".xlsx,.xls,.csv" hidden />
      </div>
      <div class="import-actions" style="margin-bottom:14px;flex-wrap:wrap;gap:8px">
        <span class="smh-stat" id="mtDbStat-${kat}">${items.length > 0 ? `${items.length} item` : 'Belum ada data'}</span>
        <button class="btn-clear-data" onclick="window._mtDbClear('${kat}')">Hapus Data</button>
        ${kat === 'lama' ? `<button onclick="window._mtLoadDefault('lama')" style="background:#0f4c81;color:#fff;border:none;border-radius:6px;padding:6px 12px;font-size:.8rem;cursor:pointer;font-weight:600">⬇ Muat Data Default MT Lama</button>` : ''}
        <button class="btn-import" onclick="document.getElementById('mtDbFile-${kat}').click()">Import Excel</button>
      </div>` : ''}
      <div class="kas-table-card">
        <div class="kas-table-header">
          <h3>Daftar ${fmtKat[kat]} <span style="font-size:.78rem;font-weight:400;color:var(--text-secondary)">(${items.length} item)</span></h3>
          <span style="font-size:.74rem;color:var(--text-secondary)">Klik kolom Gambar untuk upload foto referensi</span>
        </div>
        <div class="table-wrapper">
          <table class="kas-table">
            <thead><tr>
              <th style="width:32px">No</th>
              <th>Nama Singkat</th>
              <th>Nama Peralatan</th>
              <th>Kode Peralatan</th>
              <th style="width:90px;text-align:center">Gambar</th>
            </tr></thead>
            <tbody>${tableRows}</tbody>
          </table>
        </div>
      </div>`;

    if (isAdm) {
      const fileEl = document.getElementById(`mtDbFile-${kat}`);
      const dropEl = document.getElementById(`mtDbDrop-${kat}`);
      const lblEl  = document.getElementById(`mtDbBrowseLbl-${kat}`);
      if (lblEl) lblEl.onclick = () => fileEl?.click();
      if (fileEl) fileEl.onchange = e => { if (e.target.files[0]) _mtDbImport(kat, e.target.files[0]); };
      if (dropEl) {
        dropEl.ondragover = e => { e.preventDefault(); dropEl.style.background='#ede9fe'; };
        dropEl.ondragleave = () => { dropEl.style.background=''; };
        dropEl.ondrop = e => { e.preventDefault(); dropEl.style.background=''; if (e.dataTransfer.files[0]) _mtDbImport(kat, e.dataTransfer.files[0]); };
      }
    }
  }

  // ── Import Excel MT Database ──────────────────────────────────
  // Format yang didukung:
  //   3 kolom: Nama Singkat | Nama Lengkap | Kode Peralatan
  //   2 kolom: Nama Peralatan | Kode Peralatan
  //   Baris pertama bisa berupa header teks (dideteksi otomatis)
  // ── Format kolom yang didukung:
  //   3 kolom: Nama Singkat | Nama Peralatan (IND) | Kode Peralatan
  //   2 kolom: Nama Peralatan | Kode Peralatan
  //   Baris header teks dideteksi & dilewati otomatis
  //   Kode dengan/tanpa dash & leading-zero yang hilang ditangani otomatis
  function _mtDbImport(kat, file) {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = e => {
      try {
        const wb  = XLSX.read(e.target.result, { type:'binary' });
        const ws  = wb.Sheets[wb.SheetNames[0]];
        // raw:false agar kode dengan leading zero dikembalikan sebagai string
        const raw = XLSX.utils.sheet_to_json(ws, { header:1, defval:'', raw:false });

        const cl = s => String(s == null ? '' : s).replace(/[\r\n]+/g,' ').replace(/\s+/g,' ').trim();

        // Restore leading zero: kode angka ≥8 digit tanpa '0' di depan
        const clKode = s => {
          const str = cl(s);
          if (!str) return '';
          if (/^\d{8,}$/.test(str) && !str.startsWith('0')) return '0' + str;
          return str;
        };

        // Kode peralatan: mulai 0 + ≥7 alfanumerik/dash, ATAU angka ≥8 digit
        const isKode = s => {
          const str = clKode(cl(s));
          if (!str || str.length < 7) return false;
          return /^0[0-9A-Za-z\-]{6,}/.test(str) || /^\d{8,}/.test(str);
        };

        // Nomor urut baris: 1–4 digit saja
        const isRowNum = s => /^\d{1,4}$/.test(String(s||'').trim());

        // Normalisasi kode untuk lookup gambar (tanpa dash, uppercase)
        const normK = k => String(k||'').replace(/-/g,'').toUpperCase();
        const dbOld = loadMtDb();
        const oldMap = {};
        (dbOld[kat] || []).forEach(it => {
          if (it.kode) { oldMap[it.kode] = it; oldMap[normK(it.kode)] = it; }
        });

        const items = [];
        raw.forEach(r => {
          if (!r.some(v => v !== '' && v != null)) return;

          // Skip baris nomor urut di awal
          const off = isRowNum(r[0]) ? 1 : 0;

          // ── Kumpulkan sel non-kosong setelah offset ───────────
          // Ini mengatasi kolom kosong/gap di tengah Excel
          const cells = r.slice(off)
            .map(v => cl(v))
            .filter(s => s !== '');

          if (!cells.length) return;

          // Skip baris header
          if (/nama.*peralatan|kode.*peralatan|nama.*singkat|nama.*ind/i.test(cells.join(' '))) return;

          let namaSingkat = '', namaLengkap = '', kode = '';

          if (cells.length >= 3) {
            // Cek urutan kolom
            if (isKode(cells[2])) {
              // Urutan standar: Nama Singkat | Nama Peralatan | Kode
              namaSingkat = cells[0];
              namaLengkap = cells[1];
              kode        = clKode(cells[2]);
            } else if (isKode(cells[1])) {
              // Urutan alternatif: Nama Singkat | Kode | Nama Peralatan
              namaSingkat = cells[0];
              kode        = clKode(cells[1]);
              namaLengkap = cells[2];
            } else {
              namaSingkat = cells[0];
              namaLengkap = cells[1];
              kode        = '';
            }
          } else if (cells.length === 2) {
            if (isKode(cells[1])) {
              // 2 kolom: Nama | Kode
              namaSingkat = cells[0];
              namaLengkap = cells[0];
              kode        = clKode(cells[1]);
            } else if (isKode(cells[0])) {
              // 2 kolom: Kode | Nama
              kode        = clKode(cells[0]);
              namaSingkat = cells[1];
              namaLengkap = cells[1];
            } else {
              // 2 kolom teks: Nama Singkat | Nama Peralatan
              namaSingkat = cells[0];
              namaLengkap = cells[1];
              kode        = '';
            }
          } else {
            namaSingkat = cells[0];
            namaLengkap = cells[0];
            kode        = '';
          }

          if (!namaSingkat || namaSingkat.length < 2) return;

          const item = { namaSingkat, nama: namaLengkap || namaSingkat, kode };
          const prev = oldMap[item.kode] || oldMap[normK(item.kode)];
          if (prev?.gambar) item.gambar = prev.gambar;
          items.push(item);
        });

        if (!items.length) {
          showToast('Tidak ada data yang ditemukan. Format: Nama Singkat | Nama Peralatan | Kode', 'error');
          return;
        }
        const db = loadMtDb();
        db.baru = db.baru || []; db.lama = db.lama || []; db.fi = db.fi || [];
        db[kat] = items;
        saveMtDb(db);
        _renderMtDbContent(kat);
        showToast(`${items.length} item MT ${kat.toUpperCase()} berhasil diimport.`, 'success');
      } catch(ex) {
        showToast('Gagal membaca file. Pastikan format Excel benar.', 'error');
        console.error('[MT Import]', ex);
      }
    };
    reader.readAsBinaryString(file);
  }

  window._mtDbClear = function(kat) {
    if (!confirm(`Hapus semua data MT ${kat.toUpperCase()}?`)) return;
    const db = loadMtDb(); db.baru=db.baru||[]; db.lama=db.lama||[]; db.fi=db.fi||[]; db[kat]=[]; saveMtDb(db);
    _renderMtDbContent(kat);
    showToast(`Data MT ${kat.toUpperCase()} dihapus.`, 'success');
  };

  window._switchMtDbTab = function(kat) {
    ['baru','lama','fi'].forEach(k => {
      const c = document.getElementById(`mtDbContent-${k}`);
      const b = document.getElementById(`mtDbBtn${k.charAt(0).toUpperCase()+k.slice(1)}`);
      if (c) c.style.display = k === kat ? '' : 'none';
      if (b) {
        b.style.background     = k === kat ? 'var(--primary)' : '#f8fafc';
        b.style.color          = k === kat ? '#fff'           : '#374151';
        b.style.borderColor    = k === kat ? 'var(--primary)' : '#e2e8f0';
      }
    });
    _renderMtDbContent(kat);
  };

  let _mtPlanId    = null;
  let _mtTaskId    = null;
  let _mtCurJenis  = 'baru';
  let _mtCurSessId = null;   // ID sesi yang sedang diedit di form

  // ── Auto-save field mekanik & tgl ke sesi aktif ──────────────
  window._mtAutoSave = function() {
    if (!_mtPlanId || !_mtCurSessId) return;
    const sess = getMtSessionById(_mtPlanId, _mtCurSessId);
    if (!sess) return;
    sess.mekanik = (document.getElementById('mt_mekanik')?.value || '').trim();
    sess.tgl     = (document.getElementById('mt_tglPemeriksaan')?.value || '').trim();
    saveMtSession(_mtPlanId, sess);
    const titleEl = document.getElementById('mtFormTitle');
    if (titleEl) titleEl.textContent = sess.mekanik ? `Form MT — ${sess.mekanik}` : 'Form Pemeriksaan MT';
  };

  // ── Set Jenis & reload items di sesi aktif ───────────────────
  window._mtSetJenis = function(jenis) {
    _mtCurJenis = jenis;
    ['baru','lama','fi'].forEach(k => {
      const btn = document.getElementById(`mtJenisBtn${k.charAt(0).toUpperCase()+k.slice(1)}`);
      if (btn) { btn.className = k === jenis ? 'btn-primary' : 'btn-secondary'; btn.style.minWidth='90px'; }
    });
    if (_mtPlanId && _mtCurSessId) {
      const sess = getMtSessionById(_mtPlanId, _mtCurSessId);
      if (!sess) return;
      sess.jenis = jenis;
      _mtSyncItems(sess);
      saveMtSession(_mtPlanId, sess);
      _mtRenderItems(sess);
      _mtRenderStats(sess);
    }
  };

  // ── Sinkronisasi items sesi dengan DB ────────────────────────
  function _mtSyncItems(sess) {
    const db      = loadMtDb();
    const dbItems = db[sess.jenis] || [];
    const old     = {};
    (sess.items || []).forEach(it => { if (it.kode) old[it.kode] = it; });
    sess.items = dbItems.map(dbIt => {
      const prev = old[dbIt.kode] || {};
      return { namaSingkat: dbIt.namaSingkat||dbIt.nama||'', nama: dbIt.nama||dbIt.namaSingkat||'',
               kode: dbIt.kode||'', gambar: dbIt.gambar||null,
               kondisi: prev.kondisi||'bagus', ket: prev.ket||'' };
    });
  }

  // ── Simpan kondisi & keterangan item ─────────────────────────
  window._mtSetKondisi = function(idx, kondisi) {
    if (!_mtPlanId || !_mtCurSessId) return;
    const sess = getMtSessionById(_mtPlanId, _mtCurSessId);
    if (!sess?.items[idx]) return;
    sess.items[idx].kondisi = kondisi;
    saveMtSession(_mtPlanId, sess);
    _mtRenderStats(sess);
    const row = document.getElementById(`mtRow-${idx}`);
    if (row) {
      row.querySelectorAll('.mt-kondisi-btn').forEach(b => {
        const k = b.dataset.kondisi;
        const c = { bagus:'#16a34a', rusak:'#dc2626', hilang:'#d97706', sk_audit:'#7c3aed' };
        b.style.background = k === kondisi ? c[k] : '#f1f5f9';
        b.style.color      = k === kondisi ? '#fff' : '#374151';
        b.style.fontWeight = k === kondisi ? '700' : '400';
      });
    }
  };

  window._mtSetKet = function(idx, val) {
    if (!_mtPlanId || !_mtCurSessId) return;
    const sess = getMtSessionById(_mtPlanId, _mtCurSessId);
    if (!sess?.items[idx]) return;
    sess.items[idx].ket = val.trim();
    saveMtSession(_mtPlanId, sess);
  };

  // ── Render items list ─────────────────────────────────────────
  function _mtRenderItems(rec) {
    const el = document.getElementById('mtItemsSection');
    if (!el) return;
    const items = rec.items || [];
    if (!items.length) {
      el.innerHTML = `<div class="pem-card"><div class="pem-card-body" style="text-align:center;padding:24px;color:var(--text-secondary)">
        <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1" style="opacity:.3;margin-bottom:8px"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
        <p>Belum ada item. Import Database MT <strong>${rec.jenis.toUpperCase()}</strong> terlebih dahulu di menu <em>Database → Database MT</em>.</p>
      </div></div>`;
      return;
    }

    const styles = { bagus:'background:#16a34a;color:#fff;font-weight:700', rusak:'background:#dc2626;color:#fff;font-weight:700', hilang:'background:#d97706;color:#fff;font-weight:700', sk_audit:'background:#7c3aed;color:#fff;font-weight:700' };
    const def    = 'background:#f1f5f9;color:#374151';
    const labels = { bagus:'✔ Bagus', rusak:'✕ Rusak', hilang:'○ Hilang', sk_audit:'SK Audit' };

    const TH = 'padding:6px;background:#1e3a5f;color:#fff;font-size:.7rem;border:1px solid rgba(255,255,255,.15)';
    const rows = items.map((it, i) => {
      const btns = ['bagus','rusak','hilang','sk_audit'].map(k =>
        `<button class="mt-kondisi-btn" data-kondisi="${k}" onclick="window._mtSetKondisi(${i},'${k}')"
          style="border:none;border-radius:5px;padding:3px 9px;font-size:.72rem;cursor:pointer;transition:all .15s;${it.kondisi===k?styles[k]:def}">${labels[k]}</button>`
      ).join('');
      const thumb = it.gambar
        ? `<img src="${it.gambar}" style="width:52px;height:38px;object-fit:contain;border-radius:3px;border:1px solid #e5e7eb;display:block;margin:0 auto" title="${it.namaSingkat||it.nama}"/>`
        : `<span style="font-size:.65rem;color:#c0c4cc">—</span>`;
      return `<tr id="mtRow-${i}" style="background:${i%2===0?'#fff':'#f8fafc'}">
        <td style="padding:5px 6px;border:1px solid #e5e7eb;font-size:.74rem;text-align:center;color:#9ca3af">${i+1}</td>
        <td style="padding:4px 6px;border:1px solid #e5e7eb;text-align:center;width:58px">${thumb}</td>
        <td style="padding:5px 8px;border:1px solid #e5e7eb;font-size:.78rem;font-weight:700;color:#1e3a5f">${it.namaSingkat||it.nama}</td>
        <td style="padding:5px 8px;border:1px solid #e5e7eb;font-size:.76rem">${it.nama!==it.namaSingkat?it.nama:''}</td>
        <td style="padding:5px 8px;border:1px solid #e5e7eb;font-size:.72rem;font-family:monospace;white-space:nowrap">${it.kode||'-'}</td>
        <td style="padding:4px 6px;border:1px solid #e5e7eb">
          <div style="display:flex;gap:4px;flex-wrap:wrap">${btns}</div>
        </td>
        <td style="padding:3px 5px;border:1px solid #e5e7eb;min-width:110px">
          <input type="text" value="${(it.ket||'').replace(/"/g,'&quot;')}" placeholder="Keterangan…"
            oninput="window._mtSetKet(${i},this.value)"
            style="width:100%;border:1px solid #e5e7eb;border-radius:4px;padding:3px 6px;font-size:.72rem;background:#fff" />
        </td>
      </tr>`;
    }).join('');

    el.innerHTML = `<div class="pem-card">
      <div class="pem-card-header" style="background:#1e3a5f;color:#fff;padding:10px 16px;display:flex;align-items:center;justify-content:space-between">
        <span style="font-size:.85rem;font-weight:700;text-transform:uppercase">
          PERALATAN MT ${rec.jenis.toUpperCase()} — ${items.length} ITEM
        </span>
      </div>
      <div class="pem-card-body" style="padding:0;overflow-x:auto">
        <table style="width:100%;border-collapse:collapse;min-width:700px">
          <thead><tr>
            <th style="${TH};text-align:center;width:36px">NO.</th>
            <th style="${TH};text-align:center;width:58px">GAMBAR</th>
            <th style="${TH}">NAMA SINGKAT</th>
            <th style="${TH}">NAMA PERALATAN</th>
            <th style="${TH}">KODE</th>
            <th style="${TH};min-width:220px">KONDISI</th>
            <th style="${TH}">KETERANGAN</th>
          </tr></thead>
          <tbody>${rows}</tbody>
        </table>
      </div>
    </div>`;
  }

  // ── Render stats cards ────────────────────────────────────────
  function _mtRenderStats(rec) {
    const el = document.getElementById('mtStatsBar');
    if (!el) return;
    const items = rec.items || [];
    if (!items.length) { el.style.display='none'; return; }
    const cnt = { bagus:0, rusak:0, hilang:0, sk_audit:0 };
    items.forEach(it => { if (cnt[it.kondisi] !== undefined) cnt[it.kondisi]++; });
    const card = (lbl, val, bg, bd) =>
      `<div style="background:${bg};border:2px solid ${bd};border-radius:8px;padding:10px 16px;text-align:center;min-width:90px">
        <div style="font-size:1.1rem;font-weight:800;color:${bd}">${val}</div>
        <div style="font-size:.65rem;font-weight:700;text-transform:uppercase;color:#6b7280;margin-top:2px">${lbl}</div>
      </div>`;
    el.style.display='flex';
    el.innerHTML =
      card('Total',     items.length, '#eff6ff','#3b82f6') +
      card('Bagus',     cnt.bagus,    '#f0fdf4','#16a34a') +
      card('Rusak',     cnt.rusak,    '#fef2f2','#dc2626') +
      card('Hilang',    cnt.hilang,   '#fffbeb','#d97706') +
      card('SK Audit',  cnt.sk_audit, '#f5f3ff','#7c3aed');
  }

  // ── Render simpan bar (level plan — di luar form) ─────────────
  function _mtRenderSimpanBar() {
    const el = document.getElementById('mtSimpanBar');
    if (!el) return;
    const pid = _mtPlanId || '__standalone__';
    const sessions = loadMtSessions(pid);
    const hasAnyData = sessions.some(s => (s.items||[]).length > 0);
    if (!hasAnyData) { el.innerHTML = ''; return; }
    const savedList  = loadSavedPem();
    const isSaved    = savedList.some(s => String(s.planId) === String(pid) && s.type === 'pem_mt');
    const savedAt    = isSaved ? savedList.find(s => String(s.planId) === String(pid) && s.type === 'pem_mt')?.savedAt : null;
    const savedDate  = savedAt ? new Date(savedAt).toLocaleString('id-ID', {day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}) : '';
    const canSave    = pid !== '__standalone__';
    el.innerHTML = `
      <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;
           padding:12px 14px;background:${isSaved?'#dcfce7':'#f0f9ff'};border:1.5px solid ${isSaved?'#86efac':'#bae6fd'};border-radius:8px">
        <div>
          <div style="font-size:.82rem;font-weight:700;color:${isSaved?'#166534':'#0369a1'}">
            ${isSaved ? '✓ Sudah disimpan ke Report Audit' : '○ Belum disimpan ke Report Audit'}
          </div>
          ${savedDate ? `<div style="font-size:.72rem;color:#6b7280;margin-top:2px">Terakhir: ${savedDate}</div>` : ''}
        </div>
        <div style="display:flex;gap:8px;flex-wrap:wrap">
          <button onclick="window._mtPrintPDF()"
            style="background:#1e3a5f;color:#fff;border:none;border-radius:7px;padding:7px 16px;font-size:.82rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:6px">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 01-2-2v-5a2 2 0 012-2h16a2 2 0 012 2v5a2 2 0 01-2 2h-2"/>
              <rect x="6" y="14" width="12" height="8"/>
            </svg>Cetak PDF (${sessions.filter(s=>(s.items||[]).length>0).length} mekanik)
          </button>
          ${canSave ? `
          <button onclick="window._simpanPemeriksaan('${pid}','pem_mt')"
            style="background:${isSaved?'#16a34a':'#0369a1'};color:#fff;border:none;border-radius:7px;padding:7px 16px;font-size:.82rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:6px">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/>
              <polyline points="17 21 17 13 7 13 7 21"/>
            </svg>${isSaved ? 'Perbarui ke Report Audit' : 'Simpan ke Report Audit'}
          </button>` : ''}
        </div>
      </div>`;
  }

  // ── Render daftar sesi mekanik ────────────────────────────────
  function _mtRenderSessionList(pid) {
    const listEl = document.getElementById('mtSessionList');
    if (!listEl) return;
    const sessions = loadMtSessions(pid);
    const jenisBadge = j => {
      const m = { baru:'#7c3aed', lama:'#0369a1', fi:'#dc2626' };
      return `<span style="background:${(m[j]||'#374151')}22;color:${m[j]||'#374151'};border:1px solid ${(m[j]||'#374151')}44;border-radius:5px;padding:1px 8px;font-size:.7rem;font-weight:700;text-transform:uppercase">${j||'baru'}</span>`;
    };
    const BULAN = ['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agt','Sep','Okt','Nov','Des'];
    const fmtD = s => { if (!s) return '—'; const p=s.split('-'); if(p.length!==3) return s; const [y,m,d]=p.map(Number); return `${d} ${BULAN[m-1]||m} ${y}`; };
    const cards = sessions.map((sess) => {
      const items = sess.items || [];
      const cnt = { bagus:0, rusak:0, hilang:0, sk_audit:0 };
      items.forEach(it => { if(cnt[it.kondisi]!==undefined) cnt[it.kondisi]++; });
      const hasIssue = cnt.rusak > 0 || cnt.hilang > 0 || cnt.sk_audit > 0;
      return `
        <div style="background:#fff;border:1.5px solid ${hasIssue?'#fca5a5':'#e2e8f0'};border-radius:8px;padding:12px 14px;margin-bottom:8px;display:flex;flex-wrap:wrap;align-items:center;gap:10px">
          <div style="flex:1;min-width:160px">
            <div style="display:flex;align-items:center;gap:6px;margin-bottom:4px">
              <span style="font-weight:700;font-size:.92rem">${sess.mekanik || '<em style="color:#9ca3af;font-style:italic">Nama belum diisi</em>'}</span>
              ${jenisBadge(sess.jenis)}
            </div>
            <div style="font-size:.75rem;color:#6b7280">${fmtD(sess.tgl)}</div>
          </div>
          ${items.length ? `
          <div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center">
            <span style="font-size:.72rem;padding:2px 7px;border-radius:7px;background:#eff6ff;color:#1e40af;font-weight:600">${items.length} item</span>
            ${cnt.bagus>0?`<span style="font-size:.72rem;padding:2px 7px;border-radius:7px;background:#f0fdf4;color:#16a34a;font-weight:600">✔ ${cnt.bagus}</span>`:''}
            ${cnt.rusak>0?`<span style="font-size:.72rem;padding:2px 7px;border-radius:7px;background:#fef2f2;color:#dc2626;font-weight:600">✕ ${cnt.rusak}</span>`:''}
            ${cnt.hilang>0?`<span style="font-size:.72rem;padding:2px 7px;border-radius:7px;background:#fffbeb;color:#d97706;font-weight:600">○ ${cnt.hilang}</span>`:''}
            ${cnt.sk_audit>0?`<span style="font-size:.72rem;padding:2px 7px;border-radius:7px;background:#f5f3ff;color:#7c3aed;font-weight:600">SK ${cnt.sk_audit}</span>`:''}
          </div>` : `<span style="font-size:.75rem;color:#9ca3af;font-style:italic">Belum ada item — klik Edit &amp; pilih jenis</span>`}
          <div style="display:flex;gap:6px;flex-shrink:0">
            <button onclick="window._mtOpenForm('${sess.id}')"
              style="background:#1e3a5f;color:#fff;border:none;border-radius:6px;padding:5px 14px;font-size:.78rem;cursor:pointer;font-weight:600">
              ✏ Edit
            </button>
            <button onclick="window._mtDeleteSession('${sess.id}')"
              style="background:#fee2e2;color:#dc2626;border:1px solid #fca5a5;border-radius:6px;padding:5px 10px;font-size:.78rem;cursor:pointer;font-weight:600"
              title="Hapus sesi mekanik ini">✕</button>
          </div>
        </div>`;
    }).join('');
    const addBtn = `
      <button onclick="window._mtOpenForm(null)"
        style="width:100%;background:#f0fdf4;color:#16a34a;border:2px dashed #86efac;border-radius:8px;padding:10px;font-size:.82rem;font-weight:700;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:6px">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/>
        </svg>Tambah Mekanik Baru
      </button>`;
    listEl.innerHTML = sessions.length
      ? `<div style="font-size:.82rem;color:#6b7280;font-weight:600;margin-bottom:8px">${sessions.length} mekanik diperiksa</div>${cards}${addBtn}`
      : `<div style="text-align:center;padding:20px 16px;background:#f8fafc;border-radius:8px;margin-bottom:10px;color:var(--text-secondary)">
           <p style="margin-bottom:10px;font-size:.85rem">Belum ada data pemeriksaan MT.<br>Klik tombol di bawah untuk menambah mekanik.</p>
         </div>${addBtn}`;
  }

  // ── Buka form edit/tambah sesi ────────────────────────────────
  window._mtOpenForm = function(sessId) {
    const pid = _mtPlanId || '__standalone__';
    let sess;
    if (!sessId) {
      sess = newMtSession(_mtCurJenis || 'baru');
      saveMtSession(pid, sess);
    } else {
      sess = getMtSessionById(pid, sessId);
      if (!sess) { showToast('Sesi tidak ditemukan.', 'error'); return; }
    }
    _mtCurSessId = sess.id;
    _mtCurJenis  = sess.jenis || 'baru';

    const _s = (id, val) => { const el = document.getElementById(id); if (el) el.value = val||''; };
    _s('mt_mekanik', sess.mekanik);
    _s('mt_tglPemeriksaan', sess.tgl || new Date().toISOString().slice(0,10));

    // _mtSetJenis syncs items, renders items & stats
    window._mtSetJenis(_mtCurJenis);

    const titleEl = document.getElementById('mtFormTitle');
    if (titleEl) titleEl.textContent = sess.mekanik ? `Form MT — ${sess.mekanik}` : 'Form Pemeriksaan MT';

    const formSec  = document.getElementById('mtFormSection');
    const listSec  = document.getElementById('mtSessionList');
    const simpanB  = document.getElementById('mtSimpanBar');
    if (formSec)  formSec.style.display  = '';
    if (listSec)  listSec.style.display  = 'none';
    if (simpanB)  simpanB.style.display  = 'none';

    _mtRenderFormSaveBar();
  };

  // ── Tutup form, kembali ke daftar sesi ───────────────────────
  window._mtCloseForm = function() {
    _mtCurSessId = null;
    const formSec = document.getElementById('mtFormSection');
    const listSec = document.getElementById('mtSessionList');
    const simpanB = document.getElementById('mtSimpanBar');
    if (formSec)  formSec.style.display  = 'none';
    if (listSec)  listSec.style.display  = '';
    if (simpanB)  simpanB.style.display  = '';
    const pid = _mtPlanId || '__standalone__';
    _mtRenderSessionList(pid);
    _mtRenderSimpanBar();
  };

  // ── Hapus sesi mekanik ───────────────────────────────────────
  window._mtDeleteSession = function(sessId) {
    if (!confirm('Hapus data pemeriksaan mekanik ini?')) return;
    const pid = _mtPlanId || '__standalone__';
    deleteMtSessionById(pid, sessId);
    _mtRenderSessionList(pid);
    _mtRenderSimpanBar();
    showToast('Sesi pemeriksaan dihapus.', 'success');
  };

  // ── Render save bar di dalam form (auto-save notice + done btn)
  function _mtRenderFormSaveBar() {
    const el = document.getElementById('mtFormSaveBar');
    if (!el) return;
    el.innerHTML = `
      <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;
           padding:10px 14px;background:#f0fdf4;border:1.5px solid #86efac;border-radius:8px;margin-top:4px">
        <span style="font-size:.78rem;color:#166534;font-weight:600">✔ Data tersimpan otomatis</span>
        <button onclick="window._mtCloseForm()"
          style="background:#1e3a5f;color:#fff;border:none;border-radius:7px;padding:7px 18px;font-size:.82rem;font-weight:700;cursor:pointer">
          ✔ Selesai — Kembali ke Daftar
        </button>
      </div>`;
  }

  // ── Render semua (session list + simpan bar) ─────────────────
  function _mtRenderAll() {
    const pid = _mtPlanId || '__standalone__';
    _mtRenderSessionList(pid);
    _mtRenderSimpanBar();
  }

  // ── Buka Pemeriksaan MT ──────────────────────────────────────
  window._openMtPem = function(taskId) {
    if (taskId) {
      tasks = loadTasks();
      const t = tasks.find(x => String(x.id) === String(taskId));
      if (!t) return;
      _mtTaskId = taskId;
      _mtPlanId = t.planId;
      const infoEl = document.getElementById('mtPlanInfo');
      if (infoEl) infoEl.innerHTML = `<div class="unit-info-grid">
        <div class="unit-info-item"><label>No SPT</label><span style="font-weight:700">${t.noSPT}</span></div>
        <div class="unit-info-item"><label>Jenis Audit</label><span>${t.jenisAudit}</span></div>
        <div class="unit-info-item"><label>Cabang</label><span>${t.cabangPlan}${t.cabangArea?' '+areaBadge(t.cabangArea):''}</span></div>
        <div class="unit-info-item"><label>Status</label><span>${taskStatusBadge(t.status)}</span></div>
      </div>`;
      const banner    = document.getElementById('mtPlanBanner');
      const bannerCnt = document.getElementById('mtPlanBannerContent');
      if (banner && bannerCnt) {
        bannerCnt.innerHTML = `<span><strong>${t.noSPT||'—'}</strong></span><span style="opacity:.6">|</span><span>🏢 ${t.cabangPlan||'—'}</span><span style="opacity:.6">|</span><span>📋 ${t.jenisAudit||'—'}</span>`;
        banner.style.display = '';
      }
    } else {
      _mtTaskId = null;
      _mtPlanId = '__standalone__';
    }

    _mtCurSessId = null;
    const _mtOpenFSec = document.getElementById('mtFormSection');
    if (_mtOpenFSec) _mtOpenFSec.style.display = 'none';

    document.querySelectorAll('.content-section').forEach(s => s.classList.add('hidden'));
    document.querySelectorAll('.nav-item').forEach(li => li.classList.remove('active'));
    const sec    = document.getElementById('section-pemeriksaan-mt');
    const navAudit = document.querySelector('.nav-item[data-section="audit"]');
    if (sec)      sec.classList.remove('hidden');
    if (navAudit) navAudit.classList.add('active');
    _mtRenderAll();
  };

  // ── Kembali ──────────────────────────────────────────────────
  window._closeMtPem = function() {
    const banner = document.getElementById('mtPlanBanner');
    if (banner) banner.style.display = 'none';
    _mtTaskId = null; _mtPlanId = null;
    document.querySelectorAll('.content-section').forEach(s => s.classList.add('hidden'));
    document.querySelectorAll('.nav-item').forEach(li => li.classList.remove('active'));
    const targetSec = document.getElementById('section-audit');
    const targetNav = document.querySelector('.nav-item[data-section="audit"]');
    if (targetSec) targetSec.classList.remove('hidden');
    if (targetNav) targetNav.classList.add('active');
    if (typeof renderAuditSection === 'function') renderAuditSection();
  };

  // ── Standalone nav (tanpa task context) ──────────────────────
  // (ditangani oleh section switch di auth.js nav handler)

  // ── Print PDF semua sesi ─────────────────────────────────────
  window._mtPrintPDF = function() {
    const pid      = _mtPlanId || '__standalone__';
    const sessions = loadMtSessions(pid).filter(s => (s.items||[]).length > 0);
    if (!sessions.length) { showToast('Belum ada data untuk dicetak.', 'error'); return; }

    const BULAN    = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
    const fmtD     = s => { if (!s) return '—'; const p=s.split('-'); if(p.length!==3) return s; const [y,m,d]=p.map(Number); return `${d} ${BULAN[m-1]||m} ${y}`; };
    const lblK     = { bagus:'V', rusak:'X', hilang:'O', sk_audit:'SK' };
    const clrK     = { bagus:'#16a34a', rusak:'#dc2626', hilang:'#d97706', sk_audit:'#7c3aed' };

    const tasks2   = loadTasks();
    const task2    = tasks2.find(t => String(t.planId) === String(pid));

    const sessHtml = sessions.map((sess, si) => {
      const items = sess.items || [];
      const cnt   = { bagus:0, rusak:0, hilang:0, sk_audit:0 };
      items.forEach(it => { if(cnt[it.kondisi]!==undefined) cnt[it.kondisi]++; });
      const rows  = items.map((it, i) => `<tr>
        <td style="text-align:center">${i+1}</td>
        <td style="text-align:center;padding:2px">${it.gambar?`<img src="${it.gambar}" style="width:36px;height:26px;object-fit:contain"/>`:''}</td>
        <td style="font-weight:700">${it.namaSingkat||it.nama}</td>
        <td>${it.nama!==it.namaSingkat?it.nama:''}</td>
        <td style="font-family:monospace;font-size:7px">${it.kode||'-'}</td>
        <td style="text-align:center;font-weight:700;color:${clrK[it.kondisi]||'#374151'}">${lblK[it.kondisi]||'-'}</td>
        <td>${it.ket||''}</td>
      </tr>`).join('');
      return `
        ${si > 0 ? '<div style="page-break-before:always"></div>' : ''}
        <div class="hdr">
          <h2>LAPORAN PEMERIKSAAN PERALATAN MEKANIK</h2>
          ${task2 ? `<p>${task2.cabangPlan||'—'}${task2.cabangArea?' ('+task2.cabangArea+')':''}</p>` : ''}
        </div>
        <div class="info">
          <div>Mekanik #${si+1}&nbsp;&nbsp;&nbsp;&nbsp;: <strong>${sess.mekanik||'—'}</strong></div>
          <div>Tanggal&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;: ${fmtD(sess.tgl)}</div>
          <div>Jenis MT&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;: MT ${(sess.jenis||'baru').toUpperCase()}</div>
        </div>
        <div class="stats">
          <div class="stat-box"><strong>${items.length}</strong><br>Total</div>
          <div class="stat-box" style="color:#16a34a"><strong>${cnt.bagus}</strong><br>Bagus (V)</div>
          <div class="stat-box" style="color:#dc2626"><strong>${cnt.rusak}</strong><br>Rusak (X)</div>
          <div class="stat-box" style="color:#d97706"><strong>${cnt.hilang}</strong><br>Hilang (O)</div>
          <div class="stat-box" style="color:#7c3aed"><strong>${cnt.sk_audit}</strong><br>SK Audit</div>
        </div>
        <table>
          <thead><tr><th>No</th><th style="width:38px">Gbr</th><th>Nama Singkat</th><th>Nama Peralatan</th><th>Kode</th><th>Kondisi</th><th>Keterangan</th></tr></thead>
          <tbody>${rows}</tbody>
        </table>`;
    }).join('');

    const html = `<!DOCTYPE html><html><head><meta charset="UTF-8">
      <title>Pemeriksaan MT — ${sessions.length} Mekanik</title>
      <style>
        *{margin:0;padding:0;box-sizing:border-box}
        @page{size:A4 portrait;margin:10mm}
        body{font-family:'Times New Roman',serif;font-size:9px;color:#000;padding:4px}
        .hdr{text-align:center;margin-bottom:8px}
        .hdr h2{font-size:13px;font-weight:700;text-transform:uppercase;text-decoration:underline}
        .hdr p{font-size:9px;margin-top:2px}
        .info{margin-bottom:8px;font-size:9px}
        .stats{display:flex;gap:8px;margin-bottom:10px;font-size:8px}
        .stat-box{border:1px solid #666;padding:4px 8px;border-radius:3px;text-align:center;min-width:60px}
        table{width:100%;border-collapse:collapse;margin-top:4px}
        th{background:#1e3a5f;color:#fff;padding:4px;text-align:center;font-size:8px;border:1px solid #000}
        td{padding:3px 5px;border:1px solid #aaa;font-size:8.5px}
        tr:nth-child(even) td{background:#f5f5f5}
        .no-print{margin-bottom:12px}
        @media print{.no-print{display:none}}
      </style></head><body>
      <div class="no-print" style="display:flex;gap:8px;padding:8px 0">
        <button onclick="window.print()" style="background:#1e3a5f;color:#fff;border:none;border-radius:6px;padding:6px 16px;font-size:.82rem;cursor:pointer;font-weight:700">🖨️ Cetak / Simpan PDF</button>
        <button onclick="window.close()" style="background:#f1f5f9;color:#374151;border:1px solid #e2e8f0;border-radius:6px;padding:6px 14px;font-size:.82rem;cursor:pointer">✕ Tutup</button>
        <span style="font-size:.78rem;color:#6b7280;line-height:2">${sessions.length} mekanik dicetak</span>
      </div>
      ${sessHtml}
      </body></html>`;

    const win = window.open('','_blank','width=900,height=700');
    if (win) { win.document.write(html); win.document.close(); setTimeout(() => win.print(), 600); }
    else showToast('Popup diblokir. Izinkan popup untuk cetak PDF.', 'error');
  };

  let plans = loadPlans();
  let tasks  = loadTasks();

  const AUDITOR_ROLES = ['auditor', 'manajer', 'admin'];

  function getAuditorUsers() {
    return USERS.filter(u => u.role === 'auditor');
  }
  function getUserDisplay(username) {
    const u = USERS.find(u => u.username === username);
    return u ? u.displayName : username;
  }

  function populateCabangDropdown(selectedValue) {
    const sel  = document.getElementById('planCabang');
    const hint = document.getElementById('planCabangHint');
    if (!sel) return;

    const uu = loadSmhData(SMH_UNIT_AREA_KEY);

    if (!uu.length) {
      // No database: show the select hidden, show a text input instead
      sel.style.display = 'none';
      let manualInput = document.getElementById('planCabangManual');
      if (!manualInput) {
        manualInput = document.createElement('input');
        manualInput.type = 'text';
        manualInput.id   = 'planCabangManual';
        manualInput.className = 'form-input';
        manualInput.placeholder = 'Ketik nama cabang...';
        sel.parentNode.insertBefore(manualInput, sel.nextSibling);
      }
      manualInput.style.display = '';
      manualInput.value = selectedValue || '';
      if (hint) hint.innerHTML = 'ℹ Data Unit Usaha belum diimport — ketik nama cabang secara manual, atau import di <strong>Database SMH → Unit Usaha</strong>.';
      return;
    }

    // Hide manual input if data available
    const manualInput = document.getElementById('planCabangManual');
    if (manualInput) manualInput.style.display = 'none';
    sel.style.display = '';

    if (hint) hint.textContent = `${uu.length} cabang tersedia`;
    sel.innerHTML = '<option value="">— Pilih Cabang —</option>' +
      uu.map(u => {
        const areaLabel  = u.area  ? ` [${u.area}]`    : '';
        const jenisLabel = u.jenis ? ` — ${u.jenis}`   : '';
        return `<option value="${u.unitUsaha}" ${selectedValue === u.unitUsaha ? 'selected' : ''}>${u.unitUsaha}${areaLabel}${jenisLabel}</option>`;
      }).join('');
  }

  function generateNoSPT() {
    const now = new Date();
    const dd  = String(now.getDate()).padStart(2, '0');
    const mm  = String(now.getMonth() + 1).padStart(2, '0');
    const yyyy = now.getFullYear();
    const seq  = String(plans.length + 1).padStart(4, '0');
    return `${seq}/${dd}/${mm}/${yyyy}/SPT-IAT`;
  }

  function planStatusBadge(status) {
    const map = { aktif: 'Aktif', selesai: 'Selesai', batal: 'Dibatalkan' };
    return `<span class="badge-plan ${status}">${map[status] || status}</span>`;
  }

  function taskStatusBadge(status) {
    const map = {
      pending:        'Belum Disubmit',
      submitted:      'Menunggu Koordinator',
      koord_approved:    'Menunggu Manajer Audit',
      koord_rejected:    'Ditolak Koordinator',
      manajer_approved:  'Menunggu COO',
      manajer_rejected:  'Ditolak Manajer',
      coo_approved:      'Disetujui COO',
      coo_rejected:      'Ditolak COO',
      audit_started:  'Audit Berjalan',
      in_progress:    'Cabang Berjalan',
      selesai:        'Selesai',
      // legacy
      approved:  'Disetujui',
      rejected:  'Ditolak',
    };
    return `<span class="badge-task ${status}">${map[status] || status}</span>`;
  }

  /* Workflow steps helper — returns array of {label, status} */
  function getWorkflowSteps(taskStatus) {
    const steps = [
      { key: 'submitted',        label: 'Submit\nAuditor' },
      { key: 'koord_approved',   label: 'Approve\nKoordinator' },
      { key: 'manajer_approved', label: 'Approve\nManajer' },
      { key: 'coo_approved',     label: 'Approve\nCOO' },
      { key: 'audit_started',    label: 'Mulai\nAudit' },
      { key: 'in_progress',      label: 'Mulai\nCabang' },
      { key: 'selesai',          label: 'Selesai' },
    ];
    const order = steps.map(s => s.key);
    const curIdx = order.indexOf(taskStatus);
    return steps.map((s, i) => ({
      ...s,
      state: i < curIdx ? 'done' : i === curIdx ? 'active' : 'pending',
    }));
  }

  function renderWorkflowBar(taskStatus) {
    const steps = getWorkflowSteps(taskStatus);
    let html = '<div class="workflow-steps">';
    steps.forEach((s, i) => {
      if (i > 0) html += `<div class="wf-line${s.state === 'done' || steps[i-1].state === 'done' ? ' done' : ''}"></div>`;
      html += `<div class="wf-step ${s.state}">
        <div class="wf-step-dot">${s.state === 'done' ? '✓' : i + 1}</div>
        <div class="wf-step-label">${s.label.replace('\n', '<br>')}</div>
      </div>`;
    });
    html += '</div>';
    return html;
  }

  /* ============================================================
     MODUL AUDIT MANDIRI
     ============================================================ */

  const JENIS_MANDIRI = [
    { code: 'SMH',               label: 'Unit SMH',           pemKeys: ['smh']           },
    { code: 'KAS',               label: 'Kas',                pemKeys: ['kas']           },
    { code: 'HAO',               label: "HGP & AHM Oil's",   pemKeys: ['hgp']           },
    { code: 'MT',                label: 'MT',                 pemKeys: ['mt']            },
    { code: 'BPKB',              label: 'BPKB',               pemKeys: ['bpkb', 'lapos'] },
    { code: 'SERTIJAB_KASIR',    label: 'Sertijab Kasir',    pemKeys: ['sertijab']      },
    { code: 'SERTIJAB_ADH',      label: 'Sertijab ADH',      pemKeys: ['sertijab']      },
    { code: 'SERTIJAB_PARTKEEPER',label:'Sertijab Partkeeper',pemKeys: ['sertijab']      },
    { code: 'SERTIJAB_ADM_GDG',  label: 'Sertijab ADM Gudang',pemKeys:['sertijab']      },
  ];

  // ── Target Pemeriksaan Bulanan per Jenis Mandiri ─────────────────────
  // Sesuai jadwal: KAS 2x/bulan (SO), SMH 1x (SO), BPKB 1x (SO),
  // HGP 4x (CSC) + 2x (SO), MT 1x (SO) + 1x (CSC)
  const MANDIRI_TARGET_SCHEDULE = [
    { code:'KAS',  label:'Kas',             roleLabel:'SO',  color:'#b45309', icon:'💰',
      periods:[{label:'Target 1',start:1,end:15},{label:'Target 2',start:16,end:31}] },
    { code:'SMH',  label:'Unit SMH',        roleLabel:'SO',  color:'#0369a1', icon:'🏍',
      periods:[{label:'Target 1',start:1,end:31}] },
    { code:'BPKB', label:'BPKB',           roleLabel:'SO',  color:'#1e40af', icon:'📄',
      periods:[{label:'Target 1',start:1,end:31}] },
    { code:'HAO',  label:"HGP & AHM Oil's", roleLabel:'CSC', color:'#065f46', icon:'🛢',
      periods:[{label:'Target 1',start:1,end:7},{label:'Target 2',start:8,end:15},{label:'Target 3',start:16,end:23},{label:'Target 4',start:24,end:31}] },
    { code:'HAO',  label:"HGP & AHM Oil's", roleLabel:'SO',  color:'#065f46', icon:'🛢',
      periods:[{label:'Target 1',start:1,end:15},{label:'Target 2',start:16,end:31}] },
    { code:'MT',   label:'MT',             roleLabel:'SO',      color:'#5b21b6', icon:'🔧',
      periods:[{label:'Target 1',start:1,end:31}] },
    { code:'MT',   label:'MT',             roleLabel:'CSC',     color:'#5b21b6', icon:'🔧',
      periods:[{label:'Target 1',start:1,end:31}] },
    { code:'SMH',  label:'Unit SMH',       roleLabel:'WHS_UNIT',color:'#0369a1', icon:'🏍',
      periods:[{label:'Target 1',start:1,end:31}] },
    { code:'HAO',  label:"HGP & AHM Oil's",roleLabel:'WHS_PART',color:'#065f46', icon:'🛢',
      periods:[{label:'Target 1',start:1,end:15},{label:'Target 2',start:16,end:31}] },
  ];

  // ── Konfigurasi Checklist per Jenis Mandiri (dikelola ADM) ──────────
  const MANDIRI_CFG_KEY = 'akta_mandiri_jenis_cfg';

  // Setiap jenis mandiri mereferensikan key dari PEM_MENU_ITEMS sebagai komponen pemeriksaan.
  const MANDIRI_JENIS_DEFAULTS = {
    SMH:  { active: true, desc: 'Pemeriksaan fisik unit sepeda motor Honda', color:'#0369a1',
      defaultKeys: ['smh', 'luar'] },
    KAS:  { active: true, desc: 'Pemeriksaan kas besar dan kas kecil', color:'#b45309',
      defaultKeys: ['kas', 'bank', 'meterai', 'kwt', 'piutang', 'kds', 'ttp'] },
    HAO:  { active: true, desc: "Pemeriksaan HGP dan AHM Oil's", color:'#065f46',
      defaultKeys: ['hgp'] },
    MT:   { active: true, desc: 'Pemeriksaan tool kit per mekanik', color:'#5b21b6',
      defaultKeys: ['mt'] },
    BPKB: { active: true, desc: 'Pemeriksaan BPKB onhand dan lapos inproses', color:'#1e40af',
      defaultKeys: ['bpkb', 'lapos'] },
    SERTIJAB_KASIR: { active: true, desc: 'Serah terima jabatan Kasir', color:'#9d174d',
      defaultKeys: ['kas', 'bank', 'meterai', 'kwt', 'piutang', 'kds', 'ttp'] },
    SERTIJAB_ADH: { active: true, desc: 'Serah terima jabatan ADH (Admin Head)', color:'#7c3aed',
      defaultKeys: ['kas', 'bank', 'bpkb', 'lapos', 'smh', 'hgp'] },
    SERTIJAB_PARTKEEPER: { active: true, desc: 'Serah terima jabatan Partkeeper', color:'#0f766e',
      defaultKeys: ['bpkb', 'lapos', 'hgp'] },
    SERTIJAB_ADM_GDG: { active: true, desc: 'Serah terima jabatan Admin Gudang', color:'#92400e',
      defaultKeys: ['smh', 'luar', 'bpkb', 'lapos'] },
  };

  function loadMandiriCfg() {
    try { return JSON.parse(localStorage.getItem(MANDIRI_CFG_KEY)) || {}; } catch { return {}; }
  }
  function saveMandiriCfg(d) { localStorage.setItem(MANDIRI_CFG_KEY, JSON.stringify(d)); window.API?.sync(MANDIRI_CFG_KEY, d); }
  function getMandiriJenisCfg(code) {
    const saved = loadMandiriCfg()[code];
    const def   = MANDIRI_JENIS_DEFAULTS[code];
    if (!def) return null;
    // Build default keys map from defaultKeys array
    const defKeys = {};
    PEM_MENU_ITEMS.forEach(m => { defKeys[m.key] = (def.defaultKeys || []).includes(m.key); });
    const keys = saved?.keys ? { ...defKeys, ...saved.keys } : defKeys;
    return { ...def, active: saved ? saved.active !== false : true, keys };
  }

  // Returns active PEM_MENU_ITEMS for a jenis (those with keys[key] === true)
  function getMandiriActiveMenuItems(code) {
    const jCfg = getMandiriJenisCfg(code);
    if (!jCfg) return [];
    return PEM_MENU_ITEMS.filter(m => jCfg.keys[m.key]);
  }

  // Generate nomor plan otomatis: NNNN/MM/YYYY/CODE-AM
  function generateMandiriNoAM(code) {
    const now   = new Date();
    const mm    = String(now.getMonth() + 1).padStart(2, '0');
    const yyyy  = now.getFullYear();
    const all   = loadTasks().filter(t => t.isMandiri);
    const count = all.filter(t => {
      const d = new Date(t.createdAt || 0);
      return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear();
    }).length;
    return `${String(count + 1).padStart(4, '0')}/${mm}/${yyyy}/${code}-AM`;
  }

  // ── Modal Pengaturan Jenis Mandiri (ADM only) ─────────────────────
  let _mandiriSettingsJenis = JENIS_MANDIRI[0]?.code || 'SMH'; // jenis yang sedang dipilih di settings

  window._openMandiriSettings = function (selectedCode) {
    if (session.role !== 'adm' && session.role !== 'admin') return;
    if (selectedCode) _mandiriSettingsJenis = selectedCode;

    const existing = document.getElementById('_mandiriSettingsOverlay');
    if (existing) { _renderMandiriSettingsContent(); return; }

    const overlay = document.createElement('div');
    overlay.id = '_mandiriSettingsOverlay';
    overlay.style.cssText = `position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:9998;
      display:flex;align-items:flex-start;justify-content:center;padding:20px 16px;
      overflow-y:auto;backdrop-filter:blur(2px)`;

    overlay.innerHTML = `
      <div style="background:var(--card-bg,#fff);border-radius:16px;width:100%;max-width:820px;
                  box-shadow:0 24px 80px rgba(0,0,0,.22);animation:_fadeInUp .2s ease;margin:auto 0">
        <style>@keyframes _fadeInUp{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:translateY(0)}}</style>

        <!-- Header -->
        <div style="display:flex;align-items:center;gap:12px;padding:18px 24px 14px;
                    border-bottom:1px solid var(--border,#e5e7eb)">
          <div style="width:38px;height:38px;border-radius:10px;background:#f5f3ff;
                      display:flex;align-items:center;justify-content:center;flex-shrink:0">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#7c3aed" stroke-width="2">
              <circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 00.33 1.82l.06.06a2 2 0 010 2.83 2 2 0 01-2.83 0l-.06-.06a1.65 1.65 0 00-1.82-.33 1.65 1.65 0 00-1 1.51V21a2 2 0 01-4 0v-.09A1.65 1.65 0 009 19.4a1.65 1.65 0 00-1.82.33l-.06.06a2 2 0 01-2.83-2.83l.06-.06A1.65 1.65 0 004.68 15a1.65 1.65 0 00-1.51-1H3a2 2 0 010-4h.09A1.65 1.65 0 004.6 9a1.65 1.65 0 00-.33-1.82l-.06-.06a2 2 0 012.83-2.83l.06.06A1.65 1.65 0 009 4.68a1.65 1.65 0 001-1.51V3a2 2 0 014 0v.09a1.65 1.65 0 001 1.51 1.65 1.65 0 001.82-.33l.06-.06a2 2 0 012.83 2.83l-.06.06A1.65 1.65 0 0019.4 9a1.65 1.65 0 001.51 1H21a2 2 0 010 4h-.09a1.65 1.65 0 00-1.51 1z"/>
            </svg>
          </div>
          <div style="flex:1">
            <div style="font-weight:800;font-size:.95rem;color:var(--text-primary)">
              Pengaturan Menu Pemeriksaan per Jenis Audit Mandiri
            </div>
            <div style="font-size:.73rem;color:var(--text-secondary)">
              Pilih jenis mandiri, lalu atur komponen pemeriksaan yang aktif
            </div>
          </div>
          <span style="font-size:.7rem;background:#f5f3ff;color:#5b21b6;padding:3px 10px;border-radius:8px;font-weight:700;flex-shrink:0">Hanya ADM</span>
          <button onclick="document.getElementById('_mandiriSettingsOverlay').remove()"
            style="background:var(--hover-bg,#f1f5f9);border:none;border-radius:8px;width:30px;height:30px;
                   cursor:pointer;display:flex;align-items:center;justify-content:center;color:var(--text-secondary);margin-left:8px">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
              <line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>
            </svg>
          </button>
        </div>

        <!-- Body -->
        <div id="_mandiriSettingsBody" style="padding:20px 24px;max-height:calc(100vh - 140px);overflow-y:auto">
        </div>
      </div>`;

    overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
    document.body.appendChild(overlay);
    _renderMandiriSettingsContent();
  };

  function _renderMandiriSettingsContent() {
    const body = document.getElementById('_mandiriSettingsBody');
    if (!body) return;
    const selCode  = _mandiriSettingsJenis;
    const selJenis = JENIS_MANDIRI.find(j => j.code === selCode) || JENIS_MANDIRI[0];
    const jCfg     = getMandiriJenisCfg(selCode);
    const keys     = jCfg?.keys || {};
    const isActive = jCfg ? jCfg.active !== false : true;
    const color    = jCfg?.color || '#7c3aed';
    const activeCount = PEM_MENU_ITEMS.filter(m => keys[m.key]).length;

    // ── Pil jenis (atas) ─────────────────────────────────────────────
    const pillsHtml = `
      <div style="margin-bottom:18px">
        <div style="font-size:.68rem;font-weight:700;text-transform:uppercase;letter-spacing:.06em;
                    color:var(--text-secondary);margin-bottom:10px">Pilih Jenis Audit Mandiri</div>
        <div style="display:flex;flex-wrap:wrap;gap:6px">
          ${JENIS_MANDIRI.map(j => {
            const jc       = getMandiriJenisCfg(j.code);
            const jAct     = jc ? jc.active !== false : true;
            const jKeys    = jc?.keys || {};
            const jActive  = PEM_MENU_ITEMS.filter(m => jKeys[m.key]).length;
            const isSelected = j.code === selCode;
            const bg  = isSelected ? color : 'var(--hover-bg,#f1f5f9)';
            const clr = isSelected ? '#fff' : 'var(--text-secondary)';
            return `<button onclick="window._openMandiriSettings('${j.code}')"
              style="border:2px solid ${isSelected?color:'transparent'};border-radius:20px;padding:5px 13px;
                     background:${bg};color:${clr};font-size:.78rem;font-weight:${isSelected?'700':'500'};
                     cursor:pointer;transition:all .15s;opacity:${jAct?'1':'0.45'};
                     display:inline-flex;align-items:center;gap:5px">
              ${j.label}
              <span style="font-size:.68rem;opacity:.8">${jActive}/${PEM_MENU_ITEMS.length}</span>
            </button>`;
          }).join('')}
        </div>
      </div>`;

    // ── Panel jenis terpilih ──────────────────────────────────────────
    const panelHtml = `
      <div style="background:var(--card-bg,#fff);border:1.5px solid ${isActive?color+'44':'#e5e7eb'};
                  border-radius:12px;overflow:hidden">

        <!-- Panel header -->
        <div style="display:flex;align-items:center;gap:12px;padding:14px 18px;
                    background:${isActive?color+'0d':'#f9fafb'}">
          <div style="width:36px;height:36px;border-radius:9px;background:${color}20;
                      display:flex;align-items:center;justify-content:center;font-size:1.1rem;flex-shrink:0">
            ${selCode.startsWith('SERTIJAB')?'👤':selCode==='KAS'?'💰':selCode==='BPKB'?'📄':selCode==='MT'?'🔧':selCode==='HAO'?'🛢':'🏍'}
          </div>
          <div style="flex:1">
            <div style="font-weight:800;font-size:.95rem;color:${color}">${selJenis.label}</div>
            <div style="font-size:.73rem;color:var(--text-secondary)">${jCfg?.desc||''}</div>
          </div>

          <!-- Kontrol kanan -->
          <div style="display:flex;gap:8px;align-items:center;flex-shrink:0">
            <button onclick="window._setAllMandiriItems('${selCode}',true)"
              style="border:1.5px solid #22c55e;border-radius:8px;padding:5px 12px;font-size:.76rem;font-weight:700;
                     background:#f0fdf4;color:#15803d;cursor:pointer">✓ Semua Aktif</button>
            <button onclick="window._setAllMandiriItems('${selCode}',false)"
              style="border:1.5px solid #e5e7eb;border-radius:8px;padding:5px 12px;font-size:.76rem;font-weight:600;
                     background:var(--hover-bg);color:var(--text-secondary);cursor:pointer">○ Semua Non-aktif</button>
            <!-- Toggle aktif jenis -->
            <div style="display:flex;align-items:center;gap:6px;margin-left:4px">
              <span style="font-size:.73rem;color:var(--text-secondary)">Aktif</span>
              <div onclick="window._toggleMandiriJenisActive('${selCode}')"
                style="width:38px;height:20px;border-radius:10px;cursor:pointer;transition:all .2s;position:relative;
                       background:${isActive?color:'#d1d5db'}">
                <div style="width:16px;height:16px;border-radius:50%;background:#fff;position:absolute;top:2px;
                             transition:left .2s;left:${isActive?'20px':'2px'};box-shadow:0 1px 4px rgba(0,0,0,.25)"></div>
              </div>
            </div>
          </div>
        </div>

        <!-- Grid menu pemeriksaan -->
        <div style="padding:16px 18px;border-top:1px solid ${color}22">
          <div style="font-size:.68rem;font-weight:700;text-transform:uppercase;letter-spacing:.06em;
                      color:var(--text-secondary);margin-bottom:10px;display:flex;align-items:center;gap:6px">
            Menu Pemeriksaan
            <span style="font-size:.7rem;background:${color}15;color:${color};padding:1px 8px;
                         border-radius:8px;font-weight:700;text-transform:none">${activeCount} aktif · ${PEM_MENU_ITEMS.length} total</span>
          </div>

          <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(175px,1fr));gap:8px">
            ${PEM_MENU_ITEMS.map(m => {
              const on = keys[m.key] === true;
              return `
                <div style="border:1.5px solid ${on?color:'#e5e7eb'};border-radius:10px;
                            background:${on?color+'0d':'var(--card-bg,#fff)'};
                            transition:all .15s;overflow:hidden">
                  <div style="display:flex;align-items:center;gap:8px;padding:10px 12px;
                              background:${on?color+'15':'var(--hover-bg,#f8fafc)'};
                              border-bottom:1px solid ${on?color+'33':'#f1f5f9'}">
                    <span style="font-size:1rem;flex-shrink:0">${m.icon}</span>
                    <div style="flex:1;min-width:0">
                      <div style="font-size:.79rem;font-weight:700;color:${on?color:'var(--text-primary)'};
                                  line-height:1.3;word-break:break-word">${m.label}</div>
                    </div>
                  </div>
                  <label style="display:flex;align-items:center;gap:8px;padding:8px 12px;cursor:pointer">
                    <input type="checkbox" ${on?'checked':''} onchange="window._toggleMandiriItem('${selCode}','${m.key}',this.checked)"
                      style="width:14px;height:14px;accent-color:${color};cursor:pointer">
                    <span style="font-size:.72rem;font-weight:700;color:${on?color:'#9ca3af'}">
                      ${on?'✓ Aktif':'○ Non-aktif'}
                    </span>
                  </label>
                </div>`;
            }).join('')}
          </div>
        </div>

        <!-- Footer panel -->
        <div style="padding:12px 18px;border-top:1px solid ${color}22;background:${color}06;
                    display:flex;align-items:center;gap:10px;flex-wrap:wrap">
          <div style="font-size:.72rem;color:var(--text-secondary)">
            <span style="font-weight:700;color:${color}">${activeCount} menu aktif</span>
            dari ${PEM_MENU_ITEMS.length} menu pemeriksaan untuk jenis ini.
          </div>
          <button onclick="window._resetMandiriJenis('${selCode}')" style="margin-left:auto;
            border:1px solid #e5e7eb;border-radius:7px;padding:5px 12px;font-size:.74rem;font-weight:600;
            background:transparent;color:var(--text-secondary);cursor:pointer">
            ↺ Reset ke Default
          </button>
        </div>
      </div>`;

    body.innerHTML = pillsHtml + panelHtml;
  }

  window._toggleMandiriJenisActive = function (code) {
    const cfg = loadMandiriCfg();
    if (!cfg[code]) cfg[code] = { active: true };
    cfg[code].active = !(cfg[code].active !== false);
    saveMandiriCfg(cfg);
    _renderMandiriSettingsContent();
    _updateMandiriDropdown();
    showToast(`Jenis "${JENIS_MANDIRI.find(j=>j.code===code)?.label||code}" ${cfg[code].active?'diaktifkan':'dinonaktifkan'}.`, 'success', 1800);
  };

  window._toggleMandiriItem = function (code, key, enabled) {
    const cfg  = loadMandiriCfg();
    const jCfg = getMandiriJenisCfg(code);
    if (!cfg[code]) cfg[code] = { active: jCfg?.active !== false };
    if (!cfg[code].keys) {
      const defKeys = {};
      PEM_MENU_ITEMS.forEach(m => { defKeys[m.key] = jCfg?.keys?.[m.key] || false; });
      cfg[code].keys = defKeys;
    }
    cfg[code].keys[key] = enabled;
    saveMandiriCfg(cfg);
    _renderMandiriSettingsContent();
  };

  window._setAllMandiriItems = function (code, enabled) {
    const cfg  = loadMandiriCfg();
    const jCfg = getMandiriJenisCfg(code);
    if (!cfg[code]) cfg[code] = { active: jCfg?.active !== false };
    const newKeys = {};
    PEM_MENU_ITEMS.forEach(m => { newKeys[m.key] = enabled; });
    cfg[code].keys = newKeys;
    saveMandiriCfg(cfg);
    _renderMandiriSettingsContent();
    showToast(enabled ? 'Semua menu pemeriksaan diaktifkan.' : 'Semua menu pemeriksaan dinonaktifkan.', 'success', 1800);
  };

  window._resetMandiriJenis = function (code) {
    if (!confirm(`Reset komponen jenis "${JENIS_MANDIRI.find(j=>j.code===code)?.label||code}" ke default?`)) return;
    const cfg = loadMandiriCfg();
    delete cfg[code];
    saveMandiriCfg(cfg);
    _renderMandiriSettingsContent();
    showToast('Komponen direset ke default.', 'success', 2000);
  };

  function _updateMandiriDropdown() {
    const sel = document.getElementById('mandiriJenis');
    if (!sel) return;
    sel.innerHTML = '<option value="">— Pilih Jenis —</option>' +
      JENIS_MANDIRI.map(j => {
        const jCfg = getMandiriJenisCfg(j.code);
        const isActive = !jCfg || jCfg.active !== false;
        return isActive ? `<option value="${j.code}">${j.label}</option>` : '';
      }).join('');
  }

  function renderAuditMandiriSection() {
    const canCreate = ['so', 'csc', 'whs'].includes(session.role);
    const btn = document.getElementById('btnCreateMandiri');
    if (btn) btn.classList.toggle('hidden', !canCreate);

    // Tombol Pengaturan Jenis — hanya ADM
    const settingsBtn = document.getElementById('btnMandiriSettings');
    if (settingsBtn) settingsBtn.classList.toggle('hidden', session.role !== 'adm' && session.role !== 'admin');

    // Sync dropdown dengan jenis yang aktif
    _updateMandiriDropdown();

    // Pre-fill unit usaha in form
    const uuEl = document.getElementById('mandiriUnitUsaha');
    if (uuEl) uuEl.value = session.unitUsaha || session.username;

    // Today default
    const tglEl = document.getElementById('mandiriTanggal');
    if (tglEl && !tglEl.value) tglEl.value = new Date().toISOString().split('T')[0];

    _renderMandiriList();
    _updateMandiriBadge();
  }

  function _renderMandiriList() {
    const container = document.getElementById('mandiriListContainer');
    if (!container) return;

    const allTasks  = loadTasks().filter(t => t.isMandiri);
    const myUU      = (session.unitUsaha || '').trim().toUpperCase();
    const canCreate = ['so', 'csc', 'whs'].includes(session.role);
    const isManager = can('view-all-plans');

    // SO/CSC/WHS sees only own unit; admin/manajer sees all
    const list = (canCreate && myUU)
      ? allTasks.filter(t => (t.unitUsaha || '').trim().toUpperCase() === myUU)
      : isManager
        ? allTasks
        : allTasks.filter(t => t.assignedTo === session.username);

    if (!list.length) {
      container.innerHTML = `
        <div class="card" style="padding:32px;text-align:center;color:var(--text-secondary)">
          <div style="font-size:2rem;margin-bottom:8px">📋</div>
          <div style="font-weight:600">Belum ada Plan Audit Mandiri</div>
          ${canCreate ? '<div style="font-size:.84rem;margin-top:4px">Klik "Buat Plan Mandiri" untuk membuat plan baru.</div>' : ''}
        </div>`;
      return;
    }

    // Sort: aktif first, then by createdAt desc
    const sorted = [...list].sort((a, b) => {
      if (a.status === b.status) return new Date(b.createdAt) - new Date(a.createdAt);
      return a.status === 'in_progress' ? -1 : 1;
    });

    const cards = sorted.map(t => {
      const jenisDef  = JENIS_MANDIRI.find(j => j.code === t.jenisMandiri) || {};
      const isDone    = t.status === 'selesai';
      const statusBadge = isDone
        ? `<span style="font-size:.72rem;padding:2px 10px;border-radius:9px;background:#dcfce7;color:#166534;font-weight:700">✓ Selesai</span>`
        : `<span style="font-size:.72rem;padding:2px 10px;border-radius:9px;background:#dbeafe;color:#1e40af;font-weight:700">● Aktif</span>`;

      const pemBtns = _buildMandiriPemBtns(t, jenisDef);

      return `
        <div class="card" style="margin-bottom:12px;border:1.5px solid ${isDone ? '#bbf7d0' : 'var(--border)'}">
          <div style="padding:14px 18px">
            <!-- Header -->
            <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:10px">
              <div style="flex:1">
                <div style="font-size:.92rem;font-weight:700;font-family:monospace;color:var(--primary)">${t.noAM}</div>
                <div style="font-size:.8rem;color:var(--text-secondary);margin-top:2px">
                  ${jenisDef.label || t.jenisMandiri} &nbsp;·&nbsp; ${t.unitUsaha || '—'} &nbsp;·&nbsp; ${t.tglMulai || '—'}
                </div>
              </div>
              <div style="display:flex;align-items:center;gap:8px">
                ${statusBadge}
                ${(!isDone && canCreate && t.assignedTo === session.username) ? `
                  <button onclick="window._selesaiMandiri('${t.id}')"
                    style="font-size:.75rem;padding:5px 12px;border-radius:7px;border:none;background:#1e3a5f;color:#fff;cursor:pointer;font-weight:600">
                    ✓ Selesai
                  </button>` : ''}
                ${(canCreate || isManager) ? `
                  <button onclick="window._hapusMandiri('${t.id}')"
                    style="font-size:.75rem;padding:5px 10px;border-radius:7px;border:1px solid #fca5a5;background:#fff1f2;color:#b91c1c;cursor:pointer">
                    Hapus
                  </button>` : ''}
              </div>
            </div>
            <!-- Pemeriksaan bar -->
            ${!isDone ? `
              <div class="audit-pemeriksaan-bar" style="margin-top:0">
                <div class="audit-pemeriksaan-title">MENU PEMERIKSAAN</div>
                <div class="audit-pemeriksaan-btns">${pemBtns}</div>
              </div>` : `
              <div style="font-size:.8rem;color:#166534;padding:6px 0">✓ Audit mandiri telah diselesaikan.</div>`}
          </div>
        </div>`;
    }).join('');

    container.innerHTML = cards;
  }

  function _buildMandiriPemBtns(t, jenisDef) {
    // Sertijab: seluruh tampilan digantikan checklist inline
    if ((jenisDef.code || t.jenisMandiri || '').startsWith('SERTIJAB')) {
      return _buildSertijabChecklist(t);
    }

    // Ambil semua item aktif sesuai pengaturan
    const activeItems = getMandiriActiveMenuItems(t.jenisMandiri);
    if (!activeItems.length) {
      return '<span style="font-size:.8rem;color:#9ca3af;padding:4px 0">Belum ada komponen aktif.</span>';
    }

    // Konfigurasi warna per key untuk generic button
    const _KEY_STYLE = {
      luar:       { bg:'#f0fdf4', color:'#166534', border:'#86efac' },
      bank:       { bg:'#eff6ff', color:'#1e40af', border:'#bfdbfe' },
      meterai:    { bg:'#fefce8', color:'#854d0e', border:'#fde047' },
      kwt:        { bg:'#fff7ed', color:'#9a3412', border:'#fdba74' },
      piutang:    { bg:'#fdf4ff', color:'#6b21a8', border:'#d8b4fe' },
      kds:        { bg:'#fff1f2', color:'#9f1239', border:'#fda4af' },
      ttp:        { bg:'#f0fdf4', color:'#065f46', border:'#6ee7b7' },
      lampiran:   { bg:'#f8fafc', color:'#334155', border:'#cbd5e1' },
      grading:    { bg:'#fffbeb', color:'#92400e', border:'#fcd34d' },
      rekomendasi:{ bg:'#ecfdf5', color:'#065f46', border:'#34d399' },
      bu_perf:    { bg:'#f0f9ff', color:'#0c4a6e', border:'#7dd3fc' },
    };

    const rendered = new Set();
    let html = '';

    // ── Key dengan modal/fungsi khusus ──
    const _has = key => activeItems.some(m => m.key === key);

    if (_has('smh')) {
      rendered.add('smh');
      html += `<button class="audit-pem-btn audit-pem-btn--smh"
        onclick="window._openAuditPemeriksaan('${t.id}','pemeriksaan-smh')">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
        <span>Pemeriksaan Unit SMH</span>
      </button>`;
    }
    if (_has('kas')) {
      rendered.add('kas');
      const kasCount = loadKasAudit().filter(r => String(r.taskId) === String(t.id)).length;
      html += `<button class="audit-pem-btn audit-pem-btn--kas"
        onclick="window._openKasAuditModal('${t.id}')">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="5" width="20" height="14" rx="2"/><line x1="2" y1="10" x2="22" y2="10"/></svg>
        <span>Pemeriksaan Kas</span>
        ${kasCount > 0 ? `<span class="audit-pem-count">${kasCount}</span>` : ''}
      </button>`;
    }
    if (_has('hgp')) {
      rendered.add('hgp');
      html += `<button class="audit-pem-btn" style="background:#ecfdf5;color:#065f46;border:1px solid #6ee7b7"
        onclick="window._openHgpFromAudit('${t.planId}')">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M9 3H5a2 2 0 00-2 2v4m6-6h10a2 2 0 012 2v4M9 3v18m0 0h10a2 2 0 002-2V9M9 21H5a2 2 0 01-2-2V9m0 0h18"/>
        </svg>
        <span>HGP &amp; AHM Oil's</span>
      </button>`;
    }
    if (_has('mt')) {
      rendered.add('mt');
      const mtSessions = loadMtSessions ? loadMtSessions(t.planId) : [];
      const mtCount    = (mtSessions || []).filter(s => (s.items || []).length > 0).length;
      html += `<button class="audit-pem-btn" style="background:#fdf4ff;color:#6b21a8;border:1px solid #d8b4fe"
        onclick="window._openMtPem('${t.id}')">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M14.7 6.3a1 1 0 000 1.4l1.6 1.6a1 1 0 001.4 0l3.77-3.77a6 6 0 01-7.94 7.94l-6.91 6.91a2.12 2.12 0 01-3-3l6.91-6.91a6 6 0 017.94-7.94l-3.76 3.76z"/>
        </svg>
        <span>Pemeriksaan MT</span>
        ${mtCount > 0 ? `<span class="audit-pem-count" style="background:#6b21a8">${mtCount}</span>` : ''}
      </button>`;
    }
    if (_has('bpkb')) {
      rendered.add('bpkb');
      const bpkbCount = loadBpkbScan ? loadBpkbScan().filter(s => String(s.planId) === String(t.planId)).length : 0;
      html += `<button class="audit-pem-btn" style="background:#eff6ff;color:#1e40af;border:1px solid #bfdbfe"
        onclick="window._openBpkbModal('${t.id}')">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M9 21V9"/>
        </svg>
        <span>BPKB Onhand</span>
        ${bpkbCount > 0 ? `<span class="audit-pem-count" style="background:#1e40af">${bpkbCount}</span>` : ''}
      </button>`;
    }
    if (_has('luar')) {
      rendered.add('luar');
      html += `<button class="audit-pem-btn" style="background:#f0fdf4;color:#166534;border:1px solid #86efac"
        onclick="window._openLuarFisikModal('${t.id}')">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <rect x="2" y="7" width="20" height="14" rx="2"/><path d="M16 7V5a2 2 0 00-2-2h-4a2 2 0 00-2 2v2"/>
          <line x1="12" y1="12" x2="12" y2="17"/><line x1="9" y1="14" x2="15" y2="14"/>
        </svg>
        <span>Perlengkapan Luar Fisik</span>
      </button>`;
    }
    if (_has('lapos')) {
      rendered.add('lapos');
      const laposHasData = typeof loadLaposAll === 'function'
        ? loadLaposAll().some(d => String(d.planId) === String(t.planId)) : false;
      html += `<button class="audit-pem-btn" style="background:#f5f3ff;color:#5b21b6;border:1px solid #ddd6fe"
        onclick="window._openLaposBpkb('${t.id}')">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/>
          <polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/>
        </svg>
        <span>Lapos &amp; Inproses BPKB</span>
        ${laposHasData ? `<span class="audit-pem-count" style="background:#5b21b6">✓</span>` : ''}
      </button>`;
    }

    // ── Semua item aktif yang belum di-render (generic button) ──
    activeItems.forEach(item => {
      if (rendered.has(item.key)) return;
      const s = _KEY_STYLE[item.key] || { bg:'#f8fafc', color:'#475569', border:'#cbd5e1' };
      html += `<button class="audit-pem-btn"
        style="background:${s.bg};color:${s.color};border:1px solid ${s.border}">
        <span style="font-size:.9rem">${item.icon || '📋'}</span>
        <span>${item.label}</span>
      </button>`;
    });

    return html;
  }

  // ── Sertijab checklist inline dalam kartu mandiri ───────────────────
  const SERTIJAB_CEK_KEY = 'akta_sertijab_cek';
  function loadSertijabCek()       { try { return JSON.parse(localStorage.getItem(SERTIJAB_CEK_KEY)) || []; } catch { return []; } }
  function saveSertijabCek(d)      { localStorage.setItem(SERTIJAB_CEK_KEY, JSON.stringify(d)); window.API?.sync(SERTIJAB_CEK_KEY, d); }
  function getSertijabCek(taskId)  { return loadSertijabCek().find(c => String(c.taskId) === String(taskId)) || { taskId: String(taskId), checks: {} }; }

  window._setSertijabCheck = function (taskId, itemKey, checked) {
    const list = loadSertijabCek();
    const idx  = list.findIndex(c => String(c.taskId) === String(taskId));
    if (idx >= 0) {
      list[idx].checks[itemKey] = checked;
    } else {
      list.push({ taskId: String(taskId), checks: { [itemKey]: checked } });
    }
    saveSertijabCek(list);
    const badge = document.getElementById('sertijab-done-' + taskId);
    const cekData = getSertijabCek(taskId);
    const allItems = _getSertijabItems(taskId);
    const doneCount = allItems.filter(it => cekData.checks[it.key]).length;
    if (badge) badge.textContent = doneCount + '/' + allItems.length;
  };

  function _getSertijabItems(taskId) {
    const task = loadTasks().find(t => String(t.id) === String(taskId));
    if (!task) return [];
    return getMandiriActiveMenuItems(task.jenisMandiri);
  }

  function _buildSertijabChecklist(t) {
    const jCfg    = getMandiriJenisCfg(t.jenisMandiri);
    const items   = getMandiriActiveMenuItems(t.jenisMandiri);
    const cekData = getSertijabCek(t.id);
    const checks  = cekData.checks || {};
    const color   = jCfg?.color || '#7c3aed';
    const doneCount = items.filter(it => checks[it.key]).length;
    const isDone  = t.status === 'selesai';

    if (!items.length) return `<div style="font-size:.8rem;color:#9ca3af;padding:4px 0">Belum ada komponen pemeriksaan.</div>`;

    // Peta key → fungsi pembuka form/modal (sama dengan _buildMandiriPemBtns)
    const _openFn = key => {
      switch (key) {
        case 'smh':   return `window._openAuditPemeriksaan('${t.id}','pemeriksaan-smh')`;
        case 'kas':   return `window._openKasAuditModal('${t.id}')`;
        case 'hgp':   return `window._openHgpFromAudit('${t.planId || t.id}')`;
        case 'mt':    return `window._openMtPem('${t.id}')`;
        case 'bpkb':  return `window._openBpkbModal('${t.id}')`;
        case 'luar':  return `window._openLuarFisikModal('${t.id}')`;
        case 'lapos': return `window._openLaposBpkb('${t.id}')`;
        default:      return null;
      }
    };

    return `
      <div style="background:#faf5ff;border:1.5px solid #e9d5ff;border-radius:10px;padding:14px 16px;width:100%;box-sizing:border-box">
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:12px">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="${color}" stroke-width="2">
            <path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 01-2 2H5a2 2 0 01-2-2V5a2 2 0 012-2h11"/>
          </svg>
          <strong style="font-size:.85rem;color:${color}">Checklist Sertijab</strong>
          <span id="sertijab-done-${t.id}"
            style="font-size:.72rem;background:${doneCount===items.length?'#dcfce7':'#ede9fe'};
                   color:${doneCount===items.length?'#166534':color};padding:1px 8px;border-radius:8px;font-weight:700">
            ${doneCount}/${items.length}
          </span>
          ${doneCount === items.length ? '<span style="font-size:.7rem;background:#dcfce7;color:#166534;padding:1px 7px;border-radius:7px;font-weight:700">✓ Lengkap</span>' : ''}
        </div>
        <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:6px">
          ${items.map(it => {
            const isChecked = !!checks[it.key];
            const fn = !isDone ? _openFn(it.key) : null;
            // Item dengan form: klik buka form
            // Item tanpa form: klik toggle selesai
            const clickAction = fn
              ? fn
              : `window._setSertijabCheck('${t.id}','${it.key}',${!isChecked})`;
            return `
              <button onclick="${isDone ? '' : clickAction}"
                style="display:flex;align-items:center;gap:8px;padding:10px 12px;
                       background:${isChecked?'#f0fdf4':'var(--card-bg,#fff)'};
                       border:1px solid ${isChecked?'#86efac':'#e5e7eb'};border-radius:8px;
                       text-align:left;cursor:${isDone?'default':'pointer'};
                       transition:all .15s;width:100%;box-sizing:border-box;"
                onmouseover="if(!${isDone})this.style.borderColor='${isChecked?'#4ade80':color}';this.style.boxShadow='0 2px 8px rgba(0,0,0,.07)'"
                onmouseout="this.style.borderColor='${isChecked?'#86efac':'#e5e7eb'}';this.style.boxShadow='none'">
                ${isChecked
                  ? `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#16a34a" stroke-width="2.5" style="flex-shrink:0">
                       <path d="M22 11.08V12a10 10 0 11-5.93-9.14"/>
                       <polyline points="22 4 12 14.01 9 11.01"/>
                     </svg>`
                  : `<span style="font-size:.95rem;flex-shrink:0;line-height:1">${it.icon}</span>`}
                <span style="font-size:.8rem;color:${isChecked?'#166534':'var(--text-primary)'};
                             font-weight:${isChecked?'600':'500'};line-height:1.3;flex:1">${it.label}</span>
                ${fn && !isDone
                  ? `<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="${isChecked?'#16a34a':color}"
                         stroke-width="2.5" style="flex-shrink:0;opacity:.5">
                       <polyline points="9 18 15 12 9 6"/>
                     </svg>`
                  : ''}
              </button>`;
          }).join('')}
        </div>
      </div>`;
  }

  function _updateMandiriBadge() {
    const badge = document.getElementById('navMandiriBadge');
    if (!badge) return;
    const myUU  = (session.unitUsaha || '').trim().toUpperCase();
    const count = loadTasks().filter(t =>
      t.isMandiri && t.status === 'in_progress' &&
      (!myUU || (t.unitUsaha || '').trim().toUpperCase() === myUU)
    ).length;
    badge.textContent = count;
    badge.classList.toggle('hidden', count === 0);
  }

  window._toggleMandiriForm = function(show) {
    const card = document.getElementById('mandiriFormCard');
    if (!card) return;
    card.classList.toggle('hidden', !show);
    if (show) {
      // Reset form
      const j = document.getElementById('mandiriJenis');
      const n = document.getElementById('mandiriNoAM');
      if (j) j.value = '';
      if (n) n.value = '';
    }
  };

  window._onMandiriJenisChange = function() {
    const code = document.getElementById('mandiriJenis')?.value;
    const noEl = document.getElementById('mandiriNoAM');
    if (!noEl) return;
    noEl.value = code ? generateMandiriNoAM(code) : '';
  };

  window._saveMandiriPlan = function() {
    const code  = document.getElementById('mandiriJenis')?.value;
    const tgl   = document.getElementById('mandiriTanggal')?.value;
    const uu    = document.getElementById('mandiriUnitUsaha')?.value || session.unitUsaha || session.username;

    if (!code) { showToast('Pilih Jenis Audit Mandiri.', 'error'); return; }
    if (!tgl)  { showToast('Isi Tanggal.', 'error'); return; }

    const jenisDef = JENIS_MANDIRI.find(j => j.code === code);
    const noAM     = generateMandiriNoAM(code);
    const id       = Date.now();

    // Store as a special task so existing modals (bpkb, mt, kas, smh) work unchanged
    const newTask = {
      id,
      planId:       id,         // self-referential: task IS the plan
      isMandiri:    true,
      noAM,
      jenisMandiri: code,
      jenisLabel:   jenisDef?.label || code,
      jenisAudit:   'Audit Mandiri',
      cabangPlan:   uu,
      unitUsaha:    uu,
      assignedTo:   session.username,
      isKepala:     true,
      status:       'in_progress',
      tglMulai:     tgl,
      tglSelesai:   null,
      createdBy:    session.username,
      createdAt:    new Date().toISOString(),
    };

    tasks = loadTasks();
    tasks.push(newTask);
    saveTasks(tasks);

    window._toggleMandiriForm(false);
    renderAuditMandiriSection();
    showToast(`Plan ${noAM} berhasil dibuat.`, 'success');
  };

  window._selesaiMandiri = function(taskId) {
    if (!confirm('Tandai plan ini sebagai selesai?')) return;
    tasks = loadTasks();
    const idx = tasks.findIndex(t => String(t.id) === String(taskId) && t.isMandiri);
    if (idx < 0) return;
    tasks[idx].status     = 'selesai';
    tasks[idx].tglSelesai = new Date().toISOString().split('T')[0];
    saveTasks(tasks);
    renderAuditMandiriSection();
    showToast('Audit mandiri ditandai selesai.', 'success');
  };

  window._hapusMandiri = function(taskId) {
    if (!confirm('Hapus plan audit mandiri ini? Data pemeriksaan yang terkait akan ikut terhapus.')) return;
    tasks = loadTasks();
    tasks = tasks.filter(t => !(String(t.id) === String(taskId) && t.isMandiri));
    saveTasks(tasks);
    renderAuditMandiriSection();
    showToast('Plan mandiri dihapus.', 'info');
  };

  // ── Plan section render ──────────────────────────
  function renderPlanSection() {
    try {
      plans = _syncAllPlanStatuses();
      renderPlanSummary();
      renderPlanTable();
    } catch (e) {
      console.error('renderPlanSection error:', e);
    }
    // Button visibility — always runs regardless of errors above
    const btn = document.getElementById('btnCreatePlan');
    if (btn) btn.classList.toggle('hidden', !can('create-plan'));
  }

  // Also set button visibility on nav click (before renderPlanSection resolves)
  function initPlanAuditVisibility() {
    const btn = document.getElementById('btnCreatePlan');
    if (btn) btn.classList.toggle('hidden', !can('create-plan'));
  }

  function renderPlanSummary() {
    const el = document.getElementById('planSummaryGrid');
    if (!el) return;
    const total   = plans.length;
    const aktif   = plans.filter(p => p.status === 'aktif').length;
    const selesai = plans.filter(p => p.status === 'selesai').length;
    const _myRole = session.role;
    const tasksPending = loadTasks().filter(t => {
      if (_myRole === 'koordinator') return t.status === 'submitted';
      if (_myRole === 'manajer')     return t.status === 'koord_approved';
      if (_myRole === 'coo')         return t.status === 'manajer_approved';
      return false;
    }).length;
    el.innerHTML = `
      <div class="plan-stat-card">
        <div class="psc-label">Total Plan</div>
        <div class="psc-value">${total}</div>
      </div>
      <div class="plan-stat-card">
        <div class="psc-label">Aktif</div>
        <div class="psc-value" style="color:var(--primary)">${aktif}</div>
      </div>
      <div class="plan-stat-card">
        <div class="psc-label">Selesai</div>
        <div class="psc-value" style="color:var(--success)">${selesai}</div>
      </div>
      ${tasksPending > 0 ? `<div class="plan-stat-card">
        <div class="psc-label">Perlu Review</div>
        <div class="psc-value" style="color:var(--warning)">${tasksPending}</div>
      </div>` : ''}`;
  }

  function renderPlanTable() {
    const tbody = document.getElementById('planTableBody');
    if (!tbody) return;

    // Strict role-based plan visibility
    const allTasks = loadTasks();
    let visible;
    if (can('approve-koordinator')) {
      // Koordinator: only plans with tasks waiting for their approval
      const planIds = new Set(allTasks.filter(t => t.status === 'submitted').map(t => String(t.planId)));
      visible = plans.filter(p => planIds.has(String(p.id)));
    } else if (can('approve-coo')) {
      // COO: only plans with tasks that passed manajer
      const planIds = new Set(allTasks.filter(t => t.status === 'manajer_approved').map(t => String(t.planId)));
      visible = plans.filter(p => planIds.has(String(p.id)));
    } else if (can('view-all-plans')) {
      // Manajer/Admin: all plans
      visible = plans;
    } else {
      // Auditor: only plans where they are assigned
      visible = plans.filter(p =>
        p.kepalaTim === session.username ||
        (p.timAudit || []).includes(session.username)
      );
    }

    if (!visible.length) {
      const createBtn = can('create-plan')
        ? `<button class="btn-primary" style="margin-top:12px;font-size:.85rem" onclick="window._openPlanModal(null)">
             <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:middle;margin-right:5px"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
             Buat Plan Baru
           </button>`
        : '';
      const _r = session.role;
      const emptyMsg = _r === 'koordinator'
        ? 'Belum ada task yang menunggu persetujuan Koordinator.'
        : _r === 'manajer'
          ? 'Belum ada task yang menunggu persetujuan Manajer Audit.'
          : _r === 'coo'
            ? 'Belum ada task yang menunggu persetujuan COO.'
            : 'Belum ada plan audit yang tersedia.';
      tbody.innerHTML = `<tr><td colspan="9"><div class="empty-state"><p>${emptyMsg}</p>${createBtn}</div></td></tr>`;
      return;
    }

    tbody.innerHTML = visible.map((p, i) => {
      const tim = (p.timAudit || []).map(u => getUserDisplay(u)).join(', ') || '—';
      const kepala = getUserDisplay(p.kepalaTim);

      // Compute current workflow step from tasks
      const planTasks = allTasks.filter(t => String(t.planId) === String(p.id));
      const taskStatuses = planTasks.map(t => t.status);
      let workflowStep = 'Menunggu Submit Auditor';
      if (taskStatuses.every(s => s === 'selesai'))               workflowStep = '✓ Selesai';
      else if (taskStatuses.some(s => s === 'in_progress'))       workflowStep = '▶ Pemeriksaan Berjalan';
      else if (taskStatuses.some(s => s === 'audit_started'))     workflowStep = '▶ Audit Berjalan';
      else if (taskStatuses.some(s => s === 'coo_approved'))      workflowStep = '→ Menunggu Mulai Audit';
      else if (taskStatuses.some(s => s === 'manajer_approved'))  workflowStep = '→ Menunggu COO';
      else if (taskStatuses.some(s => s === 'koord_approved'))    workflowStep = '→ Menunggu Manajer Audit';
      else if (taskStatuses.some(s => s === 'submitted'))         workflowStep = '→ Menunggu Koordinator';
      else if (planTasks.length)                                  workflowStep = '⏳ Menunggu Submit';

      const aksi = can('create-plan')
        ? `<button class="btn-outline" style="font-size:.78rem;padding:4px 10px" onclick="window._editPlan('${p.id}')">Edit</button>
           <button class="btn-clear-data" style="font-size:.78rem;padding:4px 8px;margin-left:4px" onclick="window._deletePlan('${p.id}')">Hapus</button>`
        : `<button class="btn-outline" style="font-size:.78rem;padding:4px 10px" onclick="window._viewPlanTasks('${p.id}')">Task</button>
           <button class="btn-outline" style="font-size:.78rem;padding:4px 10px;margin-left:4px" onclick="window._gotoAudit()">Audit</button>`;
      return `<tr>
        <td>${i + 1}</td>
        <td style="white-space:nowrap;font-weight:600;font-size:.82rem">${p.noSPT}</td>
        <td>${p.jenisAudit}</td>
        <td style="white-space:nowrap">${p.tanggalPlan}</td>
        <td>${kepala}</td>
        <td style="font-size:.8rem;max-width:160px">${tim}</td>
        <td>${p.cabangPlan}${p.cabangArea ? ' ' + areaBadge(p.cabangArea) : ''}</td>
        <td>${planStatusBadge(p.status)} <div style="font-size:.72rem;color:var(--text-secondary);margin-top:2px">${workflowStep}</div></td>
        <td style="white-space:nowrap">${aksi}</td>
      </tr>`;
    }).join('');
  }

  window._editPlan = function (id) { window._openPlanModal(id); };

  window._deletePlan = function (id) {
    if (!confirm('Hapus plan ini? Task yang terkait juga akan dihapus.')) return;
    plans = plans.filter(p => p.id !== id);
    savePlans(plans);
    tasks = tasks.filter(t => t.planId !== id);
    saveTasks(tasks);
    renderPlanSection();
    renderTaskSection();
    updateTaskBadge();
    showToast('Plan dihapus.', 'info');
  };

  window._viewPlanTasks = function (planId) {
    // Switch to task section and filter by this plan
    document.querySelectorAll('.nav-item').forEach(li => li.classList.remove('active'));
    document.querySelectorAll('.content-section').forEach(s => s.classList.add('hidden'));
    document.querySelector('[data-section="task"]')?.classList.add('active');
    document.getElementById('section-task')?.classList.remove('hidden');
    renderTaskSection(planId);
  };

  function savePlan() {
    const noSPT      = document.getElementById('planNoSPT').value.trim();
    const jenisAudit = document.getElementById('planJenisAudit').value;
    const tanggal    = document.getElementById('planTanggal').value;
    const catatan    = document.getElementById('planCatatan').value.trim();
    const kepalaTim  = document.getElementById('planKepalaTim').value;
    const cabangSel   = document.getElementById('planCabang');
    const cabangManual = document.getElementById('planCabangManual');
    const cabang = (cabangManual && cabangManual.style.display !== 'none')
      ? cabangManual.value.trim()
      : cabangSel?.value || '';
    const timChecked = [...document.querySelectorAll('#planTimAuditList input:checked')].map(cb => cb.value);

    if (!jenisAudit) { showToast('Pilih Jenis Audit.', 'error'); return; }
    if (!tanggal)    { showToast('Isi Tanggal Plan.', 'error'); return; }
    if (!kepalaTim)  { showToast('Pilih Kepala Tim.', 'error'); return; }
    if (!cabang)     { showToast('Pilih Cabang Plan.', 'error'); return; }
    if (!timChecked.length) { showToast('Pilih minimal 1 anggota TIM Audit.', 'error'); return; }

    // Enrich with area from Unit Usaha database
    const uuData    = loadSmhData(SMH_UNIT_AREA_KEY);
    const uuRecord  = uuData.find(u => u.unitUsaha === cabang);
    const cabangArea = uuRecord ? uuRecord.area : '';

    // Ensure kepala is also in tim list
    const allTim = [...new Set([kepalaTim, ...timChecked])];

    plans = loadPlans();
    if (_editingPlanId) {
      const idx = plans.findIndex(p => p.id === _editingPlanId);
      if (idx >= 0) {
        plans[idx] = { ...plans[idx], jenisAudit, tanggalPlan: tanggal, catatan, kepalaTim, cabangPlan: cabang, timAudit: allTim };
        // Sync existing tasks with updated tim
        tasks = loadTasks();
        // Remove tasks for members removed from team
        tasks = tasks.filter(t => t.planId !== _editingPlanId || allTim.includes(t.assignedTo));
        // Add tasks for new members
        allTim.forEach(u => {
          if (!tasks.some(t => t.planId === _editingPlanId && t.assignedTo === u)) {
            tasks.push(createTask(plans[idx], u));
          }
        });
        saveTasks(tasks);
      }
    } else {
      const newPlan = {
        id: Date.now(),
        noSPT, jenisAudit, tanggalPlan: tanggal, catatan,
        kepalaTim, cabangPlan: cabang, cabangArea,
        timAudit: allTim,
        status: 'aktif',
        createdBy: session.username,
        createdAt: new Date().toISOString(),
      };
      plans.push(newPlan);
      // Create a task for each member
      tasks = loadTasks();
      allTim.forEach(u => tasks.push(createTask(newPlan, u)));
      saveTasks(tasks);
    }

    savePlans(plans);
    window._closePlanModal();
    renderPlanSection();
    renderTaskSection();
    updateTaskBadge();
    showToast(_editingPlanId ? 'Plan diperbarui.' : 'Plan baru berhasil dibuat dan task dikirim ke auditor.', 'success');
  }

  function formatDateTime(iso) {
    if (!iso) return '—';
    return new Date(iso).toLocaleString('id-ID', {
      day: '2-digit', month: 'short', year: 'numeric',
      hour: '2-digit', minute: '2-digit', second: '2-digit',
    });
  }

  const STATUS_LOG_LABELS = {
    pending:        'Task Dibuat',
    submitted:      'Disubmit Auditor',
    koord_approved:    'Disetujui Koordinator',
    koord_rejected:    'Ditolak Koordinator',
    manajer_approved:  'Disetujui Manajer',
    manajer_rejected:  'Ditolak Manajer',
    coo_approved:      'Disetujui COO',
    coo_rejected:      'Ditolak COO',
    audit_started:  'Audit Dimulai',
    in_progress:    'Cabang Dimulai',
    selesai:        'Selesai',
  };

  function addStatusLog(task, newStatus, note) {
    const log = Array.isArray(task.statusLog) ? [...task.statusLog] : [];
    log.push({
      status:  newStatus,
      by:      session.username,
      byName:  session.displayName,
      at:      new Date().toISOString(),
      note:    note || '',
    });
    return log;
  }

  function renderStatusLog(statusLog) {
    if (!statusLog || !statusLog.length) return '';
    return `<div class="status-log-wrap">
      <div class="status-log-title">Riwayat Status</div>
      ${statusLog.map(l => `
        <div class="status-log-item">
          <div class="status-log-dot ${l.status}"></div>
          <div class="status-log-content">
            <div class="status-log-label">${STATUS_LOG_LABELS[l.status] || l.status}</div>
            <div class="status-log-meta">${l.byName} &nbsp;·&nbsp; ${formatDateTime(l.at)}</div>
            ${l.note ? `<div class="status-log-note">"${l.note}"</div>` : ''}
          </div>
        </div>`).join('')}
    </div>`;
  }

  function createTask(plan, username) {
    return {
      id:          Date.now() + Math.random(),
      planId:      plan.id,
      noSPT:       plan.noSPT,
      jenisAudit:  plan.jenisAudit,
      cabangPlan:  plan.cabangPlan,
      cabangArea:  plan.cabangArea || '',
      tanggalPlan: plan.tanggalPlan,
      assignedTo:  username,
      isKepala:    username === plan.kepalaTim,
      tglMulai:    '',
      tglSelesai:  '',
      fileName:    '',
      catatan:     '',
      status:      'pending',
      submittedAt: '',
      approvedAt:  '',
      approvedBy:  '',
      reviewNote:  '',
      statusLog:   [{
        status: 'pending', by: session.username, byName: session.displayName,
        at: new Date().toISOString(), note: 'Task dibuat oleh manajer',
      }],
    };
  }

  // ── Task section render ──────────────────────────
  let _taskFilter = 'semua';

  function renderTaskSection(filterPlanId) {
    tasks = loadTasks();
    const filterBar = document.getElementById('taskFilterBar');
    const container = document.getElementById('taskListContainer');
    if (!filterBar || !container) return;

    // Strict role-based task visibility
    // Task = tempat persinggahan: task SELESAI tidak ditampilkan di sini
    // Mandiri tasks are handled exclusively in the Audit Mandiri section
    const regularTasks = tasks.filter(t => !t.isMandiri);
    const role = session.role;
    let myTasks;
    if (role === 'koordinator') {
      myTasks = regularTasks.filter(t => t.status === 'submitted');
    } else if (role === 'coo') {
      myTasks = regularTasks.filter(t => t.status === 'manajer_approved');
    } else if (role === 'so' || role === 'csc' || role === 'whs' || role === 'kasir') {
      // Branch staff: hanya task aktif (audit_started / in_progress), BUKAN selesai
      const myUU = (session.unitUsaha || '').trim().toUpperCase();
      myTasks = regularTasks.filter(t =>
        ['audit_started', 'in_progress'].includes(t.status) &&
        (!myUU || (t.cabangPlan || '').trim().toUpperCase() === myUU)
      );
    } else if (role === 'afd' || role === 'rss') {
      myTasks = [];
    } else if (can('view-all-plans')) {
      // Admin / Manajer: semua task KECUALI selesai
      myTasks = regularTasks.filter(t => t.status !== 'selesai');
    } else {
      // Auditor: hanya task milik sendiri yang BELUM selesai
      myTasks = regularTasks.filter(t => t.assignedTo === session.username && t.status !== 'selesai');
    }

    if (filterPlanId) myTasks = myTasks.filter(t => t.planId == filterPlanId);

    // ── AFD: tambahkan kartu Keputusan AFD dari data rekomendasi ──
    let afdCardsHtml = '';
    if (role === 'afd' || role === 'admin') {
      const afdRekoms = loadRekomendasi().filter(r => r.status === 'pending_afd');
      const filteredAfd = filterPlanId
        ? afdRekoms.filter(r => String(r.planId) === String(filterPlanId))
        : afdRekoms;

      if (filteredAfd.length) {
        afdCardsHtml = filteredAfd.map(r => {
          const mgrStep = r.steps?.manajer;
          const mgrIsi  = mgrStep?.isi || '';
          const mgrBy   = mgrStep?.byName || mgrStep?.by || '—';
          const mgrTgl  = mgrStep?.tgl || '—';
          const mgrTs   = mgrStep?.submittedAt ? (() => {
            try {
              const d = new Date(mgrStep.submittedAt);
              return d.toLocaleDateString('id-ID',{day:'2-digit',month:'long',year:'numeric'}) +
                     ', ' + d.toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit',second:'2-digit'});
            } catch(e) { return mgrTgl; }
          })() : mgrTgl;

          return `<div class="task-card" style="border:2px solid #7c3aed;background:linear-gradient(135deg,#faf5ff,#f5f3ff)">
            <div class="task-card-header">
              <div>
                <div style="display:flex;align-items:center;gap:6px;margin-bottom:2px">
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#7c3aed" stroke-width="2">
                    <path d="M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z"/>
                    <polyline points="9 22 9 12 15 12 15 22"/>
                  </svg>
                  <strong style="font-size:.78rem;color:#5b21b6;text-transform:uppercase;letter-spacing:.04em">
                    Keputusan AFD — Rekomendasi Audit
                  </strong>
                </div>
                <div class="task-card-title">${r.noSPT}</div>
                <div class="task-card-sub">${r.jenisAudit} &nbsp;·&nbsp; ${r.unitUsaha}</div>
              </div>
              <div>
                <span style="font-size:.72rem;padding:3px 10px;border-radius:10px;font-weight:700;
                             background:#fdf4ff;color:#701a75;border:1px solid #e9d5ff">
                  &#9201; Menunggu Keputusan AFD
                </span>
              </div>
            </div>

            ${mgrIsi ? `
            <div style="margin:10px 0;padding:10px 12px;background:#fff;border-radius:7px;border:1px solid #ddd6fe">
              <div style="font-size:.7rem;font-weight:700;text-transform:uppercase;color:#5b21b6;
                          letter-spacing:.04em;margin-bottom:5px">
                &#128203; Rekomendasi Manajer Audit
              </div>
              <div style="font-size:.72rem;color:#6b7280;margin-bottom:4px">
                ${mgrBy} &nbsp;&middot;&nbsp; ${mgrTs}
              </div>
              <div style="font-size:.84rem;color:#1e293b;line-height:1.55;white-space:pre-wrap">${mgrIsi}</div>
            </div>` : ''}

            <div class="task-card-actions">
              <button class="btn-primary" style="font-size:.85rem;padding:8px 20px;font-weight:700;
                             background:linear-gradient(135deg,#5b21b6,#7c3aed);border:none"
                      onclick="window._openRekomendasiModal('${r.planId}')">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor"
                     stroke-width="2" style="vertical-align:middle;margin-right:6px">
                  <path d="M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z"/>
                  <polyline points="9 22 9 12 15 12 15 22"/>
                </svg>
                Isi Keputusan AFD
              </button>
              <button class="btn-outline" style="font-size:.8rem;padding:8px 14px"
                      onclick="window._openRekomendasiModal('${r.planId}')">
                Lihat History Lengkap
              </button>
            </div>
          </div>`;
        }).join('');

        // Bungkus dengan header seksi
        afdCardsHtml =
          `<div style="margin-bottom:12px">
             <div style="display:flex;align-items:center;gap:8px;padding:10px 14px;
                         background:linear-gradient(135deg,#5b21b6,#7c3aed);border-radius:8px 8px 0 0;color:#fff">
               <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                 <path d="M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z"/>
                 <polyline points="9 22 9 12 15 12 15 22"/>
               </svg>
               <strong style="font-size:.87rem">Menunggu Keputusan AFD</strong>
               <span style="background:rgba(255,255,255,.25);border-radius:9px;padding:1px 9px;font-size:.75rem;font-weight:700">
                 ${filteredAfd.length}
               </span>
             </div>
             <div style="border:1.5px solid #7c3aed;border-top:none;border-radius:0 0 8px 8px;padding:12px">
               ${afdCardsHtml}
             </div>
           </div>`;
      }
    }

    // ── SK Approval cards (Manajer dan AFD) ──
    let skApprovalCardsHtml = '';
    if (['manajer','admin'].includes(role) || role === 'afd') {
      const skPendingKey = role === 'afd' ? 'pending_afd' : 'pending_manajer';
      let pendingSk = loadSk().filter(s => s.status === skPendingKey);
      if (filterPlanId) pendingSk = pendingSk.filter(s => String(s.planId) === String(filterPlanId));

      if (pendingSk.length) {
        const isAfdApprover = role === 'afd';
        const headerClr = isAfdApprover ? '#5b21b6' : '#065f46';
        const borderClr = isAfdApprover ? '#7c3aed' : '#34d399';
        const bgGradient = isAfdApprover ? 'linear-gradient(135deg,#5b21b6,#7c3aed)' : 'linear-gradient(135deg,#065f46,#059669)';
        const bgCard     = isAfdApprover ? 'linear-gradient(135deg,#faf5ff,#f5f3ff)' : 'linear-gradient(135deg,#f0fdf4,#ecfdf5)';
        const btnBg      = isAfdApprover ? 'linear-gradient(135deg,#5b21b6,#7c3aed)' : 'linear-gradient(135deg,#065f46,#059669)';
        const stepKey    = isAfdApprover ? 'afd' : 'manajer';
        const headerLabel = isAfdApprover ? '&#127963; Persetujuan SK — AFD' : '&#128203; Persetujuan SK — Manajer Audit';

        const cardsInner = pendingSk.map(s => {
          const tgl = (() => { try { return new Date(s.uploadedAt).toLocaleDateString('id-ID',{day:'2-digit',month:'long',year:'numeric'}); } catch{return '—';} })();
          const mgrStep = s.steps?.manajer;
          return `<div class="task-card" style="border:2px solid ${borderClr};background:${bgCard};margin-bottom:10px">
            <div class="task-card-header">
              <div>
                <div style="display:flex;align-items:center;gap:6px;margin-bottom:2px">
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="${headerClr}" stroke-width="2">
                    <rect x="3" y="3" width="18" height="18" rx="2"/><line x1="9" y1="3" x2="9" y2="21"/>
                    <path d="M13 8h4M13 12h4M13 16h4"/>
                  </svg>
                  <strong style="font-size:.78rem;color:${headerClr};text-transform:uppercase;letter-spacing:.04em">SK — ${isAfdApprover ? 'Menunggu AFD' : 'Menunggu Manajer'}</strong>
                </div>
                <div class="task-card-title">${s.noSK}</div>
                <div class="task-card-sub">${s.noSPT} &nbsp;·&nbsp; ${s.unitUsaha} &nbsp;·&nbsp; ${s.jenisAudit}</div>
              </div>
              <div><span style="font-size:.72rem;padding:3px 10px;border-radius:10px;font-weight:700;background:${isAfdApprover?'#fdf4ff':'#dcfce7'};color:${headerClr}">&#9201; Menunggu ${isAfdApprover?'AFD':'Manajer'}</span></div>
            </div>
            <div style="display:flex;align-items:center;gap:10px;margin:8px 0 10px;flex-wrap:wrap;font-size:.78rem;color:#374151">
              <span>Diupload: ${tgl} oleh ${s.uploadedByName||s.uploadedBy}</span>
              ${s.fileSK?.data ? `<button class="btn-outline" style="font-size:.72rem;padding:3px 10px;color:#0891b2;border-color:#99f6e4" onclick="window._openSkFile('${s.id}')">&#128065; Buka File SK</button>` : '<span style="color:#9ca3af;font-style:italic">Tanpa file</span>'}
            </div>
            ${(isAfdApprover && mgrStep) ? `<div style="background:#f0fdf4;border:1px solid #86efac;border-radius:7px;padding:9px 12px;margin-bottom:10px;font-size:.78rem">
              <div style="font-weight:700;color:#065f46;margin-bottom:2px">&#10003; Disetujui Manajer Audit</div>
              <div style="color:#374151">${mgrStep.byName||mgrStep.by} &nbsp;·&nbsp; ${(() => { try { return new Date(mgrStep.approvedAt).toLocaleDateString('id-ID'); } catch{return '—';} })()}</div>
            </div>` : ''}
            <div class="task-card-actions">
              <button class="btn-primary" style="font-size:.85rem;padding:8px 20px;font-weight:700;background:${btnBg};border:none"
                      onclick="window._approveSkStep('${s.id}','${stepKey}')">
                &#10003; ${isAfdApprover ? 'Setujui SK (AFD)' : 'Setujui SK (Manajer Audit)'}
              </button>
              <button class="btn-outline" style="font-size:.8rem;padding:8px 14px"
                      onclick="window._openRekomendasiModal('${s.planId}')">Lihat Rekomendasi</button>
            </div>
          </div>`;
        }).join('');

        skApprovalCardsHtml = `<div style="margin-bottom:12px">
          <div style="display:flex;align-items:center;gap:8px;padding:10px 14px;background:${bgGradient};border-radius:8px 8px 0 0;color:#fff">
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <rect x="3" y="3" width="18" height="18" rx="2"/><line x1="9" y1="3" x2="9" y2="21"/>
            </svg>
            <strong style="font-size:.87rem">${headerLabel}</strong>
            <span style="background:rgba(255,255,255,.25);border-radius:9px;padding:1px 9px;font-size:.75rem;font-weight:700">${pendingSk.length}</span>
          </div>
          <div style="border:1.5px solid ${borderClr};border-top:none;border-radius:0 0 8px 8px;padding:12px">
            ${cardsInner}
          </div>
        </div>`;
      }
    }

    // ── SK Notifikasi cards (CC dari Realisasi SK) ──
    let skNotifCardsHtml = '';
    const mySkNotifs = (() => { try { return loadSkNotif().filter(n => n.toUsername === session.username); } catch { return []; } })();
    if (mySkNotifs.length) {
      const unreadNotifs = mySkNotifs.filter(n => !n.read);
      const fmtDtN = iso => { try { return new Date(iso).toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'}); } catch { return '—'; } };
      const cardsN = mySkNotifs.map(n => `
        <div class="task-card" style="border:1.5px solid ${n.read?'#e5e7eb':'#ddd6fe'};background:${n.read?'#fff':'linear-gradient(135deg,#faf5ff,#f5f3ff)'}">
          <div class="task-card-header">
            <div>
              <div style="display:flex;align-items:center;gap:6px;margin-bottom:2px">
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#7c3aed" stroke-width="2"><path d="M18 8A6 6 0 006 8c0 7-3 9-3 9h18s-3-2-3-9"/><path d="M13.73 21a2 2 0 01-3.46 0"/></svg>
                <strong style="font-size:.76rem;color:#5b21b6;text-transform:uppercase;letter-spacing:.04em">Notifikasi Realisasi SK ${n.read?'':'&#9679;'}</strong>
              </div>
              <div class="task-card-title">${n.noSK}</div>
              <div class="task-card-sub">${n.noSPT} &nbsp;·&nbsp; ${n.unitUsaha}</div>
            </div>
            <span style="font-size:.72rem;padding:3px 10px;border-radius:10px;font-weight:600;background:${n.read?'#f1f5f9':'#ede9fe'};color:${n.read?'#64748b':'#5b21b6'}">
              ${n.read?'Telah dibaca':'Belum dibaca'}
            </span>
          </div>
          <div style="font-size:.8rem;color:#374151;margin:6px 0 2px"><strong>Perihal:</strong> ${n.perihal}</div>
          <div class="task-card-meta">
            <span>Dari: ${n.fromName}</span>
            <span>${fmtDtN(n.createdAt)}</span>
          </div>
          <div class="task-card-actions">
            <button class="btn-primary" style="font-size:.82rem;padding:7px 16px;font-weight:600;background:linear-gradient(135deg,#5b21b6,#7c3aed);border:none"
                    onclick="window._markSkNotifRead('${n.realisasiSkId}')">
              &#128196; Buka Detail Realisasi SK
            </button>
          </div>
        </div>`).join('');
      skNotifCardsHtml = `<div style="margin-bottom:12px">
        <div style="display:flex;align-items:center;gap:8px;padding:10px 14px;background:linear-gradient(135deg,#5b21b6,#7c3aed);border-radius:8px 8px 0 0;color:#fff">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 8A6 6 0 006 8c0 7-3 9-3 9h18s-3-2-3-9"/><path d="M13.73 21a2 2 0 01-3.46 0"/></svg>
          <strong style="font-size:.87rem">Notifikasi Realisasi SK</strong>
          ${unreadNotifs.length ? `<span style="background:rgba(255,255,255,.25);border-radius:9px;padding:1px 9px;font-size:.75rem;font-weight:700">${unreadNotifs.length} belum dibaca</span>` : ''}
        </div>
        <div style="border:1.5px solid #7c3aed;border-top:none;border-radius:0 0 8px 8px;padding:12px;display:grid;gap:10px">
          ${cardsN}
        </div>
      </div>`;
    }

    // Build filter defs per role
    let filterDefs;
    if (role === 'koordinator') {
      filterDefs = [{ key: 'semua', label: 'Menunggu Review Anda' }];
    } else if (role === 'coo') {
      filterDefs = [{ key: 'semua', label: 'Menunggu Review Anda' }];
    } else if (role === 'afd') {
      filterDefs = [
        { key: 'semua',     label: 'Semua' },
        { key: 'rekom_afd', label: 'Keputusan Rekomendasi' },
        { key: 'sk_afd',    label: 'Approved SK' },
      ];
    } else if (role === 'rss') {
      // RSS: hanya rekomendasi yang menunggu RSS
      filterDefs = [{ key: 'semua', label: 'Rekomendasi Menunggu Anda' }];
    } else if (role === 'so' || role === 'csc' || role === 'whs' || role === 'kasir') {
      // Hitung PICA pending untuk badge
      const myUU2 = session.unitUsaha || '';
      const picaPendingCount = (() => {
        const relevantPlans = myTasks.map(t => String(t.planId));
        return loadGradingSessions()
          .filter(s => relevantPlans.includes(String(s.planId)))
          .flatMap(s => (s.items||[]).filter(it => it.pica && it.pica.status !== 'completed'))
          .length;
      })();
      filterDefs = [
        { key: 'semua',         label: 'Semua' },
        { key: 'audit_started', label: 'Siap Mulai Cabang' },
        { key: 'in_progress',   label: 'Sedang Berjalan' },
        ...(picaPendingCount > 0 ? [{ key: 'pica_pending', label: `⚠ PICA (${picaPendingCount})` }] : []),
      ];
    } else if (can('view-all-plans')) {
      filterDefs = [
        { key: 'semua',            label: 'Semua' },
        { key: 'pending',          label: 'Belum Disubmit' },
        { key: 'submitted',        label: 'Menunggu Koordinator' },
        { key: 'koord_approved',   label: 'Menunggu Manajer Audit' },
        { key: 'koord_rejected',   label: 'Ditolak Koordinator' },
        { key: 'manajer_approved', label: 'Menunggu COO' },
        { key: 'manajer_rejected', label: 'Ditolak Manajer' },
        { key: 'coo_approved',     label: 'Disetujui COO' },
        { key: 'coo_rejected',     label: 'Ditolak COO' },
      ];
    } else {
      filterDefs = [
        { key: 'semua',            label: 'Semua' },
        { key: 'pending',          label: 'Belum Disubmit' },
        { key: 'submitted',        label: 'Menunggu Koordinator' },
        { key: 'koord_approved',   label: 'Menunggu Manajer Audit' },
        { key: 'koord_rejected',   label: 'Ditolak Koordinator' },
        { key: 'manajer_approved', label: 'Menunggu COO' },
        { key: 'manajer_rejected', label: 'Ditolak Manajer' },
        { key: 'coo_approved',     label: 'Disetujui COO' },
        { key: 'coo_rejected',     label: 'Ditolak COO' },
      ];
    }

    // Hitung counts: untuk afd/rss, pakai jumlah afd cards
    const afdRekCount = loadRekomendasi().filter(r => r.status === 'pending_afd').length;
    const rssRekCount = (() => {
      const allRek = loadRekomendasi().filter(r => r.status === 'pending_rss');
      if (role === 'rss' && session.unitUsaha) {
        const plans = loadPlans();
        const wil   = session.unitUsaha.toLowerCase().trim();
        return allRek.filter(r => {
          const p = plans.find(pl => String(pl.id) === String(r.planId));
          return (p?.cabangArea || '').toLowerCase().trim() === wil;
        }).length;
      }
      return allRek.length;
    })();

    const counts = {};
    if (role === 'afd') {
      const afdSkCount = loadSk().filter(s => s.status === 'pending_afd').length;
      counts['semua']     = afdRekCount + afdSkCount;
      counts['rekom_afd'] = afdRekCount;
      counts['sk_afd']    = afdSkCount;
    } else {
      filterDefs.forEach(f => {
        if (role === 'rss') {
          counts[f.key] = rssRekCount;
        } else {
          counts[f.key] = f.key === 'semua' ? myTasks.length : myTasks.filter(t => t.status === f.key).length;
        }
      });
    }

    filterBar.innerHTML = filterDefs.map(f =>
      `<button class="task-filter-btn ${_taskFilter === f.key ? 'active' : ''}"
         onclick="window._setTaskFilter('${f.key}')">${f.label}
         ${counts[f.key] > 0 ? `<span style="margin-left:4px;background:rgba(0,0,0,.12);border-radius:9px;padding:0 6px;font-size:.72rem">${counts[f.key]}</span>` : ''}
       </button>`
    ).join('');

    const filtered = _taskFilter === 'semua'
      ? myTasks
      : _taskFilter === 'pica_pending'
        ? myTasks.filter(t => {
            const gs = loadGradingSessions().filter(s => String(s.planId) === String(t.planId));
            return gs.some(s => (s.items||[]).some(it => it.pica && it.pica.status !== 'completed'));
          })
        : myTasks.filter(t => t.status === _taskFilter);

    if (!filtered.length && !afdCardsHtml && !skApprovalCardsHtml && !skNotifCardsHtml) {
      container.innerHTML = `<div class="empty-state" style="padding:40px"><p>Tidak ada task ${_taskFilter === 'semua' ? '' : 'dengan status ini'}.</p></div>`;
      return;
    }

    const regularTasksHtml = filtered.map(t => {
      const assignee = getUserDisplay(t.assignedTo);
      const planInfo = plans.find(p => p.id == t.planId);
      const planStatus = planInfo ? `• ${planInfo.status}` : '';

      let actionBtn = '';
      // Koordinator: review submitted tasks
      if (can('approve-koordinator') && t.status === 'submitted') {
        actionBtn = `<button class="btn-primary" style="font-size:.8rem;padding:6px 14px" onclick="window._openApproveModal(${t.id})">Review Koordinator</button>`;
      // Manajer: review koord_approved tasks
      } else if (t.status === 'koord_approved' && (role === 'manajer' || role === 'admin')) {
        actionBtn = `<button class="btn-primary" style="font-size:.8rem;padding:6px 14px" onclick="window._openApproveModal(${t.id})">Review Manajer</button>`;
      // COO: review manajer_approved tasks
      } else if (can('approve-coo') && t.status === 'manajer_approved') {
        actionBtn = `<button class="btn-primary" style="font-size:.8rem;padding:6px 14px" onclick="window._openApproveModal(${t.id})">Review COO</button>`;
      // Auditor: submit or resubmit
      } else if (t.assignedTo === session.username &&
                 (t.status === 'pending' || t.status === 'koord_rejected' || t.status === 'manajer_rejected' || t.status === 'coo_rejected')) {
        actionBtn = `<button class="btn-success" style="font-size:.8rem;padding:6px 14px" onclick="window._openTaskModal(${t.id})">
          ${t.status === 'pending' ? 'Mulai & Upload' : 'Perbaiki & Submit'}
        </button>`;
      // Branch staff: Mulai Cabang jika audit sudah dimulai auditor
      } else if ((role === 'so' || role === 'csc' || role === 'whs') && t.status === 'audit_started') {
        actionBtn = `<button class="btn-success" style="font-size:.8rem;padding:6px 16px;font-weight:600" onclick="window._mulaiCabang(${t.id})">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="vertical-align:middle;margin-right:5px"><polygon points="5 3 19 12 5 21 5 3"/></svg>
          Mulai Cabang
        </button>`;
      // Admin: buka menu pemeriksaan
      } else if ((role === 'admin') && t.status === 'in_progress') {
        actionBtn = `<button class="btn-outline" style="font-size:.8rem;padding:6px 14px" onclick="window._gotoAudit()">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:middle;margin-right:5px"><path d="M15 3h4a2 2 0 012 2v14a2 2 0 01-2 2h-4"/><polyline points="10 17 15 12 10 7"/><line x1="15" y1="12" x2="3" y2="12"/></svg>
          Buka Menu Pemeriksaan
        </button>`;
      } else {
        actionBtn = `<button class="btn-outline" style="font-size:.8rem;padding:6px 14px" onclick="window._openTaskModal(${t.id})">Lihat Detail</button>`;
      }

      const fileTag = t.fileName
        ? `<span class="task-file-badge"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/></svg> ${t.fileName}</span>`
        : '';

      // ── PICA & Grading section — gunakan helper function ──
      const picaGradingSection = _buildPicaGradingTaskSection(t.planId, role);

      return `<div class="task-card">
        <div class="task-card-header">
          <div>
            <div class="task-card-title">${t.noSPT}</div>
            <div class="task-card-sub">${t.jenisAudit} &nbsp;·&nbsp; ${t.cabangPlan}${t.cabangArea ? ' ' + areaBadge(t.cabangArea) : ''} ${planStatus}</div>
          </div>
          <div style="display:flex;flex-direction:column;align-items:flex-end;gap:5px">
            ${taskStatusBadge(t.status)}
            ${t.isKepala ? '<span style="font-size:.72rem;color:var(--primary);font-weight:600">Kepala Tim</span>' : ''}
          </div>
        </div>
        <div class="task-card-meta">
          <span><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>${assignee}</span>
          <span><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>Tgl Plan: ${t.tanggalPlan}</span>
          ${t.tglMulai ? `<span>Mulai: ${t.tglMulai}</span>` : ''}
          ${t.tglSelesai ? `<span>Selesai: ${t.tglSelesai}</span>` : ''}
          ${fileTag}
        </div>
        ${t.reviewNote ? `<div style="margin-top:8px;padding:8px 10px;background:#fef3c7;border-radius:6px;font-size:.8rem;color:#b45309"><strong>Catatan Review:</strong> ${t.reviewNote}</div>` : ''}
        ${picaGradingSection}
        <div class="task-card-actions">${actionBtn}</div>
      </div>`;
    }).join('');

    if (role === 'afd') {
      const showRekom = _taskFilter === 'semua' || _taskFilter === 'rekom_afd';
      const showSk    = _taskFilter === 'semua' || _taskFilter === 'sk_afd';
      container.innerHTML = skNotifCardsHtml + (showSk ? skApprovalCardsHtml : '') + (showRekom ? afdCardsHtml : '') + regularTasksHtml;
    } else {
      container.innerHTML = skNotifCardsHtml + skApprovalCardsHtml + afdCardsHtml + regularTasksHtml;
    }
  }

  window._setTaskFilter = function (f) {
    _taskFilter = f;
    renderTaskSection();
  };

  // ── Helper: bangun seksi Grading & PICA untuk task card ──────────────────
  function _buildPicaGradingTaskSection(planId, role) {
    try {
      const isBranch = ['so','csc','whs'].includes(role);
      const canSee   = isBranch || role === 'auditor' || role === 'admin';
      if (!canSee) return '';

      const gradSessions = loadGradingSessions().filter(s => String(s.planId) === String(planId));
      const allPicaItems = gradSessions.flatMap(sess =>
        (sess.items || []).map((it, idx) => ({ ...it, _sid: sess.id, _idx: idx, _sess: sess }))
          .filter(it => it.pica)
      );

      const pendingPica   = allPicaItems.filter(it => it.pica.status !== 'completed');
      const completedPica = allPicaItems.filter(it => it.pica.status === 'completed');

      // Jika tidak ada data sama sekali, tidak tampilkan seksi
      if (!gradSessions.length && !allPicaItems.length) return '';

      // ── Grading summary strip ──
      const gradHtml = gradSessions.length ? `
        <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#0369a1" stroke-width="2"><polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/></svg>
          <span style="font-size:.72rem;font-weight:700;color:#0369a1;text-transform:uppercase">Grading</span>
          ${gradSessions.map(gs => {
            const kolom = _gradingKolomLabel(gs.bbnkb || false, gs.fraud || false);
            return `<span style="font-size:.75rem;background:#f0f9ff;border:1px solid #bae6fd;border-radius:6px;padding:3px 10px;color:#0369a1;font-weight:600">
              ${gs.jenis||'—'} (${gs.area||'—'}) — ${kolom}: <strong>${_fmtGradingVal(gs.nilaiTotal||0)}</strong>
              ${gs.bbnkb ? '<span style="color:#b45309;margin-left:3px">BBNKB</span>' : ''}
              ${gs.fraud  ? '<span style="color:#dc2626;margin-left:3px">FRAUD</span>' : ''}
            </span>`;
          }).join('')}
        </div>` : '';

      // ── PICA pending ──
      const pendingHtml = pendingPica.length ? `
        <div style="margin-bottom:6px">
          <span style="font-size:.72rem;font-weight:700;color:#dc2626;display:flex;align-items:center;gap:5px;margin-bottom:6px">
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/></svg>
            PICA — ${pendingPica.length} Item Menunggu Response
          </span>
          ${pendingPica.map(it => `
            <div style="border:1px solid #fca5a5;border-radius:7px;padding:10px 14px;background:#fff1f2;margin-bottom:6px">
              <div style="display:flex;align-items:flex-start;justify-content:space-between;flex-wrap:wrap;gap:8px">
                <div style="flex:1;min-width:0">
                  <div style="font-weight:700;font-size:.85rem;color:#1a1a1a">${it.namaPemeriksaan}</div>
                  <div style="font-size:.77rem;color:#374151;margin-top:2px;line-height:1.4">${it.hasilPemeriksaan}</div>
                  ${it.pica.currentCondition ? `<div style="margin-top:5px;font-size:.77rem"><em style="color:#6b7280">Kondisi (Auditor):</em> ${it.pica.currentCondition}</div>` : ''}
                </div>
                ${isBranch ? `
                <button onclick="window._openPicaResponseModal('${it._sid}',${it._idx})"
                        style="background:#dc2626;color:#fff;border:none;border-radius:6px;padding:7px 14px;
                               cursor:pointer;font-size:.79rem;font-weight:700;white-space:nowrap;flex-shrink:0">
                  ✏ Isi Response PICA
                </button>` : ''}
              </div>
            </div>`).join('')}
        </div>` : '';

      // ── PICA completed ──
      const completedHtml = completedPica.length ? completedPica.map(it => `
        <div style="border:1px solid #86efac;border-radius:7px;padding:8px 14px;background:#f0fdf4;margin-bottom:6px">
          <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:6px">
            <div>
              <span style="font-size:.7rem;font-weight:700;color:#166534;text-transform:uppercase">✓ PICA Selesai</span>
              <div style="font-weight:700;font-size:.85rem;margin-top:1px">${it.namaPemeriksaan}</div>
            </div>
            <button onclick="window._openPicaResponseModal('${it._sid}',${it._idx})"
                    style="background:#dcfce7;color:#166534;border:1px solid #86efac;border-radius:6px;padding:4px 12px;cursor:pointer;font-size:.77rem;font-weight:700">
              Lihat Detail
            </button>
          </div>
          <div style="margin-top:7px;display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:4px;font-size:.75rem;color:#374151">
            <div><span style="color:#6b7280;font-weight:600">Problem:</span> ${it.pica.problemIdentification||'—'}</div>
            <div><span style="color:#6b7280;font-weight:600">Action:</span> ${it.pica.correctiveAction||'—'}</div>
            <div><span style="color:#6b7280;font-weight:600">Deadline:</span> <strong style="color:#166534">${it.pica.deadlineCorrective||'—'}</strong></div>
            <div><span style="color:#6b7280;font-weight:600">PIC:</span> ${it.pica.picCorrective||'—'}</div>
            ${it.pica.relationShipDept ? `<div><span style="color:#6b7280;font-weight:600">Dept:</span> ${it.pica.relationShipDept}</div>` : ''}
            ${it.pica.relationShip    ? `<div><span style="color:#6b7280;font-weight:600">Relation:</span> ${it.pica.relationShip}</div>` : ''}
          </div>
        </div>`).join('') : '';

      return `<div style="margin-top:10px;border-top:1px solid var(--border);padding-top:10px">
        ${gradHtml}${pendingHtml}${completedHtml}
      </div>`;
    } catch(e) {
      console.error('[PICA Task Section]', e);
      return '';
    }
  }

  // ── Task Modal (Submit) ──────────────────────────
  let _currentTaskId = null;

  window._openTaskModal = function (taskId) {
    tasks = loadTasks();
    const t = tasks.find(x => x.id == taskId);
    if (!t) return;
    _currentTaskId = taskId;

    const planInfo = plans.find(p => p.id == t.planId);
    const isOwner  = t.assignedTo === session.username;
    const canEdit  = isOwner && (t.status === 'pending' || t.status === 'koord_rejected' || t.status === 'manajer_rejected' || t.status === 'coo_rejected');

    document.getElementById('taskModalTitle').textContent = canEdit ? 'Submit Task Audit' : 'Detail Task Audit';
    document.getElementById('taskPlanInfo').innerHTML = `
      <div class="unit-info-grid">
        <div class="unit-info-item"><label>No SPT</label><span style="font-weight:700">${t.noSPT}</span></div>
        <div class="unit-info-item"><label>Jenis Audit</label><span>${t.jenisAudit}</span></div>
        <div class="unit-info-item"><label>Cabang</label><span>${t.cabangPlan}${t.cabangArea ? ' ' + areaBadge(t.cabangArea) : ''}</span></div>
        <div class="unit-info-item"><label>Tgl Plan</label><span>${t.tanggalPlan}</span></div>
        <div class="unit-info-item"><label>Assigned To</label><span>${getUserDisplay(t.assignedTo)}</span></div>
        <div class="unit-info-item"><label>Status</label><span>${taskStatusBadge(t.status)}</span></div>
      </div>`;

    document.getElementById('taskTglMulai').value   = t.tglMulai || '';
    document.getElementById('taskTglSelesai').value = t.tglSelesai || '';
    document.getElementById('taskCatatan').value    = t.catatan || '';
    document.getElementById('taskFileInfo').textContent = t.fileName ? `File tersimpan: ${t.fileName}` : '';

    const fillSection = document.getElementById('taskFillSection');
    const submitBtn   = document.getElementById('btnSubmitTask');

    // Hanya ADM dan Auditor yang boleh melihat dan upload berkas laporan
    const canUploadFile = (session.role === 'adm' || session.role === 'admin' || session.role === 'auditor');
    const uploadFileGroup = document.getElementById('taskFile')?.closest('.form-group');
    if (uploadFileGroup) uploadFileGroup.style.display = canUploadFile ? '' : 'none';

    if (canEdit) {
      fillSection.style.display = '';
      submitBtn.classList.remove('hidden');
      document.getElementById('taskTglMulai').disabled   = false;
      document.getElementById('taskTglSelesai').disabled = false;
      document.getElementById('taskCatatan').disabled    = false;
    } else {
      fillSection.style.display = '';
      submitBtn.classList.add('hidden');
      document.getElementById('taskTglMulai').disabled   = true;
      document.getElementById('taskTglSelesai').disabled = true;
      document.getElementById('taskCatatan').disabled    = true;
    }

    // Inject status log
    let logEl = document.getElementById('taskStatusLogSection');
    if (!logEl) {
      logEl = document.createElement('div');
      logEl.id = 'taskStatusLogSection';
      document.getElementById('taskModalBody').appendChild(logEl);
    }
    logEl.innerHTML = renderStatusLog(t.statusLog);

    document.getElementById('taskModal').classList.remove('hidden');
  };

  window._closeTaskModal = function () {
    document.getElementById('taskModal').classList.add('hidden');
    _currentTaskId = null;
    document.getElementById('taskFile').value = '';
    document.getElementById('taskFileInfo').textContent = '';
    const logEl = document.getElementById('taskStatusLogSection');
    if (logEl) logEl.innerHTML = '';
  };

  function submitTask() {
    if (!_currentTaskId) return;
    tasks = loadTasks();
    const idx = tasks.findIndex(t => t.id == _currentTaskId);
    if (idx < 0) return;

    const tglMulai   = document.getElementById('taskTglMulai').value;
    const tglSelesai = document.getElementById('taskTglSelesai').value;
    const fileInput  = document.getElementById('taskFile');
    const catatan    = document.getElementById('taskCatatan').value.trim();

    if (!tglMulai)   { showToast('Isi Tgl Mulai Audit.', 'error'); return; }
    if (!tglSelesai) { showToast('Isi Tgl Selesai Audit.', 'error'); return; }

    const existingFile = tasks[idx].fileName;
    const newFile = fileInput.files[0];
    if (!existingFile && !newFile) { showToast('Upload file laporan XLS/XLSX terlebih dahulu.', 'error'); return; }

    const updatedTask = {
      ...tasks[idx],
      tglMulai,
      tglSelesai,
      fileName:    newFile ? newFile.name : existingFile,
      catatan,
      status:      'submitted',
      submittedAt: new Date().toISOString(),
    };
    updatedTask.statusLog = addStatusLog(updatedTask, 'submitted', catatan || '');
    tasks[idx] = updatedTask;
    saveTasks(tasks);
    window._closeTaskModal();
    renderTaskSection();
    renderPlanSection();
    updateTaskBadge();
    showToast('Task berhasil disubmit. Menunggu approval Koordinator.', 'success');
  }

  // ── Approve Modal ────────────────────────────────
  let _currentApproveId = null;

  window._openApproveModal = function (taskId) {
    tasks = loadTasks();
    const t = tasks.find(x => x.id == taskId);
    if (!t) return;
    _currentApproveId = taskId;

    // Dynamic title based on current task status
    const titleEl = document.getElementById('approveModalTitle');
    if (titleEl) {
      if (t.status === 'submitted')            titleEl.textContent = 'Review Koordinator';
      else if (t.status === 'koord_approved')    titleEl.textContent = 'Review Manajer Audit';
      else if (t.status === 'manajer_approved')  titleEl.textContent = 'Review COO';
      else                                       titleEl.textContent = 'Review Task';
    }

    document.getElementById('approvePlanInfo').innerHTML = `
      <div class="unit-info-grid">
        <div class="unit-info-item"><label>No SPT</label><span style="font-weight:700">${t.noSPT}</span></div>
        <div class="unit-info-item"><label>Jenis Audit</label><span>${t.jenisAudit}</span></div>
        <div class="unit-info-item"><label>Cabang</label><span>${t.cabangPlan}${t.cabangArea ? ' ' + areaBadge(t.cabangArea) : ''}</span></div>
        <div class="unit-info-item"><label>Auditor</label><span>${getUserDisplay(t.assignedTo)}</span></div>
        <div class="unit-info-item"><label>Tgl Mulai</label><span>${t.tglMulai || '—'}</span></div>
        <div class="unit-info-item"><label>Tgl Selesai</label><span>${t.tglSelesai || '—'}</span></div>
        <div class="unit-info-item"><label>File</label><span class="task-file-badge">${t.fileName || '—'}</span></div>
        <div class="unit-info-item"><label>Catatan Auditor</label><span>${t.catatan || '—'}</span></div>
        <div class="unit-info-item"><label>Status Saat Ini</label><span>${taskStatusBadge(t.status)}</span></div>
      </div>`;

    document.getElementById('approveComment').value = '';

    // Inject status log after plan info
    let logEl = document.getElementById('approveStatusLogSection');
    if (!logEl) {
      logEl = document.createElement('div');
      logEl.id = 'approveStatusLogSection';
      document.getElementById('approvePlanInfo').after(logEl);
    }
    logEl.innerHTML = renderStatusLog(t.statusLog);

    document.getElementById('approveModal').classList.remove('hidden');
  };

  window._closeApproveModal = function () {
    document.getElementById('approveModal').classList.add('hidden');
    _currentApproveId = null;
    const logEl = document.getElementById('approveStatusLogSection');
    if (logEl) logEl.innerHTML = '';
  };

  function doApproveTask(approve) {
    if (!_currentApproveId) return;
    tasks = loadTasks();
    const idx = tasks.findIndex(t => t.id == _currentApproveId);
    if (idx < 0) return;

    const comment   = document.getElementById('approveComment').value.trim();
    const curStatus = tasks[idx].status;
    let newStatus;

    if (curStatus === 'submitted') {
      // Koordinator level
      newStatus = approve ? 'koord_approved' : 'koord_rejected';
    } else if (curStatus === 'koord_approved') {
      // Manajer Audit level
      newStatus = approve ? 'manajer_approved' : 'manajer_rejected';
    } else if (curStatus === 'manajer_approved') {
      // COO level
      newStatus = approve ? 'coo_approved' : 'coo_rejected';
    } else {
      window._closeApproveModal();
      return;
    }

    const updatedTask = {
      ...tasks[idx],
      status:     newStatus,
      approvedAt: new Date().toISOString(),
      approvedBy: session.username,
      reviewNote: comment,
    };
    updatedTask.statusLog = addStatusLog(updatedTask, newStatus, comment);
    tasks[idx] = updatedTask;
    saveTasks(tasks);

    // Sinkronisasi status plan berdasarkan task terkini
    _checkPlanComplete(tasks, tasks[idx].planId);

    window._closeApproveModal();
    renderTaskSection();
    renderPlanSection();
    updateTaskBadge();
    updateAuditBadge();

    let msg = '';
    if (newStatus === 'koord_approved')        msg = 'Disetujui Koordinator. Menunggu approval Manajer Audit.';
    else if (newStatus === 'koord_rejected')   msg = 'Ditolak oleh Koordinator.';
    else if (newStatus === 'manajer_approved') msg = 'Disetujui Manajer Audit. Menunggu approval COO.';
    else if (newStatus === 'manajer_rejected') msg = 'Ditolak oleh Manajer Audit.';
    else if (newStatus === 'coo_approved')     msg = 'Disetujui COO. Task masuk ke menu Audit.';
    else if (newStatus === 'coo_rejected')     msg = 'Ditolak oleh COO.';
    showToast(msg, approve ? 'success' : 'info');
  }

  function updateTaskBadge() {
    tasks = loadTasks().filter(t => !t.isMandiri);
    const badge = document.getElementById('navTaskBadge');
    if (!badge) return;
    let count = 0;
    const _r = session.role;
    if (_r === 'koordinator') {
      count = tasks.filter(t => t.status === 'submitted').length;
    } else if (_r === 'manajer') {
      count = tasks.filter(t => t.status === 'koord_approved').length
              + loadSk().filter(s => s.status === 'pending_manajer').length;
    } else if (_r === 'coo') {
      count = tasks.filter(t => t.status === 'manajer_approved').length;
    } else if (_r === 'admin') {
      const rekPending = loadRekomendasi().filter(r => r.status === 'pending_afd').length;
      const skPending  = loadSk().filter(s => ['pending_manajer','pending_afd'].includes(s.status)).length;
      count = tasks.filter(t => ['submitted', 'koord_approved', 'manajer_approved'].includes(t.status)).length
              + rekPending + skPending;
    } else if (_r === 'afd') {
      // Badge = jumlah rekomendasi yang menunggu Keputusan AFD + SK pending AFD
      count = loadRekomendasi().filter(r => r.status === 'pending_afd').length
              + loadSk().filter(s => s.status === 'pending_afd').length;
    } else if (_r === 'rss') {
      // Badge = jumlah rekomendasi pending_rss, filter per wilayah jika user RSS punya wilayah
      const allPendingRss = loadRekomendasi().filter(r => r.status === 'pending_rss');
      if (session.unitUsaha) {
        const plans   = loadPlans();
        const wilBadge = session.unitUsaha.toLowerCase().trim();
        count = allPendingRss.filter(r => {
          const pl = plans.find(p => String(p.id) === String(r.planId));
          return (pl?.cabangArea || '').toLowerCase().trim() === wilBadge;
        }).length;
      } else {
        count = allPendingRss.length;
      }
    } else if (_r === 'so' || _r === 'csc' || _r === 'whs' || _r === 'kasir') {
      // Badge = jumlah task audit_started untuk cabang mereka (perlu mulai cabang)
      const myUU = (session.unitUsaha || '').trim().toUpperCase();
      count = tasks.filter(t =>
        t.status === 'audit_started' && (!myUU || (t.cabangPlan || '').trim().toUpperCase() === myUU)
      ).length;
    } else {
      count = tasks.filter(t =>
        t.assignedTo === session.username &&
        ['pending', 'koord_rejected', 'manajer_rejected', 'coo_rejected'].includes(t.status)
      ).length;
    }
    // Tambahkan unread SK notif milik user ini
    try { count += loadSkNotif().filter(n => n.toUsername === session.username && !n.read).length; } catch {}
    badge.textContent = count;
    badge.classList.toggle('hidden', count === 0);
  }

  function updateAuditBadge() {
    tasks = loadTasks().filter(t => !t.isMandiri);
    const badge = document.getElementById('navAuditBadge');
    if (!badge) return;
    let count = 0;
    const role = session.role;
    if (role === 'auditor' || role === 'admin') {
      count = tasks.filter(t => t.status === 'coo_approved' && t.assignedTo === session.username).length;
    } else if (role === 'so' || role === 'csc' || role === 'whs') {
      count = tasks.filter(t => t.status === 'audit_started').length;
    } else if (can('view-all-plans')) {
      count = tasks.filter(t => ['coo_approved','audit_started','in_progress'].includes(t.status)).length;
    }
    badge.textContent = count;
    badge.classList.toggle('hidden', count === 0);
  }

  // ── Audit Context (set when navigating from Audit → Pemeriksaan) ──
  let _auditContext = null; // { taskId, planId, noSPT, cabang, area }

  window._openAuditPemeriksaan = function (taskId, section) {
    tasks = loadTasks();
    const t = tasks.find(x => x.id == taskId);
    if (!t) return;
    // Validate: only the matching unit usaha account can perform inspection
    if ((session.role === 'so' || session.role === 'csc' || session.role === 'whs') && session.unitUsaha) {
      if ((t.cabangPlan || '').trim().toUpperCase() !== session.unitUsaha.trim().toUpperCase()) {
        showToast(`Anda hanya dapat memeriksa cabang ${session.unitUsaha}.`, 'error');
        return;
      }
    }
    _auditContext = { taskId: t.id, planId: t.planId, noSPT: t.noSPT, cabang: t.cabangPlan, area: t.cabangArea };
    // Load onhand sesuai plan — kosong jika plan berbeda dari yg tersimpan
    smhOnhand = _loadOnhandForPlan(t.planId);
    showSection(section || 'pemeriksaan-smh');
    // Show context banner in the target section
    _refreshAuditContextBanner();
  };

  function _refreshAuditContextBanner() {
    const banner = document.getElementById('auditContextBanner');
    if (!banner) return;
    if (!_auditContext) {
      banner.classList.add('hidden');
      return;
    }
    banner.classList.remove('hidden');
    banner.innerHTML = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="flex-shrink:0"><path d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2"/><rect x="9" y="3" width="6" height="4" rx="1"/></svg>
      <span><strong>Audit Aktif:</strong> ${_auditContext.noSPT} — ${_auditContext.cabang}${_auditContext.area ? ' <span class="badge-area ' + _auditContext.area.toLowerCase().replace(/\s/g,'-') + '">' + _auditContext.area + '</span>' : ''}</span>
      <button onclick="window._clearAuditContext()" style="margin-left:auto;background:none;border:none;cursor:pointer;font-size:.75rem;color:#065f46">✕ Tutup Konteks</button>`;
  }

  window._clearAuditContext = function () {
    _auditContext = null;
    _refreshAuditContextBanner();
    populateOnhandDropdown();
  };

  // ── Audit Section ────────────────────────────────
  function renderAuditSection() {
    tasks = loadTasks().filter(t => !t.isMandiri);
    plans = _syncAllPlanStatuses();
    const container = document.getElementById('auditContent');
    if (!container) return;

    // Determine visible tasks based on role
    const auditStatuses = ['coo_approved', 'audit_started', 'in_progress'];
    let visibleTasks;
    const role = session.role;
    if (role === 'so' || role === 'csc' || role === 'whs' || role === 'kasir') {
      // Branch staff: only see tasks for THEIR unit usaha
      const myUU = (session.unitUsaha || '').trim().toUpperCase();
      visibleTasks = tasks.filter(t =>
        auditStatuses.includes(t.status) &&
        (!myUU || (t.cabangPlan || '').trim().toUpperCase() === myUU)
      );
    } else if (role === 'auditor') {
      visibleTasks = tasks.filter(t => t.assignedTo === session.username && auditStatuses.includes(t.status));
    } else {
      visibleTasks = tasks.filter(t => auditStatuses.includes(t.status));
    }

    if (!visibleTasks.length) {
      container.innerHTML = `<div class="empty-state" style="padding:60px">
        <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2"/><rect x="9" y="3" width="6" height="4" rx="1"/><path d="M9 12h6M9 16h4"/></svg>
        <p>Belum ada plan yang siap diaudit.</p>
        <p style="font-size:.82rem;color:var(--text-secondary)">Plan yang telah disetujui COO akan muncul di sini.</p>
      </div>`;
      return;
    }

    // Group tasks by planId
    const byPlan = {};
    visibleTasks.forEach(t => {
      if (!byPlan[t.planId]) byPlan[t.planId] = [];
      byPlan[t.planId].push(t);
    });

    let html = '';
    Object.entries(byPlan).forEach(([planId, ptasks]) => {
      const plan = plans.find(p => p.id == planId);
      const planLabel = plan ? `${plan.noSPT} — ${plan.jenisAudit}` : `Plan #${planId}`;
      const cabang = ptasks[0].cabangPlan;
      const area = ptasks[0].cabangArea;

      html += `<div class="audit-plan-group" style="margin-bottom:16px">
        <div style="padding:12px 16px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px">
          <div>
            <div style="font-weight:700;font-size:.95rem">${planLabel}</div>
            <div style="font-size:.82rem;color:var(--text-secondary)">${cabang}${area ? ' ' + areaBadge(area) : ''}</div>
          </div>
          ${plan ? planStatusBadge(plan.status) : ''}
        </div>`;

      ptasks.forEach(t => {
        const assignee = getUserDisplay(t.assignedTo);
        let actionBtn = '';

        // Determine if this user can actively work on this task
        const isBranchStaff = (role === 'so' || role === 'csc' || role === 'whs');
        const isMyAuditorTask = (role === 'auditor' || role === 'admin') && t.assignedTo === session.username;
        const isActiveTask  = ['audit_started', 'in_progress'].includes(t.status);

        let pemeriksaanBar = '';

        // ── Mulai Audit (Auditor) ──
        if (isMyAuditorTask && t.status === 'coo_approved') {
          actionBtn = `<button class="btn-primary" style="font-size:.8rem;padding:6px 16px" onclick="window._mulaiAudit(${t.id})">Mulai Audit</button>`;
        }

        // Rekomendasi hanya diakses dari Report Audit untuk non-auditor
        // (kecuali admin yang bisa akses dari mana saja)
        const allRekomD  = loadRekomendasi();
        const taskRekomD = allRekomD.find(r => String(r.planId) === String(t.planId));

        // ── Pemeriksaan bar: hanya untuk auditor (bukan SO/CSC/WHS) ──
        if (isMyAuditorTask && isActiveTask) {
          const hasilCount = loadSmhData(SMH_HASIL_KEY)
            .filter(h => String(h.auditPlanId) === String(t.planId)).length;
          const luarCount  = loadSmhData(SMH_LUAR_KEY)
            .filter(l => String(l.auditPlanId) === String(t.planId)).length;
          const kasCount   = loadKasAudit()
            .filter(k => String(k.planId) === String(t.planId)).length;
          const hgpCount     = (loadHgp(HGP_HASIL_KEY).length || 0) + (loadHgp(HGP_WO_KEY).length || 0);
          const gradingCount = loadGradingSessions().filter(s => String(s.planId) === String(t.planId)).length;

          // Load saved state per plan
          const _savedPem    = loadSavedPem();
          const _isSavedType = (tp) => _savedPem.some(s => String(s.planId) === String(t.planId) && s.type === tp);
          const smhSaved     = _isSavedType('smh');

          const kasSaved     = _isSavedType('kas');
          const hgpSaved     = _isSavedType('hgp');

          // Menu terbuka begitu auditor mulai audit (audit_started atau in_progress)
          const pemLocked = !['audit_started', 'in_progress'].includes(t.status);
          const pemBtnAttr = pemLocked
            ? 'disabled title="Mulai audit terlebih dahulu" style="opacity:.45;cursor:not-allowed;filter:grayscale(.6)"'
            : '';

          const waitingLabel = pemLocked
            ? `<div style="font-size:.78rem;color:#b45309;background:#fef3c7;padding:6px 10px;border-radius:5px;margin-bottom:6px">
                 ⏳ Menu pemeriksaan <strong>terkunci</strong> — Mulai audit terlebih dahulu.
               </div>`
            : '';

          // Selesai Audit: only for auditor (kepala tim) when task is in_progress
          // Branch staff use _selesaiCabang; auditor kepala tim uses _selesaiAudit
          const selesaikanBtn = t.status === 'in_progress'
            ? (isBranchStaff
                ? `<button class="audit-pem-btn" style="background:#fee2e2;color:#dc2626" onclick="window._selesaiCabang(${t.id})">
                     <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg>
                     <span>Selesai Cabang</span>
                   </button>`
                : (isMyAuditorTask && t.isKepala
                    ? `<button class="audit-pem-btn" style="background:#1e3a5f;color:#fff" onclick="window._selesaiAudit(${t.id})">
                         <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg>
                         <span>Selesai Audit</span>
                       </button>`
                    : ''))
            : '';

          // Build simpan pemeriksaan submenu
          const _mkSimpanBtn = (type, count, saved, label) => count > 0 ? `
            <button class="audit-pem-btn" style="background:${saved?'#dcfce7':'#f0fdf4'};color:${saved?'#166534':'#065f46'};border:1px solid ${saved?'#86efac':'#6ee7b7'};font-size:.77rem"
                    onclick="window._simpanPemeriksaan('${t.planId}','${type}')">
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/>
                <polyline points="17 21 17 13 7 13 7 21"/>
              </svg>
              <span>${saved ? '✓ ' : ''}Simpan ${label}</span>
              <span class="audit-pem-count" style="background:${saved?'#22c55e':'#64748b'}">${count}</span>
            </button>` : '';
          const simpanBtns = [
            // SMH: tombol simpan ada di dalam tab Riwayat Pemeriksaan SMH, bukan di sini
            // Kas: tombol simpan ada di dalam modal Pemeriksaan Kas, bukan di sini
            // HGP: tombol simpan ada di dalam tab Hasil Pemeriksaan HGP, bukan di sini
          ].filter(Boolean).join('');
          const simpanSection = '';

          const _pm = (key) => isPemMenuEnabled(t.jenisAudit, key);

          pemeriksaanBar = `
            <div class="audit-pemeriksaan-bar">
              <div class="audit-pemeriksaan-title">MENU PEMERIKSAAN</div>
              ${waitingLabel}
              <div class="audit-pemeriksaan-btns">
                ${_pm('smh') ? `<button class="audit-pem-btn audit-pem-btn--smh" ${pemBtnAttr} onclick="${pemLocked ? '' : `window._openAuditPemeriksaan(${t.id},'pemeriksaan-smh')`}">
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
                  <span>Pemeriksaan Unit SMH</span>
                  ${hasilCount > 0 ? `<span class="audit-pem-count">${hasilCount}</span>` : ''}
                  ${pemLocked ? '<span style="font-size:.68rem;margin-left:4px">🔒</span>' : ''}
                </button>` : ''}
                ${_pm('luar') ? `<button class="audit-pem-btn audit-pem-btn--luar" ${pemBtnAttr} onclick="${pemLocked ? '' : `window._openLuarFisikModal(${t.id})`}">
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2"/><rect x="9" y="3" width="6" height="4" rx="1"/></svg>
                  <span>Perlengkapan Luar Fisik</span>
                  ${luarCount > 0 ? `<span class="audit-pem-count">${luarCount}</span>` : ''}
                  ${pemLocked ? '<span style="font-size:.68rem;margin-left:4px">🔒</span>' : ''}
                </button>` : ''}
                ${_pm('kas') ? `<button class="audit-pem-btn audit-pem-btn--kas" ${pemBtnAttr} onclick="${pemLocked ? '' : `window._openKasAuditModal('${t.id}')`}">
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="5" width="20" height="14" rx="2"/><line x1="2" y1="10" x2="22" y2="10"/></svg>
                  <span>Pemeriksaan Kas</span>
                  ${kasCount > 0 ? `<span class="audit-pem-count">${kasCount}</span>` : ''}
                  ${pemLocked ? '<span style="font-size:.68rem;margin-left:4px">🔒</span>' : ''}
                </button>` : ''}
                ${_pm('hgp') ? `<button class="audit-pem-btn" style="background:#ecfdf5;color:#065f46;border:1px solid #6ee7b7" ${pemBtnAttr}
                        onclick="${pemLocked ? '' : `window._openHgpFromAudit('${t.planId}')`}">
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                    <path d="M9 3H5a2 2 0 00-2 2v4m6-6h10a2 2 0 012 2v4M9 3v18m0 0h10a2 2 0 002-2V9M9 21H5a2 2 0 01-2-2V9m0 0h18"/>
                  </svg>
                  <span>HGP &amp; AHM Oil's</span>
                  ${(() => { const hgpHasilLen = loadHgp ? loadHgp(HGP_HASIL_KEY).length : 0; return hgpHasilLen > 0 ? `<span class="audit-pem-count" style="background:#059669">${hgpHasilLen}</span>` : ''; })()}
                  ${pemLocked ? '<span style="font-size:.68rem;margin-left:4px">🔒</span>' : ''}
                </button>` : ''}
                ${(() => {
                  if (!_pm('bank')) return '';
                  const bankCount = loadBankPem().filter(r => String(r.planId) === String(t.planId)).length;
                  return `<button class="audit-pem-btn" style="background:#f0fdfa;color:#0f766e;border:1px solid #99f6e4" ${pemBtnAttr}
                          onclick="${pemLocked ? '' : `window._openBankPemModal(${t.id})`}">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                      <rect x="2" y="5" width="20" height="14" rx="2"/><line x1="2" y1="10" x2="22" y2="10"/>
                      <line x1="6" y1="15" x2="10" y2="15"/>
                    </svg>
                    <span>Pemeriksaan Bank</span>
                    ${bankCount > 0 ? `<span class="audit-pem-count" style="background:#0d9488">${bankCount}</span>` : ''}
                    ${pemLocked ? '<span style="font-size:.68rem;margin-left:4px">🔒</span>' : ''}
                  </button>`;
                })()}
                ${(() => {
                  if (!_pm('meterai')) return '';
                  const mtrSaved = loadMeterai().some(m => String(m.planId) === String(t.planId));
                  return `<button class="audit-pem-btn" style="background:#fffbeb;color:#92400e;border:1px solid #fcd34d" ${pemBtnAttr}
                          onclick="${pemLocked ? '' : `window._openMateraiModal(${t.id})`}">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                      <rect x="3" y="3" width="18" height="18" rx="2"/><path d="M9 9h6M9 13h6M9 17h4"/>
                    </svg>
                    <span>Materai Tempel</span>
                    ${mtrSaved ? '<span class="audit-pem-count" style="background:#b45309">✓</span>' : ''}
                    ${pemLocked ? '<span style="font-size:.68rem;margin-left:4px">🔒</span>' : ''}
                  </button>`;
                })()}
                ${(() => {
                  if (!_pm('bpkb')) return '';
                  const bpkbCount = loadBpkbScan().filter(s => String(s.planId) === String(t.planId)).length;
                  const bpkbSaved = loadSavedPem().some(s => String(s.planId) === String(t.planId) && s.type === 'bpkb');
                  return `<button class="audit-pem-btn" style="background:#eff6ff;color:#1e40af;border:1px solid #bfdbfe" ${pemBtnAttr}
                          onclick="${pemLocked ? '' : `window._openBpkbModal(${t.id})`}">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                      <rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M9 21V9"/>
                    </svg>
                    <span>BPKB Onhand</span>
                    ${bpkbCount > 0 ? `<span class="audit-pem-count" style="background:${bpkbSaved?'#1e40af':'#64748b'}">${bpkbCount}</span>` : ''}
                    ${pemLocked ? '<span style="font-size:.68rem;margin-left:4px">🔒</span>' : ''}
                  </button>`;
                })()}
                ${(() => {
                  if (!_pm('lapos')) return '';
                  const laposSaved = loadSavedPem().some(s => String(s.planId) === String(t.planId) && s.type === 'lapos_bpkb');
                  const laposHasData = loadLaposAll().some(d => String(d.planId) === String(t.planId));
                  return `<button class="audit-pem-btn" style="background:#f5f3ff;color:#5b21b6;border:1px solid #ddd6fe" ${pemBtnAttr}
                          onclick="${pemLocked ? '' : `window._openLaposBpkb(${t.id})`}">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                      <path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/>
                      <polyline points="14 2 14 8 20 8"/>
                      <line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="12" y2="17"/>
                    </svg>
                    <span>Lapos &amp; Inproses BPKB</span>
                    ${laposHasData ? `<span class="audit-pem-count" style="background:${laposSaved?'#5b21b6':'#64748b'}">✓</span>` : ''}
                    ${pemLocked ? '<span style="font-size:.68rem;margin-left:4px">🔒</span>' : ''}
                  </button>`;
                })()}
                ${(() => {
                  if (!_pm('kwt')) return '';
                  const kwtSaved   = loadSavedPem().some(s => String(s.planId) === String(t.planId) && s.type === 'kwt_gantung');
                  const kwtHasData = loadKwtDb().length > 0;
                  const kwtFisik   = kwtHasData ? loadKwtScan().filter(r => String(r.planId)===String(t.planId) && r.fisik).length : 0;
                  return `<button class="audit-pem-btn" style="background:#f0fdf4;color:#0f766e;border:1px solid #6ee7b7" ${pemBtnAttr}
                          onclick="${pemLocked ? '' : `window._openKwtGantung(${t.id})`}">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                      <rect x="2" y="5" width="20" height="14" rx="2"/><line x1="2" y1="10" x2="22" y2="10"/>
                    </svg>
                    <span>Kwitansi Gantung</span>
                    ${kwtFisik > 0 ? `<span class="audit-pem-count" style="background:${kwtSaved?'#0f766e':'#64748b'}">${kwtFisik}</span>` : ''}
                    ${pemLocked ? '<span style="font-size:.68rem;margin-left:4px">🔒</span>' : ''}
                  </button>`;
                })()}
                ${(() => {
                  if (!_pm('piutang')) return '';
                  const prSaved   = loadSavedPem().some(s => String(s.planId) === String(t.planId) && s.type === 'piutang_reg');
                  const prRec     = getPiutangReg(t.planId);
                  const prHasData = prRec && prRec.rows && prRec.rows.length > 0;
                  return `<button class="audit-pem-btn" style="background:#f0fdf4;color:#15803d;border:1px solid #86efac" ${pemBtnAttr}
                          onclick="${pemLocked ? '' : `window._openPiutangReg(${t.id})`}">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                      <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2z"/>
                      <path d="M12 6v6l4 2"/>
                    </svg>
                    <span>Piutang Reguler</span>
                    ${prHasData ? `<span class="audit-pem-count" style="background:${prSaved?'#15803d':'#64748b'}">${prRec.rows.length}</span>` : ''}
                    ${pemLocked ? '<span style="font-size:.68rem;margin-left:4px">🔒</span>' : ''}
                  </button>`;
                })()}
                ${(() => {
                  if (!_pm('kds')) return '';
                  const kdsSaved   = loadSavedPem().some(s => String(s.planId) === String(t.planId) && s.type === 'tunggakan_kds');
                  const kdsRec     = getKds(t.planId);
                  const kdsHasData = kdsRec && kdsRec.rows && kdsRec.rows.length > 0;
                  return `<button class="audit-pem-btn" style="background:#fff7ed;color:#92400e;border:1px solid #fcd34d" ${pemBtnAttr}
                          onclick="${pemLocked ? '' : `window._openTunggakanKds(${t.id})`}">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                      <path d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2"/>
                      <rect x="9" y="3" width="6" height="4" rx="1"/>
                      <line x1="9" y1="12" x2="15" y2="12"/><line x1="9" y1="16" x2="13" y2="16"/>
                    </svg>
                    <span>Tunggakan KDS</span>
                    ${kdsHasData ? `<span class="audit-pem-count" style="background:${kdsSaved?'#92400e':'#64748b'}">${kdsRec.rows.length}</span>` : ''}
                    ${pemLocked ? '<span style="font-size:.68rem;margin-left:4px">🔒</span>' : ''}
                  </button>`;
                })()}
                ${(() => {
                  if (!_pm('ttp')) return '';
                  const ttpSaved   = loadSavedPem().some(s => String(s.planId) === String(t.planId) && s.type === 'ttp_gantung');
                  const ttpRec     = getTtp(t.planId);
                  const ttpHasData = ttpRec && ttpRec.rows && ttpRec.rows.length > 0;
                  const ttpFisik   = ttpHasData ? ttpRec.rows.filter(r => r.fisik).length : 0;
                  return `<button class="audit-pem-btn" style="background:#eff6ff;color:#1e3a5f;border:1px solid #93c5fd" ${pemBtnAttr}
                          onclick="${pemLocked ? '' : `window._openTtpGantung(${t.id})`}">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                      <rect x="2" y="3" width="20" height="14" rx="2"/>
                      <line x1="8" y1="21" x2="16" y2="21"/>
                      <line x1="12" y1="17" x2="12" y2="21"/>
                    </svg>
                    <span>TTP Gantung</span>
                    ${ttpHasData ? `<span class="audit-pem-count" style="background:${ttpSaved?'#1e3a5f':'#64748b'}">${ttpRec.rows.length}</span>` : ''}
                    ${pemLocked ? '<span style="font-size:.68rem;margin-left:4px">🔒</span>' : ''}
                  </button>`;
                })()}
                ${(() => {
                  if (!_pm('mt')) return '';
                  const mtSaved   = loadSavedPem().some(s => String(s.planId) === String(t.planId) && s.type === 'pem_mt');
                  const mtSessions = loadMtSessions(t.planId);
                  const mtWithData = mtSessions.filter(s => (s.items||[]).length > 0);
                  const mtHasData  = mtWithData.length > 0;
                  return `<button class="audit-pem-btn" style="background:#fdf4ff;color:#6b21a8;border:1px solid #d8b4fe" ${pemBtnAttr}
                          onclick="${pemLocked ? '' : `window._openMtPem(${t.id})`}">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                      <path d="M14.7 6.3a1 1 0 000 1.4l1.6 1.6a1 1 0 001.4 0l3.77-3.77a6 6 0 01-7.94 7.94l-6.91 6.91a2.12 2.12 0 01-3-3l6.91-6.91a6 6 0 017.94-7.94l-3.76 3.76z"/>
                    </svg>
                    <span>Pemeriksaan MT</span>
                    ${mtHasData ? `<span class="audit-pem-count" style="background:${mtSaved?'#6b21a8':'#64748b'}">${mtWithData.length}</span>` : ''}
                    ${pemLocked ? '<span style="font-size:.68rem;margin-left:4px">🔒</span>' : ''}
                  </button>`;
                })()}
                ${(() => {
                  if (!_pm('lampiran')) return '';
                  const lpRec    = getLampiranForPlan(t.planId);
                  const lpCount  = (lpRec.files||[]).length;
                  const lpSaved  = loadSavedPem().some(s => String(s.planId)===String(t.planId) && s.type==='lampiran');
                  return `<button class="audit-pem-btn" style="background:#f0f9ff;color:#0369a1;border:1px solid #93c5fd"
                          onclick="window._openLampiranModal(${t.id})">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                      <path d="M21.44 11.05l-9.19 9.19a6 6 0 01-8.49-8.49l9.19-9.19a4 4 0 015.66 5.66l-9.2 9.19a2 2 0 01-2.83-2.83l8.49-8.48"/>
                    </svg>
                    <span>Lampiran</span>
                    ${lpCount > 0 ? `<span class="audit-pem-count" style="background:${lpSaved?'#0369a1':'#64748b'}">${lpCount}</span>` : ''}
                  </button>`;
                })()}
                ${selesaikanBtn}
              </div>

              <!-- ── Grading & Rekomendasi — seksi terpisah di bawah ── -->
              <div style="border-top:1px dashed var(--border);margin-top:10px;padding-top:10px">
                <div style="font-size:.68rem;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:#5b21b6;margin-bottom:6px;display:flex;align-items:center;gap:5px">
                  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/></svg>
                  Penilaian &amp; Rekomendasi
                </div>
                <div class="audit-pemeriksaan-btns">
                  ${_pm('grading') ? `<button class="audit-pem-btn audit-pem-btn--grading" ${pemBtnAttr}
                          onclick="${pemLocked ? '' : `window._openGradingModal(${t.id})`}">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                      <polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/>
                    </svg>
                    <span>Grading</span>
                    ${gradingCount > 0 ? `<span class="audit-pem-count" style="background:#7c3aed">${gradingCount}</span>` : ''}
                    ${pemLocked ? '<span style="font-size:.68rem;margin-left:4px">🔒</span>' : ''}
                  </button>` : ''}
                  ${(isMyAuditorTask && _pm('rekomendasi')) ? `
                  <button class="audit-pem-btn" style="background:#ede9fe;color:#5b21b6;border:1px solid #c4b5fd" ${pemBtnAttr}
                          onclick="${pemLocked ? '' : `window._openRekomendasiModal('${t.planId}')`}">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                      <path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/>
                      <line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/>
                    </svg>
                    <span>${taskRekomD?.status==='pending_afd'?'Keputusan AFD':'Rekomendasi'}</span>
                    ${taskRekomD ? '<span class="audit-pem-count" style="background:#7c3aed">●</span>' : ''}
                    ${pemLocked ? '<span style="font-size:.68rem;margin-left:4px">🔒</span>' : ''}
                  </button>` : ''}
                  ${(isMyAuditorTask && _pm('bu_perf')) ? `
                  <button class="audit-pem-btn" style="background:#f5f3ff;color:#5b21b6;border:1px solid #ddd8fe" ${pemBtnAttr}
                          onclick="${pemLocked ? '' : `window._openBuPerfForm(${t.id})`}">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                      <line x1="18" y1="20" x2="18" y2="10"/><line x1="12" y1="20" x2="12" y2="4"/><line x1="6" y1="20" x2="6" y2="14"/>
                    </svg>
                    <span>BU Performance</span>
                    ${getBuPerfForPlan(t.planId) ? '<span class="audit-pem-count" style="background:#7c3aed">●</span>' : ''}
                    ${pemLocked ? '<span style="font-size:.68rem;margin-left:4px">🔒</span>' : ''}
                  </button>` : ''}
                </div>
              </div>

              ${simpanSection}
            </div>`;
          actionBtn = '';
        }

        // ── Rekomendasi panel untuk task SELESAI (auditor) ──
        let rekSelesaiPanel = '';
        if (isMyAuditorTask && t.status === 'selesai') {
          const rekD2 = loadRekomendasi().find(r => String(r.planId) === String(t.planId));
          const rekSt = rekD2?.status || null;
          const rekDone = rekSt === 'selesai';
          const rekAfd  = rekSt === 'pending_afd';
          const rekCanAct = rekD2 ? _canActRekom(rekD2) : true;
          const rekBtnLabel = rekDone ? 'Lihat History Rekomendasi'
                            : rekAfd  ? 'Lihat Rekomendasi (Menunggu AFD)'
                            : rekCanAct ? 'Isi Rekomendasi Auditor'
                            : 'Lihat Rekomendasi';
          const rekBtnBg  = rekCanAct && !rekDone ? '#6366f1' : rekDone ? '#dcfce7' : '#ede9fe';
          const rekBtnClr = rekCanAct && !rekDone ? '#fff'    : rekDone ? '#166534' : '#5b21b6';
          const rekBtnBdr = rekCanAct && !rekDone ? 'none'    : '1px solid #c4b5fd';

          const rekStatusMap2 = {
            pending_auditor: { label:'Menunggu Auditor',       bg:'#fef3c7', clr:'#92400e' },
            pending_unit:    { label:'Menunggu Unit Usaha',    bg:'#dbeafe', clr:'#1e40af' },
            pending_rss:     { label:'Menunggu RSS',           bg:'#e0f2fe', clr:'#075985' },
            pending_manajer: { label:'Menunggu Manajer Audit', bg:'#ede9fe', clr:'#5b21b6' },
            pending_afd:     { label:'Menunggu Keputusan AFD', bg:'#fdf4ff', clr:'#701a75' },
            selesai:         { label:'✓ Rekomendasi Selesai',  bg:'#dcfce7', clr:'#166534' },
          };
          const rstInfo = rekD2 ? (rekStatusMap2[rekD2.status] || null) : null;
          const rstBadge = rstInfo
            ? `<span style="font-size:.72rem;padding:2px 9px;border-radius:9px;font-weight:700;background:${rstInfo.bg};color:${rstInfo.clr}">${rstInfo.label}</span>`
            : `<span style="font-size:.72rem;padding:2px 9px;border-radius:9px;background:#f1f5f9;color:#94a3b8">Belum Dimulai</span>`;

          rekSelesaiPanel = `
            <div class="audit-pemeriksaan-bar" style="margin-top:10px;border:1.5px solid #c4b5fd;background:#faf5ff;border-radius:8px">
              <div class="audit-pemeriksaan-title" style="color:#5b21b6">
                &#128203; REKOMENDASI AUDIT
                <span style="margin-left:8px">${rstBadge}</span>
              </div>
              <div class="audit-pemeriksaan-btns">
                <button class="audit-pem-btn"
                        style="background:${rekBtnBg};color:${rekBtnClr};border:${rekBtnBdr}"
                        onclick="window._openRekomendasiModal('${t.planId}')">
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                    <path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/>
                    <polyline points="14 2 14 8 20 8"/>
                    <line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/>
                  </svg>
                  <span>${rekBtnLabel}</span>
                  ${rekDone ? '<span class="audit-pem-count" style="background:#22c55e">&#10003;</span>' : ''}
                  ${!rekDone && rekD2 ? '<span class="audit-pem-count" style="background:#7c3aed">&#9679;</span>' : ''}
                </button>
                ${rekDone ? (() => {
                  const skRec = loadSk().find(s => String(s.planId) === String(t.planId));
                  const skSts = skRec?.status;
                  const skLbl = !skRec ? 'Upload SK'
                    : skSts === 'selesai' ? 'Lihat SK &#10003;'
                    : skSts === 'pending_afd' ? 'SK — Menunggu AFD'
                    : 'SK — Menunggu Manajer';
                  const skBg  = !skRec ? '#ecfdf5' : skSts === 'selesai' ? '#dcfce7' : '#fef3c7';
                  const skClr = !skRec ? '#0f766e' : skSts === 'selesai' ? '#166534' : '#92400e';
                  return `<button class="audit-pem-btn" style="background:${skBg};color:${skClr};border:1px solid ${skSts==='selesai'?'#86efac':'#99f6e4'}"
                          onclick="window._openRekomendasiModal('${t.planId}')">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                      <rect x="3" y="3" width="18" height="18" rx="2"/><line x1="9" y1="3" x2="9" y2="21"/>
                      <path d="M13 8h4M13 12h4M13 16h4"/>
                    </svg>
                    <span>${skLbl}</span>
                  </button>`;
                })() : ''}
              </div>
            </div>`;
        }

        if (can('view-all-plans') && !actionBtn && !pemeriksaanBar) {
          actionBtn = `<span style="font-size:.8rem;color:var(--text-secondary)">${taskStatusBadge(t.status)}</span>`;
        }

        html += `<div class="audit-member-row" style="border-bottom:1px solid var(--border)">
          <div style="flex:1">
            ${renderWorkflowBar(t.status)}
            <div style="display:flex;align-items:center;gap:8px;margin-top:4px">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>
              <span style="font-size:.85rem">${assignee}</span>
              ${t.isKepala ? '<span style="font-size:.72rem;color:var(--primary);font-weight:600">Kepala Tim</span>' : ''}
              ${taskStatusBadge(t.status)}
            </div>
            ${t.tglMulai ? `<div style="font-size:.78rem;color:var(--text-secondary);margin-top:2px">Tgl Mulai: ${t.tglMulai} &nbsp; Selesai: ${t.tglSelesai || '—'}</div>` : ''}
            ${pemeriksaanBar}
            ${rekSelesaiPanel}
          </div>
          ${actionBtn ? `<div style="flex-shrink:0">${actionBtn}</div>` : ''}
        </div>`;
      });

      html += `</div>`;
    });

    container.innerHTML = html;
  }

  // ── Pemeriksaan Kas Audit (form lengkap) ─────────
  let _kasAuditTaskId  = null;
  let _kasAuditEditId  = null; // ID record yang sedang diedit (null = mode baru)
  const KA_DENOMS = [100000, 50000, 20000, 10000, 5000, 2000, 1000, 500, 200, 100];

  // Helper — ambil elemen modal kas audit berdasarkan id (dengan prefix ka_)
  function _kaEl(id) { return document.getElementById('ka_' + id); }

  // Format angka dengan titik ribuan: 10000000 → "10.000.000"
  function _kaFmtVal(n) {
    const num = parseInt(String(n || 0).replace(/[^\d]/g, '')) || 0;
    return num.toLocaleString('id-ID');
  }

  // Baca nilai bersih dari elemen (hapus titik): "10.000.000" → 10000000
  function _kaNum(el) {
    return parseInt((el?.value || '').replace(/[^\d]/g, '')) || 0;
  }

  // Pasang auto-format ribuan ke elemen input
  function _kaAttachMoney(el, onChangeCb) {
    if (!el) return;
    // Format saat focus-out
    el.addEventListener('blur', () => {
      const n = _kaNum(el);
      el.value = _kaFmtVal(n);
      if (onChangeCb) onChangeCb();
    });
    // Saat focus, tampilkan angka bersih (mudah diedit)
    el.addEventListener('focus', () => {
      const n = _kaNum(el);
      el.value = n > 0 ? String(n) : '';
      el.select();
    });
    // Saat input, izinkan hanya digit
    el.addEventListener('input', () => {
      const pos   = el.selectionStart;
      const clean = el.value.replace(/[^\d]/g, '');
      el.value    = clean;
      if (onChangeCb) onChangeCb();
    });
  }

  function _kaCreateTransaksiRow(tbody, onRecalc) {
    const today = new Date().toISOString().slice(0, 10);
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td><input type="date" class="pem-input-sm" value="${today}" /></td>
      <td><input type="text" class="pem-input-sm" placeholder="Keterangan..." /></td>
      <td><input type="text" inputmode="numeric" class="pem-input-sm ka-row-money" value="0" /></td>
      <td><button class="btn-del-row" title="Hapus">&#10005;</button></td>`;
    tr.querySelector('.btn-del-row').addEventListener('click', () => { tr.remove(); onRecalc(); });
    // Pasang auto-format ribuan pada kolom jumlah
    _kaAttachMoney(tr.querySelector('.ka-row-money'), onRecalc);
    tbody.appendChild(tr);
    onRecalc();
  }

  function _kaCreateBlankoRow(container) {
    const div = document.createElement('div');
    div.className = 'blanko-row';
    div.innerHTML = `<span class="blanko-jenis-label">Jenis</span>
      <input type="text" class="kas-input blanko-input" placeholder="Nomor range blanko..." />
      <button class="btn-del-row" title="Hapus">&#10005;</button>`;
    div.querySelector('.btn-del-row').addEventListener('click', () => div.remove());
    container.appendChild(div);
  }

  function _kaBuildPecahanTable() {
    const tbody = _kaEl('pecahanBody');
    if (!tbody || tbody.children.length > 0) return; // sudah dibangun
    KA_DENOMS.forEach(d => {
      const tr = document.createElement('tr');
      tr.dataset.denom = d;
      tr.innerHTML = `
        <td class="pecahan-denom">${d.toLocaleString('id-ID')}</td>
        <td><input type="number" class="pem-num-sm pec-kb" value="0" min="0" /></td>
        <td class="pec-kb-total">Rp 0</td>
        <td><input type="number" class="pem-num-sm pec-kk" value="0" min="0" /></td>
        <td class="pec-kk-total">Rp 0</td>`;
      tbody.appendChild(tr);
    });
    tbody.querySelectorAll('.pec-kb, .pec-kk').forEach(inp =>
      inp.addEventListener('input', window._kaRecalcAll));
  }

  function _kaSumRows(tbody) {
    return Array.from(tbody.querySelectorAll('.ka-row-money'))
      .reduce((s, inp) => s + _kaNum(inp), 0);
  }

  function _kaSetSelisih(elId, selisih) {
    const el = _kaEl(elId);
    if (!el) return;
    el.textContent = formatRupiah(Math.abs(selisih)) + (selisih === 0 ? ' ✓' : ' ✗');
    el.className   = selisih === 0 ? 'selisih-ok' : 'selisih-err';
  }

  window._kaRecalcAll = function () {
    // Pecahan
    let kbQty = 0, kbAmt = 0, kkQty = 0, kkAmt = 0;
    const pecBody = _kaEl('pecahanBody');
    if (pecBody) {
      pecBody.querySelectorAll('tr').forEach(tr => {
        const d   = parseInt(tr.dataset.denom);
        const kbQ = parseInt(tr.querySelector('.pec-kb')?.value) || 0;
        const kkQ = parseInt(tr.querySelector('.pec-kk')?.value) || 0;
        const kbTot = tr.querySelector('.pec-kb-total');
        const kkTot = tr.querySelector('.pec-kk-total');
        if (kbTot) kbTot.textContent = formatRupiah(d * kbQ);
        if (kkTot) kkTot.textContent = formatRupiah(d * kkQ);
        kbQty += kbQ; kbAmt += d * kbQ;
        kkQty += kkQ; kkAmt += d * kkQ;
      });
    }
    const kbQEl = _kaEl('pec-kb-qty-total'), kbTEl = _kaEl('pec-kb-total');
    const kkQEl = _kaEl('pec-kk-qty-total'), kkTEl = _kaEl('pec-kk-total');
    if (kbQEl) kbQEl.textContent = kbQty.toLocaleString('id-ID');
    if (kbTEl) kbTEl.textContent = formatRupiah(kbAmt);
    if (kkQEl) kkQEl.textContent = kkQty.toLocaleString('id-ID');
    if (kkTEl) kkTEl.textContent = formatRupiah(kkAmt);

    // Kas Besar
    const saldoAwal        = _kaNum(_kaEl('kasBesarSaldoAwal'));
    const penBody          = _kaEl('penerimaanBody');
    const pelBody          = _kaEl('pengeluaranBody');
    const totalPenerimaan  = penBody ? _kaSumRows(penBody) : 0;
    const totalPengeluaran = pelBody ? _kaSumRows(pelBody) : 0;
    const saldoBukuKB      = saldoAwal + totalPenerimaan - totalPengeluaran;

    const sa = _kaEl('disp-kb-saldo-awal'),
          pe = _kaEl('disp-kb-penerimaan'),
          pl = _kaEl('disp-kb-pengeluaran'),
          sb = _kaEl('disp-kb-saldo-buku'),
          sf = _kaEl('disp-kb-saldo-fisik');
    if (sa) sa.textContent = formatRupiah(saldoAwal);
    if (pe) pe.textContent = formatRupiah(totalPenerimaan);
    if (pl) pl.textContent = formatRupiah(totalPengeluaran);
    if (sb) sb.textContent = formatRupiah(saldoBukuKB);
    if (sf) sf.textContent = formatRupiah(kbAmt);
    _kaSetSelisih('disp-kb-selisih', saldoBukuKB - kbAmt);

    // Kas Kecil
    const cadangan  = _kaNum(_kaEl('kasKecilCadangan'));
    const bonBody   = _kaEl('bonGantungBody');
    const totalBon  = bonBody ? _kaSumRows(bonBody) : 0;
    const saldoBukuKK = cadangan - totalBon;

    const cd = _kaEl('disp-kk-cadangan'),
          bn = _kaEl('disp-kk-bon'),
          sk = _kaEl('disp-kk-saldo-buku'),
          fk = _kaEl('disp-kk-saldo-fisik');
    if (cd) cd.textContent = formatRupiah(cadangan);
    if (bn) bn.textContent = formatRupiah(totalBon);
    if (sk) sk.textContent = formatRupiah(saldoBukuKK);
    if (fk) fk.textContent = formatRupiah(kkAmt);
    _kaSetSelisih('disp-kk-selisih', saldoBukuKK - kkAmt);
  };

  // Hitung H-1 dari tanggal pemeriksaan
  window._kaOnTglChange = function () {
    const tglVal = _kaEl('tglPemeriksaan')?.value;
    if (!tglVal) return;
    const d = new Date(tglVal);
    d.setDate(d.getDate() - 1);
    const h1 = d.toISOString().slice(0, 10);
    const h1El = _kaEl('kasBesarTanggalAwal');
    if (h1El) h1El.value = h1;
  };

  window._kaResetForm = function () {
    const today = new Date().toISOString().slice(0, 10);
    // Tanggal pemeriksaan = hari ini
    const tglEl = _kaEl('tglPemeriksaan');
    if (tglEl) { tglEl.value = today; }
    // H-1 otomatis = tgl pemeriksaan - 1 hari
    const d = new Date(today);
    d.setDate(d.getDate() - 1);
    const h1 = d.toISOString().slice(0, 10);
    const taEl = _kaEl('kasBesarTanggalAwal');
    if (taEl) taEl.value = h1;
    const namaEl = _kaEl('namaAuditee');
    if (namaEl) namaEl.value = '';
    const saEl = _kaEl('kasBesarSaldoAwal');
    if (saEl) saEl.value = '0';
    const cdEl = _kaEl('kasKecilCadangan');
    if (cdEl) cdEl.value = '0';
    // Pasang listener ribuan ke static money inputs (idempotent via _ka_moneyAttached flag)
    [_kaEl('kasBesarSaldoAwal'), _kaEl('kasKecilCadangan')].forEach(el => {
      if (el && !el._kaMoneyAttached) {
        _kaAttachMoney(el, window._kaRecalcAll);
        el._kaMoneyAttached = true;
      }
    });
    const kbKetEl = _kaEl('kasBesarKet');
    if (kbKetEl) kbKetEl.value = '';
    const kkKetEl = _kaEl('kasKecilKet');
    if (kkKetEl) kkKetEl.value = '';

    ['penerimaanBody','pengeluaranBody','bonGantungBody'].forEach(id => {
      const tb = _kaEl(id);
      if (tb) { tb.innerHTML = ''; _kaCreateTransaksiRow(tb, window._kaRecalcAll); }
    });
    ['blankoH1Body','blankoH2Body'].forEach(id => {
      const c = _kaEl(id);
      if (c) { c.innerHTML = ''; _kaCreateBlankoRow(c); }
    });
    // Reset pecahan
    const pecBody = _kaEl('pecahanBody');
    if (pecBody) {
      pecBody.querySelectorAll('.pec-kb, .pec-kk').forEach(i => { i.value = '0'; });
    }
    window._kaRecalcAll();
  };

  window._openKasAuditModal = function (taskId) {
    tasks = loadTasks();
    const t = tasks.find(x => String(x.id) === String(taskId));
    if (!t) return;
    _kasAuditTaskId = taskId;

    // Plan info
    document.getElementById('kasAuditPlanInfo').innerHTML = `
      <div class="unit-info-grid">
        <div class="unit-info-item"><label>No SPT</label><span style="font-weight:700">${t.noSPT}</span></div>
        <div class="unit-info-item"><label>Cabang</label><span>${t.cabangPlan}${t.cabangArea ? ' ' + areaBadge(t.cabangArea) : ''}</span></div>
        <div class="unit-info-item"><label>Tanggal Plan</label><span>${t.tanggalPlan}</span></div>
        <div class="unit-info-item"><label>Status</label><span>${taskStatusBadge(t.status)}</span></div>
      </div>`;

    // Riwayat
    const existing = loadKasAudit().filter(k => String(k.planId) === String(t.planId));
    const hist = document.getElementById('kasAuditHistory');
    if (existing.length) {
      hist.innerHTML = `<div class="status-log-title" style="margin-bottom:8px">Riwayat Pemeriksaan Kas (${existing.length})</div>` +
        existing.map(k => {
          const sbKB = Number(k.saldoBukuKB || k.saldoBuku || 0);
          const sfKB = Number(k.saldoFisikKB || k.saldoFisik || 0);
          const slKB = Number(k.selisihKB || k.selisih || (sfKB - sbKB));
          const sbKK = Number(k.saldoBukuKK || 0);
          const sfKK = Number(k.saldoFisikKK || 0);
          const slKK = Number(k.selisihKK || (sfKK - sbKK));
          const slClr = (v) => v === 0 ? 'var(--success)' : 'var(--danger)';
          const slLbl = (v) => v === 0 ? '✓ Sesuai' : v > 0 ? `+${v.toLocaleString('id-ID')} (Lebih)` : `${v.toLocaleString('id-ID')} (Kurang)`;
          return `
          <div style="background:#f9fafb;border:1px solid var(--border);border-radius:8px;padding:10px 14px;margin-bottom:8px;font-size:.82rem">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
              <div>
                <strong>${k.namaAuditee || k.cabang || '—'}</strong>
                <span style="color:var(--text-secondary);margin-left:8px">${k.tglPemeriksaan || k.tanggal || ''}</span>
                ${k.namaAuditor ? `<span style="background:#dbeafe;color:#1e40af;font-size:.72rem;padding:1px 7px;border-radius:10px;margin-left:6px">Auditor: ${k.namaAuditor}</span>` : ''}
                <span style="color:var(--text-secondary);margin-left:6px;font-size:.75rem">Disimpan: ${k.savedBy || '—'}</span>
              </div>
              <div style="display:flex;gap:6px">
                <button onclick="window._editKasAudit('${k.id}')" style="background:#dbeafe;border:none;border-radius:4px;padding:3px 10px;cursor:pointer;font-size:.75rem;color:#1e40af;font-weight:600">✎ Edit</button>
                <button onclick="window._deleteKasAudit('${k.id}')" style="background:#fee2e2;border:none;border-radius:4px;padding:3px 10px;cursor:pointer;font-size:.75rem;color:#dc2626">Hapus</button>
              </div>
            </div>
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px">
              <div style="background:#fff;border-radius:6px;padding:6px 10px">
                <div style="font-weight:700;color:var(--text-secondary);font-size:.72rem;text-transform:uppercase;margin-bottom:2px">Kas Besar</div>
                <div>Buku: <strong>Rp ${sbKB.toLocaleString('id-ID')}</strong> &nbsp;| Fisik: <strong>Rp ${sfKB.toLocaleString('id-ID')}</strong></div>
                <div>Selisih: <span style="color:${slClr(slKB)};font-weight:700">Rp ${slLbl(slKB)}</span></div>
              </div>
              <div style="background:#fff;border-radius:6px;padding:6px 10px">
                <div style="font-weight:700;color:var(--text-secondary);font-size:.72rem;text-transform:uppercase;margin-bottom:2px">Kas Kecil</div>
                <div>Buku: <strong>Rp ${sbKK.toLocaleString('id-ID')}</strong> &nbsp;| Fisik: <strong>Rp ${sfKK.toLocaleString('id-ID')}</strong></div>
                <div>Selisih: <span style="color:${slClr(slKK)};font-weight:700">Rp ${slLbl(slKK)}</span></div>
              </div>
            </div>
          </div>`;
        }).join('');
    } else {
      hist.innerHTML = `<p style="font-size:.82rem;color:var(--text-secondary);text-align:center;padding:8px 0;margin:0">Belum ada pemeriksaan kas untuk plan ini.</p>`;
    }

    // ── Simpan ke Report Audit bar ──────────────────────────────────────
    const kasAuditSimpanBar = document.getElementById('kasAuditSimpanBar');
    if (kasAuditSimpanBar) {
      if (existing.length > 0) {
        const _kasSavedPem  = loadSavedPem();
        const _kasIsSaved   = _kasSavedPem.some(s => String(s.planId) === String(t.planId) && s.type === 'kas');
        const _kasSavedAt   = _kasIsSaved ? _kasSavedPem.find(s => String(s.planId) === String(t.planId) && s.type === 'kas').savedAt : null;
        const _kasSavedDate = _kasSavedAt ? new Date(_kasSavedAt).toLocaleString('id-ID', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '';
        kasAuditSimpanBar.innerHTML = `
          <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:10px;margin-bottom:4px;padding:12px 16px;
               background:${_kasIsSaved ? '#dcfce7' : '#f0f9ff'};border:1.5px solid ${_kasIsSaved ? '#86efac' : '#bae6fd'};
               border-radius:8px">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="${_kasIsSaved?'#166534':'#0369a1'}" stroke-width="2">
              <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/>
              <polyline points="17 21 17 13 7 13 7 21"/><polyline points="7 3 7 8 15 8"/>
            </svg>
            <div style="flex:1">
              <div style="font-size:.83rem;font-weight:700;color:${_kasIsSaved?'#166534':'#0369a1'}">
                ${_kasIsSaved ? '✓ Pemeriksaan Kas sudah disimpan ke Report Audit' : 'Simpan hasil ini ke Report Audit'}
              </div>
              <div style="font-size:.75rem;color:${_kasIsSaved?'#4ade80':'#64748b'};margin-top:2px">
                ${_kasIsSaved
                  ? 'Tersimpan: ' + _kasSavedDate + ' &nbsp;·&nbsp; ' + existing.length + ' data pemeriksaan'
                  : existing.length + ' data pemeriksaan tersedia &nbsp;·&nbsp; Klik untuk tampil di Report Audit'}
              </div>
            </div>
            <button onclick="window._simpanKasKeReport('${t.planId}')"
                    style="background:${_kasIsSaved?'#16a34a':'#0369a1'};color:#fff;border:none;border-radius:7px;
                           padding:8px 18px;font-size:.83rem;font-weight:700;cursor:pointer;
                           display:flex;align-items:center;gap:6px;white-space:nowrap">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z"/>
                <polyline points="17 21 17 13 7 13 7 21"/><polyline points="7 3 7 8 15 8"/>
              </svg>
              ${_kasIsSaved ? 'Perbarui ke Report Audit' : 'Simpan ke Report Audit'}
            </button>
          </div>`;
      } else {
        kasAuditSimpanBar.innerHTML = '';
      }
    }

    // Reset mode edit saat modal dibuka (kecuali sedang dalam proses edit)
    if (!_kasAuditEditId) {
      const titleEl = document.getElementById('kasFormTitle');
      const batalBtn = document.getElementById('kasBatalEditBtn');
      if (titleEl) { titleEl.textContent = 'Form Pemeriksaan Kas Baru'; titleEl.style.color = ''; }
      if (batalBtn) batalBtn.style.display = 'none';
    }

    // Bangun tabel pecahan (sekali saja)
    _kaBuildPecahanTable();
    // Reset form — isi tanggal hari ini dan H-1 otomatis
    if (!_kasAuditEditId) window._kaResetForm();

    // ── Auto-fill Nama Auditor dari timAudit plan ────────────────────────
    plans = loadPlans();
    const plan = plans.find(p => String(p.id) === String(t.planId));
    const timUsernames = (!t.isMandiri && plan) ? (plan.timAudit || []) : [];
    const allUsers     = getAllUsers();
    const timAuditors  = timUsernames
      .map(u => allUsers.find(x => x.username === u))
      .filter(Boolean);

    const auditorSel   = _kaEl('namaAuditorSelect');
    const auditorInput = _kaEl('namaAuditorInput');

    if (t.isMandiri) {
      // Mandiri: auditor = user yang login
      if (auditorSel)   { auditorSel.style.display = 'none'; }
      if (auditorInput) { auditorInput.style.display = ''; auditorInput.value = session.displayName || session.username; }
    } else if (timAuditors.length === 0) {
      // Tidak ada tim auditor — kosong
      if (auditorSel)   { auditorSel.style.display = 'none'; }
      if (auditorInput) { auditorInput.style.display = ''; auditorInput.value = session.displayName || ''; }
    } else if (timAuditors.length === 1) {
      // Satu auditor — tampil readonly
      if (auditorSel)   { auditorSel.style.display = 'none'; }
      if (auditorInput) { auditorInput.style.display = ''; auditorInput.value = timAuditors[0].displayName; }
    } else {
      // Lebih dari 1 auditor — tampil dropdown
      if (auditorInput) auditorInput.style.display = 'none';
      if (auditorSel) {
        auditorSel.style.display = '';
        auditorSel.innerHTML = '<option value="">— Pilih Auditor —</option>' +
          timAuditors.map(u => `<option value="${u.displayName}">${u.displayName}</option>`).join('');
        // Auto-pilih jika current user ada di tim
        const myEntry = timAuditors.find(u => u.username === session.username);
        if (myEntry) auditorSel.value = myEntry.displayName;
      }
    }

    // ── Isi Info Umum (header dokumen) ──────────────────────────────────
    const infoUmumEl = _kaEl('infoUmum');
    if (infoUmumEl) {
      const org    = (() => { try { return JSON.parse(localStorage.getItem('akta_org')) || {}; } catch { return {}; } })();
      const orgName = org.namaOrg || org.nama || 'AKTA IAT';
      let infoItems;
      if (t.isMandiri) {
        // Audit Mandiri: nomor = noAM, tanggal = tglMulai, kepala = user login
        infoItems = [
          { l: 'Nama Organisasi',  v: orgName },
          { l: 'Cabang / Unit',    v: t.unitUsaha || t.cabangPlan || '—' },
          { l: 'No. Plan',         v: '<strong>' + (t.noAM || '—') + '</strong>' },
          { l: 'Jenis Audit',      v: 'Audit Mandiri — ' + (t.jenisLabel || t.jenisMandiri || '—') },
          { l: 'Tanggal Pemeriksaan', v: t.tglMulai || '—' },
          { l: 'Pelaksana',        v: session.displayName || session.username },
        ];
      } else {
        infoItems = [
          { l: 'Nama Organisasi',  v: orgName },
          { l: 'Cabang / Unit',    v: (t.cabangPlan || '—') + (t.cabangArea ? ' [' + t.cabangArea + ']' : '') },
          { l: 'No. Plan / SPT',   v: '<strong>' + (t.noSPT || '—') + '</strong>' },
          { l: 'Jenis Audit',      v: t.jenisAudit || '—' },
          { l: 'Tanggal Plan',     v: t.tanggalPlan || '—' },
          { l: 'Kepala Tim',       v: plan ? getUserDisplay(plan.kepalaTim) : '—' },
        ];
      }
      infoUmumEl.innerHTML = infoItems.map(item =>
        '<div style="display:flex;flex-direction:column;gap:1px">' +
          '<span style="font-size:.68rem;text-transform:uppercase;letter-spacing:.04em;color:#9ca3af">' + item.l + '</span>' +
          '<span style="font-weight:600;color:#374151">' + item.v + '</span>' +
        '</div>'
      ).join('');
    }

    // ── Auto-fill Auditee: cari pemegang kas/partkeeper, fallback kasir ──
    const normUU = (s) => (s || '').trim().toLowerCase();
    const cabang  = (t.cabangPlan || '').trim();

    // Urutan pencarian auditee: kasir → so/csc/whs untuk unit yg sama → kosong
    const kasirUser   = allUsers.find(u => u.role === 'kasir' && normUU(u.unitUsaha) === normUU(cabang));
    const branchUser  = !kasirUser
      ? allUsers.find(u => ['so','csc','whs'].includes(u.role) && normUU(u.unitUsaha) === normUU(cabang))
      : null;
    const bestAuditee = kasirUser || branchUser;

    const namaEl = _kaEl('namaAuditee');
    if (namaEl) {
      namaEl.value = bestAuditee ? bestAuditee.displayName : '';
      namaEl.removeAttribute('readonly'); // pastikan bisa diisi manual
    }

    // Isi jabatan otomatis
    const jabatanEl = _kaEl('jabatanAuditee');
    if (jabatanEl && bestAuditee) {
      jabatanEl.value = ROLE_LABELS[bestAuditee.role] || bestAuditee.role || '';
    }

    // Hint untuk auditee
    const hintEl = _kaEl('auditeeHint');
    if (hintEl) {
      if (kasirUser) {
        hintEl.innerHTML = '<span style="color:#166534">&#10003; Terisi dari role Kasir</span> — bisa diubah manual';
      } else if (branchUser) {
        hintEl.innerHTML = '<span style="color:#d97706">&#9432; Tidak ditemukan Kasir</span> — terisi dari role ' + (ROLE_LABELS[branchUser.role] || branchUser.role) + ' (bisa diubah)';
      } else {
        hintEl.innerHTML = '<span style="color:#94a3b8">Tidak ada user Kasir untuk unit ini</span> — isi manual';
      }
    }

    // Wire up tombol tambah
    const btnPen = _kaEl('addPenerimaan');
    const btnPel = _kaEl('addPengeluaran');
    const btnBon = _kaEl('addBonGantung');
    const btnH1  = _kaEl('addBlankoH1');
    const btnH2  = _kaEl('addBlankoH2');
    if (btnPen) btnPen.onclick = () => _kaCreateTransaksiRow(_kaEl('penerimaanBody'), window._kaRecalcAll);
    if (btnPel) btnPel.onclick = () => _kaCreateTransaksiRow(_kaEl('pengeluaranBody'), window._kaRecalcAll);
    if (btnBon) btnBon.onclick = () => _kaCreateTransaksiRow(_kaEl('bonGantungBody'), window._kaRecalcAll);
    if (btnH1)  btnH1.onclick  = () => _kaCreateBlankoRow(_kaEl('blankoH1Body'));
    if (btnH2)  btnH2.onclick  = () => _kaCreateBlankoRow(_kaEl('blankoH2Body'));

    document.getElementById('kasAuditModal').classList.remove('hidden');
    document.getElementById('kasAuditModal').style.display = 'flex';
  };

  window._saveKasAudit = function () {
    if (!_kasAuditTaskId) return;
    tasks = loadTasks();
    const t = tasks.find(x => String(x.id) === String(_kasAuditTaskId));
    if (!t) return;

    const namaAuditee     = _kaEl('namaAuditee')?.value?.trim() || '';
    const jabatanAuditee  = _kaEl('jabatanAuditee')?.value?.trim() || '';
    const tglPemeriksaan  = _kaEl('tglPemeriksaan')?.value || '';
    // Nama auditor: ambil dari dropdown (jika >1) atau input (jika 1)
    const audSel = _kaEl('namaAuditorSelect');
    const audInp = _kaEl('namaAuditorInput');
    const namaAuditor = (audSel && audSel.style.display !== 'none')
      ? (audSel.value || session.displayName)
      : (audInp?.value?.trim() || session.displayName);
    if (!tglPemeriksaan) { showToast('Isi tanggal pemeriksaan.', 'error'); return; }

    // Kumpulkan penerimaan rows
    const penRows = Array.from(_kaEl('penerimaanBody')?.rows || []).map(tr => ({
      tgl:    tr.cells[0]?.querySelector('input')?.value || '',
      ket:    tr.cells[1]?.querySelector('input')?.value || '',
      jumlah: _kaNum(tr.cells[2]?.querySelector('input')),
    }));
    // Kumpulkan pengeluaran rows
    const pelRows = Array.from(_kaEl('pengeluaranBody')?.rows || []).map(tr => ({
      tgl:    tr.cells[0]?.querySelector('input')?.value || '',
      ket:    tr.cells[1]?.querySelector('input')?.value || '',
      jumlah: _kaNum(tr.cells[2]?.querySelector('input')),
    }));
    // Bon gantung rows
    const bonRows = Array.from(_kaEl('bonGantungBody')?.rows || []).map(tr => ({
      tgl:    tr.cells[0]?.querySelector('input')?.value || '',
      ket:    tr.cells[1]?.querySelector('input')?.value || '',
      jumlah: _kaNum(tr.cells[2]?.querySelector('input')),
    }));

    // Pecahan
    const pecKB = {}, pecKK = {};
    (_kaEl('pecahanBody')?.querySelectorAll('tr') || []).forEach(tr => {
      const d = parseInt(tr.dataset.denom);
      pecKB[d] = parseInt(tr.querySelector('.pec-kb')?.value) || 0;
      pecKK[d] = parseInt(tr.querySelector('.pec-kk')?.value) || 0;
    });
    const fisikKB = KA_DENOMS.reduce((s, d) => s + d * (pecKB[d] || 0), 0);
    const fisikKK = KA_DENOMS.reduce((s, d) => s + d * (pecKK[d] || 0), 0);

    // Blanko
    const blankoH1 = Array.from(_kaEl('blankoH1Body')?.querySelectorAll('.blanko-input') || []).map(i => i.value.trim()).filter(Boolean);
    const blankoH2 = Array.from(_kaEl('blankoH2Body')?.querySelectorAll('.blanko-input') || []).map(i => i.value.trim()).filter(Boolean);

    // Computed (gunakan _kaNum untuk baca nilai berformat titik)
    const saldoAwal      = _kaNum(_kaEl('kasBesarSaldoAwal'));
    const totalPen       = penRows.reduce((s, r) => s + r.jumlah, 0);
    const totalPel       = pelRows.reduce((s, r) => s + r.jumlah, 0);
    const saldoBukuKB    = saldoAwal + totalPen - totalPel;
    const cadangan       = _kaNum(_kaEl('kasKecilCadangan'));
    const totalBon       = bonRows.reduce((s, r) => s + r.jumlah, 0);
    const saldoBukuKK    = cadangan - totalBon;

    const newRec = {
      id:               _kasAuditEditId ? _kasAuditEditId : Date.now(),
      planId:           t.planId,
      noSPT:            t.noSPT,
      cabang:           t.cabangPlan,
      // Informasi
      namaAuditor,
      namaAuditee,
      jabatanAuditee,
      tglPemeriksaan,
      // Kas Besar
      kasBesarTanggalAwal: _kaEl('kasBesarTanggalAwal')?.value || '',
      kasBesarSaldoAwal:   saldoAwal,
      penerimaan:          penRows,
      pengeluaran:         pelRows,
      saldoBukuKB,
      saldoFisikKB:        fisikKB,
      selisihKB:           fisikKB - saldoBukuKB,
      kasBesarKet:         _kaEl('kasBesarKet')?.value?.trim() || '',
      // Kas Kecil
      kasKecilCadangan:    cadangan,
      bonGantung:          bonRows,
      saldoBukuKK,
      saldoFisikKK:        fisikKK,
      selisihKK:           fisikKK - saldoBukuKK,
      kasKecilKet:         _kaEl('kasKecilKet')?.value?.trim() || '',
      // Pecahan
      pecahanKB:  pecKB,
      pecahanKK:  pecKK,
      // Blanko
      blankoH1,
      blankoH2,
      // Backward compat
      tanggal:    tglPemeriksaan,
      saldoBuku:  saldoBukuKB,
      saldoFisik: fisikKB,
      selisih:    fisikKB - saldoBukuKB,
      keterangan: _kaEl('kasBesarKet')?.value?.trim() || '',
      savedBy:    session.username,
      savedAt:    new Date().toISOString(),
      editedAt:   _kasAuditEditId ? new Date().toISOString() : undefined,
    };

    let data = loadKasAudit();
    if (_kasAuditEditId) {
      // Mode edit: ganti record yang ada
      const idx = data.findIndex(k => String(k.id) === String(_kasAuditEditId));
      if (idx >= 0) data[idx] = newRec; else data.unshift(newRec);
      showToast('Pemeriksaan kas berhasil diperbarui.', 'success');
    } else {
      // Mode baru: tambah di awal
      data.unshift(newRec);
      showToast('Pemeriksaan kas berhasil disimpan.', 'success');
    }
    saveKasAudit(data);
    // Perbarui savedPem agar Report Audit langsung reflect data terbaru
    _markSavedPem(t.planId, 'kas');
    _kasAuditEditId = null;
    window._openKasAuditModal(_kasAuditTaskId);
  };

  window._deleteKasAudit = function (id) {
    if (!confirm('Hapus data pemeriksaan kas ini?')) return;
    const data = loadKasAudit().filter(k => String(k.id) !== String(id));
    saveKasAudit(data);
    _kasAuditEditId = null;
    window._openKasAuditModal(_kasAuditTaskId);
    showToast('Data dihapus.', 'info');
  };

  // ── Load record ke form untuk diedit ─────────────────────────
  window._editKasAudit = function (id) {
    const rec = loadKasAudit().find(k => String(k.id) === String(id));
    if (!rec) return;
    _kasAuditEditId = id;

    // Isi field dasar
    const set = (elId, val) => { const el = _kaEl(elId); if (el) el.value = val ?? ''; };
    set('tglPemeriksaan', rec.tglPemeriksaan || rec.tanggal || '');
    set('namaAuditee', rec.namaAuditee || '');
    set('jabatanAuditee', rec.jabatanAuditee || '');
    set('kasBesarTanggalAwal', rec.kasBesarTanggalAwal || '');
    set('kasBesarKet', rec.kasBesarKet || rec.keterangan || '');
    set('kasKecilKet', rec.kasKecilKet || '');

    // Saldo Awal Kas Besar
    const saEl = _kaEl('kasBesarSaldoAwal');
    if (saEl) { saEl.value = rec.kasBesarSaldoAwal ?? rec.saldoBuku ?? 0; window._kaRecalcAll?.(); }
    // Cadangan Kas Kecil
    const cdEl = _kaEl('kasKecilCadangan');
    if (cdEl) { cdEl.value = rec.kasKecilCadangan ?? 0; }

    // Penerimaan rows
    const penBody = _kaEl('penerimaanBody');
    if (penBody) {
      penBody.innerHTML = '';
      (rec.penerimaan || []).forEach(r => {
        _kaCreateTransaksiRow(penBody, window._kaRecalcAll);
        const rows = penBody.querySelectorAll('tr');
        const last = rows[rows.length - 1];
        if (last) {
          last.cells[0]?.querySelector('input')?.setAttribute('value', r.tgl || '');
          last.cells[1]?.querySelector('input')?.setAttribute('value', r.ket || '');
          const jEl = last.cells[2]?.querySelector('input');
          if (jEl) { jEl.value = r.jumlah || 0; }
        }
      });
      if (!rec.penerimaan?.length) _kaCreateTransaksiRow(penBody, window._kaRecalcAll);
    }

    // Pengeluaran rows
    const pelBody = _kaEl('pengeluaranBody');
    if (pelBody) {
      pelBody.innerHTML = '';
      (rec.pengeluaran || []).forEach(r => {
        _kaCreateTransaksiRow(pelBody, window._kaRecalcAll);
        const rows = pelBody.querySelectorAll('tr');
        const last = rows[rows.length - 1];
        if (last) {
          last.cells[0]?.querySelector('input')?.setAttribute('value', r.tgl || '');
          last.cells[1]?.querySelector('input')?.setAttribute('value', r.ket || '');
          const jEl = last.cells[2]?.querySelector('input');
          if (jEl) { jEl.value = r.jumlah || 0; }
        }
      });
      if (!rec.pengeluaran?.length) _kaCreateTransaksiRow(pelBody, window._kaRecalcAll);
    }

    // Bon gantung
    const bonBody = _kaEl('bonGantungBody');
    if (bonBody) {
      bonBody.innerHTML = '';
      (rec.bonGantung || []).forEach(r => {
        _kaCreateTransaksiRow(bonBody, window._kaRecalcAll);
        const rows = bonBody.querySelectorAll('tr');
        const last = rows[rows.length - 1];
        if (last) {
          last.cells[0]?.querySelector('input')?.setAttribute('value', r.tgl || '');
          last.cells[1]?.querySelector('input')?.setAttribute('value', r.ket || '');
          const jEl = last.cells[2]?.querySelector('input');
          if (jEl) { jEl.value = r.jumlah || 0; }
        }
      });
      if (!rec.bonGantung?.length) _kaCreateTransaksiRow(bonBody, window._kaRecalcAll);
    }

    // Pecahan
    const pecKB = rec.pecahanKB || {};
    const pecKK = rec.pecahanKK || {};
    (_kaEl('pecahanBody')?.querySelectorAll('tr') || []).forEach(tr => {
      const d = parseInt(tr.dataset.denom);
      const kbEl = tr.querySelector('.pec-kb');
      const kkEl = tr.querySelector('.pec-kk');
      if (kbEl) kbEl.value = pecKB[d] || 0;
      if (kkEl) kkEl.value = pecKK[d] || 0;
    });

    // Blanko
    const blankoH1 = _kaEl('blankoH1Body');
    const blankoH2 = _kaEl('blankoH2Body');
    if (blankoH1) {
      blankoH1.innerHTML = '';
      (rec.blankoH1 || []).forEach(v => { _kaCreateBlankoRow(blankoH1); blankoH1.querySelector('.blanko-input:last-of-type')?.setAttribute('value', v); });
      if (!rec.blankoH1?.length) _kaCreateBlankoRow(blankoH1);
    }
    if (blankoH2) {
      blankoH2.innerHTML = '';
      (rec.blankoH2 || []).forEach(v => { _kaCreateBlankoRow(blankoH2); blankoH2.querySelector('.blanko-input:last-of-type')?.setAttribute('value', v); });
      if (!rec.blankoH2?.length) _kaCreateBlankoRow(blankoH2);
    }

    window._kaRecalcAll?.();

    // Update UI form title ke mode edit
    const titleEl = document.getElementById('kasFormTitle');
    const batalBtn = document.getElementById('kasBatalEditBtn');
    if (titleEl) titleEl.textContent = '✎ Edit Pemeriksaan Kas';
    if (titleEl) titleEl.style.color = '#1e40af';
    if (batalBtn) batalBtn.style.display = '';

    // Scroll ke form
    const formEl = document.getElementById('ka_infoUmum');
    formEl?.closest('.pem-card')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    showToast('Data dimuat ke form. Ubah dan simpan kembali.', 'info');
  };

  // ── Batal mode edit, kembali ke mode baru ────────────────────
  window._kasBatalEdit = function () {
    _kasAuditEditId = null;
    const titleEl = document.getElementById('kasFormTitle');
    const batalBtn = document.getElementById('kasBatalEditBtn');
    if (titleEl) { titleEl.textContent = 'Form Pemeriksaan Kas Baru'; titleEl.style.color = ''; }
    if (batalBtn) batalBtn.style.display = 'none';
    window._kaResetForm();
  };

  // ── Simpan Pemeriksaan SMH ke Report Audit + navigasi ─────────────────
  window._simpanSmhKeReport = function (planId) {
    const smhData = loadSmhData(SMH_HASIL_KEY).filter(h => String(h.auditPlanId) === String(planId));
    if (!smhData.length) {
      showToast('Belum ada data pemeriksaan unit SMH. Lakukan scan unit terlebih dahulu.', 'error');
      return;
    }

    const saved = loadSavedPem();
    const idx   = saved.findIndex(s => String(s.planId) === String(planId) && s.type === 'smh');

    if (idx >= 0) {
      if (!confirm('Pemeriksaan Unit SMH sudah tersimpan sebelumnya.\nPerbarui data ke Report Audit?')) return;
      saved[idx].savedAt = new Date().toISOString();
    } else {
      saved.push({ planId: String(planId), type: 'smh', savedAt: new Date().toISOString() });
    }

    saveSavedPem(saved);
    showToast('Pemeriksaan Unit SMH (' + smhData.length + ' unit) berhasil disimpan ke Report Audit.', 'success');

    // Refresh bar di SMH section, lalu navigasi ke Report Audit
    renderSmhHasil();
    setTimeout(() => {
      document.querySelectorAll('.content-section').forEach(s => s.classList.add('hidden'));
      document.querySelectorAll('.nav-item').forEach(li => li.classList.remove('active'));
      const rptSection = document.getElementById('section-report-audit');
      const rptNav     = document.querySelector('.nav-item[data-section="report-audit"]');
      if (rptSection) { rptSection.classList.remove('hidden'); renderReportAuditSection(); }
      if (rptNav)     rptNav.classList.add('active');
    }, 600);
  };

  // ── Simpan Pemeriksaan Kas ke Report Audit + navigasi ──────────────────
  window._simpanKasKeReport = function (planId) {
    const kasData = loadKasAudit().filter(k => String(k.planId) === String(planId));
    if (!kasData.length) {
      showToast('Belum ada data pemeriksaan kas. Isi dan simpan form terlebih dahulu.', 'error');
      return;
    }

    const saved = loadSavedPem();
    const idx   = saved.findIndex(s => String(s.planId) === String(planId) && s.type === 'kas');

    if (idx >= 0) {
      if (!confirm('Pemeriksaan Kas sudah tersimpan sebelumnya.\nPerbarui data ke Report Audit?')) return;
      saved[idx].savedAt = new Date().toISOString();
    } else {
      saved.push({ planId: String(planId), type: 'kas', savedAt: new Date().toISOString() });
    }

    saveSavedPem(saved);
    showToast('Pemeriksaan Kas berhasil disimpan ke Report Audit.', 'success');

    // Tutup modal dan navigasi ke Report Audit
    window._closeKasAuditModal();
    document.querySelectorAll('.content-section').forEach(s => s.classList.add('hidden'));
    document.querySelectorAll('.nav-item').forEach(li => li.classList.remove('active'));
    const rptSection = document.getElementById('section-report-audit');
    const rptNav     = document.querySelector('.nav-item[data-section="report-audit"]');
    if (rptSection) { rptSection.classList.remove('hidden'); renderReportAuditSection(); }
    if (rptNav)     rptNav.classList.add('active');
  };

  window._closeKasAuditModal = function () {
    const m = document.getElementById('kasAuditModal');
    if (m) { m.classList.add('hidden'); m.style.display = ''; }
    _kasAuditTaskId = null;
    renderAuditSection();
  };

  /* ============================================================
     MODUL EXPORT PDF
     ============================================================ */
  window._exportPDF = function (type) {
    const org = (() => { try { return JSON.parse(localStorage.getItem('akta_org')) || {}; } catch { return {}; } })();
    const orgName = org.namaOrg || 'AKTA IAT';
    const now  = new Date().toLocaleDateString('id-ID', { day: '2-digit', month: 'long', year: 'numeric' });
    const fRp  = n => 'Rp ' + Number(n || 0).toLocaleString('id-ID');
    const fTgl = s => { if (!s) return '—'; try { return new Date(s).toLocaleDateString('id-ID', { day: '2-digit', month: 'long', year: 'numeric' }); } catch { return s; } };

    // Shared CSS
    const css = `
      *{box-sizing:border-box;margin:0;padding:0}
      body{font-family:'Segoe UI',Arial,sans-serif;font-size:11px;color:#1a1a1a;background:#fff;padding:20px}
      @page{size:A4 portrait;margin:15mm 12mm}
      @media print{body{padding:0}.no-print{display:none!important}}
      h1{font-size:16px;font-weight:800;margin-bottom:2px}
      h2{font-size:13px;font-weight:700;margin-bottom:6px;color:#1e3a5f}
      h3{font-size:11px;font-weight:700;margin:8px 0 4px;text-transform:uppercase;letter-spacing:.04em;color:#374151}
      .header{border-bottom:3px solid #1e3a5f;padding-bottom:10px;margin-bottom:14px;display:flex;justify-content:space-between;align-items:flex-end}
      .header-left .org{font-size:14px;font-weight:800;color:#1e3a5f}
      .header-left .subtitle{font-size:10px;color:#6b7280;margin-top:2px}
      .header-right{text-align:right;font-size:10px;color:#6b7280}
      .badge{display:inline-block;padding:2px 8px;border-radius:12px;font-size:10px;font-weight:700}
      .badge-green{background:#dcfce7;color:#166534}
      .badge-red{background:#fee2e2;color:#991b1b}
      .badge-blue{background:#dbeafe;color:#1e40af}
      .badge-yellow{background:#fef9c3;color:#854d0e}
      .info-grid{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-bottom:12px;background:#f8fafc;border:1px solid #e5e7eb;border-radius:6px;padding:10px}
      .info-item label{font-size:9px;text-transform:uppercase;letter-spacing:.05em;color:#9ca3af;display:block;margin-bottom:2px}
      .info-item span{font-weight:600;font-size:11px}
      table{width:100%;border-collapse:collapse;margin-bottom:10px;font-size:10px}
      thead tr{background:#1e3a5f;color:#fff}
      thead th{padding:6px 8px;text-align:left;font-weight:700;font-size:10px}
      tbody tr:nth-child(even){background:#f8fafc}
      tbody tr:hover{background:#eff6ff}
      td,th{padding:5px 8px;border-bottom:1px solid #e5e7eb;vertical-align:top}
      td.num{text-align:right;font-variant-numeric:tabular-nums}
      td.center{text-align:center}
      .section{margin-bottom:16px}
      .section-title{background:#1e3a5f;color:#fff;padding:5px 10px;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;border-radius:4px 4px 0 0;margin-bottom:0}
      .section-body{border:1px solid #cbd5e1;border-top:none;border-radius:0 0 4px 4px;padding:10px;margin-bottom:12px}
      .sum-row{display:flex;justify-content:space-between;padding:3px 0;border-bottom:1px solid #f1f5f9;font-size:10px}
      .sum-row.bold{font-weight:700;font-size:11px;border-top:2px solid #1e3a5f;padding-top:4px}
      .sum-row.selisih{background:#f0fdf4;padding:4px 8px;border-radius:4px;font-weight:700}
      .sum-row.selisih.err{background:#fff1f2}
      .ttd-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:20px;margin-top:24px}
      .ttd-box{border-top:1px solid #374151;padding-top:6px;text-align:center;font-size:10px}
      .ttd-box .role{color:#6b7280;font-size:9px;margin-bottom:40px}
      .ttd-box .name{font-weight:700;border-bottom:1px solid #374151;padding-bottom:2px}
      .footer{margin-top:20px;border-top:1px solid #e5e7eb;padding-top:8px;font-size:9px;color:#9ca3af;display:flex;justify-content:space-between}
      .pecahan-table th,td{font-size:10px}
      .positive{color:#166534;font-weight:700}
      .negative{color:#991b1b;font-weight:700}
      .total-row{background:#eef2ff!important;font-weight:700}`;

    const footer = `<div class="footer">
      <span>Dicetak: ${now} &nbsp;|&nbsp; Sistem: ${orgName}</span>
      <span>Dokumen ini digenerate otomatis oleh sistem AKTA IAT</span>
    </div>`;

    // ── 1. LAPORAN PEMERIKSAAN KAS ──────────────────────────────────────
    if (type === 'kas') {
      if (!_kasAuditTaskId) { showToast('Buka form pemeriksaan kas terlebih dahulu.', 'error'); return; }
      tasks = loadTasks();
      const t     = tasks.find(x => String(x.id) === String(_kasAuditTaskId));
      const kList = loadKasAudit().filter(k => String(k.planId) === String(t?.planId));
      if (!kList.length) { showToast('Belum ada data pemeriksaan kas untuk dicetak.', 'error'); return; }

      const rows = kList.map((k, i) => {
        const sbKB = Number(k.saldoBukuKB  || k.saldoBuku  || 0);
        const sfKB = Number(k.saldoFisikKB || k.saldoFisik || 0);
        const slKB = Number(k.selisihKB    || k.selisih    || (sfKB - sbKB));
        const sbKK = Number(k.saldoBukuKK  || 0);
        const sfKK = Number(k.saldoFisikKK || 0);
        const slKK = Number(k.selisihKK    || (sfKK - sbKK));

        const penRows = (k.penerimaan || []).map(r =>
          `<tr><td>${fTgl(r.tgl)}</td><td>${r.ket||'—'}</td><td class="num">${fRp(r.jumlah)}</td></tr>`).join('') ||
          `<tr><td colspan="3" style="color:#9ca3af;text-align:center">Tidak ada data</td></tr>`;
        const pelRows = (k.pengeluaran || []).map(r =>
          `<tr><td>${fTgl(r.tgl)}</td><td>${r.ket||'—'}</td><td class="num">${fRp(r.jumlah)}</td></tr>`).join('') ||
          `<tr><td colspan="3" style="color:#9ca3af;text-align:center">Tidak ada data</td></tr>`;
        const bonRows = (k.bonGantung || []).map(r =>
          `<tr><td>${fTgl(r.tgl)}</td><td>${r.ket||'—'}</td><td class="num">${fRp(r.jumlah)}</td></tr>`).join('') ||
          `<tr><td colspan="3" style="color:#9ca3af;text-align:center">Tidak ada data</td></tr>`;

        const pecKB  = k.pecahanKB || {};
        const pecKK  = k.pecahanKK || {};
        const denomRows = KA_DENOMS.map(d =>
          `<tr><td class="num">${d.toLocaleString('id-ID')}</td>
           <td class="center">${pecKB[d]||0}</td><td class="num">${fRp(d*(pecKB[d]||0))}</td>
           <td class="center">${pecKK[d]||0}</td><td class="num">${fRp(d*(pecKK[d]||0))}</td></tr>`).join('');

        const slKBCls = slKB === 0 ? 'positive' : 'negative';
        const slKKCls = slKK === 0 ? 'positive' : 'negative';

        return `
          ${i > 0 ? '<div style="page-break-before:always"></div>' : ''}
          <div class="section">
            <div class="section-title">BERITA ACARA PEMERIKSAAN KAS #${i+1}</div>
            <div class="section-body">
              <div class="info-grid">
                <div class="info-item"><label>Nama Auditee / Pemegang Kas</label><span>${k.namaAuditee||'—'}${k.jabatanAuditee ? ' <span style="font-size:9px;background:#f0f9ff;color:#0369a1;border-radius:3px;padding:1px 5px;margin-left:4px">' + k.jabatanAuditee + '</span>' : ''}</span></div>
                <div class="info-item"><label>Tanggal Pemeriksaan</label><span>${fTgl(k.tglPemeriksaan||k.tanggal)}</span></div>
                <div class="info-item"><label>Nama Auditor</label><span>${k.namaAuditor||k.savedBy||'—'}</span></div>
                <div class="info-item"><label>Cabang / Unit Usaha</label><span>${k.cabang||'—'}</span></div>
                <div class="info-item"><label>No SPT</label><span>${k.noSPT||'—'}</span></div>
                <div class="info-item"><label>Disimpan Oleh</label><span>${k.savedBy||'—'} — ${new Date(k.savedAt||Date.now()).toLocaleDateString('id-ID')}</span></div>
              </div>
            </div>
          </div>

          <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">
            <!-- KAS BESAR -->
            <div>
              <h3 style="background:#1e3a5f;color:#fff;padding:4px 8px;border-radius:4px">KAS BESAR</h3>
              <h3>▲ Penerimaan</h3>
              <table><thead><tr><th>Tanggal</th><th>Keterangan</th><th>Jumlah</th></tr></thead>
                <tbody>${penRows}</tbody></table>
              <h3>▼ Pengeluaran</h3>
              <table><thead><tr><th>Tanggal</th><th>Keterangan</th><th>Jumlah</th></tr></thead>
                <tbody>${pelRows}</tbody></table>
              <div class="sum-row"><span>Saldo Awal</span><span>${fRp(k.kasBesarSaldoAwal||0)}</span></div>
              <div class="sum-row"><span>+ Total Penerimaan</span><span>${fRp((k.penerimaan||[]).reduce((s,r)=>s+r.jumlah,0))}</span></div>
              <div class="sum-row"><span>− Total Pengeluaran</span><span>${fRp((k.pengeluaran||[]).reduce((s,r)=>s+r.jumlah,0))}</span></div>
              <div class="sum-row bold"><span>Saldo Buku</span><span>${fRp(sbKB)}</span></div>
              <div class="sum-row"><span>Saldo Fisik</span><span>${fRp(sfKB)}</span></div>
              <div class="sum-row selisih${slKB!==0?' err':''}"><span>Selisih KB</span><span class="${slKBCls}">${fRp(slKB)} ${slKB===0?'✓':'✗'}</span></div>
              ${k.kasBesarKet ? `<div style="font-size:9px;color:#6b7280;margin-top:4px">Ket: ${k.kasBesarKet}</div>` : ''}
            </div>

            <!-- KAS KECIL -->
            <div>
              <h3 style="background:#1e3a5f;color:#fff;padding:4px 8px;border-radius:4px">KAS KECIL</h3>
              <h3>📌 Bon Gantung</h3>
              <table><thead><tr><th>Tanggal</th><th>Keterangan</th><th>Jumlah</th></tr></thead>
                <tbody>${bonRows}</tbody></table>
              <div class="sum-row"><span>Cadangan Kas Kecil</span><span>${fRp(k.kasKecilCadangan||0)}</span></div>
              <div class="sum-row"><span>− Total Bon Gantung</span><span>${fRp((k.bonGantung||[]).reduce((s,r)=>s+r.jumlah,0))}</span></div>
              <div class="sum-row bold"><span>Saldo Buku</span><span>${fRp(sbKK)}</span></div>
              <div class="sum-row"><span>Saldo Fisik</span><span>${fRp(sfKK)}</span></div>
              <div class="sum-row selisih${slKK!==0?' err':''}"><span>Selisih KK</span><span class="${slKKCls}">${fRp(slKK)} ${slKK===0?'✓':'✗'}</span></div>
              ${k.kasKecilKet ? `<div style="font-size:9px;color:#6b7280;margin-top:4px">Ket: ${k.kasKecilKet}</div>` : ''}
            </div>
          </div>

          <!-- PECAHAN NOMINAL -->
          <h3 style="margin-top:12px">Rincian Pecahan Nominal</h3>
          <table><thead>
            <tr><th>Pecahan (Rp)</th><th class="center">KB Lbr</th><th>KB Total</th><th class="center">KK Lbr</th><th>KK Total</th></tr>
          </thead><tbody>${denomRows}</tbody></table>

          <!-- TTD -->
          <div class="ttd-grid">
            <div class="ttd-box"><div class="role">${k.jabatanAuditee||'Auditee / Pemegang Kas'}</div><div class="name">${k.namaAuditee||'&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;'}</div><div style="font-size:9px;margin-top:3px">Nama & Tanda Tangan</div></div>
            <div class="ttd-box"><div class="role">Auditor</div><div class="name">${k.namaAuditor||'&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;'}</div><div style="font-size:9px;margin-top:3px">Nama & Tanda Tangan</div></div>
            <div class="ttd-box"><div class="role">Mengetahui / Kepala Cabang</div><div class="name">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</div><div style="font-size:9px;margin-top:3px">Nama & Tanda Tangan</div></div>
          </div>`;
      }).join('');

      _printReport(`
        <div class="header">
          <div class="header-left">
            <div class="org">${orgName}</div>
            <div class="subtitle">Laporan Pemeriksaan Kas</div>
          </div>
          <div class="header-right">
            <div style="font-size:13px;font-weight:700;color:#1e3a5f">BERITA ACARA PEMERIKSAAN KAS</div>
            <div>No SPT: ${t?.noSPT||'—'} &nbsp;|&nbsp; Cabang: ${t?.cabangPlan||'—'}</div>
            <div>Dicetak: ${now}</div>
          </div>
        </div>
        ${rows}
        ${footer}
      `, `Laporan Pemeriksaan Kas — ${t?.cabangPlan||''}`);
    }

    // ── 2. LAPORAN FISIK SMH ─────────────────────────────────────────────
    else if (type === 'fisik-smh') {
      const hasilData  = loadSmhData(SMH_HASIL_KEY);
      const planId     = _auditContext?.planId;
      const filtered   = planId
        ? hasilData.filter(h => String(h.auditPlanId) === String(planId))
        : hasilData;

      if (!filtered.length) { showToast('Belum ada data pemeriksaan fisik SMH.', 'error'); return; }

      const cabang   = _auditContext?.cabang || '—';
      const noSPT    = _auditContext?.noSPT  || '—';
      const area     = _auditContext?.area   || '—';
      const auditor  = session.displayName;

      const totalAda    = filtered.filter(h => h.statusFisik !== 'TIDAK ADA').length;
      const totalTidak  = filtered.length - totalAda;

      const tableRows = filtered.map((h, i) => {
        const perlYang = (h.perlengkapan || []).filter(p => p.ada === 1 || p.ada === true).map(p => p.nama).join(', ') || '—';
        const perlTdk  = (h.perlengkapan || []).filter(p => !p.ada).map(p => p.nama).join(', ') || '—';
        const statusBadge = h.statusFisik === 'Ready for Sale'
          ? `<span class="badge badge-green">Ready for Sale</span>`
          : `<span class="badge badge-yellow">${h.statusFisik||'—'}</span>`;
        return `<tr>
          <td class="center">${i+1}</td>
          <td style="white-space:nowrap">${h.noMesin||'—'}</td>
          <td style="white-space:nowrap">${h.noRangka||'—'}</td>
          <td>${h.kodeModel||'—'}</td>
          <td>${h.kodeWarna||'—'}</td>
          <td>${h.gudang||'—'}</td>
          <td>${perlYang}</td>
          <td style="color:#dc2626;font-size:9px">${perlTdk === '—' ? '' : perlTdk}</td>
          <td>${statusBadge}</td>
        </tr>`;
      }).join('');

      _printReport(`
        <div class="header">
          <div class="header-left">
            <div class="org">${orgName}</div>
            <div class="subtitle">Laporan Pemeriksaan Fisik SMH (Stok Motor Honda)</div>
          </div>
          <div class="header-right">
            <div style="font-size:13px;font-weight:700;color:#1e3a5f">LAPORAN FISIK SMH</div>
            <div>Dicetak: ${now}</div>
          </div>
        </div>
        <div class="info-grid" style="grid-template-columns:1fr 1fr 1fr">
          <div class="info-item"><label>Unit Usaha / Cabang</label><span>${cabang}</span></div>
          <div class="info-item"><label>No SPT</label><span>${noSPT}</span></div>
          <div class="info-item"><label>Area / Wilayah</label><span>${area}</span></div>
          <div class="info-item"><label>Auditor</label><span>${auditor}</span></div>
          <div class="info-item"><label>Total Diperiksa</label><span>${filtered.length} unit</span></div>
          <div class="info-item"><label>Fisik Ada / Tidak Ada</label>
            <span><span class="badge badge-green">${totalAda} Ada</span>&nbsp;<span class="badge badge-red">${totalTidak} Tidak Ada</span></span>
          </div>
        </div>
        <div class="section">
          <div class="section-title">DAFTAR UNIT YANG DIPERIKSA</div>
          <div style="border:1px solid #cbd5e1;border-top:none;overflow:auto">
            <table><thead>
              <tr>
                <th class="center">No</th><th>No.Mesin</th><th>No.Rangka</th>
                <th>Kode Model</th><th>Warna</th><th>Gudang</th>
                <th>Perlengkapan Ada</th><th>Perlengkapan Kurang</th><th>Status</th>
              </tr>
            </thead><tbody>${tableRows}</tbody></table>
          </div>
        </div>
        <div class="ttd-grid">
          <div class="ttd-box"><div class="role">Kasir / Auditee</div><div class="name">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</div><div style="font-size:9px;margin-top:3px">Nama & Tanda Tangan</div></div>
          <div class="ttd-box"><div class="role">Auditor</div><div class="name">${auditor}</div><div style="font-size:9px;margin-top:3px">Nama & Tanda Tangan</div></div>
          <div class="ttd-box"><div class="role">Mengetahui</div><div class="name">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</div><div style="font-size:9px;margin-top:3px">Nama & Tanda Tangan</div></div>
        </div>
        ${footer}
      `, `Laporan Fisik SMH — ${cabang}`);
    }

    // ── 3. LAPORAN PERLENGKAPAN SMH ──────────────────────────────────────
    else if (type === 'perlengkapan') {
      const luarData = loadSmhData(SMH_LUAR_KEY);
      const planId   = _auditContext?.planId;
      const filtered = planId
        ? luarData.filter(r => String(r.auditPlanId) === String(planId))
        : luarData;

      const cabang  = _auditContext?.cabang || '—';
      const noSPT   = _auditContext?.noSPT  || '—';
      const auditor = session.displayName;

      const tableRows = filtered.map((r, i) => {
        const sl     = Number(r.selisih || (r.fisik - r.saldo) || 0);
        const slCls  = sl === 0 ? 'positive' : 'negative';
        const slTxt  = sl === 0 ? `<span class="positive">0 ✓</span>` : `<span class="negative">${sl} ✗</span>`;
        return `<tr>
          <td class="center">${i+1}</td>
          <td>${fTgl(r.tgl)}</td>
          <td>${r.namaUnitUsaha||r.cabang||'—'}</td>
          <td>${r.namaPemeriksa||r.savedBy||'—'}</td>
          <td><strong>${r.jenisPerlengkapan||'—'}</strong></td>
          <td class="center">${r.saldo||0}</td>
          <td class="center">${r.fisik||0}</td>
          <td class="center">${slTxt}</td>
          <td style="font-size:9px;color:#6b7280">${r.penjelasan||'—'}</td>
        </tr>`;
      }).join('') || `<tr><td colspan="9" style="text-align:center;color:#9ca3af;padding:16px">Belum ada data</td></tr>`;

      const totalSaldo = filtered.reduce((s,r) => s + (r.saldo||0), 0);
      const totalFisik = filtered.reduce((s,r) => s + (r.fisik||0), 0);
      const totalSel   = totalFisik - totalSaldo;

      _printReport(`
        <div class="header">
          <div class="header-left">
            <div class="org">${orgName}</div>
            <div class="subtitle">Laporan Pemeriksaan Perlengkapan SMH (Luar Fisik)</div>
          </div>
          <div class="header-right">
            <div style="font-size:13px;font-weight:700;color:#1e3a5f">LAPORAN PERLENGKAPAN SMH</div>
            <div>Dicetak: ${now}</div>
          </div>
        </div>
        <div class="info-grid" style="grid-template-columns:1fr 1fr 1fr">
          <div class="info-item"><label>Unit Usaha / Cabang</label><span>${cabang}</span></div>
          <div class="info-item"><label>No SPT</label><span>${noSPT}</span></div>
          <div class="info-item"><label>Auditor</label><span>${auditor}</span></div>
          <div class="info-item"><label>Total Item</label><span>${filtered.length} jenis perlengkapan</span></div>
          <div class="info-item"><label>Total Saldo (Ekspektasi)</label><span>${totalSaldo}</span></div>
          <div class="info-item"><label>Total Fisik / Selisih</label>
            <span>${totalFisik} / <span class="${totalSel===0?'positive':'negative'}">${totalSel===0?'Sesuai ✓':totalSel+' ✗'}</span></span>
          </div>
        </div>
        <div class="section">
          <div class="section-title">RINCIAN PEMERIKSAAN PERLENGKAPAN</div>
          <div style="border:1px solid #cbd5e1;border-top:none;overflow:auto">
            <table><thead>
              <tr><th class="center">No</th><th>Tanggal</th><th>Unit Usaha</th><th>Pemeriksa</th>
                  <th>Jenis Perlengkapan</th><th class="center">Saldo</th><th class="center">Fisik</th>
                  <th class="center">Selisih</th><th>Penjelasan</th></tr>
            </thead><tbody>${tableRows}</tbody>
            <tfoot><tr class="total-row">
              <td colspan="5" style="text-align:right;padding-right:12px">TOTAL</td>
              <td class="center">${totalSaldo}</td>
              <td class="center">${totalFisik}</td>
              <td class="center ${totalSel===0?'positive':'negative'}">${totalSel===0?'0 ✓':totalSel+' ✗'}</td>
              <td></td>
            </tr></tfoot>
            </table>
          </div>
        </div>
        <div class="ttd-grid">
          <div class="ttd-box"><div class="role">Kasir / Auditee</div><div class="name">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</div><div style="font-size:9px;margin-top:3px">Nama & Tanda Tangan</div></div>
          <div class="ttd-box"><div class="role">Auditor</div><div class="name">${auditor}</div><div style="font-size:9px;margin-top:3px">Nama & Tanda Tangan</div></div>
          <div class="ttd-box"><div class="role">Mengetahui</div><div class="name">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</div><div style="font-size:9px;margin-top:3px">Nama & Tanda Tangan</div></div>
        </div>
        ${footer}
      `, `Laporan Perlengkapan SMH — ${cabang}`);
    }

    // ── 4. LAPORAN PLAFON SMH ────────────────────────────────────────────
    else if (type === 'plafon') {
      const harga   = loadSmhData(SMH_HARGA_KEY);
      const plafon  = loadSmhData(SMH_PLAFON_KEY);
      const onhand  = _loadOnhandForPlan(_auditContext?.planId);
      const normK   = s => (s || '').replace(/[\s\/\-_]/g, '').toUpperCase();
      const last3   = s => (s || '').replace(/[\s\-_]/g, '').toUpperCase().slice(-3);

      const findH = (model, intern) => {
        const nM = normK(model), nI = normK(intern);
        return harga.find(h => h.kodeModel === model)
            || harga.find(h => normK(h.kodeModel) === nM)
            || harga.find(h => (h.namaSMH||'') === model)
            || harga.find(h => normK(h.namaSMH) === nM)
            || (intern && (harga.find(h => h.kodeModel === intern) || harga.find(h => normK(h.kodeModel) === nI)));
      };

      // Hitung per model
      const modelQty = {}, modelInternMap = {};
      onhand.forEach(u => {
        const m = (u.model || u.kodeModelIntern || '').trim() || '—';
        modelQty[m] = (modelQty[m] || 0) + 1;
        if (u.kodeModelIntern && !modelInternMap[m]) modelInternMap[m] = u.kodeModelIntern;
      });

      let totalQty = 0, totalNilai = 0;
      const modelRows = Object.entries(modelQty).sort((a,b) => a[0].localeCompare(b[0])).map(([model, qty], i) => {
        const hData = findH(model, modelInternMap[model]);
        const harga2 = hData ? hData.harga : 0;
        const nilai  = harga2 * qty;
        totalQty   += qty;
        totalNilai += nilai;
        return `<tr>
          <td class="center">${i+1}</td>
          <td><strong>${model}</strong>${modelInternMap[model]?`<br><span style="font-size:9px;color:#9ca3af">${modelInternMap[model]}</span>`:''}</td>
          <td>${hData?hData.namaSMH:'<span style="color:#9ca3af">—</span>'}</td>
          <td class="center">${qty}</td>
          <td class="num">${harga2 ? fRp(harga2) : '<span style="color:#9ca3af">—</span>'}</td>
          <td class="num">${nilai ? fRp(nilai) : '<span style="color:#9ca3af">—</span>'}</td>
        </tr>`;
      }).join('') || `<tr><td colspan="6" style="text-align:center;color:#9ca3af;padding:16px">Belum ada data onhand</td></tr>`;

      // Hitung per unit usaha (last3 matching)
      const unitMap = {};
      onhand.forEach(u => {
        const k     = last3(u.kodeUnitUsaha);
        const m     = (u.model || u.kodeModelIntern || '').trim();
        const hData = findH(m, u.kodeModelIntern);
        if (k) unitMap[k] = (unitMap[k] || 0) + (hData ? hData.harga : 0);
      });

      const cabang      = _auditContext?.cabang || session.unitUsaha || '—';
      const auditor     = session.displayName;
      const hasUUData   = Object.keys(unitMap).length > 0;
      const auditCabang = (_auditContext?.cabang || session.unitUsaha || '').trim();

      // ── Fallback: jika onhand tidak punya kodeUnitUsaha,
      //    cocokkan via audit context atau single-plafon ──────────────────────
      let grandPlafonNilai = 0, grandPlafonPf = 0;
      let rowNo = 0;

      const plafonRows = plafon.map(p => {
        const key3  = last3(p.kodeUnitUsaha);
        let   nilai = unitMap[key3] || 0;

        // Fallback A: onhand tanpa kodeUnitUsaha → pakai totalNilai
        if (!hasUUData && !nilai) {
          const isCtxMatch = auditCabang && last3(auditCabang) === key3;
          const isOnlyOne  = plafon.length === 1;
          nilai = (isCtxMatch || isOnlyOne) ? totalNilai : 0;
        }
        // Fallback B: single plafon entry + ada total nilai
        if (!nilai && plafon.length === 1 && totalNilai > 0) nilai = totalNilai;

        if (nilai <= 0) return null;

        rowNo++;
        const pf     = p.plafon || 0;
        const sel    = pf - nilai;
        const util   = pf > 0 ? Math.round((nilai / pf) * 100) : 0;
        const selCls = sel >= 0 ? 'positive' : 'negative';
        const stsCls = sel >= 0 ? 'badge-green' : 'badge-red';
        const stsLbl = sel > 0 ? '✓ Dalam Plafon' : sel < 0 ? '⚠ Melewati Plafon' : '= Tepat Plafon';
        grandPlafonNilai += nilai;
        grandPlafonPf    += pf;

        return `<tr>
          <td class="center">${rowNo}</td>
          <td><strong>${p.kodeUnitUsaha}</strong></td>
          <td>${p.daerah || '—'}</td>
          <td class="num" style="font-weight:700">${fRp(nilai)}</td>
          <td class="num">${fRp(pf)}</td>
          <td class="num ${selCls}" style="font-weight:700">${sel >= 0 ? '' : '−'}${fRp(Math.abs(sel))}</td>
          <td class="center">${util}%</td>
          <td class="center"><span class="badge ${stsCls}">${stsLbl}</span></td>
        </tr>`;
      }).filter(Boolean);

      // Baris total
      if (plafonRows.length > 0) {
        const grandSel    = grandPlafonPf - grandPlafonNilai;
        const grandUtil   = grandPlafonPf > 0 ? Math.round((grandPlafonNilai / grandPlafonPf) * 100) : 0;
        const grandSelCls = grandSel >= 0 ? 'positive' : 'negative';
        plafonRows.push(`<tr class="total-row">
          <td colspan="2" style="text-align:right;padding-right:12px">TOTAL (${rowNo} unit)</td>
          <td></td>
          <td class="num" style="color:#1e3a5f;font-size:12px">${fRp(grandPlafonNilai)}</td>
          <td class="num" style="font-size:12px">${fRp(grandPlafonPf)}</td>
          <td class="num ${grandSelCls}" style="font-size:12px;font-weight:700">${grandSel >= 0 ? '' : '−'}${fRp(Math.abs(grandSel))}</td>
          <td class="center" style="font-weight:700">${grandUtil}%</td>
          <td></td>
        </tr>`);
      }

      const plafonRowsHtml = plafonRows.join('') ||
        `<tr><td colspan="8" style="text-align:center;color:#9ca3af;padding:16px">Tidak ada data plafon yang cocok dengan onhand</td></tr>`;

      _printReport(`
        <div class="header">
          <div class="header-left">
            <div class="org">${orgName}</div>
            <div class="subtitle">Laporan Plafon SMH (Stok Motor Honda)</div>
          </div>
          <div class="header-right">
            <div style="font-size:13px;font-weight:700;color:#1e3a5f">LAPORAN PLAFON SMH</div>
            <div>Auditor: ${auditor} &nbsp;|&nbsp; Dicetak: ${now}</div>
          </div>
        </div>
        <div class="info-grid" style="grid-template-columns:repeat(3,1fr)">
          <div class="info-item"><label>Unit Usaha / Cabang</label><span>${cabang}</span></div>
          <div class="info-item"><label>Total Unit Onhand</label><span>${onhand.length} unit</span></div>
          <div class="info-item"><label>Jenis Model SMH</label><span>${Object.keys(modelQty).length} model</span></div>
          <div class="info-item"><label>Total Nilai Onhand SMH</label><span style="color:#1e3a5f;font-weight:800">${fRp(totalNilai)}</span></div>
          <div class="info-item"><label>Total Plafon</label><span style="font-weight:700">${fRp(grandPlafonPf)}</span></div>
          <div class="info-item"><label>Sisa Plafon</label><span style="font-weight:700;color:${grandPlafonPf - grandPlafonNilai >= 0 ? '#166534' : '#991b1b'}">${grandPlafonPf > 0 ? ((grandPlafonPf - grandPlafonNilai >= 0 ? '' : '−') + fRp(Math.abs(grandPlafonPf - grandPlafonNilai))) : '—'}</span></div>
          <div class="info-item"><label>Auditor</label><span>${auditor}</span></div>
          <div class="info-item"><label>Tanggal Cetak</label><span>${now}</span></div>
          <div class="info-item"><label>% Utilisasi Plafon</label><span style="font-weight:800;color:${grandPlafonPf > 0 && grandPlafonNilai > grandPlafonPf ? '#991b1b' : '#1e3a5f'}">${grandPlafonPf > 0 ? Math.round((grandPlafonNilai / grandPlafonPf) * 100) + '%' : '—'}</span></div>
        </div>
        <div class="section">
          <div class="section-title">NILAI ONHAND PER KODE MODEL</div>
          <div style="border:1px solid #cbd5e1;border-top:none">
            <table><thead><tr><th class="center">No</th><th>Kode Model</th><th>Nama SMH</th>
              <th class="center">Qty</th><th>Harga Satuan</th><th>Nilai Onhand</th></tr></thead>
            <tbody>${modelRows}</tbody>
            <tfoot><tr class="total-row">
              <td colspan="3" style="text-align:right;padding-right:12px">TOTAL KESELURUHAN</td>
              <td class="center">${totalQty}</td><td></td>
              <td class="num" style="color:#1e3a5f;font-size:12px">${fRp(totalNilai)}</td>
            </tr></tfoot>
            </table>
          </div>
        </div>
        <div class="section">
          <div class="section-title">PERBANDINGAN PLAFON vs NILAI ONHAND</div>
          <div style="border:1px solid #cbd5e1;border-top:none">
            <table><thead><tr><th class="center">No</th><th>Unit Usaha</th><th>Daerah</th>
              <th>Nilai Onhand</th><th>Plafon</th><th>Selisih</th>
              <th class="center">% Utilisasi</th><th>Status</th></tr></thead>
            <tbody>${plafonRowsHtml}</tbody>
            </table>
          </div>
        </div>
        <div class="ttd-grid">
          <div class="ttd-box"><div class="role">Kasir / Auditee</div><div class="name">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</div><div style="font-size:9px;margin-top:3px">Nama & Tanda Tangan</div></div>
          <div class="ttd-box"><div class="role">Auditor</div><div class="name">${auditor}</div><div style="font-size:9px;margin-top:3px">Nama & Tanda Tangan</div></div>
          <div class="ttd-box"><div class="role">Mengetahui</div><div class="name">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</div><div style="font-size:9px;margin-top:3px">Nama & Tanda Tangan</div></div>
        </div>
        ${footer}
      `, `Laporan Plafon SMH — ${cabang}`);
    }

    // ── 5. LAPORAN PERLENGKAPAN GABUNGAN (FISIK + LUAR FISIK) ────────────
    else if (type === 'perlengkapan-full') {
      const hasilData  = loadSmhData(SMH_HASIL_KEY);
      const luarData   = loadSmhData(SMH_LUAR_KEY);
      const perlDB     = loadSmhData(SMH_PERL_KEY);
      const planId     = _auditContext?.planId;
      const onhandData = _loadOnhandForPlan(planId);

      const filteredHasil = planId
        ? hasilData.filter(h => String(h.auditPlanId) === String(planId))
        : hasilData;
      const filteredLuar  = planId
        ? luarData.filter(r => String(r.auditPlanId) === String(planId))
        : luarData;

      const cabang  = _auditContext?.cabang || session.unitUsaha || '—';
      const noSPT   = _auditContext?.noSPT  || '—';
      const area    = (_auditContext?.area  || '').toUpperCase();
      const auditor = session.displayName;
      const nowFmt  = new Date().toLocaleDateString('id-ID', { day: '2-digit', month: 'long', year: 'numeric' });

      // ── Helpers ──────────────────────────────────────────────────────────
      const normK = s => (s || '').replace(/[\s\/\-_]/g, '').toUpperCase();
      const isAda = p => p.ada === 1 || p.ada === true;

      // ── A. Hitung ekspektasi per perlengkapan (dari smhPerl × onhand) ───
      // Ambil semua nama perlengkapan unik dari smhPerl (filter area jika ada)
      let perlDBFiltered = perlDB;
      if (area) {
        const byArea = perlDB.filter(p => (p.area||'').toUpperCase() === area);
        if (byArea.length) perlDBFiltered = byArea;
      }

      // Build: nama → Set of kodeModel (NOSIN)
      const perlModelMap = {};
      perlDBFiltered.forEach(p => {
        const n = (p.namaPerlengkapan || '').trim();
        if (!n) return;
        if (!perlModelMap[n]) perlModelMap[n] = new Set();
        const mc = normK(p.kodeModel);
        if (mc) perlModelMap[n].add(mc);
      });

      // Hitung expected per perlengkapan (unit onhand yg cocok kodeModel)
      const perlExpected = {};
      Object.entries(perlModelMap).forEach(([nama, codes]) => {
        let cnt = 0;
        onhandData.forEach(u => {
          const pfx5 = (u.noMesin || '').replace(/\s/g,'').slice(0,5).toUpperCase();
          if (!pfx5) return;
          for (const mc of codes) {
            if (mc === pfx5 || mc.startsWith(pfx5) || pfx5.startsWith(mc)) { cnt++; break; }
          }
        });
        perlExpected[nama] = cnt;
      });

      // ── B. Agregasi dari fisik SMH per perlengkapan ──────────────────────
      // perlFisikAgg[nama] → { ada, tidakAda, unitsTidakAda:[{noMesin, model, tgl}] }
      const perlFisikAgg = {};
      filteredHasil.forEach(h => {
        (h.perlengkapan || []).forEach(p => {
          const n = (p.nama || '').trim();
          if (!n) return;
          if (!perlFisikAgg[n]) perlFisikAgg[n] = { ada: 0, tidakAda: 0, unitsTidakAda: [], unitsAda: [] };
          if (isAda(p)) {
            perlFisikAgg[n].ada++;
            perlFisikAgg[n].unitsAda.push({ noMesin: h.noMesin, model: h.kodeModel||'—' });
          } else {
            perlFisikAgg[n].tidakAda++;
            perlFisikAgg[n].unitsTidakAda.push({ noMesin: h.noMesin, model: h.kodeModel||'—', tgl: h.waktu });
          }
        });
      });

      // ── C. Unit yang belum diperiksa ─────────────────────────────────────
      const scannedSet = new Set(filteredHasil.map(h => (h.noMesin||'').replace(/\s/g,'').toUpperCase()));
      const unscanned  = onhandData.filter(u => {
        const key = (u.noMesin||'').replace(/\s/g,'').toUpperCase();
        return key && !scannedSet.has(key);
      });

      // ── D. Luar fisik per perlengkapan ───────────────────────────────────
      const luarAgg = {};
      filteredLuar.forEach(r => {
        const n = (r.jenisPerlengkapan || '').trim();
        if (!n) return;
        if (!luarAgg[n]) luarAgg[n] = { saldo: 0, fisik: 0, entries: [] };
        luarAgg[n].saldo += parseFloat(r.saldo) || 0;
        luarAgg[n].fisik += parseFloat(r.fisik ?? r.items?.[0]?.qty) || 0;
        luarAgg[n].entries.push(r);
      });

      // ── E. Gabungkan semua nama perlengkapan (hanya yang ada di onhand) ──
      const allNamaSet = new Set([
        ...Object.keys(perlExpected).filter(n => perlExpected[n] > 0),
        ...Object.keys(perlFisikAgg).filter(n => (perlExpected[n]||0) > 0),
        ...Object.keys(luarAgg).filter(n => (perlExpected[n]||0) > 0),
      ]);
      const allNama = [...allNamaSet].sort();

      // ── F. Hitung summary ────────────────────────────────────────────────
      const totalExpected   = allNama.reduce((s,n) => s + (perlExpected[n]||0), 0);
      const totalFisikAda   = allNama.reduce((s,n) => s + (perlFisikAgg[n]?.ada||0), 0);
      const totalFisikMinus = allNama.reduce((s,n) => s + (perlFisikAgg[n]?.tidakAda||0), 0);
      const totalBelumScan  = unscanned.length;
      const jenisMinus      = allNama.filter(n => (perlFisikAgg[n]?.tidakAda||0) > 0 || (luarAgg[n] && (luarAgg[n].entries||[]).reduce((s,r)=>{const f=parseFloat(r.fisik??r.items?.[0]?.qty)||0;const sd=parseFloat(r.saldo)||0;return s+(r.selisih??(f-sd));},0) < 0)).length;

      const statusOK = totalFisikMinus === 0 && jenisMinus === 0;

      // ── REKAP UTAMA — semua perlengkapan + semua kondisi ─────────────────
      const rekapRows = allNama.map((nama, i) => {
        const exp      = perlExpected[nama] || 0;
        const agg      = perlFisikAgg[nama] || { ada: 0, tidakAda: 0 };
        const luar     = luarAgg[nama] || { saldo: 0, fisik: 0, entries: [] };
        const luarSel  = (luar.entries || []).reduce((s, r) => { const f=parseFloat(r.fisik??r.items?.[0]?.qty)||0; const sd=parseFloat(r.saldo)||0; return s+(r.selisih??(f-sd)); }, 0);
        const belumScan = exp - agg.ada - agg.tidakAda;  // unit di database tapi belum scan
        const minus    = agg.tidakAda;    // unit yang perlengkapan ini tidak ada saat diperiksa
        const isMinus  = minus > 0 || luarSel < 0;
        const isBelum  = belumScan > 0;

        const rowBg    = isMinus ? 'background:#fff1f2' : isBelum ? 'background:#fefce8' : '';
        const statusEl = isMinus
          ? `<span style="background:#fee2e2;color:#991b1b;padding:2px 8px;border-radius:10px;font-weight:800;font-size:10px">⚠ MINUS ${minus>0?'('+minus+' unit)':''}</span>`
          : isBelum
            ? `<span style="background:#fef9c3;color:#854d0e;padding:2px 8px;border-radius:10px;font-weight:700;font-size:10px">⏳ BELUM LENGKAP</span>`
            : `<span style="background:#dcfce7;color:#166534;padding:2px 8px;border-radius:10px;font-weight:700;font-size:10px">✓ OK</span>`;

        const noMesinsKurang = agg.unitsTidakAda?.map(u => u.noMesin).join(', ') || '—';

        return `<tr style="${rowBg}">
          <td class="center">${i+1}</td>
          <td><strong>${nama}</strong></td>
          <td class="center" style="color:#6b7280">${exp||'—'}</td>
          <td class="center" style="color:#166534;font-weight:700">${agg.ada}</td>
          <td class="center" style="color:${minus>0?'#dc2626':'#6b7280'};font-weight:${minus>0?'800':'400'}">${minus>0?'<strong>−'+minus+'</strong>':agg.tidakAda}</td>
          <td class="center" style="color:${belumScan>0?'#854d0e':'#6b7280'}">${belumScan > 0 ? belumScan : '—'}</td>
          <td class="center">${luar.saldo||0}</td>
          <td class="center">${luar.fisik||0}</td>
          <td class="center" style="color:${luarSel<0?'#dc2626':luarSel>0?'#166534':'#6b7280'};font-weight:700">${luarSel===0?'0':luarSel>0?'+'+luarSel:luarSel}</td>
          <td>${statusEl}</td>
        </tr>
        ${minus > 0 ? `<tr style="background:#fff8f8"><td></td><td colspan="9" style="font-size:9px;color:#991b1b;padding:3px 8px 5px 20px">
          ⚠ Unit kurang: ${noMesinsKurang}</td></tr>` : ''}`;
      }).join('') || `<tr><td colspan="10" style="text-align:center;color:#9ca3af;padding:16px">Tidak ada data perlengkapan</td></tr>`;

      // ── DAFTAR KEKURANGAN (MINUS) ────────────────────────────────────────
      const minusRows = [];
      filteredHasil.forEach(h => {
        const tidakAdaList = (h.perlengkapan||[]).filter(p => !isAda(p)).map(p => p.nama);
        if (tidakAdaList.length === 0) return;
        minusRows.push(`<tr style="background:#fff1f2">
          <td style="white-space:nowrap;font-weight:700;color:#dc2626">${h.noMesin||'—'}</td>
          <td>${h.kodeModel||'—'}</td>
          <td>${h.gudang||'—'}</td>
          <td>${fTgl(h.waktu)}</td>
          <td style="color:#dc2626;font-weight:600">${tidakAdaList.join(', ')}</td>
          <td class="center" style="font-weight:800;color:#dc2626">${tidakAdaList.length}</td>
        </tr>`);
      });
      const minusSection = minusRows.length
        ? minusRows.join('')
        : `<tr><td colspan="6" style="text-align:center;color:#166534;padding:12px;font-weight:700">✓ Tidak ada kekurangan perlengkapan dari fisik unit</td></tr>`;

      // ── UNIT BELUM DIPERIKSA ─────────────────────────────────────────────
      const unscannedRows = unscanned.map((u, i) => `<tr style="background:#fefce8">
        <td class="center">${i+1}</td>
        <td style="font-weight:700;color:#854d0e;white-space:nowrap">${u.noMesin||'—'}</td>
        <td>${u.noRangka||'—'}</td>
        <td>${u.kodeModelIntern||'—'}</td>
        <td>${u.model||'—'}</td>
        <td>${u.gudang||'—'}</td>
        <td style="color:#6b7280;font-size:9px">${u.kodeUnitUsaha||'—'}</td>
      </tr>`).join('') || `<tr><td colspan="7" style="text-align:center;color:#166534;padding:12px;font-weight:700">✓ Semua unit onhand sudah diperiksa</td></tr>`;

      // ── DETAIL PER UNIT (semua unit + status perlengkapan) ───────────────
      const unitDetailRows = filteredHasil.map((h, i) => {
        const semua    = (h.perlengkapan||[]).length;
        const adaCount = (h.perlengkapan||[]).filter(isAda).length;
        const tdkCount = semua - adaCount;
        const pct      = semua > 0 ? Math.round((adaCount/semua)*100) : 100;
        const perlAda  = (h.perlengkapan||[]).filter(isAda).map(p=>p.nama).join(', ') || '—';
        const perlTdk  = (h.perlengkapan||[]).filter(p=>!isAda(p)).map(p=>p.nama).join(', ') || '—';
        const rowBg    = tdkCount > 0 ? 'background:#fff8f8' : '';
        const bar      = `<div style="display:flex;align-items:center;gap:4px">
          <div style="background:#e5e7eb;border-radius:3px;height:8px;width:50px;flex-shrink:0">
            <div style="background:${pct===100?'#22c55e':pct>=50?'#f59e0b':'#ef4444'};width:${pct}%;height:100%;border-radius:3px"></div>
          </div>
          <span style="font-size:9px">${adaCount}/${semua}</span>
        </div>`;
        return `<tr style="${rowBg}">
          <td class="center">${i+1}</td>
          <td style="white-space:nowrap;font-weight:600;color:${tdkCount>0?'#dc2626':'#1a1a1a'}">${h.noMesin||'—'}</td>
          <td>${h.kodeModel||'—'}</td>
          <td>${fTgl(h.waktu)}</td>
          <td>${h.gudang||'—'}</td>
          <td>${bar}</td>
          <td style="font-size:9px;color:#166534">${perlAda}</td>
          <td style="font-size:9px;color:#dc2626;font-weight:${tdkCount>0?'700':'400'}">${perlTdk === '—' ? '<span style="color:#9ca3af">—</span>' : perlTdk}</td>
          <td>${h.statusFisik==='Ready for Sale'?'<span class="badge badge-green">Ready</span>':'<span class="badge badge-yellow">'+(h.statusFisik||'—')+'</span>'}</td>
        </tr>`;
      }).join('') || `<tr><td colspan="9" style="text-align:center;color:#9ca3af;padding:12px">Belum ada unit yang diperiksa</td></tr>`;

      // ── LUAR FISIK ROWS ──────────────────────────────────────────────────
      const luarRows2 = filteredLuar.map((r, i) => {
        const sl = Number(r.selisih ?? (r.fisik - r.saldo) ?? 0);
        return `<tr style="${sl<0?'background:#fff1f2':''}">
          <td class="center">${i+1}</td>
          <td>${fTgl(r.tgl)}</td>
          <td><strong>${r.jenisPerlengkapan||'—'}</strong></td>
          <td>${r.namaUnitUsaha||'—'}</td>
          <td>${r.namaPemeriksa||r.savedBy||'—'}</td>
          <td class="center">${r.saldo||0}</td>
          <td class="center" style="font-weight:700">${r.fisik||0}</td>
          <td class="center" style="color:${sl<0?'#dc2626':sl>0?'#166534':'#6b7280'};font-weight:700">${sl===0?'0 ✓':sl>0?'+'+sl+' ✓':sl+' ✗'}</td>
          <td style="font-size:9px;color:#6b7280">${r.penjelasan||'—'}</td>
        </tr>`;
      }).join('') || `<tr><td colspan="9" style="text-align:center;color:#9ca3af;padding:12px">Belum ada data luar fisik</td></tr>`;

      // ── A. Agregasi perlengkapan dari fisik SMH per jenis ───────────────
      const perlAggFisik = {}; // nama → {ada, tidakAda, units: [{noMesin, model}]}
      filteredHasil.forEach(h => {
        (h.perlengkapan || []).forEach(p => {
          if (!perlAggFisik[p.nama]) perlAggFisik[p.nama] = { ada: 0, tidakAda: 0, units: [] };
          if (p.ada === 1 || p.ada === true) {
            perlAggFisik[p.nama].ada++;
            perlAggFisik[p.nama].units.push({ noMesin: h.noMesin, model: h.kodeModel || '—' });
          } else {
            perlAggFisik[p.nama].tidakAda++;
          }
        });
      });

      // ── B. Tabel per unit (perlengkapan yang diperiksa saat scan) ──────
      const unitTableRows = filteredHasil.map((h, i) => {
        const perlAda  = (h.perlengkapan || []).filter(p => p.ada === 1 || p.ada === true).map(p => p.nama).join(', ') || '—';
        const perlTdk  = (h.perlengkapan || []).filter(p => !(p.ada === 1 || p.ada === true)).map(p => p.nama).join(', ') || '—';
        const semua    = (h.perlengkapan || []).length;
        const adaCount = (h.perlengkapan || []).filter(p => p.ada === 1 || p.ada === true).length;
        const pctBar   = semua > 0 ? Math.round((adaCount / semua) * 100) : 100;
        const statusBadge = h.statusFisik === 'Ready for Sale'
          ? `<span class="badge badge-green">Ready for Sale</span>`
          : `<span class="badge badge-yellow">${h.statusFisik||'—'}</span>`;
        return `<tr>
          <td class="center">${i+1}</td>
          <td style="white-space:nowrap;font-weight:600">${h.noMesin||'—'}</td>
          <td>${h.kodeModel||'—'}</td>
          <td class="center">${fTgl(h.waktu)}</td>
          <td>${h.gudang||'—'}</td>
          <td class="center">${adaCount}/${semua}
            <div style="background:#e5e7eb;border-radius:4px;height:6px;margin-top:3px;width:60px">
              <div style="background:${pctBar===100?'#22c55e':pctBar>=50?'#f59e0b':'#ef4444'};width:${pctBar}%;height:100%;border-radius:4px"></div>
            </div>
          </td>
          <td style="font-size:9px;color:#166534">${perlAda}</td>
          <td style="font-size:9px;color:#dc2626">${perlTdk === '—' ? '' : perlTdk}</td>
          <td>${statusBadge}</td>
        </tr>`;
      }).join('') || `<tr><td colspan="9" style="text-align:center;color:#9ca3af;padding:12px">Belum ada pemeriksaan fisik unit</td></tr>`;

      // ── C. Rekap perlengkapan per jenis dari fisik SMH ──────────────────
      const rekapFisikRows = Object.entries(perlAggFisik)
        .sort((a,b) => a[0].localeCompare(b[0]))
        .map(([nama, agg], i) => {
          const total   = agg.ada + agg.tidakAda;
          const pct     = total > 0 ? Math.round((agg.ada / total) * 100) : 0;
          const stsCls  = pct === 100 ? 'badge-green' : pct >= 50 ? 'badge-yellow' : 'badge-red';
          const stsLbl  = pct === 100 ? 'Lengkap' : pct >= 50 ? 'Sebagian' : 'Banyak Kurang';
          return `<tr>
            <td class="center">${i+1}</td>
            <td><strong>${nama}</strong></td>
            <td class="center" style="color:#166534;font-weight:700">${agg.ada}</td>
            <td class="center" style="color:#dc2626;font-weight:700">${agg.tidakAda}</td>
            <td class="center">${total}</td>
            <td class="center">${pct}%
              <div style="background:#e5e7eb;border-radius:4px;height:6px;margin-top:3px">
                <div style="background:${pct===100?'#22c55e':pct>=50?'#f59e0b':'#ef4444'};width:${pct}%;height:100%;border-radius:4px"></div>
              </div>
            </td>
            <td class="center"><span class="badge ${stsCls}">${stsLbl}</span></td>
          </tr>`;
        }).join('') || `<tr><td colspan="7" style="text-align:center;color:#9ca3af;padding:12px">Tidak ada data perlengkapan dari fisik SMH</td></tr>`;

      // ── D. Tabel perlengkapan luar fisik ────────────────────────────────
      const luarRows = filteredLuar.map((r, i) => {
        const sl    = Number(r.selisih ?? (r.fisik - r.saldo) ?? 0);
        const slCls = sl === 0 ? 'positive' : 'negative';
        return `<tr>
          <td class="center">${i+1}</td>
          <td>${fTgl(r.tgl)}</td>
          <td><strong>${r.jenisPerlengkapan||'—'}</strong></td>
          <td>${r.namaUnitUsaha||r.cabang||'—'}</td>
          <td>${r.namaPemeriksa||r.savedBy||'—'}</td>
          <td class="center">${r.saldo||0}</td>
          <td class="center ${sl>=0?'positive':'negative'}" style="font-weight:700">${r.fisik||0}</td>
          <td class="center"><span class="${slCls}" style="font-weight:700">${sl===0?'0 ✓':sl+' ✗'}</span></td>
          <td style="font-size:9px;color:#6b7280">${r.penjelasan||'—'}</td>
        </tr>`;
      }).join('') || `<tr><td colspan="9" style="text-align:center;color:#9ca3af;padding:12px">Belum ada data perlengkapan luar fisik</td></tr>`;

      // ── E. Rekap Gabungan per jenis ─────────────────────────────────────
      // Kumpulkan semua nama perlengkapan dari kedua sumber
      const allNamaGab = new Set([
        ...Object.keys(perlAggFisik),
        ...filteredLuar.map(r => r.jenisPerlengkapan || '—'),
      ]);
      const rekapGabRows = [...allNamaGab].sort().map((nama, i) => {
        const fisikAgg  = perlAggFisik[nama] || { ada: 0, tidakAda: 0 };
        const luarEntry = filteredLuar.filter(r => (r.jenisPerlengkapan||'') === nama);
        const luarSaldo = luarEntry.reduce((s,r) => s + (parseFloat(r.saldo) || 0), 0);
        const luarFisik = luarEntry.reduce((s,r) => s + (parseFloat(r.fisik ?? r.items?.[0]?.qty) || 0), 0);
        const luarSel   = luarEntry.reduce((s,r) => {
          const f = parseFloat(r.fisik ?? r.items?.[0]?.qty) || 0;
          const sd = parseFloat(r.saldo) || 0;
          return s + (r.selisih ?? (f - sd));
        }, 0);
        const overallOk = fisikAgg.tidakAda === 0 && luarSel === 0;
        const stsCls    = overallOk ? 'badge-green' : 'badge-red';
        return `<tr>
          <td class="center">${i+1}</td>
          <td><strong>${nama}</strong></td>
          <td class="center">${fisikAgg.ada}</td>
          <td class="center" style="color:#dc2626">${fisikAgg.tidakAda}</td>
          <td class="center">${luarSaldo}</td>
          <td class="center">${luarFisik}</td>
          <td class="center ${luarSel===0?'positive':luarSel<0?'negative':''}" style="font-weight:700">${luarSel===0?'0 ✓':luarSel>0?'+'+luarSel+' ✓':luarSel+' ✗'}</td>
          <td class="center"><span class="badge ${stsCls}">${overallOk?'OK ✓':'Perlu Perhatian ⚠'}</span></td>
        </tr>`;
      }).join('') || `<tr><td colspan="8" style="text-align:center;color:#9ca3af;padding:12px">Tidak ada data</td></tr>`;

      const statusBanner = statusOK
        ? `<div style="background:#dcfce7;border:1.5px solid #86efac;border-radius:8px;padding:10px 16px;margin-bottom:14px;display:flex;align-items:center;gap:10px"><span style="font-size:18px">✅</span><span style="font-weight:800;color:#166534;font-size:13px">SEMUA PERLENGKAPAN LENGKAP — Tidak ada kekurangan</span></div>`
        : `<div style="background:#fff1f2;border:1.5px solid #fca5a5;border-radius:8px;padding:10px 16px;margin-bottom:14px;display:flex;align-items:center;gap:10px"><span style="font-size:18px">⚠️</span><span style="font-weight:800;color:#991b1b;font-size:13px">DITEMUKAN KEKURANGAN — ${jenisMinus} jenis perlengkapan minus · ${totalFisikMinus} unit bermasalah · ${totalBelumScan} unit belum diperiksa</span></div>`;

      _printReport(`
        <div class="header">
          <div class="header-left">
            <div class="org">${orgName}</div>
            <div class="subtitle">Laporan Perlengkapan SMH — Data Lengkap (Fisik + Luar Fisik)</div>
          </div>
          <div class="header-right">
            <div style="font-size:14px;font-weight:800;color:#1e3a5f">LAPORAN PERLENGKAPAN SMH</div>
            <div>No SPT: <strong>${noSPT}</strong> &nbsp;|&nbsp; Cabang: <strong>${cabang}</strong></div>
            <div>Area: ${area||'—'} &nbsp;|&nbsp; Auditor: ${auditor} &nbsp;|&nbsp; ${nowFmt}</div>
          </div>
        </div>

        ${statusBanner}

        <!-- Summary -->
        <div class="info-grid" style="grid-template-columns:repeat(6,1fr);margin-bottom:14px">
          <div class="info-item"><label>Total Onhand</label><span style="font-size:14px;color:#1e3a5f">${onhandData.length}</span></div>
          <div class="info-item"><label>Sudah Diperiksa</label><span style="font-size:14px;color:#166534">${filteredHasil.length}</span></div>
          <div class="info-item"><label>Belum Diperiksa</label><span style="font-size:14px;color:${totalBelumScan>0?'#854d0e':'#166534'}">${totalBelumScan}</span></div>
          <div class="info-item"><label>Jenis Perlengkapan</label><span style="font-size:14px">${allNama.length}</span></div>
          <div class="info-item"><label>Perlengkapan Minus</label><span style="font-size:14px;color:${totalFisikMinus>0?'#dc2626':'#166534'};font-weight:800">${totalFisikMinus} ${totalFisikMinus>0?'⚠':'✓'}</span></div>
          <div class="info-item"><label>Luar Fisik Entries</label><span style="font-size:14px">${filteredLuar.length}</span></div>
        </div>

        <!-- ═══ REKAP UTAMA ═══ -->
        <div class="section">
          <div class="section-title" style="background:#1e3a5f;font-size:12px">
            ▣ REKAP LENGKAP — SEMUA PERLENGKAPAN (SUDAH &amp; BELUM DIPERIKSA + MINUS)
          </div>
          <div style="border:1px solid #cbd5e1;border-top:none;overflow:auto">
            <table>
              <thead>
                <tr>
                  <th class="center" rowspan="2">No</th>
                  <th rowspan="2">Jenis Perlengkapan</th>
                  <th class="center" rowspan="2" style="background:#e0f2fe;color:#075985">Ekspektasi<br><span style="font-size:8px;font-weight:400">(dari onhand)</span></th>
                  <th colspan="3" style="background:#dcfce7;color:#166534;text-align:center">FISIK UNIT</th>
                  <th class="center" rowspan="2" style="background:#fef9c3;color:#854d0e">Belum<br>Scan</th>
                  <th colspan="3" style="background:#ede9fe;color:#5b21b6;text-align:center">LUAR FISIK</th>
                  <th class="center" rowspan="2">Status</th>
                </tr>
                <tr>
                  <th class="center" style="background:#dcfce7;color:#166534">Ada ✓</th>
                  <th class="center" style="background:#fee2e2;color:#991b1b">Minus ✗</th>
                  <th class="center" style="background:#fff7ed;color:#9a3412" title="No.Mesin unit yang kurang">Unit Kurang</th>
                  <th class="center" style="background:#ede9fe;color:#5b21b6">Saldo</th>
                  <th class="center" style="background:#ede9fe;color:#5b21b6">Fisik</th>
                  <th class="center" style="background:#ede9fe;color:#5b21b6">Selisih</th>
                </tr>
              </thead>
              <tbody>${rekapRows}</tbody>
            </table>
          </div>
        </div>

        <!-- ═══ DAFTAR KEKURANGAN (MINUS) ═══ -->
        <div class="section">
          <div class="section-title" style="background:#dc2626">⚠ DAFTAR KEKURANGAN PERLENGKAPAN (MINUS) — UNIT YANG TIDAK LENGKAP</div>
          <div style="border:1px solid #fca5a5;border-top:none;overflow:auto">
            <table>
              <thead><tr>
                <th>No.Mesin</th><th>Model</th><th>Gudang</th><th>Tgl Periksa</th>
                <th>Perlengkapan yang Tidak Ada</th><th class="center">Jml Kurang</th>
              </tr></thead>
              <tbody>${minusSection}</tbody>
            </table>
          </div>
        </div>

        <!-- ═══ UNIT BELUM DIPERIKSA ═══ -->
        <div class="section">
          <div class="section-title" style="background:#854d0e">⏳ UNIT ONHAND YANG BELUM DIPERIKSA PERLENGKAPANNYA</div>
          <div style="border:1px solid #fed7aa;border-top:none;overflow:auto">
            <table>
              <thead><tr>
                <th class="center">No</th><th>No.Mesin</th><th>No.Rangka</th>
                <th>Kode Model</th><th>Model</th><th>Gudang</th><th>Unit Usaha</th>
              </tr></thead>
              <tbody>${unscannedRows}</tbody>
            </table>
          </div>
        </div>

        <div style="page-break-before:always"></div>

        <!-- ═══ DETAIL PER UNIT YANG SUDAH DIPERIKSA ═══ -->
        <div class="header" style="margin-top:0">
          <div class="header-left"><div class="org">${orgName}</div><div class="subtitle">Laporan Perlengkapan SMH — Halaman 2</div></div>
          <div class="header-right"><div style="font-size:11px;font-weight:700;color:#1e3a5f">DETAIL PER UNIT &amp; PERLENGKAPAN LUAR FISIK</div><div>Cabang: ${cabang} | ${nowFmt}</div></div>
        </div>
        <div class="section">
          <div class="section-title" style="background:#374151">▤ DETAIL PERLENGKAPAN PER UNIT YANG SUDAH DIPERIKSA</div>
          <div style="border:1px solid #cbd5e1;border-top:none;overflow:auto">
            <table>
              <thead><tr>
                <th class="center">No</th><th>No.Mesin</th><th>Model</th>
                <th>Tgl Periksa</th><th>Gudang</th><th class="center">Ada/Total</th>
                <th>Perlengkapan Ada ✓</th><th>Perlengkapan Kurang ✗</th><th>Status</th>
              </tr></thead>
              <tbody>${unitDetailRows}</tbody>
            </table>
          </div>
        </div>

        <!-- ═══ PERLENGKAPAN LUAR FISIK ═══ -->
        <div class="section">
          <div class="section-title" style="background:#5b21b6">▦ PERLENGKAPAN LUAR FISIK (STOCK GUDANG)</div>
          <div style="border:1px solid #ddd6fe;border-top:none;overflow:auto">
            <table>
              <thead><tr>
                <th class="center">No</th><th>Tanggal</th><th>Jenis Perlengkapan</th>
                <th>Unit Usaha</th><th>Pemeriksa</th>
                <th class="center">Saldo</th><th class="center">Fisik</th>
                <th class="center">Selisih</th><th>Penjelasan</th>
              </tr></thead>
              <tbody>${luarRows2}</tbody>
            </table>
          </div>
        </div>

        <!-- Tanda tangan -->
        <div class="ttd-grid">
          <div class="ttd-box"><div class="role">Kasir / Auditee</div><div class="name">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</div><div style="font-size:9px;margin-top:3px">Nama &amp; Tanda Tangan</div></div>
          <div class="ttd-box"><div class="role">Auditor</div><div class="name">${auditor}</div><div style="font-size:9px;margin-top:3px">Nama &amp; Tanda Tangan</div></div>
          <div class="ttd-box"><div class="role">Mengetahui / Kepala Cabang</div><div class="name">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</div><div style="font-size:9px;margin-top:3px">Nama &amp; Tanda Tangan</div></div>
        </div>
        ${footer}
      `, `Laporan Perlengkapan SMH — ${cabang}`);
    }
  };

  // ── Helper: buka window baru dan print ─────────────────────────────────
  function _printReport(htmlContent, title) {
    const w = window.open('', '_blank', 'width=960,height=800');
    if (!w) { showToast('Popup diblokir browser. Izinkan popup untuk halaman ini.', 'error'); return; }
    w.document.write(`<!DOCTYPE html><html lang="id"><head>
      <meta charset="UTF-8">
      <title>${title}</title>
      <style>${_pdfCss()}</style>
    </head><body>
      <div class="no-print" style="background:#1e3a5f;color:#fff;padding:10px 16px;display:flex;align-items:center;gap:12px;margin-bottom:16px">
        <span style="font-size:14px;font-weight:700">📄 ${title}</span>
        <button onclick="window.print()" style="margin-left:auto;background:#22c55e;color:#fff;border:none;padding:6px 18px;border-radius:6px;cursor:pointer;font-weight:700">🖨️ Print / Simpan PDF</button>
        <button onclick="window.close()" style="background:#6b7280;color:#fff;border:none;padding:6px 14px;border-radius:6px;cursor:pointer">✕ Tutup</button>
      </div>
      ${htmlContent}
    </body></html>`);
    w.document.close();
  }

  function _pdfCss() { return `*{box-sizing:border-box;margin:0;padding:0}body{font-family:'Segoe UI',Arial,sans-serif;font-size:11px;color:#1a1a1a;background:#fff;padding:20px}@page{size:A4 portrait;margin:15mm 12mm}@media print{body{padding:0}.no-print{display:none!important}}h1{font-size:16px;font-weight:800;margin-bottom:2px}h2{font-size:13px;font-weight:700;margin-bottom:6px;color:#1e3a5f}h3{font-size:11px;font-weight:700;margin:8px 0 4px;text-transform:uppercase;letter-spacing:.04em;color:#374151}.header{border-bottom:3px solid #1e3a5f;padding-bottom:10px;margin-bottom:14px;display:flex;justify-content:space-between;align-items:flex-end}.header-left .org{font-size:14px;font-weight:800;color:#1e3a5f}.header-left .subtitle{font-size:10px;color:#6b7280;margin-top:2px}.header-right{text-align:right;font-size:10px;color:#6b7280}.badge{display:inline-block;padding:2px 8px;border-radius:12px;font-size:10px;font-weight:700}.badge-green{background:#dcfce7;color:#166534}.badge-red{background:#fee2e2;color:#991b1b}.badge-blue{background:#dbeafe;color:#1e40af}.badge-yellow{background:#fef9c3;color:#854d0e}.info-grid{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-bottom:12px;background:#f8fafc;border:1px solid #e5e7eb;border-radius:6px;padding:10px}.info-item label{font-size:9px;text-transform:uppercase;letter-spacing:.05em;color:#9ca3af;display:block;margin-bottom:2px}.info-item span{font-weight:600;font-size:11px}table{width:100%;border-collapse:collapse;margin-bottom:10px;font-size:10px}thead tr{background:#1e3a5f;color:#fff}thead th{padding:6px 8px;text-align:left;font-weight:700;font-size:10px}tbody tr:nth-child(even){background:#f8fafc}td,th{padding:5px 8px;border-bottom:1px solid #e5e7eb;vertical-align:top}td.num{text-align:right;font-variant-numeric:tabular-nums}td.center{text-align:center}.section{margin-bottom:16px}.section-title{background:#1e3a5f;color:#fff;padding:5px 10px;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;border-radius:4px 4px 0 0;margin-bottom:0}.section-body{border:1px solid #cbd5e1;border-top:none;border-radius:0 0 4px 4px;padding:10px;margin-bottom:12px}.sum-row{display:flex;justify-content:space-between;padding:3px 0;border-bottom:1px solid #f1f5f9;font-size:10px}.sum-row.bold{font-weight:700;font-size:11px;border-top:2px solid #1e3a5f;padding-top:4px}.sum-row.selisih{background:#f0fdf4;padding:4px 8px;border-radius:4px;font-weight:700}.sum-row.selisih.err{background:#fff1f2}.ttd-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:20px;margin-top:24px}.ttd-box{border-top:1px solid #374151;padding-top:6px;text-align:center;font-size:10px}.ttd-box .role{color:#6b7280;font-size:9px;margin-bottom:40px}.ttd-box .name{font-weight:700;border-bottom:1px solid #374151;padding-bottom:2px}.footer{margin-top:20px;border-top:1px solid #e5e7eb;padding-top:8px;font-size:9px;color:#9ca3af;display:flex;justify-content:space-between}.positive{color:#166534;font-weight:700}.negative{color:#991b1b;font-weight:700}.total-row{background:#eef2ff!important;font-weight:700}`; }

  window._mulaiAudit = function (taskId) {
    if (!confirm('Mulai audit untuk task ini?')) return;
    tasks = loadTasks();
    const idx = tasks.findIndex(t => t.id == taskId);
    if (idx < 0) return;
    if (tasks[idx].status !== 'coo_approved') { showToast('Status task tidak valid untuk memulai audit.', 'error'); return; }
    const t = { ...tasks[idx], status: 'audit_started', auditStartedAt: new Date().toISOString() };
    t.statusLog = addStatusLog(t, 'audit_started', '');
    tasks[idx] = t;
    saveTasks(tasks);
    renderAuditSection();
    updateAuditBadge();
    showToast('Audit dimulai. Menunggu cabang untuk memulai.', 'success');
  };

  window._mulaiCabang = function (taskId) {
    if (!confirm('Mulai pemeriksaan cabang untuk task ini?')) return;
    tasks = loadTasks();
    const idx = tasks.findIndex(t => t.id == taskId);
    if (idx < 0) return;
    if (tasks[idx].status !== 'audit_started') { showToast('Audit belum dimulai oleh auditor.', 'error'); return; }
    const t = { ...tasks[idx], status: 'in_progress', cabangStartedAt: new Date().toISOString() };
    t.statusLog = addStatusLog(t, 'in_progress', '');
    tasks[idx] = t;
    saveTasks(tasks);
    renderAuditSection();
    renderTaskSection();
    updateTaskBadge();
    updateAuditBadge();
    showToast('Pemeriksaan cabang dimulai. Buka menu Audit untuk mulai pemeriksaan.', 'success');
  };

  window._selesaiCabang = function (taskId) {
    if (!confirm('Selesaikan pemeriksaan cabang ini?')) return;
    tasks = loadTasks();
    const idx = tasks.findIndex(t => t.id == taskId);
    if (idx < 0) return;
    const t = { ...tasks[idx], status: 'selesai', selesaiAt: new Date().toISOString() };
    t.statusLog = addStatusLog(t, 'selesai', 'Pemeriksaan cabang selesai');
    tasks[idx] = t;
    saveTasks(tasks);
    _checkPlanComplete(tasks, tasks[idx].planId);
    renderAuditSection();
    renderPlanSection();
    updateAuditBadge();
    showToast('Pemeriksaan cabang selesai.', 'success');
  };

  // Kepala tim auditor menutup audit secara keseluruhan
  window._selesaiAudit = function (taskId) {
    if (!confirm('Tutup dan selesaikan audit ini?\n\nPastikan semua pemeriksaan sudah dilakukan.')) return;
    tasks = loadTasks();
    const idx = tasks.findIndex(t => t.id == taskId);
    if (idx < 0) return;
    const task = tasks[idx];

    // Validate: minimal 1 jenis pemeriksaan apapun harus ada
    const hasilCount = loadSmhData(SMH_HASIL_KEY).filter(h => String(h.auditPlanId) === String(task.planId)).length;
    const kasCount   = loadKasAudit().filter(k => String(k.planId) === String(task.planId)).length;
    const luarCount  = loadSmhData(SMH_LUAR_KEY).filter(l => String(l.auditPlanId) === String(task.planId)).length;
    const hgpCount   = loadHgp(HGP_HASIL_KEY).length + loadHgp(HGP_WO_KEY).length;

    const adaPemeriksaan = hasilCount > 0 || kasCount > 0 || luarCount > 0 || hgpCount > 0;
    if (!adaPemeriksaan) {
      showToast('Belum ada data pemeriksaan. Lakukan minimal 1 jenis pemeriksaan (SMH, Kas, HGP & AHM Oil\'s, atau Perlengkapan Luar Fisik) terlebih dahulu.', 'error', 5000);
      return;
    }

    // Validate: BU Performance wajib diisi sebelum selesai
    const buPerfRec = getBuPerfForPlan(task.planId);
    if (!buPerfRec || !buPerfRec.savedAt) {
      showToast('BU Performance belum diisi. Isi BU Performance terlebih dahulu sebelum menyelesaikan audit.', 'error', 5000);
      return;
    }

    const t = { ...task, status: 'selesai', selesaiAt: new Date().toISOString() };
    t.statusLog = addStatusLog(t, 'selesai', 'Audit ditutup oleh Kepala Tim');
    tasks[idx] = t;
    saveTasks(tasks);
    _checkPlanComplete(tasks, task.planId);
    renderAuditSection();
    renderPlanSection();
    updateTaskBadge();
    updateAuditBadge();
    showToast('Audit berhasil diselesaikan! Laporan dapat dilihat di menu Laporan.', 'success');
  };

  function _checkPlanComplete(taskList, planId) {
    const planTasks = taskList.filter(t => String(t.planId) === String(planId));
    if (!planTasks.length) return;

    // Plan selesai jika:
    // A. Kepala Tim sudah selesai, ATAU
    // B. Semua task yang masuk fase audit (coo_approved+) sudah selesai
    const auditPhase  = ['coo_approved', 'audit_started', 'in_progress', 'selesai'];
    const auditTasks  = planTasks.filter(t => auditPhase.includes(t.status));
    const kepalaSelesai  = planTasks.some(t => t.isKepala && t.status === 'selesai');
    const allAuditSelesai = auditTasks.length > 0 && auditTasks.every(t => t.status === 'selesai');

    if (kepalaSelesai || allAuditSelesai) {
      plans = loadPlans();
      const pi = plans.findIndex(p => String(p.id) === String(planId));
      if (pi >= 0 && plans[pi].status !== 'selesai') {
        plans[pi].status    = 'selesai';
        plans[pi].selesaiAt = new Date().toISOString();
        savePlans(plans);
      }
    }
  }

  // ── Sinkronisasi status semua plan berdasarkan task (dipanggil saat render) ──
  function _syncAllPlanStatuses() {
    const allTasks = loadTasks();
    plans          = loadPlans();
    let changed    = false;
    const auditPhase = ['coo_approved', 'audit_started', 'in_progress', 'selesai'];

    plans.forEach((plan, pi) => {
      const pt          = allTasks.filter(t => String(t.planId) === String(plan.id));
      const auditTasks  = pt.filter(t => auditPhase.includes(t.status));
      const kepalaSelesai  = pt.some(t => t.isKepala && t.status === 'selesai');
      const allAuditDone   = auditTasks.length > 0 && auditTasks.every(t => t.status === 'selesai');

      if ((kepalaSelesai || allAuditDone) && plan.status !== 'selesai') {
        plans[pi].status    = 'selesai';
        plans[pi].selesaiAt = plans[pi].selesaiAt || new Date().toISOString();
        changed = true;
      }

      // Rollback: plan kembali aktif jika ada task audit yang masih berjalan
      if (plan.status === 'selesai' && auditTasks.some(t => t.status !== 'selesai')) {
        const kepalaAktif = pt.some(t => t.isKepala && t.status !== 'selesai' && auditPhase.includes(t.status));
        if (kepalaAktif) {
          plans[pi].status = 'aktif';
          changed = true;
        }
      }
    });

    if (changed) savePlans(plans);
    return plans;
  }

  /* ── Wire up Luar Fisik Modal ── */
  // Pasang listener ke SEMUA elemen btnSimpanLuar (standalone + modal keduanya punya ID ini)
  document.querySelectorAll('[id="btnSimpanLuar"]').forEach(btn =>
    btn.addEventListener('click', saveLuarFisik)
  );
  document.getElementById('luarFisikModal')?.addEventListener('click', function(e) {
    if (e.target === this) window._closeLuarFisikModal();
  });
  document.getElementById('btnHapusLuar')?.addEventListener('click', () => {
    if (!confirm('Hapus semua riwayat perlengkapan luar fisik?')) return;
    smhLuarFisik = [];
    saveSmhData(SMH_LUAR_KEY, smhLuarFisik);
    renderLuarFisik();
    showToast('Riwayat luar fisik dihapus.', 'info');
  });

  /* ── Wire up Plan & Task ── */
  document.getElementById('btnCreatePlan')?.addEventListener('click', () => window._openPlanModal(null));
  document.getElementById('btnSavePlan')?.addEventListener('click', savePlan);
  document.getElementById('btnSubmitTask')?.addEventListener('click', submitTask);
  document.getElementById('btnApproveTask')?.addEventListener('click', () => doApproveTask(true));
  document.getElementById('btnRejectTask')?.addEventListener('click', () => doApproveTask(false));

  // Close modals on overlay click
  ['planModal', 'taskModal', 'approveModal', 'kasAuditModal'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.addEventListener('click', function (e) {
      if (e.target === this) {
        if (id === 'planModal')     window._closePlanModal();
        if (id === 'taskModal')     window._closeTaskModal();
        if (id === 'approveModal')  window._closeApproveModal();
        if (id === 'kasAuditModal') window._closeKasAuditModal();
      }
    });
  });

